COPLAS_PIEZA(2, [["carrizo_salta-nc0379-10",3,"Así marchan las mujeres,\nSiempre con mal pensamiento,\nTrenzan cuentos a cadenas\nHasta salir con su intento.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"eo",94,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0379-11",3,"Así, vean caballeros,\nComo hay verano e invierno,\nEn la redondez del mundo\nHay purgatorio e infierno.",3,1,0,35,"E DICEN QUE NO HAY INFIERNO",0,4,"eo",225,0,-1,0,268,268,"C-379","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0380-01",3,"No hay amigo verdadero\nEn las tragedias de amor.\nEl que no la hace la intenta,\nEn llegando la ocasión.",3,1,0,35,"NO HAY AMIGO VERDADERO",0,4,"o",-1,0,-1,0,268,268,"C-380","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0380-02",3,"¿Quién había de pensar\nDespués de ser tan querido,\nQue me había de ver perdido\nPor un amigo traidor?\nMe mostraba tanto amor\nEse villano severo,\nQue cada vez que recuerdo\nDonde lo llego a mirar,\nDigo con rabia y pesar:\n—No hay amigo verdadero.",3,1,0,35,"NO HAY AMIGO VERDADERO",18,10,"eo",-1,0,-1,0,269,269,"C-380","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0380-03",3,"¡Mucho te quiero y te estimo!\nMuchas veces me decía,\nY de este modo vivía\nMuy confiado de mi amigo.\nPero ya me había vendido\nHaciéndome una traición.\nLuego me pidió perdón\nCon descaro y agudeza,\n¿Cómo puede haber firmeza\nEn las tragedias de amor?",3,1,0,35,"NO HAY AMIGO VERDADERO",18,10,"o",-1,0,-1,0,269,269,"C-380","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0380-04",3,"Como la falsa mujer\nMuestra halagos al querido,\nLo mismo son los amigos,\nCuando lo quieren vender.\nTodo puede suceder,\nEs preciso que se advierta\nPorque si uno no anda alerta,\nY su atención se demora,\nYa los amigos de ahora\nEl que no la hace la intenta.",3,1,0,35,"NO HAY AMIGO VERDADERO",18,10,"ea",-1,0,-1,0,269,269,"C-380","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0380-05",3,"Es pues una pasión loca\nEl querer ser amigable,\nNo siendo corresponsable\nA la pasión que sofoca.\nMás bien callemos la boca\nEn esta misma ocasión,\n¿Para qué es tener pasión\nEn este mundo inportuno?\nNo reflexiona ninguno\nEn llegando la ocasión.",3,1,0,35,"NO HAY AMIGO VERDADERO",18,10,"o",31,0,-1,0,269,269,"C-380","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0381-01",3,"Fué guiada por la inclemencia\nMi triste venida al mundo,\nMartiriza mi existencia\nUn vacío y dolor profundo.",3,1,0,35,"",3,4,"uo",179,0,-1,0,269,269,"C-381","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0381-02",3,"Aún los padres desconocen,\nAl que nació desgraciado,\nNegándole su cariño,\nLo separan de su lado.",3,1,0,35,"",0,4,"ao",14,0,-1,0,269,269,"C-381","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0381-03",3,"Lo miran como un extraño,\nEntre medio sus hermanos.\nDe todos desconocido,\nSufriendo mil desengaños.",3,1,0,35,"",0,4,"ao",-1,0,-1,0,269,269,"C-381","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0381-04",3,"No es bastante la honradez\nNi el vivir sólo callando,\nAl que nació sin fortuna\nTodos lo están señalando.",3,1,0,35,"",0,4,"ao",33,0,-1,0,269,269,"C-381","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0381-a-01",3,"No hay mayor pena en la vida,\nComo nacer sin fortuna,\nTiene su sangre manchada\nY obscurecida su cuna.",3,1,0,35,"NO HAY MAYOR PENA EN LA VIDA,",0,4,"ua",56,0,-1,0,269,269,"C-381-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0381-a-02",3,"Lo miran como un extraño\nEn medio de sus hermanos,\nDe todos desconocidos\nSufriendo mil desengaños.",3,1,0,35,"NO HAY MAYOR PENA EN LA VIDA,",0,4,"ao",-1,0,-1,0,269,269,"C-381-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0381-a-03",3,"No es bastante la honradez,\nNi vivir sólo callando,\nQue el que no tiene fortuna,\nTodo le están señalando.",3,1,0,35,"NO HAY MAYOR PENA EN LA VIDA,",0,4,"ao",33,0,-1,0,269,269,"C-381-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0381-a-04",3,"Pueda que cantando triste\nAlgún día cante alegre,\nVuelvan mis penas en gloria\nSi mi fortuna no muere.",3,1,0,35,"NO HAY MAYOR PENA EN LA VIDA,",0,4,"ee",-1,0,-1,0,269,269,"C-381-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-01",3,"No hay desgracia en la vida\nCmo el nacer sin fortuna,\nTengo mi sangre manchada\nY obscurecida mi cuna.",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"ua",56,0,-1,0,269,269,"C-382","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0382-02",3,"¡No hay mayor pena que amar\nSin esperar recompensa,\nY tener que agradecer\nUn mal pago por fineza!",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"ea",-1,0,-1,0,269,269,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-03",3,"Triste, penoso y confuso\nMe consuelo con llorar;\nRepitiendo entre mis ayes:\nNo hay mayor pena que amar",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"a",21,0,-1,0,270,270,"C-382","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0382-04",3,"Aquel que fino idolatra\nY se rinde a una belleza,\nVive siempre atribulado,\nSin esperar recompensa.",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"ea",-1,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-05",3,"Grande locura es por cierto\nNo ser querido y querer\nVivir mal correspondido\nY tener que agradecer",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"e",20,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-06",3,"Es el mayor desatino\nEl amar con tanta fuerza,\nPara después recibir\nUn mal pago por fineza.",3,1,0,35,"NO HAY DESGRACIA EN LA VIDA ¡NO HAY MAYOR PENA QUE AMAR!",0,4,"ea",-1,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-07",3,"¡Pajarillo buen amigo!\n¿Qué consejo me darís\nPara volver a los brazos\nDe una prenda que perdí?",3,1,0,35,"PAJARILLO BUEN AMIGO",0,4,"i",-1,0,-1,0,270,270,"C-382","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0382-08",3,"—El consejo te daré\nPero me has de hacer saber\nSi la has dejao por vileza\nO ha sido a más no poder.",3,1,0,35,"PAJARILLO BUEN AMIGO",0,4,"e",20,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-09",3,"—Ella anduvo bien conmigo\nSe cambió de parecer\nY se trocó en otros brazos;\nLuego, por vileza fué.",3,1,0,35,"PAJARILLO BUEN AMIGO",0,4,"e",-1,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0382-10",3,"—Déjala que ella ha i volver\nAl error que ha cometido,\nEntonces le dirás vos:\n—Quítate que yo no hi sido.",3,1,0,35,"PAJARILLO BUEN AMIGO",0,4,"io",101,0,-1,0,270,270,"C-382","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0384-01",3,"¡Qué equivocación será\nPara aquel que llegue a creer,\nQue ausente lo han de querer\nY jamás lo han de olvidar!\nEsto me pongo a pensar",3,1,0,35,"I QUE EQUIVOCACIÓN SERA!",7,5,"a",21,0,-1,0,270,270,"C-384","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0384-02",3,"En mis horas de amargura.\nConsulto mi desventura\nY pensando, he comprendido,\nPara el ausente hay olvido,\nPara el muerto sepultura.",3,1,0,35,"I QUE EQUIVOCACIÓN SERA!",7,5,"ua",17,0,-1,0,270,270,"C-384","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0384-03",3,"Hay amores muy constantes\nMientras uno esté presente,\nPero en cuanto se halla ausente\nPronto tiene reemplazante.\nEligiendo nuevo amante\nLo ponen en su lugar,\nY no lo tomen a mal\nLo que mi lengua refiere,\nEntierran al que se muere\nY olvidan al que se va.",3,1,0,35,"I QUE EQUIVOCACIÓN SERA!",18,10,"a",-1,0,-1,0,270,270,"C-384","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0384-04",3,"Yo tengo por experiencia\nQue tratándose de amantes,\nNo existe el amor constante\nSi está por medio la ausencia.\nEs del amor la potencia\nEl no hallarse dividido,\nSi uno tiene un ser querido\nLa presencia es muy forzosa,\nComo pal muerto la fosa,\nComo pal ausente olvido.",3,1,0,35,"I QUE EQUIVOCACIÓN SERA!",18,10,"io",101,0,-1,0,270,270,"C-384","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0385-01",3,"Que para los hombres se hizo\nEl andar en malos pasos,\nComo la mujer sea buena,\nVengan y vayan trabajos.",3,1,0,35,"QITF, PARA LOS HOMBRES SE HIZO",0,4,"ao",-1,0,-1,0,270,270,"C-385","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0385-02",3,"Cárcel, grillos y cadenas,\nSon prisiones rigurosas,\nVengan cordeles y esposas,\nAnsias, angustias y penas,\nPresidio en tierras ajenas,\nQue siempre lo hallo preciso,\nPara el hombre que es remiso\nEn amar a una mujer,\nEl suplicio ha de tener\nQue para los hombres se hizo.",3,1,0,35,"QITF, PARA LOS HOMBRES SE HIZO",18,10,"io",95,0,-1,0,270,270,"C-385","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0385-03",3,"Hambre, desnudez y males,\nAnsias, ayes y tormentos,\nDolor y desabrimientos,\nJueces, ministros, fiscales,\nSon para los hombres leales\nQue en amor son bien escasos.\nHeridas, fuertes balazos,\nY otros golpes que se infiere,\nHa de sufrir el que quiere\nEl andar en malos pasos.",3,1,0,35,"QITF, PARA LOS HOMBRES SE HIZO",18,10,"ao",375,0,-1,0,270,271,"C-385","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0385-04",3,"Ni potro, ni mordazeada,\nNi el verdugo más tirano,\nNi el cepo más inhumano,\nPara los que aman es nada,\nLa condena sentenciada,\nQue puede causarle pena.\nMas, cuando el amor ordena\nHasta la vida rendir,\nTodo esto se ha de sufrir\nComo la mujer sea buena.",3,1,0,35,"QITF, PARA LOS HOMBRES SE HIZO",18,10,"ea",59,0,-1,0,271,271,"C-385","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0385-05",3,"Ni la lanzada enemiga,\nNi la espada del rigor,\nNi la saña ni el rencor\nDe la guerr.:. fatiga,\nAl hombre no le domina,\nNi causan altos y bajos.\nSólo un dolor que contrajo\nDe una pasión como amante,\nMas si es la mujer constante\nVengan y vayan trabajos.",3,1,0,35,"QITF, PARA LOS HOMBRES SE HIZO",18,10,"ao",-1,0,-1,0,271,271,"C-385","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0386-01",3,"Quien se casa hace un error,\nLo que en soltero no advierte,\nAllí después que se casa,\nVé que el matrimonio es fuerte.",3,1,0,35,"QUIEN SE CASA HACE UN ERROR",0,4,"ee",134,0,-1,0,271,271,"C-386","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0386-02",3,"No hay cosa más desabrida\nQue el tener mala mujer,\nTan sólo para tener\nPurgatorio en esta vida.\nEs tanto, ni a la comida\nNo le halla ningún sabor,\nSoltero vivir mejor\nEl hombre más descansado,\n¡Ay, qué fiero es ser casado,\nQuién se casa hace un error!",3,1,0,35,"QUIEN SE CASA HACE UN ERROR",18,10,"o",72,0,-1,0,271,271,"C-386","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0386-03",3,"La mujer es una esposa,\nY le dieron ese nombre,\nPorque es ella para el hombre,\nLa prisión más rigurosa.\nSe vé que no es otra cosa\nQue prisión hasta la muerte,\nHasta que quiera la suerte,\nDe que esta prisión se acabe,\nEsto el hombre no precave,\nLo que en soltero no advierte.",3,1,0,35,"QUIEN SE CASA HACE UN ERROR",18,10,"ee",134,0,-1,0,271,271,"C-386","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0386-04",3,"La mujer sin reverencia\nPara que el hombre se avenga\nEs preciso de que tenga,\nDe los cielos la paciencia.\nElla habla con insolencia,\nQue merece una mordaza;\nLa mujer parece mansa\nAntes de su matrimonio,\nPero se vuelve el demonio\nAllá después que se casa.",3,1,0,35,"QUIEN SE CASA HACE UN ERROR",18,10,"aa",-1,0,-1,0,271,271,"C-386","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0386-05",3,"La mujer que es habladora\nHace dar mucha fatiga,\nCierto es que ella no castiga\nPero es atormentadora.\nDe paciencia moledora\nEn donde hay más mucha gente.\nEl hombre por ser prudente\nSufre insultos muy terribles,\nEntonces se ve visible\nLo que el matrimonio es fuerte.",3,1,0,35,"QUIEN SE CASA HACE UN ERROR",18,10,"ee",-1,0,-1,0,271,271,"C-386","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0387-01",3,"¿Quién vence a los imposibles?\n¿Quién avasalla al amor?\n¿Quién rompe dificultades?\nLa plata, después de Dios.",3,1,0,35,"¿QUIEN VENCE A LOS IMPOSIBLES?",0,4,"o",-1,0,-1,0,271,271,"C-387","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0387-02",3,"Si el interés no reinara\nMás cuerdo el hombre estuviera,\nNinguno de ellos perdiera:\nHonra, hacienda, vida y alma;\nSólo el que tiene se salva,\nDel modo más ostensible.\nCual el genio más terrible,\nCon la plata se hace humano,\nEs la plata del cristiano\nQuien vence los imposibles.",3,1,0,35,"¿QUIEN VENCE A LOS IMPOSIBLES?",18,10,"ie",-1,0,-1,0,271,271,"C-387","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0388-01",3,"Quiero dejar mi pasión,\nQuiero mudar de costumbre,\nQuiero subir a la cumbre\nDe una sabia reflexión.",3,1,0,35,"QUIERO DEJAR MI PASIÓN",11,4,"o",31,0,-1,0,272,272,"C-388","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0388-02",3,"Un golpe recio me avisa\nDe la mano Soberana,\nQue debo morir mañana,\nY esto más me atemoriza.\nEl dejarte me precisa\nPorque es mi única intención,\nComo temo en la ocasión,\nDe Dios un juicio severo,\nComo conozco que muero,\nQuiero dejar mi pasión.",3,1,0,35,"QUIERO DEJAR MI PASIÓN",18,10,"o",31,0,-1,0,272,272,"C-388","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0388-03",3,"Tan ciegamente he vivido\nEn mi pasión abrazado,\nQue sin temor ni cuidado,\nAún más que a Dios te he querido.\nPero ahora yo te pido\nPerdón y que Dios te ayude.\nPara que no me perturbe\nEl enemigo guerrero,\nDejar todo vicio quiero,\nQuiero mudar mi costumbre.",3,1,0,35,"QUIERO DEJAR MI PASIÓN",18,10,"ue",-1,0,-1,0,272,272,"C-388","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0388-04",3,"No pienses que es despreciarte\nPor otro bien temporal,\nNi menos tengas a mal\nPues por Dios quiero dejarte.\nPon tu amor en otra parte,\nSi quieres que yo me encumbre.\nQuiero mi Dios, ya que tuve\nLa gloria de arrepertirme,\nAntes que haya de morirme,\nQuiero subir a la sumbre.",3,1,0,35,"QUIERO DEJAR MI PASIÓN",18,10,"ue",-1,0,-1,0,272,272,"C-388","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0388-05",3,"Sabes que una alma nacida\nY en todo vicio encerrada,\nAntes que fuera juzgada,\nDebe de variar de vida,\nPara que sea parecida\nA la del gran Salomón.\nQuiero dejar la ocasión\nPorque el más justo resbala,\nQuiero volar por la escala,\nDe una sabia reflexión.",3,1,0,35,"QUIERO DEJAR MI PASIÓN",18,10,"o",31,0,-1,0,272,272,"C-388","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0389-01",3,"Si un pobre llega a una casa,\nPor conocencia que tenga,\nLuego dicen los vecinos:\n—Ese de vicio no llega.",3,1,0,35,"SI UN POBRE LLEGA A UNA CASA",0,4,"ea",-1,0,-1,0,272,272,"C-389","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0389-02",3,"Si llega a desensillar\nPorque lo haigan invitado,\nLuego dicen los vecinos:\n—Ya viven como casados.",3,1,0,35,"SI UN POBRE LLEGA A UNA CASA",0,4,"ao",-1,0,-1,0,272,272,"C-389","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0389-03",3,"Y si le ven prendas buenas,\nQue la plata le costó,\nLuego dicen los vecinos:\n—Que la querida le dió.",3,1,0,35,"SI UN POBRE LLEGA A UNA CASA",0,4,"o",2,0,-1,0,272,272,"C-389","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0389-04",3,"¡Caramba con los vecinos,\nNo pueden ver y callar!\n¿No piensan ellos jamás\nQué igual les puede pasar?",3,1,0,35,"SI UN POBRE LLEGA A UNA CASA",0,4,"a",-1,0,-1,0,273,273,"C-389","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-01",3,"Todo el que sepa de amor\nSírvase de dar sentencia,\nEn esta desavenencia\nDe tres damas en cuestión;\nLas tres con tanta razón\nAlegan constantemente,\n¿Cuál será más delincuente,\nO mancha más su honradez,\nCuando alguna de las tres\nDiera el sí, a su pretendiente?",3,1,0,35,"TODO EL QUE SEPA DE AMOR",18,10,"ee",15,0,-1,0,273,273,"C-390","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-02",3,"La soltera en comparada\nCon una flor, que al nacer\nNos envía con placer\nUna aureola perfumada,\nMas si del tallo es cortada\nAquella flor se marchita,\nY su fragancia exquisita,\nHa perdido su valor,\nNo dejará de ser flor,\nPero ya se desmerita.",3,1,0,35,"TODO EL QUE SEPA DE AMOR",18,10,"ia",50,0,-1,0,273,273,"C-390","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-03",3,"La viuda es un general\nQue a un soldado delincuente,\nCastiga celosamente,\nPara hacerse respetar.\nY si no da ese ejemplar\nCometerá una ignorancia;\nY ha de llegar circunstancia,\nQue le falten al respeto;\nY para evitar todo esto,\nEjemplo quiere la crianza.",3,1,0,35,"TODO EL QUE SEPA DE AMOR",18,10,"aa",-1,0,-1,0,273,273,"C-390","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-04",3,"Comparada es la casada\nCon un fiel gobernador,\nQue mantiene con honor,\nLa ciudad tranquilizada.\nMas si su firma es robada,\nSerá su pueblo perdido,\nDel enemigo invadido,\nY por esto es que se entiende,\nCuando a sabiendas ofende,\nLa mujer a su marido.",3,1,0,35,"TODO EL QUE SEPA DE AMOR",18,10,"io",101,0,-1,0,273,273,"C-390","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-05",3,"La soltera es un pimpollo,\nLa viuda es un general,\nLa casada es un gobierno,\nPor su estado natural.\nPara poder comparar\nHago esta suposición\nQue este pimpollo es botón,\nLlama al riego que la ampare,\nEl jefe, a sus militares,\nEl gobierno a su nación.",3,1,0,35,"TODO EL QUE SEPA DE AMOR",18,10,"o",31,0,-1,0,273,273,"C-390","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-a-01",3,"Los que de amores supieran\nSírvanse dar sentencia\nDe una gran desavenencia\nDe tres damas y un quimera.\nCasada, viuda y soltera,\nAlegan confusamente:\n¿Cuál será más delincuente\nO mancha más sin revés,\nCuando a alguna de las tres\nLa vence algún pretendiente?",3,1,0,35,"LOS QUE DE AMORES SUPIERAN",18,10,"ee",15,0,-1,0,273,273,"C-390-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-a-02",3,"La soltera dijo: soy\nQuien no deba deshonrarme,\nPues pierdo a Dios y a mis padres\nSi cometo tal error;\nPerdiendo todo mi honor\nY mi belleza y niñez,\nCuando mis padres tal vez\nMe amarán más que a un tesoro,\nY si pierdo este decoro\nNada merezco después.",3,1,0,35,"LOS QUE DE AMORES SUPIERAN",18,10,"e",218,0,-1,0,273,273,"C-390-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-a-04",3,"La casada dijo: yo,\nYo, por mi estado formal\nSoy más fina que un cristal,\nLa paja más delicada,\nY debo ser comparada,",3,1,0,35,"LOS QUE DE AMORES SUPIERAN",7,5,"aa",49,0,-1,0,273,273,"C-390-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0390-a-05",3,"Con el más fino reloj;\nPor lo tanto debo yo\nGuardar con delicadeza,\nLos preceptos de la iglesia\nQue el Supremo me ordenó.",3,1,0,35,"LOS QUE DE AMORES SUPIERAN",7,5,"o",2,0,-1,0,274,274,"C-390-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0391-01",3,"Triste es la vida del pobre\nQue vive de su trabajo,\nSiempre luchando de abajo,\nSin poder juntar un cobre.\nAunque la razón le sobre\nEl rico siempre la gana,\nEn vano el pobre se afana,\nA su lao no está la ley,\nY va siguiendo cual buey\nAl rigor de la picana.",3,1,0,35,"TRISTE ES LA VIDA DEL POBRE",18,10,"aa",4,0,-1,0,274,274,"C-391","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-01",3,"Un amigo le pregunta\nA otro amigo que tenía:\nQue es la vida del casado,\nQue casarse pretendía.",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"ia",0,0,-1,0,274,274,"C-392","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-02",3,"Y el amigo le responde:\n—No hagas tal barbaridad,\nAprovecha tu existencia,\nGoza de tu libertad.",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"a",16,0,-1,0,274,274,"C-392","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-03",3,"\"Gozarás del primer día,\nDel segundo y del tercero,\nY el cuarto ya llorarás\nLa vida de los solteros.",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"eo",-1,0,-1,0,274,274,"C-392","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-04",3,"\"La vida de los solteros,\nTodo es cantar y bailar,\nLa de los pobres casados,\nTodo es sufrir y llorar.",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"a",21,0,-1,0,274,274,"C-392","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0392-05",3,"\"Esos grillos que te pongas\nY esa cadena tan fuerte,\nNo la has de poder romper,\nSolamente con la muerte.",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"ee",134,0,-1,0,274,274,"C-392","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-06",3,"\"Y cuando te halles rodeado\nDe más hijos que el demonio,\nEntonces sabrás lo que es\nEl peso del matrimonio\".",3,1,0,35,"UN AMIGO LE PREGUNTA",0,4,"oo",169,0,-1,0,274,274,"C-392","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-01",3,"Un amigo preguntó\nA otro amigo que tenía:\nCuál es la vida el casado,\nQue casarse pretendía.",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"ia",0,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-02",3,"\"Cásese mi buen amigo,\nQuizá se case con suerte\nDespués no venga llorando\nPidiéndole a Dios la muerte.",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"ee",134,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-03",3,"Y le responde otro amigo,\nQue era amigo más legal:\nNo se case por mi gusto,\nGoce de su libertad.",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"a",-1,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-04",3,"\"Gozarás el primer día,\nEl segundo y el tercero,\nEn el cuarto llorarás\nLa vida de los solteros.",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"eo",-1,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-05",3,"\"La vida de los solteros\nTodo es cantar y bailar,\nY la de un triste casado\nLa de sufrir y llorar.",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"a",21,0,-1,0,274,274,"C-392-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0392-a-06",3,"\"Disfrute un poco la vida,\nNo se case tan temprano,\nQue la buena mujer es,\nComo helado de verano\".",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"ao",81,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0392-a-07",3,"Según la ley de Cupido\nNadie se debe casar,\nSi al bien casado le pesa,\n¡Qué será al que casa mal!",3,1,0,35,"UN AMIGO PREGUNTO",0,4,"a",-1,0,-1,0,274,274,"C-392-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0394-01",3,"Un domingo de mañana\nDe penas no me podía,\nAl ver que se me casaba\nLa prenda que yo quería.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"ia",0,0,-1,0,275,275,"C-394","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0394-02",3,"Ahora que te has casao,\nEs bueno servir a Dios,\nQue esto no es para un día\nNi pa una semana o dos.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"o",87,0,-1,0,275,275,"C-394","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0394-03",3,"Esos grillos que te has puesto,\nPor tu propia voluntad,\nEsos son los que te quitan\nEl gusto y la libertad.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"a",16,0,-1,0,275,275,"C-394","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0394-04",3,"Esos grillos que te has puesto,\nEsa cadena tan fuerte,\nVos la has de poder cortar\nSolamente con la muerte.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"ee",134,0,-1,0,275,275,"C-394","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0394-05",3,"Cuando te veas rodeada\nCon más hijos que el demonio,\nEmpezarás a sentir\nEl peso del matrimonio.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"oo",169,0,-1,0,275,275,"C-394","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0394-06",3,"Las mujeres son muy buenas\nAntes de su matrimonio,\nLuego después que se casan\nSe vuelven como el demonio.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"oo",169,0,-1,0,275,275,"C-394","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0394-07",3,"Dijo un pajarillo amante:\n—Nadie se debe casar,\nSi al buen casado le pesa\n¿Qué será al que casa mal?",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"a",-1,0,-1,0,275,275,"C-394","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0394-08",3,"De otro barrio me hi venido\nSólito por mi camino,\nSólo por venir a ver\nLas bodas de tu destino.",3,1,0,35,"UN DOMINGO DE MAÑANA",0,4,"io",199,0,-1,0,275,275,"C-394","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0394-09",3,"Cuando ya te veas rodeada\nDe tus hijos el demonio,\nTe empezará hacer sentir\nLas penas del matrimonio.",3,1,0,35,"UN DOMINGO DE MAÑANA",3,4,"oo",169,0,-1,0,275,275,"C-394","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0396-01",3,"Un sacramento de Dios\nAquí voy a publicar,\nNo se verán arruinados\nEn sabiéndose mariar.",3,1,0,35,"UN SACRAMENTO DE DIOS",0,4,"a",21,0,-1,0,275,275,"C-396","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0396-02",3,"El séptimo, matrimonio.\nReza la iglesia romana,\nQue a toda mujer casada\nMucho la tienta el demonio.\nNuestro padre San Antonio\nCon San José están los dos\nCuantas horas dá un reloj,\nPidiendo sean perdonados,\nAquellos que han abrazado\nUn sacramento de Dios.",3,1,0,35,"UN SACRAMENTO DE DIOS",18,10,"o",-1,0,-1,0,276,276,"C-396","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0396-03",3,"La mujer será obediente,\nPara servir a su esposo,\nAsí vivirán gustosos,\nPara que no hable la gente.\nSi la mujer algo siente\nA solas le ha de decir,\nAsí se ha de corregir,\nA solas se ha de enmendar.\nLo que le toca al marido\nAquí voy a publicar.",3,1,0,35,"UN SACRAMENTO DE DIOS",18,10,"a",21,0,-1,0,276,276,"C-396","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0396-04",3,"El hombre por lo primero\nSe ha i poner a trabajar,\nO ha i ver qué giro ha i tomar\nPa sostener la mujer.\nY si hijos llega a tener\nEl pan redime al cristiano,\nEl chicote en una mano\nEn lo malo darles juicio,\nQuitándoles todo vicio\nNo se verán arruinados.",3,1,0,35,"UN SACRAMENTO DE DIOS",18,10,"ao",-1,0,-1,0,276,276,"C-396","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0396-05",3,"No se celen sn saber,\nNo se quieran maltratar,\nPorque para asegurar\nPrimero se espera el ver.\nSiempre es bueno reprender\nPero no es bueno matar,\nTodo se debe aclarar\nTambién se debe advertir,\nSepa el hombre que ha i morir\nSepa cómo se ha i mariar.",3,1,0,35,"UN SACRAMENTO DE DIOS",18,10,"a",21,0,-1,0,276,276,"C-396","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0397-01",3,"Un triste joven habló\nEn el trono de Cupido,\nDonde disputando estaba\nLa ausencia con el olvido.",3,1,0,35,"UN TRISTE JOVEN HABLO",0,4,"io",101,0,-1,0,276,276,"C-397","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0397-02",3,"Hizo Cupido una junta,\nDe todos sus allegados,\nY en un lugar señalado\nSe pusieron en consulta.\nAl más sabio le pregunta\nSobre el asunto de amor,\nQue si cual sería mejor\nSi olvidar o ser constante,\nEntre todos los amantes,\nUn triste joven habló.",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"o",-1,0,-1,0,276,276,"C-397","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0397-03",3,"Dijo el joven: considero\nQue todo amor incesante\nSiempre debe ser constante\nO si no, no es verdadero.\nY por lo tanto yo infiero\nQue todo amor desunido\nPuede darse por perdido;\nPor más que tenga razón,\nNo ha de hallar apelación\nEn el trono de Cupido.",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"io",101,0,-1,0,276,276,"C-397","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0397-04",3,"Sale el pérfido Desdén\nA cubrir la ingratitud,\nY dijo con prontitud:\nYo os daré a conocer,\nDe que nunca puede ser\nUn amor cosa forzada.\n\"Todo aquél que se ausentara\nNunca espere el ser querido\",\nConsejo que dió Cupido,\nDonde disputando estaban.",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"aa",-1,0,-1,0,276,276,"C-397","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0397-05",3,"Se quedan todos callados\nVen de que esto era razón,\nPara mayor precaución,\nDijo Cupido enfadado:\n\"Todo amor que es bien pagado,\nNunca es bien correspondido,\nEl que quiera ser querido,\nNunca se debe ausentar,\nPorque disputando están\nLa ausencia con el olvido\".",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"io",101,0,-1,0,276,276,"C-397","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0397-a-01",3,"Un triste joven habló\nEn el trono de Cupido,\nDonde disputando estaban\nLa ausencia con el olvido.",3,1,0,35,"UN TRISTE JOVEN HABLO",0,4,"io",101,0,-1,0,276,276,"C-397-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0397-a-02",3,"Hizo Cupido una junta\nDe todos sus allegados,\nY en un lugar señalado,\nSe pusieron en consulta.\nY al más sabio le pregunta\nDe los asuntos de amor,\nDiga. ¿qué será mejor\nOlvidar o ser constante?\nEntre medio los amantes,\nUn triste joven habló.",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"o",-1,0,-1,0,277,277,"C-397-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0397-a-04",3,"Salió el perdido Desdén\nA cubrir su ingratitud,\nY dijo con prontitud:\n—Yo los haré conocer\nCómo nunca puede ser\nUn amor caso forzado.\n\"Todo aquél que se ha ausentado\nNunca espere ser querido\",\nConsejo que dió Cupido\nDonde disputando estaba.",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"aa",-1,0,-1,0,277,277,"C-397-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0397-a-05",3,"Se quedan todos callados\nAl ver que esto era razón,\nCon la mayor precaución\nDijo Cupido enfadado:\n\"Que todo amor bien pagado\nNunca es bien correspondido,\nEl que quiera ser querido\nNunca se debe ausentar,\nPorque siempre suele andar\nLa ausencia con el olvido\".",3,1,0,35,"UN TRISTE JOVEN HABLO",18,10,"io",101,0,-1,0,277,277,"C-397-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0398-01",3,"El mundo está diferente,\nNo está como se formó,\nPrincipal en las vivientes\nSegún lo voy viendo yo.\nNo hay hermanos, no hay parientes\nNi amigos en la ocasión.\nSi es pobre con más razón,\nLo miran como a un extraño,\nMiren que este es un engaño,\nHoy somos, mañana no.",3,1,0,35,"",18,10,"o",2,0,-1,0,277,277,"C-398","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0398-02",3,"Hoy en el día el que tiene,\nDonde quiera es bien mirado,\nEl que es pobre es desgraciado,\nY en esta razón me fundo,\nQue en las vueltas que da el mundo\nNadie se debe fijar.",3,1,0,35,"",9,6,"a",-1,0,-1,0,277,277,"C-398","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-01",3,"Voy a contarles señores\nEn un tiempo de mi vida,\nCuando boté la fortuna\nPor mis padres adquirida.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"ia",37,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-02",3,"Nunca aprendí a trabajar\nPorque plata me sobraba,\nMis padres la habían ganado\nY yo me la disfrutaba.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"aa",28,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-03",3,"Todos los que tienen hijos\nQue no saben trabajar,\nNo les llenen el bolsillo\nAntes que sepan ganar.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"a",21,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-04",3,"Poner la plata en sus manos\nEs hacerles un gran mal,\nPorque aprenden a comer\nAntes de saber mamar.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"a",-1,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-05",3,"Hoy los hijos ya se crian\nCon dinero, sin ganarlo,\nNo saben cómo lo tienen\nPero ya saben botarlo.",3,1,0,35,"¡VAMOS CANTANDO Y BAILANDO!",0,4,"ao",236,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-06",3,"¡Vamos cantando y bailando,\nVamos alegrándonos,\nY nos hagamos la cuenta:\nHoy somos, mañana no!",3,1,0,35,"VOY A CONTARLES SEÑORES",5,4,"o",-1,0,-1,0,277,277,"C-399","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0399-07",3,"Los padres hoy en el día,\nCon sus empeños prolijos,\nAcarician con dinero\nPervirtiendo así a sus hijos.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"io",377,0,-1,0,277,277,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-16",3,"¿nía mi buen pantalón\nara salir a pasear,\ncuando encontraba gente\n¡mpezaba a recular.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"a",21,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-17",3,"Tenía mis calzoncillos\nQue eran pura fantasía,\nLa pretina era bordada,\nDe purita liendrería.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"ia",0,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-18",3,"Tenía mi camisita\nPara salir a moniar,\nTiras por el espinazo\nY otras por el costillar.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"a",21,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-19",3,"Al verla tan viejecita\nYo la puse al sol un día,\nLo que se movían los piojos\nParecía infantería.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"ia",0,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-20",3,"Mi camisa se perdió\nY la hallé en los basurales,\nLa buscaba, no por ella,\nCuanto por los animales.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"ae",26,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-21",3,"Todo esto sufrí señores\nPor la culpa de mi tata,\nQue de chiquito me tuvo\nLa mano llena de plata.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"aa",74,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-22",3,"No me hizo amar el trabajo\nEn donde al dinero lo halle,\nSólo me enseñó a botarlo,\nY pronto me ví en la calle.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"ae",371,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-23",3,"Felizmente, mi razón\nY fuerza de voluntad,\nMe alejaron de los vicios\nY me puse a trabajar.",3,1,0,35,"VOY A CONTARLES SEÑORES",0,4,"a",-1,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0399-24",3,"Al fin soy feliz señores,\nPor la Virgen de Mercedes,\nY aquí me tienen casado\nA las órdenes de ustedes.",3,1,0,35,"VOY A CONTARLES SEÑORES",3,4,"ee",378,0,-1,0,278,278,"C-399","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0400-01",3,"Ya se acabaron tsu gustos\nSe acabó tu libertad,\nHas dentrado a la prisión\nEn la más florida edad.",3,1,0,35,"YA SE ACABARON TUS GUSTOS",0,4,"a",16,0,-1,0,278,278,"C-400","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0400-02",3,"Hoy es la pura alegría\nMañana será tristeza,\nY pasado ya comienza\nRecién la melancolía.\nSe han de aumentar cada día\nLos pesares y disgustos,\nTe ha de parecer injusto,\nHaberlo hecho sin saber,\nY allá verás el por qué\nYa se acabaron tus gustos.",3,1,0,35,"YA SE ACABARON TUS GUSTOS",18,10,"uo",-1,0,-1,0,278,278,"C-400","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0400-03",3,"¡Adiós, a las pajarillos\nQue fueron tus compañeros!\nHoy te quedas prisionero\nCon los más pesados grillos.",3,1,0,35,"YA SE ACABARON TUS GUSTOS",5,4,"io",161,0,-1,0,278,278,"C-400","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0400-04",3,"Acordate de que ayer\nGozabas lo que querías,\nY sólito bien dormías,\n¿Quién privaba tu placer?\nAgora como te vez\nCautivo, sin dirección,\nCon la dura precisión\nDe haber andado ignorante,\nSin ver atrás, ni adelante,\nHas dentrado a la prisión.",3,1,0,35,"YA SE ACABARON TUS GUSTOS",18,10,"o",31,0,-1,0,278,279,"C-400","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0400-05",3,"¿Qué es lo que te ha sucedido\nCuál ha sido tu pensar,\nQue así te has llegado a enfriar\nDe la noche a la mañana?\nTe vas a cubrir de canas\nEn la más florida edad.",3,1,0,35,"YA SE ACABARON TUS GUSTOS",9,6,"a",-1,0,-1,0,279,279,"C-400","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0401-02",3,"Y en mis hojas solamente,\nAlojaban su niditos.\nY hoy porque me ven marchito\nMe miran indiferente.",3,1,0,35,"YO ERA UN ÁRBOL ESTIMADO",5,4,"ee",15,0,-1,0,279,279,"C-401","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0401-03",3,"Cuando era de hojas coposo,\nA mis sombras se venían,\nLas aves allí vivían,\nContentas, llenas de gozo.\nEse tiempo primoroso,\nEn el mal se ha convertido,\nLas aves dejan sus nidos,\nSin saber considerar,\nQue mis hojas se han de criar\nY seré el que ante he sido.",3,1,0,35,"YO ERA UN ÁRBOL ESTIMADO",18,10,"io",-1,0,-1,0,279,279,"C-401","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0401-04",3,"Cada árbol tiene su tiempo,\nY al riego de un hortelano\nSólo espera un buen verano,\nY una hermosa primavera.\nY si esto así sucediera,\nGozará esta pobre planta,\nCon el riego se levanta,\nY vuelve a reverdecer,\nPorque suele suceder\nQue el más caído se levanta.",3,1,0,35,"YO ERA UN ÁRBOL ESTIMADO",18,10,"aa",-1,0,-1,0,279,279,"C-401","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0402-01",3,"A un jardín hermoso entré,\nmil flores guarnecido.\nY de ellas he elegido,\nque de mi gusto fué.\nmirarla la encontré\nY mil virtudes a un tiempo,\nla contemplé un momento,\ntarla me era un dolor,\nque para mí, no hay flor,\nMás linda que el pensamiento.",3,1,0,36,"L UN JARDÍN HERMOSO ENTRE",18,10,"eo",94,0,-1,0,281,281,"C-402","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0402-02",3,"•éis en la primavera,\nEsparciendo sus colores,\ndiamela y otras flores,\nHermoseando la pradera.\nmo bonita es cualquiera,\nlas deseo un momento,\nPero luego me arrepiento\nNegándoles su primor,\nPorque para mí, no hay flor\nMás linda que el pensamiento,",3,1,0,36,"L UN JARDÍN HERMOSO ENTRE",18,10,"eo",94,0,-1,0,281,281,"C-402","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0402-03",3,"clavelina y la rosa,\nazucena y margarita,\nTodas estas son bonitas,\nSon flores muy primorosas,\nFragantes y muy hermosas,\nniego su valimiento;\nPero ellas tienen su tiempo\nque pierden su valor,\nPor esto digo, no hay flor\nMás linda que el pensamiento.",3,1,0,36,"L UN JARDÍN HERMOSO ENTRE",18,10,"eo",-1,0,-1,0,281,281,"C-402","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0402-06",3,"Siempre quisiera tenerlo\nConservado en todo tiempo,\nPorque con el pensamiento\nGozo de un amor sin verlo.\nNo hay quién deje de quererlo\nPorque es todo nuestro aliento,\nNos da vida y movimiento,\nEndulza nuestro dolor,\nPor eso digo: no hay flor\nMás linda que el pensamiento.",3,1,0,36,"L UN JARDÍN HERMOSO ENTRE",18,10,"eo",94,0,-1,0,281,281,"C-402","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0402-07",3,"Con esta flor puedo entrar\nHasta en lugar más secreto,\nY ver muy bien el objeto,\nQue más se quiera ocultar.\nY es imposible evitar\nA este ojo su atrevimiento;\nEl se penetra violento\nAl sitio de más honor,\n¡Quisiera ser esa flor\nQué se llama pensamiento!",3,1,0,36,"L UN JARDÍN HERMOSO ENTRE",18,10,"eo",94,0,-1,0,281,281,"C-402","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-01",3,"¡Ay, pucha, con mi acuyico,\nYa sin zumo se quedó!\nApúrate pos burrito\nEl avio se me acabó.",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",0,4,"o",2,0,-1,0,281,281,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-02",3,"Marchá juerte mi burrito,\nYa está cerca l'apacheta,\nPa cambiar mi acuyiquito\nHasta estirar bien la geta.",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",1,4,"ea",200,0,-1,0,281,281,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-03",3,"También se acabó mi muti,\nTraigo más hambre que un perro,\nVamos al trote burrito,\nHay que trastornar el cerro.",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",0,4,"eo",379,0,-1,0,281,281,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-04",3,"Ya viene la noche encima,\nTuavía está lejos mi rancho,\nY para mayor pesar,\nLa lunita, manancancho.",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",0,4,"ao",380,0,-1,0,281,282,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-05",3,"Vengo caminando agatas,\nYa no puedo caminar,\nMueva el burrito sus patas\nVoy a ponerme a cantar:",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",1,4,"a",21,0,-1,0,282,282,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0403-06",3,"Granada puca ttikita\nTtica puca granadita;\nIscaita munacuscaita\nLlahuani munacuscaita.",3,1,0,36,"¡AY, PUCHA, CON MI ACUYICO!",5,4,"aa",-1,0,-1,0,282,282,"C-403","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0404-01",3,"Bello árbol que habéis crecido\nEn el medio de la selva.\nQuizá a tu sombra no vuelva\nA tirarse el león rendido.",3,1,0,36,"BELLO ÁRBOL QUE HABÉIS CRECIDO",11,4,"io",101,0,-1,0,282,282,"C-404","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0404-02",3,"Ahora solo, en la lomada,\nTe alzas enorgullecido,\nViéndote verde y erguido,\nDominando la cañada.\nEn tu copa enmarañada\nLas aves han hecho nido,\nY yo también he venido,\nA vivir bajo tu sombra,\nPor esto nada te asombra,\nBello árbol que habéis crecido.",3,1,0,36,"BELLO ÁRBOL QUE HABÉIS CRECIDO",18,10,"io",101,0,-1,0,282,282,"C-404","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0404-03",3,"Tantos años ignorado,\nDentro del bosque has vivido,\nHoy mi suerte te ha elegido,\nPara morar a tu lado.\nAl pie de tu tronco amado,\nY antes que el invierno vuelva\nY en hielo mi plan resuelva\nConstruyo pronto mi rancho,\nAl estilo del carancho,\nEn el medio de la selva.",3,1,0,36,"BELLO ÁRBOL QUE HABÉIS CRECIDO",18,10,"ea",381,0,-1,0,282,282,"C-404","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0404-04",3,"A tu sombra muy dichoso\nMi luna de miel pasé,\nJamás a tu lado hallé,\nNingún pesar doloroso.\nTu follaje siempre hermoso\nSentirá que se disuelva,\nMas no quiero que te envuelva,\nLa fatal enredadera;\nAunque dicha verdadera,\nQuizá a tu sombra no vuelva.",3,1,0,36,"BELLO ÁRBOL QUE HABÉIS CRECIDO",18,10,"ea",-1,0,-1,0,282,282,"C-404","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0404-05",3,"Veintiún años, felizmente\nHas pasado en mis amores,\nY otros tantos con tus flores,\nPerfumastes el ambiente.\n¡Cuántas veces dulcemente\nA tu sombra se ha dormido\nMi madre y te ha bendecido\nAl unirte a mi destino!\nDonde tantas veces vino\nA tirarse el león rendido.",3,1,0,36,"BELLO ÁRBOL QUE HABÉIS CRECIDO",18,10,"io",-1,0,-1,0,282,282,"C-404","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0405-01",3,"De todos los labradores\nNadie me gana a sembrar.\nEn tierra de cultivar\nTengo plantas de nogal,\nY aunque duro pedernal,\nQue se riega con los soles,\nMe da lechugas y coles,\nDuraznos, ricos membrillos,\nTambién da para cercar\nTrébol, bobo y espinillo.",3,1,0,36,"DE TODOS LOS LABRADORES",18,10,"io",-1,0,-1,0,282,282,"C-405","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0405-02",3,"Tengo una planta frondosa\nEn la tierra más pelada,\nCuando está recién regada\nDa una flor, la más hermosa\nDa margaritas y rosas,\nAl medio día, avellanas,\nPor la tarde, da manzanas,\nA la oración quirucillas,\nPor la noche da frutillas,\nY guindas por la mañana.",3,1,0,36,"DE TODOS LOS LABRADORES",18,10,"aa",-1,0,-1,0,282,282,"C-405","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0405-03",3,"Tengo plantas de amancais\nMe dicen que no da fruto,\nYo con ellas vivo a gusto,\nCosecho cebada y máiz.\nY si le tapo la ráiz\nDa variadas producciones,\nEntre ellas me da pelones;\nCarga como una zapallar,\nY para dejar de dar\nMe da papas y piñones.",3,1,0,36,"DE TODOS LOS LABRADORES",18,10,"oe",34,0,-1,0,282,282,"C-405","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0406-01",3,"Hombre rico por demás\nDe fortuna cerrada,\nmuchos rodeos de vacas\nMucha plata enterrada.",3,1,0,36,"HOMBRE RICO POR DEMÁS",0,4,"aa",-1,0,-1,0,283,283,"C-406","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-02",3,"Que al cerrarse la oración\nSalga a repuntar las flacas,\nLes resbale cuero y astas,\nDe consiguiente a las yeguas,\nQue no me descuide de ellas\nQue también la cerda es plata.",3,1,0,36,"JAN DEL CAMPO ES MI PATRÓN",9,6,"aa",-1,0,-1,0,283,283,"C-407","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-03",3,"A varios hombres los veo\nSeñalar al orejano,\nY así van acrecentando,\nY agrandando sus rodeos.\nYo me muero de deseos\nAl ver esta maravilla,\nTodos señalan y pillan\nY lo marcan sin tardanza,\nEl que no es horqueta y lanza,\nEs tarja, muesca o varilla.",3,1,0,36,"JAN DEL CAMPO ES MI PATRÓN",18,10,"ia",-1,0,-1,0,283,283,"C-407","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0407-04",3,"¡Señores los que no tengan\nTorzales para ír a atar,\nPueden con tiempo sacar\nAntes que los dueños vengan!\nEs bueno que se prevengan\nDe lonjas y maniadores.\nLuego con los mancarrones\nMe lo paso muy contento,\nLes tapo el hierro al momento\nY los vendo cuando engorden.",3,1,0,36,"JAN DEL CAMPO ES MI PATRÓN",18,10,"oe",-1,0,-1,0,283,283,"C-407","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-05",3,"En esto que voy y vengo,\nSi me llegan a pillar\nBien estudiada la tengo\nLa excusa que voy a echar.\nSi alguno me llega hallar\nAlgún toro desollando",3,1,0,36,"JAN DEL CAMPO ES MI PATRÓN",9,6,"ao",-1,0,-1,0,283,283,"C-407","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-06",3,"Le diré al dueño: —campeando\nHallé muerto este animal,\nConociendo su señal\nPor eso lo estoy cueriando.",3,1,0,36,"JAN DEL CAMPO ES MI PATRÓN",11,4,"ao",33,0,-1,0,284,284,"C-407","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-a-01",3,"Juan del campo es mi patrón,\nY me dió su hacienda a medías,\nPa que trabaje con ella,\nPero con la condición\nQue llegada la oración\nSalga a recontar las flacas,\nLes resfal cuero y astas,\nDe consiguiente a las yeguas,\nQue no me descuide de ellas\nQue también la cerda es plata.",3,1,0,36,"JUAN DEL CAMPO ES MI PATRÓN",18,10,"aa",-1,0,-1,0,284,284,"C-407-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0407-a-02",3,"Si me llegan a topar\nEn esto que voy y vengo,\nEs t u d i a d i t a la tengo,\nA la escusa que hi d'echar.\nSi me llegan a pillar\nCon un toro desollado\nLe diré al dueño: —campiando\nHallé muerto a este animal,\nConociendo su señal\nEl cuero le estoy sacando.",3,1,0,36,"JUAN DEL CAMPO ES MI PATRÓN",18,10,"ao",33,0,-1,0,284,284,"C-407-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-a-03",3,"¡Señore's, los que no tengan\nTorzales para amarrar,\nCon tiempo deben sacar\nAntes que los dueños vengan!\nY es justo que se prevengan\nCon lonjas y maniadores\nQue yo con mis mancarrones\nPal trajín estoy contento\nBorrar el hierro por cierto\nY venderlo cuando engorde.",3,1,0,36,"JUAN DEL CAMPO ES MI PATRÓN",18,10,"oe",-1,0,-1,0,284,284,"C-407-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0407-a-04",3,"A varios hombres los veo\nSeñalar al orejano,\nAsí van acrecentando,\nMás y más a su rodeo.\nYo me muero de deseo\nAl ver esa maravilla,\nTodos enlazan y pillan,\nContra señalan y marcan\nLe echan pilón, punta i lanza\nY si no es plancha es parrilla.",3,1,0,36,"JUAN DEL CAMPO ES MI PATRÓN",18,10,"ia",-1,0,-1,0,284,284,"C-407-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0408-01",3,"No hay vida más ventajosa\nQue la vida del colero,\nEllos toman con esmero\nSin que les cueste la cosa.",3,1,0,36,"NO HAY VIDA MAS VENTAJOSA",11,4,"oa",63,0,-1,0,284,284,"C-408","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0408-02",3,"Son aves muy desplumadas\nY de un olfato terrible,\nPara ellos no es imposible\n'. descubrir las tomadas;\nDe lejos son olfateadas,\nDe esa gente tan ociosa,\nNo se ocupan de otra cosa,\nPues no tienen qué gastar,\nPoniéndonos a pensar,\nNo hay vida más ventajosa.",3,1,0,36,"NO HAY VIDA MAS VENTAJOSA",18,10,"oa",63,0,-1,0,285,285,"C-408","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0408-03",3,"A ellos les entra la loca\nPor pedir tabaco y chala,\nY lo miran a la cara;\nPor ver si mueve la boca,\nPara pedirnos la coca,\nCon acento plañidero,\nY como falta el entero\nNo le retiran la vista,\nPor ver si muerde la yista\nQue es la vida del colero.",3,1,0,36,"NO HAY VIDA MAS VENTAJOSA",18,10,"eo",38,0,-1,0,285,285,"C-408","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0408-04",3,"Después que se han enchispado\nLo principian a insultar,\nY lo quieren aporriar,\nAl que todo lo ha costeado.\nY se vuelven entonados\nCon aire de forasteros,\nLuego arman el entrevero,\nA cuchillo y a pedrada;\nEs que sin costarles nada\nEllos toman con esmero.",3,1,0,36,"NO HAY VIDA MAS VENTAJOSA",18,10,"eo",38,0,-1,0,285,285,"C-408","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0408-05",3,"no les brinda bebida\nde antojo no se mueran,\nsalen para afuera,\nEn busca de la querida.\nNos esconden la bebida.\nEntre su ropa asquerosa,\n¡Qué gente facinerosa!\nQue se llena los bolsillos,\nCon los vasos y pocillos\nSin que les cueste la cosa.",3,1,0,36,"NO HAY VIDA MAS VENTAJOSA",18,10,"oa",63,0,-1,0,285,285,"C-408","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0409-01",3,"¿Quién no se puede alegrar\nAl ver el tiesto en el fuego?\nY más cuando tuestan luego\nSe quita todo pesar.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",11,4,"a",21,0,-1,0,285,285,"C-409","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0409-02",3,"Cuando arreglan los tizones\nY empiezan con el carbón,\nSe le alegra el corazón\nAl mirar estas acciones,\nQue demuestran las funciones\nA que se va a destinar;\nViendo al tiesto colocar\nPara empezar la maniobra,\nCuando el hambre a uno le sobra\n¿Quién no se puede alegrar?",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",18,10,"a",21,0,-1,0,285,285,"C-409","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0409-03",3,"Poniendo el máiz en un plato\nSe principia a desgranar,\nTodo se debe aprontar,\nCon todo juicio y recato,\nNo se deje para un rato,\nLo que se puede hacer luego,\nMás si uno está medio ciego,\nCon un hambre sin memoria,\nTodo es un placer y gloria\nAl ver el tiesto en el fuego.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",18,10,"eo",29,0,-1,0,285,285,"C-409","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0409-04",3,"Echándole la ceniza\nDespués el máiz en el tiesto,\nSe mirará presto, presto,\nPorque es cosa muy precisa;\nSi se quemó ya es omisa\nLa tostadora y no el fuego;\nSi se derrama en el suelo,\nEs causa de una omisión,\nSe le perdona la acción,\nY más cuando tuesta luego.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",18,10,"eo",-1,0,-1,0,285,285,"C-409","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0409-05",3,"¿Dónde habrá gloria mayor\nQue tener máiz morochillo?\nAunque es de grano sencillo,\nPero es muy reventador,\nTodo se convierte en flor;\nEl chulpi para gustar,\nEs suave y dulce al mascar,\nEl capia es atorador\nY aunque es tan empachador\nQue guita todo pesar.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",18,10,"a",21,0,-1,0,285,286,"C-409","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0409-a-01",3,"¿Quién no se puede alegrar\nAl ver el tiesto en el fuego?\nAl menos si tuesta luego,\nSe quita todo pesar.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",11,4,"a",21,0,-1,0,286,286,"C-409-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0409-a-02",3,"Echando el máiz en el plato\nSe comienza a desgranar,\nTodo se ha de preparar\nLo que es menester de un rato,\nAunque con juicio y recato,\nBuscarlo temprano es bueno.\nPor lo que turbarme puedo\nEn la fuerza de esta historia,\nPorque todo es pura gloria\nAl ver el tiesto en el fuego.",3,1,0,36,"¿QUIEN NO SE PUEDE ALEGRAR?",18,10,"eo",-1,0,-1,0,286,286,"C-409-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0410-01",3,"Todas las frutas marchaban\nUna mañana de enero,\nY a la ciruela eligieron,\nPríncipe de jardinero.",3,1,0,36,"TODAS LAS FRUTAS MARCHABAN",0,4,"eo",-1,0,-1,0,286,286,"C-410","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0410-02",3,"Los árboles a porfía\nSe ponen a argumentar,\nA cual se le podría dar\nEl don de la mejoría.",3,1,0,36,"TODAS LAS FRUTAS MARCHABAN",11,4,"ia",0,0,-1,0,286,286,"C-410","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0410-03",3,"La manzana respondía:\nQue todo lo despreciaba\nPorque en el campo se hallaba\nLlena de sofocación.\nPor esta justa razón\nTodas las frutas marchaban.",3,1,0,36,"TODAS LAS FRUTAS MARCHABAN",9,6,"aa",-1,0,-1,0,286,286,"C-410","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0410-a-02",3,"Los árboles a porfía,\nSe ponen a argumentar,\nA cual se le podría dar\nEl don de la mejoría.\nLa manzana respondía,\nQue todo lo despreciaba,\nPorque en el campo se hallaba,\nLlena de sofocación;\nPor esta justa razón\nTodas las frutas marchaban.",3,1,0,36,"TODAS LAS FRUTAS MARCHABAN",18,10,"aa",-1,0,-1,0,286,286,"C-410-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0410-a-03",3,"presentó en breve rato\ndurazno en corto trecho,\nos rajos de un peral\nhendiendo su derecho,\nmelón que no es deshecho,\npresentó con esmero\ndamasco caballero\nY escuchó esta pendencia,\nse presentó en audiencia\na mañana de Enero.",3,1,0,36,"TODAS LAS FRUTAS MARCHABAN",18,10,"eo",38,0,-1,0,287,287,"C-410-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0411-02",3,"Es cierto que al parecer\nEl apero es elegante,\nPero como no es flamante,\nPuede algo malo tener.\nDe estar echado a perder;\nSi el dueño fué descuidado,\nPuede estar apolillado,\nY tal vez sin compostura,\nMirándolo con cordura,\nEs un precio demasiado.",3,1,0,36,"",18,10,"ao",14,0,-1,0,287,287,"C-411","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0411-03",3,"En mi sería una maldad\nSi pretendiera comprarlo,\nSin primero examinarlo,\nY mirar su calidad.\nSólo por casualidad,\nPodría salir a mi agrado,\nAunque muy bien arreglado,\nPero el dueño por supuesto,\nPuede haberlo descompuesto,\nPorque bastante lo ha usado.",3,1,0,36,"",18,10,"ao",14,0,-1,0,287,287,"C-411","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0411-06",3,"Cierto, el apero es muy lindo\nMás no por eso consiento,\nEn que sea de buen asiento,\nPor el uso que ha tenido.\nPuede por algún descuido\nMaltratarme el parejero,\nPorque según considero,\nTiene el defecto mayor,\nEn que lo hizo atrasador,\nEl que lo compró primero.",3,1,0,36,"",18,10,"eo",38,0,-1,0,287,287,"C-411","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0411-08",3,"Acuso mi padre santo,\nQue adoro a una ingrata bella,\nEs más linda que una estrella\nPor eso la quiero tanto.\n—¡Hijo muy malo es tu encanto\nNo puede ser permitido,\nPorque Dios tiene prohibido,\nEl amor con desenfreno.\n—¡Mi padre, no siendo así,\nYo creo que es permitido!",3,1,0,37,"ACUSO, MI PADRE SANTO",18,10,"io",101,0,-1,0,289,289,"C-411","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0411-10",3,"¡Jesús hijo, reza el Credo,\nMira que estás condenado,\nQue si el diablo te ha tentado\nHasta yo te tengo miedo!\nMi padre no fuera el miedo\nEn su razón lo venciera,\nNi al infierno le temiera\nCuando se ama a una bonita.\nPorque sólo Dios se irrita\nCuando se adora una fiera.",3,1,0,37,"ACUSO, MI PADRE SANTO",18,10,"ea",44,0,-1,0,289,289,"C-411","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0411-11",3,"—Si tu alma está arrepentida\nBotarás a esa mujer,\n—¡Padre, no lo puedo hacer,\nEs mi alma y toda mi vida,\nMe da plata y la comida,\nRopita y planchado hermoso.\nResponde el padre gozoso:\n¡Jesús, mi Dios y Señor,\nQué bonita proporción\nPara un padre religioso!",3,1,0,37,"ACUSO, MI PADRE SANTO",18,10,"oo",160,0,-1,0,289,289,"C-411","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0412-a-01",3,"Acúsome padre santo\nQue adoro a una ingrata y bella,\nQue es más linda que una estrella\nPor eso la quiero tanto.\n—Hijo, es muy malo tu encanto\nY mira que vas perdido,\nPorque Dios tiene prohibido\nEl amor con desenfreno:\n—Padre, si no siendo ajeno\nCreo que me es permitido...",3,1,0,37,"ACUSÓME, PADRE SANTO",18,10,"io",101,0,-1,0,289,289,"C-412-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0412-a-02",3,"Yo le diré, padre santo,\nCómo ha sido mi pasión:\nMe ha robado el corazón\nCon la mayor sutileza,\nEs tan grande su belleza,\nQue al mirar esa deidad,\nCon tanta gracia y bondad,\nPadre si usted la mirara,\nHasta el hábito botara\nTalvez, su paternidad.",3,1,0,37,"ACUSÓME, PADRE SANTO",18,10,"a",16,0,-1,0,289,289,"C-412-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0412-a-03",3,"¡Jesús, hijo, reza el credo\nMira que estás condenado\nQue si el diablo te ha tentado\nHasta yo te tengo miedo!\n—Padre, si no fuera el miedo\nMi razón lo convenciera\nY al infierno no temiera\nPor amar una bonita\nPorque sólo Dios se irrita\nCuando se quiere una fiera.",3,1,0,37,"ACUSÓME, PADRE SANTO",18,10,"ea",44,0,-1,0,289,289,"C-412-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0414-01",3,"Al que ande enfermo de amor\nZampelé un baño en el río,\nSi se le apodera el mal,\nTomelé el pulso Cupido.",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",0,4,"io",-1,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0414-02",3,"Denlé al enfermo un purgante\nDe jarabe de mosqueta,\nCupido dió esta receta,\nPor que aquel ha sido amante.\nSi el amor sigue adelante,\nDenlé de leche un sudor,\nY para que críe valor\nY el enfermo no padezca,\nDenlé una bebida fresca\nAl que ande enfermo de amor.",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",18,10,"o",72,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0414-03",3,"Hagamoslé una bebida\nEn cáscara de patagua,\nUn tercio de canchalagua,\nY más tres claras batidas,\nEn agua cocida y tibia,\nUn vaso de vino hervido.\nSi el calor ha recogido\nDénle la raíz de la malva,\nBien de mañana o al alba\nZámpenlé un baño en el río.",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",18,10,"io",-1,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0414-04",3,"Apliquelé usted una ayuda\nDe caldo de pollo negro,\nPóngale parche al cerebro\nPara que el mal no le acuda.\nMachaque usted una ave cruda,\nMedia fanega de sal,\nQuince libras de quillay\nY seis pesos de jabón.\nBusquelé la confesión\nSi se le apodera el mal.",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",18,10,"a",-1,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0414-05",3,"Si esta cura no le opera\nY está falto de sustento,\nDelé por agua del tiempo,\nLa ráiz de la escorsonera.\nPongalé parches de cera,\nA ambos lados del sentido,",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",9,6,"io",-1,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0414-06",3,"De tabaco bien molido,\nEn papel que no se acabe,\nY más si el mal no le sale\nTomelé el pulso Cupido.",3,1,0,37,"AL QUE ANDE ENFERMO DE AMOR",5,4,"io",101,0,-1,0,290,290,"C-414","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-01",3,"Aquí está tu medio amante,\nQue medio anduvo perdido,\nMedio te viene a buscar\nPorque medio te ha querido.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"io",101,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-02",3,"En el medio del camino\nYo medio me anoticié,\nQue medio me has olvidado\nPorque medio te dejé.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"e",77,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-03",3,"Con el medio portador,\nTe mandé medias memorias,\nPorque medio recordaba\nQue era yo tu media gloria.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"oa",-1,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-04",3,"Medio de ti me alejé\nPorque medio había notado,\nQue si medio me querías,\nMedio me habías engañado.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"ao",14,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-05",3,"Yo medio me retiré,\nMedio tiempo de tu lado,\nComo medio ingrato he sido,\nA medio tiempo he llegado.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"ao",14,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0415-06",3,"Medio arrepentido vengo,\nMedio te vengo a decir,\nQue si medio no me admites,\nMedio me verás morir.",3,1,0,37,"AQUÍ ESTA TU MEDIO AMANTE",0,4,"i",157,0,-1,0,290,290,"C-415","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0416-01",3,"Aviso al mundo que tuve\nUna hija con mi comadre;\nSe crió, me casé con ella,\nFuí su padrino y su padre.",3,1,0,37,"AVISO AL MUNDO QUE TUVE",3,4,"ae",166,0,-1,0,290,290,"C-416","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0416-03",3,"Cuando él llegó a volver,\nVió a su mujer desgraciada,\nY como ninguno entraba,\nDijo que yo había de ser.\nY ella por obscurecer\nMe dijo: \"No seas cobarde;\nTú vas a ser mi compadre\".\nY yo tuve que ceder.\nPor donde vine a tener\nUna hija con mi comadre.",3,1,0,37,"AVISO AL MUNDO QUE TUVE",18,10,"ae",166,0,-1,0,291,291,"C-416","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0416-05",3,"Después que ya me casé,\nEn conversación un día,\nis que era hija mía,\ni ahijada y mi mujer.\nA be conocer\nCada uno sus amistades,\nY no cometer maldades\nComo las he cometido.\nQue antes de ser su marido,\nFui su padrino y su padre.",3,1,0,37,"AVISO AL MUNDO QUE TUVE",18,10,"ae",-1,0,-1,0,291,291,"C-416","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0417-01",3,"Ayer estabas con Juan,\nAntes con Diego y Martín,\nHoy con Hilario y Fermín,\nMañana con Sebastián.\nSi de esto sabe Julián,\nEn sus manos quiero verte,\nY bien puedes esconderte,\nPorque has querido a Matías.\nY a causa de Zacarías,\nYo prometo no quererte.",3,1,0,37,"AYER ESTABAS CON JUAN",18,10,"ee",134,0,-1,0,291,291,"C-417","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0417-02",3,"Con Miguel eres ingrata,\nPor querer a Celedonio;\nTambién le sales a Antonio\nCon la misma patarata.\nMirá que Ignacio te mata\nPorque le hicistes así,\nTú me engañastes a mí,\nTratando de mala fe,\nPor eso te desconfié\nDesde que te conocí.",3,1,0,37,"AYER ESTABAS CON JUAN",18,10,"i",23,0,-1,0,291,291,"C-417","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0417-03",3,"Estando tú con Reinaldo,\nLo engañastes a Manuel,\nFuistes a casa de Andrés\nA pedir dote de Eduardo.\nPor eso dice Ricardo\nQue son tus astucias tantas,\nY que si a Lorenzo lo plantas,\nCon Pablo quedas formal.\nCuando yo te quiero hablar,\nTe quieres hacer la santa.",3,1,0,37,"AYER ESTABAS CON JUAN",18,10,"aa",-1,0,-1,0,291,291,"C-417","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0417-04",3,"Estanislao con Mariano,\nAmbos se mueren por vos;\nLo que has hecho con los dos,\nLo has de pagar con Lauriano.\nAsí dice Cayetano,\nQue ya dará fe de ti.\nYo me retiro de aquí\nPorque no tienes enmienda.\nYa saldrás con encomienda\nY me culparás a mí.",3,1,0,37,"AYER ESTABAS CON JUAN",18,10,"i",23,0,-1,0,291,291,"C-417","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0418-01",3,"Casate, me dijo el cura;\nYo le dije: no, vicario,\nSi quiere que yo me case,\nQue se case el comisario.",3,1,0,37,"CÁSATE, ME DIJO EL CURA",0,4,"ao",25,0,-1,0,291,291,"C-418","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0418-02",3,"Porque estuve divertido\nUna noche en un gran baile,\nSin tocar un pelo a nadie,\nTodo el mundo lo ha sabido;\nY en un infierno metido",3,1,0,37,"CÁSATE, ME DIJO EL CURA",7,5,"io",101,0,-1,0,291,291,"C-418","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0418-03",3,"Me tienen con gran locura;\nBuscarme mujer procuran\nLas viejas casamenteras;\nY por estas consejeras,\nCásate, me dijo el cura.",3,1,0,37,"CÁSATE, ME DIJO EL CURA",7,5,"ua",-1,0,-1,0,292,292,"C-418","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0419-01",3,"Cuando carnie mi chivito\nL'astita no hi de perder,\nMañana cuando me case,\nChambao para mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-02",3,"Cuando carnie mi chivito\nLa paleta no hi perder,\nMañana cuando me case,\nBandeja pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-03",3,"Cuando carnie mi chivito\nLas bostitas no hi perder,\nMañana cuando me case,\nRosario pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-04",3,"Cuando carnie mi chivito\nL'uñita no hi de perder,\nMañana cuando me case,\nZapatos pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-05",3,"Cuando carnie mi chivito\nL'uchito no hi de perder,\nMañana cuando me case,\nBombilla pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-06",3,"Cuando carnie mi chivito\nCabeza no hi de perder,\nMañana cuando me case,\nUn mate pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0419-07",3,"Cuando mate mi chivito\nCostillas no hi de perder,\nMañana cuando me case,\nValija pa mi mujer.",3,1,0,37,"CUANDO CARNIE MI CHIVITO",0,4,"e",-1,0,-1,0,292,292,"C-419","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0420-01",3,"Determinado me siento\nDe aborrecer lo que adoro,\nY en el mismo instante lloro\nMi propio aborrecimiento.",3,1,0,37,"DETERMINADO ME SIENTO",11,4,"eo",94,0,-1,0,292,292,"C-420","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0420-02",3,"Adoro una niña hermosa,\nPero es una ingrata fiera,\nEs de mi alma prisionera,\nEs una sierpe engañosa.\nEs tortolilla amorosa,\nPero en lo que digo miento,\nEs un fiero león sangriento,\nNo esmeralda, sino perla,\nPor adorarla y quererla,\nDeterminado me siento.",3,1,0,37,"DETERMINADO ME SIENTO",18,10,"eo",94,0,-1,0,292,292,"C-420","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0420-03",3,"Es un Serafín del Cielo\nAquella deidad que adoro,\nEs de honores un tesoro\nY es todo mi desconsuelo.\nPor amarla me desvelo,\nY por su amor yo me atoro,\nPero si no la desdoro,\nYo mismo me contradigo,\nQue me obligo y no me obligo\nDe aborrecer lo que adoro.",3,1,0,37,"DETERMINADO ME SIENTO",18,10,"oo",85,0,-1,0,292,292,"C-420","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0420-04",3,"Es mi fe tan excesiva\nY mi pena tan incierta,\nQue quisiera verla muerta,\nPero al mismo instante viva.\nEl amor de ella me obliga\nA no perder su decoro,\nYo la aborrezco y la adoro\nAl ver su bello semblante;\nLa aborrezco en un instante,\nY en el mismo instante lloro.",3,1,0,37,"DETERMINADO ME SIENTO",18,10,"oo",85,0,-1,0,292,292,"C-420","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0420-05",3,"Al fin no la puedo ver,\nPorque si la veo me pesa,\nSi me falta su belleza\nEs más crecido el placer.\nDejarla no puede ser,\nOlvidarla es sentimiento,\nEstar con ella es tormento;\nEntre uno y otro dolor,\nMe sirve de más amor\nMi propio aborrecimiento.",3,1,0,37,"DETERMINADO ME SIENTO",18,10,"eo",94,0,-1,0,292,292,"C-420","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0421-01",3,"Dispara un zorro sarnoso\nDe otro sarnoso como él,\nCreyendo que era algún tigre\nQue se lo venía a comer.",3,1,0,37,"DISPARA UN ZORRO SARNOSO",0,4,"e",-1,0,-1,0,293,293,"C-421","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0421-02",3,"Después de tanto correr,\nPerdió su rumbo y su ruta,\nCayó en la boca del tigre\nY se lo llevó a San P u...",3,1,0,37,"DISPARA UN ZORRO SARNOSO",5,4,"u",-1,0,-1,0,293,293,"C-421","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0422-01",3,"El alma, mi bien, te di,\nY es cuanto puedo hacer yo.\n¿Qué diré al que me la dió?\nDiré que se me perdió.",3,1,0,37,"EL ALMA, MI BIEN, TE DI",0,4,"o",2,0,-1,0,293,293,"C-422","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0422-02",3,"Un rey, ofrecer podrá\nUn trono a su amante hermosa,\nPero un trono es poca cosa\nSi el alma fiel no le da.\nEste don no igualará\nAl que yo te ofrecí a ti,\nQue porque reines en mí,\nDe mí mismo hago abandono,\nSi no te ofrecí yo un trono,\nEl alma, mi bien, te di.",3,1,0,37,"EL ALMA, MI BIEN, TE DI",18,10,"i",23,0,-1,0,293,293,"C-422","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0422-03",3,"Este es mi holocausto, en él\nFundo todo mi derecho,\nViviendo mi alma en tu pecho,\nVerá si la tuya es fiel.\nConserva tú ese joyel\nQue mi fino amor te dió,\nMás rico le habrá, mas no\nDe una calidad tan firme,\nQue es cuanto puedes pedirme,\nY es cuanto puedo hacer yo.",3,1,0,37,"EL ALMA, MI BIEN, TE DI",18,10,"o",2,0,-1,0,293,293,"C-422","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0422-04",3,"Así, un enigma seré\nCuando mi ser se destruya,\nViviendo mi alma en la tuya,\nMuerto o vivo te veré.",3,1,0,37,"EL ALMA, MI BIEN, TE DI",11,4,"e",77,0,-1,0,293,293,"C-422","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0422-05",3,"Y si el reino de la fe\nSólo al alma se ofreció,\nNo sé cómo aspiro yo\nUn bien que a sólo ella es dado,\nY si en ti mi alma he dejado,\n¿Qué diré al que me la dió?",3,1,0,37,"EL ALMA, MI BIEN, TE DI",9,6,"o",2,0,-1,0,293,293,"C-422","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0422-06",3,"De esta suerte en triste calma\nUna sombra indefinida,\nNo soy un alma sin vida\nSino una vida sin alma.\nY si Dios, darme la palma\nQuiere allí, ¿qué diré yo?\n¿Qué nací sin alma? No,\nQue te la he dado, tampoco;\nMás bien haciéndome el loco,\nDiré que se me perdió.",3,1,0,37,"EL ALMA, MI BIEN, TE DI",18,10,"o",2,0,-1,0,293,293,"C-422","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0423-01",3,"El buey le dice al novillo:\n—Trabajá con atención,\nFijate que es pa tu bien,\nPa que no seas fatigón.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"o",31,0,-1,0,293,293,"C-423","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0423-02",3,"Responde el ternero y dice:\n—Mí padre es trabajador\nY con el tiempo hi de ser:\nAlcalde y Corregidor.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"o",72,0,-1,0,293,293,"C-423","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0423-03",3,"Responde la vaca y dice:\n—¡Calla, muchacho embustero,\nPronto nomás has de ser\nComo tu padre, jullero!",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"eo",38,0,-1,0,293,293,"C-423","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0423-04",3,"Responde el toro y le dice:\n—Y ¿qué es eso de jullero?\nSi querís te hago una apuesta\nA que te forjo un ternero.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"eo",38,0,-1,0,293,293,"C-423","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0423-05",3,"Responde la vaca y dice:\n—Ese cuento no es certero;\nVos echás tus multiplicos\nY te andás de bandolero.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"eo",38,0,-1,0,293,293,"C-423","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0423-06",3,"Responde el toro diciendo:\n—Y con esta condición,\nQue donde dejo el ternero,\nTambién dejo mantención.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"o",31,0,-1,0,293,294,"C-423","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0423-07",3,"Responde la vaca y dice:\n—Ese cuento es pura bola,\nSi querís criar tus hijos,\nHacé mamar en tus bo...",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",5,4,"o",-1,0,-1,0,294,294,"C-423","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0423-08",3,"Responde el toro diciendo:\n—Yo me levanto y me voy,\nQue si más me dejo estar\nPierdo lo que hi comer hoy.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"o",112,0,-1,0,294,294,"C-423","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0423-09",3,"Responde la vaca y dice:\n—Ite vos a tu querencia,\nYo mejor lo paso sola,\nQue tengo mejor presencia.",3,1,0,37,"EL BUEY LE DICE AL NOVILLO",0,4,"ea",46,0,-1,0,294,294,"C-423","",0,"","","",4,0,0,[],""],["carrizo_salta-nc0424-01",3,"El gobierno de hoy es bueno,\nY a todos nos da la mano.\nQuema el sol para el invierno,\nCon zuecos en el verano.\nSe han mudado los gobiernos,\nEl trigo moliendo piedras,\nLa nieve se ha vuelto negra,\nLos pastos comiendo reses,\nDoce años traen los meses,\nPor el camino la huella.",3,1,0,37,"EL GOBIERNO DE HOY ES BUENO",18,10,"ea",-1,0,-1,0,294,294,"C-424","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-02",3,"¿Quién ha visto a lo moderno\nPintar el mundo al revés?\nEl zorro comiendo al perro,\nEl ladrón por tras del juez.\nPara arriba van los pies,\nCon la boca va pisando,\nEl fuego al agua apagando,\nEl ciego enseñando letras,\nLos bueyes en la carreta,\nY la carreta tirando.",3,1,0,37,"EL GOBIERNO DE HOY ES BUENO",18,10,"ao",33,0,-1,0,294,294,"C-424","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-03",3,"Y si esto se prosiguiera,\nEl criado al amo mandara,\nLos dueños llevan las cargas,\nLas mulas se han vuelto arrieras.",3,1,0,37,"EL GOBIERNO DE HOY ES BUENO",5,4,"ea",-1,0,-1,0,294,294,"C-424","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-04",3,"Y en esta carrera espera\nEl ratón correr al gato,\nL'agua nadando en el pato,\nLa perdiz tras del halcón,\nEn esta constitución\nEntro el trigo van los sacos.",3,1,0,37,"EL GOBIERNO DE HOY ES BUENO",9,6,"ao",-1,0,-1,0,294,294,"C-424","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-05",3,"Alléguense a la jornada,\nAllá verán cosas raras,\nA los ganados tendidos\nY las culebras paradas.\nAllá verán cosas varias,\nCorrer al tigre el potrillo,\nAllá bala el corderillo,\nSiendo de la oveja madre,\nPor eso siempre la carne,\nViene cortando al cuchillo.",3,1,0,37,"EL GOBIERNO DE HOY ES BUENO",18,10,"io",228,0,-1,0,294,294,"C-424","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-a-01",3,"Pintar el mundo al revés\nSe ha visto entre tanto yerro,\nEl zorro corriendo al perro,\nEl ladrón por tras del juez.\nPara arriba van los pies,\nCon la boca va pisando,\nEl fuego al agua apagando,\nEl ciego enseñando letras,\nLos bueyes en la carreta\nY el carretero tirando.",3,1,0,37,"PINTAR EL MUNDO AL REVÉS",18,10,"ao",33,0,-1,0,294,294,"C-424-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-a-02",3,"Ei tirano de hoy es bueno,\nA todos nos da la mano.\nHiela el sol en el verano,\nY nos quema en el invierno.\nSe han mudado los gobiernos,\nLos trigos moliendo piedras,\nLa nieve se ha vuelto negra,\nLos pastos comiendo reses,\nDoce años tienen los meses,\nLa nuera se ha vuelto suegra.",3,1,0,37,"PINTAR EL MUNDO AL REVÉS",18,10,"ea",382,0,-1,0,294,294,"C-424-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-a-03",3,"Arrímense a una majada,\nVerán lo que nunca ha habido,\nEl ganado andar tendido,\nY las culebras paradas.",3,1,0,37,"PINTAR EL MUNDO AL REVÉS",5,4,"aa",-1,0,-1,0,294,294,"C-424-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-a-04",3,"Allí verán asombradas,\nCorrer al tigre el potrillo,\nY llamarlo al corderillo,\nSiendo la oveja la madre,\nAsí lo mismo la carne,\nAhora corta al cuchillo.",3,1,0,37,"PINTAR EL MUNDO AL REVÉS",9,6,"io",228,0,-1,0,295,295,"C-424-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0424-a-05",3,"Esto viene por su esfera\nQue el esclavo al amo manda,\nLos hombres llevan la carga\nLa mula se ha vuelto arriera,\nPor esta misma carrera,\nEl ratón corriendo al gato,\nEl agua nada en el pato,\nLa perdiz tras del halcón,\nPor esta continuación,\nAdentro el trigo va el saco.",3,1,0,37,"PINTAR EL MUNDO AL REVÉS",18,10,"ao",-1,0,-1,0,295,295,"C-424-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0425-01",3,"El tabaco y el papel\nEstá caro con extremo,\nPor eso siempre nos vemos\nTodos careciendo de él.\nHasta la yerba también\nHa llegado a tal estado,\nQue el agasajo, el agrado,\nMuy pronto se ha de acabar.\nY no se ha de convidar\nCon mate ni con cigarro.",3,1,0,37,"EL TABACO Y EL PAPEL",18,10,"ao",-1,0,-1,0,295,295,"C-425","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0425-02",3,"El aguardiente, el licor,\nEl vino y otras bebidas,\nEstán tan encarecidas,\nQue el comprarlas da terror,\nMas a un hombre tomador,\n¡Qué bolsillo ha de bastar!\n¿Qué cuenta le hace el comprar\nTan poquito como dan?\nYo dejo ya de tomar\nHasta que esté el frasco a real.",3,1,0,37,"EL TABACO Y EL PAPEL",18,10,"a",-1,0,-1,0,295,295,"C-425","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0425-03",3,"El querer muchachas mozas\nEs el engaño mayor,\nEstá tan caro el amor\nComo están todas las cosas.\nEllas son todas viciosas,\nY no llegan a mirar\nQue a uno le cuesta el comprar,\nEn esto no hacen reparo.\nMientras esté todo caro\nYo voy a dejar de amar.",3,1,0,37,"EL TABACO Y EL PAPEL",18,10,"a",21,0,-1,0,295,295,"C-425","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0425-04",3,"Yo no quiero mantener\nMuchachas que tengan vicio,\nPorque me es un sacrificio\nEl poderlas mantener.\nLa que se quiera poner\nMucho lujo, que lo sude,\nQue todo está por las nubes;\nY ahora, por fuerza mayor,\nVoy a dejar el amor,\nPorque el oro siempre sube.",3,1,0,37,"EL TABACO Y EL PAPEL",18,10,"ue",-1,0,-1,0,295,295,"C-425","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0426-01",3,"En esta casa hi llegado,\nSolo, hi llegado cantando;\nEl dueño hi casa ha salido\nViendo que yo iba llegando.",3,1,0,37,"EN ESTA CASA HI LLEGADO",0,4,"ao",33,0,-1,0,295,295,"C-426","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0426-02",3,"Yo le hi pedido permiso\nPara ponerme a cantar,\nEl permiso que me ha dado,\nAdentro me hizo sentar.",3,1,0,37,"EN ESTA CASA HI LLEGADO",0,4,"a",21,0,-1,0,295,295,"C-426","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0426-03",3,"Y me dijeron que cante,\nEchando para adelante\nUna copita de aloja.\n¡Ay, qué linda y qué fragante!",3,1,0,37,"EN ESTA CASA HI LLEGADO",0,4,"ae",47,0,-1,0,295,295,"C-426","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0427-01",3,"Entre todas las mujeres,\nNo hay mujer como mi Juana;\nSale por las oraciones.\nVuelve cuando le da gana.",3,1,0,37,"ENTRE TODAS LAS MUJERES",0,4,"aa",4,0,-1,0,295,295,"C-427","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0427-02",3,"Si se ofrece una guerrilla,\nSale la gente en campaña;\nPregunten quién va adelante,\nLa pobrecita mi Juana.",3,1,0,37,"ENTRE TODAS LAS MUJERES",0,4,"aa",-1,0,-1,0,295,295,"C-427","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0427-03",3,"A esto de jugar al paro\nTambién entiende mi Juana;\nBarajando bien el naipe,\nNo muy cualquiera le gana.",3,1,0,37,"ENTRE TODAS LAS MUJERES",0,4,"aa",4,0,-1,0,295,295,"C-427","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0428-01",3,"Eran cuatro caballeros\nQue perseguían una dama.\nLos cuatro se disputaban\n¿Quién será el dueño de su alma?",3,1,0,37,"ERAN CUATRO CABALLEROS",3,4,"aa",-1,0,-1,0,296,296,"C-428","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0428-02",3,"El uno de ellos decía\nQue, aunque no tenía camisa,\nPero que la ha de llevar\nA fuerza de sus caricias.",3,1,0,37,"ERAN CUATRO CABALLEROS",0,4,"ia",-1,0,-1,0,296,296,"C-428","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0428-03",3,"El otro de ellos decía\nQue, aún cuando no era soltero,\nPero que la ha de llevar\nA costa de su dinero.",3,1,0,37,"ERAN CUATRO CABALLEROS",0,4,"eo",38,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0428-04",3,"El otro de ellos decía\nQue no tenía pantalones,\nPero que la ha de llevar\nA costa de sus razones.",3,1,0,37,"ERAN CUATRO CABALLEROS",0,4,"oe",34,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0428-05",3,"El otro de ellos decía\nQue no tenía valimiento,\nPero que la ha de llevar\nPrometiendo casamiento.",3,1,0,37,"ERAN CUATRO CABALLEROS",0,4,"eo",94,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0428-06",3,"Se la llevaron,\nSe la llevó;\nLa polvareda\nNo más quedó.",3,1,0,37,"ERAN CUATRO CABALLEROS",6,4,"o",2,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0428-07",3,"Se la llevaron,\nSe la llevó;\nYo fuí testigo,\nPor ahí pasó.",3,1,0,37,"ERAN CUATRO CABALLEROS",6,4,"o",2,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0428-08",3,"Subí al alto de la torre,\nPor ver si la divisaba;\nSólo alcancé a ver el polvo,\nQue su amante la llevaba.",3,1,0,37,"ERAN CUATRO CABALLEROS",0,4,"aa",28,0,-1,0,296,296,"C-428","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0428-09",3,"Se la llevaron,\nSe la llevó;\nEn media plaza\nLa quité yo.",3,1,0,37,"ERAN CUATRO CABALLEROS",6,4,"o",2,0,-1,0,296,296,"C-428","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0430-01",3,"Un español\n—¡Hermosa deidad,\nAdorado hechizo,\nEscucha mis ayes,\nOye mis suspiros!",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,296,296,"C-430","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0430-02",3,"Una colla\n—Halagos de hombres\nSiempre son fingidos,\nY así, señor mío,\nYo no quiero oírlos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,296,296,"C-430","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0430-03",3,"Español\n—Bien, prenda del alma,\nSabes que los míos\nDel corazón nacen,\nLeales y finos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,296,296,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-04",3,"Colla\n—Vaya usted diciendo\nTodas sus caricias,\na ver lo que saca\nUsted con decirlas.",3,1,0,37,"HERMOSA DEIDAD",7,5,"ia",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-05",3,"Español\n-Sabrás, pues, mi bien,\n¡ue te amo y te estimo;\n\" en ti tengo puestos\n'odos mis sentidos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-06",3,"Colla\n—Esa es mucha brona\nY es mucho delirio,\nPonga usted doblones,\ntfo ponga sentidos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-07",3,"Español\n—Doblones, mi bien,\nSío te puedo dar,\nPorque en \"La Moneda\"\nÍTo sé trabajar.",3,1,0,37,"HERMOSA DEIDAD",7,5,"a",21,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-08",3,"Colla\n—Deme usted vestidos,\nPañuelos, zarcillos,\nFaluchos, pulcillos,\nMiriñaques finos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-09",3,"Español\n—Mi prenda del alma,\nMercader no he sido,\nNo tengo más ropas\nQue la que me visto.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-10",3,"Colla\n—Con gente tan pobre\nJamás he tratado,\nY en primer lugar\nPonga usted ducados.",3,1,0,37,"HERMOSA DEIDAD",7,5,"ao",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-11",3,"Español\n—El mejor ducado\nEs el corazón,\nDesde hoy será tuyo,\nDesde hoy te lo doy.",3,1,0,37,"HERMOSA DEIDAD",7,5,"o",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-12",3,"Colla\n—Corazón de gente\nJamás he comido,\nY así, señor mío,\nNo lo necesito.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-13",3,"Español\n—¡El alma que tiene\nUn precio infinito!\n¿Por qué me desprecias\nEste sacrificio?",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-14",3,"Colla\n—El alma no quiero,\nPorque según creo,\nNo soy purgatorio,\nNi tampoco infierno.",3,1,0,37,"HERMOSA DEIDAD",7,5,"eo",-1,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-15",3,"Español\n—Yo te diera todo\nCon justa razón,\nY también de palos\nSi hubiera ocasión.",3,1,0,37,"HERMOSA DEIDAD",7,5,"o",31,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-16",3,"Colla\n—Yo te los pegara\nCon mayor razón,\nPara que no seas\nPobre y querendón.",3,1,0,37,"HERMOSA DEIDAD",7,5,"o",31,0,-1,0,297,297,"C-430","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-01",3,"Español\n—¡Hermosa deidad,\nAdorado hechizo,\nEscucha mis ayes,\nOye mis suspiros!",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-02",3,"Colla\n—Halagos de hombre,\nTodos son fingidos;\nAsí, señor mío,\nYo no puedo oirlos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"oo",-1,0,-1,0,297,297,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-03",3,"Español\n—Sabrás que te quiero,\nTe adoro y te estimo;\nEn ti tengo puesto\nMis cinco sentidos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-04",3,"Colla\n—Esa es mucha excusa,\nEs mucho delirio;\nPonga usted dos luises,\nNo ponga sentidos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,297,297,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-05",3,"Español\n—Doblones, mi bien,\nNo te puedo dar,\nPorque en \"La Moneda\"\nNo sé trabajar.",3,1,0,37,"HERMOSA DEIDAD",7,5,"a",21,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-06",3,"Colla\n—Deme usted zarcillos,\nSortijas y aritos,\nFaluchos y anillos,\nMiriñaques finos.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-07",3,"Español\n—Mercader yo fuera,\nTe diera de un golpe\nTodo cuanto quieras,\nPero soy un pobre.",3,1,0,37,"HERMOSA DEIDAD",7,5,"oe",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-08",3,"Colla\n—Esa es mucha broma,\nCon pobres no trato;\nAsí, señor mío,\nBúsquese un ducado.",3,1,0,37,"HERMOSA DEIDAD",7,5,"ao",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-09",3,"Español\n—El mejor ducado\nEs mi corazón,\nSi tú lo recibes,\nDesde hoy te lo doy.",3,1,0,37,"HERMOSA DEIDAD",7,5,"o",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-10",3,"Colla\n—Corazón de gente,\nYo nunca he comido.\nAsí, señor mío,\nNo lo necesito.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-11",3,"Español\n—Bien, prenda del alma,\nA tus pies me rindo,\nY no es rendir poco,\nRendirme a mí mismo.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-12",3,"Colla\n—Esa es mucha excusa,\nEs mucho delirio;\nVada usted a rendirse\nA los pies de un Cristo.",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-13",3,"Español\n—Y si el alma tiene\nUn precio infinito,\n¿Por qué me desprecias\nEste sacrificio?",3,1,0,37,"HERMOSA DEIDAD",7,5,"io",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0430-a-14",3,"Colla\n—El alma no quiero,\nPorque según veo,\nNo soy purgatorio,\nNi menos infierno.",3,1,0,37,"HERMOSA DEIDAD",7,5,"eo",-1,0,-1,0,298,298,"C-430-a","",0,"","","",0,0,0,[],""],["carrizo_salta-nc0431-01",3,"La torcaza es la pulpera,\nLa calandria es la cantora,\nY la acompaña la lora,\nEn esta dicha taberna.\nEl zorzal se queda afuera,\nY el chingolo y chiquichí\nPreguntan si hay chicha aquí\nY responde el payogasto,\nEsto estará muy buenazo,\nHagamos un zapateo...",3,1,0,37,"LA TORCAZA ES LA PULPERA",18,10,"eo",-1,0,-1,0,298,298,"C-431","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0432-01",3,"Le dijo un despilfarrado\nA una señora de manto:\n—Mi sol, mi luna, mi encanto,\n¿No necesita un criado?",3,1,0,37,"LE DIJO UN DESPILFARRADO",11,4,"ao",-1,0,-1,0,298,298,"C-432","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0432-02",3,"En un concurso de gente,\nEn una grande función,\nSe le atrevió un pobretón\nA una señora decente.\nPues él, sin tener presente,\nNi mirar que era un pelado,\nCon señas de enamorado,\nDe esta manera le habló:\n—El que la quiere soy yo.\nLe dijo el despilfarrado.",3,1,0,37,"LE DIJO UN DESPILFARRADO",18,10,"ao",14,0,-1,0,298,298,"C-432","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0432-03",3,"La señora sin hablar,\nElla formó la intención\nQue, en pasando la función,\nLo había de demandar,\nY sin prevenir su mal.\nSalió del templo entretanto,\nY entre con cólera y llanto\nEl Alcalde fué informado.\nAsí se atrevió un pelado\nA una señora de manto.",3,1,0,37,"LE DIJO UN DESPILFARRADO",18,10,"ao",-1,0,-1,0,299,299,"C-432","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0432-04",3,"Llamó el juez al agresor,\nA preguntarle por qué\nAtrevido en faltar fué\nA una señora de honor.\nContesta el pobre: —Señor,\nDe su pregunta me espanto,\nElla hace pecar a un santo\nY a cualquier amante aflige,\nLa vi tan linda y le dije:\n—¡Mi sol, mi luna y mi encanto!",3,1,0,37,"LE DIJO UN DESPILFARRADO",18,10,"ao",30,0,-1,0,299,299,"C-432","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0432-05",3,"Le dice el juez: —Mi señora,\nCorre de su natural,\nQue si este pobre hizo mal,\nDispénsele por ahora,\nEl en nada la desdora,\nNo es sino un adelantado,\nEso deje que ha pasado,\nPerdónele a un imprudente.\nY ahora que ya no hay gente:\n¿No necesita un criado?",3,1,0,37,"LE DIJO UN DESPILFARRADO",18,10,"ao",14,0,-1,0,299,299,"C-432","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0433-01",3,"Nadie gana más que el cura,\nEl logra los que se mueren,\nPara el cura no hay mal año,\nHaiga la plaga que hubiere.",3,1,0,37,"NADIE GANA MAS QUE EL CURA",0,4,"ee",-1,0,-1,0,299,299,"C-433","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0433-02",3,"El cura no sabe arar,\nY menos uncir un buey,\nPero por su justa ley,\nEl cosecha sin sembrar.\nPues para salir a andar,\nEl poco o nada se apura;\nTiene su renta segura\nSin andarse molestando.\nEn la sombra, descansando,\nNadie gana más que el cura.",3,1,0,37,"NADIE GANA MAS QUE EL CURA",18,10,"ua",17,0,-1,0,299,299,"C-433","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0433-03",3,"El tiene cabras y ovejas,\nBueyes, vacas y dinero,\nY según esto yo infiero,\nQue hace muy mal si se queja,\nEl logra la gente vieja,\nSea de la edad que fuere.\nQue pagen es lo que quiere\nEl entierro de los muertos,\nSean rengos, mancos o tuertos,\nEl logra los que se mueren.",3,1,0,37,"NADIE GANA MAS QUE EL CURA",18,10,"ee",-1,0,-1,0,299,299,"C-433","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0433-04",3,"De la Trinidad del cielo,\nEl es la cuarta persona;\nEs gloriosa su corona,\nSirve a todos con buen celo;\nPara su mayor consuelo,\nEl sabrá su desengaño.\nPara él no hay plaga ni daño,\nEl por el orden que tiene,\nGana plata, gana bienes,\nPara el cura no hay mal año.",3,1,0,37,"NADIE GANA MAS QUE EL CURA",18,10,"ao",40,0,-1,0,299,299,"C-433","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0433-05",3,"Si el diezmo va con aumento,\nSon ganancias para él sólo.\nEl gana plata en los olios,\nTambién en los casamientos;\nPara él no hay impedimento\nPara vender las mujeres.\nTodas las que les pidieres\nVa vendiendo y entregando;\nTodo el año está ganando,\nHaiga la plaga que hubiere.",3,1,0,37,"NADIE GANA MAS QUE EL CURA",18,10,"ee",-1,0,-1,0,299,299,"C-433","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0434-01",3,"No me quisiera morir\nSin hacer mi testamento,\nPor si acaso en algún tiempo\nMis hijos quieran reñir.",3,1,0,37,"NO ME QUISIERA MORIR",5,4,"i",157,0,-1,0,299,299,"C-434","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0434-02",3,"Son muchos mis herederos\nY asimismo mis caudales,\nPorque tengo en animales\nUn chivato y un carnero.\nUn jumento sillonero\nEn que me sé divertir,\nAunque viejo ha de servir,\nAunque rengo, manco y tuerto,\nY antes de arreglar todo esto\nNo me quisiera morir.",3,1,0,37,"NO ME QUISIERA MORIR",18,10,"i",157,0,-1,0,299,299,"C-434","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0434-03",3,"Y en lo que hace a mis prendas,\nTengo un freno sin barbada,\nUn recao sin cabezada,\nDe chivo un cuero de jerga,\nUn torzal de que hago riendas\nCuando ensillo mi jumento;\nMis estribos son de tiento:\nSepan todos los presentes,\nPor si muero de repente\nSin hacer mi testamento.",3,1,0,37,"NO ME QUISIERA MORIR",18,10,"eo",94,0,-1,0,300,300,"C-434","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0434-04",3,"Ahora, lo que hace en ropa,\nTengo un pantalón mezclilla,\nAujeriado en la rodilla;\nTengo un sombrero sin copa,\nTambién tengo un par de botas,\nBien remachadas con tiento,\nSon de canilla i jumento,\nSepan todos mis amigos,\nPara que me sean testigos\nPor si acaso, en algún tiempo.",3,1,0,37,"NO ME QUISIERA MORIR",18,10,"eo",-1,0,-1,0,300,300,"C-434","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0434-05",3,"Ahora de servicio i mesa,\nTodo junto lo relato,\nTengo la mitad de un plato,\nY un retazo i servilleta.\nTengo una cuchara vieja,\nNo es palo de guayabil,\nNi menos de cuchupí,\nEs de corazón de higuera,\nPero puede ser por ella\nMis hijos quieran reñir.",3,1,0,37,"NO ME QUISIERA MORIR",18,10,"i",-1,0,-1,0,300,300,"C-434","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0435-01",3,"¡Oh, valientes santiagueños!\nY no para trabajar.\nTodos son vagos y ociosos,\nHábiles para robar.",3,1,0,37,"¡OH; VALIENTES SANTIAGÜENOS!",0,4,"a",21,0,-1,0,300,300,"C-435","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0435-02",3,"Ellos son amigos leales\nDe quien los va a visitar,\nHasta hacerlo descuidar\nDe las prendas y de los reales;\nEllos se muestran afables,\nCon el rostro bien risueño,\nCon mucho valor y empeño\nLe entregan la voluntad.\n¡Qué arbitrios para robar!\n¡Oh, valientes santiagueños!",3,1,0,37,"¡OH; VALIENTES SANTIAGÜENOS!",18,10,"eo",-1,0,-1,0,300,300,"C-435","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0435-03",3,"El cuidado que ellos tienen\nEs que pase un panadero,\nY más si cruza un resero,\nMucho más bien les conviene.\nLuego dicen, éste tiene,\nLe busquemos la amistad;\nLo comienzan a saquiar,\nPasan por el ensillado.\n¡Qué hombres de tantos cuidados!\nY no para trabajar.",3,1,0,37,"¡OH; VALIENTES SANTIAGÜENOS!",18,10,"a",21,0,-1,0,300,300,"C-435","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0435-04",3,"Ellos tienden sus carpetas\nY se sientan a jugar,\nPorque para macanear\nJamás a nadie respetan.\nAllá todos se presentan\nHalagüeños y amorosos,\nDiciendo: somos rumbosos\nY tenemos resistencia.\nEn Dios y en buena conciencia,\nTodos son vagos y ociosos.",3,1,0,37,"¡OH; VALIENTES SANTIAGÜENOS!",18,10,"oo",186,0,-1,0,300,301,"C-435","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0435-05",3,"Se llenan de compromisos,\nSi llega algún forastero,\nPonen todos sus oficios\nPor ver si lleva dinero.\nEmpiezan por el primero,\nDicen: le hemos de ganar,\nAsí lo hemos de pelar\nPara que nos haga caso.\n¡Qué picaros bribonazos!\nHábiles para robar.",3,1,0,37,"¡OH; VALIENTES SANTIAGÜENOS!",18,10,"a",21,0,-1,0,301,301,"C-435","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0436-01",3,"Ordeno que cuando muera\nNo me lloren los parientes,\nLloremén los alambiques\nY las pipas de aguardiente.",3,1,0,37,"ORDENO QUE CUANDO MUERA",0,4,"ee",-1,0,-1,0,301,301,"C-436","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0436-02",3,"Cuando muera un libertino,\n¿Quién podrá sentir por él?\nSólo el té, sólo el café\nQue se toma en los pocillos.\nComo soy el más caudillo,\nEn todo arte calavera,\nVoy a formar una hoguera\nPara que sirva de ejemplo,\nAsí advirtiendo con tiempo,\nOrdeno que cuando muera.",3,1,0,37,"ORDENO QUE CUANDO MUERA",18,10,"ea",44,0,-1,0,301,301,"C-436","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0436-03",3,"Lloren los cañaverales\nEl día que fallezca yo.\nLloremén con llanto atroz\nLos vasos y los cristales,\nTodos estos materiales\nEn que se pone aguardiente.\nEllos serán mis dolientes\nCuando yo muera algún día,\nLloremén las pulperías,\nNo me lloren los parientes.",3,1,0,37,"ORDENO QUE CUANDO MUERA",18,10,"ee",252,0,-1,0,301,301,"C-436","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0436-04",3,"Barriles y botijuelas\nSerán las que me hagan duelo,\nSe quedarán por los suelos\nLas copas y las botellas.\nLas jarras y las calderas\nLlorarán con llanto triste;\nLos embudos y los chifles\nNo hallarán jamás consuelo.\nLloren los alambiqueros,\nLloremén los alambiques.",3,1,0,37,"ORDENO QUE CUANDO MUERA",18,10,"ie",-1,0,-1,0,301,301,"C-436","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0436-05",3,"Lloremén las damajuanas,\nPor ser muebles de mi oficio,\nTodos estos artificios\nEn que se hace la mañana,\nHagan sufragio de mi alma\nCon un naipe en de repente,\nMedio copando en caliente,\nComo que se juega un rato,\nSe desocupan los frascos\nY las pipas de aguardiente.",3,1,0,37,"ORDENO QUE CUANDO MUERA",18,10,"ee",15,0,-1,0,301,301,"C-436","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0437-01",3,"Peno por una Susana,\nPadezco por una Anita,\nSuspiro por una Rita,\nY muero por una Juana.",3,1,0,37,"PENO POR UNA SUSANA",11,4,"aa",4,0,-1,0,301,301,"C-437","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0437-02",3,"La Lucrecia me da pena\nTan sólo de oirla nombrar,\nPor celos con la Pilar,\nOdio me tiene la Elena.\nSi miro a la Magdalena,\nSe enoja la Cayetana,\nPara ver a la Juliana\nHe de engañar a la Amelia,\nLo mismo que por la Delia\nPeno por una Susana.",3,1,0,37,"PENO POR UNA SUSANA",18,10,"aa",4,0,-1,0,301,301,"C-437","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0437-03",3,"Me acaricia la Tadea\nY me lisonjea la Ignacia,\nNo permite la Anastasia,\nHable con la Dorotea.\nMucho más que la Matea\nMe gusta una Margarita,\nY la Petrona le quita,\nA mi vida la existencia.\nY con mayor complacencia\nPadezco por una Anita.",3,1,0,37,"PENO POR UNA SUSANA",18,10,"ia",50,0,-1,0,301,302,"C-437","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0437-04",3,"Si abandono a la Sofía,\nDaré en el gusto a la Rosa.\nSólo por la Sinforosa\nPerdonaré a Rosalía.\nSi me olvidase María,\nIré donde la Benita,\nY en caso que no me admita,\nO me dijera que no,\nLe haré saber, que yo\nSuspiro por una Rita,",3,1,0,37,"PENO POR UNA SUSANA",18,10,"ia",50,0,-1,0,302,302,"C-437","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0437-05",3,"Dejar a la Carolina\nNo me place, por la Antonia,\nSe morirá la Polonia\nSi me vé con la Martina;\nA más que la Serafina\nSabe lo que es la Fabiana,",3,1,0,37,"PENO POR UNA SUSANA",9,6,"aa",-1,0,-1,0,302,302,"C-437","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0438-02",3,"Si ella cambiara de vida,\nY llorando me rogara,\nLa culpa le perdonara,\nSi viniera arrepentida.\nMás, como es tan fementida,\nY de un falso proceder,\nMuy pronto he venido a ver,\nClaramente en sus engaños,\nQue aunque pasen dos mil años,\nYa no la vuelvo a querer.",3,1,0,37,"",18,10,"e",20,0,-1,0,302,302,"C-438","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0438-03",3,"Si ella me manifestara\nQue a mí me quiso infinito,\nLe perdonara el delito\nY de nuevo la adorara.\nPero no, si yo la amara,\nTuviera que blasfemar.\nAsí, más vale dejar\nQue esté de mi amor ajena,\nHe de tener mayor pena\nQue si la vuelvo a adorar.",3,1,0,37,"",18,10,"a",21,0,-1,0,302,302,"C-438","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0438-04",3,"Si se ofreciera rendida,\nJamás a hacerme traición,\nLe entregara el corazón,\nEl alma y toda mi vida,\nPero sin ser conocida\nEn su falso proceder.\nAsí más vale querer\nOtra más firme y constante,\nQue si vuelvo a ser su amante,\nMe ha de volver a ofender.",3,1,0,37,"PRENDA QUE A MI ME OFENDIÓ",18,10,"e",20,0,-1,0,302,302,"C-438","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0438-05",3,"Prenda que a mi me ofendió,\nYa no la vuelvo a querer,\nQue si la vuelvo a adorar,\nMe ha de volver a ofender.",3,1,0,37,"",0,4,"e",20,0,-1,0,302,302,"C-438","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0438-07",3,"Prenda que a mí me ofendió,\nYo no la pienso buscar,\nQue si la vuelvo a querer,\nMe ha de volver a engañar.",3,1,0,37,"PRENDA QUE A MI ME OFENDIÓ",0,4,"a",21,0,-1,0,302,302,"C-438","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0438-10",3,"?i ella me representara\nDe que me quiso infinito,\nLe perdonara el delito,\nY de nuevo la adorara.\nPero no, si yo la amara,\nYa tendría de qué hablar,\nPara esto es mejor dejar,\nQue de mi amor viva ajena,\nY para darle más penas,\nYo no la pienso buscar.",3,1,0,37,"PRENDA QUE A MI ME OFENDIÓ",18,10,"a",21,0,-1,0,303,303,"C-438","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0438-11",3,"Si me jurara rendida,\nNo hacerme jamás traición,\nLe diera mi corazón,\nMi alma y toda mi vida,\nPero no, es homicida,\nY es de falso proceder,\nPara esto es mejor querer\nOtra más fiel y constante,\nQue si llego a ser un amante\nMe ha de volver a ofender.",3,1,0,37,"PRENDA QUE A MI ME OFENDIÓ",18,10,"e",20,0,-1,0,303,303,"C-438","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0439-01",3,"Quiero decir y contar\nDe la viuda afortunada,\nEl jueves murió el marido,\nY el viernes ya fué casada.",3,1,0,37,"QUIERO DECIR Y CONTAR",0,4,"aa",49,0,-1,0,303,303,"C-439","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0439-02",3,"Me encargó si se casaba,\nQue me case con usted,\nQue le cuide sus hijitos\nComo diantes solía ser.",3,1,0,37,"QUIERO DECIR Y CONTAR",0,4,"e",-1,0,-1,0,303,303,"C-439","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-01",3,"Rendido, vienes marido,\nRendido de trabajar,\nTienes la cama tendida,\nBien te puedes acostar.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"a",21,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-02",3,"Mi marido se ha enfermado,\nYo estoy en la cabecera,\nCon el rosario en las manos,\nRogando a Dios que se muera.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"ea",44,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-03",3,"Ya se ha muerto mi marido,\nYa se ha muerto el majadero,\nYa no tengo quien me diga:\n—Anda pronto y vuelve luego.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"eo",-1,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-04",3,"Ya lo llevan a enterrar,\nCon mucho acompañamiento,\nYo voy por bajo de cuerda,\nTratando de casamiento.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"eo",94,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-05",3,"Yo me largué por la calle\nEn busca de un albañil,\nA hacerle echar cal y piedra,\nPor lo que pueda salir.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"i",-1,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0440-06",3,"Aquí se acabó este verso\nDe la viuda afortunada,\nEl lunes murió el marido,\nY el martes ya fué casada.",3,1,0,37,"RENDIDO, VIENES MARIDO",0,4,"aa",49,0,-1,0,303,303,"C-440","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0442-01",3,"Señores, les contaré,\nYa que se ofrece ocasión,\nYo con toda mi pasión,\nA una vieja enamoré.\nRendido me le ofrecí,\nLe dije: mire, señora,\nEs constante quien la adora\nY a sus pies está rendido.\nSolamente dirigido\nPor gozar de su hermosura.",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"ua",-1,0,-1,0,304,304,"C-442","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0442-02",3,"¡Mire, qué feliz mañana,\nDijo la vieja, había sido,\nOh, mozo, en cuanto ha venido\nA pretender a una anciana!\n¡Mozo, yo para jarana\nYa no me encuentro capaz,\nPorque cada día más,\nSe me aumenta la vejez!\n¿O por burlarse tal vez,\nHoy tan comedido está?",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"a",-1,0,-1,0,304,304,"C-442","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0442-03",3,"—Le dije: estoy de tal suerte,\nA vuestras plantas rendido,\nQue habrá del cielo venido\nEl designio de quererte.\n¡Señora,, dadme la muerte\nSi me has de decir que no,\nY si es que merezco yo,\nSeñora, dame un consuelo,\nNo me niegues vuestro cielo,\nNo hagas infeliz mi amor!",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"o",-1,0,-1,0,304,304,"C-442","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0442-04",3,"—No puedo servirte, hijito,\nMe dijo la vieja entonces,\nPorque cuando de mí goces,\nMe has de perder el respeto,\nTodos dirán, por supuesto:\n¡Quién pensara que fulana,\nSiendo una señora anciana,\nHabía de tener amigos!\nAún por eso no me animo.\nYo no sé andar con mañana.",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"aa",4,0,-1,0,304,304,"C-442","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0442-05",3,"Entonces pegué un suspiro,\nCasi el alma me salió,\nY la vieja contestó:\n—¡Aguárdese, compañero!\nEntonces le dije: muero,\nSeñora, por vuestro amor,\nPor Dios, hágame el favor,\nAntes que pierda el sentido,\nSeré su dueño querido,\nNo me trate con rigor.",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"o",72,0,-1,0,304,304,"C-442","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0442-06",3,"—Pero mozo ¿qué no vé,\nMe dijo la vieja, al fin,\nQue no te puedo servir\nMi imposible es la vejez?\nVamos a ver si tú puedes\nVolverme a la juventud,\nEntonces con prontitud,\nSeré yo tu dueña amada,\nSin temor de ser burlada\nNi de perder mi virtud.",3,1,0,37,"SEÑORES, LES CONTARE",18,10,"u",278,0,-1,0,304,304,"C-442","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0443-01",3,"Señores, yo soy de aquí,\nPero vivo Tahuatahua,\nMás, existo en Aconcagua,\nY hoy me veo en Guayaquil.\nAllá me acuesto a dormir\nEn la cuesta de Aricón.\nMi sueño no lleva fin,",3,1,0,37,"SEÑORES, YO SOY DE AQUÍ",4,7,"i",-1,0,-1,0,304,304,"C-443","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-01",3,"Te daré porque me quieras,\nUn pedazo i soncoiyana,\nTambién un trapo amarillo,\nY una sortija de iguana.",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",0,4,"aa",4,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-02",3,"De las prendas que yo tengo,\nTodas le voy a avisar:\nUn caballo regular,\nQue es tuerto, lunanco y rengo,\nNi por oro no lo vendo,\nAunque manco, es de carrera,\nCorre cuadras, corre leguas,\nComiendo no se fatiga,\nAunque es de toda mi estima,\nTe daré porque me quieras.",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",18,10,"ea",-1,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-03",3,"Para todo el año entero,\nVoy a abastecer tu casa,\nVoy a carnear por la grasa,\nAl padre de los carneros.\nDe la chuspa harás salero,\nDel cuerpo una hermosa cama,\nDonde vivas muy ufana.\nTodo esto te he de poner,\nA toda hora has de comer\nUn pedazo i soncoiyana.",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",18,10,"aa",4,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-04",3,"Tres varas de barracán\nTe daré para tu traje,\nCon eso, con más coraje,\nPuedas salir a bailar;",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",5,4,"a",-1,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-05",3,"Todos te han de festejar\nCodiciándote el vestido,\nQue aunque el género es sencillo,\nPero te resguarda el hielo,\nY si no tienes pañuelo,\nTe daré un trapo amarillo.",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",9,6,"io",228,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0445-06",3,"Si tú me das tu palabra,\nYo he de ser tu fino esclavo,\nTengo un cuchillo sin cabo,\nY un pellón de cuero i cabra,\nQue toda mi dicha labra.\nTengo unas jergas de lana\nQue no tienen parte sana,\nMe cuesta para ensillar,\nTodo esto te voy a dar,\nY una sortija de iguana.",3,1,0,37,"TE DARÉ PORQUE ME QUIERAS",18,10,"aa",4,0,-1,0,306,306,"C-445","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0446-01",3,"¡Te quise, ya no te quiero,\nY así juro jamás verte,\nTu pecho es un lisonjero,\nPrometo ya no quererte,\nPero sí, por tí me muero!",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"eo",38,0,-1,0,306,306,"C-446","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0446-02",3,"Bien conozco tu indolencia,\nNo te volveré a querer,\nFavor me hace con tu ausencia,\nCuando no te puedo ver,\nDistante de mi presencia.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"ea",46,0,-1,0,306,306,"C-446","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0446-03",3,"Mi pecho impaciente está,\nCon tu permanencia allá,\nMe dices que es tarde yá,\nY que ya te debes ir,\n¡No te vayas, ven acá!",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"a",9,0,-1,0,306,306,"C-446","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0446-04",3,"No te digo con soberbia,\nLo digo con humildad,\nPrimero he de lamer tierra\nQue volver a tu amistad.\nLo que digo es falsedad.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"a",16,0,-1,0,306,306,"C-446","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0446-05",3,"Bien puedes en un instante\nSepararte de mi lado,\nQue los que son inconstantes,\nA mí me causan enfado,\nMenos tú, que eres mi amante.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"ae",-1,0,-1,0,306,307,"C-446","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0446-06",3,"¡Adiós, adiós, que me voy\nA separarme de tí!\nQué bien enfadado estoy\nDesde el día en que te ví\n¡Tuyo soy y tuyo fuí!",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"i",23,0,-1,0,307,307,"C-446","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0446-a-01",3,"Te quise, ya no te quiero,\nAsí juro jamás verte\nTu pecho es un lisonjero,\nPrometo no más quererte,\nPero sí, por tí me muero.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"eo",38,0,-1,0,307,307,"C-446-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0446-a-02",3,"Bien conozco tu indolencia,\nNo te volveré a querer,\nFavor me haces con tu ausencia,\nPorque no te puedo ver\nDistante de mi presencia.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"ea",46,0,-1,0,307,307,"C-446-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0446-a-03",3,"No lo digo con soberbia,\nLo digo con humildad,\nPrimero lamberé tierra,\nQue volver a tu amistad;\nLo que digo es falsedad.",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"a",16,0,-1,0,307,307,"C-446-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0446-a-05",3,"Adiós, que yo ya me voy\nA separarme de tí,\nQue muy enfadado estoy,\nDesde el día en que te ví.\n¡Tuyo soy y tuyo fuí!",3,1,0,37,"TE QUISE, YA NO TE QUIERO",7,5,"i",23,0,-1,0,307,307,"C-446-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0447-02",3,"A causa de Casimira,\nSe fué mi amor a la maula,\nPor amores de una Paula,\nTristes mis ojos suspiran.\nY de ver que no me miran\nLos ojos de Liberata,\nMuy sin piedad me maltrata,\nLa celosa de mi Antonia,\nMe hace sufrir la Polonia,\nY una Bárbara me mata.",3,1,0,37,"l NA BARBARA ME MATA",18,10,"aa",74,0,-1,0,307,307,"C-447","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0447-03",3,"Injustamente una Juana\nMe traspasa el corazón,\nY me niega la pasión,\nUna Manuela tirana.\nSale Josefa y Juliana\nCon un candado y cadena,\nDiciéndole a Magdalena,\nQue Rosa me ha dado cita,\nTambién se me enoja Rita\nY una Angela me da pena.",3,1,0,37,"l NA BARBARA ME MATA",18,10,"ea",59,0,-1,0,307,307,"C-447","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0447-04",3,"La Toribia y la Justina,\nMe salen con sus enojos,\nArrancándome los ojos,\nSale la Marta y Rufina.\nVeneno, una Catalina\nMe da para que no la hable,\nAhorcándome con un cable,\nMe tiene una hermosa Luisa,\nPor eso tanta ojeriza\nMe tiene una Pepa amable.",3,1,0,37,"l NA BARBARA ME MATA",18,10,"ae",322,0,-1,0,307,307,"C-447","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0447-a-01",3,"Causa de una Casimira,\nPuse mi amor en tal jaula,\nPor amores de una Paula,\nTriste mi pecho suspira.",3,1,0,37,"CAUSA DE UNA CASIMIRA",11,4,"ia",372,0,-1,0,307,307,"C-447-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0447-a-02",3,"Y, al ver que no me mira\nNi Juana y ni Liberata,\nUna Segunda me encanta,\nMe da pesar una Antonia,\nCecilia me da ponzoña,\nLa Barbarita me mata.",3,1,0,37,"CAUSA DE UNA CASIMIRA",9,6,"aa",-1,0,-1,0,308,308,"C-447-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0447-a-03",3,"Injustamente, una Juana\nMe traspasa el corazón,\nY me aciega una pasión,\nDe una Manuela tirana.\nSalen Josefa y Juliana\nCon candados y cadenas,\nDiciéndole a Magdalena,\nQue aprontara su cuchillo,\nY con todos sus tornillos,\nAngelita me da pena.",3,1,0,37,"CAUSA DE UNA CASIMIRA",18,10,"ea",59,0,-1,0,308,308,"C-447-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0447-a-04",3,"También Andrea y Rufina\nMe piden que no desmaye,\nY me miran en la calle,\nOjos de una hermosa Luisa.\nUna Clotilde me hechiza,\nY una Pepa me fascina;\nLa Clara y la Bertolina\nMe tienen a trás perder,\nPero mi amor ha de ser\nPor la Rosa y la Joaquina.",3,1,0,37,"CAUSA DE UNA CASIMIRA",18,10,"ia",11,0,-1,0,308,308,"C-447-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0448-01",3,"Una chancha muy comadre,\nSe casó con un zorrino,\nY sirvieron de padrino,\nLa paloma y el zorzal.\nUn hermoso pavorreal\nDe cura hizo en la ocasión,\nSacristán fué un lechuzón.\nYo reventaba de risa\nAl ver la chancha en camisa\nY al zorrino en camisón.",3,1,0,37,"UNA CHANCHA MUY COMADRE",18,10,"o",31,0,-1,0,308,308,"C-448","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0448-02",3,"Esa vez concurrí al baile,\nMe invitaron al festín,\nTocaba el burro el violín,\nLa flauta una cucaracha,\nLa guitarra una vizcacha\nY el ratón el mandolín.",3,1,0,37,"UNA CHANCHA MUY COMADRE",9,6,"i",211,0,-1,0,308,308,"C-448","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0449-01",3,"Una mujer me contaba,\nDiciendo que me quería,\nMe dijo que la estimara,\nQue ella bien me pagaría.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"ia",0,0,-1,0,308,308,"C-449","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0449-02",3,"Me pedía una muda i ropa\nY un par de pesos al día,\nComo mozo pretendiente,\nSacaba de ande no había.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"ia",0,0,-1,0,308,308,"C-449","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0449-03",3,"También me pedía botines,\nQue han de ser de medio punto,\nComo mozo pretendiente,\nLe traje tres pares juntos.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"uo",-1,0,-1,0,308,308,"C-449","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0449-04",3,"También me pedía unas medias,\nQue habían de ser de Bruselas,\nComo mozo pretendiente,\nLe traje medias de seda.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"ea",-1,0,-1,0,308,308,"C-449","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0449-05",3,"También me pedía enaguas\nQue habían de ser punteadas,\nComo mozo pretendiente.\nLe traje naguas bordadas.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"aa",282,0,-1,0,308,308,"C-449","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0449-06",3,"Andando caí a la cama,\nDe enfermo que me moría,\nA más de caer enfermo,\nMe llevó cuanto tenía.",3,1,0,37,"UNA MUJER ME CONTABA",0,4,"ia",0,0,-1,0,308,308,"C-449","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-01",3,"Jna vez yendo a gatiar,\nDe un golpe casi morí,\nLos perros me rompijiaron,\nHasta el alma me rompí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",0,4,"i",23,0,-1,0,309,309,"C-451","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-02",3,"Me levanté de mi cama,\nEn mi poncho arrebozado,\nEste se me había rasgado,\nPorque sin vinchas estaba,\nPresto, presto caminaba.\nPero me sentía anudar.\nMas, me volví a levantar,\nCorriendo por llegar luego,\nVoy me caigo dentro el fuego,\nUna vez llendo a gatiar.",3,1,0,37,"UNA VEZ YENDO A GATIAR",18,10,"a",21,0,-1,0,309,309,"C-451","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-03",3,"La noche estaba muy clara,\nMe entré y me gané a un rincón,\nVoy me golpeo en un horcón;\nMe paro y alzo la cara,\nVoy, me golpeo en una vara;\n¡Qué grande ruido metí!\nY dije: saldré de aquí,\nPorqué me voy a matar,\nVoy me golpeo en el umbral,\nDe un golpe casi morí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",18,10,"i",23,0,-1,0,309,309,"C-451","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-04",3,"Allí me quedé quejando,\nPues me dí el golpe en la oreja,\nMe sintió la diabla vieja,\nLos perros me salió echando.\nsalí disparando,\nPero luego me alcanzaron,\nEn el barro me voltearon,\nMe pusieron indecente,\nVaya, que completamente\nLos perros me rompijiaron.",3,1,0,37,"UNA VEZ YENDO A GATIAR",18,10,"ao",41,0,-1,0,309,309,"C-451","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-07",3,"A una acequia la brinqué.\nEn un tronco tropecé,\nDentro la acequia caí,\nSin poder salir de allí.\nYa no me valió el ser pillo,\nY con mi mismo cuchillo,\nHasta el alma me rompí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",4,7,"i",23,0,-1,0,309,309,"C-451","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-a-01",3,"Una vez yendo a gatiar,\nDe un golpe casi morí,\nLos perros me rompejiaron,\nY hasta el alma me rompí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",0,4,"i",23,0,-1,0,309,309,"C-451-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-a-02",3,"Una noche por costumbre\nMe levanté de mi cama,\nCon mi poncho arrebozado\nSobre que rompido estaba.\nComo estaba devanado,\nPresto, presto lo anudaba,\nLigerito caminaba,\nA ver si llegaba luego,\nVoy y piso dentro el fuego\nUna vez yendo a gatiar.",3,1,0,37,"UNA VEZ YENDO A GATIAR",18,10,"a",-1,0,-1,0,309,309,"C-451-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-a-03",3,"Llegué y me paré en la puerta,\nMe acomodé en un rincón,\nVoy, me golpío en un horcón,\nMe paré y alcé la cara,\nMe golpié en una vara,\nY grande ruido metí.\nDije, yo voy a salir,\nEsto es tirarme a matar,\nMe tropecé en un umbral,\nDel golpe casi morí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",18,10,"i",-1,0,-1,0,309,309,"C-451-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-a-05",3,"Agatas pude pararme,\nY mi camino agarré,\nHasta me determiné,\nQue una cequia había i pasar.",3,1,0,37,"UNA VEZ YENDO A GATIAR",5,4,"a",-1,0,-1,0,309,309,"C-451-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0451-a-07",3,"Yo me dispuse a brincar,\nDentro la acequia caí,\nYa no me valió ser pillo,\nPues con mi mismo cuchillo,\nHasta el alma me rompí.",3,1,0,37,"UNA VEZ YENDO A GATIAR",7,5,"i",23,0,-1,0,310,310,"C-451-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-01",3,"Un muerto dijo ¡Jesús!\nVn la puerta un camposanto,\nSi no me dan qué tomar,\nEsta noche los espanto.",3,1,0,37,"UN MUERTO DIJO jJESÚS!",0,4,"ao",30,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-02",3,"Este fué un hombre profundo,\nDe mucha sabiduría,\nDispuso salir un día,\nSolo, a recorrer el mundo.\nTomó por distintos rumbos,\nA la muerte le hizo ¡flus!\nY faltándole la luz,\nCuando se acortó la vida,\nAl ver el alma afligida,\nl'n muerto dijo: ¡Jesús!",3,1,0,37,"UN MUERTO DIJO jJESÚS!",18,10,"u",270,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-03",3,"Después que éste falleció,\nDel cielo llamó a la puerta,\nY Dios le exigió la cuenta\nDesde el día en que nació.\nLlorosa su alma pidió\nLe perdonase algún tanto.",3,1,0,37,"UN MUERTO DIJO jJESÚS!",9,6,"ao",-1,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-04",3,"Dios lo colocó en un campo,\nDonde purgue sus maldades,\nLloró sus iniquidades\nEn la puerta un camposanto.",3,1,0,37,"UN MUERTO DIJO jJESÚS!",5,4,"ao",-1,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-05",3,"Cuando Dios le perdonó,\nEmpezó el alma a pensar,\nY se comenzó a acordar,\nDe aquellos tiempos pasados.\nMe salvé del condenado,\nY ahora debo cobrar,\nMi botella y mi caudal,\nQue dejé en distintos puntos,\nYo quemaré los dijuntos,\nSi no me dan qué tomar.",3,1,0,37,"UN MUERTO DIJO jJESÚS!",18,10,"a",-1,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0453-06",3,"El alma se fué a un convento,\nGolpeó la puerta al portero:\n—Yo vengo por el dinero\nQue me lo tienen adentro.\nNunca han de vivir contentos,\nDijo con amargo llanto,\nPorque la plata es mi encanto,\nMe la tienen que entregar,\nSi no me la quieren dar,\nEsta noche los espanto.",3,1,0,37,"UN MUERTO DIJO jJESÚS!",18,10,"ao",30,0,-1,0,311,311,"C-453","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0454-01",3,"Voy a contar lo que pasa\nCon los que son de otra parte,\nDe esos que calientan agua,\nPara que otros tomen mate.",3,1,0,37,"VOY A CONTAR LO QUE PASA",0,4,"ae",-1,0,-1,0,311,311,"C-454","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0454-02",3,"Muchos hay que se costean,\nTragándose las distancias,\nPor ver de calmar sus ansias,\nDe un amor que ellos desean.\nMas en vano se recrean\nY se vienen de su casa.\nPor comer pan de otra masa\nDejan el horno encendido,\nMás, para ser entendido,\nVoy a contar lo 'que pasa.",3,1,0,37,"VOY A CONTAR LO QUE PASA",18,10,"aa",123,0,-1,0,311,312,"C-454","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0454-03",3,"Hay muchos recién llegados,\nNo saben enamorar,\nY sirven para estorbar\nA dos amantes formados,\nY con razones armados,\nEl fuego encienden con arte,\nY antes que el calor se aparte,\nOtro aprovecha el fogón,\nEsto hacen sin compasión\nCon los que son de otra parte.",3,1,0,37,"VOY A CONTAR LO QUE PASA",18,10,"ae",8,0,-1,0,312,312,"C-454","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0454-04",3,"Cuando una niña se alegra,\nLuego les parece sueño,\nQue han de lograr con empeño,\nDe una pasión por entera.\nY ya la creen verdadera,\nY engañaos tienen por gala,\nEchan carbón a la fragua\nY hacen hervir los calderos;\nReímos los forasteros,\nDe esos que calientan agua.",3,1,0,37,"VOY A CONTAR LO QUE PASA",18,10,"aa",383,0,-1,0,312,312,"C-454","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0454-05",3,"Antes de tener respuesta,\nYa empiezan a regalar,\nY la otra empieza a tragar\nLo que a ese zonzo le cuesta.\nNo gastes en tu protesta,\nY de este empeño dejate,\nNo hagas tanto disparate,\nEn tu pasión tan acerba.\nCompras azúcar y yerba\nPara que otros tomen mate.",3,1,0,37,"VOY A CONTAR LO QUE PASA",18,10,"ae",384,0,-1,0,312,312,"C-454","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0455-04",3,"Ahí viene un chiquillo\nQue trae una carta\nDel Continental;\nDéjenlo que venga,\nDéjenlo que pase,\nQue ha de ser regalo,\nQue me hace Marcial.",3,1,0,37,"YA DENTRO DE POCO",4,7,"a",1,0,-1,0,312,312,"C-455","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0456-01",3,"Yo me pensaba casar,\nPero siento un gran disgusto,\nPorque mujer a mi gusto,\nBusco y no puedo encontrar.\nEl llegarme a desposar\nCon cualquiera, no me place,\nPues saldrá mal el enlace,\nY sufriré sinsabores.\nPensándolo bien, señores,\nEs mejor que no me case.",3,1,0,37,"YO ME PENSABA CASAR",18,10,"ae",385,0,-1,0,313,313,"C-456","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0456-02",3,"Si es gorda, es una ballena\nQue infunde a todos respeto,\nSi flaca, es un esqueleto\nQue da compasión y pena.\nY si es de cara morena,\nEs un rostro mal lavado:\nSi es blanca, que se ha pintado,\nTodo el mundo se reirá,\nPor eso, a decir verdad,\nEs mejor que no me case.",3,1,0,37,"YO ME PENSABA CASAR",18,10,"ae",-1,0,-1,0,313,313,"C-456","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0457-01",3,"Yo me quisiera casar,\nComo todos los demás,\nPero mujer de mi gusto,\nBusco y no puedo encontrar.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"a",-1,0,-1,0,313,313,"C-457","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0457-02",3,"Que si es negra, es noche obscura\nQue no se puede mirar,\nQue si es blanca, es compostura\nDe carmín y solimán.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"a",-1,0,-1,0,313,313,"C-457","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0457-03",3,"Si chiquita, es un juguete,\nNo se sabe dónde está,\nQue si es grande, es un fantasma.\nQue asusta por donde va.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"a",9,0,-1,0,313,313,"C-457","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0457-04",3,"Y si es rica, cacarea\nSu fortuna sin cesar,\nSi pobre, es una pelada\nQue no tiene qué gastar.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"a",21,0,-1,0,313,313,"C-457","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0457-05",3,"Si ella es flaca, es un pescado,\nQue es sin gusto ni sabor,\nY si es gorda, es una estufa,\nNo se puede de calor.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"o",72,0,-1,0,313,313,"C-457","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0457-06",3,"Por todo esto, amigos míos,\nYo no me quiero casar,\nSólo lo haría si supiera\nQue pronto había de enviudar.",3,1,0,37,"YO ME QUISIERA CASAR",0,4,"a",21,0,-1,0,313,313,"C-457","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0458-01",3,"Yo soy como el gavilán,\nQue vuela con ligereza,\nY con la mayor destreza,\nSabe las aves cazar.\nTambién en sagacidad,\nNo hay pájaro que le iguale,\nPorque es más diestro que la ave,\nQue en el cazar se ejercita,\nY hoy, por una palomita,\nDoy vuelta y nadie lo sabe.",3,1,0,37,"YO SOY COMO EL GAVILÁN",18,10,"ae",131,0,-1,0,313,314,"C-458","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0458-02",3,"Pero si esta palomita\nLa encontrara entretenida,\nO si se encuentra dormida,\nAhí le preparo la muerte,\nSin ofenderle la vida.\nSi otro gavilán viniese\nPara interrumpir mi tiro,\nYo con aire desmedido,\nRemonto el vuelo y me bajo,\nPara conocer su giro.",3,1,0,37,"YO SOY COMO EL GAVILÁN",18,10,"io",-1,0,-1,0,314,314,"C-458","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0458-03",3,"Hay pajarillos del arte,\nQue cazan adentro el nido.\nCazan, pero son sentidos,\nPresos al instante son.\nYo, por la misma razón,\nMe reservo de los ruidos,\nPara lograr un buen tiro\nSi es arisca la paloma,\nAl bajar no hay que hacer ruido,\nNi al volar hay que hacer sombra.",3,1,0,37,"YO SOY COMO EL GAVILÁN",18,10,"oa",-1,0,-1,0,314,314,"C-458","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0459-01",3,"Yo soy halcón de virtud,\nQue cazo cuando tengo hambre,\nY nunca se echa de ver,\nEl daño que hago en las aves.",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",0,4,"ae",-1,0,-1,0,314,314,"C-459","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0459-02",3,"Soy astuto cazador,\nAl ave cuando está ufana,\nEntonces de mejor gana\nLe escapo un tiro de amor.\nMás, el ave de valor\nSe eleva con prontitud,\nY la dejo en su quietud,\nY me bajo a descansar.\nAl fin la llego a cazar;\nYo soy halcón de virtud.",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",18,10,"u",278,0,-1,0,314,314,"C-459","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0459-03",3,"Por fin, sin arma de chispa,\nPólvora ni munición,\nCazo con mi pretensión\nPor victoria o por conquista;\nJamás les pierdo la vista,",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",7,5,"ia",352,0,-1,0,314,314,"C-459","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0459-04",3,"El poder divino es grande,\n¿Es justo de que Dios mande\nDe su clemencia el perdón?\nYo no pierdo la ocasión,\nY cazo cuando tengo hambre.",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",7,5,"ae",-1,0,-1,0,314,314,"C-459","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0459-06",3,"Estando yo en mi retiro\nMe puse a considerar,\nDónde me fuera a cazar,\nPara no perder mi tiro.\nEn esta lidia me miro,\nComo todo el mundo sabe,\nSoy de mi aposento llave\nY de todo el mundo entero,\nCazo y como cuando quiero,\nSin hacer daño en las aves.",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",18,10,"ae",-1,0,-1,0,314,314,"C-459","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0459-a-01",3,"Yo soy halcón de virtud,\nSalgo de noche a cazar,\nTodo mi gusto es hallar\nA las aves en el nido.\nSi me sienten el volido,\nO les causo algún temor,\nLas persuado con amor,\nCon cariño y con destreza,\nY de ese modo hago presa\nDe las aves en el nido.",3,1,0,37,"YO SOY HALCÓN DE VIRTUD",18,10,"io",101,0,-1,0,314,314,"C-459-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0460-01",3,"Yo te quisiera querer,\nY tu madre no me deja.\nLa demonia de la vieja,\nQue en todo se ha de meter!",3,1,0,37,"YO TE QUISIERA QUERER",11,4,"e",20,0,-1,0,315,315,"C-460","",0,"","","",8,0,0,[],""],["carrizo_salta-nc0460-02",3,"Donde canta el chilicote,\nTe estaba esperando yo,\nDe allá tu madre salió,\nDel corral con un garrote;\nDe allí que me saca al trote,\nTanto que me hace correr,\nPero siempre he de volver\nAunque el corazón me late,\nY aún cuando a palos me mate,\nYo te quisiera querer.",3,1,0,37,"YO TE QUISIERA QUERER",18,10,"e",-1,0,-1,0,315,315,"C-460","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0460-03",3,"Un perro bayo amarillo,\nPegó un brinco y me agarró,\nMe rompió los calzoncillos,\nDentro del barro me voltió,\nMira, cómo, me arrastró,\nMás humilde que una oveja,\nNo tengo a quien dar mi queja,\nSi tan sólo a mí me toca,\n¡Agua se me hace la boca,\nY tu madre no me deja!",3,1,0,37,"YO TE QUISIERA QUERER",18,10,"ea",165,0,-1,0,315,315,"C-460","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0460-04",3,"Voy a buscar mis calzones,\nPor la noche en el chiquero,\nDe allí me saca el cabrero,\nLas nalgas a mordizcones.\nQue corran bien mis talones,\nSe enredan como madeja;\nEn tierra tan despareja,\nLarga se me hace la playa,\nY me sirve de muralla\nLa demonia de la vieja.",3,1,0,37,"YO TE QUISIERA QUERER",18,10,"ea",165,0,-1,0,315,315,"C-460","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0460-05",3,"La vida, prometo el dar,\nPero ha de ser si te gozo,\nPero primero en el pozo,\nA la vieja la he de echar;\nAl cabrero lo he de ahorcar,\nTodos han de perecer,\nEl perro amarillo ha i ser,\nPartido como un teja,\n¡Ahíjuna p u.., la vieja;\nQue en todo se ha de meter.",3,1,0,37,"YO TE QUISIERA QUERER",18,10,"e",20,0,-1,0,315,315,"C-460","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0461-01",3,"Yo tuve mi buen chiquero,\nPara encerrar mi majada,\nY tenía mis tres cabrillas,\nDe mi cabrita tostada.",3,1,0,37,"YO TUVE MI BUEN CHIQUERO",0,4,"aa",49,0,-1,0,315,315,"C-461","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0461-02",3,"Tenía mi buena majada,\nEntre cabrillas y cabras,\nY siempre multiplicadas,\nDe mi cabrita tostada.",3,1,0,37,"YO TUVE MI BUEN CHIQUERO",0,4,"aa",-1,0,-1,0,315,315,"C-461","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-01",3,"Al derredor de una mesa\nRústicamente labrada,\nSo ir.'-an algunos gauchos\nC:n ate nc ión ocupada.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",49,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-02",3,"Se oye al son de la guitarra,\nComo un sentido lamento,\nEs el Peñalva que canta,\nAl compás del instrumento.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",94,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-03",3,"Es el gaucho desgraciado,\nQue canta su desventura,\nEs el infeliz que cuenta,\nUna pasada aventura.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ua",17,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-04",3,"De pronto cesa en su canto,\nPorque ha roto una bordona,\nSe pone ahí nomás la anuda,\nY en cifra esta letra entona:",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"oa",7,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-05",3,"Empriestemén su atención,\nAmigos de un desgraciao,\nQuiero contarles cantando,\nLo que anoche me ha pasao.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",-1,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-06",3,"Muy triste me dejó el día,\nY ansí la noche me halló,\nNo sabía a qué echar la culpa,\nDel pesar que me agarró.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"o",2,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-07",3,"Esa noche me dió cita,\nLa que yo andaba queriendo,\nQuedé en ir cuando la vieja,\nEstuviera ya durmiendo.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",52,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-08",3,"A las doce, más o menos,\nDejé mi rancho y me fuí,\nY al llegar al Bulevar,\nParados, tres hombres ví.",3,1,0,38,"AL DERREDOR DE UNA MESA",3,4,"i",23,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-09",3,"Yo, atravesé la calle,\nSin hacer caso de nada,\nNo vía la hora de abrazar\nA mi prenda idolatrada.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",49,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-10",3,"Cuando llegué a sus umbrales,\nTan manso como una oveja,\nMe encontré de sopetón\nCon mi prenda y con la vieja.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ea",165,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-11",3,"La chica se lamentaba,\nDe un sustazo que tenía,\nY la vieja bien furiosa,\nA un tal Raña maldecía.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ia",0,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-12",3,"Mi señora y señorita,\nLes dije yo, ¿qué les pasa?\nY me responden llorando:\n—Raña nos rodea la casa.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",123,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-13",3,"¡Qué Raña ni qué demonio!\nCierren las puertas y entremos,\nY si este zonzo se mete,\nLos dos nos entenderemos.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",127,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-14",3,"Consideren mis amigos,\nLa rabia que me vendría,\nAl no poder conseguir,\nLo que yo me prometía.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ia",0,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-15",3,"Según les oí decir,\nEn el medio del dolor,\nEl tal Raña que nombraban\nEra un pícaro doctor.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"o",72,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-16",3,"Ya se metieron pa dentro\nLas dos, prendidas de mí,\nMe hicieron con repugnancia,\nChupar cerveza hasta aquí.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"i",23,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-17",3,"Estaban las dos allá,\nHablando mal del tal Raña,\nMe lo pintaban diciendo,\nQue tenía traza de araña.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",213,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-18",3,"Que parecía un comepiojo,\nMirándolo ansí de lejos,\nQue eran, sombrero y levita,\nDe una misma edad de viejos.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",149,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-19",3,"Que el levitón, en su cuerpo,\nGrandes desvelos pasaba,\nPorque a chupar, a su dueño,\nEn la noche acompañaba.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",28,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-20",3,"Tiene luto por camisa,\nDecían color de salchicha,\nMedio amarillento ya,\nCon las chorreras de chicha.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ia",357,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-21",3,"Lo único blanco en su ropa,\nEs puño, cuello y no más,\nPrendido el cuello en el luto,\nPor delante y por detrás.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"a",51,0,-1,0,317,317,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-23",3,"Que quién sabe ande hallaría\nUna corbata hilachenta,\nQue tal vez fueron hermanas,\nCon su levita grasienta.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ea",229,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-24",3,"No bien me dijeron esto,\nYa la ventana sonó,\nLas dos pegaron un grito,\nQue en el salón retumbó.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"o",2,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-25",3,"Los rempujes continuaban,\nCon más fuerza cada vez,\nYo la apretaba de adentro,\nSi no la voltian tal vez.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"e",-1,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-26",3,"Cesaron los rempujones,\nY la vieja, medio muerta\nMe pegó un grito, diciendo:\n—¡Ya han corrido pa la puerta!",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ea",267,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-27",3,"Abandoné la ventana,\nY pa la puerta puntié,\nY ya un rempujón pegaron,\nEn cuanto yo me llegué.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"e",77,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-28",3,"Si no llego tan a tiempo,\nSe me cuela algún malvao,\nY si quiere me degüella,\nPorque estuve desarmao.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",98,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-29",3,"¡Si es caballero el de adentro,\nPegó el grito uno de afuera,\nAbra sin miedo la puerta,\nNo tenga temor que muera!",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ea",-1,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-30",3,"En el modo de explicarse,\nAl que me habló, conocí\nQue era letrao y escribido,\nY sin temor se la abrí.",3,1,0,38,"AL DERREDOR DE UNA MESA",3,4,"i",23,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-31",3,"El primero que se entró,\nHabía sido el mismo Raña,\nLo que pasó de la puerta,\nMe tapó un olor a caña.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"aa",213,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-32",3,"Al entrar este individuo,\nCon sus bigotes de gato,\nVi que detrás asomaron\nDos cabezas de mulato.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",-1,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-33",3,"Y lo que entró el tal doctor,\nAllí se topó conmigo,\nYa se me quitó el sombrero,\nY me dió mano de amigo.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"io",106,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-34",3,"Tenía puesta una levita,\nComo un lazo de largura,\nY un revólver bajo de ella,\nAmarrao en la cintura.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ua",17,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-35",3,"Me dió una satisfacción,\nLo mismito que a un decente,\nY al fin me dijo: amigaso,\n¿No conoce a usted esta gente?",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ee",15,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-36",3,"Yo, dijo, venía resuelto,\nComo hombre que soy, severo,\nA la vieja a castigarla,\nY a la hija sacarle el cuero.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",38,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-37",3,"Pues me tienen, hasta aquí,\nDijo, y se tocó la oreja,\nY ya no puedo aguantarles,\nNo soy carnero ni oveja.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ea",165,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-38",3,"No me dijo qué habían hecho,\nTal vez no fuera muy bueno,\nTampoco le pregunté,\nQue no averiguo lo ajeno.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"eo",76,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-39",3,"—Que le agradezcan a Vd.\nSino tal vez yo las mato,\nPero en fin, me dijo, amigo,\nMás bien vamos pa mi cuarto.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",-1,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-40",3,"Mientras pasaba todo esto,\nLa chica estaba llorando,\nLa vieja, boca de tulpo,\nAl Raña estaba insultando.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",33,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-41",3,"Lo que nos íbamos, dijo,\nSeñalando a dos mulatos:\nCon estos iba a enseñarles,\nA que sean de malos tratos.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",386,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-42",3,"Y me llevó pa su cuarto,\nMaldiciendo su destino,\nDe entrada me convidó,\nUna copita de vino.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"io",199,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-43",3,"Ni pa mojarme el gargero,\nAlcanzó la copa aquella,\nPues había sido lo último\nQue había tenío la botella.",3,1,0,38,"AL DERREDOR DE UNA MESA",3,4,"ea",6,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-44",3,"Y no quise esperar más,\nY por fin me despedí,\nVolví otra vez a mi rancho,\nLo mismo quedé al salir.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"i",-1,0,-1,0,318,318,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-45",3,"Los tres hombres que antes vi,\nCuando llegué al Bulevar,\nEran Raña y los mulatos,\nQue me hicieron asustar.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"a",21,0,-1,0,319,319,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0462-46",3,"Esto, es, amigos queridos,\nLo que anoche me ha pasado,\nJamás en mis aventuras,\nHe sido tan desgraciado.",3,1,0,38,"AL DERREDOR DE UNA MESA",0,4,"ao",14,0,-1,0,319,319,"C-462","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-01",3,"Al derredor de un fogón,\nDonde ardían gruesos tizones,\nEstaban todos los peones,\nDe una estancia, a la oración.\nEstaban en diversión,\nContando cuentos graciosos,\nCuando llegaron dos mozos,\nY ¡buenas noches! dijeron,\n¡Buenas noches! respondieron;\nLos del fogón, cariñosos.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"oo",186,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-02",3,"—¿Habrá, señores, posada\nPara dos desconocidos?\nDijo uno de los venidos,\nParándose en la ramada.\n—Desensille, camarada,\nTiene pasto donde atar,\nY pásese a calentar,\nEn el fuego a nuestro lado,\nQue ya va estar el asado,\nSi nos gusta acompañar.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"a",21,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-03",3,"Uno de ellos al dar vuelta,\nAlumbrao por el fogón,\nMiramos que en un horcón,\nColgó una guitarra envuelta.\nTendremos ahora retreta,\nDijimos todos contentos,\nSi vienen con instrumento,\nCantores deben de ser.\nNos vamos a entretener,\nEn esta noche un momento.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"eo",94,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-04",3,"De los pingos se bajaron,\nY acomodaron sus bastos,\nEn seguida para el pasto,\nA que coman los llevaron;\nDe allí luego regresaron,\nY como estaba el asao,",3,1,0,38,"AL DERREDOR DE UN FOGÓN",9,6,"ao",-1,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-05",3,"En el suelo fué clavao,\nEntre todos lo rodeamos,\nComo con ganas cargamos,\nFué al momento devorao.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",11,4,"ao",-1,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-06",3,"Al acabar la comida,\nFué servilleta un ancoche,\nY para acortar la noche,\nY pasarla entretenida,\nPedimos por despedida,\nAl paisano, que un momento\nLo templara al instrumento,\nY que una vez igualado,\nAcompañe al encordao,\nCon algún triste lamento.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"eo",94,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-07",3,"El mozo había sio corriente,\nY no se hizo de rogar,\nFué la envuelta a descolgar,\nCon voluntad sorprendente.\nDe allí se vino sonriente,\nCon la guitarra en la mano,\nY con el otro paisano,\nA un banco se acomodaron.\nY al instrumento igualaron,\nComo cantores baquianos.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"ao",-1,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-08",3,"Cuando ya la hubo igualao\nQuizo probarla primero,\nSe hizo un preludio ligero,\nKecorriendo el encordao,\nHizo un lindo bordoneo,\nY al acabarlo rasgó.\nEn seguida respiró,\nY compuso la garganta,\nY con una voz que encanta,\nDe esta manera empezó:",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"o",2,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-09",3,"—Señores, voy a cantar,\nYa que Vds. lo desean,\nMas quiero que también sean\nPrudentes al escuchar,\nY que sepan disculpar,\nSi incurro en cualquier torpeza,\nPues soy rudo de cabeza,\nCanto sin saberlo hacer,\nLo hago por corresponder,\nA ustedes tanta fineza.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"ea",108,0,-1,0,319,319,"C-463","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0463-10",3,"\"Nos vinimos desde Orán,\nA las fiestas de \"El Galón\",\nQue allí tan mentadas son,\nSegún las noticias van.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",11,4,"a",147,0,-1,0,319,319,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-11",3,"Nosotros buscando el pan,\nCon el canto y con el juego,\nNos largamos desde luego,\nA probar nuestra fortuna,\nTal vez hallemos alguna,\nSi Dios nos escucha el ruego.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",9,6,"eo",29,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-12",3,"\"A juzgar por lo que veo,\nEstoy entre gente alegre,\nCantaré versos que integre,\nEl colmo de sus deseos,\nMas como algunos son feos\nPara que oigan las mujeres,\nCreo que está en mis deberes,\nPedirles que se retiren,\nPara que ellas no se almiren\nSi son de otros pareceres.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"ee",55,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-13",3,"Pues ellas son muy curiosas,\nY cuando los oigan reirse,\nHan de querer imponerse,\nDe toditas estas cosas,\nY temo a estas buenas mozas,\nMe malquisten con el cura,\nPues sería cosa muy dura,\nQue por esta diversión,\nMe eche una descomunión,\nQue es la cosa más segura.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"ua",17,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-14",3,"Las mujeres, llevan luego\nCuentos a los confesores,\nNo quiero que estos señores,\nSe mezclen en este juego.\nYo no quiero con el fuego,\nAndarme metiendo en chanzas;\nDel fraile no hay esperanza,\nQue nos salve del infierno,\nQue sea verano o invierno,\nNos larga nomás de panza.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"aa",163,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-15",3,"¡Señoras, siento altamente,\nY perdonen al contor,\nQue desprecia el gran honor,\nDe tenerlas por oyentes.\nPero aquí son imprudentes,\nDisculpemén la franqueza,\nPido a ustedes la fineza,\nQue se ausenten esta vez,\nPerdonando, que justo es,\nAl cantor tanta dureza.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"ea",108,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0463-16",3,"En fin, con esta advertencia,\nYa puedo seguir mi canto,\nSin temor de dar espanto,\nA una mujer de inocencia.\nSi alguna por imprudencia,\nSe esconde para escuchar,\nYa tendrá qué saboriar\nAlgún dulce por curiosa,\nQuien se mete a novedosa,\nYa tendrá pa no olvidar.",3,1,0,38,"AL DERREDOR DE UN FOGÓN",18,10,"a",21,0,-1,0,320,320,"C-463","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-01",3,"Atiéndame todo el mundo,\nTodo el mundo estese atento,\nQuiero que todos escuchen\nDe un moreno el argumento.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"eo",94,0,-1,0,320,320,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-02",3,"Era un negro muy bozal,\nNegro de la mota rala,\nQue por suerte lo encontré\nEn el cerro de la Tala.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"aa",330,0,-1,0,320,320,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-03",3,"Le pregunté qué se llama,\nCon la cortesía más fina,\nY me responde y me dice:\nYo soy Antonio Molina.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"ia",11,0,-1,0,320,320,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-04",3,"¿Podrás decirme, Molina,\nYa que la suerte nos junta,\nSi te encontrarás dispuesto\nA contestar mis preguntas?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"ua",-1,0,-1,0,320,320,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-05",3,"¡Válgame, Dios de los Cielos!\nAunque soy rudo al hablar,\nHagamé las que usted, guste,\nAún cuando sean ciento y más.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",3,4,"a",-1,0,-1,0,320,320,"C-464","",0,"","","",33,0,0,[],""],["carrizo_salta-nc0464-06",3,"A ver, decime Molina,\nTe pregunto a lo profundo,\n¿Cuáles son los tres pilares\nQue hubo primero en el mundo?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"uo",179,0,-1,0,320,320,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-07",3,"Ya que la pregunta me hace,\nLe contesto a lo primero:\n—Son tres personas distintas\nY un sólo Dios verdadero.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"eo",38,0,-1,0,320,320,"C-464","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0464-08",3,"A ver, decidme, Molina\nTe pregunto y ya van dos,\nDebajo de siete estados\n¿Qué estará haciendo mi Dios?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"o",87,0,-1,0,321,321,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-09",3,"A esta pregunta respondo:\nDentro de rayos y truenos\nSentado sobre su silla,\nJuzgando a malos y buenos.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"eo",365,0,-1,0,321,321,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-10",3,"A ver, decime, Molina,\nTe voy esto a preguntar:\n¿Cuántas leguas anda el sol\nHasta que se va a dentrar?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"a",21,0,-1,0,321,321,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-11",3,"Sin duda estará pensando\nQue voy perdido en mi cuenta,\nPorque el sol nunca camina,\nEs el mundo el que da vuelta.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"ea",-1,0,-1,0,321,321,"C-464","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0464-12",3,"A ver, decime, Molina,\nA esta pregunta también,\n¿En qué caballo fué Cristo\nAl mismo Jerusalén?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"e",242,0,-1,0,321,321,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-13",3,"¡Válgame Dios de los Cielos,\nPiensa que no he de saber!\nFué en un ángel desvalido\nQue Dios le negó su fé.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"e",-1,0,-1,0,321,321,"C-464","",0,"","","",33,0,0,[],""],["carrizo_salta-nc0464-14",3,"A ver, decime, Molina,\nTe pregunto porque es dable\n¿Cómo se podrá casar,\nUn hijo con una madre?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"ae",-1,0,-1,0,321,321,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-15",3,"—Yendo a Roma, viendo al Papa,\nViendo al Profeta Mayor,\nAsí se podrá casar,\nPagando dispensación.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"o",-1,0,-1,0,321,321,"C-464","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0464-16",3,"A ver, decime, Molina,\nLa pregunta se me antoja,\nAnda Cristo dentro el agua,\n¿Por qué es lo que no se moja?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"oa",146,0,-1,0,321,321,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-17",3,"Sin duda, estará pensando,\nQue se ha topao con un crudo,\n¿Cómo se podrá mojar\nSiendo un espíritu puro?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"uo",-1,0,-1,0,321,321,"C-464","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0464-18",3,"A ver, decime, Molina,\nComo viento de una fragua,\nQuiero que me contestis\n¿Con qué intención corre el agua?",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"aa",383,0,-1,0,321,321,"C-464","",0,"","","",6,0,0,[],""],["carrizo_salta-nc0464-19",3,"¡Válgame Dios de los cielos,\nComo el fiel de una balanza!\nLa intención que lleva el agua,\nCorrer, hasta donde alcanza.",3,1,0,38,"ATIÉNDAME TODO EL MUNDO",0,4,"aa",-1,0,-1,0,321,321,"C-464","",0,"","","",33,0,0,[],""],["carrizo_salta-nc0465-02",3,"Estaba un viejo sentado\nEncima de un mostrador,\nCon la guitarra en la mano,\nQue oirlo daba primor.",3,1,0,38,"EN EL PAGO DE COIQUILLE",0,4,"o",72,0,-1,0,321,321,"C-465","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0465-03",3,"¡Vení para acá, muchacho!\nPor la señal de la cruz,\nYo te quiero preguntar,\n¿Cómo te hallas de salud?",3,1,0,38,"EN EL PAGO DE COIQUILLE",0,4,"u",-1,0,-1,0,321,321,"C-465","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0465-04",3,"—Ya que esa pregunta me hace,\nLe contesto lo que sé,\nMi familia quedó buena,\nPa servir a su merced.",3,1,0,38,"EN EL PAGO DE COIQUILLE",0,4,"e",-1,0,-1,0,321,321,"C-465","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0466-01",3,"¡Hola, mi amigo Sandeta!\n¿De ande sale, qué anda haciendo?\nTanto tiempo por el pago,\nQue no lo veo divertiendo.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"eo",52,0,-1,0,321,321,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-02",3,"Hace tiempo, amigo, yo\nMe perdí, de estos lugares,\nPor la culpa de una gresca\nQue armé por los arrabales.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ae",-1,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-03",3,"¡Vaya, amigo, sientesé,\nY hágame la relación,\nCreo que esa gresca ha sido,\nPor quitar un corazón.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",31,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-04",3,"Le contaré, cómo no,\nAunque es larga relación,\nPero convide primero\nUn trago de ginebrón.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",31,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-05",3,"Aquí tiene, priéndalé,\nEmpape bien el garguero,\nQue no debe tomar poco,\nEl que es un gaucho matrero.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"eo",38,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-06",3,"Voy a contarle, amigaso,\nCómo fué la cosa aquella,\nPero tome usted un traguito,\nY páseme la botella.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",6,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-07",3,"¡Ahijuna, amigo Fanor,\nQué parranda y qué barullo!\nCasi me sacan el cuero,\nSi no lo llevo a mi puyo.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"uo",78,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-08",3,"En un poste recostao,\nMe encontraba en una esquina,\nCuando oí sonar la guitarra,\nY que cantaba una china.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ia",11,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-09",3,"Yo andaba medio tristón,\nY al oir cantar me alegré,\nMe retiré de ande estuve,\nY pal baile enderecé.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",77,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-10",3,"Me llegué muy despacito,\nY puse al óido en la puerta,\nCuando en derrepente se abre.\nY sale una vieja tuerta.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",267,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-11",3,"Parao nomás me quedé,\nNo me quise retirar,\nLa vieja salió apurada,\nSin verme se puso a miar.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"a",21,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-12",3,"Después que esto terminó,\nSe vino para mi lao,\nMe vió, me dijo: ¡entre adentro,\nNo se esté helando parao!",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",98,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-13",3,"¡Gracias, le dije, señora!\nY trás ella me colé,\nY pronto junto a una moza,\nAl punto me acomodé.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",77,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-14",3,"Al oído le platicaba,\nHablándole del amor,\nY ella me dijo: amigaso,\n¿Se le ablanda el corazón?",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",-1,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-15",3,"Pase amigo, la botella,\nQue se me secó el garguero,\nY luego le contaré,\nCómo fué aquel entrevero.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"eo",38,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-16",3,"Y cómo le iba contando,\nLa saqué a bailar un gato,\nY de ella otro enamorao\nHabía sido un gaucho ñato.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",-1,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-17",3,"Al verme salir con ella,\nMe blanquió sus ojarrones,\nPero yo no le hice caso,\nDe sus malas intenciones.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"oe",34,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-18",3,"Cuando acabé el primer baile,\nDijo: ¡gaucho chapucero!\nY ahí nomás le contesté:\n—¡Narices de vizcachero!",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",3,4,"eo",38,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-19",3,"Al oir esto, se me vino\nGritando: ¡gaucho rechoncho!\nMe tiró unos dos puntazos,\nMe los quité con el poncho.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"oo",387,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-20",3,"Yo eché mano a la cintura,\nEn busca de mí cuchillo,\nPero sólo hallé la vaina,\nPara suerte de aquel pillo.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"io",228,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-21",3,"Ya cargaron las mujeres,\nY todas se le prendieron,\nY como a un santo bendito,\nEn andas me lo tuvieron.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"eo",105,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-22",3,"Mientras así lo tenían,\nYo cargué sobre una mesa,\nEché mano a una botella,\nY le dí por la cabeza.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",-1,0,-1,0,322,322,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-23",3,"El ñato pegó un bufido,\nY ahí nomás se desmayó,\nLo pusieron en el suelo,\nY la gritería empezó.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",3,4,"o",2,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-24",3,"Atropellé pa la puerta,\nHuyendo de aquel mal trago,\nDisparando pa otra tierra,\nA ampararme en otro pago.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",207,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-25",3,"Susto grande me mamé,\nMás que en otras ocasiones,\nSi hubiera sido gallego,\nAllí empuerco mis calzones.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"oe",34,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-26",3,"Después supe al mucho tiempo,\nQue al que yo creía fino,\nAl hospital lo llevaron,\nY allí mismo había santo.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",5,4,"ao",-1,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-27",3,"Mucho me alegré al saberlo,\nY gracias a Dios le he dao,\nPorque no había permitido,\nQue yo viva desgracia,",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",5,4,"aa",-1,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-28",3,"Aquí tiene amigo, ya\nToda la culpa contada,\nDe la ausencia en que he vivido,\nLejos de mi tierra amada.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"aa",49,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-29",3,"Ahora lo dejaré a usted,\nQue me cuente cómo le ha ido,\nDurante la temporada\nEn que estuve yo perdido.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"io",101,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-34",3,"¡Linda era, como el lucero,\nQue sale para el verano,\nComo la luz al nacer,\nAllá en los montes, hermano!",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",81,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-35",3,"Allí en mi triste ranchito,\nFeliz, yo vivía con ella,\nMe llamaba: ¡sol querido!\nYo la llamaba: ¡mi estrella!",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",6,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-36",3,"Pero quiso en sus designios,\nNuestra sabia Providencia,\nQue no dure el ser feliz,\nComo dura la existencia.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",46,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-37",3,"Un día que salí al campo,\nMis vacas a rejuntar,\nEl corazón me golpeaba,\nComo avisos de un pesar.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"a",21,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-38",3,"Carnié un ternero ese día,\nPara tener qué comer,\nHice charque y lo dejé,\nQue lo cuide mi mujer.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",-1,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-39",3,"Volví a la hora de la siesta,\nCon dirección a mi rancho,\nY de lejos vi a mi charqui,\nQue lo comían los caranchos.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",-1,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-40",3,"Al momento que esto ví,\nEntero me espeluzné,\nLlego y busco a mi querida,\nFué en vano, no la encontré.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",77,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-41",3,"De tanto quererla, hermano,\nLa ingrata se me voló,\n¡Cuál sería mi pena, amigo,\nAl ver que me abandonó!",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",2,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-42",3,"Sentí entonces lo que nunca,\nTodo inflamado mi pecho,\nPor una rabia tremenda,\nContra la que mal me había hecho.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"eo",60,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-43",3,"Le pegué fuego a mi rancho,\nDonde tan feliz viví,\nLas lágrimas me corrían,\nAl ver que me iba de allí.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"i",23,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-44",3,"Dentré a rastriarla en seguida,\nPorque la güella era fresca,\nJuré en su alcance matarla,\nJunto con quién lo merezca.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",346,0,-1,0,323,323,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-45",3,"El amor que le tenía,\nEn rabia se convirtió,\nY la sangre de mis venas,\nAl corazón se agolpó.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",2,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-46",3,"En el rastro conocí\nQue se me había ido con otro,\nMás aumentó mi furor,\nY más le piqué a mi potro.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"oo",275,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-47",3,"De galope se habían ido\nLos caminos extraviando,\nLos alcancé con el día,\nLos caballos ensillando.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",33,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-48",3,"El gaucho estaba cinchando\nAl ensillao pa mujer,\nCuando ahí nomás me presento\nY ya no atinó qué hacer.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",20,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-49",3,"Se dispuso al fin montar,\nEn el caballo con silla,\nPero yo me le eché encima,\nY lo clavé en la tetilla.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ia",-1,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-50",3,"Cayó de espaldas al suelo\nTirando al aire patadas,\nY pa que no pene tanto,\nLe aumenté dos puñaladas.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"aa",282,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-51",3,"Corrí en seguida a la indina,\nQue al monte había disparao,\nY maniada en la pollera.\nAllí no más había rodao.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",3,4,"ao",98,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-52",3,"La agarré de los dos pieces,\nY hacia el otro la arrastré.\nY sobre su mismo amante,\nSin verla, la degollé.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",77,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-53",3,"El era un gaucho que meses,\nCon pretexto de campiar,\nSolía llegarse a mi rancho,\nDonde se le hacía almorzar.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"a",21,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-54",3,"Solía llamarme su amigo,\nDe todo su corazón,\nYo le creí en mi ignorancia,\nY ella fué mi perdición.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"o",31,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-55",3,"No tenga confianza, hermano,\nDel que le llame su amigo,\nPorque aquel más cariñoso,\nEs su mayor enemigo.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"io",106,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-56",3,"Después, no crea en la mujer,\nQue mucho amor le asegure,\nAunque a sus plantas le llore,\nY aunque por Dios se lo jure.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ue",388,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-57",3,"Convenzámonos, amigo,\nQue aunque la mujer sea bella,\nNo merece que los hombres,\nSuframos tanto por ella.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ea",6,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-58",3,"Después del delito que hice,\nMatando aquellos bellacos,\nSeis años viví en los montes\nEntre medio de matacos.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",389,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-59",3,"Al fin, me pude librar\nDe aquel terrible linaje,\nDonde viví tanto tiempo,\nLo mesmito que un salvaje.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ae",231,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-60",3,"¡Velay, amigo Sandeta,\nDe mi desgracia la historia,\nSepa que esto me entristece,\nCuando traigo a la memoria.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"oa",126,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-61",3,"Y sepa para su bien,\nComo consejo de amigo,\nQue a tener mujer bonita,\nMás valen los enemigos.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"io",-1,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-62",3,"¿Pues sabe, amigo Fanor,\nQue usted me ha hecho entristecer?\nTomemos, más bien, hermano,\nY olvidemos la mujer.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"e",20,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0466-63",3,"Sentados los dos juntitos,\nMano a mano se agarraron,\nCuando yo salí del rancho,\nDurmiendo los dos quedaron.",3,1,0,38,"¡HOLA MI AMIGO SANDETA!",0,4,"ao",-1,0,-1,0,324,324,"C-466","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-01",3,"Organizo mi memoria,\nPreparo el entendimiento,\nPara cantar, caballeros,\nAl compás del instrumento.",3,1,0,38,"ORGANIZO MI MEMORIA",0,4,"eo",-1,0,-1,0,324,324,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-02",3,"Al sonido de las cuerdas,\nHallándome autorizado,\nVoy a contarles l'historia,\nDe lo que a mí me ha pasado.",3,1,0,38,"ORGANIZO MI MEMORIA",0,4,"ao",14,0,-1,0,324,324,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-03",3,"Con una linda muchacha,\nQue por su puesto pasé,\nComo era tan bonita,\nDe enamorarla traté.",3,1,0,38,"ORGANIZO MI MEMORIA",0,4,"e",77,0,-1,0,325,325,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-04",3,"Le pintaba mi cariño,\nDel modo más amoroso,\nY le decía: ¡señorita,\nA su lao sería dichoso!",3,1,0,38,"ORGANIZO MI MEMORIA",3,4,"oo",160,0,-1,0,325,325,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-05",3,"Como niña muy resuelta,\nRespondió a lo que le dijo:\n—Imposible es conseguir,\nNada de lo que Vd. exige",3,1,0,38,"ORGANIZO MI MEMORIA",5,4,"ie",-1,0,-1,0,325,325,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-06",3,"Di vuelta la casa al punto,\nPensando en lo que pasaba,\nY una extraña voz oí,\nDe una que me saludaba.",3,1,0,38,"ORGANIZO MI MEMORIA",0,4,"aa",28,0,-1,0,325,325,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0467-07",3,"Después siguió caminando,\nY me volvió a repetir:\n—Mira, que si algo te falta\nYo lo puedo conseguir.",3,1,0,38,"ORGANIZO MI MEMORIA",0,4,"i",157,0,-1,0,325,325,"C-467","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-02",3,"Mundanas son las mujeres,\nDe sesenta años de edad,\nQue ningún hombre en el mundo,\nLe ha de decir la verdad.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"a",16,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-03",3,"Verdad dice el verdadero,\nY el que miente no haçe hazaña,\nEl que miente con discurso,\nConserva una amistad clara.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"aa",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-04",3,"Claro es el sol y la luna,\nQue alumbran con claridad,\nIluminan todo el mundo,\nY a toditos por igual.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"a",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-05",3,"Iguales son las fortunas,\nDe un matrimonio moreno,\nAunque se laven la cara,\nSiempre se quedan overos.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"eo",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-06",3,"Overos son los porotos\nQue venden en Buenos Aires,\nLos hay de todos tamaños,\nMedianos, chicos y grandes.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ae",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-07",3,"Grandes son los grandes diablos,\nQue viven en los infiernos,\nQue todos salen en contra,\nCuando se muda un gobierno.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"eo",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-08",3,"Gobierna el padre i familia,\nCon muchas obligaciones,\nY si estos viven muy pobres,\nTienen para sofocones.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"oe",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-09",3,"Sofocos tiene el carrero\nSi tiene que latiguiar,\nSi en el primer cuesta arriba,\nNo lo vienen a cuartiar.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"a",21,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-10",3,"Cuartian una tropa i carros,\nCuando dentran al pantano,\nEntran las ruedas al barro,\nSi el carrero no es baquiano.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ao",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-11",3,"Baquiano es el jugador,\nQue hace fortuna jugando,\nY cuando dice que pierde,\nEs cuando sale ganando.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ao",33,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-12",3,"Ganan plata los pulperos,\nCuando nos fían los vicios,\nApurao tienen al pobre,\nComo cuando hace ejercicio.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"io",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-13",3,"Ejercicio hace el soldado,\nCuando bala le menean\nEn el campo de batalla,\nAnde dicen que pelean.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ea",390,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-14",3,"Pelean también los gallos,\nSi dentran al reñidero,\nSe está con la precaución,\nPor saber cuál es más bueno.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"eo",-1,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-15",3,"Buenos son esos amigos,\nQue no tienen mal vivir,\nY si tienen plata, gastan,\nPara irse a divertir.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"i",157,0,-1,0,325,325,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-16",3,"Se divierten los niñitos,\nCuando se van a la misa,\nY les preparan el arco,\nPara correr la sortija.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ia",-1,0,-1,0,326,326,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-17",3,"Sortijas hace un enfermo,\nCuando el invierno ha llegado,\nNo tienen con qué taparse,\nDespiertan engarrotados.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"ao",-1,0,-1,0,326,326,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0468-18",3,"Se engarrotan los corderos,\nEn medio de la majada,\nCuando viene el viento Sud,\nCon neblina y con nevada.",3,1,0,38,"UNA VEZ EN \"LA FRONTERA\"",0,4,"aa",49,0,-1,0,326,326,"C-468","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0469-01",3,"Un viejo estaba sentado,\nEncima de un mostrador,\nCantando con la guitarra,\nCosas que daba primor.",3,1,0,38,"UN VIEJO ESTABA SENTADO",0,4,"o",72,0,-1,0,326,326,"C-469","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0469-02",3,"¡Vení acá, muchacho,\nRevolcado en la ceniza,\nQuiero que me digas aura,\nLo que contiene la misa!",3,1,0,38,"UN VIEJO ESTABA SENTADO",0,4,"ia",68,0,-1,0,326,326,"C-469","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0469-03",3,"—Ya que la pregunta me hace,\nContestaré con certeza,\nDesde que me bautizaron,\nNo volví a entrar en la iglesia.",3,1,0,38,"UN VIEJO ESTABA SENTADO",0,4,"ea",-1,0,-1,0,326,326,"C-469","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0469-04",3,"—Aura, decime muchacho,\nUna pregunta te haré:\n¿Cuántos pelos tiene el sapo\nCuando acaba de nacer?",3,1,0,38,"UN VIEJO ESTABA SENTADO",0,4,"e",-1,0,-1,0,326,326,"C-469","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0469-05",3,"—Ya que la pregunta me hace,\nLa respuesta le diré:\n¿Qué pelos puede tener\nCuando es más pelao que Vd.?",3,1,0,38,"UN VIEJO ESTABA SENTADO",5,4,"",-1,0,-1,0,326,326,"C-469","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0469-06",3,"¡Mandate a mudar, muchacho,\nMe tenis acobardao!\nIte pronto a tu ceniza,\nA masticar tu tostao.",3,1,0,38,"UN VIEJO ESTABA SENTADO",0,4,"ao",98,0,-1,0,326,326,"C-469","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-01",3,"¿Cuántas leguas hay al cielo?\n¿Qué hondura tiene el mar?\n¿Qué animal pastió primero,\nEn el Paraíso de Adán?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",0,4,"a",-1,0,-1,0,328,328,"C-470","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0470-02",3,"Silencio pido a los poetas,\nDe lo ignorante que soy;\nPara que me ayuden voy\nA componer esta letra,\nY verán un gran cometa,\nQue a todos causa recelo,\n¿Quién encumbra más el vuelo?\n¿Cuál es el astro mayor?\nPregunto al mejor autor:\n¿Cuántas leguas hay al cielo?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"eo",10,0,-1,0,328,328,"C-470","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-03",3,"Quisiera un punto saber,\nQue lo desea mi fortuna,\n¿Cuántas vueltas da la luna?\n¿Qué horas se tarda en nacer?\nEn un pliego de papel,\n¿Cuántos renglones cabrán?\n¿Años ha que murió Adán?\n¿Qué fin tuvo Salomón?\nDigamé con precisión,\n¿Qué hondura tiene la mar?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"a",-1,0,-1,0,328,328,"C-470","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-04",3,"¿Quién hizo el arpa y vihuela?\n¿Cuál fué el primer ermitaño?\n¿Cuántas horas tiene el año?\n¿Qué grosor tiene la tierra?\n¿Cuántas gotas en la sierra\nCaerán en un aguacero?\n¿Qué tanto será el dinero\nEn oro y plata sellada?\nPor selva, monte y cañada,\n¿Qué animal pastió primero?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"eo",38,0,-1,0,328,328,"C-470","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-05",3,"¿Cuál fué el ave que anunció\nDe Cristo su nacimiento?\n¿Cuál fué el primer elemento\nQue en el mundo Dios formó?\n¿Cuántos árboles plantó,\nDe la cordillera al mar?\nEl agua del río Jordán,\n¿Qué dicha o qué virtud tuvo?\n¿Cuál fué el primero que anduvo\nEn el Paraíso de Adán?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"a",147,0,-1,0,328,328,"C-470","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0470-a-02",3,"Licencia pido a los poetas,\nDe lo ignorante que soy,\nPero les pregunto yo,\nQuiero me den la respuesta:\n¿Cuál fué aquel primer cometa,\nQue a todos causó recelo?\n¿Qué ave hizo el primer vuelo?\n¿Cuál es el astro mayor?\nPregunto al mejor postor:\n¿Cuántas leguas hay al cielo?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"eo",10,0,-1,0,328,328,"C-470-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-a-03",3,"Un punto quiero saber,\nQue lo desea mi fortuna,\n¿Cuántas vueltas da la luna?\n¿Qué horas se tarda al nacer?\nY en un pliego de papel,\n¿Cuántas letras caberán?\n¿Qué años ha que murió Adán?\n¿Qué fin tuvo Salomón?\nPregunto al mejor autor,\n¿Qué hondura tiene la mar?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"a",-1,0,-1,0,328,328,"C-470-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0470-a-04",3,"¿Quién inventó arpa y vigüela?\n¿Cuál fué el primer ermitaño?\n¿Cuántas horas tiene el año?\n¿Qué grueso tiene la tierra?\n¿Cuántas fueron las goteras\nQue cayó en un aguacero?\n¿Cuántos fueron los dineros\nEn oro y plata sellados?\nY en montes, peñas y prados,\n¿Qué animal pastió primero?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"eo",-1,0,-1,0,328,328,"C-470-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-a-05",3,"¿Cuál fué el ave que anunció\nDe Cristo su nacimiento?\n¿Cuál fué el primer elemento\nQue Dios al mundo formó?\n¿Cuántos árboles plantó\nEntre cordillera y mar?\nY aquella agua del Jordán,\n¿Qué dicha o qué virtud tuvo?\n¿Cuál fué el primero que anduvo\nEn el Paraíso de Adán?",3,1,0,39,"CUANTAS LEGUAS HAY AL CIELO",18,10,"a",147,0,-1,0,328,328,"C-470-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0470-b-01",3,"¿Qué leguas hay de aquí al cielo?\n¿Qué hondura tendrá la mar?\n¿Qué bestia pastió primero\nEn los jardines de Adán?",3,1,0,39,"¿QUE LEGUAS HAY DE AQUÍ AL CIELO?",0,4,"a",-1,0,-1,0,329,329,"C-470-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-b-02",3,"Pregunto al mejor autor,\nEn lo ignorante que soy,\nA preguntarles me voy,\nQuiero me den la respuesta,\n¿Quién fué el que formó la letra?\n¿Quién fué el inventor del sello?\n¿Qué ave encumbró su vuelo?\n¿Cuál es el astro mayor?\nA que me avisen voy yo:\n¿Cuántas leguas hay al cielo?",3,1,0,39,"¿QUE LEGUAS HAY DE AQUÍ AL CIELO?",18,10,"eo",10,0,-1,0,329,329,"C-470-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-b-03",3,"Un punto quiero saber,\nQue lo desea mi fortuna,\n¿Cuántas vueltas da la luna,\nDel nacer hasta el poner?\nEn un pliegue de papel\n¿Cuántas letras caberán?\n¿Qué año ha que murió Adán?\nQué fín tuvo Salomón?\nPregunto al mejor autor,\n¿Qué hondura tendrá la mar?",3,1,0,39,"¿QUE LEGUAS HAY DE AQUÍ AL CIELO?",18,10,"a",-1,0,-1,0,329,329,"C-470-b","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0470-b-04",3,"¿Cuál fué el primer ermitaño?\n¿Quién inventó arpa y vihuela?\n¿Cuántas horas tiene el año?\n¿Qué grosor tiene la tierra?\n¿Cuántas serán las goteras,\nQue caen de un aguacero?\n¿Cuántos serán los dineros\nEn oro y plata sellados?\nY en peñas, montes y prados,\n¿Qué bestia pastió primero?",3,1,0,39,"¿QUE LEGUAS HAY DE AQUÍ AL CIELO?",18,10,"eo",-1,0,-1,0,329,329,"C-470-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0470-b-05",3,"¿Cuál fué el astro que anunció,\nDe Cristo su nacimiento?\n¿Cuál fué el primer elemento\nQue Dios en el mundo creó?\n¿Cuántos árboles plantó,\nEntre cordillera y mar?\nAl lado del río Jordán,\n¿Qué amor y dicha mantuvo?\n¿Quién fué el primero que anduvo,\nEn los jardines de Adán?",3,1,0,39,"¿QUE LEGUAS HAY DE AQUÍ AL CIELO?",18,10,"a",147,0,-1,0,329,329,"C-470-b","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0471-01",3,"En medio estoy de la gloria,\nY en misa no puedo estar,\nNi menos en el altar,\nPorque habito en la custodia.",3,1,0,39,"EN MEDIO ESTOY DE LA GLORIA",5,4,"oa",-1,0,-1,0,329,329,"C-471","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0471-02",3,"Yo habito en partes diversas,\nNo soy mujer ni viviente,\nSoy vocablo de la gente,\nColmo de las agudezas.\nEn el mundo hago grandezas,\nDe mí nacen las historias,\nSon fúnebres mis memorias,\nEn el oro me verán,\nSi me buscan me hallarán,\nEn medio estoy de la gloria.",3,1,0,39,"EN MEDIO ESTOY DE LA GLORIA",18,10,"oa",-1,0,-1,0,329,329,"C-471","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0471-03",3,"También soy de la oración,\nPues en los templos habito,\nTengo parte en Jesucristo,\nY en su sagrada pasión.\nYo soy de la confesión,\nDe la hostia y no del altar,\nProcuren adivinar,\nSin quebrantar la memoria,\nQue siendo yo de la gloria,\nEn misa no puedo estar.",3,1,0,39,"EN MEDIO ESTOY DE LA GLORIA",18,10,"a",21,0,-1,0,329,329,"C-471","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0471-04",3,"En medio del sol estoy,\nSoy una de cinco hermanas,\nNo soy divina ni humana,\nAdivinen, pues quién soy.\nBastantes señas les doy,\nSin descubrir ni ocultar,\nEn la hablando la verdad,\nDe la religión me espanto,\nYo en el cielo no soy santo,\nNi menos en el altar.",3,1,0,39,"EN MEDIO ESTOY DE LA GLORIA",18,10,"a",-1,0,-1,0,329,329,"C-471","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0472-01",3,"En ninguna parte habito,\nAntes que nadies hubiera,\nAntes de ser Dios nacido,\nNinguno supo quién era.",3,1,0,39,"EN NINGUNA PARTE HABITO",0,4,"ea",44,0,-1,0,330,330,"C-472","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0472-02",3,"Cuando la ciencia nació,\nEl sol, la luna y los vientos,\nNacieron los elementos,\nY ya era nacido yo.\nCuando el mundo se formó\nYa era nacido mil veces,\nNacieron todos los meses,\nLa luz y la obscuridad,\nDe más antes supe andar,\nAntes 'que nadies hubiese.",3,1,0,39,"EN NINGUNA PARTE HABITO",18,10,"ee",-1,0,-1,0,330,330,"C-472","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0472-03",3,"Soy de la luna, luz bella,\nEl sol de mí no ha sabido,\nDe nadie fuí conocido,\nVide nacer las estrellas.\nAnduve junto con ellas,\nNinguna de ellas me vido,\nNi el silencio me ha sentido,\nFuí formado antes del mar,\nAnduve en todo lugar,\nAntes de ser Dios nacido.",3,1,0,39,"EN NINGUNA PARTE HABITO",18,10,"io",101,0,-1,0,330,330,"C-472","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0472-04",3,"Al primer Dios conocí,\nY antes de que hubiera Dios,\nNunca lloré culpa atroz,\nDios no se informó de mí,\nA los cielos escribí,\nAntes que cielos hubiera,\ndel eclipse antiesfera,\nfundador de la fe,\nlos angeles hablé,\nNinguno supo quien era.",3,1,0,39,"EN NINGUNA PARTE HABITO",18,10,"ea",44,0,-1,0,330,330,"C-472","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0472-a-01",3,"Yo en el mundo no nací.\nAl cielo nunca llegué,\nNi por infierno pasé\nAl purgatorio no fuí\nNunca Dios supo de mí\nNi los angeles me han visto\nYo soy de todos registro,\nYo no tengo alma ni cuerpo,\nNo estoy ni afuera ni adentro,\nNi en ninguna parte habito.",3,1,0,39,"YO EN EL MUNDO NO NACÍ",18,10,"io",-1,0,-1,0,330,330,"C-472-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0472-a-02",3,"Soy de la luna, luz bella,\nEl sol de mi no ha salido,\nDe nadie fuí conocido,\nNi ví nacer las estrellas.\nMe anduve junto con ellas,\nNinguna de ellas me vió,\nNi el silencio me sintió,\nSoy formado antes del mar,\nMe anduve en todo lugar,\nAntes que nadie nació.",3,1,0,39,"YO EN EL MUNDO NO NACÍ",18,10,"o",2,0,-1,0,330,330,"C-472-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0472-a-03",3,"Yo al mismo Dios conocí,\nAntes de que fuera Dios,\nNunca lloré culpa atroz\nNi nadie informó de mí,\nYo a los cielos escribí,\nAntes que cielos hubiera,\nSoy eclipse de alta esfera,\nEl fundador de la fe,\nCon los ángeles hablé,\nY no supieron quien era.",3,1,0,39,"YO EN EL MUNDO NO NACÍ",18,10,"ea",44,0,-1,0,330,330,"C-472-a","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0472-a-04",3,"Cuando la ciencia nació\nEl sol, la luna, los vientos\nNacieron los elementos,\nNacido había sido yo.\nCuando el mundo se formó,\nYo fuí nacido mil veces,\nNacieron todos los meses,\nLa luz y la obscuridad,\nYo nací más cuantuá,\nAntes que nadies hubiese.",3,1,0,39,"YO EN EL MUNDO NO NACÍ",18,10,"ee",-1,0,-1,0,330,330,"C-472-a","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0473-01",3,"No tengo pena ni gloria,\nEstoy enfermo y sin males,\nEstoy muerto y tengo vida,\nEstoy rico y sin caudales.",3,1,0,39,"NO TENGO PENA NI GLORIA",0,4,"ae",26,0,-1,0,331,331,"C-473","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0473-02",3,"No hay quien me pueda entender\nEn esta pasión tan fuerte,\nAndo con desdicha y suerte,\nBien repleto y sin comer.\nSoy ciego pero sé ver,\nRecuerdo sin la memoria,\nTengo dicha y no es victoria,\nTengo suerte y no es cabal,\nY de este modo fatal,\nNo tengo pena ni gloria.",3,1,0,39,"NO TENGO PENA NI GLORIA",18,10,"oa",126,0,-1,0,331,331,"C-473","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0473-03",3,"En mi mismo no me amaño,\nMe desconozco y me toco,\nYa me miro como loco,\nEn mi casa soy extraño,\nSi en el fuego yo me baño\nMis ardores son fatales,\nSoy como los pedernales.\nSin dar chispa sé encender,\nSin penar sé padecer,\nEstoy enfermo y sin males.",3,1,0,39,"NO TENGO PENA NI GLORIA",18,10,"ae",26,0,-1,0,331,331,"C-473","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0473-04",3,"Es mi existencia tan rara,\nQue no sé si yo seré,\nY si siempre pasaré,\nSin poderme ver la cara.\nEl tiempo en nada me ampara,\nSoy como cosa perdida,\nTengo vara y no es medida,\nTengo suerte y no es cabal,\nDe un modo tan desigual,\nEstoy muerto y tengo vida.",3,1,0,39,"NO TENGO PENA NI GLORIA",18,10,"ia",37,0,-1,0,331,331,"C-473","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0473-05",3,"Yo quisiera adivinar\nY desde luego lo imploro,\nSoy sabio y todo lo ignoro,\nY también sé aconsejar,\nY les puedo asegurar,\nQue aunque soy irracional,\nTengo una finca frutal,\nAl fruto no lo merezco,\nDe todo tengo y carezco,\nEstoy rico y sin caudal.",3,1,0,39,"NO TENGO PENA NI GLORIA",18,10,"a",1,0,-1,0,331,331,"C-473","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0474-01",3,"Tipo de fidelidad,\nModelo de sentimiento,\nDechado de sufrimiento,\nY fénix de la amistad.",3,1,0,39,"TIPO DE FIDELIDAD",11,4,"a",16,0,-1,0,331,331,"C-474","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0474-02",3,"El es el ser más sincero,\nY de corazón amante,\nEl es siempre el más constante,\nY del hombre compañero.\nSu cariño es verdadero,\nY es humilde a la crueldad,\nSin quebrantar su amistad,\nJamás reclama el mal trato,\nEs de todos el más grato\nTipo de fidelidad.",3,1,0,39,"TIPO DE FIDELIDAD",18,10,"a",16,0,-1,0,331,331,"C-474","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0474-03",3,"Toda su dicha consiste\nHallarse al lado de su amo,\nTambién tiene algo de humano;\nCuando vé a su dueño triste,\nLa mayor pena lo asiste\nEsto le causa un tormento,\nY sin lanzar un lamento,\nNo protesta el trato cruel,\nAsí de este modo es él\nModelo de sentimiento.",3,1,0,39,"TIPO DE FIDELIDAD",18,10,"eo",94,0,-1,0,331,331,"C-474","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0474-04",3,"Si alguna vez cae herido\nEl mismo sólo se cura,\nY así sufre una amargura,\nPor algún mal consumido.\nSe pasa siempre dormido,\nHecho una rosca y hambriento\nMientras su dueño contento,\nTalvez no se acuerda de él,\nEs un compuesto de hiel\nDechado de sufrimiento.",3,1,0,39,"TIPO DE FIDELIDAD",18,10,"eo",94,0,-1,0,332,332,"C-474","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0474-05",3,"Ese su amor extremado,\nCon el hombre a quien él quiere,\nY aún hasta el hambre prefiere,\nPor estar siempre a su lado.\nEs el amigo abnegado,\nVíctima de la impiedad,\nSi le tratan con crueldad\nSin el merecido aprecio\nEs ejemplo de desprecio,\nY fénix de la amistad.",3,1,0,39,"TIPO DE FIDELIDAD",18,10,"a",16,0,-1,0,332,332,"C-474","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-01",3,"Yo soy más que Salomón\nExaminado profeta,\nQue al más sabio doy lección,\nA más, entiendo mi letra.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",0,4,"ea",-1,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-02",3,"Yo soy más que el pensamiento\nSoy tan inmenso, invisible,\nHombre soy en lo posible,\nTransito más que los vientos,\nYo soy raro en lo violento,\nDe más fuerza que un Sansón.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",9,6,"o",-1,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-03",3,"De talento y condición\nYo soy como el Padre Eterno,\nQue para mí no hay infierno,\nYo soy más que Salomón.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",11,4,"o",31,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-04",3,"Hasta con Dios soy igual,\nMi protesta tengo en Cristo.\nA todo el mundo lo habito\nEn todo soy principal.\nEn la corte celestial,\nDe mí nada se decreta,\nEl Evangelio me menta,\nEn el acto más profundo,\nSoy recreación del mundo\nExaminado y profeta.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",18,10,"ea",-1,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-05",3,"Yo, espíritu pienso ser,\nPorque mi rastro es inmenso,\nCon evidencia confieso,\nQue santo no puedo ser.\nNo he nacido de mujer,\nPero estoy en la Pasión,\nTambién en la Creación,\nDespués en los tribunales,\nEn la tierra, fuego y mares,\nAl más sabio doy lección.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",18,10,"o",31,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0475-06",3,"Yo hago Papas y Arzobispos\nSin ser Dios con excelencia,\nEnterada providencia,\nAstrólogos canonizo.\nYo doy estudio y oficios\nYo hago excelentes planetas,\nCompositores, poetas,\nDoy fincas y minerales,\nYo quito y doy los caudales,\nA más, entiendo mi letra.",3,1,0,39,"YO SOY MAS QUE SALOMÓN",18,10,"ea",-1,0,-1,0,332,332,"C-475","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-01",3,"Catorce años para quince\nQue he vivido encarcelado,\nMe leyeron la sentencia,\nDe morir afusilado.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"ao",14,0,-1,0,334,334,"C-477","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-02",3,"¡Aguarde señor verdugo\nUn favor voy a pedir:\nQue la traigan a mi madre\nQue me quiero despedir!",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"i",157,0,-1,0,334,334,"C-477","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-03",3,"Ya viene el famoso herrero\nCon su mejor oficial,\nA remacharme los grillos,\nQuitarme la libertad.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"a",-1,0,-1,0,334,334,"C-477","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-04",3,"Salí al patio de la cárcel\nPor ver si alguno pasaba.\nY el amigo más querido\nPor no verme se ocultaba.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"aa",28,0,-1,0,334,334,"C-477","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0477-05",3,"Un domingo de mañana\nSin pensar esta malicia\nDieron golpes a la celda,\nDiciendo \"Soy la justicia\".",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"ia",391,0,-1,0,334,334,"C-477","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0477-06",3,"El lunes por la mañana\nFué mi martirio primero,\nMe sacan que me despida,\nDe todos mis compañeros.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"eo",-1,0,-1,0,334,334,"C-477","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0477-07",3,"El martes por la mañana\nSué mi martirio segundo,\nMe sacan que me despida\nDe las delicias del mundo.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"uo",179,0,-1,0,334,334,"C-477","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-08",3,"El miércoles por la tarde,\nFué mi martirio tercero,\nEn el pecho me apuntaron\nCon los fusiles de acero.",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"eo",38,0,-1,0,334,334,"C-477","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0477-09",3,"A las cuatro de la tarde\nSe oyen campanas doblar,\nY entre los presos decían\n¡Pobrecito! ¿cuál será?",3,1,0,40,"CATORCE AÑOS PARA QUINCE",0,4,"a",-1,0,-1,0,334,334,"C-477","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0479-01",3,"Desde mi casa he salido\nCon grande necesidad,\nQue necesito unos riales\nY usted me los puede dar.",3,1,0,40,"DESDE MI CASA HE SALIDO",0,4,"a",-1,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0479-02",3,"—No tengo más que dos pesos\nY eso es lo que has de llevar\nSólo por servirte a vos.\nQuedo sin un medio rial.",3,1,0,40,"DESDE MI CASA HE SALIDO",0,4,"a",-1,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0479-03",3,"—Con dos pesos no hago nada\nNi suplo necesidad.\nDoscientos pesos preciso\nY aquí me los ha de dar.",3,1,0,40,"DESDE MI CASA HE SALIDO",3,4,"a",-1,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0479-04",3,"—Entonces le dice el cura:\nSólo por servirte a vos.\nSiquiera para que empeñes,\nToma y lleva este reloj.",3,1,0,40,"DESDE MI CASA HE SALIDO",0,4,"o",-1,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0479-05",3,"—Por ser de oro lo recibo\nPero con la condición,\nQue al reloj junto conmigo,\nNos eche la absolución.",3,1,0,40,"DESDE MI CASA HE SALIDO",0,4,"o",31,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0479-06",3,"—Absuelto de culpa y pena\nVáyanse juntos los dos,\nPor no mirarte a mi lado,\nDaré mil gracias a Dios.",3,1,0,40,"DESDE MI CASA HE SALIDO",0,4,"o",87,0,-1,0,336,336,"C-479","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-01",3,"¡Dios te salve, Virgen Santa\nAdónde estaba sentado!\nParecía que era la muerte\nEse Cántaro el mentado.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",14,0,-1,0,336,336,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-02",3,"De repente se levanta,\nCon gran precipitación\nY le dice a su mujer\nQue se llamaba Asunción:",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",31,0,-1,0,336,336,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-03",3,"Dame la ropa, mujer,\nQue me voy a ir a pasear,\nA casa de Don Antonio,\nQue ayer me mandó llamar.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"a",21,0,-1,0,336,336,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-04",3,"Talvez pueda yo morir\nEs preciso te prepares,\nTu sabes que me persiguen,\nPueden dar fin a mis males.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ae",-1,0,-1,0,336,336,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-05",3,"¡Levanta pronto! le dice,\nQue tengo que hablar con vos,\nTe aviso quienes me deben,\nY a quienes les debo yo.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",-1,0,-1,0,336,336,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-06",3,"¿Es posible Cantarito\nQue me des esta razón?\n¿Que pierdas las esperanzas\nEn un poderoso Dios?",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",-1,0,-1,0,337,337,"C-480","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0480-07",3,"No pierdo las esperanzas\nEn un poderoso Dios,\nPor si acaso muera yo\nBueno es que lo sepas vos.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",-1,0,-1,0,337,337,"C-480","",0,"","","",3,0,0,[],""],["carrizo_salta-nc0480-08",3,"Y salió de mañanita\nDe Las Acheras partió\nA casa de Don Antonio,\nA puestas del sol llegó.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",2,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-09",3,"¡Buena tarde amigo Antonio!\n¡Buena tarde, te dé Dios!\nYo bueno para servirte\n¿Cómo te va yendo a vos?",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",87,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-10",3,"¿Es posible Cantarito\nQué hayas venido de día?\nEl Capitán del Salado\nPara vos ha puesto espías.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ia",-1,0,-1,0,337,337,"C-480","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0480-11",3,"¿Qué importa que el Capitán\nPonga espías para mí,\nSi yo vengo destinado\nAl Carrizal a morir?",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"i",-1,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-12",3,"Y les dice a sus amigos\nTiendan la mesa, juguemos,\nNos divertamos un rato\nLuego nos levantaremos.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"eo",127,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-13",3,"Esto oyeron los espías,\nDieron parte al Capitán,\nQue Cantarito se hallaba,\nJugando en El Carrizal.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"a",-1,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-14",3,"Juntó gente el Capitán\nEntre lo mejor que había,\nY les repartió las armas,\nTodas las que allí tenía.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ia",0,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-15",3,"Y se vino el Capitán\nCon su gente bien armada,\nCaminaron cuatro cuadras,\nDesvainaron las espadas.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"aa",-1,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-16",3,"Entonces allí les dice:\n\"La casa van a rodear,\nEstensé bien prevenidos,\nPor si se quiere escapar.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"a",21,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-17",3,"\"Este es un gaucho advertido\nY de escaparse es capaz.\nY lo oyen decir a Cántaro:\n—¿Quién topa diez pesos más?",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"a",51,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-18",3,"En la puerta el Capitán\nSe presentó sin sentir,\n¡Oiga, dice a Cantarito,\nAhora vas a morir!",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"i",157,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-19",3,"Se levantó Cantarito\nDe donde estaba sentado,\nY levantó su puñal,\nQue lo tenía preparado.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",14,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-20",3,"¡Dejen venir a ese guapo!\n¡Denlé campo a ese alentado!\nQue la vista se me va,\nDe sólo estarlo mirando.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",-1,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-21",3,"Lo atropelló el Capitán\nTirándole de estocadas,\nComo los dos eran diestros\nAl aire se barajaban.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"aa",-1,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-22",3,"Entonces ya los soldados\nTodos a un tiempo cargaron,\nHicieron una descarga\nY a Cántaro lo voltiaron.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",41,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-23",3,"Después de estar en el suelo\nPor completo desarmado,\nAhí le dice el Capitán:\n—¡Oiga el muchacho alentado!",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",14,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-24",3,"Y le dice Cantarito:\n—No te agrandes por tu acción,\nSi al fin vos me hubieras muerto\nAl cabo tendrías razón.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"o",31,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-25",3,"Y no ha de ser por más guapo\nNi por ser más alentado,\nYo muerto he venido a ser,\nPorque la hora me ha llegado.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",14,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-26",3,"Y le dice al Capitán:\nQue esa gente se remita,\nQue poca gracia le lleva\nBala de cera bendita.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ia",50,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0480-27",3,"Aquí se acaba esta letra\nDe Cantarito el mentado\nQue en El Carrizal se ha vieto\nEn su sangre revolcado.",3,1,0,40,"DIOS TE SALVE, VIRGEN SANTA",0,4,"ao",14,0,-1,0,337,337,"C-480","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-01",3,"El primero de Noviembre\nDía domingo en que fueron,\nCon la severa justicia,\nA mi corazón prendieron.",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"eo",105,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-02",3,"Ya vino el famoso herrero\nCon el mayor oficial,\nA remacharme los grillos,\nQuitarme la libertad.",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"a",-1,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-04",3,"¡Ay, hijos desobedientes!\nObedezcan a sus padres.\nNo se vean como yo,\nMendigando voluntades.",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"ae",-1,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-05",3,"Ya me llevan al cadalso\nMe desremachan los grillos,\nYa me han leído la sentencia,\nDe morir en el banquillo.",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"io",-1,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-06",3,"Vino mi querida madre\nA echarme su bendición,\n¡Adiós, hijo de mi vida\nSangre de mi corazón!",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"o",31,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0481-07",3,"—¡Adiós, mi madre querida,\nTronco de todas mis ramas,\nRuegue a Dios por este su hijo\nNacido de sus entrañas!",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"aa",-1,0,-1,0,338,338,"C-481","",0,"","","",5,0,0,[],""],["carrizo_salta-nc0481-08",3,"—¡Váyase madre de aquí\nQuiero morir con valor,\nPara que sepan que Amaya\nNo ha temblado ante el terror!",3,1,0,40,"EL PRIMERO DE NOVIEMBRE",0,4,"o",72,0,-1,0,338,338,"C-481","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-01",3,"En catorce años de preso\nMi causa se tramitaba\nJamás me acordé ya de ella\nComo esta vez me acordaba.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"aa",28,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-02",3,"Al otro día de mañana\nOí las campanas doblar,\nVacilan entre los presos\n¿Cuál será, cuál no será?",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"a",-1,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-03",3,"Y se presentó el verdugo\nCon un silencio al llegar,\n¡Salí para acá Julián,\nQue te he venido a llevar!",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"a",-1,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-04",3,"Me sacaron arrastrando\nComo martirio primero,\nMe dicen que me despida,\nDe mis tristes compañeros.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"eo",-1,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-05",3,"¡Adiós, compañeros míos!\nQue ya los voy a dejar,\nAllá en el otro mundo,\nPor todos he de rogar.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"a",21,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-06",3,"Ya me ajustan las cadenas\nComo un martirio segundo,\nMe dicen que me despida\nDe las cosas de este mundo.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"uo",179,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-07",3,"¡Adiós, mundo traicionero!\nQue me has tenido engañando,\nCatorce años pa los quince\nA que he vivido penando.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"ao",33,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-08",3,"Y'a me sientan al banquillo\nAtado como un cordero,\nMe apuntan a la garganta,\nCon cuatro balas de acero.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"eo",38,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-09",3,"¡Permita señor verdugo\nUna cosa no he pedido,\nQue la traigan a mi madre\nDe ella no me he despedido!",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"io",101,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-10",3,"A mi mujer no la traigan\nPorque creo no la hi tenido,\nCatorce años pa los quince\nA que ni a verme ha venido.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"io",101,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0482-11",3,"A mis hijos sólo pido\nQue sean de buen proceder,\nQue recuerden de su padre,\nEl fin que vino a tener.",3,1,0,40,"EN CATORCE AÑOS DE PRESO",0,4,"e",20,0,-1,0,338,338,"C-482","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-01",3,"En nombre de Dios empiezo\n¡Nuestra Madre de Luján!\nPara relatar la muerte,\nDe Don Domingo Garán.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"a",147,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-02",3,"Ese Domingo Garán\nEra un hombre muy profundo,\nPues todo lo que él sabía\nNo era sabido en el mundo.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"uo",179,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-03",3,"Un domingo de mañana\nHa llegado el capataz,\nA darle los buenos días,\n¿Cómo está y cómo le vá?",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"a",-1,0,-1,0,339,339,"C-484","",0,"","","",9,0,0,[],""],["carrizo_salta-nc0484-04",3,"Don Domngo le responde\nCon toda su terquedad:\n—Yo, bueno, para servirte,\nHasta aquí sin novedad.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"a",16,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-05",3,"¿A qué vienes Santos Torres?\n¿Qué es lo que estás precisando?\n¿Vienes a darme noticias\nDel puesto que estás cuidando?",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"ao",33,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-06",3,"Santos Torres le responde:\n—A sus puertas me he venido,\nVengo ajustarme de cuentas,\nDel tiempo que le he servido.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"io",101,0,-1,0,339,339,"C-484","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0484-07",3,"En la fecha que hoy estamos\nOtro plazo se ha vencido,\nTengo un año trabajado\nY cuatro meses cumplidos.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"io",-1,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-08",3,"Don Domingo sacó el libro\nDonde llevaba su cuenta,\nY le dice, voy a ver\nTu cumples todos los treinta.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"ea",-1,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-09",3,"Lo puso sobre la mesa\nY pasó vista por él.\nYo te he de pagar el año\nTus cuatro meses también.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"e",-1,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-10",3,"Le responde Santos Torres:\n—Muy claro yo le hablaré,\nComo Ud. me pague el año,\nMuy contento quedaré.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"e",77,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-11",3,"Esto dijo Santos Torres\nY le volvió a repetir:\n—Como usted me pague el año\nVoy ahora mismo a salir.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"i",157,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-12",3,"Don Domingo le contesta:\n—Eso no me dice a mí\nYo he de pagar tu salario\nY has de ir al puesto a servir.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"i",-1,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-13",3,"Santos Torres le responde\nLe habla con toda verdad:\nSi usted está hecho a forzar hombres\nA mí no me ha de forzar.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"a",-1,0,-1,0,339,339,"C-484","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0484-14",3,"Se levantó Don Domingo,\nGran bofetada le dió,\nDe donde estuvo parado\nAl suelo lo derribó.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"o",2,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-15",3,"Se levanta Santos Torres\nY su puñal resbaló,\nLe pegó una puñalada,\nQue al otro lado bandió.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"o",2,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-16",3,"El valor de Don Domingo\nNo tiene comparación.\n¡Con las heridas abiertas\nY no pide confesión!",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"o",31,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-17",3,"El pobre de Don Domingo\nSe hallaba en gran aflicción;\nConvencido que moría,\nRecién pidió confesión.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"o",31,0,-1,0,339,339,"C-484","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0484-21",3,"Acuso, mi padre santo,\n\"on pesar hoy lo contemplo,\nlúe el rato que no pecaba,\n\"Jaba por perdido el tiempo.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"eo",-1,0,-1,0,340,340,"C-484","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0484-22",3,"'Acuso mi padre santo,\nSsto lo hacía por jactancia,\nfo debo unas siete muertes,\nCapataces de mi estancia.",3,1,0,40,"EN NOMBRE DE DIOS EMPIEZO",0,4,"aa",340,0,-1,0,340,340,"C-484","",0,"","","",7,0,0,[],""],["carrizo_salta-nc0485-01",3,"La plata interesa mucho\nAlborota al angelito,\nPor interés de cien pesos,\nMataron a Bartolito.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"io",119,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-03",3,"Bartolito estaba adentro\nMetiendo conversación,\nSalió Pizarro pa afuera.\nQue le avisó el corazón.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"o",31,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-04",3,"De afuera del guardapatio\nCon señas lo había sacado.\n¡Salga, compañero, vamos,\nPeñalva nos ha rodeado!",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"ao",-1,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-05",3,"Responde Bartolo y dice:\n—Yo soy como la baraja\nQue montando en mi caballo,\nNo les conozco ventaja.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"aa",393,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-06",3,"Responde Peñalva y dice:\n—Es cosa que se ha de ver\nQue llegándote el destino,\nCaballo no te ha i valer.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"e",20,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-07",3,"Montaron a sus caballos.\nSalieron de disparada,\nAl dar vuelta a un carrilón\nCayeron de una rodada.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"aa",49,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-08",3,"Allá se soltó Peñalva,\nPara ver si lo agarraba,\nDe sobre de su caballo,\nDe estocadas le tiraba.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"aa",28,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-09",3,"El pobre de Bartolito\nTodavía haciendo valor,\nDe abajo de su caballo,\nEl arma le barajó",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"o",-1,0,-1,0,340,340,"C-485","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0485-11",3,"Responde Manuel, el Viejo\nEl, como más advertido,\nBartolito ya se ha muerto\n¿Qué declaración va ha dar?",3,1,0,40,"LA PLATA INTERESA MUCHO",5,4,"a",-1,0,-1,0,340,340,"C-485","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0485-12",3,"El pobre de Bartolito\n¡Qué mozo tan desgraciado!\nAl cuerpo se lo llevaron\nEn una bolsa, arrastrado.",3,1,0,40,"LA PLATA INTERESA MUCHO",0,4,"ao",-1,0,-1,0,340,340,"C-485","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0486-01",3,"Señor Don Conrao Latorre\nBajo la luz de la luna,\nSin comparación ninguna\nEn la villa \"Los Galpones\",\nCasi mató a dos Ramones,\nA uno le erró un balazo,\nAl otro le erró un hachazo,\nY después de otras marañas,\nSalió en su mula castaña,\nCon su puñal y su lazo.",3,1,0,40,"SEÑOR DON CONRAO LATORRE",18,10,"ao",43,0,-1,0,341,341,"C-486","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0488-01",3,"'Adiós, madre de mi vida,\nTronco de todas mis ramas,\nfa se va su hijo querido,\nVacido de sus entrañas!",3,1,0,41,"ADIÓS, MADRE DE MI VIDA",0,4,"aa",-1,0,-1,0,343,343,"C-488","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0488-02",3,"Ya me despido señora\nMadre de mi corazón.\nEchemé su bendición,\nPorque ya me llega l'hora,\nAsí es que mi pecho llora\nLa ausencia de mi partida,\n¡Adiós, hermanas queridas!\nNo lloren ni sientan pena,\nMe voy a tierras ajenas\n¡Adiós, madre de mi vida!",3,1,0,41,"ADIÓS, MADRE DE MI VIDA",18,10,"ia",-1,0,-1,0,343,343,"C-488","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0488-03",3,"¡Hermanos, por Dios les pido;\nConsuelen a nuestra madre!\nPorque quedan como padre\nA darle gusto cumplido\nYo me voy enternecido\nMetido en tan fuerte llama,\nQue me abrasa toda el alma,\nY se me apaga la voz.\n¡Madre, encomendame a Dios,\nTronco de todas mis ramas!",3,1,0,41,"ADIÓS, MADRE DE MI VIDA",18,10,"aa",-1,0,-1,0,343,343,"C-488","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0488-04",3,"Siento una pena terrible\nSalir como desterrado,\nDe mi casa separado,\nCon el dolor insufrible\nDe mi suerte tan horrible,\ni' si a alguno yo he ofendido,\nMil veces perdón les pido\nPerdonemé que es razón,\n¡Madre de mi corazón\nFa se va su hijo querido!",3,1,0,41,"ADIÓS, MADRE DE MI VIDA",18,10,"io",101,0,-1,0,343,343,"C-488","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0488-05",3,"Me voy como un huerfanito\nMe voy a diversas tierras,\nMetido en civiles guerras,\nComo a purgar mi delito.\nTriste, afligido y contrito,\nMe voy a una tierra extraña,\nA sufrir toda la saña,\nDel rigor que yo colijo,\n¡Adiós madre, dice su hijo:\nSacido de sus entrañas!",3,1,0,41,"ADIÓS, MADRE DE MI VIDA",18,10,"aa",-1,0,-1,0,343,343,"C-488","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0489-01",3,"¡Adiós, mi querido hermano!\n¡Adiós, dueño de mi vida!\nAl tiempo de mi partida\nQuisiera darte la mano.",3,1,0,41,"ADIÓS, MI QUERIDO HERMANO",11,4,"ao",81,0,-1,0,343,343,"C-489","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0489-02",3,"Somos de una sola planta,\nFrutos de un solo sabor,\nQue antes de voltear la flor\nLa fortuna nos aparta.\nDe tu lado me levanta,\nUn viento fuerte y temprano,\nPero al contemplar que te amo,\nQueda mi cuerpo temblando.\nAsí yo me voy llorando\nAdiós, mi querido hermano.",3,1,0,41,"ADIÓS, MI QUERIDO HERMANO",18,10,"ao",-1,0,-1,0,343,343,"C-489","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0489-03",3,"En amarga confusión\nLo tienes al pecho mío,\nAl dejar el albedrío,\nQue goza mi corazón.\nHa llegado la ocasión\nDe darte esta despedida,\nEs una mortal herida\nDel puñal más penetrante,\nAl decirte en este instante:\n¡Adiós, dueño de mi vida!",3,1,0,41,"ADIÓS, MI QUERIDO HERMANO",18,10,"ia",37,0,-1,0,343,343,"C-489","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0489-04",3,"Guiado por una estrella\nBuscando mi suerte voy,\nSi con la fortuna doy,\nVos también gozarás de ella.\nDe mi hallarás la huella.\nEn donde quiera que viva,\nAunque me halle entre fatiga,\nY en el trance más amargo,\nQue no me olvides te encargo,\nAl tiempo de mi partida.",3,1,0,41,"ADIÓS, MI QUERIDO HERMANO",18,10,"ia",-1,0,-1,0,343,343,"C-489","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0489-05",3,"En fin, adiós, hermanito\nSalir de tu lado siento,\nPero apelo al sufrimiento\nEn este amargo conflicto.\nOtro adiós, más, te repito,\nComo al dejarte otro ramo.\nBien sabe el Dios soberano\nQue me quejo con razón,\nCon todo mi corazón,\nQuisiera darte la mano.",3,1,0,41,"ADIÓS, MI QUERIDO HERMANO",18,10,"ao",81,0,-1,0,343,343,"C-489","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0490-01",3,"¡Ay, muerte, tan sin piedad\nAutora de mis trabajos\nMe quitaste de los brazos\nToda mi felicidad!",3,1,0,41,"jAY, MUERTE, TAN SIN PIEDAD!",5,4,"a",16,0,-1,0,344,344,"C-490","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0490-02",3,"Ya no hay vuelo que me encumbre\nEn mi peregrinación,\nParece que sin razón,\nHe perdido el bien que tuve.\nUn negro luto me cubre,\nDesde aquella hora fatal,\nQuedando en mi soledad,\nA donde lamento y gimo,\nMe quejo, suspiro y digo\n¡Ay, muerte tan sin piedad!",3,1,0,41,"jAY, MUERTE, TAN SIN PIEDAD!",18,10,"a",16,0,-1,0,344,344,"C-490","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0490-03",3,"Entre todos mis hijitos\nMe ayudan a lamentar,\nY cansados de llorar\nSe me quedan dormiditos.\nMás, quedando yo solito\nImagino mis atrasos,\nSalgo, doy algunos pasos,\nLlorando mi fatal suerte,\n¡Ay, cómo no ha de ser la muerte,\nAutora de mis trabajos!",3,1,0,41,"jAY, MUERTE, TAN SIN PIEDAD!",18,10,"ao",-1,0,-1,0,344,344,"C-490","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0490-04",3,"En esta ocasión tan dura,\n¿Qué tal sería mi congoja\nVer a mi querida esposa\nBajar a la sepultura?\nCrujieron las coyonturas\nDe mi pecho, hecho pedazos,\nEn estos aciagos casos\nLe digo a la muerte así:\n—¡Esta es la prenda que a mí\nMe quitastes de los brazos!",3,1,0,41,"jAY, MUERTE, TAN SIN PIEDAD!",18,10,"ao",132,0,-1,0,344,344,"C-490","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0490-05",3,"Y después de llorar tanto\nLa busco afuera y adentro,\nMas, cuando no me la encuentro\nVuelvo a renovar mi llanto.\nDe mi lecho me levanto,\nEn la negra oscuridad,\nY allí me pongo a pensar,\nEn mi grande contratiempo,\nPorque perdí en un momento\nToda mi felicidad.",3,1,0,41,"jAY, MUERTE, TAN SIN PIEDAD!",18,10,"a",-1,0,-1,0,344,344,"C-490","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-01",3,"Ninguno por alto vuele,\nSe compare con las aves;\nPorque se ha de ver mañana,\nComo huérfano y sin padre.",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"ae",-1,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-02",3,"Yo también cuando volaba,\nMe comparé con las aves,\nY hoy me hallo rodando el mundo,\nMendigando voluntades.",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"ae",-1,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-03",3,"Dicen que un padre hace falta,\n¡Cómo no nos ha de hacer!\nPero ande dientra una madre,\nYo al mundo me he de oponer.",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"e",20,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-04",3,"Dijo mi madre al morir:\n—¡Quedarás a padecer.\nUnos te han de querer bien,\nOtros te han de aborrecer!",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"e",-1,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-05",3,"Cuando el hombre anda con plata,\nTodos le han de dar la mano,\nCuando la plata se acaba,\nNo hay amigos ni hay hermano.",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"ao",81,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0491-06",3,"Mi madre murió, fué cierto,\nYo me quedé sin ventura\n¡Ninguno pasa trabajos,\nMientras la madre le dura!",3,1,0,41,"NINGUNO POR ALTO VUELE",0,4,"ua",17,0,-1,0,344,344,"C-491","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0492-01",3,"¡Perdí mi padre y mi madre,\nAy, qué triste me quedé!\nDesde aquel funesto día,\nYa comencé a padecer.",3,1,0,41,"PERDÍ MI PADRE Y MI MADRE",0,4,"e",-1,0,-1,0,344,344,"C-492","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0492-02",3,"Quedé tan desconocido.\nNadie me daba la mano,\nDije, puede haber hermano\nO alguno que fué mi amigo,\nQue me brinde su cariño,\nViendo mi pena incurable.\nPuede que halle alguno amable\nQue le conmueva mis penas,\nAl ver que en hora fatal,\nPerdí mi padre y mi madre.",3,1,0,41,"PERDÍ MI PADRE Y MI MADRE",18,10,"ae",-1,0,-1,0,344,344,"C-492","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0492-03",3,"Ahora ya en mi soledad,\nMe quejo al cielo y suspiro\nViéndome en grande martirio\nSin poderme consolar.\nPerdí todo mi caudal,\nTan apreciado que fué.\n¡Jardín en que me sombrié,\nY luz que fué de mis ojos!\nEn tan crecido despojo\n¡Ay, qué triste me quedé!",3,1,0,41,"PERDÍ MI PADRE Y MI MADRE",18,10,"e",77,0,-1,0,345,345,"C-492","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0492-04",3,"Principiaron mis rebaños\nSin remedio a perecer,\nEn un largo padecer\nSe me trocaron los años.\nViví entre medio de extraños\nY nadie me conocía,\nPues ninguno me decía:\n—Yo te voy a proteger,\nSiento al verte padecer,\nDesde aquel funesto día.",3,1,0,41,"PERDÍ MI PADRE Y MI MADRE",18,10,"ia",0,0,-1,0,345,345,"C-492","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0492-05",3,"Perdí mi brillante sol\nMis troncos, ramas y gajos,\nPrincipiaron mis trabajos,\nA acrecentar mi dolor\nPerdiendo fama y honor,\nQue tanto solía tener,\nCuando existía mi placer,\nCon esos seres queridos.\nDesde que los he perdido,\nYa comencé a padecer.",3,1,0,41,"PERDÍ MI PADRE Y MI MADRE",18,10,"e",20,0,-1,0,345,345,"C-492","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0493-03",3,"Que no he podido encontrar\nAlivio en ningún lugar\nPara este rudo deshecho!\nElla me crió en su pecho,\nSoy hijo y debo llorar.",3,1,0,41,"VINO LA MUERTE ATREVIDA",7,5,"a",21,0,-1,0,345,345,"C-493","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0493-04",3,"¡Válgame Dios qué dolor,\nQué pesar tan sin segundo,\nPues he perdido en el mundo\nLa prenda de más valor!\nPerdí el timón de mi amor,\nYa murió de quién nací.\nYa falleció a quien le dí,\nTanto desvelo al criarme,\nPor quién debo lamentarme,\n¡Murió mi madre, ay de mí!",3,1,0,41,"VINO LA MUERTE ATREVIDA",18,10,"i",23,0,-1,0,345,345,"C-493","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0493-05",3,"Ya mi madre se murió,\n¡Ay, de mí qué desconsuelo!\nPero yo bien considero.\nQue para morir nació.\nY lo que debo hacer yo\nSentir es lo natural\nQue el que sea racional,\nLa razón me la ha de dar.\nMurió mi madre querida,\n¿Dónde la podré encontrar?",3,1,0,41,"VINO LA MUERTE ATREVIDA",18,10,"a",21,0,-1,0,345,345,"C-493","",0,"","","",2,0,0,[],""],["carrizo_salta-nc0494-01",3,"¡Ya mi placer se acabó,\nYa mi gloria se deshizo!\nCon sobrada razón llora\nEl que perdió lo que quiso.",3,1,0,41,"YA MI PLACER SE ACABO",0,4,"io",92,0,-1,0,345,345,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0494-02",3,"Llegó la muerte horroroza,\nHizo el estrago más grande,\nDejó a mis hijos sin madre,\nY a mí sin mi fiel esposa.\n¡Qué soledad lastimosa.\nDonde mi bien me dejó!\nNo tengo consuelo, no;\nEn mi espantoso sentir,\nDebo llorar y decir:\n¡Ya mi placer se acabó!",3,1,0,41,"YA MI PLACER SE ACABO",18,10,"o",2,0,-1,0,345,345,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0494-03",3,"El sentimiento más serio,\nFué quien deshizo mi pecho,\nPensando que se ha deshecho,\nCon el dolor más severo.\n¡Qué pena, qué desconsuelo",3,1,0,41,"YA MI PLACER SE ACABO",7,5,"eo",-1,0,-1,0,345,345,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0494-04",3,"Al perder mi dulce hechizo!\nAunque el morir es preciso,\nComo verdad de la fé,\nYo me lamento por qué.\nYa mi gloria se deshizo.",3,1,0,41,"YA MI PLACER SE ACABO",7,5,"io",95,0,-1,0,346,346,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0494-05",3,"Allí perdí mi consuelo,\nPerdí mi lucido oriente,\nPerdí mi dulce aliciente,\nEl afecto de mi anhelo.\nPerdí mi rápido vuelo,\nEn aquella funesta hora.\nPerdí la luz de mi aurora,\nPerdí mi seguro puesto,\nPues el que pierde todo esto\nCon sobrada razón llora.",3,1,0,41,"YA MI PLACER SE ACABO",18,10,"oa",107,0,-1,0,346,346,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0494-06",3,"Al dar el último aliento\nSus pobres ojos se eclipsan,\nY se reduce a cenizas,\nMi placer y mi contento.\nAsí determina el tiempo,\nUn vivir tan quebradizo;\nPerdió el diamante su viso,\nAl vivir en duro anhelo,\n¿En dónde hallará consuelo\nEl que perdió lo que quiso?",3,1,0,41,"YA MI PLACER SE ACABO",18,10,"io",92,0,-1,0,346,346,"C-494","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0495-01",3,"Yo soy ángel soberano,\nMe voy para la otra vida,\n¡Adiós mi madre querida!\n¡Adiós mi padre estimado!",3,1,0,41,"YO SOY ÁNGEL SOBERANO",5,4,"ao",-1,0,-1,0,346,346,"C-495","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0495-02",3,"Ya me ausento para siempre,\nDe este mundo miserable.\n¡Adiós mi padre y mi madre!\n¡Adiós hermanos, parientes!\nSi mi padrino algo siente\nAl mirarme amortajado,\nDebe quedar conformado,\nQue la gloria es permitida\nPues, por la ciencia divina,\nYo soy ángel soberano.",3,1,0,41,"YO SOY ÁNGEL SOBERANO",18,10,"ao",-1,0,-1,0,346,346,"C-495","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0495-03",3,"Tal vez si me hubiera criado,\nHubiera sido un perdido,\nPor eso Dios ha querido,\nRecogerme en este estado,\nSería talvez desgraciado,\nDurante toda mi vida.\nMi padrino y mi madrina,\nDeben quedar sin cuidado,\nPor librarme del pecado\nMe voy para la otra vida.",3,1,0,41,"YO SOY ÁNGEL SOBERANO",18,10,"ia",-1,0,-1,0,346,346,"C-495","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0495-04",3,"Sólo les queda el consuelo,\nCon toda seguridad,\nQue volando voy a entrar,\nEn el reino de los cielos.\nMe alejo ya de este suelo,\n¡Madre, padrino y madrina,\nQue cuando pierdan la vida\nPediré su salvación!\n¡Echemé su bendición!\n¡Adiós, mi madre 'querida!",3,1,0,41,"YO SOY ÁNGEL SOBERANO",18,10,"ia",37,0,-1,0,346,346,"C-495","",0,"","","",1,0,0,[],""],["carrizo_salta-nc0495-05",3,"Me despido de este valle\nTodo llevo de miseria,\nVosotros hermanos quedan,\nA servir a vuestros padres,\nLlegará el tiempo que vayan,\nTambién en el mismo estado,\nDe Dios serán perdonados,\nSi lo llegan a ofender.\nHasta volvernos a ver\n¡Adiós mi padre estimado!",3,1,0,41,"YO SOY ÁNGEL SOBERANO",18,10,"ao",-1,0,-1,0,346,346,"C-495","",0,"","","",1,0,0,[],""],["carrizo_salta-n0008-01",3,"Si la madrecita mía\nLevantara la cabeza,\nY viera cómo yo vivo,\nSe moriría de tristeza.",3,1,0,42,"",0,4,"ea",108,0,-1,0,349,349,"8","",0,"","","",4,0,0,[],""],["carrizo_salta-n0010-01",3,"A la bola, volando,\nFuertes murallas,\nEse tu amor y el mío\nForman batalla.",3,1,0,43,"",6,4,"aa",-1,0,-1,0,351,351,"10","",0,"","","",2,0,0,[],""],["carrizo_salta-n0011-01",3,"A la hora de mi muerte,\nUna cosa he de pedir,\nPoder un instante verte.\nPara contento morir.",3,1,0,43,"",1,4,"i",157,0,-1,0,351,351,"11","",0,"","","",1,0,0,[],""],["carrizo_salta-n0012-01",3,"Alhajita la rubita,\nDe catorce años de edad;\nDemasiado cuerpo tiene\nPara sufrir un pesar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,351,351,"12","",0,"","","",1,0,0,[],""],["carrizo_salta-n0013-01",3,"Al amor lo pintan ciego,\n¡Angel de mis ilusiones!\nCiegos estamos los dos,\nCiegos nuestros corazones.",3,1,0,43,"",0,4,"oe",34,0,-1,0,351,351,"13","",0,"","","",2,0,0,[],""],["carrizo_salta-n0014-01",3,"Al caminito de Oran\nTengo que hacerlo dorar,\nPara que ande mi vidita,\nCalladita sin llorar.",3,1,0,43,"",0,4,"a",21,0,-1,0,351,351,"14","",0,"","","",1,0,0,[],""],["carrizo_salta-n0015-01",3,"Al corazón te lo doy,\nPorque gobierna la vida;\nSólo el alma no te doy,\nPorque esa prenda no es mía.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,351,351,"15","",0,"","","",1,0,0,[],""],["carrizo_salta-n0015-01-e2",3,"A los ángeles del cielo\nLes voy aman dar pedir,\nUna pluma de sus alas,\nPara poderte escribir.",3,1,0,43,"",0,4,"i",157,0,-1,0,351,351,"15","",0,"","","",9,0,0,[],""],["carrizo_salta-n0016-01",3,"De los ángeles del cielo,\nHe podido conseguir,\nUna pluma y un tintero\nPara poderte escribir.",3,1,0,43,"",0,4,"i",157,0,-1,0,352,352,"16","",0,"","","",2,0,0,[],""],["carrizo_salta-n0017-01",3,"Al pié de tu reja vengo,\nPara contarte mis quejas,\nCon el alma dolorida.\n¡Despierta, mi alma, despierta!",3,1,0,43,"",0,4,"ea",-1,0,-1,0,352,352,"17","",0,"","","",1,0,0,[],""],["carrizo_salta-n0018-01",3,"Al silencio de la noche\nYo me iré a su rica cama,\nPerderá su lindo sueño,\nQue yo quiero ser su dueño.",3,1,0,43,"",5,4,"eo",138,0,-1,0,352,352,"18","",0,"","","",4,0,0,[],""],["carrizo_salta-n0019-01",3,"Al silencio de la noche,\nY al ruido de los nogales\nVengo a pedirle señora.\nRemedio para mis males.",3,1,0,43,"",0,4,"ae",26,0,-1,0,352,352,"19","",0,"","","",4,0,0,[],""],["carrizo_salta-n0020-01",3,"¡Amalhayas yo tuviera\nLas alas de aquel halcón!\nVolando me fuera a verte,\n¡Dueña de mi corazón!",3,1,0,43,"",0,4,"o",31,0,-1,0,352,352,"20","",0,"","","",2,0,0,[],""],["carrizo_salta-n0020-a-01",3,"¡Amalhayas yo tuviera\nLas alas de algún halcón!\nVolando me fuera a verte\n¡Prenda de mi corazón!",3,1,0,43,"",0,4,"o",31,0,-1,0,352,352,"20-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0021-01",3,"¡Amalhayas fuera pato\nY Ud. se hiciera laguna!\nPara sacudir mis alas.\nY tocarla con mis plumas.",3,1,0,43,"",0,4,"ua",-1,0,-1,0,352,352,"21","",0,"","","",1,0,0,[],""],["carrizo_salta-n0022-01",3,"¡Amalhayas mi vidita,\nFuera conmigo a la altura!\nEntonces sería dichoso,\nGozaría de su hermosura.",3,1,0,43,"",0,4,"ua",17,0,-1,0,352,352,"22","",0,"","","",1,0,0,[],""],["carrizo_salta-n0023-01",3,"¡Amalhayas, vida mía,\nEn tus brazos yo me hallara!\nDando las gracias a Dios.\nToda la vida pasara.",3,1,0,43,"",0,4,"aa",57,0,-1,0,352,352,"23","",0,"","","",4,0,0,[],""],["carrizo_salta-n0024-01",3,"¡Amalhayas, vida mía,\nMe dijeras la verdad!\nSeríamos dos amantes,\nPor toda la eternidad.",3,1,0,43,"",0,4,"a",16,0,-1,0,352,352,"24","",0,"","","",4,0,0,[],""],["carrizo_salta-n0025-01",3,"¡Amalhayas, vida mía,\nMe dijeras la verdad!\nMe señalaras un sitio,\nDonde te pueda aguardar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,352,352,"25","",0,"","","",4,0,0,[],""],["carrizo_salta-n0025-a-01",3,"¡Amalhayas, vida mía,\nMe dijeras la verdad!\nMe dijeras dónde duermes,\nDónde te podía aguardar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,352,352,"25-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n0026-01",3,"¡Amapolita morada,\nDel valle donde nací!\nNo te enamores de nadie,\nEnamorate de mí.",3,1,0,43,"",0,4,"i",23,0,-1,0,352,352,"26","",0,"","","",3,0,0,[],""],["carrizo_salta-n0027-01",3,"Antes era aburrecido,\nAhora soy bien querido.\nNo puedo pasar sin verte,\nVuelvo a tus brazos rendido.",3,1,0,43,"",0,4,"io",101,0,-1,0,352,352,"27","",0,"","","",1,0,0,[],""],["carrizo_salta-n0028-01",3,"¡Azucena, lindos ojos!\nRecorre tu pensamiento.\nAquí te viene a cantar.\nUn amante de otro tiempo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,353,353,"28","",0,"","","",1,0,0,[],""],["carrizo_salta-n0029-01",3,"¡Amiguita de fulana!\nAl pié de este árbol florido,\nMemorias hi de dejar,\nPorque aquí la he conocido.",3,1,0,43,"",0,4,"io",101,0,-1,0,353,353,"29","",0,"","","",1,0,0,[],""],["carrizo_salta-n0029-02",3,"¡Amiguito de fulano,\nParadito donde está!\nParece un granito de oro\nY una flor por reventar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,353,353,"29","",0,"","","",4,0,0,[],""],["carrizo_salta-n0031-01",3,"A mí me gustan las rubias\nPorque son de lindos modos,\nSon tan buenas y tan dulces\nComo miel de moro moro.",3,1,0,43,"",0,4,"oo",-1,0,-1,0,353,353,"31","",0,"","","",1,0,0,[],""],["carrizo_salta-n0034-01",3,"A mi vida la quiero,\nPorque ella es muy alhajita,\nTiene las cejas arqueadas,\nY la cara morenita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,353,353,"34","",0,"","","",1,0,0,[],""],["carrizo_salta-n0035-01",3,"A mi vidita la quiero,\nPorque tiene lindos modos,\nSi supiera en donde duerme,\nLa robaría cama y todo.",3,1,0,43,"",3,4,"oo",-1,0,-1,0,353,353,"35","",0,"","","",2,0,0,[],""],["carrizo_salta-n0036-01",3,"A mi vidita la quiero,\nPorque todos la aborrecen.\nEl consuelo que me queda,\nDonde ella pisa florece.",3,1,0,43,"",0,4,"ee",-1,0,-1,0,353,353,"36","",0,"","","",2,0,0,[],""],["carrizo_salta-n0037-01",3,"Amor firme te prometo,\nHasta mi última agonía,\nSólo el alma no te ofrezco,\nPorque esa prenda no es mía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,353,353,"37","",0,"","","",2,0,0,[],""],["carrizo_salta-n0038-01",3,"Amor firme te prometo,\nMás no te puedo ofrecer.\nAgua que corre río abajo,\nPara atrás no ha de volver.",3,1,0,43,"",0,4,"e",20,0,-1,0,353,353,"38","",0,"","","",2,0,0,[],""],["carrizo_salta-n0039-01",3,"¡Amor mío, amor mío!\nNo te apresures,\nQue el amor que te tengo,\nQuiero que dure.",3,1,0,43,"",6,4,"ue",-1,0,-1,0,353,353,"39","",0,"","","",5,0,0,[],""],["carrizo_salta-n0040-01",3,"Anoche, estando durmiendo,\nSoñé que estaba cortando,\nDe un jardín la flor más linda,\nY te la estaba brindando.",3,1,0,43,"",0,4,"ao",33,0,-1,0,353,353,"40","",0,"","","",2,0,0,[],""],["carrizo_salta-n0041-01",3,"Anoche, estando durmiendo,\nSoñé que te estaba haciendo,\nUna corona de flores,\nY te la estaba poniendo.",3,1,0,43,"",0,4,"eo",52,0,-1,0,353,353,"41","",0,"","","",2,0,0,[],""],["carrizo_salta-n0042-01",3,"Anoche por vez primera,\nMis ojos los tuyos vieron,\nY en el momento encendieron\nEl dulce fuego de amor.",3,1,0,43,"",5,4,"o",-1,0,-1,0,354,354,"42","",0,"","","",1,0,0,[],""],["carrizo_salta-n0043-01",3,"Antes que te conociera,\nNada de tí se me daba,\nSin pensamientos dormía,\nSin aflicción recordaba.",3,1,0,43,"",0,4,"aa",28,0,-1,0,354,354,"43","",0,"","","",2,0,0,[],""],["carrizo_salta-n0044-01",3,"Antinoche la soñé,\nAura la vuelvo a soñar;\nSu amor me tiene cautivo\nY no la puedo olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,354,354,"44","",0,"","","",1,0,0,[],""],["carrizo_salta-n0045-01",3,"Antinoche soñé un sueño,\nAnoche volví a soñar\nQue te tenía en mis brazos,\nMudo, sin poderte hablar.",3,1,0,43,"",0,4,"a",21,0,-1,0,354,354,"45","",0,"","","",2,0,0,[],""],["carrizo_salta-n0046-01",3,"Aprovechen la volada\nAl bailar el pericón,\n¡Señorita yo la quiero,\nCon todo mi corazón!",3,1,0,43,"",0,4,"o",31,0,-1,0,354,354,"46","",0,"","","",1,0,0,[],""],["carrizo_salta-n0047-01",3,"Arito quisiera ser,\nDe tus orejas pendiente\nPara decirte al oído,\nLo que mi corazón siente.",3,1,0,43,"",0,4,"ee",15,0,-1,0,354,354,"47","",0,"","","",1,0,0,[],""],["carrizo_salta-n0048-01",3,"Arriba de la ventana,\nQuisiera pintar al sol,\nMás abajito la luna,\nY en medio tu corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,354,354,"48","",0,"","","",1,0,0,[],""],["carrizo_salta-n0049-01",3,"Arrimate a la ventana\nO si no a la ventanilla,\nY si no tenís ventana,\nTras la puerta, vida mía.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,354,354,"49","",0,"","","",2,0,0,[],""],["carrizo_salta-n0050-01",3,"Arrimate, vida mía,\nArrimate para aquita,\nTengo un dolor en el alma,\nQue con verte se me quita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,354,354,"50","",0,"","","",1,0,0,[],""],["carrizo_salta-n0051-01",3,"Arroyos tienen los montes,\nQue botan agua a los ríos,\nAunque pase mil trabajos\nNo ti hi de olvidar bien mío.",3,1,0,43,"",0,4,"io",-1,0,-1,0,354,354,"51","",0,"","","",1,0,0,[],""],["carrizo_salta-n0052-01",3,"Así ha sido,\nY así ha i ser.\nPrimero se dá la mano,\nEse es mi modo i querer.",3,1,0,43,"",3,4,"e",20,0,-1,0,354,354,"52","",0,"","","",1,0,0,[],""],["carrizo_salta-n0053-01",3,"Así te dijo mi alma:\n—¡Ay, mi ricura!\nPorque tu eres la reina.\nDe la hermosura.",3,1,0,43,"",6,4,"ua",17,0,-1,0,354,354,"53","",0,"","","",1,0,0,[],""],["carrizo_salta-n0054-01",3,"¡Atienda, vidita mía,\nAtienda y ponga atención!\nMire que le estoy cantando,\nRendido de corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,354,354,"54","",0,"","","",3,0,0,[],""],["carrizo_salta-n0055-01",3,"Aunque es negro mi color,\nNo se vaya usted a asustar.\nQue más negros son sus ojos\nY me hacen enamorar.",3,1,0,43,"",0,4,"a",21,0,-1,0,354,354,"55","",0,"","","",1,0,0,[],""],["carrizo_salta-n0056-01",3,"Aunque me remachen grillos\nCon sus cadenas de acero,\nNo me han de privar los gustos,\nYa t'hi dicho que te quiero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,355,355,"56","",0,"","","",1,0,0,[],""],["carrizo_salta-n0057-01",3,"Aunque para mí no seas,\nSiempre te tendré afición;\nPero has de disimular\nCuando llegue la ocasión.",3,1,0,43,"",0,4,"o",31,0,-1,0,355,355,"57","",0,"","","",5,0,0,[],""],["carrizo_salta-n0058-01",3,"Aunque sea linda mi copla,\nLa de Ud. siempre es mejor.\nUna palabra que diga.\nEn su boca es una flor.",3,1,0,43,"",0,4,"o",72,0,-1,0,355,355,"58","",0,"","","",1,0,0,[],""],["carrizo_salta-n0059-01",3,"Aunque soy muy chiquitito,\nTengo grande el corazón,\nY en él están guardaditos\nLos tesoros de tu amor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,355,355,"59","",0,"","","",1,0,0,[],""],["carrizo_salta-n0060-01",3,"Aunque tuviera que andar\nCuarenta leguas por día,\nEn el día llegaré,\nAnde está la prenda mía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,355,355,"60","",0,"","","",1,0,0,[],""],["carrizo_salta-n0061-01",3,"Ausencias causan olvido,\nDice un antiguo cantar.\nMiente el cantar porque yo,\nNunca te sabré olvidar.",3,1,0,43,"",1,4,"a",21,0,-1,0,355,355,"61","",0,"","","",1,0,0,[],""],["carrizo_salta-n0063-01",3,"A vos solita te quiero,\nA vos solita te adoro,\nPorque vos solita sos,\nLa llave de mi tesoro.",3,1,0,43,"",0,4,"oo",85,0,-1,0,355,355,"63","",0,"","","",1,0,0,[],""],["carrizo_salta-n0064-01",3,"¡Ay, ay, ay, comeme!\nSi soy tu melón,\nGuardá la semilla,\nPara otra ocasión.",3,1,0,43,"",0,4,"o",31,0,-1,0,355,355,"64","",0,"","","",1,0,0,[],""],["carrizo_salta-n0065-01",3,"¡Ay, hermanita i fulana!\nBlanca espuma de la mar,\nDebes comprar un espejo\nPara poderte mirar.",3,1,0,43,"",0,4,"a",21,0,-1,0,355,355,"65","",0,"","","",1,0,0,[],""],["carrizo_salta-n0066-01",3,"¡Ahijuna puta mi amor,\nVerde como el cebollar!\nSi me quiere la hi querer,\nMientras viva la hí llorar.",3,1,0,43,"",0,4,"a",21,0,-1,0,355,355,"66","",0,"","","",2,0,0,[],""],["carrizo_salta-n0067-01",3,"¡Ahijuna puta vidita!\n¡Ahijuna puta negrita!\n¿Cuándo te estaré diciendo:\nVolameló palomita?",3,1,0,43,"",0,4,"ia",50,0,-1,0,355,355,"67","",0,"","","",4,0,0,[],""],["carrizo_salta-n0068-01",3,"¡Ahijuna puta, vidita,\nNo pongas mi amor en duda!\nDende que te vide a vos,\nNo quise otra criatura.",3,1,0,43,"",0,4,"ua",-1,0,-1,0,355,355,"68","",0,"","","",4,0,0,[],""],["carrizo_salta-n0069-01",3,"¡Ay, mi querida fulana!\nFlorcita de la ciudad.\nHermosa planta del mundo,\nEspejo de este lugar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,355,355,"69","",0,"","","",9,0,0,[],""],["carrizo_salta-n0070-01",3,"¡Ay, mi querida fulana!\nLa quiero y la hi de buscar,\nAunque se pierda en el mundo\nEn el cielo la hi de hallar.",3,1,0,43,"",0,4,"a",21,0,-1,0,356,356,"70","",0,"","","",9,0,0,[],""],["carrizo_salta-n0071-01",3,"¡Ay, mi querida fulana!\nSi quiere la llevaré,\nUd. se irá en mi caballo,\nY yo a su ladito a pié.",3,1,0,43,"",0,4,"e",77,0,-1,0,356,356,"71","",0,"","","",9,0,0,[],""],["carrizo_salta-n0072-01",3,"¡Ay, mi querida fulana,\nYo soñé que la quería!\nY que la balanza estaba\nQue se iba y que se venía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,356,356,"72","",0,"","","",9,0,0,[],""],["carrizo_salta-n0073-01",3,"¡Ay, mi querida fulana!\n¿Qué más le puedo decir?\nCon mi vida le atestiguo\nQue a su lado hi de morir.",3,1,0,43,"",0,4,"i",157,0,-1,0,356,356,"73","",0,"","","",9,0,0,[],""],["carrizo_salta-n0074-01",3,"¡Ay, mi querido fulano\nYo soy su amigo legal!\nSi algo le prometí yo\nCuente con seguridad.",3,1,0,43,"",0,4,"a",-1,0,-1,0,356,356,"74","",0,"","","",2,0,0,[],""],["carrizo_salta-n0075-01",3,"¡Ay, vidita! no pierdo\nLas esperanzas,\nDe poner un puestito,\nJunto a tu estancia.",3,1,0,43,"",6,4,"aa",-1,0,-1,0,356,356,"75","",0,"","","",1,0,0,[],""],["carrizo_salta-n0076-01",3,"Baja, linda, al cuarto bajo\nY hablaremos por la reja,\nDos palabritas de amor.\nSin que se entere la vieja.",3,1,0,43,"",0,4,"ea",165,0,-1,0,356,356,"76","",0,"","","",1,0,0,[],""],["carrizo_salta-n0076-a-01",3,"Negrita, a tu casa vengo\nPara decirte a la oreja.\nDos palabritas de amor\nSin que lo sienta la vieja.",3,1,0,43,"",0,4,"ea",165,0,-1,0,356,356,"76-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0077-01",3,"¡Bien haiga la piedra lisa,\nEn la que me resfalé!\nVidita, porque la quise\nAl verla me levanté.",3,1,0,43,"",0,4,"e",77,0,-1,0,356,356,"77","",0,"","","",1,0,0,[],""],["carrizo_salta-n0078-01",3,"Bien sabes que las mentiras\nMalquistan un fino amor,\nNo te he de cambiar con otra\nAunque parezca mejor.",3,1,0,43,"",0,4,"o",72,0,-1,0,356,356,"78","",0,"","","",1,0,0,[],""],["carrizo_salta-n0079-01",3,"¡Blanca paloma\nDe Villazón!\nAquí está tu dueño\nDe corazón.",3,1,0,43,"",6,4,"o",31,0,-1,0,356,356,"79","",0,"","","",2,0,0,[],""],["carrizo_salta-n0080-01",3,"Buenos Aires, buena tierra;\nTucumán, para llorar.\nOjos negros de mi vida\nQue no los puedo olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,356,356,"80","",0,"","","",2,0,0,[],""],["carrizo_salta-n0081-01",3,"¡Caballero de fulano!\nCantemeló una coplita.\nAunque no sea concertada,\nComo sea de su boquita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,356,356,"81","",0,"","","",36,0,0,[],""],["carrizo_salta-n0082-01",3,"¡Caballero de fulano!\nClavel nácar encendido,\nEspejo de una campana,\nCorazón de un afligido.",3,1,0,43,"",0,4,"io",101,0,-1,0,356,356,"82","",0,"","","",36,0,0,[],""],["carrizo_salta-n0083-01",3,"¡Caballero de fulano!\nCoronado de alhelí,\nSi se parara a mi lado,\nMe contara por feliz.",3,1,0,43,"",0,4,"i",-1,0,-1,0,357,357,"83","",0,"","","",36,0,0,[],""],["carrizo_salta-n0084-01",3,"¡Caballero de fulano!\nDe la sala al corredor.\nHaga brillar las estrellas,\nHaga detener al sol.",3,1,0,43,"",0,4,"o",-1,0,-1,0,357,357,"84","",0,"","","",36,0,0,[],""],["carrizo_salta-n0085-01",3,"¡Caballero de fulano!\nDel cielo caigan dos rosas,\nUna se quede en el aire\nCon Ud. la más hermosa.",3,1,0,43,"",0,4,"oa",-1,0,-1,0,357,357,"85","",0,"","","",36,0,0,[],""],["carrizo_salta-n0086-01",3,"¡Caballero de fulano!\nFlores crecen donde pisa,\nPresa me tiene su amor,\nPor su hechicera sonrisa.",3,1,0,43,"",0,4,"ia",68,0,-1,0,357,357,"86","",0,"","","",36,0,0,[],""],["carrizo_salta-n0087-01",3,"¡Caballero de fulano!\nFuente de agua cristalina,\nDonde resucitan muertos\nY los enfermos se alivian.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,357,357,"87","",0,"","","",36,0,0,[],""],["carrizo_salta-n0088-01",3,"¡Caballero de fulano!\n-r ito de oro molido.\n7: dito adonde está\nParece un jardín florido.",3,1,0,43,"",0,4,"io",101,0,-1,0,357,357,"88","",0,"","","",36,0,0,[],""],["carrizo_salta-n0089-01",3,"¡Caballero de fulano!\no de oro de quilates,\nilates pasó a perlas,\nperlas a diamantes.",3,1,0,43,"",0,4,"ae",-1,0,-1,0,357,357,"89","",0,"","","",36,0,0,[],""],["carrizo_salta-n0091-01",3,"¡Caballero de fulano!\nOiga, le voy a decir,\nSolicite un imposible,\nYo le ayudaré a sentir.",3,1,0,43,"",0,4,"i",157,0,-1,0,357,357,"91","",0,"","","",36,0,0,[],""],["carrizo_salta-n0092-01",3,"¡Caballero de fulano!\nLo quiero, y qué le daré?\nEn cada mano una rosa,\nY en el ojal un clavel.",3,1,0,43,"",0,4,"e",-1,0,-1,0,357,357,"92","",0,"","","",36,0,0,[],""],["carrizo_salta-n0093-01",3,"¡Caballero de fulano!\nSentadito donde está\nParece un jardín de rosas,\nY un clavel por reventar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,357,357,"93","",0,"","","",36,0,0,[],""],["carrizo_salta-n0094-01",3,"¡Caballero de fulano!\nYo respeto sus honores,\n¿Qué dijera si volviera\nA sus años anteriores?",3,1,0,43,"",0,4,"oe",5,0,-1,0,357,357,"94","",0,"","","",36,0,0,[],""],["carrizo_salta-n0095-01",3,"¡Caballero de fulano!\nClavelito mordoré,\nNo pienso querer a nadie,\nTan sólo querer a usted.",3,1,0,43,"",0,4,"e",-1,0,-1,0,357,357,"95","",0,"","","",36,0,0,[],""],["carrizo_salta-n0096-01",3,"¡Caballero don fulano!\n¡Estrellita chilimbrosa!\nUd. diz que ha chilimbrado,\nEntre San Juan y Mendoza.",3,1,0,43,"",0,4,"oa",195,0,-1,0,357,357,"96","",0,"","","",2,0,0,[],""],["carrizo_salta-n0097-01",3,"Cansate de serme infiel\nY de pagarme tan mal,\nComo soy mozo constante\nDe amarte no m'hi cansar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,357,357,"97","",0,"","","",1,0,0,[],""],["carrizo_salta-n0098-01",3,"Canta el jilguero en la rama,\nLa canadria en el almendro,\nNo sé dónde t'hi poner,\nPara siempre estarte viendo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,357,357,"98","",0,"","","",1,0,0,[],""],["carrizo_salta-n0099-01",3,"¡Caramba con la memoria!\nQue no me puedo acordar.\nEstando junto con ella\nLa memoria se me va.",3,1,0,43,"",0,4,"a",-1,0,-1,0,358,358,"99","",0,"","","",2,0,0,[],""],["carrizo_salta-n0100-01",3,"¡Caramba que tiembla el mundo!\nQue hasta el alma me tirita,\nYo me quisiera encontrar,\nEn sus brazos, señorita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,358,358,"100","",0,"","","",1,0,0,[],""],["carrizo_salta-n0101-01",3,"¡Casate, niña bonita!\nBoquita de dulce miel,\nPero no pa San Antonio\nSino para San Miguel.",3,1,0,43,"",0,4,"e",32,0,-1,0,358,358,"101","",0,"","","",1,0,0,[],""],["carrizo_salta-n0102-01",3,"¡Cazador de palomas!\nTirale al vuelo,\nA esa paloma hermosa\nQue anda en el suelo.",3,1,0,43,"",6,4,"eo",10,0,-1,0,358,358,"102","",0,"","","",1,0,0,[],""],["carrizo_salta-n0103-01",3,"¡Clavelina colorada!\nNacida en el mes de Enero,\n¿Dónde han visto nacer flores\nEn el rigor del invierno?",3,1,0,43,"",0,4,"eo",-1,0,-1,0,358,358,"103","",0,"","","",2,0,0,[],""],["carrizo_salta-n0104-01",3,"¡Clavelina, flor morada!\nNacida en el mes de Enero,\nHi de pintar tu cariño,\nHaré constar que te quiero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,358,358,"104","",0,"","","",1,0,0,[],""],["carrizo_salta-n0105-01",3,"¡Clavelito en medio l'agua!\nRegado por el rocío,\n¿Cuándo yo podré juntar\nTu corazón con el mío?",3,1,0,43,"",0,4,"io",3,0,-1,0,358,358,"105","",0,"","","",1,0,0,[],""],["carrizo_salta-n0106-01",3,"¡Cogollito de naranjo!\nFlorcita de duraznillo,\nDejate de amar tu dueño,\nVenite a vivir conmigo.",3,1,0,43,"",0,4,"io",-1,0,-1,0,358,358,"106","",0,"","","",1,0,0,[],""],["carrizo_salta-n0107-01",3,"Como a melón de Castilla\nRecojamos la semilla.\nA mí me gusta querer\nHijas de buenas familias.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,358,358,"107","",0,"","","",1,0,0,[],""],["carrizo_salta-n0108-01",3,"Como árbol marchito estoy\nCuando te puedo ver\nCon el riego de tu vista\nVolveré a reverdecer.",3,1,0,43,"",0,4,"e",20,0,-1,0,358,358,"108","",0,"","","",2,0,0,[],""],["carrizo_salta-n0109-01",3,"Como si fuera veleta,\nQue con el viento va y viene,\nAsí la vidita mía,\nA mi corazón lo tiene.",3,1,0,43,"",0,4,"ee",70,0,-1,0,358,358,"109","",0,"","","",1,0,0,[],""],["carrizo_salta-n0110-01",3,"Como ciega mariposa,\nAlrededor de la vela,\nAsí está mi corazón.\nMirándote se consuela.",3,1,0,43,"",0,4,"ea",167,0,-1,0,358,358,"110","",0,"","","",1,0,0,[],""],["carrizo_salta-n0111-01",3,"Cómo me matan las penas\nCuando me pongo a pensar,\nAsí me matan tus ojos\nCuando me quieres mirar.",3,1,0,43,"",0,4,"a",21,0,-1,0,358,358,"111","",0,"","","",1,0,0,[],""],["carrizo_salta-n0112-01",3,"¿Cómo quieres que te olvide\nSi es que Dolores te llamas?\n¡Dolores, del alma mía!\nDolores sufre mi alma.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,358,358,"112","",0,"","","",6,0,0,[],""],["carrizo_salta-n0113-01",3,"¿Cómo quiere que lo quiera\nSi recién lo hi conocido?\nVenga seguido a mi casa,\nVerá si es aborrecido.",3,1,0,43,"",0,4,"io",101,0,-1,0,359,359,"113","",0,"","","",1,0,0,[],""],["carrizo_salta-n0114-01",3,"Como sabís que te quiero\nTe reís de mi cariño,\nY no me tomas en serio\nComo pregunta de niño.",3,1,0,43,"",0,4,"io",176,0,-1,0,359,359,"114","",0,"","","",1,0,0,[],""],["carrizo_salta-n0115-01",3,"Cómo será que la quiero,\nQue no siento el padecer,\nLa vida pienso quitarme\nPara hacerme conocer.",3,1,0,43,"",0,4,"e",20,0,-1,0,359,359,"115","",0,"","","",1,0,0,[],""],["carrizo_salta-n0116-01",3,"Como sois rosa de fuego,\nDe lejos me estás quemando,\n¡Retírate, no te quiero!\n¡Vení, te digo jugando!",3,1,0,43,"",0,4,"ao",33,0,-1,0,359,359,"116","",0,"","","",1,0,0,[],""],["carrizo_salta-n0119-01",3,"Con el llanto no se apaga\nEl fuego de la pasión,\nAmame, prenda querida,\nQue me muero por tu amor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,359,359,"119","",0,"","","",1,0,0,[],""],["carrizo_salta-n0120-01",3,"Con el naipe de su amor,\nYo no quisiera jugar.\nMe ha ganado el corazón,\nNo me puedo desquitar.",3,1,0,43,"",0,4,"a",21,0,-1,0,359,359,"120","",0,"","","",1,0,0,[],""],["carrizo_salta-n0121-01",3,"Conforme la estoy queriendo,\nDe mí se compadeciera,\nNo hallando dónde ponerla,\nEn mis brazos la tuviera.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,359,359,"121","",0,"","","",1,0,0,[],""],["carrizo_salta-n0122-01",3,"Con gusto me emborrachara\nY de borracho muriera,\nSi en tus ojitos, mi vida,\nBeber el vino pudiera.",3,1,0,43,"",0,4,"ea",44,0,-1,0,359,359,"122","",0,"","","",1,0,0,[],""],["carrizo_salta-n0123-01",3,"Con letras de plata y oro\nVoy a poner un letrero,\nPara que sepa la gente,\nLo mucho que yo te quiero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,359,359,"123","",0,"","","",2,0,0,[],""],["carrizo_salta-n0124-01",3,"Con qué ojitos te mirara,\nCon qué vocita te hablara;\nEn la primera palabra,\nEl corazón te ablandara.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,359,359,"124","",0,"","","",1,0,0,[],""],["carrizo_salta-n0125-01",3,"Con su permiso, vidita,\nA su cama m'hi arrimado;\nCon su corazón a gusto\nTalvez no sea despreciado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,360,360,"125","",0,"","","",1,0,0,[],""],["carrizo_salta-n0126-01",3,"Contigo iré donde quieras,\nMoreno, juntos los dos.\nTu patria será mi patria,\nY tu Dios será mi Dios.",3,1,0,43,"",0,4,"o",87,0,-1,0,360,360,"126","",0,"","","",1,0,0,[],""],["carrizo_salta-n0127-01",3,"Con tres libros yo te escribo,\nCon cuatro te hago un pedido,\nCon cinco, prenda querida,\nY con seis ya no te olvido.",3,1,0,43,"",0,4,"io",101,0,-1,0,360,360,"127","",0,"","","",1,0,0,[],""],["carrizo_salta-n0128-01",3,"Con tus miradas me matas,\nSin ellas vivo muriendo.\nA tu lado estoy con celos,\nAusente de ti me muero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,360,360,"128","",0,"","","",1,0,0,[],""],["carrizo_salta-n0129-01",3,"¡Corazón de avellana!\nPecho de almendra,\nLimón azucarado,\n¡Quién te comiera!",3,1,0,43,"",6,4,"ea",-1,0,-1,0,360,360,"129","",0,"barcenas_marinera, huambachano","","",3,0,0,[],""],["carrizo_salta-n0130-01",3,"Corriente soy como el río,\nComo el agua de beber,\n¡Vení, vidita, a mis brazos!\nQue mal pago no has de ver.",3,1,0,43,"",0,4,"e",20,0,-1,0,360,360,"130","",0,"","","",1,0,0,[],""],["carrizo_salta-n0131-01",3,"Cuando al sepulcro me arroje\nLa fuerza de mi dolor,\nSeré un esqueleto amante\nSi hay tras de la muerte amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,360,360,"131","",0,"","","",1,0,0,[],""],["carrizo_salta-n0132-01",3,"Cuando ando por los caminos\nSe me hace que la voy viendo,\nTanto es el amor que tengo,\nTanto la vivo queriendo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,360,360,"132","",0,"","","",1,0,0,[],""],["carrizo_salta-n0133-01",3,"Cuando caigan las estrellas\nY el río corra ya arriba.\nT'hi de dejar de querer\nSi Dios me presta la vida.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,360,360,"133","",0,"","","",1,0,0,[],""],["carrizo_salta-n0134-01",3,"Cuando de mí estás ausente,\nEs tan grande mi pesar,\nQue para contar mis penas\nFaltan arenas del mar.",3,1,0,43,"",0,4,"a",21,0,-1,0,360,360,"134","",0,"","","",1,0,0,[],""],["carrizo_salta-n0135-01",3,"Cuando el pozo está más hondo,\nMás fresca se pone l'agua.\nCuando más lejos te veo\nMás firme está mi palabra.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,360,360,"135","",0,"","","",1,0,0,[],""],["carrizo_salta-n0136-01",3,"Cuando estés mirando el cielo,\nViendo el lucero brillar,\nAcordate de este mozo\nQue nunca te ha de olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,360,360,"136","",0,"","","",1,0,0,[],""],["carrizo_salta-n0137-01",3,"Cuando estuve en la prisión,\nEn lo que me divertía.\nEra en escribir tu nombre\nEn los ladrillos que había.",3,1,0,43,"",0,4,"ia",0,0,-1,0,360,360,"137","",0,"","","",1,0,0,[],""],["carrizo_salta-n0138-01",3,"Cuando las estrellas caigan,\nY el río corra pa arriba,\nEntonces te olvidaré,\nAdorada prenda mía.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,360,360,"138","",0,"","","",2,0,0,[],""],["carrizo_salta-n0139-01",3,"Cuando las estrellas caigan\nY el golpe se oiga en el cielo,\nDejarás de ser, vidita,\nLa prenda de mi consuelo.",3,1,0,43,"",0,4,"eo",10,0,-1,0,361,361,"139","",0,"","","",2,0,0,[],""],["carrizo_salta-n0140-01",3,"Cuando la veo venir,\nHasta Taima se me alegra.\nNo la salgo a recibir\nTemiendo las malas lenguas.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,361,361,"140","",0,"","","",1,0,0,[],""],["carrizo_salta-n0140-a-01",3,"Cuando te veo llegar,\nHasta el alma se me alegra.\nPero no salgo a toparte,\nTemiendo las malas lenguas.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,361,361,"140-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0141-01",3,"Cuando me fuí para abajo,\nAltos y bajos pisaba.\nAl acostarme en la cama\nNoche a noche la soñaba.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,361,361,"141","",0,"","","",4,0,0,[],""],["carrizo_salta-n0142-01",3,"Cuando me miran tus ojos,\nNiña, me quiero morir.\nNo me dejes de mirar\nAunque me mates al fin.",3,1,0,43,"",0,4,"i",-1,0,-1,0,361,361,"142","",0,"","","",1,0,0,[],""],["carrizo_salta-n0143-01",3,"Cuando me muera y me vaya\n\"'- ha poner una vela,\nque venga a su cama\nServir de centinela.",3,1,0,43,"",0,4,"ea",167,0,-1,0,361,361,"143","",0,"","","",1,0,0,[],""],["carrizo_salta-n0144-01",3,"Yo me paro a tu lado,\ninclina el corazón\ni. porque te quiero\ndico esta canción.",3,1,0,43,"",0,4,"o",31,0,-1,0,361,361,"144","",0,"","","",1,0,0,[],""],["carrizo_salta-n0146-01",3,"Cuando quiero, quiero mucho;\nCuando olvido, olvido luego;\nAntes de haberme querido,\nYo ya te quise primero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,361,361,"146","",0,"","","",2,0,0,[],""],["carrizo_salta-n0147-01",3,"Cuando sepa que se vaya,\nLa hi de seguir hasta Roma;\nSi no cumplo lo que digo,\nSe abra la tierra y me coma.",3,1,0,43,"",0,4,"oa",86,0,-1,0,361,361,"147","",0,"","","",1,0,0,[],""],["carrizo_salta-n0148-01",3,"Cuando supe tu venida\nMe puse color de grana,\nPorque por verte me salen\nLos colores a la cara.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,361,361,"148","",0,"","","",2,0,0,[],""],["carrizo_salta-n0149-01",3,"Cuando supe tu venida,\nSe alegraron mis oídos,\nAunque no vengas por verme,\nMe alegro que haigas venido.",3,1,0,43,"",0,4,"io",-1,0,-1,0,361,361,"149","",0,"","","",2,0,0,[],""],["carrizo_salta-n0150-01",3,"Cuando vine de mi tierra\nTe traje un ramo de flores,\nCon esas flores, vidita,\nJuntamos los corazones.",3,1,0,43,"",0,4,"oe",-1,0,-1,0,361,361,"150","",0,"","","",1,0,0,[],""],["carrizo_salta-n0151-01",3,"Cuantas vueltas dará l'agua\nPara llegar al molino,\nTantas vueltas daré yo\nPara dejar mi camino.",3,1,0,43,"",0,4,"io",199,0,-1,0,361,361,"151","",0,"","","",1,0,0,[],""],["carrizo_salta-n0152-01",3,"Cuántas veces por amarte,\nVine de noche y de día.\n¿Qué, no sabías maliciar\nEl amor que te tenía?",3,1,0,43,"",0,4,"ia",0,0,-1,0,361,361,"152","",0,"","","",4,0,0,[],""],["carrizo_salta-n0153-01",3,"¡Chacarera, chacarera!\n¡Cómo no t'hi querer yo!\nOjitos como aceitunas.\nBoca de clavel punzó.",3,1,0,43,"",0,4,"o",2,0,-1,0,361,361,"153","",0,"","","",13,0,0,[],""],["carrizo_salta-n0154-01",3,"Dame la mano, vidita,\nNo me la des con rigor,\nQue yo te daré la mía\nCon cinco dedos de amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,362,362,"154","",0,"","","",3,0,0,[],""],["carrizo_salta-n0154-a-01",3,"Dame la mano, vidita,\nNo me la des con rigor,\nQue yo te daré la mía\nY un juramento de amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,362,362,"154-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n0155-01",3,"Dame tu pañuelito,\nQue yo te lo marcaré,\nCon hilo de mil colores,\nÑatita, lo bordaré.",3,1,0,43,"",0,4,"e",77,0,-1,0,362,362,"155","",0,"","","",1,0,0,[],""],["carrizo_salta-n0156-01",3,"Dame un besito, mi alma,\nQue me iré al cielo;\nLos demonios se han muerto,\nYa no hay infierno.",3,1,0,43,"",6,4,"eo",-1,0,-1,0,362,362,"156","",0,"","","",1,0,0,[],""],["carrizo_salta-n0157-01",3,"De abajo salen las nubes,\nColoradas y rosadas;\nVidita, si me querís\nTapame con tu frazada.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,362,362,"157","",0,"","","",1,0,0,[],""],["carrizo_salta-n0158-01",3,"De adobe y techo de paja,\nTres varas por cuatro de ancho,\n¿Qué le parece, mi negra?\nTodo eso pa nuestro rancho...",3,1,0,43,"",0,4,"ao",380,0,-1,0,362,362,"158","",0,"","","",1,0,0,[],""],["carrizo_salta-n0159-01",3,"De aquí te vas, palomita.\n¿Cuándo será tu volver?\nVuelvas pal año, pal otro,\nSiempre tu dueño hi de ser.",3,1,0,43,"",0,4,"e",20,0,-1,0,362,362,"159","",0,"","","",1,0,0,[],""],["carrizo_salta-n0160-01",3,"Debajo de tu ventana,\nMe dió sueño y me dormí;\nMe despertaron los gallos,\nCantando el quiquiriquí.",3,1,0,43,"",0,4,"i",23,0,-1,0,362,362,"160","",0,"","","",29,0,0,[],""],["carrizo_salta-n0161-01",3,"Debajo de un sauce verde,\nMe sombrié a las doce un día,\nCon la mano en la quijada,\nPensando en ti, vida mía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,362,362,"161","",0,"","","",3,0,0,[],""],["carrizo_salta-n0162-01",3,"De cama tengo una palma,\nDe cabecera una flor,\nPa que duermamos los dos\nCon cariño y con amor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,362,362,"162","",0,"","","",1,0,0,[],""],["carrizo_salta-n0163-01",3,"Decime cómo te llamas\nPara escribirte un papel,\nSi no me dices tu nombre,\nEl mío te hi de poner.",3,1,0,43,"",0,4,"e",-1,0,-1,0,362,362,"163","",0,"","","",1,0,0,[],""],["carrizo_salta-n0164-01",3,"Decime nomás, vidita,\nDel mal que andas padeciendo,\nYo hi de romper imposibles,\nComo que te ando queriendo.",3,1,0,43,"",0,4,"eo",52,0,-1,0,362,362,"164","",0,"","","",1,0,0,[],""],["carrizo_salta-n0165-01",3,"Decís que me querís mucho,\nMucho sin comparación,\nQue es tu amor como la luna,\nComo los rayos del sol.",3,1,0,43,"",0,4,"o",-1,0,-1,0,362,362,"165","",0,"","","",1,0,0,[],""],["carrizo_salta-n0166-01",3,"¿De dónde nace esta flor?\n¿De qué jardín ha nacido?\nEn el jardín de Cupido\nNo he visto otra flor mejor.",3,1,0,43,"",11,4,"o",72,0,-1,0,362,362,"166","",0,"","","",1,0,0,[],""],["carrizo_salta-n0166-a-01",3,"De dónde sale esta flor?\n¿De qué jardín ha salido?\nNo hi visto tales colores,\nEn el jardín de Cupido.",3,1,0,43,"",0,4,"io",101,0,-1,0,363,363,"166-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0167-01",3,"De esta banda a l'otra banda,\nNo me canso de mirarla,\nPor ella se me va el alma,\nPero no me atrevo a hablarla.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,363,363,"167","",0,"","","",5,0,0,[],""],["carrizo_salta-n0168-01",3,"Dejá de llorar, paloma,\nYo te voy a cautivar,\nCuando te cases conmigo,\nLinda vida has de pasar.",3,1,0,43,"",0,4,"a",21,0,-1,0,363,363,"168","",0,"","","",1,0,0,[],""],["carrizo_salta-n0169-01",3,"Dejen de llorar mis ojos,\nQue en mí no cabe tristeza,\nPor pensar en su hermosura\nEl alma se me atraviesa.",3,1,0,43,"",0,4,"ea",201,0,-1,0,363,363,"169","",0,"","","",2,0,0,[],""],["carrizo_salta-n0170-01",3,"De la banda me divisan,\nTambién estoy divisando,\nComo son buenasmocitas,\nYa me estoy aficionando.",3,1,0,43,"",0,4,"ao",33,0,-1,0,363,363,"170","",0,"","","",1,0,0,[],""],["carrizo_salta-n0171-01",3,"la banda te traigo,\nRamo de olivo,\nA la prenda que quiero,\nNunca la olvido.",3,1,0,43,"",6,4,"io",-1,0,-1,0,363,363,"171","",0,"","","",1,0,0,[],""],["carrizo_salta-n0172-01",3,"De la loma redonda,\nVienen bajando,\nUnos ojos azules,\nDe contrabando.",3,1,0,43,"",6,4,"ao",33,0,-1,0,363,363,"172","",0,"","","",1,0,0,[],""],["carrizo_salta-n0173-01",3,"Del cielo nace una estrella\nY del paraíso una guía.\nNo pierdo las esperanzas\nDe ser tu dueño algún día.",3,1,0,43,"",3,4,"ia",0,0,-1,0,363,363,"173","",0,"","","",1,0,0,[],""],["carrizo_salta-n0174-01",3,"De las nubes se hace l'agua,\nDe l'agua se forma el río,\nSi me querís, mi vidita,\nDecí nomás, amor mío.",3,1,0,43,"",0,4,"io",3,0,-1,0,363,363,"174","",0,"","","",1,0,0,[],""],["carrizo_salta-n0175-01",3,"De lejos te estoy queriendo,\nDe cerca me pasa igual,\nEl recelo que yo tengo\nQue me quieras pagar mal.",3,1,0,43,"",0,4,"a",1,0,-1,0,363,363,"175","",0,"","","",1,0,0,[],""],["carrizo_salta-n0176-01",3,"De Lima más adelante,\nDonde le Uaman \"Tristeza\",\nDe ahi hi mandar una carta\nPara que veas mi firmeza.",3,1,0,43,"",0,4,"ea",108,0,-1,0,363,363,"176","",0,"","","",3,0,0,[],""],["carrizo_salta-n0176-a-01",3,"De Lima para delante,\nAhí lloraba mi tristeza,\nPorque te supe escribir\nUn papel lleno i firmeza.",3,1,0,43,"",0,4,"ea",108,0,-1,0,363,363,"176-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0177-01",3,"De lo ausente que yo anduve,\nVelay, ¿no vengo recién?\nEncadename a tus brazos,\nYa estoy de nuevo, mi bien.",3,1,0,43,"",0,4,"e",242,0,-1,0,363,363,"177","",0,"","","",1,0,0,[],""],["carrizo_salta-n0178-01",3,"De lo mucho que la quiero,\nUd. no sabrá dudar;\nSi no la tengo en los brazos,\nSerá por disimular.",3,1,0,43,"",0,4,"a",21,0,-1,0,363,363,"178","",0,"","","",1,0,0,[],""],["carrizo_salta-n0179-01",3,"De mi nombre yo soy rosa,\nY de apellido jardín.\nComo soy firme y constante,\nEn tus brazos daré fin.",3,1,0,43,"",0,4,"i",211,0,-1,0,363,363,"179","",0,"","","",1,0,0,[],""],["carrizo_salta-n0180-01",3,"De mi tierra m'hi venío,\nCansado de caminar,\nTanto te quiero, vidita,\nQue no te puedo olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,363,363,"180","",0,"","","",2,0,0,[],""],["carrizo_salta-n0182-01",3,"De noche te contemplaba,\nEn medio la oscuridad,\nY cuando abriste los ojos,\nTodo comenzó a brillar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,364,364,"182","",0,"","","",1,0,0,[],""],["carrizo_salta-n0183-01",3,"Dende arriba m'hi venío,\nComo paja por el aire.\nPara ver a mi vidita,\nDesde Salta a Buenos Aires.",3,1,0,43,"",0,4,"ae",-1,0,-1,0,364,364,"183","",0,"","","",1,0,0,[],""],["carrizo_salta-n0184-01",3,"De olvidarte no lo dudes,\nSerá sólo con la muerte,\nSerá cuando me sepulte,\nLa ingratitud de la suerte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,364,364,"184","",0,"","","",1,0,0,[],""],["carrizo_salta-n0185-01",3,"¿De qué monte habrá salido\nEsta paloma tan bella?\nQuisiera hallarla sólita,\nPara conversar con ella.",3,1,0,43,"",0,4,"ea",6,0,-1,0,364,364,"185","",0,"","","",1,0,0,[],""],["carrizo_salta-n0186-01",3,"Deseando estoy que llegue\nEl día de nuestra unión,\nPara estrecharte en mis brazos,\nPrenda de mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,364,364,"186","",0,"","","",1,0,0,[],""],["carrizo_salta-n0187-01",3,"Desde antes de conocerte,\nYa me enamoré de ti.\nMe vine sólo por verte,\nPor tu amor me vine aquí.",3,1,0,43,"",1,4,"i",23,0,-1,0,364,364,"187","",0,"","","",1,0,0,[],""],["carrizo_salta-n0188-01",3,"Desde arriba me he venío\nSin poderme detener,\nSólo aquí m' hi detenio,\nA tomar su parecer.",3,1,0,43,"",0,4,"e",20,0,-1,0,364,364,"188","",0,"","","",1,0,0,[],""],["carrizo_salta-n0189-01",3,"Desde arriba m' hi venío\nAcabando mis trabajos,\nNo sé qué gusto me da\nCuando yo me hallo en tus brazos.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,364,364,"189","",0,"","","",17,0,0,[],""],["carrizo_salta-n0190-01",3,"Desde arriba m' hi venío\nComo paloma torcaza,\nDerechito m' hi venío,\nMi señorita, a su casa.",3,1,0,43,"",1,4,"aa",123,0,-1,0,364,364,"190","",0,"","","",17,0,0,[],""],["carrizo_salta-n0191-01",3,"Desde arriba m' hi venío,\nCon ganas de darte un beso;\nNo te vayas a enojar,\nPorque yo te diga eso.",3,1,0,43,"",0,4,"eo",48,0,-1,0,364,364,"191","",0,"","","",17,0,0,[],""],["carrizo_salta-n0192-01",3,"Desde arriba m' hi venío\nPorque estaba muy solito,\nY tuve la suerte buena\nDe ver mi corazoncito.",3,1,0,43,"",0,4,"io",119,0,-1,0,364,364,"192","",0,"","","",17,0,0,[],""],["carrizo_salta-n0193-01",3,"Desde mi pago hi venío,\nCaminando noche y día.\nDespreciando mi bandera\nPor tus brazos, vida mía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,364,364,"193","",0,"","","",6,0,0,[],""],["carrizo_salta-n0194-01",3,"Desde que fui chiquitito,\nMi mamita me enseñó\nQue buscara una niñita,\nTan bonita como vos.",3,1,0,43,"",0,4,"o",-1,0,-1,0,364,364,"194","",0,"","","",1,0,0,[],""],["carrizo_salta-n0195-01",3,"¡Despierta, dueña querida!\nDe ese tu sueño profundo;\nMientras vos estás dormida\nVivo penando en el mundo.",3,1,0,43,"",1,4,"uo",179,0,-1,0,364,364,"195","",0,"","","",1,0,0,[],""],["carrizo_salta-n0196-01",3,"¡Despierta, prenda querida!\nDeja tu profundo sueño,\nQuien te viene a despertar,\nPretende de ser tu dueño.",3,1,0,43,"",0,4,"eo",138,0,-1,0,364,364,"196","",0,"","","",1,0,0,[],""],["carrizo_salta-n0205-01",3,"Dicen que el veneno mata,\nY también mata el puñal,\nLos ojitos de tu cielo,\nMe quieren asesinar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,365,365,"205","",0,"","","",1,0,0,[],""],["carrizo_salta-n0206-01",3,"Dicen que la agua del mar,\nSe junta con la del río,\nAsí también se ha i juntar\nTu corazón con el mío.",3,1,0,43,"",1,4,"io",3,0,-1,0,365,365,"206","",0,"","","",1,0,0,[],""],["carrizo_salta-n0207-01",3,"Dicen que los negros,\nSon de chocolate.\nPor una morena,\nMi corazón late.",3,1,0,43,"",0,4,"ae",384,0,-1,0,365,365,"207","",0,"","","",1,0,0,[],""],["carrizo_salta-n0208-01",3,"Dicen que no la conocen\nA la flor de verdolaga,\n¿Quién no la va a conocer,\nSi es tan linda y colorada?",3,1,0,43,"",0,4,"aa",-1,0,-1,0,365,365,"208","",0,"","","",1,0,0,[],""],["carrizo_salta-n0209-01",3,"Dicen que tus manos pinchan,\nPara mí son amorosas,\nTambién pinchan los rosales\nCuando le cortan las rosas.",3,1,0,43,"",0,4,"oa",61,0,-1,0,365,365,"209","",0,"","","",1,0,0,[],""],["carrizo_salta-n0210-01",3,"Dicen que las muchachas,\nDe quince a veinte,\nSon iguales que el dulce:\nPican los dientes.",3,1,0,43,"",6,4,"ee",-1,0,-1,0,365,365,"210","",0,"","","",1,0,0,[],""],["carrizo_salta-n0211-01",3,"Dicen y no digo quién,\nQue pincha mucho el abrojo.\n¡Malhaya, pincha también\nLa lanza que hay en tus ojos!",3,1,0,43,"",0,4,"oo",-1,0,-1,0,365,365,"211","",0,"","","",1,0,0,[],""],["carrizo_salta-n0212-01",3,"Dice que me quiere mucho,\nYo también l'ando queriendo,\nSe casemos de una vez,\nDejemos de andar sufriendo.",3,1,0,43,"",0,4,"eo",52,0,-1,0,365,365,"212","",0,"","","",2,0,0,[],""],["carrizo_salta-n0213-01",3,"Dices que no me quieres,\nYa lo voy viendo;\nA lo desimulado,\nMe vas queriendo.",3,1,0,43,"",6,4,"eo",52,0,-1,0,366,366,"213","",0,"","","",15,0,0,[],""],["carrizo_salta-n0214-01",3,"Dios se los pague, señora;\nDios se los ha de pagar,\nLos recuerdos que de mí ha hecho,\nCon tan fina voluntad.",3,1,0,43,"",0,4,"a",-1,0,-1,0,366,366,"214","",0,"","","",1,0,0,[],""],["carrizo_salta-n0215-01",3,"Dios se lo pague, señora,\nEl cariño que usted me ha hecho;\nEn gratitud de su obsequio,\nLa retrataré en mi pecho.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,366,366,"215","",0,"","","",2,0,0,[],""],["carrizo_salta-n0216-01",3,"Donocita, bonita,\nTe vas criando,\nComo sos de mi gusto,\nTe voy dejando.",3,1,0,43,"",6,4,"ao",33,0,-1,0,366,366,"216","",0,"","","",1,0,0,[],""],["carrizo_salta-n0217-01",3,"Dos claveles tengo en agua,\nPor los dos tengo pasión,\nPor fulano, doy la vida;\nPor zutano, el corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,366,366,"217","",0,"","","",1,0,0,[],""],["carrizo_salta-n0218-01",3,"Dos pensamientos te mando,\nDos pensamientos te envío,\nUn pensamiento pintado,\nEn el pensamiento mío.",3,1,0,43,"",0,4,"io",3,0,-1,0,366,366,"218","",0,"","","",1,0,0,[],""],["carrizo_salta-n0219-01",3,"Dos plantitas de claveles,\nMi vida, tus ojos son.\nQuereme firme, bien mío,\nComo yo te quiero a vos.",3,1,0,43,"",0,4,"o",-1,0,-1,0,366,366,"219","",0,"","","",1,0,0,[],""],["carrizo_salta-n0220-01",3,"El alma que tengo es tuya,\nEso no puedes dudar,\nQue si presente te quiero,\nAusente te quiero más.",3,1,0,43,"",0,4,"a",-1,0,-1,0,366,366,"220","",0,"","","",4,0,0,[],""],["carrizo_salta-n0221-01",3,"El amor que yo te tengo\nJamás lo profanaré;\nAunque vivo, aunque muerto,\nEn tus brazos moriré.",3,1,0,43,"",0,4,"e",77,0,-1,0,366,366,"221","",0,"","","",4,0,0,[],""],["carrizo_salta-n0222-01",3,"El amor que yo te tengo,\nNo se parece a ninguno,\nMe cabe dentro del alma\nY no cabe en este mundo.",3,1,0,43,"",0,4,"uo",-1,0,-1,0,366,366,"222","",0,"","","",4,0,0,[],""],["carrizo_salta-n0223-01",3,"El árbol para el invierno,\nCarece de su verdura,\nAsí lo carezco yo\nPor gozar de su hermosura.",3,1,0,43,"",0,4,"ua",17,0,-1,0,366,366,"223","",0,"","","",1,0,0,[],""],["carrizo_salta-n0224-01",3,"El camino de tu casa,\nMe lo cerraron un trecho.\nYo hi de ver modos de hablarte,\nBuscando por lo deshecho.",3,1,0,43,"",0,4,"eo",60,0,-1,0,366,366,"224","",0,"","","",1,0,0,[],""],["carrizo_salta-n0225-01",3,"El día que tú naciste,\nDe gala se vistió el sol,\nHubo una fiesta en el cielo,\nY hasta el mismo Dios bailó.",3,1,0,43,"",0,4,"o",-1,0,-1,0,366,366,"225","",0,"","","",16,0,0,[],""],["carrizo_salta-n0226-01",3,"El día que tú nacistes,\nAquel día nací yo.\nEl día que tú te mueras,\nNos moriremos los dos.",3,1,0,43,"",0,4,"o",-1,0,-1,0,366,366,"226","",0,"rm_t2","","",7,0,0,[],""],["carrizo_salta-n0234-01",3,"En amarte goza el alma,\nEn quererte está mi ley,\nToda mi gloria es mirarte,\nY verte es todo mi bien.",3,1,0,43,"",0,4,"e",-1,0,-1,0,367,367,"234","",0,"","","",2,0,0,[],""],["carrizo_salta-n0235-01",3,"¡Encanto del alma mía!\n¡Dulce cielo de mi antojo!\nNo permitas que yo muera\nAusente de vuestros ojos.",3,1,0,43,"",0,4,"oo",-1,0,-1,0,367,367,"235","",0,"","","",1,0,0,[],""],["carrizo_salta-n0236-01",3,"En el año nuevo nacen\nFlores en gran variedad.\nPara mí, las del olvido;\nPara usted, felicidad.",3,1,0,43,"",0,4,"a",16,0,-1,0,367,367,"236","",0,"","","",1,0,0,[],""],["carrizo_salta-n0237-01",3,"En el campo hay una yerba,\nUna yerba con su flor,\nLinda es tu cara, vidita,\nTus ojitos son mi amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,367,367,"237","",0,"","","",2,0,0,[],""],["carrizo_salta-n0238-01",3,"En el campo nacen flores,\nEn las fuentes agua clara,\nPero el jardín superior,\nEstá, vidita, en tu cara.",3,1,0,43,"",0,4,"aa",57,0,-1,0,367,367,"238","",0,"","","",1,0,0,[],""],["carrizo_salta-n0239-01",3,"En el centro de la mar,\nHa florecido una higuera,\nDe todo me privarán\nMenos de que yo la quiera.",3,1,0,43,"",0,4,"ea",44,0,-1,0,367,367,"239","",0,"","","",7,0,0,[],""],["carrizo_salta-n0240-01",3,"En el centro de la mar\nTengo una caja con llave,\nQue todos quieren entrar,\nSólo tu persona cabe.",3,1,0,43,"",1,4,"ae",131,0,-1,0,367,367,"240","",0,"","","",7,0,0,[],""],["carrizo_salta-n0241-01",3,"En esta casita,\nAzucenas crece,\nLa dueña de casa,\nCorona merece.",3,1,0,43,"",0,4,"ee",64,0,-1,0,368,368,"241","",0,"","","",1,0,0,[],""],["carrizo_salta-n0242-01",3,"En esta noche serena,\nQue no se oye ni un ruido,\nA cantarte, palomita,\nMi dulce amor me ha traído.",3,1,0,43,"",0,4,"io",101,0,-1,0,368,368,"242","",0,"","","",1,0,0,[],""],["carrizo_salta-n0243-01",3,"En este Santa María,\nMás tengo gusto que penas,\nPara cantarte quisiera\nTener eco de sirena.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,368,368,"243","",0,"","","",2,0,0,[],""],["carrizo_salta-n0244-01",3,"En este Santa María\n¿Qué más le puedo decir?\nSi Ud. sufre un imposible,\nYo le ayudaré a sentir.",3,1,0,43,"",0,4,"i",157,0,-1,0,368,368,"244","",0,"","","",2,0,0,[],""],["carrizo_salta-n0245-01",3,"Enfermo estoy en la cama,\nMi enfermedad es de pena,\nY sanaré si me cura,\nEsa mocita morena.",3,1,0,43,"",0,4,"ea",59,0,-1,0,368,368,"245","",0,"","","",3,0,0,[],""],["carrizo_salta-n0246-01",3,"En invierno no hay claveles,\nPorque los marchita el hielo,\nEn tu cara los hay siempre,\nAsí lo permite el cielo.",3,1,0,43,"",0,4,"eo",10,0,-1,0,368,368,"246","",0,"","","",1,0,0,[],""],["carrizo_salta-n0246-02",3,"En la cara tengo pecas,\nEn la garganta un lunar,\nEn señas de que te quiero,\nMe vengo yo a este lugar.",3,1,0,43,"",0,4,"a",21,0,-1,0,368,368,"246","",0,"","","",3,0,0,[],""],["carrizo_salta-n0246-03",3,"En la cara tengo pecas,\nEn la garganta un lunar,\nSólo por venirte a ver\nMe encuentro en este lugar.",3,1,0,43,"",0,4,"a",21,0,-1,0,368,368,"246","",0,"","","",3,0,0,[],""],["carrizo_salta-n0248-01",3,"En la cara tienes pecas,\nEn la garganta un lunar,\nY los ojitos me dicen:\n—Yo te quiero a vos nomás.",3,1,0,43,"",0,4,"a",-1,0,-1,0,368,368,"248","",0,"","","",1,0,0,[],""],["carrizo_salta-n0249-01",3,"En la falda de aquel cerro,\nPasa garva y aguacero,\nAbrazame con tus brazos,\nTapame con tu pañuelo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,368,368,"249","",0,"","","",54,0,0,[],""],["carrizo_salta-n0250-01",3,"En la huerta de mi casa,\nTengo un zapallar hermoso,\nPa convidarle a mi negra,\nCuando yo sea su esposo.",3,1,0,43,"",0,4,"oo",160,0,-1,0,368,368,"250","",0,"","","",1,0,0,[],""],["carrizo_salta-n0251-01",3,"En la puerta de su casa\nLe dejé un letrero escrito:\n\"Hagamos suerte, señora,\nUd. es sola y yo solito\".",3,1,0,43,"",0,4,"io",119,0,-1,0,368,368,"251","",0,"","","",1,0,0,[],""],["carrizo_salta-n0252-01",3,"En las montañas soy tigre,\nEn los campos soy león,\nQuisiera estar en su pecho,\nRobarle su corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,369,369,"252","",0,"","","",1,0,0,[],""],["carrizo_salta-n0253-01",3,"En mí no has de hallar mudanza,\nPorque te supe querer,\nCuantos más años se paser.,\nMás constante te he de ser.",3,1,0,43,"",0,4,"e",20,0,-1,0,369,369,"253","",0,"","","",1,0,0,[],""],["carrizo_salta-n0254-01",3,"En mi pensamiento tengo,\nTu pensamiento visible,\n¡Vidita, para olvidarte,\nTodo se me hace imposible!",3,1,0,43,"",0,4,"ie",259,0,-1,0,369,369,"254","",0,"","","",1,0,0,[],""],["carrizo_salta-n0255-01",3,"En mí sólo has de encontrar\nTres cosas en abundancia:\nAmor y mucha firmeza\nY demasiada constancia.",3,1,0,43,"",0,4,"aa",340,0,-1,0,369,369,"255","",0,"","","",1,0,0,[],""],["carrizo_salta-n0256-01",3,"En papel blanco te escribo,\nPorque blanca fué mi suerte,\nConste que t' hi de querer\nHasta que venga la muerte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,369,369,"256","",0,"","","",7,0,0,[],""],["carrizo_salta-n0257-01",3,"En qué topa que no dentra?\nEn qué tabla de marfil?\nSi en sus brazos me tuviera\nEn sus brazos diera fin.",3,1,0,43,"",0,4,"i",-1,0,-1,0,369,369,"257","",0,"","","",1,0,0,[],""],["carrizo_salta-n0258-01",3,"En su cariño me empeño,\nYa le tengo simpatía,\nDispuesta está el alma mía\nEn que usted sea mi dueño.",3,1,0,43,"",11,4,"eo",138,0,-1,0,369,369,"258","",0,"","","",1,0,0,[],""],["carrizo_salta-n0259-01",3,"Entre cortinas ocultas,\nDos niñas me tienen loco,\nQue ocultas en tus pestañas,\nLas dos niñas de tus ojos.",3,1,0,43,"",0,4,"oo",-1,0,-1,0,369,369,"259","",0,"","","",1,0,0,[],""],["carrizo_salta-n0260-01",3,"Entre dos jardines me hallo,\nNinguna flor me divierte,\nAunque mil amores me hagan\nNo puedo vivir sin verte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,369,369,"260","",0,"","","",1,0,0,[],""],["carrizo_salta-n0261-01",3,"En vano con la distancia,\nPiensas mi pasión calmar.\nEste pecho no conoce\nRemedio para olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,369,369,"261","",0,"","","",1,0,0,[],""],["carrizo_salta-n0262-01",3,"Envidia tengo a la luna,\nY envidia le tengo al sol,\nPorque ven de noche y día,\nLo que no puedo ver yo.",3,1,0,43,"",0,4,"o",-1,0,-1,0,369,369,"262","",0,"","","",1,0,0,[],""],["carrizo_salta-n0263-01",3,"Eres águila real,\nEn el pico llevas flores,\nEn las alas azucenas,\nY en el corazón, amores.",3,1,0,43,"",0,4,"oe",5,0,-1,0,369,369,"263","",0,"","","",5,0,0,[],""],["carrizo_salta-n0264-01",3,"Eres alta y bizarra,\nDelgada y lisa,\nEres como la vara,\nDe la Justicia.",3,1,0,43,"",6,4,"ia",-1,0,-1,0,369,369,"264","",0,"","","",1,0,0,[],""],["carrizo_salta-n0265-01",3,"Eres chiquita y bonita,\nAsí como yo te quiero,\nComo si fueras chispita,\nQue salta de mi yesquero.",3,1,0,43,"",1,4,"eo",38,0,-1,0,369,369,"265","",0,"","","",12,0,0,[],""],["carrizo_salta-n0266-01",3,"Eres fragante azucena,\nRosa que cautiva el alma,\nNardo blanco del desierto,\nEncanto del que te ama.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,369,369,"266","",0,"","","",1,0,0,[],""],["carrizo_salta-n0267-01",3,"Eres un grano de arroz,\nEres un bello jazmín,\nEres la rosa fragante,\nDel más hermoso jardín.",3,1,0,43,"",0,4,"i",211,0,-1,0,369,369,"267","",0,"","","",1,0,0,[],""],["carrizo_salta-n0268-01",3,"Esa tu cara bonita,\nY tu esmerada presencia,\nNunca la podré olvidar,\nAunque sea larga mi ausencia.",3,1,0,43,"",0,4,"ea",46,0,-1,0,370,370,"268","",0,"","","",1,0,0,[],""],["carrizo_salta-n0269-01",3,"Es cierto que te he querido,\nY siempre te estoy queriendo.\nEl amor que te he tenido,\nEl mismo te estoy teniendo.",3,1,0,43,"",1,4,"eo",52,0,-1,0,370,370,"269","",0,"","","",7,0,0,[],""],["carrizo_salta-n0270-01",3,"Es el amor, mi vida,\nComo una sombra,\nQue mientras más se aleja,\nMás cuerpo toma.",3,1,0,43,"",6,4,"oa",-1,0,-1,0,370,370,"270","",0,"","","",1,0,0,[],""],["carrizo_salta-n0271-01",3,"Es más hermosa, vidita,\nQue el sol de la mañanita,\nA la niña de mis ojos,\nVd. es el viento que agita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,370,370,"271","",0,"","","",1,0,0,[],""],["carrizo_salta-n0272-01",3,"Esos cabellitos rubios,\nQue te caen a la frente,\nParecen campanas de oro\nQue llaman toda la gente.",3,1,0,43,"",0,4,"ee",15,0,-1,0,370,370,"272","",0,"","","",1,0,0,[],""],["carrizo_salta-n0273-01",3,"Esos tus crespos cabellos,\nQue le caen a la cara,\nSon como rayos de sol,\nQue salen por la mañana.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,370,370,"273","",0,"","","",1,0,0,[],""],["carrizo_salta-n0274-01",3,"Esperate, prenda amada,\nVoy a sacar esta flor,\nPueda ser que en ella encuentre,\nLa llave del corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,370,370,"274","",0,"","","",1,0,0,[],""],["carrizo_salta-n0275-01",3,"Es tanto lo que te adoro,\nQue te quiero colocar,\nEn un pabellón de nubes,\nY en un trono de cristal.",3,1,0,43,"",0,4,"a",-1,0,-1,0,370,370,"275","",0,"","","",2,0,0,[],""],["carrizo_salta-n0276-01",3,"Es tanto lo que te adoro,\nY es tanto lo que te quiero,\nQue si me sacan los ojos,\nT' hi mirar por los aujeros.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,370,370,"276","",0,"","","",2,0,0,[],""],["carrizo_salta-n0277-01",3,"Es tanto lo que te quiero,\nQue te quisiera llevar,\nEn ancas de mi caballo,\nCuando deje este lugar.",3,1,0,43,"",0,4,"a",21,0,-1,0,370,370,"277","",0,"","","",26,0,0,[],""],["carrizo_salta-n0278-01",3,"Es tanto lo que te quiero,\nY te tengo tanto amor,\nQue estoy por abrirme el pecho\nY entregarte el corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,370,370,"278","",0,"","","",26,0,0,[],""],["carrizo_salta-n0279-01",3,"Es tanto lo que te quiero,\nY lo que te quiero es tanto,\nQue ángeles y querubines,\nDicen: ¡Santo, Santo, Santo!",3,1,0,43,"",0,4,"ao",30,0,-1,0,370,370,"279","",0,"","","",26,0,0,[],""],["carrizo_salta-n0280-01",3,"Es tanto lo que la quiero,\nY no la puedo olvidar,\nQue salgo a buscar olvido,\nVuelvo con más voluntad.",3,1,0,43,"",0,4,"a",-1,0,-1,0,370,370,"280","",0,"","","",1,0,0,[],""],["carrizo_salta-n0281-01",3,"Estas son las flores blancas,\nSacadas de San Andrés,\n—¡Dame la mano, vidita,\nSeguiremos otra vez!",3,1,0,43,"",0,4,"e",150,0,-1,0,370,370,"281","",0,"","","",1,0,0,[],""],["carrizo_salta-n0282-01",3,"¡Estrella del alto cielo,\nQue alumbras lo más profundo!\nNo t' hi dejar de querer,\nAunque sepa todo el mundo.",3,1,0,43,"",0,4,"uo",179,0,-1,0,370,370,"282","",0,"","","",2,0,0,[],""],["carrizo_salta-n0283-01",3,"Estrellas del alto cielo,\nPiedritas del ancho mar,\nPara tí, mi corazón,\nY jamás t' hi de olvidar.",3,1,0,43,"",0,4,"a",21,0,-1,0,370,370,"283","",0,"","","",6,0,0,[],""],["carrizo_salta-n0283-02",3,"Estrellas y lucero\nVan con la luna,\nPero como tu cara,\nNo va ninguna.",3,1,0,43,"",6,4,"ua",56,0,-1,0,371,371,"283","",0,"","","",1,0,0,[],""],["carrizo_salta-n0283-03",3,"Estrellita reluciente,\nFlorcita la más fragante,\nOiga mis tristes amores,\nYo quisiera ser su amante.",3,1,0,43,"",0,4,"ae",47,0,-1,0,371,371,"283","",0,"","","",11,0,0,[],""],["carrizo_salta-n0283-04",3,"Es tu cara una hermosura,\nTus ojos son unos soles.\n¿Aún teniendo este tesoro\nTe quejas de que eres pobre?",3,1,0,43,"",0,4,"oe",-1,0,-1,0,371,371,"283","",0,"","","",1,0,0,[],""],["carrizo_salta-n0287-02",3,"Florcita de arca,\nFlorcita de arca,\nOjitos lindos,\nDe Catamarca.",3,1,0,43,"",6,4,"aa",395,0,-1,0,371,371,"287","",0,"","","",1,0,0,[],""],["carrizo_salta-n0287-03",3,"Florcita i clavel celeste,\nDecís que no me querís.\nDebalde, yo te hi buscar,\nAunque la vida me cueste.",3,1,0,43,"",5,4,"ee",396,0,-1,0,371,371,"287","",0,"","","",1,0,0,[],""],["carrizo_salta-n0290-01",3,"Florcita i laurel,\nFlorcita i laurel,\nEn medio tus brazos,\nMe quisiera ver.",3,1,0,43,"",0,4,"e",-1,0,-1,0,371,371,"290","",0,"","","",1,0,0,[],""],["carrizo_salta-n0291-01",3,"Flor de azucena,\nRojo clavel,\nFirme y constante,\nT' hi venido a ver.",3,1,0,43,"",6,4,"e",-1,0,-1,0,371,371,"291","",0,"","","",1,0,0,[],""],["carrizo_salta-n0292-01",3,"Flor del aire,\nFlor del aire,\nLinda la moza,\nDe Buenos Aires.",3,1,0,43,"",3,4,"ae",-1,0,-1,0,371,371,"292","",0,"","","",1,0,0,[],""],["carrizo_salta-n0293-01",3,"Flor de lampazo,\nFlor de lampazo,\nDate una vuelta,\nDame un abrazo.",3,1,0,43,"",6,4,"ao",43,0,-1,0,371,371,"293","",0,"","","",2,0,0,[],""],["carrizo_salta-n0294-01",3,"Flor de molle,\nFlor de molle,\nSe hace la sorda,\nY no me oye.",3,1,0,43,"",3,4,"oe",397,0,-1,0,371,371,"294","",0,"","","",1,0,0,[],""],["carrizo_salta-n0295-01",3,"Flores he visto en el mundo,\nNinguna me ha cautivado,\nSólo la que vi en tu pecho,\nAl mío lo ha traspasado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,371,371,"295","",0,"","","",1,0,0,[],""],["carrizo_salta-n0296-01",3,"Flores hi visto en el mundo,\nNinguna me ha cautivado,\nUna que hi visto recién,\nSin corazón me ha dejado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,371,371,"296","",0,"","","",1,0,0,[],""],["carrizo_salta-n0297-01",3,"¡Golondrina pasajera!\nPasas la mar de un volido,\nYo también la pasaría,\nEn alas de tu cariño.",3,1,0,43,"",0,4,"io",-1,0,-1,0,371,371,"297","",0,"","","",1,0,0,[],""],["carrizo_salta-n0298-01",3,"Gracias a Dios que t' hi visto,\nAsí puedo consolarme,\nCon la ausencia de tu cielo,\nLa vida quiero quitarme.",3,1,0,43,"",0,4,"ae",35,0,-1,0,372,372,"298","",0,"","","",1,0,0,[],""],["carrizo_salta-n0299-01",3,"Guardate de mis suspiros,\nSi los sentís caminar,\nMis suspiros llevan fuego,\nY te pueden abrasar.",3,1,0,43,"",0,4,"a",21,0,-1,0,372,372,"299","",0,"","","",3,0,0,[],""],["carrizo_salta-n0299-a-01",3,"Guardate de mis suspiros,\nSi los sientes caminar,\nPorque llevan mucha fuerza,\nY te pueden abrasar.",3,1,0,43,"",0,4,"a",21,0,-1,0,372,372,"299-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n0300-01",3,"Hace tiempo que quería,\nPedirte un beso, mi ñata,\nPero jamás me animaba,\nPorque el valor me hacía falta.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,372,372,"300","",0,"","","",2,0,0,[],""],["carrizo_salta-n0301-01",3,"Han dicho los envidiosos,\nQue nadita nos querimos,\nLágrimas nos va a costar,\nPara que nos separimos.",3,1,0,43,"",0,4,"io",329,0,-1,0,372,372,"301","",0,"","","",1,0,0,[],""],["carrizo_salta-n0302-01",3,"Haré constar que la quiero,\nCon documento y recibo,\nY después de autorizado,\nMatemé si no le sirvo.",3,1,0,43,"",0,4,"io",-1,0,-1,0,372,372,"302","",0,"","","",1,0,0,[],""],["carrizo_salta-n0303-01",3,"Hay flores en mi jardín,\nLindas, de mucha frescura;\nPero no hi podido hallar,\nUna igual a tu hermosura.",3,1,0,43,"",0,4,"ua",17,0,-1,0,372,372,"303","",0,"","","",1,0,0,[],""],["carrizo_salta-n0304-01",3,"Hay ojos que miran mucho,\nHay ojos que miran poco,\nHay ojos que dan la vida,\nHay ojos que vuelven loco.",3,1,0,43,"",0,4,"oo",152,0,-1,0,372,372,"304","",0,"","","",1,0,0,[],""],["carrizo_salta-n0305-01",3,"Hay una estrella en el cielo,\nQue me llama la atención,\nHay una flor en la tierra,\nQue me parte el corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,372,372,"305","",0,"","","",2,0,0,[],""],["carrizo_salta-n0306-01",3,"¡Hermosa planta!\n¡Preciosa flor!\nQuiero dejarte,\nY otra vez, no.",3,1,0,43,"",6,4,"o",-1,0,-1,0,372,372,"306","",0,"","","",1,0,0,[],""],["carrizo_salta-n0307-01",3,"Hojitas verdes de sauce,\nHojas verdes de nogal,\nAl cabo han visto mis ojos,\nLo que me sabían negar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,372,372,"307","",0,"","","",1,0,0,[],""],["carrizo_salta-n0308-01",3,"La hi llegado a querer tanto,\nQue jamás la hi de olvidar,\nPrimero h'i perder la vida,\nQue yo dejarla de amar.",3,1,0,43,"",0,4,"a",21,0,-1,0,372,372,"308","",0,"","","",1,0,0,[],""],["carrizo_salta-n0309-01",3,"La inclinación a quererla,\nMe tiene fuera de mí,\nY la miro con anhelo,\nDesde el día que la ví.",3,1,0,43,"",0,4,"i",23,0,-1,0,372,372,"309","",0,"","","",1,0,0,[],""],["carrizo_salta-n0310-01",3,"La luna por el cielo,\nVa serenita,\nAsí va por la calle,\nMi morenita.",3,1,0,43,"",6,4,"ia",50,0,-1,0,372,372,"310","",0,"rm_t2, palau_cantares","","",3,0,0,[],""],["carrizo_salta-n0311-01",3,"La naranja para Vd.,\nLa cáscara para mí,\nDesde mi pago hi venío\nDirigido para tí.",3,1,0,43,"",0,4,"i",23,0,-1,0,373,373,"311","",0,"","","",1,0,0,[],""],["carrizo_salta-n0312-01",3,"La primer vez que te víde,\nEn vos puse la afición.\nPor eso vivo pensando,\nQué dice tu corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,373,373,"312","",0,"","","",1,0,0,[],""],["carrizo_salta-n0313-01",3,"La primer vez que te ví,\nTe ví como una rosita,\nY ahora te estoy rogando,\nComo a la Virgen bendita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,373,373,"313","",0,"","","",7,0,0,[],""],["carrizo_salta-n0314-01",3,"La prueba de que te quiero,\nEs que no te digo nada,\nLos amores siempre nacen,\nSon la lengua atravesada.",3,1,0,43,"",0,4,"aa",49,0,-1,0,373,373,"314","",0,"","","",1,0,0,[],""],["carrizo_salta-n0315-01",3,"Las estrellas en el cielo,\nCaminan del sol en pos,\nAsí caminando voy,\nTodas las noches por vos.",3,1,0,43,"",0,4,"o",-1,0,-1,0,373,373,"315","",0,"","","",18,0,0,[],""],["carrizo_salta-n0316-01",3,"Las estrellas en el cielo,\nCaminan pasito a paso,\nAsí hi de caminar yo,\nDe rodillas a tus brazos.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,373,373,"316","",0,"","","",18,0,0,[],""],["carrizo_salta-n0317-01",3,"Las estrellas en el cielo,\nLas cuento y no están cabales,\nFaltan sus ojos, vidita,\nQue son las dos principales.",3,1,0,43,"",0,4,"ae",26,0,-1,0,373,373,"317","",0,"","","",18,0,0,[],""],["carrizo_salta-n0318-01",3,"Las estrellitas del cielo,\nQue están alumbrando a Dios,\nNunca habrán querido tanto,\nComo yo te quiero a vos.",3,1,0,43,"",0,4,"o",87,0,-1,0,373,373,"318","",0,"","","",25,0,0,[],""],["carrizo_salta-n0319-01",3,"Las flores, como las hojas,\nNacen en el arbolar,\nCon tus amores, vidita,\nYo me quiero consolar.",3,1,0,43,"",0,4,"a",21,0,-1,0,373,373,"319","",0,"","","",1,0,0,[],""],["carrizo_salta-n0320-01",3,"La sombra de tu hermosura,\nMe has de dar para tener,\nQue me sirva de consuelo,\nCuando no te pueda ver.",3,1,0,43,"",0,4,"e",20,0,-1,0,373,373,"320","",0,"","","",1,0,0,[],""],["carrizo_salta-n0321-01",3,"Las rosas de tus mejillas,\nRosas sin espinas son,\nClavadas las tengo todas,\nDentro de mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,373,373,"321","",0,"","","",1,0,0,[],""],["carrizo_salta-n0322-01",3,"La tengo comparadita,\nCon las piedras de la calle,\nQue las pisa todo el mundo,\nSin dar las quejas a nadie.",3,1,0,43,"",0,4,"ae",-1,0,-1,0,373,373,"322","",0,"","","",1,0,0,[],""],["carrizo_salta-n0323-01",3,"La vergüenza me retira,\nY tu amor me hace llegar,\n¡Cómo será que te quiero,\nQue no te puedo olvidar!",3,1,0,43,"",0,4,"a",21,0,-1,0,373,373,"323","",0,"","","",1,0,0,[],""],["carrizo_salta-n0324-01",3,"Lejos de tí todo es triste,\nMi vida es un cautiverio,\nDe luto mi alma se viste,\nMi pecho es un cementerio.",3,1,0,43,"",1,4,"eo",398,0,-1,0,373,373,"324","",0,"","","",1,0,0,[],""],["carrizo_salta-n0325-01",3,"Lejos de tí, vida mía,\nMientras viva lloraré,\nY hasta mi última agonía,\nTu nombre pronunciaré.",3,1,0,43,"",1,4,"e",77,0,-1,0,374,374,"325","",0,"","","",4,0,0,[],""],["carrizo_salta-n0325-a-01",3,"Lejos de tí, vida mía,\nMientras viva lloraré,\nAunque me lleve la muerte,\nDe vos no me olvidaré.",3,1,0,43,"",0,4,"e",77,0,-1,0,374,374,"325-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n0326-01",3,"Lejos de tí, vida mía,\nSiempre llorando estaré,\nHaciendo mis ojos mares,\nCon mi vida acabaré.",3,1,0,43,"",0,4,"e",77,0,-1,0,374,374,"326","",0,"","","",4,0,0,[],""],["carrizo_salta-n0327-01",3,"Le pregunté a una gitana,\nDe qué mal me moriría,\nY la gitana, me dijo:\nDel amor que te tenía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,374,374,"327","",0,"","","",1,0,0,[],""],["carrizo_salta-n0328-01",3,"Linda de atrás y adelante,\nLindo modo i caminar,\nHasta las aves que vuelan,\nSe han de poner a mirar.",3,1,0,43,"",0,4,"a",21,0,-1,0,374,374,"328","",0,"","","",1,0,0,[],""],["carrizo_salta-n0329-01",3,"Linda la ñata,\nComo la aurora.\n¡Lástima grande!\nMal pagadora.",3,1,0,43,"",6,4,"oa",107,0,-1,0,374,374,"329","",0,"","","",1,0,0,[],""],["carrizo_salta-n0330-01",3,"Los árboles arrancados,\nY atados de siete en siete,\nNo han de tener más firmeza,\nComo yo para quererte.",3,1,0,43,"",0,4,"ee",-1,0,-1,0,374,374,"330","",0,"","","",1,0,0,[],""],["carrizo_salta-n0331-01",3,"Los cabellos de mi chica,\nNo se lavan con jabón,\nSino con agua florida,\nTerciada con alcanfor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,374,374,"331","",0,"","","",1,0,0,[],""],["carrizo_salta-n0332-01",3,"Los ojos azules,\nSon mala fortuna.\nSi no hay ojos negros,\nNo hay hermosura.",3,1,0,43,"",6,4,"ua",-1,0,-1,0,374,374,"332","",0,"","","",1,0,0,[],""],["carrizo_salta-n0333-01",3,"Los ojos de mi morena,\nMe están matando,\nComo ella es tan hermosa,\nLa estoy amando.",3,1,0,43,"",6,4,"ao",33,0,-1,0,374,374,"333","",0,"","","",23,0,0,[],""],["carrizo_salta-n0334-01",3,"Los ojos de mi morena,\nSon dos brillantes luceros,\nQue si me miran me matan,\nSi no me miran, me muero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,374,374,"334","",0,"rm_t2","","",23,0,0,[],""],["carrizo_salta-n0335-01",3,"Los ojos de mi morena,\nTienen pleitos con el sol.\nPorque el sol es uno solo,\nSus ojos dos soles son.",3,1,0,43,"",0,4,"o",-1,0,-1,0,374,374,"335","",0,"","","",23,0,0,[],""],["carrizo_salta-n0336-01",3,"Los ojos de mi negra,\nLlenos de antojo.\nCada vez que me miran,\nMe vuelven loco.",3,1,0,43,"",6,4,"oo",-1,0,-1,0,374,374,"336","",0,"","","",1,0,0,[],""],["carrizo_salta-n0337-01",3,"Lucerito de alto cielo!\nCaminas de cuatro en cuatro,\nTuyo soy, vidita mía,\nVendeme caro o barato.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,374,374,"337","",0,"","","",1,0,0,[],""],["carrizo_salta-n0338-01",3,"¡Lucero de la mañana!\nQue venís cerquita el día,\n¿Cómo no me despertaste,\nSi estaba la vida mía?",3,1,0,43,"",0,4,"ia",0,0,-1,0,374,374,"338","",0,"","","",22,0,0,[],""],["carrizo_salta-n0339-01",3,"¡Luna de todas las noches!\n¡Estrella al amanecer!\nLo que cantan las sirenas\nYo no lo puedo entender.",3,1,0,43,"",0,4,"e",20,0,-1,0,374,374,"339","",0,"","","",2,0,0,[],""],["carrizo_salta-n0340-01",3,"Mal no l' hi pagar, señora,\nEso es lo que no ha de ver.\nDichoso me considero,\nSi me muero en su poder.",3,1,0,43,"",0,4,"e",20,0,-1,0,375,375,"340","",0,"","","",1,0,0,[],""],["carrizo_salta-n0341-01",3,"María, paloma mía!\nLas palomas son del rey.\nY tú, María, eres mía,\nPorque lo manda la ley.",3,1,0,43,"",1,4,"e",133,0,-1,0,375,375,"341","",0,"","","",4,0,0,[],""],["carrizo_salta-n0342-01",3,"¡Marinero, que navegas!\nLevántate con el sol,\nPara seguirle los pasos,\nDe mi amante al Ecuador.",3,1,0,43,"",0,4,"o",-1,0,-1,0,375,375,"342","",0,"","","",1,0,0,[],""],["carrizo_salta-n0343-01",3,"Más lindos son tus ojos,\nNiña hechicera,\nQue los astros del cielo,\n¡Quién los tuviera!",3,1,0,43,"",6,4,"ea",44,0,-1,0,375,375,"343","",0,"","","",1,0,0,[],""],["carrizo_salta-n0344-01",3,"Me animo y me desanimo,\nDe verme así tan pequeño,\nLe advierto que soy solito,\nYo quisiera ser su dueño.",3,1,0,43,"",0,4,"eo",138,0,-1,0,375,375,"344","",0,"","","",2,0,0,[],""],["carrizo_salta-n0344-a-01",3,"Me animo y me desanimo,\nDe ver mi bulto pequeño,\nAdvierto que soy solito.\n¿No quisiera tener dueño?",3,1,0,43,"",0,4,"eo",138,0,-1,0,375,375,"344-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0345-01",3,"Me dicen que no te quiera,\n¡Jesús, qué barbaridad!\nCpnió no saben querer,\nNo saben aconsejar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,375,375,"345","",0,"","","",2,0,0,[],""],["carrizo_salta-n0345-01-e2",3,"Me dicen que tiene dueño,\nAsí con dueño la quiero.\nEl que quiere prenda ajena,\nTiene un amor verdadero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,375,375,"345","",0,"","","",1,0,0,[],""],["carrizo_salta-n0347-01",3,"Me dicen que tus ojitos,\nSólo alumbran para mí.\nY yo me digo, temblando,\n¡Señor, si no fuera así!",3,1,0,43,"",0,4,"i",23,0,-1,0,375,375,"347","",0,"","","",1,0,0,[],""],["carrizo_salta-n0348-01",3,"Medio del jardín estoy,\nNinguna flor me divierte.\nAunque me hagan mil caricias,\nNo puedo vivir sin verte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,375,375,"348","",0,"","","",1,0,0,[],""],["carrizo_salta-n0349-01",3,"Me dices que me querís,\nYo también t' hi de querer.\nCon la bendición del cura,\nCompañeros 'mos de ser.",3,1,0,43,"",0,4,"e",20,0,-1,0,375,375,"349","",0,"","","",1,0,0,[],""],["carrizo_salta-n0350-01",3,"Me gusta la cinta verde,\nTambién la color café,\nSin despreciar a ninguna,\nLa más bonita es Vd.",3,1,0,43,"",5,4,"",-1,0,-1,0,375,375,"350","",0,"","","",1,0,0,[],""],["carrizo_salta-n0351-01",3,"Me han dicho que me aborreces,\nQue quieres verme morir.\nCon darme un beso te basta,\nYa pueden doblar por mí.",3,1,0,43,"",0,4,"i",-1,0,-1,0,376,376,"351","",0,"","","",1,0,0,[],""],["carrizo_salta-n0352-01",3,"Me parece que te veo,\nPor donde quiera que voy.\nSon las sombras del deseo,\nEn que vacilando estoy.",3,1,0,43,"",1,4,"o",112,0,-1,0,376,376,"352","",0,"","","",1,0,0,[],""],["carrizo_salta-n0353-01",3,"Me preguntas lo que hago,\nCon tanto mirar al cielo.\nLas estrellas que más brillan,\nPara escribirte las quiero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,376,376,"353","",0,"","","",1,0,0,[],""],["carrizo_salta-n0354-01",3,"Me voy llorando, me voy,\nPero siempre hi de volver.\nA tus brazos, a tu vista,\nY mejor a tu poder.",3,1,0,43,"",0,4,"e",20,0,-1,0,376,376,"354","",0,"","","",1,0,0,[],""],["carrizo_salta-n0355-01",3,"Me voy para lejas tierras,\nDonde me coman las fieras;\nNo importa que ellas me coman,\nComo mi dueña me quiera.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,376,376,"355","",0,"","","",1,0,0,[],""],["carrizo_salta-n0356-01",3,"Mi corazón es de tierra,\nY lo voy hacer arar,\nPara sembrar un cariño,\nCon tu amor lo hi de regar.",3,1,0,43,"",0,4,"a",21,0,-1,0,376,376,"356","",0,"","","",1,0,0,[],""],["carrizo_salta-n0357-01",3,"Mi corazón no está en sí,\nPorque vivo apasionado,\nSin vuestros ojos, mi vida,\nNo puedo estar sosegado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,376,376,"357","",0,"","","",1,0,0,[],""],["carrizo_salta-n0358-01",3,"Mi corazón todo es tuyo,\nY en mi pecho está visible,\nEn ti puse mi afición,\nLa primer vez que te vide.",3,1,0,43,"",0,4,"ie",-1,0,-1,0,376,376,"358","",0,"","","",1,0,0,[],""],["carrizo_salta-n0359-01",3,"Mi negra encantadora,\n¿Por qué no quiere,\nQue le digan la reina\nDe las mujeres?",3,1,0,43,"",6,4,"ee",-1,0,-1,0,376,376,"359","",0,"","","",1,0,0,[],""],["carrizo_salta-n0360-01",3,"¡Mira cómo corre 'l agua\nPor debajo del peñón!\nAsí corre por tu cara,\nToda la gracia de Dios.",3,1,0,43,"",0,4,"o",-1,0,-1,0,376,376,"360","",0,"","","",1,0,0,[],""],["carrizo_salta-n0361-01",3,"Mirando estoy desde aquí,\nA l' otra banda del río,\nAl que tiene que juntar,\nSu corazón con el mío.",3,1,0,43,"",0,4,"io",3,0,-1,0,376,376,"361","",0,"","","",4,0,0,[],""],["carrizo_salta-n0362-01",3,"Mi turqulta enamorada,\nCogollo de rica flor,\nSi te gusta mi cariño,\nTratemos algo de amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,376,376,"362","",0,"","","",1,0,0,[],""],["carrizo_salta-n0363-01",3,"¡Moza de sombrero blanco!\nNo agachís la vista al suelo,\nAquellos que te van viendo,\nDirán que yo soy tu dueño.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,377,377,"363","",0,"","","",1,0,0,[],""],["carrizo_salta-n0364-01",3,"Mucho la quiero, vidita,\nY lo que la quiero es tanto,\nQue tengo por cama el suelo,\nY de cabecera un banco.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,377,377,"364","",0,"","","",2,0,0,[],""],["carrizo_salta-n0365-01",3,"Mucho me gustan tus ojos,\nPorque los tienes azules.\nParecen un cielo claro,\nCuando se apartan las nubes.",3,1,0,43,"",0,4,"ue",-1,0,-1,0,377,377,"365","",0,"","","",1,0,0,[],""],["carrizo_salta-n0366-01",3,"Muy cerca, muy cerca,\nNo me animo estar.\nPorque a tu boquita,\nLa quiero besar.",3,1,0,43,"",0,4,"a",21,0,-1,0,377,377,"366","",0,"","","",1,0,0,[],""],["carrizo_salta-n0367-01",3,"Nadie ha contado en el mundo,\nLas florcitas del almendro,\nY nadie te ha de querer,\nComo yo te estoy queriendo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,377,377,"367","",0,"","","",1,0,0,[],""],["carrizo_salta-n0367-a-01",3,"Si sabrá la vida mía,\nSi sabrá mi flor de almendro,\nQue nadie la ha de querer,\nComo yo la estoy queriendo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,377,377,"367-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0368-01",3,"Naranja verde,\nLimón maduro,\nDame un besito,\nCon disimulo.",3,1,0,43,"",6,4,"uo",-1,0,-1,0,377,377,"368","",0,"","","",1,0,0,[],""],["carrizo_salta-n0369-01",3,"¡Negrita de mi vida!\nDame, te pido,\nUna mirada tierna,\nComo un suspiro.",3,1,0,43,"",6,4,"io",-1,0,-1,0,377,377,"369","",0,"","","",1,0,0,[],""],["carrizo_salta-n0370-01",3,"Ni el tiempo ni la distancia,\nHarán que de tí me olvide,\nMás haré que el mundo admire,\nDe mi pecho la constancia.",3,1,0,43,"",5,4,"aa",340,0,-1,0,377,377,"370","",0,"","","",2,0,0,[],""],["carrizo_salta-n0371-01",3,"¡Niña linda! yo te dije,\nAl verte de una distancia,\nNiña, porque yo te quiero,\nNo pierdo las esperanzas.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,377,377,"371","",0,"","","",1,0,0,[],""],["carrizo_salta-n0372-01",3,"Niña, que mucho la quiero,\nCon esa fina carita,\n¿Me recibirá en su casa\nPara hacerle una visita?",3,1,0,43,"",0,4,"ia",50,0,-1,0,377,377,"372","",0,"","","",1,0,0,[],""],["carrizo_salta-n0373-01",3,"Niñita, trencitas de oro,\nBoquita de flor de aroma,\nSólo las alas te faltan,\nPara ser una paloma.",3,1,0,43,"",0,4,"oa",86,0,-1,0,377,377,"373","",0,"","","",1,0,0,[],""],["carrizo_salta-n0374-01",3,"No bajes los ojos, niña,\nNo escondas lo que agracea,\nQue a tu gracia la hizo Dios,\nPara que todos la vean.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,377,377,"374","",0,"","","",1,0,0,[],""],["carrizo_salta-n0375-01",3,"No desprecies las morenas,\nQue valen más que la plata.\nPorque morena es la prenda,\nVidita, que a mí me mata.",3,1,0,43,"",0,4,"aa",74,0,-1,0,377,377,"375","",0,"","","",1,0,0,[],""],["carrizo_salta-n0376-01",3,"No firmo porque soy firme,\nNo porque firmar no sé,\nPorque si firmo dirán:\nAsí uno firmó y se fué.",3,1,0,43,"",0,4,"e",77,0,-1,0,378,378,"376","",0,"","","",1,0,0,[],""],["carrizo_salta-n0377-01",3,"No hagas desprecios de mí,\nNo marchites mi pasión,\nQue la niña de tus ojos,\nCautiva mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,378,378,"377","",0,"","","",1,0,0,[],""],["carrizo_salta-n0378-01",3,"No la h' i dejar de adorar,\nPorque talmente es mi anhelo,\nAunque Vd. no ha de querer.\nPrendas que andan por el suelo.",3,1,0,43,"",0,4,"eo",10,0,-1,0,378,378,"378","",0,"","","",1,0,0,[],""],["carrizo_salta-n0379-01",3,"No me busques entre flores,\nQue entre flores hay traición,\nChacarero soy, vidita,\nTengo noble corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,378,378,"379","",0,"","","",1,0,0,[],""],["carrizo_salta-n0380-01",3,"No me hables de comida,\nNi me invites a comer,\nQue yo estoy alimentado,\nTan sólo con tu querer.",3,1,0,43,"",0,4,"e",20,0,-1,0,378,378,"380","",0,"","","",3,0,0,[],""],["carrizo_salta-n0381-01",3,"No me matís con cuchillo,\nQue es un acero muy fuerte,\nMátame con tu cariño,\nY te perdono la muerte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,378,378,"381","",0,"","","",1,0,0,[],""],["carrizo_salta-n0382-01",3,"No me mires con enojo,\nPorque el corazón me dice:\nQue yo nací para tí,\nY tú para mí naciste.",3,1,0,43,"",0,4,"ie",-1,0,-1,0,378,378,"382","",0,"","","",1,0,0,[],""],["carrizo_salta-n0383-01",3,"No me vendo ni me doy,\nSólo de mi dueño soy,\nNo lo hi de cambiar por otro,\nAunque me pague mejor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,378,378,"383","",0,"","","",1,0,0,[],""],["carrizo_salta-n0384-01",3,"No mire mi pequeñez,\nNi mi traje peregrino,\nNo me desprecie, señora,\nVengo a sus plantas rendido.",3,1,0,43,"",0,4,"io",-1,0,-1,0,378,378,"384","",0,"","","",1,0,0,[],""],["carrizo_salta-n0385-01",3,"No pienses, vidita mía,\nQue otro amor hi de seguir,\nNo ha i ser otro sino el tuyo,\nPor el que yo hi de morir.",3,1,0,43,"",0,4,"i",157,0,-1,0,378,378,"385","",0,"","","",1,0,0,[],""],["carrizo_salta-n0386-01",3,"No porque todos los días\nMis ojos no puedan verte,\nPor eso no has de pensar,\nQue yo hi dejar de quererte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,378,378,"386","",0,"","","",1,0,0,[],""],["carrizo_salta-n0387-01",3,"No puedes tener temor,\nQue yo soy pa defenderte,\nYo no le temo a la muerte,\nEn defensa de tu amor.",3,1,0,43,"",11,4,"o",72,0,-1,0,378,378,"387","",0,"","","",1,0,0,[],""],["carrizo_salta-n0388-01",3,"No te importe de mi dueño,\nPorque con dueño te quiero.\nA la sombra que hace un dedo,\nSe goza mejor que el dueño.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,378,378,"388","",0,"","","",1,0,0,[],""],["carrizo_salta-n0389-01",3,"No te retires, vida,\nPorque no puedo,\nOlvidar el camino\nDel Portizuelo.",3,1,0,43,"",6,4,"eo",-1,0,-1,0,378,378,"389","",0,"","","",1,0,0,[],""],["carrizo_salta-n0394-01",3,"Ojalá mil años pasen,\nSiempre constante hi de ser.\nAunque a la fuerza me lleven,\nA tus brazos h' i volver.",3,1,0,43,"",0,4,"e",20,0,-1,0,379,379,"394","",0,"","","",1,0,0,[],""],["carrizo_salta-n0395-01",3,"Ojitos negros hi visto,\nComo los suyos ya no.\nOjitos consoladores,\nCon que me consuelo yo.",3,1,0,43,"",0,4,"o",2,0,-1,0,379,379,"395","",0,"","","",1,0,0,[],""],["carrizo_salta-n0396-01",3,"¡Ojos bellos, que me dais,\nDulce muerte con mirarme!\n¡Ojos, que con no mirarme,\nDulce vdia me quitáis!",3,1,0,43,"",11,4,"a",394,0,-1,0,379,379,"396","",0,"","","",1,0,0,[],""],["carrizo_salta-n0397-01",3,"¡Ojos de garza morena!\nCorazón de terciopelo,\nVengo a llevarte, vidita,\nPara tener un consuelo.",3,1,0,43,"",0,4,"eo",10,0,-1,0,379,379,"397","",0,"","","",1,0,0,[],""],["carrizo_salta-n0398-01",3,"¡Ojos negros de tintero,\nNariz de pluma delgada,\nCarita i letra menuda,\nBoquita i carta cerrada!",3,1,0,43,"",0,4,"aa",49,0,-1,0,379,379,"398","",0,"","","",1,0,0,[],""],["carrizo_salta-n0399-01",3,"Olvidarla, niña hermosa,\nEso es lo que no hi de hacer,\nPorque tengo la esperanza,\nDe acabarme en su poder.",3,1,0,43,"",0,4,"e",20,0,-1,0,379,379,"399","",0,"","","",1,0,0,[],""],["carrizo_salta-n0400-01",3,"Olvidarte no lo dudo,\nPero ha de ser con la muerte,\nImposible es para mí,\nOlvidarte de otra suerte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,379,379,"400","",0,"","","",1,0,0,[],""],["carrizo_salta-n0401-01",3,"¡Paloma de dulce canto,\nNo me la quieras llevar!\nDe aquí para otro lugar,\nPorque sin ella, no puedo estar.",3,1,0,43,"",3,4,"a",21,0,-1,0,379,379,"401","",0,"","","",1,0,0,[],""],["carrizo_salta-n0402-01",3,"¡Palomita blanca!\nDe \"El Algarrobal\",\nDejá tu nidito,\nTe vengo a llevar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,379,379,"402","",0,"","","",12,0,0,[],""],["carrizo_salta-n0403-01",3,"¡Palomita boliviana!\nPiedra que se desmorona,\nSi te pago con vileza,\nSe abra la tierra y me coma.",3,1,0,43,"",0,4,"oa",-1,0,-1,0,379,379,"403","",0,"","","",1,0,0,[],""],["carrizo_salta-n0404-01",3,"¡Palomita encantadora!\nDe mi sentido el recreo,\nMe hayo sin vida y sin gusto,\nEl rato que no te veo.",3,1,0,43,"",0,4,"eo",66,0,-1,0,380,380,"404","",0,"","","",1,0,0,[],""],["carrizo_salta-n0405-01",3,"¡Palomita que t' hi tráido!\nCerca la Laguna Blanca.\nPiquito de oro macizo,\nAlitas de plata blanca.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,380,380,"405","",0,"","","",1,0,0,[],""],["carrizo_salta-n0406-01",3,"¿Para dónde, paloma,\nTan de mañana?\n—A recoger las flores\nDe las montañas.",3,1,0,43,"",6,4,"aa",-1,0,-1,0,380,380,"406","",0,"","","",1,0,0,[],""],["carrizo_salta-n0407-01",3,"Para mí no hay alegría,\nTodo es tristeza y pesar,\nSólo viéndome en tus brazos,\nMe podría consolar.",3,1,0,43,"",0,4,"a",21,0,-1,0,380,380,"407","",0,"","","",2,0,0,[],""],["carrizo_salta-n0408-01",3,"Para morir hi tomado,\nPapeles, pluma y tintero,\nVoy a hacer mi testamento,\nDe lo mucho que te quiero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,380,380,"408","",0,"","","",1,0,0,[],""],["carrizo_salta-n0408-a-01",3,"Para morir me preparo,\nCon la pluma y el tintero,\nPara hacer mi testamento,\nDe lo mucho que te quiero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,380,380,"408-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0409-01",3,"Para olvidar tu querer,\nHas de mirar dos señales,\nQue se caigan las estrellas,\nY que se sequen los mares.",3,1,0,43,"",0,4,"ae",-1,0,-1,0,380,380,"409","",0,"","","",6,0,0,[],""],["carrizo_salta-n0409-a-01",3,"Para olvidar tu querer,\nHe de esperar dos señales,\nQue se caigan las estrellas,\nY que se sequen los mares.",3,1,0,43,"",0,4,"ae",-1,0,-1,0,380,380,"409-a","",0,"","","",6,0,0,[],""],["carrizo_salta-n0410-01",3,"¿Para qué Dios plantaría\nTentación en el desierto?\nAntes que la conociera,\nMás antes me hubiera muerto.",3,1,0,43,"",0,4,"eo",88,0,-1,0,380,380,"410","",0,"","","",1,0,0,[],""],["carrizo_salta-n0411-01",3,"Paso ríos, paso puentes,\nSiempre te encuentro lavando.\nLa hermosura de tu cara,\nLa agua se la va llevando.",3,1,0,43,"",0,4,"ao",33,0,-1,0,380,380,"411","",0,"","","",2,0,0,[],""],["carrizo_salta-n0411-a-01",3,"Paso ríos, paso puentes,\nSiempre te encuentro cantando.\nLa hermosura de tu canto,\nL'agua se la va llevando.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,380,380,"411-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0412-01",3,"Parece oscura la noche,\nComo si fuera a llover,\nAsí se pone mi vista,\nCuando no te puede ver.",3,1,0,43,"",0,4,"e",20,0,-1,0,380,380,"412","",0,"","","",1,0,0,[],""],["carrizo_salta-n0413-01",3,"Picaflor quisiera ser,\nChiquitito y volador,\nPara sentarme en tu brazo,\nRendirte cuentas de amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,380,380,"413","",0,"","","",1,0,0,[],""],["carrizo_salta-n0414-01",3,"Piensa si será posible,\nPrivarle al sol su carrera,\nMás imposible será,\nPrivarme que yo te quiera.",3,1,0,43,"",0,4,"ea",44,0,-1,0,380,380,"414","",0,"","","",1,0,0,[],""],["carrizo_salta-n0415-01",3,"¡Pobrecita la vidita,\nNo tiene ningún amigo!\nSi no quiere andar solita,\nQue se acompañe conmigo.",3,1,0,43,"",1,4,"io",106,0,-1,0,380,380,"415","",0,"","","",1,0,0,[],""],["carrizo_salta-n0416-01",3,"Podrá hundirse la tierra,\nPodrán los astros caer,\nPero el amor que te tengo,\nJamás se ha i desvanecer.",3,1,0,43,"",0,4,"e",20,0,-1,0,380,380,"416","",0,"","","",1,0,0,[],""],["carrizo_salta-n0425-01",3,"¿Qué día se acabará\nDe mi pecho la alegría?\nSerá cuando yo me muera,\nRegalada prenda mía.",3,1,0,43,"",0,4,"ia",0,0,-1,0,381,381,"425","",0,"","","",1,0,0,[],""],["carrizo_salta-n0426-01",3,"¿Qué es eso que remanece,\nY el suelo viene temblando?\nEsos serán los pasitos,\nQue mi vida viene dando.",3,1,0,43,"",0,4,"ao",33,0,-1,0,381,381,"426","",0,"","","",1,0,0,[],""],["carrizo_salta-n0426-a-01",3,"Yo no sé qué ruido es este,\nEl mundo viene temblando,\nSon pasos de una fulana,\nQue recién viene llegando.",3,1,0,43,"",0,4,"ao",33,0,-1,0,381,381,"426-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0427-01",3,"Que esos tus labios rojos,\nPor mí suspiran,\nMe lo dicen tus ojos,\nCuando me miran.",3,1,0,43,"",6,4,"ia",338,0,-1,0,381,381,"427","",0,"","","",1,0,0,[],""],["carrizo_salta-n0428-01",3,"¡Qué lindas son las palomas,\nQue viven a su placer!\nCon la bendición del cura,\nCompañeros 'mos de ser.",3,1,0,43,"",0,4,"e",20,0,-1,0,381,381,"428","",0,"","","",1,0,0,[],""],["carrizo_salta-n0429-01",3,"¡Qué lindos rulitos tiene!\nY todos caracolados,\nEn cada caracolcito,\nEstá mi amor amarrado.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,381,381,"429","",0,"","","",1,0,0,[],""],["carrizo_salta-n0430-01",3,"Que no me olvides, te pido,\nYo nunca te olvidaré,\nY siempre y siempre seré,\nUn amigo agradecido.",3,1,0,43,"",11,4,"io",101,0,-1,0,381,381,"430","",0,"","","",1,0,0,[],""],["carrizo_salta-n0431-01",3,"Querida, cuando reciba,\nMis cartas del regimiento,\nConservelás mientras viva,\nY guardelás con el tiempo.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,381,381,"431","",0,"","","",1,0,0,[],""],["carrizo_salta-n0432-01",3,"¿Querís que te esté diciendo,\nCómo la catita al loro?\n¿Hasta cuándo t' hi decir,\nQue te quiero y que te adoro?",3,1,0,43,"",0,4,"oo",85,0,-1,0,382,382,"432","",0,"","","",1,0,0,[],""],["carrizo_salta-n0433-01",3,"¿Qué será lo que relumbra,\nPor debajo de esa peña?\nSon los ojos de mi negra,\nQue de lejos me hacen seña.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,382,382,"433","",0,"","","",1,0,0,[],""],["carrizo_salta-n0434-01",3,"Quién diga que no te quiero,\nNada de quereres sabe,\n¡Candadito de oro fino!\n¿A dónde estará tu llave?",3,1,0,43,"",0,4,"ae",69,0,-1,0,382,382,"434","",0,"","","",1,0,0,[],""],["carrizo_salta-n0435-01",3,"¡Quién tuviera esos ojitos,\nComo perlas de la mar!\nPara tirarle el anzuelo,\nPor ver si quiere picar.",3,1,0,43,"",0,4,"a",21,0,-1,0,382,382,"435","",0,"","","",1,0,0,[],""],["carrizo_salta-n0436-01",3,"Quiérame, vidita mía,\nQue me aborrezca, no quiero,\nY si me ha de aborrecer,\nDemé la muerte primero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,382,382,"436","",0,"","","",1,0,0,[],""],["carrizo_salta-n0437-01",3,"Quiero firmar y no puedo,\nAllí va toda mi fama,\nQuien la aprecia, quien la estima,\nÑo Cupertino se llama.",3,1,0,43,"",0,4,"aa",90,0,-1,0,382,382,"437","",0,"","","",1,0,0,[],""],["carrizo_salta-n0438-01",3,"Quisiera guerrear contigo,\nAunque me hicieras pedazos,\nFuego granadiado de besos,\nY fusilado en tus brazos.",3,1,0,43,"",0,4,"ao",132,0,-1,0,382,382,"438","",0,"","","",1,0,0,[],""],["carrizo_salta-n0439-01",3,"Quisiera ser picaflor,\nPara picar flor de tuna.\nHe visto rubitas lindas,\nPero como vos, ninguna.",3,1,0,43,"",0,4,"ua",56,0,-1,0,382,382,"439","",0,"","","",3,0,0,[],""],["carrizo_salta-n0440-01",3,"Quisiera ser por un rato,\nPeineta de tu cabello,\nMoñito de sus zapatos,\nCadenita de tu cuello.",3,1,0,43,"",0,4,"eo",12,0,-1,0,382,382,"440","",0,"","","",9,0,0,[],""],["carrizo_salta-n0441-01",3,"Quisiera ser ruiseñor,\nY tener un dulce trino.\nPara cantarte tu amor,\nCuando formemos el nido.",3,1,0,43,"",0,4,"io",-1,0,-1,0,382,382,"441","",0,"","","",1,0,0,[],""],["carrizo_salta-n0442-01",3,"Quisiera ser un patito,\nChiquitito y nadador,\nPara dentrar en tu pecho,\nNadar en tu corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,382,382,"442","",0,"","","",2,0,0,[],""],["carrizo_salta-n0443-01",3,"Ramos de flores me ofrecen,\nYo de esos dones me río,\nSi yo preferí quererte,\nFué por tu gusto y el mío.",3,1,0,43,"",0,4,"io",3,0,-1,0,382,382,"443","",0,"","","",1,0,0,[],""],["carrizo_salta-n0444-01",3,"Reina de mis ilusiones,\nYo no sé qué voy a hacer,\nQuiérame un momentito,\nAunque me olvide después.",3,1,0,43,"",0,4,"e",-1,0,-1,0,382,382,"444","",0,"","","",1,0,0,[],""],["carrizo_salta-n0445-01",3,"Rendido de tus amores,\nSólo por verte hi venido,\nComo no te puedo hablar,\nYo ya estoy loco perdido.",3,1,0,43,"",0,4,"io",101,0,-1,0,382,382,"445","",0,"","","",1,0,0,[],""],["carrizo_salta-n0446-01",3,"Ronco me siento del pecho,\nCalmado de la garganta,\nTanto seguirte los pasos,\nY el polvo que vos levantas.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,382,382,"446","",0,"","","",2,0,0,[],""],["carrizo_salta-n0453-01",3,"Señora, doña fulana!\nBlanca flor en un rastrojo,\na qué la conocería\nPara morirme de antojo?",3,1,0,43,"",0,4,"oo",400,0,-1,0,383,383,"453","",0,"","","",22,0,0,[],""],["carrizo_salta-n0456-01",3,"¡Señora, doña fulana!\nCarita de oro molido,\n¿Por qué me quiere apuntar,\nEn el libro del olvido?",3,1,0,43,"",0,4,"io",101,0,-1,0,383,383,"456","",0,"","","",22,0,0,[],""],["carrizo_salta-n0457-01",3,"¡Señora, doña fulana!\nDe mí se compadeciera,\nYo soy una laya i mozo,\nQue no se halla donde quiera.",3,1,0,43,"",0,4,"ea",44,0,-1,0,383,383,"457","",0,"","","",22,0,0,[],""],["carrizo_salta-n0458-01",3,"¡Señora, doña fulana!\nDe nombrarla se me antoja,\nA sus pies estoy rendido,\nComo árbol que se deshoja.",3,1,0,43,"",0,4,"oa",146,0,-1,0,383,383,"458","",0,"","","",22,0,0,[],""],["carrizo_salta-n0459-01",3,"¡Señora, doña fulana!\nDespierte del dulce sueño,\nA preguntarle hi venio,\nSi está sola, o tiene dueño.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,383,383,"459","",0,"","","",22,0,0,[],""],["carrizo_salta-n0460-01",3,"¡Señora, doña fulana!\nMucho me gustan sus modos,\nSupiera cual es su casa,\nMe cambiaría cama y todo.",3,1,0,43,"",3,4,"oo",-1,0,-1,0,383,383,"460","",0,"","","",22,0,0,[],""],["carrizo_salta-n0461-01",3,"¡Señora, doña fulana!\nOjitos de clavelina,\nPonga su nombre y su firma,\nSi su corazón me estima.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,383,383,"461","",0,"","","",22,0,0,[],""],["carrizo_salta-n0462-01",3,"¡Señora, doña fulana!\nRosa remolida en Roma,\nSus pelitos perlas de oro,\nSu carita flor de aroma.",3,1,0,43,"",0,4,"oa",86,0,-1,0,383,383,"462","",0,"","","",22,0,0,[],""],["carrizo_salta-n0463-01",3,"¡Señora, doña fulana!\nSi Vd. me tiene afición,\nYo le postraré rendido,\nA sus piés, mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,383,383,"463","",0,"","","",22,0,0,[],""],["carrizo_salta-n0464-01",3,"¡Señora, doña fulana!\nVerde planta de romero,\nAvisemé cuando muera,\nPara yo morir primero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,383,383,"464","",0,"","","",22,0,0,[],""],["carrizo_salta-n0465-01",3,"¡Señora, dueña de casa!\nAlhelí, nardo y aroma,\nDe los manjares del cielo,\nDisfrutará su persona.",3,1,0,43,"",0,4,"oa",-1,0,-1,0,384,384,"465","",0,"","","",7,0,0,[],""],["carrizo_salta-n0466-01",3,"¡Señora, dueña de casa!\n¿Si habrá pensado algún día,\nQue la había de visitar\nLa humilde persona mía?",3,1,0,43,"",0,4,"ia",0,0,-1,0,384,384,"466","",0,"","","",7,0,0,[],""],["carrizo_salta-n0466-a-01",3,"¡Señorita de Fulana!\n¿Si habrá pensado algún día,\nQue yo vendría a cantarle,\nHumildes estrofas mías?",3,1,0,43,"",0,4,"ia",-1,0,-1,0,384,384,"466-a","",0,"","","",16,0,0,[],""],["carrizo_salta-n0467-01",3,"Señora, no la conozco,\nLa hi venio a conocer,\nDicen que se hacen dichosos,\nOjos que la logran ver.",3,1,0,43,"",0,4,"e",20,0,-1,0,384,384,"467","",0,"","","",2,0,0,[],""],["carrizo_salta-n0468-01",3,"Señora, para su altura,\nParece que soy basura,\nPor dichoso me contara,\nSi gozo de su hermosura.",3,1,0,43,"",0,4,"ua",17,0,-1,0,384,384,"468","",0,"","","",1,0,0,[],""],["carrizo_salta-n0469-01",3,"Señora, pecho de luna,\nOjos de garza milicia,\nCuando con verla me encanto,\n¿Qué será cuando acaricia?",3,1,0,43,"",0,4,"ia",391,0,-1,0,384,384,"469","",0,"","","",1,0,0,[],""],["carrizo_salta-n0470-01",3,"¡Señorita de fulana!\nBlanca flor adormecida,\nSi por mí se ha despertado,\nVuélvase a quedar dormida.",3,1,0,43,"",0,4,"ia",37,0,-1,0,384,384,"470","",0,"","","",16,0,0,[],""],["carrizo_salta-n0471-01",3,"¡Señorita de fulana!\nCantemeló su coplita,\nAunque no sea concertada,\nComo sea de su boquita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,384,384,"471","",0,"","","",16,0,0,[],""],["carrizo_salta-n0472-01",3,"¡Señorita de fulana!\nCapullito de dulzura,\n¡Cuántos mozos no andarán,\nPor gozar de su hermosura!",3,1,0,43,"",0,4,"ua",17,0,-1,0,384,384,"472","",0,"","","",16,0,0,[],""],["carrizo_salta-n0473-01",3,"¡Señorita de fulana!\nClavelito dentro l'agua,\nSi me estuviera muriendo,\nViéndola resucitara.",3,1,0,43,"",0,4,"aa",-1,0,-1,0,384,384,"473","",0,"","","",16,0,0,[],""],["carrizo_salta-n0474-01",3,"¡Señorita de fulana!\nDel cielo cayó esta flor,\nRecibalá como obsequio,\nQue en su mano está mejor.",3,1,0,43,"",0,4,"o",72,0,-1,0,384,384,"474","",0,"","","",16,0,0,[],""],["carrizo_salta-n0475-01",3,"¡Señorita de fulana!\nSoy suela de sus zapatos,\nAquí me tiene a sus piés,\nVendamé caro o barato.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,384,384,"475","",0,"","","",16,0,0,[],""],["carrizo_salta-n0476-01",3,"¡Señorita de fulana!\nNadie se acuerda de Vd.,\nY como su esclavo soy,\nSolito la vengo a ver.",3,1,0,43,"",5,4,"e",-1,0,-1,0,384,384,"476","",0,"","","",16,0,0,[],""],["carrizo_salta-n0477-01",3,"¡Señorita de fulana!\nPlanta de clavel silvestre,\nLa hi de querer mientras viva,\nAunque la vida me cueste.",3,1,0,43,"",0,4,"ee",-1,0,-1,0,384,384,"477","",0,"","","",16,0,0,[],""],["carrizo_salta-n0478-01",3,"¡Señorita de fulana!\nSoñé que yo estaba viendo,\nUn caminito de flores,\nQue a su paso iban naciendo.",3,1,0,43,"",0,4,"eo",52,0,-1,0,384,384,"478","",0,"","","",16,0,0,[],""],["carrizo_salta-n0479-01",3,"¡Señorita de fulana!\nSoy su esclavo, vendamé,\nPor la plata que Vd. quiera,\nQue yo me rescataré.",3,1,0,43,"",0,4,"e",77,0,-1,0,384,384,"479","",0,"","","",16,0,0,[],""],["carrizo_salta-n0479-a-01",3,"Soy esclavo y vendamé,\nPor la plata que Vd. quiera.\nQue yo me rescataré,\nTan solamente por verla.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,384,384,"479-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0480-01",3,"¡Señorita de fulana!\nVerdecita como yuyo,\n¿Me sentirá, señorita\nCuando me coma el coyuyo?",3,1,0,43,"",0,4,"uo",78,0,-1,0,384,384,"480","",0,"","","",16,0,0,[],""],["carrizo_salta-n0481-01",3,"¡Señorita de fulana!\nTenga Vd. unas buenas noches,\nSalga el sol en hebras de oro,\nPara que su pecho abroche.",3,1,0,43,"",0,4,"oe",-1,0,-1,0,385,385,"481","",0,"","","",16,0,0,[],""],["carrizo_salta-n0482-01",3,"¡Señorita de fulana!\nVerde cogollo de olivo,\nComo el olivo es amargo,\nEn amargas penas vivo.",3,1,0,43,"",0,4,"io",351,0,-1,0,385,385,"482","",0,"","","",16,0,0,[],""],["carrizo_salta-n0483-01",3,"Señorita de fulana!\nYo la vengo a coronar,\nDe reina de los cacheños,\nQue estamos a su mandar.",3,1,0,43,"",0,4,"a",21,0,-1,0,385,385,"483","",0,"","","",16,0,0,[],""],["carrizo_salta-n0487-01",3,"Si con tu mirar matas,\nYo te pregunto:\nDónde vas enterrando,\nTanto difunto?",3,1,0,43,"",6,4,"uo",36,0,-1,0,385,385,"487","",0,"","","",1,0,0,[],""],["carrizo_salta-n0488-01",3,"Si David con su honda\nMató un gigante,\nTú me matas, bien mío,\nCon tu semblante.",3,1,0,43,"",6,4,"ae",47,0,-1,0,385,385,"488","",0,"","","",1,0,0,[],""],["carrizo_salta-n0489-01",3,"Si eres más rubia que el oro,\nMás blanquita que la leche,\nMás hermosa que el lucero,\n¿Qué hi de hacer sino quererte?",3,1,0,43,"",0,4,"ee",-1,0,-1,0,385,385,"489","",0,"","","",1,0,0,[],""],["carrizo_salta-n0490-01",3,"Siempre miré aquella estrella,\nQue brilla en el cielo azul,\nYo pensaba, al contemplarla,\nQue la estabas viendo tú.",3,1,0,43,"",0,4,"u",-1,0,-1,0,385,385,"490","",0,"","","",1,0,0,[],""],["carrizo_salta-n0491-01",3,"Si en tus bracitos me viera,\nAcariciado por tí,\nEntonces diría, vidita:\n¡Este es mi día feliz!",3,1,0,43,"",0,4,"i",-1,0,-1,0,385,385,"491","",0,"","","",1,0,0,[],""],["carrizo_salta-n0492-01",3,"Siete mundos he corrido,\nTan sólo encontré una flor,\nSiendo fragante y bonita,\nEn su mano está mejor.",3,1,0,43,"",0,4,"o",72,0,-1,0,385,385,"492","",0,"","","",1,0,0,[],""],["carrizo_salta-n0493-01",3,"Si mi corazón llegara\nA pedirte algo por Dios,\nY no tuvieras qué darle,\nDile con amor: perdón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,385,385,"493","",0,"","","",1,0,0,[],""],["carrizo_salta-n0494-01",3,"Si me hallo lejos de tí,\nSiempre suspiro de amor,\nY si estoy cerca, ¡ay de mí!\nEl suspiro es de dolor.",3,1,0,43,"",1,4,"o",72,0,-1,0,385,385,"494","",0,"","","",1,0,0,[],""],["carrizo_salta-n0495-01",3,"Si me miráis, me matáis,\nSi no me miráis, me muero,\nY si no lo remediáis,\nDel cielo venga el remedio.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,386,386,"495","",0,"","","",1,0,0,[],""],["carrizo_salta-n0496-01",3,"Si me miras, me matas,\nSi no, me muero,\n¡Mírame, vida mía!\nQue morir quiero.",3,1,0,43,"",6,4,"eo",38,0,-1,0,386,386,"496","",0,"rm_t2, palau_cantares","","",3,0,0,[],""],["carrizo_salta-n0497-01",3,"Si me querís, negra mía,\nDecí nomás la verdad,\nY si es que te estoy gustando,\nA mi vos me gustás más.",3,1,0,43,"",0,4,"a",-1,0,-1,0,386,386,"497","",0,"","","",1,0,0,[],""],["carrizo_salta-n0498-01",3,"Si me quieres ver morir,\nDejá sin contestación,\nEsta carta que te escribo,\nCon sangre del corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,386,386,"498","",0,"","","",7,0,0,[],""],["carrizo_salta-n0499-01",3,"Si porque te quiero tanto,\nTodo el mundo me hace guerra,\nLa guerra se ha de acabar,\nY el amor ahí nomás queda.",3,1,0,43,"",3,4,"ea",-1,0,-1,0,386,386,"499","",0,"","","",2,0,0,[],""],["carrizo_salta-n0500-01",3,"Si pudieras penetrar,\nEn el fondo de mi pecho,\nVerías cómo tu nombre,\nEstá grabado allí dentro.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,386,386,"500","",0,"","","",1,0,0,[],""],["carrizo_salta-n0501-01",3,"Si sosegado anduviera,\nYa menos penas tuviera,\nCon la luz de vuestros ojos,\nDe tí no me dividiera.",3,1,0,43,"",0,4,"ea",44,0,-1,0,386,386,"501","",0,"","","",1,0,0,[],""],["carrizo_salta-n0502-01",3,"Si supiera que cantando,\nTe había de divertir,\nToda mi vida cantara,\nCantando había de morir.",3,1,0,43,"",0,4,"i",157,0,-1,0,386,386,"502","",0,"","","",10,0,0,[],""],["carrizo_salta-n0503-01",3,"Si todo el mundo tuviera,\nTu entusiasmo arrobador,\nTodito el mundo anduviera,\nPor conseguirse tu amor.",3,1,0,43,"",1,4,"o",72,0,-1,0,386,386,"503","",0,"","","",1,0,0,[],""],["carrizo_salta-n0504-01",3,"Si tu amante te lo priva,\nY no te deja salir,\nAvisame a mí solito,\nDe lejos m'hi de venir.",3,1,0,43,"",0,4,"i",157,0,-1,0,386,386,"504","",0,"","","",1,0,0,[],""],["carrizo_salta-n0505-01",3,"Si tu casa fuera iglesia,\nY tu cuarto fuera altar,\nY tu cama sepultura,\nVivo me fuera a enterrar.",3,1,0,43,"",0,4,"a",21,0,-1,0,386,386,"505","",0,"palau_cantares, lafuente_madrid, ortiz_ecuador","","",4,0,0,[],""],["carrizo_salta-n0506-01",3,"Si tu pecho fuera sándia,\nY yo fuera calador,\nEn la primer caladura,\nTe comería el corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,386,386,"506","",0,"","","",1,0,0,[],""],["carrizo_salta-n0507-01",3,"Si tu vida se acabara,\nY al otro mundo te fueras,\nAllí te iría a adorar,\nComo si viva estuvieras.",3,1,0,43,"",0,4,"ea",103,0,-1,0,386,386,"507","",0,"","","",1,0,0,[],""],["carrizo_salta-n0508-01",3,"Si yo mismo no me entiendo,\n¿Quién me va a entender a mí?\nTe digo que no te quiero,\nY ando muriendo por tí.",3,1,0,43,"",0,4,"i",23,0,-1,0,386,386,"508","",0,"","","",2,0,0,[],""],["carrizo_salta-n0509-01",3,"Si yo supiera volar,\nA cada paso te viera,\nNo fueran tantas mis penas,\nSi a mi lado te tuviera.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,387,387,"509","",0,"","","",1,0,0,[],""],["carrizo_salta-n0510-01",3,"Sois, vidita, tan hermosa,\nComo el sol, como el lucero,\nPor eso todos te dicen:\nEncanto del pago entero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,387,387,"510","",0,"","","",1,0,0,[],""],["carrizo_salta-n0511-01",3,"Sólo a tí miran mis ojos,\nSin tí no puedo vivir,\nA tí solamente quiero,\nY he de amarte hasta morir.",3,1,0,43,"",0,4,"i",157,0,-1,0,387,387,"511","",0,"","","",1,0,0,[],""],["carrizo_salta-n0512-01",3,"Son locas las ilusiones,\nQue en tí se anidan,\nY hay besos y apretones,\nQue no se olvidan.",3,1,0,43,"",3,4,"ia",401,0,-1,0,387,387,"512","",0,"","","",1,0,0,[],""],["carrizo_salta-n0513-01",3,"Son tus ojos las estrellas,\nQue iluminan mi pasión,\nSon las más dulces y bellas,\nPrendas de mi corazón.",3,1,0,43,"",1,4,"o",31,0,-1,0,387,387,"513","",0,"","","",2,0,0,[],""],["carrizo_salta-n0514-01",3,"Son tus ojos noche y día,\nLuz y sombra a un tiempo son,\nSon negros como la noche,\nY brillantes como el sol.",3,1,0,43,"",0,4,"o",-1,0,-1,0,387,387,"514","",0,"","","",1,0,0,[],""],["carrizo_salta-n0515-01",3,"Soñaba un cielo de dichas,\nY hallé un infierno de penas,\nPensaba en hacerte mía,\nPensaba en hacerte buena.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,387,387,"515","",0,"","","",1,0,0,[],""],["carrizo_salta-n0516-01",3,"Sos chiquitita y bonita,\nSin tener comparación,\nPrima hermana de la luna,\nPrima segunda del sol.",3,1,0,43,"",0,4,"o",-1,0,-1,0,387,387,"516","",0,"","","",1,0,0,[],""],["carrizo_salta-n0517-01",3,"Soy de rosa, soy de rosas,\nSoy la más fragante flor,\nQuereme, prenda querida,\nQue me muero por tu amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,387,387,"517","",0,"","","",1,0,0,[],""],["carrizo_salta-n0518-01",3,"Soy forastero del pago,\nY recién vengo del norte,\n¡Qué lindos rulitos tiene,\nY no quiere que le corte!...",3,1,0,43,"",0,4,"oe",402,0,-1,0,387,387,"518","",0,"","","",2,0,0,[],""],["carrizo_salta-n0519-01",3,"Soy joven para el amor,\nNo te cause almiración,\nPero tus ojitos negros,\nMe han robado el corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,387,387,"519","",0,"","","",1,0,0,[],""],["carrizo_salta-n0520-01",3,"Su esclavo quisiera ser,\n¿Qué más le puedo decir?\nSi gozo de su hermosura,\nCien años hi de servir.",3,1,0,43,"",0,4,"i",157,0,-1,0,387,387,"520","",0,"","","",1,0,0,[],""],["carrizo_salta-n0521-01",3,"Supiera lo que la quiero,\nLo que la quiero supiera,\nEn despierto me soñara,\nY aún en dormido me viera.",3,1,0,43,"",3,4,"ea",44,0,-1,0,387,387,"521","",0,"","","",1,0,0,[],""],["carrizo_salta-n0522-01",3,"Supieras, clavel dorado,\nEl amor que te he tomado,\nNo como ni duermo a gusto,\nComo si fuera penado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,387,387,"522","",0,"","","",1,0,0,[],""],["carrizo_salta-n0523-01",3,"Supieras, vida, supieras,\nCómo es grande mi cariño;\nMe habrías de acariciar,\nComo se acaricia un niño.",3,1,0,43,"",0,4,"io",176,0,-1,0,387,387,"523","",0,"","","",1,0,0,[],""],["carrizo_salta-n0524-01",3,"Supuesto que eres mi dueña,\nDame un besito, ñatita,\nNo tienes porque negarme,\nUn beso de tu boquita.",3,1,0,43,"",0,4,"ia",50,0,-1,0,387,387,"524","",0,"","","",1,0,0,[],""],["carrizo_salta-n0525-01",3,"Supuesto que me amas tanto,\nBien pudieras algún día,\nHacerme un corto servicio,\nComo una cosa perdida.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,388,388,"525","",0,"","","",1,0,0,[],""],["carrizo_salta-n0526-01",3,"Suspiros del corazón,\nSalen de mi pecho ardido,\nY se van a aposentar,\nEn tu corazón dormido.",3,1,0,43,"",0,4,"io",101,0,-1,0,388,388,"526","",0,"","","",4,0,0,[],""],["carrizo_salta-n0527-01",3,"También tengo algo de malo,\nSoy un poquito ladrón,\nEl día menos pensado,\nLe hi robar el corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,388,388,"527","",0,"","","",1,0,0,[],""],["carrizo_salta-n0528-01",3,"Tan de lejos hi venío,\nTan de lejos a tu casa,\nEn un camino tan largo,\nSabe Dios lo que le pasa.",3,1,0,43,"",0,4,"aa",123,0,-1,0,388,388,"528","",0,"","","",1,0,0,[],""],["carrizo_salta-n0529-01",3,"Tan alta que está la luna,\nEl viento es quien la revoca,\n¿Quién pudiera merecer\nUn besito de tu boca?",3,1,0,43,"",0,4,"oa",178,0,-1,0,388,388,"529","",0,"","","",1,0,0,[],""],["carrizo_salta-n0530-01",3,"Tan sólo a verte he venido,\nNo traigo más diligencia,\nY a preguntarte diciendo:\n—¿Cómo te va con mi ausencia?",3,1,0,43,"",0,4,"ea",46,0,-1,0,388,388,"530","",0,"","","",1,0,0,[],""],["carrizo_salta-n0531-01",3,"Tanto tiempo estuve ausente,\nVelay, hi vuelto recién,\nA encadenarme en tus brazos,\nYa estoy de vuelta, mi bien.",3,1,0,43,"",0,4,"e",242,0,-1,0,388,388,"531","",0,"","","",1,0,0,[],""],["carrizo_salta-n0532-01",3,"Tarde la noche a deshora,\nVengo a pedirte un favor,\nNo me trates de atrevido,\nLa culpa tiene el amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,388,388,"532","",0,"","","",2,0,0,[],""],["carrizo_salta-n0533-01",3,"Te comparo con la luna,\nCon el sol, con el lucero,\nY si no fuera pecado,\nCon la Reina de los cielos.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,388,388,"533","",0,"","","",6,0,0,[],""],["carrizo_salta-n0534-01",3,"Te dentrastes en mi pecho,\nComo polilla de amor,\nMe comistes las entrañas,\nLas alas del corazón.",3,1,0,43,"",0,4,"o",-1,0,-1,0,388,388,"534","",0,"","","",1,0,0,[],""],["carrizo_salta-n0535-01",3,"Te entrego mi corazón,\nComo un vidrio cristalino,\nDime, si me has de atender,\nEscúchame, ángel divino.",3,1,0,43,"",0,4,"io",199,0,-1,0,388,388,"535","",0,"","","",1,0,0,[],""],["carrizo_salta-n0536-01",3,"Te he soñado, vida mía,\nEn brazos de ajeno dueño,\nY creo que con la vida,\nVoy a pagar este sueño.",3,1,0,43,"",0,4,"eo",138,0,-1,0,388,388,"536","",0,"","","",1,0,0,[],""],["carrizo_salta-n0537-01",3,"Te lleva el agua,\nTe lleva el río,\nDame la mano,\n¡Corazón mío!",3,1,0,43,"",6,4,"io",3,0,-1,0,388,388,"537","",0,"","","",2,0,0,[],""],["carrizo_salta-n0537-a-01",3,"Te lleva el agua,\nTe lleva el río,\nAgarrate a esa rama,\n¡Corazón mío!",3,1,0,43,"",6,4,"io",3,0,-1,0,388,388,"537-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0543-01",3,"Tengo vergüenza y me callo,\nTengo amor y no lo digo,\nNo sé cómo le diré,\nSi quiere vivir conmigo.",3,1,0,43,"",0,4,"io",106,0,-1,0,389,389,"543","",0,"","","",6,0,0,[],""],["carrizo_salta-n0544-01",3,"Ten paciencia, vida mía!\nQue ya vendrá l'ocasión,\nEn tus brazos amorosos,\nDormirá mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,389,389,"544","",0,"","","",1,0,0,[],""],["carrizo_salta-n0545-01",3,"Te olvidaré yo algún día,\nPero será con la muerte,\nCuando en un sepulcro, tu alma,\nEntierre mi infeliz suerte.",3,1,0,43,"",0,4,"ee",134,0,-1,0,389,389,"545","",0,"","","",1,0,0,[],""],["carrizo_salta-n0546-01",3,"Te quiero con tal pasión,\nY con tanto frenesí,\nQue si tú me das el sí,\nTe entrego mi corazón.",3,1,0,43,"",11,4,"o",31,0,-1,0,389,389,"546","",0,"","","",1,0,0,[],""],["carrizo_salta-n0547-01",3,"Te quiero más que a mi vida,\nY más que a mi corazón,\nMás que a mi tata y mi mama;\n¡Mirá si hay comparación!",3,1,0,43,"",0,4,"o",31,0,-1,0,389,389,"547","",0,"","","",8,0,0,[],""],["carrizo_salta-n0548-01",3,"Te quiero tanto, alma mía,\nQue no te puedo decir,\nVivo soñando contigo,\nNo duermo pensando en tí.",3,1,0,43,"",0,4,"i",-1,0,-1,0,389,389,"548","",0,"","","",1,0,0,[],""],["carrizo_salta-n0549-01",3,"Te trataré con cuidado,\nY también con mucho esmero,\nQue si no estoy a tu lado,\nLa triste muerte prefiero.",3,1,0,43,"",1,4,"eo",38,0,-1,0,389,389,"549","",0,"","","",1,0,0,[],""],["carrizo_salta-n0550-01",3,"Tiene la vida mía,\nEn el pañuelo,\nUn letrero que dice:\n¡Viva mi dueño!",3,1,0,43,"",6,4,"eo",-1,0,-1,0,389,389,"550","",0,"","","",1,0,0,[],""],["carrizo_salta-n0551-01",3,"Toditos me dicen,\nQue el mundo es traidor,\nDe lejos me vengo,\nBuscando mi amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,389,389,"551","",0,"","","",1,0,0,[],""],["carrizo_salta-n0552-01",3,"Todo amor precisamente,\nCon la larga ausencia calma,\nPero tu imagen viviente,\nLa llevo impresa en el alma.",3,1,0,43,"",1,4,"aa",125,0,-1,0,389,389,"552","",0,"","","",1,0,0,[],""],["carrizo_salta-n0553-01",3,"Todos los que se mueren,\nPierden la vida,\nY yo por adorarte,\nPierdo la mía.",3,1,0,43,"",6,4,"ia",-1,0,-1,0,389,389,"553","",0,"","","",2,0,0,[],""],["carrizo_salta-n0555-01",3,"Traigo una flor formoseña,\nDe muy distinto color,\nY si le gusta, donosa,\nLa cambiaré por su amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,390,390,"555","",0,"","","",1,0,0,[],""],["carrizo_salta-n0556-01",3,"Tres cosas hay que deseo:\nAmor, esperanza y f é,\nLas primeras yo te envío,\nLa tercera Dios te dé.",3,1,0,43,"",0,4,"e",77,0,-1,0,390,390,"556","",0,"","","",1,0,0,[],""],["carrizo_salta-n0557-01",3,"Tú eres mi fé y mi porfía,\nTú eres mi pasión profunda,\nHe de amarte, prenda mía,\nHasta que de amor sucumba.",3,1,0,43,"",0,4,"ua",-1,0,-1,0,390,390,"557","",0,"","","",1,0,0,[],""],["carrizo_salta-n0558-01",3,"Tú eres linda rosa,\nYo verde alhelí,\nAunque tengas dueño,\nNo olvides de mí.",3,1,0,43,"",0,4,"i",23,0,-1,0,390,390,"558","",0,"","","",1,0,0,[],""],["carrizo_salta-n0559-01",3,"Tu recuerdo encantador,\nEs para mí tan querido,\nQue cuando pienso en tu amor,\nTodo lo demás olvido.",3,1,0,43,"",1,4,"io",101,0,-1,0,390,390,"559","",0,"","","",1,0,0,[],""],["carrizo_salta-n0560-01",3,"Tus ojos me han de llevar,\nDerechito al cementerio,\nSi no me miras, me matas,\nY si me miras, me muero.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,390,390,"560","",0,"","","",1,0,0,[],""],["carrizo_salta-n0561-01",3,"Tus ojos son aguaciles,\nY en la calle me prendieron,\nY tus cabellos, mi negra,\nDe cadenas me sirvieron.",3,1,0,43,"",0,4,"eo",105,0,-1,0,390,390,"561","",0,"","","",1,0,0,[],""],["carrizo_salta-n0562-01",3,"Tus ojos son cañones,\nDe artillería,\nQue le están apuntando\nAl alma mía.",3,1,0,43,"",6,4,"ia",0,0,-1,0,390,390,"562","",0,"","","",1,0,0,[],""],["carrizo_salta-n0563-01",3,"Tus ojos son como chispas,\nQue incendian mi corazón,\nÁmame como yo te amo,\nCorresponde a mi pasión.",3,1,0,43,"",0,4,"o",31,0,-1,0,390,390,"563","",0,"","","",1,0,0,[],""],["carrizo_salta-n0564-01",3,"Tus ojitos son dos brasas,\nDe lejos me están quemando,\nRetírese, no la quiero,\nVenga, le digo jugando!",3,1,0,43,"",0,4,"ao",33,0,-1,0,390,390,"564","",0,"","","",1,0,0,[],""],["carrizo_salta-n0565-01",3,"Tus ojos son dos centellas,\nMi corazón es un trueno,\nA ver si de mí te acuerdas,\nEstando en el primer sueño.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,390,390,"565","",0,"","","",1,0,0,[],""],["carrizo_salta-n0566-01",3,"Tus ojos son dos luceros,\nY dos rosas tus mejillas,\nTus labios son dos claveles,\nY tus pechitos dos limas.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,390,390,"566","",0,"","","",5,0,0,[],""],["carrizo_salta-n0567-01",3,"Tus ojos trigueños\nSe burlan de mí,\nY yo con los tuyos,\nNo puedo vivir.",3,1,0,43,"",0,4,"i",-1,0,-1,0,390,390,"567","",0,"","","",1,0,0,[],""],["carrizo_salta-n0568-01",3,"Tú sólito eres mi dueño,\nPara tus brazos nací,\n¿Quién me impide que te quiera?\n¿Quién tiene dominio en mí?",3,1,0,43,"",0,4,"i",23,0,-1,0,390,390,"568","",0,"","","",1,0,0,[],""],["carrizo_salta-n0569-01",3,"Un ángel bajó del cielo,\nCon un ramo de alhelí,\nPara decirte, vidita,\nEn este día seas feliz.",3,1,0,43,"",3,4,"i",-1,0,-1,0,390,390,"569","",0,"","","",1,0,0,[],""],["carrizo_salta-n0570-01",3,"Una sobra y una falta,\nTengo de tí, vida mía,\nLa sobra de ser hermosa,\nLa falta de no ser mía.",3,1,0,43,"",0,4,"ia",-1,0,-1,0,391,391,"570","",0,"","","",2,0,0,[],""],["carrizo_salta-n0571-01",3,"Una tijerita de oro,\nYo me quisiera comprar,\nPara cortarte las alas,\nCuando te quieras volar.",3,1,0,43,"",0,4,"a",21,0,-1,0,391,391,"571","",0,"","","",1,0,0,[],""],["carrizo_salta-n0572-01",3,"Una vez que me miraste,\nY otra vez que te miré,\nEn duda mi amor pusistes,\nY jamás te olvidaré.",3,1,0,43,"",0,4,"e",77,0,-1,0,391,391,"572","",0,"","","",2,0,0,[],""],["carrizo_salta-n0573-01",3,"Unos ojitos tenís,\nQue roban los corazones,\nY una boquita tan linda,\nQue llenan mis ilusiones.",3,1,0,43,"",0,4,"oe",34,0,-1,0,391,391,"573","",0,"","","",1,0,0,[],""],["carrizo_salta-n0574-01",3,"Vale más lo moreno,\nDe mi morena,\nQue toda la blancura,\nDe la azucena.",3,1,0,43,"",6,4,"ea",59,0,-1,0,391,391,"574","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],""],["carrizo_salta-n0575-01",3,"Válgame Dios de los cielos!\nEl amor que te hi tomado,\nEl rato que no te veo,\nPienso que me has olvidado.",3,1,0,43,"",0,4,"ao",14,0,-1,0,391,391,"575","",0,"","","",33,0,0,[],""],["carrizo_salta-n0576-01",3,"Vamos al campo, ñatita,\nYa que tu madre no sabe,\nY a gozar comenzaremos,\nAntes que el mundo se acabe.",3,1,0,43,"",0,4,"ae",131,0,-1,0,391,391,"576","",0,"","","",1,0,0,[],""],["carrizo_salta-n0576-a-01",3,"¡Vidita, te ando queriendo,\nPero tu madre no sabe,\nApúrate, la gocemos,\nAntes que el mundo se acabe.",3,1,0,43,"",0,4,"ae",131,0,-1,0,391,391,"576-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0577-01",3,"Vamos, vamos, vamos,\nYo te llevaré,\nAntes que olvidarte,\nLa vida daré.",3,1,0,43,"",0,4,"e",77,0,-1,0,391,391,"577","",0,"","","",1,0,0,[],""],["carrizo_salta-n0578-01",3,"Varios autores han dicho,\nQue la ausencia causa olvido,\nYo me ausenté de mi prenda,\nY olvidarla no he podido.",3,1,0,43,"",0,4,"io",101,0,-1,0,391,391,"578","",0,"","","",2,0,0,[],""],["carrizo_salta-n0579-01",3,"Varios autores han dicho,\nQue por tí me he de perder,\nSi ese es tu gusto y el mío,\nQue nos dejen padecer.",3,1,0,43,"",0,4,"e",20,0,-1,0,391,391,"579","",0,"","","",2,0,0,[],""],["carrizo_salta-n0580-01",3,"¡Veinticinco de Mayo!\nNueve de Julio,\n¡Amalhaya un pañuelo,\nCon nombre tuyo!",3,1,0,43,"",6,4,"uo",-1,0,-1,0,391,391,"580","",0,"","","",1,0,0,[],""],["carrizo_salta-n0581-01",3,"Venga aura, venga mañana,\nSiempre tu dueño hi de ser,\nSi no me cambias por otro,\nY no mudas parecer.",3,1,0,43,"",0,4,"e",20,0,-1,0,391,391,"581","",0,"","","",1,0,0,[],""],["carrizo_salta-n0582-01",3,"¡Vení, vidita mía,\nVení a mis brazos!\nQue al corazón lo tengo,\nHecho pedazos.",3,1,0,43,"",6,4,"ao",132,0,-1,0,391,391,"582","",0,"","","",2,0,0,[],""],["carrizo_salta-n0583-01",3,"Vení y parate a mi lado,\nGrandes rosas te daría,\nMañana cuando me muera,\nMemorias te dejaría.",3,1,0,43,"",0,4,"ia",0,0,-1,0,392,392,"583","",0,"","","",1,0,0,[],""],["carrizo_salta-n0584-01",3,"¿Ves aquella nube blanca,\nCon los cordones azules?\nAsí t' hi vestir a vos,\nCarita de ingratitudes.",3,1,0,43,"",0,4,"ue",-1,0,-1,0,392,392,"584","",0,"","","",2,0,0,[],""],["carrizo_salta-n0585-01",3,"¿Ves aquella nube blanca,\nQue viene volando abajo?\nCon esa me has de escribir,\nCuando te vea en trabajos.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,392,392,"585","",0,"","","",2,0,0,[],""],["carrizo_salta-n0585-a-01",3,"¿Ves aquella nube negra,\nQue se bate por abajo?\nAsí llomo por tu amor,\nCuando me veo en trabajos.",3,1,0,43,"",0,4,"ao",-1,0,-1,0,392,392,"585-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0586-01",3,"¿Ves aquella pluma blanca,\nCon la que vuela el halcón?\nCon esa te he de escribir,\nPrenda de mi corazón.",3,1,0,43,"",0,4,"o",31,0,-1,0,392,392,"586","",0,"","","",1,0,0,[],""],["carrizo_salta-n0587-01",3,"¡Vida mía, de mis ojos!\nRetrato de mi esperanza,\nAunque vos me pagues mal,\nEn mí no hallarás mudanza.",3,1,0,43,"",0,4,"aa",163,0,-1,0,392,392,"587","",0,"","","",1,0,0,[],""],["carrizo_salta-n0588-01",3,"¡Vidita, dame un besito!\nQue me voy a confesar,\nUn besito no es delito,\nDándolo con voluntad.",3,1,0,43,"",0,4,"a",-1,0,-1,0,392,392,"588","",0,"","","",1,0,0,[],""],["carrizo_salta-n0589-01",3,"¡Vidita del alma mía!\nTus pasos voy a seguir,\nCuando seas mi prenda amada,\nHi de dejar de sufrir.",3,1,0,43,"",0,4,"i",157,0,-1,0,392,392,"589","",0,"","","",1,0,0,[],""],["carrizo_salta-n0590-01",3,"¡Vidita, mucho la quiero!\nPero, ¿cómo ha de durar?\nCómo será que la quiero,\nNo puedo disimular.",3,1,0,43,"",1,4,"a",21,0,-1,0,392,392,"590","",0,"","","",1,0,0,[],""],["carrizo_salta-n0591-01",3,"¡Vidita, porque te quiero!\nMi vida la paso triste,\nComo canario en la jaula,\nCuando le falta el alpiste.",3,1,0,43,"",0,4,"ie",153,0,-1,0,392,392,"591","",0,"","","",1,0,0,[],""],["carrizo_salta-n0592-01",3,"¡Vidita, por que la quiero,\nNo me diga que le miento!\nDesde que la conocí,\nLa tengo en mi pensamiento.",3,1,0,43,"",0,4,"eo",94,0,-1,0,392,392,"592","",0,"","","",1,0,0,[],""],["carrizo_salta-n0593-01",3,"¡Vidita, si me querís!\nApróntate, vamonós,\nEn el camino hallaremos,\nRemedio para los dos.",3,1,0,43,"",0,4,"o",87,0,-1,0,392,392,"593","",0,"","","",10,0,0,[],""],["carrizo_salta-n0594-01",3,"¡Vidita, si me querís!\nA mis brazos arrimate,\nY si tu dueño viniera,\nPoco a poco, retirate.",3,1,0,43,"",0,4,"ae",384,0,-1,0,392,392,"594","",0,"","","",10,0,0,[],""],["carrizo_salta-n0595-01",3,"¡Vidita, si me querís!\nNo lo des a conocer,\nDecime con tus ojitos,\nQue ya no me querís ver.",3,1,0,43,"",0,4,"e",20,0,-1,0,392,392,"595","",0,"","","",10,0,0,[],""],["carrizo_salta-n0596-01",3,"¡Vidita, si me querís!\nVení cerquita de mí,\nQue yo te daré mi pecho,\nPara que puedas dormir.",3,1,0,43,"",0,4,"i",-1,0,-1,0,392,392,"596","",0,"","","",10,0,0,[],""],["carrizo_salta-n0597-01",3,"¡Vidita, si Vd. me quiere!\nNo se deje conocer,\nEn un chiquito de holgura,\nYo l' hi de corresponder.",3,1,0,43,"",0,4,"e",20,0,-1,0,392,392,"597","",0,"","","",1,0,0,[],""],["carrizo_salta-n0600-01",3,"Vidita, te estoy queriendo!\nPero hablarte no me animo,\nPorque tu mama es celosa,\nY me ha i cerrar el camino.",3,1,0,43,"",0,4,"io",-1,0,-1,0,393,393,"600","",0,"","","",5,0,0,[],""],["carrizo_salta-n0606-01",3,"Voy a sentarme a tu lado,\nCon el pecho dolorido.\nVoy a decirte un secreto:\nNo me digas atrevido.",3,1,0,43,"",0,4,"io",101,0,-1,0,393,393,"606","",0,"","","",1,0,0,[],""],["carrizo_salta-n0607-01",3,"Vuelvo a tu lado, morena,\nPublicando mi retiro,\nAunque estés en otros brazos,\nNo te hi de echar en olvido.",3,1,0,43,"",0,4,"io",-1,0,-1,0,393,393,"607","",0,"","","",1,0,0,[],""],["carrizo_salta-n0608-01",3,"Ya estamos en el empeño,\nYo no le temo al rigor,\nNo deparé de salvarme,\nSi me muero por su amor.",3,1,0,43,"",0,4,"o",72,0,-1,0,393,393,"608","",0,"","","",1,0,0,[],""],["carrizo_salta-n0609-01",3,"Ya sé que me has conocido,\nPor el eco de mi voz,\nY dirás desde la cama:\nEse que canta es mi amor.",3,1,0,43,"",0,4,"o",-1,0,-1,0,393,393,"609","",0,"","","",1,0,0,[],""],["carrizo_salta-n0610-01",3,"Ya t' hi dicho que te quiero,\nMás no te puedo querer,\nMi amor es agua de río,\nPara atrás no ha de volver.",3,1,0,43,"",0,4,"e",20,0,-1,0,393,393,"610","",0,"","","",1,0,0,[],""],["carrizo_salta-n0611-01",3,"Ya viene el alba y el día,\nPa mi pago rumbiaré,\nEnsillaré mi caballo,\nSi gusta la llevaré.",3,1,0,43,"",0,4,"e",77,0,-1,0,393,393,"611","",0,"","","",1,0,0,[],""],["carrizo_salta-n0612-01",3,"Ya viene mi mal creciendo,\nAumentando mi dolor,\nNo la hi de cambiar por otra,\nAunque me pague mejor.",3,1,0,43,"",0,4,"o",72,0,-1,0,393,393,"612","",0,"","","",1,0,0,[],""],["carrizo_salta-n0613-01",3,"Yo conozco un remedio,\nVidita mía, vidita mía,\nQue si te lo aplicara,\nTe sanaría, te sanaría.",3,1,0,43,"",3,4,"ia",0,0,-1,0,393,393,"613","",0,"","","",1,0,0,[],""],["carrizo_salta-n0614-01",3,"Yo la idolatro, y espero,\nContestación favorable,\nVa mi porvenir entero,\nEn su respuesta probable.",3,1,0,43,"",1,4,"ae",322,0,-1,0,394,394,"614","",0,"","","",1,0,0,[],""],["carrizo_salta-n0615-01",3,"Yo la quiero a la vidita,\nPorque todos la aborrecen,\nA dónde quiera que va,\nComo la yerba florece.",3,1,0,43,"",0,4,"ee",-1,0,-1,0,394,394,"615","",0,"","","",1,0,0,[],""],["carrizo_salta-n0615-02",3,"Yo las quiero a las mujeres,\nPorque de ellas soy nacido,\nPero con mayor razón,\nA aquellas que me han querido.",3,1,0,43,"",0,4,"io",101,0,-1,0,394,394,"615","",0,"","","",1,0,0,[],""],["carrizo_salta-n0617-01",3,"Yo le diré a mi negrita,\nY le diré con cautela:\n—Por su amor vivo, las vueltas,\nComo el pirpinto en la vela.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,394,394,"617","",0,"","","",1,0,0,[],""],["carrizo_salta-n0618-01",3,"Yo nací blanca y diré,\nLa razón de ser morena,\nEstoy adorando un sol,\nQue con sus rayos me quema.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,394,394,"618","",0,"","","",1,0,0,[],""],["carrizo_salta-n0619-01",3,"Yo quisiera el engañarte,\nDiciendo que no te quiero.\nPero mis ojos pregonan:\nAmor firme y lisonjero.",3,1,0,43,"",0,4,"eo",38,0,-1,0,394,394,"619","",0,"","","",1,0,0,[],""],["carrizo_salta-n0620-01",3,"Yo soy como la aceituna,\nPrendida del verde olivo,\nPor más lejos que me vaya,\nDe tu amor nunca me olvido.",3,1,0,43,"",0,4,"io",-1,0,-1,0,394,394,"620","",0,"","","",1,0,0,[],""],["carrizo_salta-n0621-01",3,"Yo soy como paja en l' era,\nTrastornada por el viento,\nMás trastornado me tiene,\nVidita, tu pensamiento.",3,1,0,43,"",0,4,"eo",94,0,-1,0,394,394,"621","",0,"","","",1,0,0,[],""],["carrizo_salta-n0622-01",3,"Yo soy fulano de tal,\nQue vivo en la soledad,\nUn año yo estuve ausente,\nY no te puedo olvidar.",3,1,0,43,"",0,4,"a",-1,0,-1,0,394,394,"622","",0,"","","",4,0,0,[],""],["carrizo_salta-n0623-01",3,"Yo soy mozo pobrecito,\nY si me pongo a querer,\nNo te prometo grandezas,\nSino mi buen proceder.",3,1,0,43,"",0,4,"e",20,0,-1,0,394,394,"623","",0,"","","",1,0,0,[],""],["carrizo_salta-n0624-01",3,"Yo tengo un sauce elegido,\nPa cruz de mi sepultura,\n¡Amalayas consiguiera,\nEl gozar de tu hermosura!",3,1,0,43,"",0,4,"ua",17,0,-1,0,394,394,"624","",0,"","","",1,0,0,[],""],["carrizo_salta-n0625-01",3,"Yo te prometí constancia,\nY constante t' hi cumplir.\nPorque constante hi nacido\nY constante hi de dar fin.",3,1,0,43,"",0,4,"i",-1,0,-1,0,394,394,"625","",0,"","","",1,0,0,[],""],["carrizo_salta-n0626-01",3,"Yo te quiero, tú me quieres,\nY amor los dos nos tenimos,\nEse es el gusto, vidita.\nQue ambos los dos nos querimos.",3,1,0,43,"",0,4,"io",329,0,-1,0,394,394,"626","",0,"","","",1,0,0,[],""],["carrizo_salta-n0627-01",3,"Yo t' hi querer, mi vidita,\nAunque se oponga San Diego,\nPorque el amor que te tengo,\nEs, vidita, un nudo ciego.",3,1,0,43,"",0,4,"eo",-1,0,-1,0,394,394,"627","",0,"","","",1,0,0,[],""],["carrizo_salta-n0628-01",3,"Yo ya me voy de su casa,\nYo ya me voy de su puerta,\nPero mi corazón queda,\nComo reloj dando vuelta.",3,1,0,43,"",0,4,"ea",-1,0,-1,0,394,394,"628","",0,"","","",1,0,0,[],""],["carrizo_salta-n0629-01",3,"Zarzamora, morenita,\nTan bonita como vos,\nYo me humillo a tí, vidita,\nZarzamora, morenita.",3,1,0,43,"",5,4,"ia",50,0,-1,0,394,394,"629","",0,"","","",1,0,0,[],""],["carrizo_salta-n0630-01",3,"¡Acaba, parca mi vida,\nCon tu guadaña aterrante!\nHorrorizado, decía,\nLleno de pena, un amante.",3,1,0,44,"",0,4,"ae",47,0,-1,0,396,396,"630","",0,"","","",1,0,0,[],""],["carrizo_salta-n0631-01",3,"Adentro de un rancho viejo,\nEn los campos l'Asunción,\nUnos ayes lastimeros,\nConmovían mi corazón.",3,1,0,44,"",0,4,"o",31,0,-1,0,396,396,"631","",0,"","","",1,0,0,[],""],["carrizo_salta-n0632-01",3,"A Dios le pido la muerte,\nDios no me la quiere dar,\nAbramén la sepultura,\nVivo me quiero enterrar.",3,1,0,44,"",0,4,"a",21,0,-1,0,396,396,"632","",0,"","","",4,0,0,[],""],["carrizo_salta-n0633-01",3,"A Dios le pido la muerte,\nDios no me la quiere dar,\nEl me dijo: Te eché al mundo,\nPara que sepas llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,396,396,"633","",0,"","","",4,0,0,[],""],["carrizo_salta-n0635-01",3,"A esa paloma blanca,\nQue canta sobre el peral,\nYo quisiera preguntarle,\nSi su amor sabe negar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,396,396,"635","",0,"","","",1,0,0,[],""],["carrizo_salta-n0637-01",3,"A este pobre corazón,\nNo le pague mal su amor,\nMire que se ha de cansar,\nDe tanta pena y dolor.",3,1,0,44,"",0,4,"o",72,0,-1,0,396,396,"637","",0,"","","",3,0,0,[],""],["carrizo_salta-n0638-01",3,"Agora, vuelta de nuevo,\nA poner nuevo cuidado,\nQuiero ver si están como antes\nO de mí se han olvidado,",3,1,0,44,"",0,4,"ao",14,0,-1,0,396,396,"638","",0,"","","",1,0,0,[],""],["carrizo_salta-n0639-01",3,"Agua que busca su centro,\nHay que formarle represa,\nPueda ser que con el tiempo,\nDe mi amor se compadezca.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,396,396,"639","",0,"","","",2,0,0,[],""],["carrizo_salta-n0640-01",3,"¡Aguilita voladora!\n¿Por qué no volás ahora?\nEchame sobre tus alas,\nQue yo soy tu dueño ahora.",3,1,0,44,"",0,4,"oa",-1,0,-1,0,396,396,"640","",0,"","","",1,0,0,[],""],["carrizo_salta-n0641-01",3,"Ahí sale el sol, velos negros,\nPóngase luto la luna,\nY de duelo las estrellas,\nAl ver mi mala fortuna.",3,1,0,44,"",0,4,"ua",56,0,-1,0,396,396,"641","",0,"","","",1,0,0,[],""],["carrizo_salta-n0642-01",3,"¡Ah, mis tiempos, cuando mozo;\nCuando sabía festejar!\nQuebrantado ahora me veo,\nNadie me quiere mirar.",3,1,0,44,"",0,4,"a",21,0,-1,0,396,396,"642","",0,"","","",1,0,0,[],""],["carrizo_salta-n0643-01",3,"Al acabarse' mi vida,\nSe acabará mi pesar,\nTodo quedará tranquilo,\nNadie podrá remediar.",3,1,0,44,"",0,4,"a",21,0,-1,0,396,396,"643","",0,"","","",1,0,0,[],""],["carrizo_salta-n0644-01",3,"A las montañas inmensas,\nYa me voy a retirar,\nSollozando, sollozando,\nComo agua de manantial.",3,1,0,44,"",0,4,"a",-1,0,-1,0,396,396,"644","",0,"","","",2,0,0,[],""],["carrizo_salta-n0645-01",3,"A las peñas di mis quejas,\nPor ver si me consolaba,\nComo la peña era dura,\nNi esperanzas no me daba.",3,1,0,44,"",0,4,"aa",28,0,-1,0,396,396,"645","",0,"","","",1,0,0,[],""],["carrizo_salta-n0646-01",3,"A la una y a las dos,\nA las tres ya me remato,\n¿Quién me compra el corazón,\nDespreciado de un ingrato?",3,1,0,44,"",0,4,"ao",19,0,-1,0,397,397,"646","",0,"","","",3,0,0,[],""],["carrizo_salta-n0647-01",3,"Al bosque más solitario,\nMe retiraré a vivir,\nPorque me ha salido cierto,\nLo que me sabían decir.",3,1,0,44,"",0,4,"i",157,0,-1,0,397,397,"647","",0,"","","",1,0,0,[],""],["carrizo_salta-n0648-01",3,"Al cavar mi sepultura,\nHallarán mi corazón,\nCon cien cadenas atado,\nComo si fuera un ladrón.",3,1,0,44,"",0,4,"o",31,0,-1,0,397,397,"648","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],""],["carrizo_salta-n0649-01",3,"Al cielo pido justicia,\nY el cielo me la ha de dar;\nSi el cielo no hace justicia,\nRazón tengo de llorar.",3,1,0,44,"",1,4,"a",21,0,-1,0,397,397,"649","",0,"","","",2,0,0,[],""],["carrizo_salta-n0651-01",3,"Al pie de una cruz bendita,\nLloraba por tu querer;\nLas lágrimas que vertía,\nSe cuajaban al caer.",3,1,0,44,"",0,4,"e",20,0,-1,0,397,397,"651","",0,"","","",2,0,0,[],""],["carrizo_salta-n0652-01",3,"Al sepulcro me encamino,\nBuscando mi triste suerte,\nPorque en la vida no encuentro,\nMás alivio que la muerte.",3,1,0,44,"",0,4,"ee",134,0,-1,0,397,397,"652","",0,"","","",2,0,0,[],""],["carrizo_salta-n0653-01",3,"¡Alto pino, alto pino!\nAl cielo llega tu rama,\nNo te derrames mi pino,\nQue me derramas el alma.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,397,397,"653","",0,"","","",1,0,0,[],""],["carrizo_salta-n0654-01",3,"Alzá la vista y mirame,\nCompadecete de mí,\nPedí permiso a tu dueño,\nEl te ha de decir que sí.",3,1,0,44,"",0,4,"i",23,0,-1,0,397,397,"654","",0,"","","",1,0,0,[],""],["carrizo_salta-n0655-01",3,"Allí donde hubo fuego,\nCenizas quedan,\nEn cenizas me veo,\nPor una pena.",3,1,0,44,"",6,4,"ea",-1,0,-1,0,397,397,"655","",0,"","","",1,0,0,[],""],["carrizo_salta-n0656-01",3,"¡Amalhayas, me muriera!\nYa me estuvieran velando,\nY mi vidita llorando,\nA gritos hablando, hablando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,397,397,"656","",0,"","","",1,0,0,[],""],["carrizo_salta-n0656-02",3,"¿Cuándo me moriré yo?\n¿Cuándo me estarán velando,\nY mis hijitos llorando,\nA gritos hablando, hablando?",3,1,0,44,"",0,4,"ao",33,0,-1,0,397,397,"656","",0,"","","",1,0,0,[],""],["carrizo_salta-n0660-01",3,"A mi corazón le dije,\nQue no suspire y no llore,\nQue si le han dado mal pago,\nNo ha de faltar quien lo adore.",3,1,0,44,"",0,4,"oe",77,0,-1,0,398,398,"660","",0,"","","",1,0,0,[],""],["carrizo_salta-n0661-01",3,"A mi corazón quisiera\nNo darle ningún desvelo,\nPero la prenda de mi alma,\nNo me da ningún consuelo.",3,1,0,44,"",0,4,"eo",10,0,-1,0,398,398,"661","",0,"","","",1,0,0,[],""],["carrizo_salta-n0662-01",3,"Amiguito de fulano,\nColorado como ají,\nHa de sentir mi amistad,\nCuando me boten de aquí.",3,1,0,44,"",0,4,"i",23,0,-1,0,398,398,"662","",0,"","","",4,0,0,[],""],["carrizo_salta-n0663-01",3,"A mí todos me aburrecen,\nNinguno a mí me ha de amar,\n¿Será por mi mala suerte,\nO por mi mal natural?",3,1,0,44,"",0,4,"a",-1,0,-1,0,398,398,"663","",0,"","","",1,0,0,[],""],["carrizo_salta-n0664-01",3,"Andando a solas yo lloro,\nY en conversación me río.\nPa que no diga la gente,\nQue andoy a disgusto mío.",3,1,0,44,"",0,4,"io",3,0,-1,0,398,398,"664","",0,"","","",1,0,0,[],""],["carrizo_salta-n0665-01",3,"¡Anda señalame un sitio,\nA donde yo me pueda ir!\nAllí lloraré mis penas,\nAcordándome de tí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,398,398,"665","",0,"","","",1,0,0,[],""],["carrizo_salta-n0666-01",3,"Anoche soñaba yo,\nQue otros brazos te tenían.\nGozabas de otras caricias,\nY no gozabas las mías.",3,1,0,44,"",0,4,"ia",-1,0,-1,0,398,398,"666","",0,"","","",9,0,0,[],""],["carrizo_salta-n0667-01",3,"Anteayer planté un repollo,\nEn la orilla de la playa.\n¿Pa' que te habré conocido,\nPara verte de esta laya?",3,1,0,44,"",0,4,"aa",404,0,-1,0,398,398,"667","",0,"","","",1,0,0,[],""],["carrizo_salta-n0668-01",3,"Antes cuando era chiquito,\nYo lloraba por mamar,\nAhora que grandecito,\nSólo lloro por amar.",3,1,0,44,"",1,4,"a",21,0,-1,0,398,398,"668","",0,"","","",12,0,0,[],""],["carrizo_salta-n0669-01",3,"Anteanoche y anoche,\nY esta mañana;\nPor tus ingratitudes,\nLloraba mi alma.",3,1,0,44,"",3,4,"aa",-1,0,-1,0,399,399,"669","",0,"","","",2,0,0,[],""],["carrizo_salta-n0670-01",3,"Antes de que yo me muera,\nHabían hecho mi inventario,\n¡Vuelvan las prendas al dueño!\nEl muerto ha resucitado.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,399,399,"670","",0,"","","",1,0,0,[],""],["carrizo_salta-n0671-01",3,"Antes era barca llena,\nHoy ya soy barca vacía,\nNo puedo entrar a la mar,\nPara hacer la travesía.",3,1,0,44,"",0,4,"ia",0,0,-1,0,399,399,"671","",0,"","","",1,0,0,[],""],["carrizo_salta-n0672-01",3,"Antes me ví por los altos,\nEn las sierras más frondosas,\nAhora me veo por los suelos,\n¡Miren cómo son las cosas!",3,1,0,44,"",3,4,"oa",61,0,-1,0,399,399,"672","",0,"","","",1,0,0,[],""],["carrizo_salta-n0673-01",3,"Antes te mandé recuerdos,\nEnvueltos en papel fino,\nAhora ya no te mando,\nPorque vivo resentido.",3,1,0,44,"",0,4,"io",-1,0,-1,0,399,399,"673","",0,"","","",1,0,0,[],""],["carrizo_salta-n0674-01",3,"Anti era Jesusito,\nAgora Jesú María,\nAnti era plata, en reales,\nAgora chafalonía.",3,1,0,44,"",0,4,"ia",0,0,-1,0,399,399,"674","",0,"","","",1,0,0,[],""],["carrizo_salta-n0675-01",3,"Antinoche fuí a tu casa,\nA que me dieras posada.\nDe allá me vine llorando,\nHallé tus puertas cerradas.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,399,399,"675","",0,"","","",1,0,0,[],""],["carrizo_salta-n0676-01",3,"Antinoche salí al monte,\nAl cacuy oí cantar,\nComo cantaba tan triste,\nTriste me puse a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,399,399,"676","",0,"","","",1,0,0,[],""],["carrizo_salta-n0677-01",3,"Antinoche tuve un sueño,\nY anoche volví a soñar,\n¡Qué sueño tan engañero,\nNunca me sale verdad!",3,1,0,44,"",0,4,"a",-1,0,-1,0,399,399,"677","",0,"","","",1,0,0,[],""],["carrizo_salta-n0678-01",3,"Años y meses se pasan,\nYa me estoy haciendo viejo,\nCada día para atrás,\nA la moda del cangrejo.",3,1,0,44,"",0,4,"eo",264,0,-1,0,399,399,"678","",0,"","","",1,0,0,[],""],["carrizo_salta-n0679-01",3,"Apenas soy fulanito,\nNada se me echa de ver,\nPor la prenda que yo quiero,\nVoy dispuesto a padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,399,399,"679","",0,"","","",2,0,0,[],""],["carrizo_salta-n0680-01",3,"Apenas soy ño Galván,\nAquí en estos momentitos,\nMi nombre se va acabando,\nDe poco en poco, en poquito.",3,1,0,44,"",0,4,"io",-1,0,-1,0,399,399,"680","",0,"","","",1,0,0,[],""],["carrizo_salta-n0681-01",3,"Apenas voy ño fulano,\nEl mismo que antes ha sido,\nNo me hago ni me deshago,\nEn un mismo ser yo vivo.",3,1,0,44,"",0,4,"io",-1,0,-1,0,399,399,"681","",0,"","","",1,0,0,[],""],["carrizo_salta-n0682-01",3,"Aquella estrella del cielo,\nQue brilla en Siete de Abril,\nLlorando se fué, mi negra,\nY ya no quiere venir.",3,1,0,44,"",0,4,"i",-1,0,-1,0,399,399,"682","",0,"","","",1,0,0,[],""],["carrizo_salta-n0683-01",3,"Aquí está el pobre fulano,\nQue se ha visto en apretura,\nCon un pié pisa en el mundo,\nCon otra en la sepoltura.",3,1,0,44,"",0,4,"ua",17,0,-1,0,399,399,"683","",0,"","","",1,0,0,[],""],["carrizo_salta-n0684-01",3,"Aquí está esta pobrecita,\nEl vestido hecho pedazos,\nAl verme pobre y desnuda,\n¿Quién diablos me va hacer caso?",3,1,0,44,"",0,4,"ao",-1,0,-1,0,399,399,"684","",0,"","","",1,0,0,[],""],["carrizo_salta-n0685-01",3,"Aquí está esta pobre moza,\nComo espina de un pencal,\nPor una prenda que estimo,\nMe han sentenciado en el mal.",3,1,0,44,"",0,4,"a",1,0,-1,0,400,400,"685","",0,"","","",1,0,0,[],""],["carrizo_salta-n0686-01",3,"Aquí he venido, amiguitas,\nA divertirme cantando,\nComo paloma trampiada,\nPaso en mi casa llorando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,400,400,"686","",0,"","","",1,0,0,[],""],["carrizo_salta-n0687-01",3,"Aquí me hallo en penitencia,\nEntre la pared y la espada.\nEn un pecho tan chiquito,\nNo pueden caber dos almas.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,400,400,"687","",0,"","","",1,0,0,[],""],["carrizo_salta-n0688-01",3,"Aquí respirando estoy,\nComo una cosa perdida,\nSe han alarmado de mí,\nComo cosa desvalida.",3,1,0,44,"",0,4,"ia",37,0,-1,0,400,400,"688","",0,"","","",1,0,0,[],""],["carrizo_salta-n0690-01",3,"¡Arboles, montes y selvas!\nAyúdenme a sentir penas,\nA mi vidita la llevan,\nLas voluntades ajenas.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,400,400,"690","",0,"","","",3,0,0,[],""],["carrizo_salta-n0691-a-01",3,"¡Caballero de fulano!\nTenga lástima de mí,\nSoy piedra que ando rodando,\nPuede tropezar en mí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,400,400,"691-a","",0,"","","",36,0,0,[],""],["carrizo_salta-n0692-01",3,"¡Arbolito, arbolito,\nDe verdes ramas!\nCuando te pido sombra,\nTe desparramas.",3,1,0,44,"",6,4,"aa",405,0,-1,0,400,400,"692","",0,"","","",3,0,0,[],""],["carrizo_salta-n0693-01",3,"¡Árbol, monte, rica selva,\nArboleda de manzana!\n¿Quién comería la fruta,\nSin ofenderle la rama?",3,1,0,44,"",0,4,"aa",-1,0,-1,0,400,400,"693","",0,"","","",1,0,0,[],""],["carrizo_salta-n0694-01",3,"¡Árbol! ¿Por qué te has secado,\nTeniendo tu riego al pié,\nEn el tronco la firmeza,\nY en el cogollo el querer?",3,1,0,44,"",0,4,"e",-1,0,-1,0,400,400,"694","",0,"","","",1,0,0,[],""],["carrizo_salta-n0695-01",3,"Arriba van las velas,\nY el viento en popa;\nNo sé qué rumbo lleva,\nMi pasión loca.",3,1,0,44,"",6,4,"oa",-1,0,-1,0,400,400,"695","",0,"","","",2,0,0,[],""],["carrizo_salta-n0696-01",3,"Arrimate al padecer,\nPadeceremos los dos,\nVos padecerás por mí,\nYo padeceré por vos.",3,1,0,44,"",0,4,"o",87,0,-1,0,400,400,"696","",0,"","","",1,0,0,[],""],["carrizo_salta-n0697-01",3,"Arroyos, playas y ríos,\nTodos quedan en la nada,\nAsí se quedó mi amor,\nDe la noche a la mañana.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,400,400,"697","",0,"","","",1,0,0,[],""],["carrizo_salta-n0698-01",3,"A San Antonio le pido,\nPero él no me quiere dar,\nAl niñito de sus brazos,\nPara ayudarme a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,401,401,"698","",0,"","","",6,0,0,[],""],["carrizo_salta-n0698-02",3,"A San Antonio le pido,\nY no me lo quiere dar,\nAl niño que está en sus brazos,\nQue me acompañe a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,401,401,"698","",0,"","","",6,0,0,[],""],["carrizo_salta-n0699-01",3,"Asentada en una piedra,\nDe las faldas de una loma,\nCantando se lamentaba,\nUna huérfana paloma.",3,1,0,44,"",0,4,"oa",86,0,-1,0,401,401,"699","",0,"","","",1,0,0,[],""],["carrizo_salta-n0700-01",3,"Así cantaba un cuyano,\nQue de pena se moría:\n—Por lejos que vos te vayas,\nT' hi de alcanzar algún día.",3,1,0,44,"",0,4,"ia",0,0,-1,0,401,401,"700","",0,"","","",1,0,0,[],""],["carrizo_salta-n0701-01",3,"Así había sido mi suerte,\nAsí había venido a ser,\nEsa es mi suerte, vidita,\nMi destino es padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,401,401,"701","",0,"","","",1,0,0,[],""],["carrizo_salta-n0702-01",3,"Así hagan toda la vida,\nNo hagan caso de mi amor,\nEn otro hallarán grandezas,\nEn mí no hallarán favor.",3,1,0,44,"",0,4,"o",72,0,-1,0,401,401,"702","",0,"","","",1,0,0,[],""],["carrizo_salta-n0703-01",3,"Así me han dicho,\nY andan diciendo,\nQue yo en las pajas,\nMe ando durmiendo.",3,1,0,44,"",6,4,"eo",52,0,-1,0,401,401,"703","",0,"","","",1,0,0,[],""],["carrizo_salta-n0704-01",3,"Así nomás es mi suerte,\nAsí nomás me sucede,\nPongo mis cinco sentidos,\nEn prenda que no me quiere.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,401,401,"704","",0,"","","",1,0,0,[],""],["carrizo_salta-n0705-01",3,"A tu casita,\nNo hi de llegar,\nPorque si llego,\nMe han de celar.",3,1,0,44,"",6,4,"a",21,0,-1,0,401,401,"705","",0,"","","",1,0,0,[],""],["carrizo_salta-n0706-01",3,"A tus puertas vengo,\nNo me digas: ¡quita!\nMás antes matame,\nBlanca palomita.",3,1,0,44,"",0,4,"ia",50,0,-1,0,401,401,"706","",0,"","","",1,0,0,[],""],["carrizo_salta-n0707-01",3,"Aunque me muera de amor,\nNo me vuelvo a apasionar,\nConozco que soy sin suerte,\nY no sirvo para amar.",3,1,0,44,"",0,4,"a",21,0,-1,0,401,401,"707","",0,"","","",1,0,0,[],""],["carrizo_salta-n0708-01",3,"Aunque yo viva muriendo,\nEn un continuo pesar,\nPadecer será mi suerte,\nQue no te puedo olvidar.",3,1,0,44,"",0,4,"a",21,0,-1,0,401,401,"708","",0,"","","",1,0,0,[],""],["carrizo_salta-n0709-01",3,"Ausente de vuestro cielo,\nTriste me puse a escribir,\nTomé la pluma en las manos,\nY un triste suspiro dí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,401,401,"709","",0,"","","",1,0,0,[],""],["carrizo_salta-n0710-01",3,"Ausente de tí he vivido,\nSabe Dios, con qué dolor;\nCon el alma atravesada,\nY preso mi corazón.",3,1,0,44,"",0,4,"o",-1,0,-1,0,401,401,"710","",0,"","","",1,0,0,[],""],["carrizo_salta-n0711-01",3,"¡Ave, no salgas al campo,\nPorque ahí está el cazador;\nSi te matan o te pegan,\nPara mí será el dolor!",3,1,0,44,"",0,4,"o",72,0,-1,0,402,402,"711","",0,"","","",1,0,0,[],""],["carrizo_salta-n0712-01",3,"¡Ay, amigo de fulano!\nAyudame a sentir penas,\nAquí está tu pobre amigo,\nEntre grillos y cadenas.",3,1,0,44,"",0,4,"ea",62,0,-1,0,402,402,"712","",0,"","","",1,0,0,[],""],["carrizo_salta-n0713-01",3,"¡Ay, amiguito i fulano!\nMucho le siento sus penas;\nLe quisiera remediar,\nCon la sangre de mis venas.",3,1,0,44,"",0,4,"ea",62,0,-1,0,402,402,"713","",0,"","","",1,0,0,[],""],["carrizo_salta-n0714-01",3,"Ayer nació una esperanza,\nPero se murió muy presto,\nY tuvo cuna y sepulcro,\nEn un rincón de mi pecho.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,402,402,"714","",0,"","","",1,0,0,[],""],["carrizo_salta-n0715-01",3,"Ayer salí de mi pago,\nHuyendo a la mala suerte,\nPara que dejen de estar,\nDeseándome la muerte.",3,1,0,44,"",0,4,"ee",134,0,-1,0,402,402,"715","",0,"","","",1,0,0,[],""],["carrizo_salta-n0716-01",3,"Ayer tarde, estando triste,\nAl pié de un hermoso pino,\nSentí que se lamentaba,\nLa palomita en su nido.",3,1,0,44,"",0,4,"io",-1,0,-1,0,402,402,"716","",0,"","","",1,0,0,[],""],["carrizo_salta-n0717-01",3,"¡Ay, juay juna!\n¡Velay tu fortuna!\n¿Qué has sacao, vidita?\nCosa ninguna.",3,1,0,44,"",3,4,"ua",56,0,-1,0,402,402,"717","",0,"","","",1,0,0,[],""],["carrizo_salta-n0718-01",3,"¡Ahijuna, puchita!\nSombrero compuesto,\nEstoy resentida,\nCuernos me has puesto.",3,1,0,44,"",6,4,"eo",83,0,-1,0,402,402,"718","",0,"","","",1,0,0,[],""],["carrizo_salta-n0719-01",3,"¡Ahijuna, puta mi amor!\nNo acaba de escarmentar,\nAnoche se vió en trabajos,\nHoy le vuelve a segundiar.",3,1,0,44,"",0,4,"a",21,0,-1,0,402,402,"719","",0,"","","",2,0,0,[],""],["carrizo_salta-n0720-01",3,"¡Ay, madrecita del Valle!\nCon toda mi alma te digo,\nQue me estoy aborbojado,\nComo se aborboja el trigo.",3,1,0,44,"",0,4,"io",106,0,-1,0,402,402,"720","",0,"","","",1,0,0,[],""],["carrizo_salta-n0721-01",3,"¡Ay, mi querida, fulana!\nFlorcita de árbol fragante,\nOiga mis tristes clamores,\nQuieramé para su amante.",3,1,0,44,"",0,4,"ae",47,0,-1,0,402,402,"721","",0,"","","",9,0,0,[],""],["carrizo_salta-n0722-01",3,"¡Ay, mi triste corazón!\nTan rodeado de pesares,\nNo tengo padre ni madre,\nNi encuentro consolación.",3,1,0,44,"",5,4,"o",31,0,-1,0,402,402,"722","",0,"","","",1,0,0,[],""],["carrizo_salta-n0723-01",3,"¡Ay, mi vida, antes serena,\nTornóse agitada y turbia!\nCambióse el placer en pena,\nDe amor gimo en la cadena.",3,1,0,44,"",5,4,"ea",59,0,-1,0,402,402,"723","",0,"","","",1,0,0,[],""],["carrizo_salta-n0724-01",3,"¡Ay, mi vidita del alma,\nBlanquita como una peña!\n¿Pa qué la conocería,\nPara morirme de pena?",3,1,0,44,"",0,4,"ea",-1,0,-1,0,402,402,"724","",0,"","","",1,0,0,[],""],["carrizo_salta-n0725-01",3,"¡Ay, pobrecita mi suerte!\nYa lo llevan destinado,\nAunque nunca ofendió a nadie,\nPobrecito, es desgraciado.",3,1,0,44,"",0,4,"ao",14,0,-1,0,403,403,"725","",0,"","","",1,0,0,[],""],["carrizo_salta-n0726-01",3,"¡Ay, que me pican las pulgas!\nQue no me dejan morir,\nNo son pulgas sino celos,\nQue me quitan el vivir.",3,1,0,44,"",0,4,"i",157,0,-1,0,403,403,"726","",0,"","","",1,0,0,[],""],["carrizo_salta-n0727-01",3,"¡Ay, suspiro, sólo vos!\nQue dentro del alma sales,\nSabes los acerbos males,\nQue padecemos los dos.",3,1,0,44,"",11,4,"o",87,0,-1,0,403,403,"727","",0,"","","",3,0,0,[],""],["carrizo_salta-n0728-01",3,"Bajo de aquel limón verde,\nDonde las aguas vertían,\nEntregué mi amor un día,\nA un tipo que no valía.",3,1,0,44,"",0,4,"ia",0,0,-1,0,403,403,"728","",0,"","","",1,0,0,[],""],["carrizo_salta-n0729-01",3,"Bajo de tanta esperanza,\nNiña ¿no habrá caridad?\n—\"Venga, Señor el tu reino\nHagasé tu voluntad\".",3,1,0,44,"",0,4,"a",16,0,-1,0,403,403,"729","",0,"","","",1,0,0,[],""],["carrizo_salta-n0730-01",3,"Bajo de un sauce llorón,\nDonde corre un arroyuelo,\nMe contastes tus desdichas,\nTus penas y tus desvelos.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,403,403,"730","",0,"","","",2,0,0,[],""],["carrizo_salta-n0731-01",3,"¡Caballero de fulano!\nAl pié de un frondoso olivo,\nComo el olivo es amargo,\nAsí entre amarguras vivo.",3,1,0,44,"",0,4,"io",351,0,-1,0,403,403,"731","",0,"","","",36,0,0,[],""],["carrizo_salta-n0732-01",3,"¡Caballero de fulano!\nAunque negra gente he sido,\nJamás he pagado mal,\nA quien amor me ha tenido.",3,1,0,44,"",0,4,"io",101,0,-1,0,403,403,"732","",0,"","","",36,0,0,[],""],["carrizo_salta-n0733-01",3,"Cada vez que canto digo:\n¡Ay, mis tiempos que se harían!\nAntes era real de plata,\nAhora, chafalonía.",3,1,0,44,"",0,4,"ia",-1,0,-1,0,403,403,"733","",0,"","","",1,0,0,[],""],["carrizo_salta-n0734-01",3,"Cada vez que considero\nY vuelvo a considerar,\nComienzan mis tristes ojos,\nGotas de sangre a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,403,403,"734","",0,"","","",14,0,0,[],""],["carrizo_salta-n0735-01",3,"Cada vez que paso y miro,\nEl sitio donde vivió,\nCon la casa me divierto,\nEl pájaro se voló.",3,1,0,44,"",0,4,"o",2,0,-1,0,403,403,"735","",0,"","","",25,0,0,[],""],["carrizo_salta-n0736-01",3,"Callate, no digas nada,\nAguantá si me querís;\nSi es mucho tu sufrimiento\nCon el tiempo gozarís.",3,1,0,44,"",0,4,"i",58,0,-1,0,403,403,"736","",0,"","","",1,0,0,[],""],["carrizo_salta-n0737-01",3,"Canales tengo en la cara,\nDe tanto llorar por tí,\n¡Pucha que soy desgraciado!\nYa nadie me quiere a mí.",3,1,0,44,"",0,4,"i",23,0,-1,0,404,404,"737","",0,"","","",2,0,0,[],""],["carrizo_salta-n0738-01",3,"Cantaré mi pena triste,\nQue mi pecho aflige tanto,\nAgora si pueden ojos,\nLargarle la rienda al llanto.",3,1,0,44,"",0,4,"ao",30,0,-1,0,404,404,"738","",0,"","","",2,0,0,[],""],["carrizo_salta-n0738-02",3,"Cantaré mi pena triste\nQue mi pecho aflige tanto,\nLloraré mares de sangre,\nLargaré mi rienda al llanto.",3,1,0,44,"",0,4,"ao",30,0,-1,0,404,404,"738","",0,"","","",2,0,0,[],""],["carrizo_salta-n0738-02-e2",3,"¡Caramba que estoy t; on pena!\nNo hallo que hacerme;\nSi me tiro a los campos,\nTemo perderme.",3,1,0,44,"",6,4,"ee",245,0,-1,0,404,404,"738","",0,"","","",1,0,0,[],""],["carrizo_salta-n0740-01",3,"¡Caramba que estoy mellado!\nComo hacha de quebrar güeso,\nParece que me ha salido,\nSobregüeso en el pescuezo.",3,1,0,44,"",0,4,"eo",345,0,-1,0,404,404,"740","",0,"","","",1,0,0,[],""],["carrizo_salta-n0741-01",3,"¡Caramba que me hallo pobre!\nDe pobre me andoy muriendo,\nYa no encuentro quién me quiera,\nYo solo, me andoy queriendo.",3,1,0,44,"",0,4,"eo",52,0,-1,0,404,404,"741","",0,"","","",3,0,0,[],""],["carrizo_salta-n0742-01",3,"¡Caramba que me hallo pobre!\nNo tengo nada que hacer,\nMe ha elegido la pobreza,\nY no tengo qué vender.",3,1,0,44,"",0,4,"e",20,0,-1,0,404,404,"742","",0,"","","",3,0,0,[],""],["carrizo_salta-n0743-01",3,"¡Caramba que me hallo pobre!\nQue mi pobreza no vale,\nNo soy como el hombre rico,\nDonde quiera dentra y sale.",3,1,0,44,"",0,4,"ae",202,0,-1,0,404,404,"743","",0,"","","",3,0,0,[],""],["carrizo_salta-n0744-01",3,"¡Caramba que tengo pena!\nMe dan ganas de llorar,\nVoy a ensillar mi caballo,\nPara mandarme a mudar.",3,1,0,44,"",0,4,"a",21,0,-1,0,404,404,"744","",0,"","","",1,0,0,[],""],["carrizo_salta-n0745-01",3,"¡Caramba que ya estoy viejo!\nMe ha apretado la vejez,\nAquí andoy como chiquillo,\nCaminando a cuatro pies.",3,1,0,44,"",0,4,"e",218,0,-1,0,404,404,"745","",0,"","","",1,0,0,[],""],["carrizo_salta-n0747-01",3,"Carta te escribo,\nPapel te mando,\nSi no te reciben bien,\nVolvete papel llorando.",3,1,0,44,"",3,4,"ao",33,0,-1,0,404,404,"747","",0,"","","",1,0,0,[],""],["carrizo_salta-n0748-01",3,"Casa de quicha y adobe,\nTodo ha sido para tí,\nPero todo ha sido en vano,\n¡Cogollito de alhelí!",3,1,0,44,"",0,4,"i",23,0,-1,0,404,404,"748","",0,"","","",1,0,0,[],""],["carrizo_salta-n0749-01",3,"Catorce años pa los quince,\n¡Madre me quiero casar!\nSi no me caso a los veinte,\nDe monja me voy a entrar.",3,1,0,44,"",0,4,"a",21,0,-1,0,404,404,"749","",0,"","","",1,0,0,[],""],["carrizo_salta-n0750-01",3,"Cautivita soy, señores,\nLloro mi cautividad,\nHasta que del cielo baje\nCarta de mi libertad.",3,1,0,44,"",0,4,"a",16,0,-1,0,405,405,"750","",0,"","","",1,0,0,[],""],["carrizo_salta-n0751-01",3,"Cavemén la sepultura\nVivo me quiero enterrar,\nPara no ver mi morena,\nQue me ha pagado tan mal.",3,1,0,44,"",0,4,"a",-1,0,-1,0,405,405,"751","",0,"","","",1,0,0,[],""],["carrizo_salta-n0752-01",3,"Celos me dan de comer,\nCelos me dan de beber,\nCelos a la media noche,\nCelos al amanecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,405,405,"752","",0,"","","",1,0,0,[],""],["carrizo_salta-n0753-01",3,"Cerrito blanco de arena,\nCada día polvia el viento.\nVamonós, vidita mía,\nDonde olvide mi tormento.",3,1,0,44,"",0,4,"eo",94,0,-1,0,405,405,"753","",0,"","","",1,0,0,[],""],["carrizo_salta-n0754-01",3,"Como la perla del mar\nTengo una herida escondida,\nUna herida tan querida,\nQue nunca la he de curar.",3,1,0,44,"",11,4,"a",21,0,-1,0,405,405,"754","",0,"","","",1,0,0,[],""],["carrizo_salta-n0755-01",3,"¡Cómo no hi de llorar yo!\n¡Cómo no hi de tener pena!\nSi a mi vidita la llevan,\nLas voluntades ajenas.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,405,405,"755","",0,"","","",1,0,0,[],""],["carrizo_salta-n0756-01",3,"Como si fuera árbol seco,\nQue ya no tiene verdura,\nAsí yo vivo penando,\nPor gozar de tu hermosura.",3,1,0,44,"",0,4,"ua",17,0,-1,0,405,405,"756","",0,"","","",1,0,0,[],""],["carrizo_salta-n0757-01",3,"Con el rocío del cielo,\nCrecen las pintadas flores,\nCon el riego de mis ojos,\nCrecen mis tristes amores.",3,1,0,44,"",0,4,"oe",5,0,-1,0,405,405,"757","",0,"","","",1,0,0,[],""],["carrizo_salta-n0758-01",3,"Creció abundante la planta,\nY sus ráices me han herido,\nComo la sembré en otoño,\nMal pago me ha producido.",3,1,0,44,"",0,4,"io",101,0,-1,0,405,405,"758","",0,"","","",1,0,0,[],""],["carrizo_salta-n0760-01",3,"¿Cuál es aquel pajarillo\nQue canta sobre el cebil?\nLe quisiera preguntar\nSi su amor sabe seguir.",3,1,0,44,"",0,4,"i",-1,0,-1,0,405,405,"760","",0,"","","",1,0,0,[],""],["carrizo_salta-n0761-01",3,"¿Cuál es ese pajarillo\nQué canta sobre el chalchal?\nYo le quiero preguntar,\nSi su amor sabe chanciar.",3,1,0,44,"",0,4,"a",21,0,-1,0,405,405,"761","",0,"","","",3,0,0,[],""],["carrizo_salta-n0761-a-01",3,"¿Cuál es ese pajarillo\nQué canta sobre el chañar?\nYo le quiero preguntar,\nSi su amor sabe chanciar.",3,1,0,44,"",0,4,"a",21,0,-1,0,405,405,"761-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n0762-01",3,"¿Cuál es ese pajarillo\nQué canta sobre el nogal?\nYo le quiero preguntar\nSi su amor sabe trinar.",3,1,0,44,"",0,4,"a",21,0,-1,0,405,405,"762","",0,"","","",3,0,0,[],""],["carrizo_salta-n0763-01",3,"Cuando contemplo una niña,\nDice mi alma con tristeza:\n¡Lástima que tal capullo\nEn rosa al fin se convicta!",3,1,0,44,"",5,4,"ia",-1,0,-1,0,406,406,"763","",0,"","","",1,0,0,[],""],["carrizo_salta-n0765-01",3,"Cuando me fuí para abajo,\nMe volví al año cumplido\nVine en busca mi vidita,\nOtro dueño había tenido.",3,1,0,44,"",0,4,"io",101,0,-1,0,406,406,"765","",0,"","","",4,0,0,[],""],["carrizo_salta-n0766-01",3,"Cuando me fuí para abajo\nA los cinco años volví,\nVine y te hallé en otros brazos\nA los desiertos me fuí.",3,1,0,44,"",0,4,"i",23,0,-1,0,406,406,"766","",0,"","","",4,0,0,[],""],["carrizo_salta-n0767-01",3,"Cuando me llegue a morir,\nCinco años no ha de llover,\nSe han de secar las vertientes,\nLos ríos no han de correr.",3,1,0,44,"",0,4,"e",20,0,-1,0,406,406,"767","",0,"","","",1,0,0,[],""],["carrizo_salta-n0768-01",3,"Cuando muera mi morena,\nPagando la haré velar,\nPagando el \"cuerpo presente\",\nPagando la haré enterrar.",3,1,0,44,"",0,4,"a",21,0,-1,0,406,406,"768","",0,"","","",2,0,0,[],""],["carrizo_salta-n0768-a-01",3,"Cuando muera mi morena,\nPagando la haré velar,\nPagando irá al cementerio,\nPagando la haré enterrar.",3,1,0,44,"",0,4,"a",21,0,-1,0,406,406,"768-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0769-01",3,"Cuando pensé tener gusto,\nTuve un pesar sin segundo,\nNo pienso tener jamás,\nGusto cabal en el mundo.",3,1,0,44,"",0,4,"uo",179,0,-1,0,406,406,"769","",0,"","","",1,0,0,[],""],["carrizo_salta-n0770-01",3,"Cuando salí de Santiago\nTodo el camino lloré,\nCon lágrimas de mis ojos,\nMontes y campos regué.",3,1,0,44,"",0,4,"e",77,0,-1,0,406,406,"770","",0,"","","",1,0,0,[],""],["carrizo_salta-n0771-01",3,"Cuando sepas que m'hi muerto,\n¡Qué contenta quedarás!\nDe mis continuas molestias,\nProntito te olvidarás.",3,1,0,44,"",0,4,"a",51,0,-1,0,406,406,"771","",0,"","","",1,0,0,[],""],["carrizo_salta-n0772-01",3,"Cuando te escribo esta carta,\n¡Sabe Dios lo que me cuesta!\nLlorando a cada momento,\nEsperando tu respuesta.",3,1,0,44,"",0,4,"ea",406,0,-1,0,406,406,"772","",0,"","","",1,0,0,[],""],["carrizo_salta-n0773-01",3,"Cuando yo la conocí,\nNo era de esa condición,\nCausa los malos consejos,\nMe anda por jugar traición.",3,1,0,44,"",0,4,"o",31,0,-1,0,406,406,"773","",0,"","","",1,0,0,[],""],["carrizo_salta-n0774-01",3,"Cuando yo nací en el mundo,\nNo supe lo que era amor,\nLos golpes y los tormentos,\nMe han dicho que era dolor.",3,1,0,44,"",0,4,"o",72,0,-1,0,406,406,"774","",0,"","","",1,0,0,[],""],["carrizo_salta-n0775-01",3,"¡Chacarera, chacarera!\n¡Chacarera 'El Carrizal\"!\nYo me voy a la otra banda,\nAquí me han pagado mal.",3,1,0,44,"",0,4,"a",1,0,-1,0,406,406,"775","",0,"","","",13,0,0,[],""],["carrizo_salta-n0776-01",3,"¡Chacarera, chacarera!\n¿Qué no te aflige el amor?\nSi sabes que por tí paso,\nEn un eterno dolor.",3,1,0,44,"",0,4,"o",-1,0,-1,0,406,406,"776","",0,"","","",13,0,0,[],""],["carrizo_salta-n0777-01",3,"Dame la mano, bien mío,\nQue me estoy por despedir,\nQuizás la suerte me arrastre,\nA otro pago a morir.",3,1,0,44,"",0,4,"i",157,0,-1,0,406,406,"777","",0,"","","",1,0,0,[],""],["carrizo_salta-n0778-01",3,"Dame la mano, mi alma,\nDame los brazos,\nQue el corazón lo tengo,\nHecho pedazos.",3,1,0,44,"",6,4,"ao",132,0,-1,0,406,406,"778","",0,"","","",1,0,0,[],""],["carrizo_salta-n0779-01",3,"Dame tus ojos, vidita,\nQue quiero tener dos pares,\nQue los míos no son basta\nPara llorar mis pesares.",3,1,0,44,"",0,4,"ae",164,0,-1,0,406,406,"779","",0,"","","",1,0,0,[],""],["carrizo_salta-n0780-01",3,"Debajo de un limón verde,\nDonde sembré mi confianza,\nMemorias hi de dejar\nNo coseché ni esperanzas.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,407,407,"780","",0,"","","",9,0,0,[],""],["carrizo_salta-n0781-01",3,"Debajo de un sauce verde,\nDonde el agua corre fría,\nLloré las amargas penas,\nQue tiene la vida mía.",3,1,0,44,"",0,4,"ia",0,0,-1,0,407,407,"781","",0,"","","",3,0,0,[],""],["carrizo_salta-n0782-01",3,"De esta banda a l'otra banda.\nAl pié de un tierno laurel,\nMe puse a reflexionar,\nMirando l'agua correr.",3,1,0,44,"",0,4,"e",-1,0,-1,0,407,407,"782","",0,"","","",5,0,0,[],""],["carrizo_salta-n0783-01",3,"De esta banda a l'otra banda,\nYo no soy dueño de ir,\nCausa de las malas lenguas,\nQue averiguan el vivir.",3,1,0,44,"",0,4,"i",157,0,-1,0,407,407,"783","",0,"","","",5,0,0,[],""],["carrizo_salta-n0783-a-01",3,"De mi casa para fuera,\nNo soy dueño de salir,\nHay gente de mala lengua,\nQue averiguan mi vivir.",3,1,0,44,"",0,4,"i",157,0,-1,0,407,407,"783-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0783-b-01",3,"De mi casa para afuera,\nNo soy dueño de salir,\nPorque hay muchos adulones,\nQue adivinan el vivir.",3,1,0,44,"",0,4,"i",157,0,-1,0,407,407,"783-b","",0,"","","",1,0,0,[],""],["carrizo_salta-n0784-01",3,"De graves penas cubierto,\nMi pecho se queja a voces,\nSólo para mí se hicieron\nLos tormentos más atroces.",3,1,0,44,"",0,4,"oe",205,0,-1,0,407,407,"784","",0,"","","",1,0,0,[],""],["carrizo_salta-n0785-01",3,"De la cara diera un ojo,\nDe la mano diera un dedo.\nPa olvidar a mi vidita,\nPero olvidarla no puedo.",3,1,0,44,"",0,4,"eo",304,0,-1,0,407,407,"785","",0,"","","",1,0,0,[],""],["carrizo_salta-n0786-01",3,"Del accidente de amor,\nUn poco mejor me siento,\nCon una libra de olvido,\nY una oncita de escarmiento.",3,1,0,44,"",0,4,"eo",94,0,-1,0,407,407,"786","",0,"","","",1,0,0,[],""],["carrizo_salta-n0787-01",3,"De lao de arriba hi venío,\nPor l'orilla de la mar,\nPor preguntarles diciendo,\nSi han visto mi amor pasar.",3,1,0,44,"",0,4,"a",21,0,-1,0,407,407,"787","",0,"","","",2,0,0,[],""],["carrizo_salta-n0788-01",3,"De lao de arriba me vengo,\nPerdido por el camino,\nAtravesando montañas,\nComo si fuera querido.",3,1,0,44,"",0,4,"io",-1,0,-1,0,407,407,"788","",0,"","","",1,0,0,[],""],["carrizo_salta-n0789-01",3,"De la piedra nace l'agua,\nDe los árboles el viento,\nDe mi pecho nacen coplas,\nDel corazón sentimientos.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,407,407,"789","",0,"","","",1,0,0,[],""],["carrizo_salta-n0789-a-01",3,"De las peñas nace el agua,\nDe los árboles el viento,\nDel pecho la vida mía,\nNacen malos pensamientos.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,407,407,"789-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0790-01",3,"De la planta la granada,\nNace una flor colorada,\nDe mi triste corazón,\nNace una espina clavada.",3,1,0,44,"",0,4,"aa",49,0,-1,0,407,407,"790","",0,"","","",1,0,0,[],""],["carrizo_salta-n0791-01",3,"De la rama de una rosa,\nUn lindo pimpollo ví.\nVine y se seca la rama,\nPorque desgraciada fuí.",3,1,0,44,"",0,4,"i",23,0,-1,0,407,407,"791","",0,"","","",1,0,0,[],""],["carrizo_salta-n0793-01",3,"De los hijos de mi madre,\nSólo yo nací llorando,\nY había sido para que ande,\nDe tierra en tierra rodando.",3,1,0,44,"",3,4,"ao",33,0,-1,0,408,408,"793","",0,"","","",1,0,0,[],""],["carrizo_salta-n0794-01",3,"De los hombres desgraciados,\nPrimero me cuento yo.\nComo la desgracia es peste\nA mí primero me dió.",3,1,0,44,"",0,4,"o",2,0,-1,0,408,408,"794","",0,"","","",1,0,0,[],""],["carrizo_salta-n0795-01",3,"De los montes de Santiago,\nA los montes de Jujuy,\nMe quejo como el crespín,\nY lloro como el cacuy.",3,1,0,44,"",0,4,"i",-1,0,-1,0,408,408,"795","",0,"","","",1,0,0,[],""],["carrizo_salta-n0796-01",3,"De mi pago i Talapampa.\n¿A qué pucha me vendría?\nDe la mitá la quebrada\n¿Cómo no me volvería?",3,1,0,44,"",0,4,"ia",0,0,-1,0,408,408,"796","",0,"","","",1,0,0,[],""],["carrizo_salta-n0796-a-01",3,"De mi pago i Villa Vía\n¿Para qué yo me vendría?\nDe medio de la quebrada\n¿Cómo no me volvería?",3,1,0,44,"",0,4,"ia",0,0,-1,0,408,408,"796-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0797-01",3,"Demos principio a este fin,\nAntes que otro pesar venga,\nEl fin es finalizar,\nNo hay cosa que fin no tenga.",3,1,0,44,"",0,4,"ea",407,0,-1,0,408,408,"797","",0,"","","",1,0,0,[],""],["carrizo_salta-n0798-01",3,"Dentro las flores del campo,\nBusco y no puedo encontrar,\nUna que me cause alivio,\nPara poder descansar.",3,1,0,44,"",0,4,"a",21,0,-1,0,408,408,"798","",0,"","","",1,0,0,[],""],["carrizo_salta-n0799-01",3,"Dentro de mi corazón,\nTengo una hojita de lata,\nY en esa hojita, vidita,\nUna pena que me mata.",3,1,0,44,"",0,4,"aa",74,0,-1,0,408,408,"799","",0,"","","",7,0,0,[],""],["carrizo_salta-n0800-01",3,"De para abajo hi venío,\nEscribiendo contra el viento,\nLa letra viene diciendo:\n¿Cuál será su pensamiento?",3,1,0,44,"",0,4,"eo",-1,0,-1,0,408,408,"800","",0,"","","",1,0,0,[],""],["carrizo_salta-n0801-01",3,"¿De qué me sirve ser fino\nSi voy perdiendo la vida?\n¿De qué sirve la esperanza\nSi la hi de llorar perdida?",3,1,0,44,"",0,4,"ia",37,0,-1,0,408,408,"801","",0,"","","",1,0,0,[],""],["carrizo_salta-n0802-01",3,"¿De qué peña nacerías?\n¿De qué duro pedernal?\n¿Con qué corazón dejaste\nA un peregrino llorar?",3,1,0,44,"",0,4,"a",-1,0,-1,0,408,408,"802","",0,"","","",1,0,0,[],""],["carrizo_salta-n0803-01",3,"¡De qué sirve mi existencia!\n¡De qué sirve haber nacido!\nSi no hi de lograr mi intento\nNo la hubiese conocido.",3,1,0,44,"",0,4,"io",101,0,-1,0,408,408,"803","",0,"","","",2,0,0,[],""],["carrizo_salta-n0804-01",3,"¿De qué te quejas, quejoso?\nTe quejas sin tener penas,\nCuando por vos en el mundo,\nAndo arrastrando cadenas.",3,1,0,44,"",0,4,"ea",62,0,-1,0,408,408,"804","",0,"","","",1,0,0,[],""],["carrizo_salta-n0805-01",3,"De Salta al Ceibal,\nDe Salta al Ceibal,\nNada me han hecho\nCon pagarme mal.",3,1,0,44,"",6,4,"a",1,0,-1,0,408,408,"805","",0,"","","",1,0,0,[],""],["carrizo_salta-n0806-01",3,"¡Desespera, desespera!\nDijo el fiel de la balanza,\nAsí desespera un hombre,\nCuando pretende y no alcanza.",3,1,0,44,"",0,4,"aa",163,0,-1,0,408,408,"806","",0,"","","",1,0,0,[],""],["carrizo_salta-n0807-01",3,"Desde arriba m'hi venío\nNadando como patito,\nPorque en el pago ande vivo,\nTriste lo paso sólito.",3,1,0,44,"",5,4,"oo",-1,0,-1,0,408,408,"807","",0,"","","",17,0,0,[],""],["carrizo_salta-n0808-01",3,"Desgraciados como yo,\nNo sé si en el mundo hubiera,\nA desgraciao no me ganan,\nA dichoso sí, cualquiera.",3,1,0,44,"",0,4,"ea",44,0,-1,0,409,409,"808","",0,"","","",1,0,0,[],""],["carrizo_salta-n0809-01",3,"De toditos mis hermanos,\nSólo yo nací llorando,\nHasta el agua del bautismo,\nPara mí estuvo faltando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,409,409,"809","",0,"","","",2,0,0,[],""],["carrizo_salta-n0810-01",3,"De todos mis hermanitos,\nSólo yo nací llorando,\nHabía sido para andar\nDe pago en pago rodando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,409,409,"810","",0,"","","",1,0,0,[],""],["carrizo_salta-n0811-01",3,"De tu casa a la mía,\nNo hay más que un paso,\nY para hacerte mía,\nTan largo plazo.",3,1,0,44,"",6,4,"ao",43,0,-1,0,409,409,"811","",0,"","","",4,0,0,[],""],["carrizo_salta-n0812-01",3,"Dichosos son los que gozan,\nDel fresco que traen los vientos,\nSólo para mí se hicieron,\nDesprecios y sufrimientos.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,409,409,"812","",0,"","","",1,0,0,[],""],["carrizo_salta-n0813-01",3,"Dichosos son los que tienen,\nAmor en la vecindad,\nSólo yo soy desgraciado,\nQue ni lejos puedo hallar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,409,409,"813","",0,"","","",1,0,0,[],""],["carrizo_salta-n0814-01",3,"Dicen que de la granada,\nNacen flores coloradas,\nDe mi triste corazón,\nNacen espinas clavadas.",3,1,0,44,"",0,4,"aa",282,0,-1,0,409,409,"814","",0,"","","",1,0,0,[],""],["carrizo_salta-n0815-01",3,"Dicen que han visto\nA mi negra llorar,\nDejelán, que sola\nSe ha de consolar.",3,1,0,44,"",3,4,"a",21,0,-1,0,409,409,"815","",0,"","","",1,0,0,[],""],["carrizo_salta-n0816-01",3,"Dicen que los ajuérenos,\nTienen suerte pa querer,\nYo también soy ajuereño,\nSuerte no pudo tener.",3,1,0,44,"",0,4,"e",20,0,-1,0,409,409,"816","",0,"","","",1,0,0,[],""],["carrizo_salta-n0816-a-01",3,"Dicen que los tunaleños,\nTienen suerte pa querer,\nYo también soy tunaleño,\nSuerte no puedo tener.",3,1,0,44,"",0,4,"e",20,0,-1,0,409,409,"816-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0817-01",3,"Dicen que tras la alegría,\nSuele venir el dolor,\nYo conozco los dolores,\nPero la alegría no.",3,1,0,44,"",0,4,"o",-1,0,-1,0,409,409,"817","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["carrizo_salta-n0818-01",3,"Dicen que la golondrina,\nPasa el mar de un sólo vuelo,\nAsí quisiera olvidar,\nMi pena y mi desconsuelo.",3,1,0,44,"",0,4,"eo",10,0,-1,0,409,409,"818","",0,"","","",12,0,0,[],""],["carrizo_salta-n0819-01",3,"Dicen que la mar es grande,\nPero no cabe un suspiro,\nAhí me mandan a enterrar,\nPor pedimento i Cupido.",3,1,0,44,"",0,4,"io",-1,0,-1,0,409,409,"819","",0,"","","",2,0,0,[],""],["carrizo_salta-n0820-01",3,"Dicen que las penas matan,\nYo digo: no puede ser.\nQue si las penas mataran,\nNo me hicieran padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,409,409,"820","",0,"","","",6,0,0,[],""],["carrizo_salta-n0821-01",3,"Dices que me querís mucho,\n¡Es mentira, que me engañas!\nEn un pecho tan pequeño\nNo pueden caber dos almas.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,410,410,"821","",0,"","","",1,0,0,[],""],["carrizo_salta-n0822-01",3,"Dices que me quieres mucho,\nY con que te pagaré,\nCon quererte yo otro tanto,\nNada te quedo a deber.",3,1,0,44,"",0,4,"e",-1,0,-1,0,410,410,"822","",0,"","","",13,0,0,[],""],["carrizo_salta-n0823-01",3,"Dígales a mis amigos,\nY a todas mis relaciones,\nQue de este infeliz cautivo,\nReciban las expresiones.",3,1,0,44,"",0,4,"oe",34,0,-1,0,410,410,"823","",0,"","","",1,0,0,[],""],["carrizo_salta-n0824-01",3,"Dí riendas a mi caballo,\nPor ver si yo la alcanzaba,\nCada paso que pegaba,\nGotas de sangre lloraba.",3,1,0,44,"",0,4,"aa",28,0,-1,0,410,410,"824","",0,"","","",1,0,0,[],""],["carrizo_salta-n0825-01",3,"Divertite cantando,\nCalla y no llores;\nEstas son pesadumbres,\nQue dan los hombres.",3,1,0,44,"",6,4,"oe",-1,0,-1,0,410,410,"825","",0,"","","",1,0,0,[],""],["carrizo_salta-n0826-01",3,"¿Dónde estará mi vidita\nTomando su rico mate?\nAquí está su pobrecito\nDespreciado hasta el remate.",3,1,0,44,"",0,4,"ae",384,0,-1,0,410,410,"826","",0,"","","",1,0,0,[],""],["carrizo_salta-n0827-01",3,"¿Dónde se hallarán mis prendas?\n¿Quién de ellas se habrá apropiado?\nAntes de que yo muera\nYa me han hecho el inventario.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,410,410,"827","",0,"","","",1,0,0,[],""],["carrizo_salta-n0828-01",3,"Dos pareceres te pongo,\n¿De cuál quieres escoger?\nVer a tu querida muerta,\nO ajena, en otro poder.",3,1,0,44,"",0,4,"e",20,0,-1,0,410,410,"828","",0,"","","",1,0,0,[],""],["carrizo_salta-n0829-01",3,"Dulces recuerdos queridos,\nQue nunca más volverán,\nRecuerdos de un bien perdido,\nMuy lejos de mi se van.",3,1,0,44,"",0,4,"a",147,0,-1,0,410,410,"829","",0,"","","",1,0,0,[],""],["carrizo_salta-n0830-01",3,"Duraznito blanco\nPepita rosada,\nTodos con su vidita\nYo sólo, nada.",3,1,0,44,"",6,4,"aa",49,0,-1,0,410,410,"830","",0,"","","",2,0,0,[],""],["carrizo_salta-n0831-01",3,"Echemén al calabozo\nDonde no haiga sol ni luna,\nAllá dentro lloraré\nToda mi mala fortuna.",3,1,0,44,"",0,4,"ua",56,0,-1,0,410,410,"831","",0,"","","",1,0,0,[],""],["carrizo_salta-n0832-01",3,"El cielo vista de luto,\nDe negro manto la luna,\nHagan duelo las estrellas\nDe esta mi mala fortuna.",3,1,0,44,"",0,4,"ua",56,0,-1,0,410,410,"832","",0,"","","",1,0,0,[],""],["carrizo_salta-n0833-01",3,"El ciervo en su soledad,\nNo siente ningún quebranto,\nYo a pesar de vivir solo.\n¡Vivo padeciendo tanto!",3,1,0,44,"",0,4,"ao",30,0,-1,0,410,410,"833","",0,"","","",1,0,0,[],""],["carrizo_salta-n0834-01",3,"El corazón tengo mudo,\nCon los ojos vengo hablando,\nA fuerza de ser discreto,\nMe vengo disimulando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,410,410,"834","",0,"","","",1,0,0,[],""],["carrizo_salta-n0835-01",3,"El corazón tengo triste,\nEl alma tengo confusa,\nAlgo me va a suceder,\nTriste el corazón me anuncia.",3,1,0,44,"",0,4,"ua",-1,0,-1,0,411,411,"835","",0,"","","",3,0,0,[],""],["carrizo_salta-n0836-01",3,"El cuervo con el ser cuervo,\nNunca pierde su volido,\n¿Cómo querís que yo pierda\nTu amor, mi dueño querido?",3,1,0,44,"",0,4,"io",101,0,-1,0,411,411,"836","",0,"","","",1,0,0,[],""],["carrizo_salta-n0836-a-01",3,"Yo soy como el cuervo negro,\nQue no pierde su volido,\n¿Cómo querís que yo pierda\nUn corazón tan querido?",3,1,0,44,"",0,4,"io",101,0,-1,0,411,411,"836-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0837-01",3,"El día paso contento,\nLa noche con aprensión;\nRecordando tus amores,\nPalpita mi corazón.",3,1,0,44,"",0,4,"o",31,0,-1,0,411,411,"837","",0,"","","",1,0,0,[],""],["carrizo_salta-n0838-01",3,"El día que tengo pena,\nNi llorando me consuelo.\n¿Por qué no hi de llorar yo\nEstando presente el duelo?",3,1,0,44,"",0,4,"eo",10,0,-1,0,411,411,"838","",0,"","","",1,0,0,[],""],["carrizo_salta-n0839-01",3,"El día que usted se aparte,\nLa vida me han de quitar,\nYo dijunto y usted ausente,\nNadie nos ha de llorar.",3,1,0,44,"",3,4,"a",21,0,-1,0,411,411,"839","",0,"","","",1,0,0,[],""],["carrizo_salta-n0840-01",3,"El domingo por la tarde,\nSe enteran los siete días,\nTriste me puse a llorar,\nDe ver que no aparecías.",3,1,0,44,"",0,4,"ia",214,0,-1,0,411,411,"840","",0,"","","",1,0,0,[],""],["carrizo_salta-n0841-01",3,"El martes, amargo día,\nPrincipio de mis trabajos,\nNo me quisiera acordar,\nCuando salí de tus brazos.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,411,411,"841","",0,"","","",1,0,0,[],""],["carrizo_salta-n0842-01",3,"El negro que tiene plata,\nDonde quiera dentra y sale;\nComo yo soy negro pobre\nNi las razones me valen.",3,1,0,44,"",0,4,"ae",-1,0,-1,0,411,411,"842","",0,"","","",1,0,0,[],""],["carrizo_salta-n0843-01",3,"El otro día a la mañana,\nSe me oscureció una nube,\nEse había sido el mal pago,\nDe una querida que tuve.",3,1,0,44,"",0,4,"ue",348,0,-1,0,411,411,"843","",0,"","","",1,0,0,[],""],["carrizo_salta-n0844-01",3,"El pañuelo que me distes,\nMarcado con carmesí,\nTiene en las puntas suspiros,\nY en el centro un ¡ay, de mí!",3,1,0,44,"",0,4,"i",23,0,-1,0,411,411,"844","",0,"","","",1,0,0,[],""],["carrizo_salta-n0845-01",3,"El tiempo dichas me dió,\nYo pesares elegí,\nYo no me quejo del tiempo,\nQuéjese el tiempo de mí.",3,1,0,44,"",0,4,"i",23,0,-1,0,411,411,"845","",0,"","","",1,0,0,[],""],["carrizo_salta-n0846-01",3,"El viento lleva las flores,\nNinguna puedo pescar,\nTodas dicen: tengo dueño;\nCuando las salgo a buscar.",3,1,0,44,"",0,4,"a",21,0,-1,0,411,411,"846","",0,"","","",1,0,0,[],""],["carrizo_salta-n0847-01",3,"En aquellos altos montes,\nEn aquellas faldas lomas,\nEnternecida se queja,\nUna güerfana paloma.",3,1,0,44,"",0,4,"oa",-1,0,-1,0,411,411,"847","",0,"","","",1,0,0,[],""],["carrizo_salta-n0848-01",3,"Encarcelada me veo,\nSólo a llorar apetezco,\nSin volar a las montañas,\nSoy una ave que padezco.",3,1,0,44,"",0,4,"eo",355,0,-1,0,411,411,"848","",0,"","","",1,0,0,[],""],["carrizo_salta-n0849-01",3,"En el corazón de un hombre,\nSemilla de amor sembré;\nSin recordar que en las rocas,\nFlores no pueden nacer.",3,1,0,44,"",0,4,"e",-1,0,-1,0,411,411,"849","",0,"","","",1,0,0,[],""],["carrizo_salta-n0850-01",3,"En el Jardín del amor,\nSembré cuando fuí querido,\nY perdida la semilla,\nSoy el más aborrecido.",3,1,0,44,"",0,4,"io",101,0,-1,0,412,412,"850","",0,"","","",2,0,0,[],""],["carrizo_salta-n0851-01",3,"En el mar planté una viña,\nY alcanzó el sarmiento al cielo,\n¿Dónde se irá a consolar\nEl que no tenga consuelo?",3,1,0,44,"",0,4,"eo",10,0,-1,0,412,412,"851","",0,"","","",1,0,0,[],""],["carrizo_salta-n0852-01",3,"En el río de Angastaco,\nCorre el agua sollozando,\nEn el pago de Pucara,\nCorre mi ausencia llorando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,412,412,"852","",0,"","","",1,0,0,[],""],["carrizo_salta-n0853-01",3,"Enfermo estoy en la cama,\nMuerto estoy en realidad,\nNo hay médico que me sane,\nNi hay remedio pa mi mal.",3,1,0,44,"",0,4,"a",-1,0,-1,0,412,412,"853","",0,"","","",3,0,0,[],""],["carrizo_salta-n0854-01",3,"En la costa de un arroyo,\nEn la sombra de un laurel,\nPensando tener ganancia,\nPuse mi amor a vender.",3,1,0,44,"",0,4,"e",-1,0,-1,0,412,412,"854","",0,"","","",1,0,0,[],""],["carrizo_salta-n0855-01",3,"En la falda de aquel cerro,\nLlora triste un gavilán,\nNo llora porque tiene hambre,\nSino porque es animal.",3,1,0,44,"",0,4,"a",-1,0,-1,0,412,412,"855","",0,"","","",54,0,0,[],""],["carrizo_salta-n0856-01",3,"En la falda de aquel cerro,\nTriste lloré mi tormento,\nDigo la verdad no miento,\nPorque soy de cumplimiento.",3,1,0,44,"",0,4,"eo",94,0,-1,0,412,412,"856","",0,"","","",54,0,0,[],""],["carrizo_salta-n0857-01",3,"En la labranza el amor,\nToda mi pasión gasté,\nPara que otro esté gozando,\nTerrenos que cultivé.",3,1,0,44,"",0,4,"e",77,0,-1,0,412,412,"857","",0,"","","",1,0,0,[],""],["carrizo_salta-n0858-01",3,"En la noche más oscura,\nAl ruido de los canales,\nSalió un amante a buscar,\nRemedio para sus males.",3,1,0,44,"",0,4,"ae",26,0,-1,0,412,412,"858","",0,"","","",1,0,0,[],""],["carrizo_salta-n0859-01",3,"En la orilla de aquel campo,\nTengo una casa de piedra,\nAllá dentro lloraré\nCuando me deje mi negra.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,412,412,"859","",0,"","","",1,0,0,[],""],["carrizo_salta-n0860-01",3,"En la orilla de la mar,\nTriste llora el caraguay,\nEn sus suspiros decía,\n¿Qué dirán de mi por ahí?",3,1,0,44,"",5,4,"i",-1,0,-1,0,412,412,"860","",0,"","","",1,0,0,[],""],["carrizo_salta-n0861-01",3,"En la punta de una lanza,\nBatalla mi corazón.\nPor un falso testimonio,\nEl me cela sin razón.",3,1,0,44,"",0,4,"o",31,0,-1,0,412,412,"861","",0,"","","",1,0,0,[],""],["carrizo_salta-n0862-01",3,"En la situación que me hallo,\nNo hay parientes, no hay amigos,\nYa todos se han olvidado,\nDe un infeliz abatido.",3,1,0,44,"",0,4,"io",-1,0,-1,0,412,412,"862","",0,"","","",1,0,0,[],""],["carrizo_salta-n0863-01",3,"En mi casa me dicen,\nSi yo te quiero;\nYo digo que ni verte...\n¡Cuándo no puedo!",3,1,0,44,"",6,4,"eo",-1,0,-1,0,412,412,"863","",0,"","","",11,0,0,[],""],["carrizo_salta-n0864-01",3,"En mil novecientos,\nPerdí mi amor,\nCautiva y sola,\nNo tengo valor.",3,1,0,44,"",6,4,"o",72,0,-1,0,412,412,"864","",0,"","","",1,0,0,[],""],["carrizo_salta-n0865-01",3,"En mis tiempos cuando mozo,\nYo tenía un árbol pal cielo,\nVino un triste carpintero,\nCon su hacha me lo echó al suelo.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,412,412,"865","",0,"","","",6,0,0,[],""],["carrizo_salta-n0866-01",3,"¿En qué hora nacería,\nUn hijo tan desgraciado?\n¿Cómo no me moriría\nAntes de ser bautizado?",3,1,0,44,"",1,4,"ao",14,0,-1,0,413,413,"866","",0,"","","",1,0,0,[],""],["carrizo_salta-n0867-01",3,"¿En qué modo soy tan pobre\nY nací tan infeliz?\nQue hasta de las piedras brotan\nLenguas para hablar de mí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,413,413,"867","",0,"","","",1,0,0,[],""],["carrizo_salta-n0868-01",3,"Entre Córdoba y Lucena,\nHay una laguna clara,\nDonde lloraba mis penas,\nCuando de tí me acordaba.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,413,413,"868","",0,"","","",1,0,0,[],""],["carrizo_salta-n0869-01",3,"Entre sus barrotes canta,\nLa calandria prisionera,\nCanta su dura prisión,\nPor no morirse de pena.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,413,413,"869","",0,"","","",1,0,0,[],""],["carrizo_salta-n0870-01",3,"En un campito verdoso,\nHay un yuyito frondoso,\nAsí son muchas las penas,\nQue pasa este pobre mozo.",3,1,0,44,"",0,4,"oo",156,0,-1,0,413,413,"870","",0,"","","",1,0,0,[],""],["carrizo_salta-n0871-01",3,"Es para mí, mi vida,\nDuro tormento,\nEl verte y no gozarte\nCada momento.",3,1,0,44,"",6,4,"eo",94,0,-1,0,413,413,"871","",0,"","","",1,0,0,[],""],["carrizo_salta-n0872-01",3,"Es pobre mi pensamiento,\nY amargo mi padecer,\nDe verla andar en el mundo,\nPrenda linda en mal poder.",3,1,0,44,"",0,4,"e",20,0,-1,0,413,413,"872","",0,"","","",1,0,0,[],""],["carrizo_salta-n0873-01",3,"Esta es la vida del hombre,\nEsta es la vida i nosotros,\nCuando nos llega la muerte,\nLa mujer queda para otro.",3,1,0,44,"",0,4,"oo",-1,0,-1,0,413,413,"873","",0,"","","",1,0,0,[],""],["carrizo_salta-n0874-01",3,"Esta tonada que cantan,\nCantaba con mi vidita,\nAgora ya no la canto,\nPorque hi quedado sólita.",3,1,0,44,"",5,4,"oa",-1,0,-1,0,413,413,"874","",0,"","","",1,0,0,[],""],["carrizo_salta-n0875-01",3,"Este año pa carnaval,\nNada no tengo de bueno,\nLa moza que me quería,\nYa había tenido otro dueño.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,413,413,"875","",0,"","","",22,0,0,[],""],["carrizo_salta-n0876-01",3,"Este es mi lindo tesoro,\nQue me sirve de cadena;\nA lejas tierras me voy,\nPorque te veo prenda ajena.",3,1,0,44,"",0,4,"ea",59,0,-1,0,413,413,"876","",0,"","","",1,0,0,[],""],["carrizo_salta-n0877-01",3,"Esto digo porque es cierto,\nMando mi suspiro y va,\nAl lugar donde ella vive,\nA ver los pasos que da.",3,1,0,44,"",0,4,"a",9,0,-1,0,413,413,"877","",0,"","","",1,0,0,[],""],["carrizo_salta-n0878-01",3,"Estoy tan hecho a las penas,\nQue me sirve de compaña,\nEl día que no las tengo,\nMe parece cosa extraña.",3,1,0,44,"",0,4,"aa",213,0,-1,0,413,413,"878","",0,"","","",1,0,0,[],""],["carrizo_salta-n0879-01",3,"¡Estrellita de alto cielo!\n¡Estrellita reluciente!\nYo siempre me pongo luto\nPorque mi dueño está ausente.",3,1,0,44,"",0,4,"ee",15,0,-1,0,413,413,"879","",0,"","","",2,0,0,[],""],["carrizo_salta-n0880-01",3,"Flor marchita y sin esencia,\nBusco en la muerte querencia,\nPorque siento que se apaga,\nEl candil de mi existencia.",3,1,0,44,"",0,4,"ea",46,0,-1,0,414,414,"880","",0,"","","",1,0,0,[],""],["carrizo_salta-n0883-01",3,"Ganas tengo de morir\nY también no dejar verme,\nSobre el mundo disponer,\nY en un aujero esconderme.",3,1,0,44,"",0,4,"ee",245,0,-1,0,414,414,"883","",0,"","","",1,0,0,[],""],["carrizo_salta-n0885-a-01",3,"Hace lunas y menguantes,\nQue yo te ando por hablar,\nLa vergüenza me retira\nY tu amor me hace llegar.",3,1,0,44,"",0,4,"a",21,0,-1,0,414,414,"885-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0886-01",3,"Las estrellitas del cielo,\nY las arenas del mar,\nSe parecen a mis penas,\nEn lo largo de contar.",3,1,0,44,"",0,4,"a",21,0,-1,0,414,414,"886","",0,"","","",25,0,0,[],""],["carrizo_salta-n0887-01",3,"Las ilusiones de ayer,\nSe agotaron una a una,\nY de esas horas felices,\nNo me ha quedado ninguna.",3,1,0,44,"",0,4,"ua",56,0,-1,0,414,414,"887","",0,"","","",1,0,0,[],""],["carrizo_salta-n0888-01",3,"Hace un siglo que padezco,\nYo por tu amor me desvelo,\nMe mantiene la esperanza\nDe ser tuyo si no muero.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,414,414,"888","",0,"","","",1,0,0,[],""],["carrizo_salta-n0889-01",3,"Haré un hoyito en la arena\nY vivo me enterraré,\nPa no ver en brazos de otro\nPrenda que tanto estimé.",3,1,0,44,"",0,4,"e",77,0,-1,0,414,414,"889","",0,"","","",5,0,0,[],""],["carrizo_salta-n0890-01",3,"¿Hasta cuándo serán penas?\n¿Hasta cuándo hi padecer?\nSerá hasta cuando me vea,\n¿Dulce prenda, en su poder?",3,1,0,44,"",0,4,"e",20,0,-1,0,414,414,"890","",0,"","","",1,0,0,[],""],["carrizo_salta-n0891-01",3,"¿Hasta cuándo seré yo,\nPapel de contradición?\nDonde quiera que conversen\nDe mí es la conversación.",3,1,0,44,"",0,4,"o",31,0,-1,0,415,415,"891","",0,"","","",5,0,0,[],""],["carrizo_salta-n0891-a-01",3,"¿Hasta cuándo seré yo,\nPobre que dé compasión?\nDonde quiera que conversen\nDe mí es la conversación.",3,1,0,44,"",0,4,"o",31,0,-1,0,415,415,"891-a","",0,"","","",5,0,0,[],""],["carrizo_salta-n0892-01",3,"¿Hasta cuándo, vida mía,\nMe va a tener padeciendo?\nAl verla gozar se me hace\nQue la vida estoy perdiendo.",3,1,0,44,"",0,4,"eo",52,0,-1,0,415,415,"892","",0,"","","",11,0,0,[],""],["carrizo_salta-n0893-01",3,"Hasta el alma tengo triste,\nY enlutado el corazón,\nPorque tengo una pasión\nQue a todas horas me asiste.",3,1,0,44,"",11,4,"ie",153,0,-1,0,415,415,"893","",0,"","","",2,0,0,[],""],["carrizo_salta-n0894-01",3,"Hasta las piedras sufren,\nEl viento y la flor,\nY los ríos se lamentan\nCuando me lamento yo.",3,1,0,44,"",0,4,"o",-1,0,-1,0,415,415,"894","",0,"","","",1,0,0,[],""],["carrizo_salta-n0895-01",3,"Hasta la cuenta he perdido,\nDe los años de mi vida,\n¿Qué cuenta le daré a Dios,\nCuando Dios cuenta me pida?",3,1,0,44,"",0,4,"ia",37,0,-1,0,415,415,"895","",0,"","","",1,0,0,[],""],["carrizo_salta-n0896-01",3,"¿Has visto al sol ausentarse\nDejando al mundo sombrío?\nAsí se me enluta el alma\nPor tu ausencia, dueño mío.",3,1,0,44,"",0,4,"io",3,0,-1,0,415,415,"896","",0,"","","",1,0,0,[],""],["carrizo_salta-n0897-01",3,"Hay suspiros como truenos,\nLágrimas como aguacero,\nOtros son los que atormentan,\nYo hi de ser el pegadero.",3,1,0,44,"",0,4,"eo",38,0,-1,0,415,415,"897","",0,"","","",1,0,0,[],""],["carrizo_salta-n0898-01",3,"Hay una niña en la troya,\nQue a mí me tiene penando,\nElla se hace la que no oye,\nCuando yo le estoy cantando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,415,415,"898","",0,"","","",1,0,0,[],""],["carrizo_salta-n0899-01",3,"Helado se quedó el río,\nY la lomita nevada,\nAsí se quedó mi amor\nDe la noche a la mañana.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,415,415,"899","",0,"","","",1,0,0,[],""],["carrizo_salta-n0901-01",3,"¡Infelices ojos míos!\n¿De qué tienen qué llorar?\nCuando la vida se acaba\nUn gusto ¿qué ha de durar?",3,1,0,44,"",0,4,"a",21,0,-1,0,415,416,"901","",0,"","","",2,0,0,[],""],["carrizo_salta-n0909-01",3,"Las campanas de tus bodas,\nRepican tus alegrías,\nPara mí son los responsos,\nPor las ilusiones mías.",3,1,0,44,"",0,4,"ia",214,0,-1,0,416,416,"909","",0,"","","",1,0,0,[],""],["carrizo_salta-n0910-01",3,"Las nubes del alto cielo,\nSe visten de azul celeste,\nY yo me visto de negro,\nPorque mi amor está ausente.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,416,416,"910","",0,"","","",1,0,0,[],""],["carrizo_salta-n0910-a-01",3,"Las estrellitas del cielo,\nSe visten de azul celeste,\nY yo me visto de negro,\nPorque mi dueña está ausente.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,416,416,"910-a","",0,"","","",25,0,0,[],""],["carrizo_salta-n0911-01",3,"Las olas del mar,\nLas olas del mar,\nNo las hi visto,\nLas oigo llorar.",3,1,0,44,"",6,4,"a",21,0,-1,0,416,416,"911","",0,"","","",1,0,0,[],""],["carrizo_salta-n0912-01",3,"Las penitas que yo siento,\nPenitas de mujer joven,\nSon amarguitas lo mismo\nQue las hojitas del molle.",3,1,0,44,"",0,4,"oe",-1,0,-1,0,416,416,"912","",0,"","","",2,0,0,[],""],["carrizo_salta-n0913-01",3,"Lástima me estoy teniendo,\nDe verme peregrinando,\nCausa mi mala fortuna,\n¡Paguen mis ojos llorando!",3,1,0,44,"",0,4,"ao",33,0,-1,0,416,416,"913","",0,"","","",1,0,0,[],""],["carrizo_salta-n0914-01",3,"Lástima que soy borracho,\nMi mujer es querendona,\nLo quiere al rico y al pobre,\nSin distinción de persona.",3,1,0,44,"",0,4,"oa",7,0,-1,0,416,416,"914","",0,"","","",1,0,0,[],""],["carrizo_salta-n0915-01",3,"Lástima que ya soy viejo,\nYa no me puedo acordar,\nLas cosas que ya han pasado,\nY no las puedo anotar.",3,1,0,44,"",0,4,"a",21,0,-1,0,417,417,"915","",0,"","","",1,0,0,[],""],["carrizo_salta-n0916-01",3,"Le cantaba a una rubita,\nQue la estaba enamorando,\nVino su amante y se fué,\nY me dejó suspirando.",3,1,0,44,"",0,4,"ao",33,0,-1,0,417,417,"916","",0,"","","",1,0,0,[],""],["carrizo_salta-n0917-01",3,"Lindo canta un divertido,\nTriste llora un pobrecito,\nAsí tristes lloran todos,\nViejos, mozos y chiquitos.",3,1,0,44,"",0,4,"io",-1,0,-1,0,417,417,"917","",0,"","","",1,0,0,[],""],["carrizo_salta-n0918-01",3,"Los campos y las montañas,\nFlorecen a costa mía,\nPorque merecen el riego,\nDe mis ojos cada día.",3,1,0,44,"",0,4,"ia",0,0,-1,0,417,417,"918","",0,"","","",1,0,0,[],""],["carrizo_salta-n0919-01",3,"Los tiempos nunca han podido,\nBorrarte de mi memoria,\nY viéndome confundido,\nPenas se han vuelto mis glorias.",3,1,0,44,"",0,4,"oa",-1,0,-1,0,417,417,"919","",0,"","","",1,0,0,[],""],["carrizo_salta-n0920-01",3,"¡Luna que alumbras el mundo!\n¿Díme si has visto en la tierra,\nMujer más buena que yo,\nY que pase tantas penas?",3,1,0,44,"",0,4,"ea",-1,0,-1,0,417,417,"920","",0,"","","",1,0,0,[],""],["carrizo_salta-n0921-01",3,"Llega la tarde sombría,\nY la noche con su horror,\nA dar pesares a mi alma,\nY partir mi corazón.",3,1,0,44,"",0,4,"o",-1,0,-1,0,417,417,"921","",0,"","","",1,0,0,[],""],["carrizo_salta-n0922-01",3,"Llevo en mis plantas la muerte,\nDentro mi pecho un abismo,\nY en mi cabeza el bautismo,\nDe mi desgraciada suerte.",3,1,0,44,"",11,4,"ee",134,0,-1,0,417,417,"922","",0,"","","",1,0,0,[],""],["carrizo_salta-n0923-01",3,"Lloro como lastimada,\nMe quejo como afligida,\nComo aquel que lo lastiman,\nY resuella por l'herida.",3,1,0,44,"",0,4,"ia",-1,0,-1,0,417,417,"923","",0,"","","",1,0,0,[],""],["carrizo_salta-n0924-01",3,"Maldigo todas las horas\nAl que me enseñó a querer,\nPorque muy bien lo pasaba,\nInocente sin saber.",3,1,0,44,"",0,4,"e",20,0,-1,0,417,417,"924","",0,"","","",1,0,0,[],""],["carrizo_salta-n0925-01",3,"Maldigo la suerte mía,\nY el primer paso que dí,\nDesde mi primer quebranto,\nEl mal camino seguí.",3,1,0,44,"",0,4,"i",23,0,-1,0,417,417,"925","",0,"","","",1,0,0,[],""],["carrizo_salta-n0926-01",3,"Mañana me voy a Salta,\nDe Salta me iré a Jujuy,\nY de Jujuy a los montes,\nA llorar como el cacuy.",3,1,0,44,"",0,4,"i",408,0,-1,0,417,417,"926","",0,"","","",2,0,0,[],""],["carrizo_salta-n0927-01",3,"Mañana me voy a Salta,\nDe Salta para Santiago,\nDe Santiago al campamento,\nA llorar mi sentimiento.",3,1,0,44,"",5,4,"eo",94,0,-1,0,417,417,"927","",0,"","","",2,0,0,[],""],["carrizo_salta-n0928-01",3,"Mañana me voy por Salta,\nA la Puna de Jujuy,\nSuspirando por los campos,\nLos ojos como cacuy.",3,1,0,44,"",0,4,"i",408,0,-1,0,417,417,"928","",0,"","","",1,0,0,[],""],["carrizo_salta-n0929-01",3,"Mañana se van los quintos,\nYo no me quisiera ir,\nPorque en esta calle tengo,\nUn capullo a medio abrir.",3,1,0,44,"",0,4,"i",157,0,-1,0,418,418,"929","",0,"","","",10,0,0,[],""],["carrizo_salta-n0931-01",3,"Más antes de morir en mozo,\nY no recargado de años.\nPara no ser estropajo,\nDe todo el género humano.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,418,418,"931","",0,"","","",1,0,0,[],""],["carrizo_salta-n0931-a-01",3,"Más vale morir en mozo,\nNo llegar a ser anciano,\nPara no ser estropajo,\nDe todo el género humano.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,418,418,"931-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0932-01",3,"Me dicen que me consuele,\nCon el mismo desconsuelo,\nYo los vería consolarse,\nEstando presente el duelo.",3,1,0,44,"",0,4,"eo",10,0,-1,0,418,418,"932","",0,"","","",1,0,0,[],""],["carrizo_salta-n0933-01",3,"Me fuí a las fiestas reales,\nPor ver si me consolaba,\nOí sonido de cuerdas,\n¡Qué tristeza me causaba!",3,1,0,44,"",0,4,"aa",28,0,-1,0,418,418,"933","",0,"","","",1,0,0,[],""],["carrizo_salta-n0935-01",3,"Mi corazón es de bronce,\nSiento pero no hi llorar,\nPorque no hi de remediar\nCon mi llanto, tanto mal.",3,1,0,44,"",0,4,"a",-1,0,-1,0,418,418,"935","",0,"","","",1,0,0,[],""],["carrizo_salta-n0936-01",3,"Mi corazón está triste\nLe dan ganas de llorar,\nCuando le dicen que calle,\nMás sentimiento le da.",3,1,0,44,"",0,4,"a",-1,0,-1,0,418,418,"936","",0,"","","",1,0,0,[],""],["carrizo_salta-n0936-a-01",3,"Mi corazón es tan niño\nQue no hace más que llorar\nMientras más le digo ¡calla!\nMás sentimiento le dá.",3,1,0,44,"",0,4,"a",-1,0,-1,0,418,418,"936-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0937-01",3,"Mi corazón es un niño,\nQue no sabe lo que quiere,\nUna ilusión lo alimenta,\nY un capricho lo sostiene.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,418,418,"937","",0,"","","",2,0,0,[],""],["carrizo_salta-n0937-a-01",3,"Mi corazón es un niño,\nQue no sabe lo que quiere,\nUna caricia lo alienta,\nUna ilusión la sostiene.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,418,418,"937-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n0938-01",3,"Mi corazón no ha sentido\nNunca tan hondo dolor,\nComo el día en que tus labios,\nMe sentenciaron el no.",3,1,0,44,"",0,4,"o",-1,0,-1,0,418,418,"938","",0,"","","",1,0,0,[],""],["carrizo_salta-n0939-01",3,"Mi corazón traigo triste,\nTanto llorar mi destino,\nMi garganta traigo seca,\nCon el polvo del camino.",3,1,0,44,"",0,4,"io",199,0,-1,0,418,418,"939","",0,"","","",1,0,0,[],""],["carrizo_salta-n0940-01",3,"Mi firma no se la pongo,\nPorque no tiene valor;\nTodos me niegan favores\nNadie me ofrece su amor.",3,1,0,44,"",0,4,"o",72,0,-1,0,419,419,"940","",0,"","","",1,0,0,[],""],["carrizo_salta-n0941-01",3,"M'hi de mandar a mudar,\nDonde no haiga sol ni luna,\nM'hi largar a padecer,\nSin esperanza ninguna.",3,1,0,44,"",0,4,"ua",56,0,-1,0,419,419,"941","",0,"","","",1,0,0,[],""],["carrizo_salta-n0942-01",3,"Mis penas y mis fatigas,\nYa no se pueden juntar,\nUnas con otras se alcanzan,\nComo las olas del mar.",3,1,0,44,"",0,4,"a",21,0,-1,0,419,419,"942","",0,"","","",4,0,0,[],""],["carrizo_salta-n0943-01",3,"Miren como viene el agua,\nRemando contra la arena,\nAsí reman mis amores,\nEntre grillos y cadenas.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,419,419,"943","",0,"","","",1,0,0,[],""],["carrizo_salta-n0944-01",3,"¡Muerte desconsiderada!\nMe quitaste todo el bien,\nCargaste con quien quisiste,\nCargá conmigo también.",3,1,0,44,"",0,4,"e",242,0,-1,0,419,419,"944","",0,"","","",2,0,0,[],""],["carrizo_salta-n0945-01",3,"No estís triste corazón,\nNo tengas melancolía,\nSi otro te ha dado mal pago,\nTu lo darás otro día.",3,1,0,44,"",0,4,"ia",0,0,-1,0,419,419,"945","",0,"","","",1,0,0,[],""],["carrizo_salta-n0946-01",3,"No hay peor que los sufrimientos,\nPara que el hombre envejezca,\nAntes brillaba cual sol,\nHoy ni cosa que parezca.",3,1,0,44,"",0,4,"ea",346,0,-1,0,419,419,"946","",0,"","","",1,0,0,[],""],["carrizo_salta-n0947-01",3,"No llores, negra querida,\nQue aunque soy un gaucho pobre,\nSaldré a buscarme la vida,\nEn \"San Antonio los Cobres\".",3,1,0,44,"",0,4,"oe",-1,0,-1,0,419,419,"947","",0,"","","",1,0,0,[],""],["carrizo_salta-n0948-01",3,"No me casé por mi gusto,\nY menos por mi querer,\nMe casé por los terceros,\nQue me fueron a vender.",3,1,0,44,"",0,4,"e",20,0,-1,0,419,419,"948","",0,"","","",1,0,0,[],""],["carrizo_salta-n0949-01",3,"¿No miras aquel barquito\nQue está para naufragar?\nViene llorando sus penas,\nSobre las olas del mar.",3,1,0,44,"",0,4,"a",21,0,-1,0,419,419,"949","",0,"","","",1,0,0,[],""],["carrizo_salta-n0950-01",3,"No quiero aquí referir\nPara no avivar la herida,\n¿Por qué mi ingrata me olvida?\n¿Por qué me deja morir?",3,1,0,44,"",11,4,"i",157,0,-1,0,419,419,"950","",0,"","","",1,0,0,[],""],["carrizo_salta-n0951-01",3,"No sé por qué al corazón\nLo desconozco en el pecho,\nAlgún mal pago le han dado,\nO alguna traición le han hecho.",3,1,0,44,"",0,4,"eo",60,0,-1,0,419,419,"951","",0,"","","",1,0,0,[],""],["carrizo_salta-n0952-01",3,"No sé que costumbre tengo\nDe querer a la mujer,\nPero soy tan desgraciado,\nA mí nadie me ha i querer.",3,1,0,44,"",0,4,"e",20,0,-1,0,419,419,"952","",0,"","","",1,0,0,[],""],["carrizo_salta-n0953-01",3,"No sé si al año saldré,\n¡Sabe Dios si he de alcanzar!\nLes ha de causar tristeza,\nSólo al oirme mentar.",3,1,0,44,"",0,4,"a",21,0,-1,0,419,419,"953","",0,"","","",1,0,0,[],""],["carrizo_salta-n0954-01",3,"No tengo casa ni rancho,\nNo tengo ni una guarida,\nMe boto a vivir al monte,\nComo fiera perseguida.",3,1,0,44,"",0,4,"ia",37,0,-1,0,419,419,"954","",0,"","","",1,0,0,[],""],["carrizo_salta-n0955-01",3,"No tengo padre ni madre,\nNi hermanos a quien decir:\n—En esta pena me encuentro,\nAyudemén a sentir.",3,1,0,44,"",0,4,"i",157,0,-1,0,419,419,"955","",0,"","","",4,0,0,[],""],["carrizo_salta-n0956-01",3,"¡Nubes que andais por los altos,\nHasta mis ojos llegad!\nY humedecelos un poco,\nQue están secos de llorar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,420,420,"956","",0,"","","",1,0,0,[],""],["carrizo_salta-n0957-01",3,"¡Ojos de ardiente lucero\nQue me divulgan la suerte!\nHi pagar con mala dicha\nSi no llego a merecerte.",3,1,0,44,"",0,4,"ee",134,0,-1,0,420,420,"957","",0,"","","",1,0,0,[],""],["carrizo_salta-n0957-02",3,"¡Ojos que te vieron ir!\n¿Cuándo te verán volver?\nLlorarán mares de sangre\nDe ver el tiempo correr.",3,1,0,44,"",0,4,"e",20,0,-1,0,420,420,"957","",0,"","","",12,0,0,[],""],["carrizo_salta-n0959-01",3,"¡Pajarillo, buen amigo!\n¿Qué consejo me darís,\nPara volver a querer\nUna prenda que perdí?",3,1,0,44,"",0,4,"i",-1,0,-1,0,420,420,"959","",0,"","","",3,0,0,[],""],["carrizo_salta-n0960-01",3,"¡Pajarillo, buen amigo!\n¿Qué consuelo me darás?\nLa prenda que adoro tanto\n¿A mis brazos volverá?",3,1,0,44,"",0,4,"a",-1,0,-1,0,420,420,"960","",0,"","","",3,0,0,[],""],["carrizo_salta-n0961-01",3,"¡Paloma tierna y constante!\nQue habitas lujoso nido,\nDe tu desgraciado amante,\nEscucha el canto sentido.",3,1,0,44,"",1,4,"io",101,0,-1,0,420,420,"961","",0,"","","",1,0,0,[],""],["carrizo_salta-n0962-01",3,"¡Palo verde de orégano!\nVolverís tarde o temprano,\nAl rastrojito sembrao,\nY verís tu desengaño.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,420,420,"962","",0,"","","",1,0,0,[],""],["carrizo_salta-n0963-01",3,"Para alivio de mis penas,\nAquí me pongo a cantar,\nUna mujer me hizo un daño,\nQue nadie puede curar.",3,1,0,44,"",0,4,"a",21,0,-1,0,420,420,"963","",0,"","","",3,0,0,[],""],["carrizo_salta-n0964-01",3,"Para lo que dura un gusto,\nMás antes dura un pesar,\nEsas cuentas me hago yo\nSolito me dejo andar.",3,1,0,44,"",1,4,"a",21,0,-1,0,420,420,"964","",0,"","","",1,0,0,[],""],["carrizo_salta-n0965-01",3,"Para mí no hay alegría,\nPara mí no habrá piedad,\nSoy como el árbol maldito,\nQue arrastró la tempestad.",3,1,0,44,"",0,4,"a",16,0,-1,0,420,420,"965","",0,"","","",2,0,0,[],""],["carrizo_salta-n0966-01",3,"Paramí no hay tiempo alegre,\nSoy un deshojado lirio,\nYa mis hojas se cayeron,\nA los golpes de un martirio.",3,1,0,44,"",0,4,"io",360,0,-1,0,420,420,"966","",0,"","","",1,0,0,[],""],["carrizo_salta-n0967-01",3,"Para mí ya no hay consuelo,\nNi en la cama ni en el suelo,\nEl día que yo me muera,\n¿Quién será tu chalchalero?",3,1,0,44,"",0,4,"eo",-1,0,-1,0,420,420,"967","",0,"","","",1,0,0,[],""],["carrizo_salta-n0968-01",3,"Para mí ya no hay placer,\nYa mis glorias dieron fin.\nTan sólo reinan en mí:\nDesdichas y padecer.",3,1,0,44,"",5,4,"e",20,0,-1,0,420,420,"968","",0,"","","",1,0,0,[],""],["carrizo_salta-n0969-01",3,"¿Para qué me casaría\nSiendo guagua todavía?\nEl diablo me tentaría\nCon la cola batiría.",3,1,0,44,"",0,4,"ia",0,0,-1,0,420,420,"969","",0,"","","",2,0,0,[],""],["carrizo_salta-n0970-01",3,"¿Para qué me casaría\nSiendo moza todavía?\nAl lado de mi mamita.\n¿Por qué no me quedaría?",3,1,0,44,"",0,4,"ia",-1,0,-1,0,420,420,"970","",0,"","","",2,0,0,[],""],["carrizo_salta-n0971-01",3,"¿Para qué quiero la vida?\n¿Para qué quiero vivir?\nPara vivir padeciendo\nMás antes quiero morir.",3,1,0,44,"",0,4,"i",157,0,-1,0,420,420,"971","",0,"","","",6,0,0,[],""],["carrizo_salta-n0971-02",3,"¿Para qué quiero la vida,\nSi cada día la lloro?\nSi otro merece gozar,\nLa prenda que tanto adoro?",3,1,0,44,"",0,4,"oo",85,0,-1,0,421,421,"971","",0,"","","",6,0,0,[],""],["carrizo_salta-n0973-01",3,"Perdí mi querida prenda,\nPerdí todo mi caudal,\nUn desgraciao como yo\nNo tiene gusto cabal.",3,1,0,44,"",0,4,"a",1,0,-1,0,421,421,"973","",0,"","","",1,0,0,[],""],["carrizo_salta-n0974-01",3,"¡Pobrecita de mi abuela!\nLos consejos que me dió,\nNadie le agradece tanto,\nComo le agradezco yo.",3,1,0,44,"",0,4,"o",2,0,-1,0,421,421,"974","",0,"","","",1,0,0,[],""],["carrizo_salta-n0975-01",3,"¡Pobre de mí que nací!\nCon esta triste desgracia,\nLas mujeres no me quieren,\nY les digo: muchas gracias.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,421,421,"975","",0,"","","",1,0,0,[],""],["carrizo_salta-n0976-01",3,"¡Pobre mi madre, se ha muerto!\nYa la llevan a enterrar,\nEn una carreta i palo,\nPor ahí la verán pasar.",3,1,0,44,"",0,4,"a",21,0,-1,0,421,421,"976","",0,"","","",1,0,0,[],""],["carrizo_salta-n0977-01",3,"¡Pobre mi negra!\nLa han visto llorar,\nElla sabrá lo que sufre,\nCada uno siente su mal.",3,1,0,44,"",3,4,"a",-1,0,-1,0,421,421,"977","",0,"","","",3,0,0,[],""],["carrizo_salta-n0978-01",3,"Pobres nosotros los hombres,\nSiempre sin gusto cabal,\nCon el tiempo todos vamos,\nA la \"Guardia Nacional\".",3,1,0,44,"",0,4,"a",1,0,-1,0,421,421,"978","",0,"","","",1,0,0,[],""],["carrizo_salta-n0979-01",3,"Pongalén de cabecera\nUn letrero colorado,\nPa que digan los camperos:\n—Aquí ha muerto un desgraciado.",3,1,0,44,"",0,4,"ao",14,0,-1,0,421,421,"979","",0,"","","",1,0,0,[],""],["carrizo_salta-n0980-01",3,"Por el aire me anduviera,\nCantando mi elevación,\nQuizás asina tuviera,\nAlegría mi corazón.",3,1,0,44,"",1,4,"o",31,0,-1,0,421,421,"980","",0,"","","",1,0,0,[],""],["carrizo_salta-n0980-a-01",3,"Quisiera subir al aire\nCantar con elevación,\nPueda ser que así tuviera,\nAlivio mi corazón.",3,1,0,44,"",0,4,"o",31,0,-1,0,421,421,"980-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0981-01",3,"Por el amor de una ingrata,\nVoy quedando como espina,\nEstoy que me lleva el viento,\nEn la vuelta de una esquina.",3,1,0,44,"",0,4,"ia",11,0,-1,0,422,422,"981","",0,"","","",1,0,0,[],""],["carrizo_salta-n0982-01",3,"Por el camino el amor,\nHan privado que yo ande,\nQuieren que viva extraviado,\nY que vuele por los aires.",3,1,0,44,"",0,4,"ae",-1,0,-1,0,422,422,"982","",0,"","","",1,0,0,[],""],["carrizo_salta-n0983-01",3,"Por la falda de aquel cerro,\nPasan ráfagas de viento,\nAsí pasa mi vidita,\nEntre pena y sufrimiento.",3,1,0,44,"",0,4,"eo",94,0,-1,0,422,422,"983","",0,"","","",5,0,0,[],""],["carrizo_salta-n0984-01",3,"Por mi desdicha, bien mío,\nEn un retiro padezco,\nMe ocuparé en escribirte,\nQue el mirarte no merezco.",3,1,0,44,"",0,4,"eo",355,0,-1,0,422,422,"984","",0,"","","",1,0,0,[],""],["carrizo_salta-n0985-01",3,"Por mi madre soy vallista,\nPor mi padre soy chaqueño,\nY ahora vivo aullando,\nComo perrito sin dueño.",3,1,0,44,"",0,4,"eo",138,0,-1,0,422,422,"985","",0,"","","",1,0,0,[],""],["carrizo_salta-n0986-01",3,"Por no ponerme a llorar,\nVoy a ponerme a cantar,\nPorque si hago dejación,\nLas penas me han de matar.",3,1,0,44,"",0,4,"a",21,0,-1,0,422,422,"986","",0,"","","",1,0,0,[],""],["carrizo_salta-n0987-01",3,"Porque me ven forastero,\nMe quieren poner la marca,\n¡Cómo no compran y tienen\nQue a mi dueña le hago falta!",3,1,0,44,"",0,4,"aa",-1,0,-1,0,422,422,"987","",0,"","","",1,0,0,[],""],["carrizo_salta-n0988-01",3,"¿Por qué nacería al mundo\nPa qué la conocería?\nMás vale me hubiera muerto\nCon el mal de siete días.",3,1,0,44,"",0,4,"ia",-1,0,-1,0,422,422,"988","",0,"","","",1,0,0,[],""],["carrizo_salta-n0989-01",3,"¡Pu.. que soy desgraciao!\nQue soy infeliz,\nCiegos me han hallado faltas,\nMudos han hablao de mí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,422,422,"989","",0,"","","",1,0,0,[],""],["carrizo_salta-n0991-01",3,"¡Qué cosa fiera había sido\nCuando se arraiga el amor!\nIgual que la verdolaga\nCuando le cortan la flor.",3,1,0,44,"",0,4,"o",72,0,-1,0,422,422,"991","",0,"","","",1,0,0,[],""],["carrizo_salta-n0992-01",3,"¡Qué había i pensar de que yo\nDespués de verme querida,\nAhora por nuevos gustos,\nSea la más aborrecida!",3,1,0,44,"",0,4,"ia",37,0,-1,0,422,422,"992","",0,"","","",1,0,0,[],""],["carrizo_salta-n0992-a-01",3,"¡Quién ha i pensar de que yo\nDespués de ser tan querido!\nAgora por nuevos gustos\nSea el más aborrecido!",3,1,0,44,"",0,4,"io",101,0,-1,0,422,422,"992-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0993-01",3,"¿Qué hago con vida y sin gusto?\n¿Qué hago padeciendo tanto?\nVivir la vida sufriendo,\nEnvuelto en amargo llanto.",3,1,0,44,"",0,4,"ao",30,0,-1,0,422,422,"993","",0,"","","",1,0,0,[],""],["carrizo_salta-n0993-02",3,"Por tus quereres, serrana.\nMe boy quedando en la espina:\nEstoy, que me yeba 'r biento\nAr reborbé d' una esquina.",3,1,0,44,"",0,4,"ia",11,0,-1,0,422,422,"993","",0,"","","",2,0,0,[],""],["carrizo_salta-n0993-a-01",3,"¿Qué haré con vida y sin gusto?\n¿Qué haré padeciendo tanto?\nSólo pagándole al tiempo\nLágrimas de amargo llanto.",3,1,0,44,"",0,4,"ao",30,0,-1,0,423,423,"993-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n0994-01",3,"¿Qué importa que yo me acueste,\nEn rico lecho de flores,\nSi no me dejan dormir,\nTristes imaginaciones?",3,1,0,44,"",0,4,"oe",-1,0,-1,0,423,423,"994","",0,"","","",1,0,0,[],""],["carrizo_salta-n0995-01",3,"¿Qué les parece señores\nDe mi triste situación,\nTener la risa en los labios\nDestrozado el corazón?",3,1,0,44,"",0,4,"o",31,0,-1,0,423,423,"995","",0,"","","",3,0,0,[],""],["carrizo_salta-n0996-01",3,"¡Qué, negros son mis pesares!\n¡Qué negra es mi fiera suerte!\nSi negros son mis principios,\n¡Qué negra será mi muerte!",3,1,0,44,"",0,4,"ee",134,0,-1,0,423,423,"996","",0,"","","",1,0,0,[],""],["carrizo_salta-n0997-01",3,"¿Qué querís que haga, vida?\n¿Qué querís que haga?\nCuando más uno quiere,\nMás mal le pagan.",3,1,0,44,"",6,4,"aa",-1,0,-1,0,423,423,"997","",0,"","","",1,0,0,[],""],["carrizo_salta-n0998-01",3,"¡Qué tormento es el sufrir\nPor la ausencia de un querer!\nOjos que te vieron ir,\n¿Cuándo te verán volver?",3,1,0,44,"",1,4,"e",20,0,-1,0,423,423,"998","",0,"","","",1,0,0,[],""],["carrizo_salta-n0999-01",3,"¡Qué triste es la situación\nDel que ama sin libertad,\nSe expone a perder la vida\nPor amar a una deidad.",3,1,0,44,"",0,4,"a",16,0,-1,0,423,423,"999","",0,"","","",1,0,0,[],""],["carrizo_salta-n1000-01",3,"¡Qué triste es para una madre\nTener un hijo varón!\nCuando cumple sus veinte años,\nSe marcha a la conscrición.",3,1,0,44,"",0,4,"o",31,0,-1,0,423,423,"1000","",0,"","","",1,0,0,[],""],["carrizo_salta-n1001-01",3,"¿Qué voy a hacer mi vida?\n¿Qué voy a hacer?\nViviré solo y triste\nPor tu querer.",3,1,0,44,"",6,4,"e",20,0,-1,0,423,423,"1001","",0,"","","",1,0,0,[],""],["carrizo_salta-n1002-01",3,"Quisiera tener la ciencia,\nDe mis años anteriores,\nFlorecerían mis jardines,\nRenacerían mis amores.",3,1,0,44,"",0,4,"oe",5,0,-1,0,423,423,"1002","",0,"","","",1,0,0,[],""],["carrizo_salta-n1003-01",3,"Quisiera verme solito,\nComo el águila real,\nSin tener de qué quejarme,\nPorque me han pagado mal.",3,1,0,44,"",0,4,"a",1,0,-1,0,423,423,"1003","",0,"","","",1,0,0,[],""],["carrizo_salta-n1004-01",3,"Reza a los santos por mí,\nPor mi dolor tan crecido,\nA donde pongo mi amor,\nSe vuelve el amor suspiro.",3,1,0,44,"",0,4,"io",-1,0,-1,0,423,423,"1004","",0,"","","",1,0,0,[],""],["carrizo_salta-n1005-01",3,"Río abajo corre l'agua,\nYo me voy por las orillas,\nDando vueltas como piedra,\nCaminando de rodillas.",3,1,0,44,"",0,4,"ia",294,0,-1,0,423,423,"1005","",0,"","","",1,0,0,[],""],["carrizo_salta-n1006-01",3,"Río arriba van mis ansias,\nRío abajo mis pesares,\nConforme se muda el tiempo,\nSe mudan las voluntades.",3,1,0,44,"",0,4,"ae",-1,0,-1,0,423,423,"1006","",0,"","","",2,0,0,[],""],["carrizo_salta-n1006-a-01",3,"Río arriba van mis ansias,\nRío abajo mis pesares,\nCon las mudanzas del tiempo,\nSe cambian las voluntades",3,1,0,44,"",0,4,"ae",-1,0,-1,0,423,423,"1006-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n1007-01",3,"¡Río caudaloso!\nDejame pasar,\nSe ha muerto mi amante,\nLo quiero velar.",3,1,0,44,"",0,4,"a",21,0,-1,0,423,423,"1007","",0,"","","",3,0,0,[],""],["carrizo_salta-n1008-01",3,"¡Señora doña fulana!\nEncarguesé de este pobre,\nNo tiene padre ni madre,\nY en el bolsillo ni un cobre.",3,1,0,44,"",0,4,"oe",410,0,-1,0,424,424,"1008","",0,"","","",22,0,0,[],""],["carrizo_salta-n1009-01",3,"Si crees porque estoy cantando\nTengo el corazón alegre,\nYo soy como el pobre cisie,\nQue canta cuando se muere.",3,1,0,44,"",0,4,"ee",-1,0,-1,0,424,424,"1009","",0,"","","",1,0,0,[],""],["carrizo_salta-n1010-01",3,"Siempre está mi corazón,\nPensando si volverá,\nAlegrías en un pobre,\nSon anuncios de un pesar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,424,424,"1010","",0,"","","",1,0,0,[],""],["carrizo_salta-n1011-01",3,"Siento que el amor se muere,\nYo me quedaré sin él,\nEl tiempo todo lo acaba,\nSe acaba el amor también.",3,1,0,44,"",0,4,"e",-1,0,-1,0,424,424,"1011","",0,"","","",1,0,0,[],""],["carrizo_salta-n1012-01",3,"Si hallara un maestro de amor,\nQue me enseñara a querer,\nOlvidando lo preciso\nDejaría de padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,424,424,"1012","",0,"","","",1,0,0,[],""],["carrizo_salta-n1013-01",3,"Si porque me has visto viejo,\nDicen que no sé desiar,\n¿No saben que tengo hiel,\nY se puede reventar?",3,1,0,44,"",0,4,"a",21,0,-1,0,424,424,"1013","",0,"","","",1,0,0,[],""],["carrizo_salta-n1014-01",3,"Si ves las flores mojadas,\nNo le achaquis al rocío,\nSon lágrimas de mis ojos,\nQue por tu amor hi vertió.",3,1,0,44,"",5,4,"o",-1,0,-1,0,424,424,"1014","",0,"","","",1,0,0,[],""],["carrizo_salta-n1015-01",3,"Solita vivo en el mundo,\nSola hi de permanecer,\nHasta ahora no hi hallao,\nHombre fiel pa una mujer.",3,1,0,44,"",0,4,"e",20,0,-1,0,424,424,"1015","",0,"","","",1,0,0,[],""],["carrizo_salta-n1016-01",3,"Sólo me falta valor,\nPara sufrir tanta pena,\nCausa tu cariño ingrato,\nMe veo en esta cadena.",3,1,0,44,"",0,4,"ea",59,0,-1,0,424,424,"1016","",0,"","","",1,0,0,[],""],["carrizo_salta-n1017-01",3,"Soñé que mucho te amaba,\nY que era correspondido,\nY al despertar se cambió\nMi alegre sueño en suspiro.",3,1,0,44,"",0,4,"io",-1,0,-1,0,424,424,"1017","",0,"","","",1,0,0,[],""],["carrizo_salta-n1018-01",3,"Soy como el urutaú,\nQue canta mirando al cielo,\nPorque no puedo encontrar,\nLa prenda de mi consuelo.",3,1,0,44,"",0,4,"eo",10,0,-1,0,424,424,"1018","",0,"","","",1,0,0,[],""],["carrizo_salta-n1019-01",3,"Soy como la golondrina,\nSolita nací en verano\nAsí que hi de morir tarde\n¿Cómo no muero temprano?",3,1,0,44,"",0,4,"ao",81,0,-1,0,424,424,"1019","",0,"","","",1,0,0,[],""],["carrizo_salta-n1020-01",3,"Soy desgraciada en el mundo,\nHecha para padecer,\nSoy como la mala yerba,\nMe arrancan vuelvo a crecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,424,424,"1020","",0,"","","",1,0,0,[],""],["carrizo_salta-n1020-a-01",3,"Yo soy como el maldecido,\nBotadito a padecer,\nSoy como la mala yerba.\nLa arrancan, vuelve a nacer.",3,1,0,44,"",0,4,"e",20,0,-1,0,424,424,"1020-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1021-01",3,"Soy forastero del pago,\nNo tengo de quien valerme,\nCompadezcansé de mí\nHagan el bien de quererme.",3,1,0,44,"",0,4,"ee",245,0,-1,0,424,424,"1021","",0,"","","",2,0,0,[],""],["carrizo_salta-n1022-01",3,"Sol halconcito milano,\nQue me lo paso cantando.\nCuando no miro a la que amo,\nTriste lo paso llorando.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,424,424,"1022","",0,"","","",1,0,0,[],""],["carrizo_salta-n1023-01",3,"Soy hombre pobre y no puedo,\nDarle gusto a mi querer,\nEstoy hecho a andar errando,\nSufriendo a más no poder.",3,1,0,44,"",0,4,"e",20,0,-1,0,425,425,"1023","",0,"","","",1,0,0,[],""],["carrizo_salta-n1024-01",3,"Soy un árbol deshojado,\nEl mal tiempo me hizo mal,\nMe acuerdo de lo pasado,\nSólo me resta el llorar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,425,425,"1024","",0,"","","",1,0,0,[],""],["carrizo_salta-n1025-01",3,"Soy un pobre desgraciado,\nNo tengo donde alojarme,\nNi rancho donde apiñarme,\nNi mujer donde arrimarme.",3,1,0,44,"",0,4,"ae",35,0,-1,0,425,425,"1025","",0,"","","",1,0,0,[],""],["carrizo_salta-n1026-01",3,"Talvez porque yo he venido,\nVoy vuestra angustia a aumentar,\nYa su prenda lo ha dejado,\nEl inútil el llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,425,425,"1026","",0,"","","",1,0,0,[],""],["carrizo_salta-n1027-01",3,"También yo quisiera ser\nComo las piedras del río,\nTiradas en media playa\nSin sentir calor ni frío.",3,1,0,44,"",0,4,"io",3,0,-1,0,425,425,"1027","",0,"","","",1,0,0,[],""],["carrizo_salta-n1028-01",3,"Tan alta que está la nube,\nY el viento que la deshace,\nAsí se acaban los gustos\nQue en mi triste pecho nacen.",3,1,0,44,"",0,4,"ae",-1,0,-1,0,425,425,"1028","",0,"","","",1,0,0,[],""],["carrizo_salta-n1029-01",3,"Tan solamente hi nacido,\nPara que miren mis pasos,\nA mí solamente vienen,\nLas penas y los trabajos.",3,1,0,44,"",0,4,"ao",-1,0,-1,0,425,425,"1029","",0,"","","",1,0,0,[],""],["carrizo_salta-n1030-01",3,"Tengan compasión, señores,\nDe una pobre sin hogar,\nQue por falta de recursos\nHoy los viene a molestar.",3,1,0,44,"",0,4,"a",21,0,-1,0,425,425,"1030","",0,"","","",1,0,0,[],""],["carrizo_salta-n1031-01",3,"Tengo que hacer una cruz\nDe una madera pesada,\nPara cargar en mis hombros,\nTodas mis culpas pasadas.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,425,425,"1031","",0,"","","",1,0,0,[],""],["carrizo_salta-n1032-01",3,"Tengo una pena ¡qué pena!\nTengo un dolor ¡qué dolor!\nDe un amorcito tunante\nQue aprecia mi corazón.",3,1,0,44,"",0,4,"o",-1,0,-1,0,425,425,"1032","",0,"","","",3,0,0,[],""],["carrizo_salta-n1033-01",3,"Tengo un dolor en el alma,\nQue no me deja vivir,\nEl desdén de una morena,\nQue medio me hizo sentir.",3,1,0,44,"",0,4,"i",157,0,-1,0,425,425,"1033","",0,"","","",4,0,0,[],""],["carrizo_salta-n1034-01",3,"Te perdí, dulce contento,\nSólo conservo ¡Ay, de mí!\nUn triste recuerdo tuyo,\nPorque fino amante fui.",3,1,0,44,"",0,4,"i",23,0,-1,0,425,425,"1034","",0,"","","",1,0,0,[],""],["carrizo_salta-n1035-01",3,"¡Tiempo ayudame a sentir!\nDe lo mal que me han pagado,\n¡Ay, qué desgraciado he sido,\nPor otro me han olvidado!",3,1,0,44,"",0,4,"ao",14,0,-1,0,425,425,"1035","",0,"","","",1,0,0,[],""],["carrizo_salta-n1036-01",3,"Todas las dichas ajenas\nAmargan la vida mía,\nPor eso lloro mis penas,\nBajo una noche sombría.",3,1,0,44,"",1,4,"ia",0,0,-1,0,425,425,"1036","",0,"","","",1,0,0,[],""],["carrizo_salta-n1037-01",3,"Todito el mundo me anduve,\nEn busca de soledad,\nPasando dos mil trabajos,\nSin poderla hallar jamás.",3,1,0,44,"",0,4,"a",-1,0,-1,0,426,426,"1037","",0,"","","",1,0,0,[],""],["carrizo_salta-n1038-01",3,"Todo el mundo he recorrido,\nSiempre mi suerte al revés,\nDespués de padecer tanto,\nVuelvo a mi pago otra vez.",3,1,0,44,"",0,4,"e",150,0,-1,0,426,426,"1038","",0,"","","",1,0,0,[],""],["carrizo_salta-n1039-01",3,"Todo el que me oiga cantar,\nDirá que de alegre canto,\nNo hay rato que no suspire,\nEl día que no suelte el llanto.",3,1,0,44,"",0,4,"ao",30,0,-1,0,426,426,"1039","",0,"","","",1,0,0,[],""],["carrizo_salta-n1040-01",3,"Trabajo es hacerse viejo,\nA lo menos siendo pobre,\nEn medio la plata blanca,\nEscogiendo le dan cobre.",3,1,0,44,"",0,4,"oe",410,0,-1,0,426,426,"1040","",0,"","","",1,0,0,[],""],["carrizo_salta-n1041-01",3,"Triste penoso y confuso,\nTriste me pongo a llorar,\nRepitiendo en tiernos ayes,\n¡No hay mayor pena que amar!",3,1,0,44,"",0,4,"a",21,0,-1,0,426,426,"1041","",0,"","","",2,0,0,[],""],["carrizo_salta-n1042-01",3,"Triste me pilló la tarde,\nSin saber lo qu'hi de hacer,\nTriste está mi corazón,\n¡Algo me ha de suceder!",3,1,0,44,"",0,4,"e",20,0,-1,0,426,426,"1042","",0,"","","",1,0,0,[],""],["carrizo_salta-n1043-01",3,"Triste están mis ojos viendo,\nUn lastimoso pesar,\nSi con vivir los ofendo,\nAcabemén de matar.",3,1,0,44,"",1,4,"a",21,0,-1,0,426,426,"1043","",0,"","","",1,0,0,[],""],["carrizo_salta-n1044-01",3,"Tuve en mi pago en un tiempo,\nHijos, hacienda y mujer,\nMe fui de mala cabeza\nY nada encontré al volver.",3,1,0,44,"",0,4,"e",20,0,-1,0,426,426,"1044","",0,"","","",1,0,0,[],""],["carrizo_salta-n1045-01",3,"Una palomita amante,\nQue en el corazón tenía,\nHoy se quiere separar,\n¡Áy, qué desgracia la mía!",3,1,0,44,"",0,4,"ia",0,0,-1,0,426,426,"1045","",0,"","","",1,0,0,[],""],["carrizo_salta-n1046-01",3,"Una palomita,\nDe piquito de oro,\nCada que la veo,\nCada vez la lloro.",3,1,0,44,"",0,4,"oo",85,0,-1,0,426,426,"1046","",0,"","","",3,0,0,[],""],["carrizo_salta-n1047-01",3,"Una torre formada,\nDe amores tuve.\nVino un viento contrario\nNo hay bien que dure.",3,1,0,44,"",6,4,"ue",-1,0,-1,0,426,426,"1047","",0,"","","",1,0,0,[],""],["carrizo_salta-n1048-01",3,"Una traigo y dos envido,\nEn la mano traigo un as.\nSólo un amor conocí,\nNo quiero conocer más.",3,1,0,44,"",0,4,"a",51,0,-1,0,426,426,"1048","",0,"","","",1,0,0,[],""],["carrizo_salta-n1049-01",3,"Una vela se consume,\nA fuerza de tanto arder,\nAsí me consumo yo,\nCausa de un cruel padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,426,426,"1049","",0,"","","",7,0,0,[],""],["carrizo_salta-n1050-01",3,"Una vela se consume,\nArdiendo en el candelero,\nAsí me consumo yo,\nPor un amor verdadero.",3,1,0,44,"",0,4,"eo",38,0,-1,0,426,426,"1050","",0,"","","",7,0,0,[],""],["carrizo_salta-n1051-01",3,"Un día estando regando,\nCasi me morí de ser,\nPor causa de una rubita,\nQue me dejó a padecer.",3,1,0,44,"",0,4,"e",20,0,-1,0,426,426,"1051","",0,"","","",1,0,0,[],""],["carrizo_salta-n1052-01",3,"Un sentimiento me mata,\nUn amor me da la vida,\nCausa de mi suerte ingrata,\nNo cicatriza mi herida.",3,1,0,44,"",1,4,"ia",37,0,-1,0,426,426,"1052","",0,"","","",1,0,0,[],""],["carrizo_salta-n1053-01",3,"Un terreno que compré,\nCon cuidado lo labré,\nOtros están disfrutando,\nLo que yo lo cultivé.",3,1,0,44,"",0,4,"e",77,0,-1,0,427,427,"1053","",0,"","","",1,0,0,[],""],["carrizo_salta-n1054-01",3,"¡Válgame Dios de los cielos!\n¿Dónde estará mi consuelo?\nPorque me vean perdido\nNo crean qu' estoy por el suelo.",3,1,0,44,"",3,4,"eo",10,0,-1,0,427,427,"1054","",0,"","","",33,0,0,[],""],["carrizo_salta-n1055-01",3,"¡Válgame Dios de los cielos!\n¡Qué grande es la pena mía!\nEstoy metido en un pozo,\nY no encuentro la salida.",3,1,0,44,"",0,4,"ia",-1,0,-1,0,427,427,"1055","",0,"","","",33,0,0,[],""],["carrizo_salta-n1058-01",3,"Varios amigos yo tengo,\nPocos son de mi amistad.\nApenas yo me retiro,\nDe mí se ponen a hablar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,427,427,"1058","",0,"","","",1,0,0,[],""],["carrizo_salta-n1061-01",3,"Vengan doctores de ciencia,\nLos sabios vengan a mí,\nA ver cómo puede un hombre\nEstando muerto vivir.",3,1,0,44,"",0,4,"i",-1,0,-1,0,427,427,"1061","",0,"","","",1,0,0,[],""],["carrizo_salta-n1062-01",3,"Vení, vidita mía,\nVení lloremos,\nUna sola desgracia,\nLos dos tenemos.",3,1,0,44,"",6,4,"eo",127,0,-1,0,427,427,"1062","",0,"","","",2,0,0,[],""],["carrizo_salta-n1063-01",3,"¿Ves aquella pluma verde\nQue se bate por el aire?\nAsí se bate mi amor,\nCuando le hacen un desaire.",3,1,0,44,"",0,4,"ae",411,0,-1,0,427,427,"1063","",0,"","","",1,0,0,[],""],["carrizo_salta-n1064-01",3,"¡Vidita, vidita, sí!\n¡Vidita de mi tormento!\nVos te llevas el luto,\nYo el sentimiento.",3,1,0,44,"",3,4,"eo",94,0,-1,0,427,427,"1064","",0,"","","",1,0,0,[],""],["carrizo_salta-n1065-01",3,"Viene el mundo dando vueltas,\nY los demonios tentando,\nMis trabajos se acabaron,\nPero mis desdichas ?cuándo?",3,1,0,44,"",0,4,"ao",-1,0,-1,0,427,427,"1065","",0,"","","",1,0,0,[],""],["carrizo_salta-n1066-01",3,"¡Virgencita del Milagro!\nLlena i sublime bondad,\nNo dejes que pene mi alma,\nEntre tanta soledad.",3,1,0,44,"",0,4,"a",16,0,-1,0,427,427,"1066","",0,"","","",1,0,0,[],""],["carrizo_salta-n1068-01",3,"Voy a dejar de querer,\nEsto es mucho padecer,\nYa hi visto mi desengaño,\nNo hay mujer que pague bien.",3,1,0,44,"",0,4,"e",-1,0,-1,0,427,427,"1068","",0,"","","",2,0,0,[],""],["carrizo_salta-n1074-a-01",3,"Ya me llevan para arriba,\n¿Qué destino llevaré?\nLos caminos son tan largos\n¡Quién sabe si volveré!",3,1,0,44,"",0,4,"e",77,0,-1,0,428,428,"1074-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1074-b-01",3,"Ya me voy pa lao de abajo\n¿Qué destino llevaré?\nCaminos largos pasando,\n¡Sabe Dios si volveré!",3,1,0,44,"",0,4,"e",77,0,-1,0,428,428,"1074-b","",0,"","","",3,0,0,[],""],["carrizo_salta-n1075-01",3,"Ya me voy a confundir\nCon la razón suficiente,\nPorque no hay pecho valiente,\nCuando penetra un sentir.",3,1,0,44,"",11,4,"i",157,0,-1,0,428,428,"1075","",0,"","","",1,0,0,[],""],["carrizo_salta-n1076-01",3,"Ya no siento la agonía,\nNi morir en un tormento,\nLo que siento es que otro goce,\nLo que yo gocé en un tiempo.",3,1,0,44,"",0,4,"eo",-1,0,-1,0,428,428,"1076","",0,"","","",1,0,0,[],""],["carrizo_salta-n1077-01",3,"Ya no soy quien antes fui,\nNi sombra lo que solía,\nAntes era plata en riales,\nAhora chafalonía.",3,1,0,44,"",0,4,"ia",0,0,-1,0,428,428,"1077","",0,"","","",1,0,0,[],""],["carrizo_salta-n1078-01",3,"Ya no tengo resistencia,\nEn mi desesperación,\n¿No oyes mis tristes gemidos\nNacidos del corazón?",3,1,0,44,"",0,4,"o",31,0,-1,0,428,428,"1078","",0,"","","",1,0,0,[],""],["carrizo_salta-n1079-01",3,"Ya no vivo en aquel sitio\nA donde me conoció,\nYa vivo en la travesía,\nDonde me desengañó.",3,1,0,44,"",0,4,"o",2,0,-1,0,428,428,"1079","",0,"","","",1,0,0,[],""],["carrizo_salta-n1080-01",3,"Ya que me pongo a cantar\nVoy a cantar mis pesares,\nCantaré la vida triste\nQue paso en estos lugares.",3,1,0,44,"",0,4,"ae",164,0,-1,0,428,428,"1080","",0,"","","",1,0,0,[],""],["carrizo_salta-n1081-01",3,"Ya se acabó mi esperanza,\nCon gran desesperación,\nY me gusta un desengaño\nCuando llega la ocasión.",3,1,0,44,"",0,4,"o",31,0,-1,0,428,428,"1081","",0,"","","",2,0,0,[],""],["carrizo_salta-n1082-01",3,"Ya se me quebró el espejo,\nEn que me sabía mirar,\nNi las tapas me han quedado,\nPara mi mayor pesar.",3,1,0,44,"",0,4,"a",21,0,-1,0,428,428,"1082","",0,"","","",1,0,0,[],""],["carrizo_salta-n1083-01",3,"Ya se quedarán a gusto,\nLos vecinos adulones,\nDe ver que se han separado,\nDos unidos corazones.",3,1,0,44,"",0,4,"oe",34,0,-1,0,429,429,"1083","",0,"","","",1,0,0,[],""],["carrizo_salta-n1084-01",3,"Ya se va ese aborrecido,\nYa no volverá jamás,\nYa no cruzará sus puertas,\nNi las ofenderá más.",3,1,0,44,"",0,4,"a",51,0,-1,0,429,429,"1084","",0,"","","",1,0,0,[],""],["carrizo_salta-n1085-01",3,"Ya ti hi dicho corazón,\nPrimera y segunda vez,\nQue no llames a esas puertas,\nQue no te han de responder.",3,1,0,44,"",0,4,"e",-1,0,-1,0,429,429,"1085","",0,"","","",1,0,0,[],""],["carrizo_salta-n1086-01",3,"Ya viene el sol saliendo,\nDicen las flores;\nYa viene quien nos quita,\nNuestros colores.",3,1,0,44,"",6,4,"oe",5,0,-1,0,429,429,"1086","",0,"","","",1,0,0,[],""],["carrizo_salta-n1087-01",3,"Yo fui un árbol muy hermoso,\nQue daba fruto y virtudes,\nAhora ruedo por el mundo,\nCausa las ingratitudes.",3,1,0,44,"",0,4,"ue",412,0,-1,0,429,429,"1087","",0,"","","",1,0,0,[],""],["carrizo_salta-n1088-01",3,"Yo la quise y la amé tanto,\nQue por ella soy perdido.\nNo hay cosa que más aflija\nQue querer sin ser querido.",3,1,0,44,"",0,4,"io",101,0,-1,0,429,429,"1088","",0,"","","",1,0,0,[],""],["carrizo_salta-n1089-01",3,"Yo me acuerdo de mis tiempos,\nCuando sabía retozar,\nAhora que ya soy viejo,\nYa no puedo ni trotar.",3,1,0,44,"",0,4,"a",21,0,-1,0,429,429,"1089","",0,"","","",1,0,0,[],""],["carrizo_salta-n1090-01",3,"Ya me acuerdo, en otros tiempos,\nSolía ser medio dichoso,\nNo quisiera recordar,\nMis tiempos cuando era mozo.",3,1,0,44,"",0,4,"oo",156,0,-1,0,429,429,"1090","",0,"","","",1,0,0,[],""],["carrizo_salta-n1091-01",3,"Yo me voy para Lesser\nPa que me quite la ser,\nCuando yo me descomponga\n¿Quién me podrá componer?",3,1,0,44,"",0,4,"e",20,0,-1,0,429,429,"1091","",0,"","","",1,0,0,[],""],["carrizo_salta-n1092-01",3,"Yo nací muy desgraciada,\nMis males no tienen fin,\nQue soy como un potrerillo\nTodo un mal se encierra en mí.",3,1,0,44,"",0,4,"i",-1,0,-1,0,429,429,"1092","",0,"","","",1,0,0,[],""],["carrizo_salta-n1093-01",3,"Yo no le temo a la muerte,\nMenos a la sepultura,\nYo le temo a la vejez,\nPorque es mal sin compostura.",3,1,0,44,"",0,4,"ua",17,0,-1,0,429,429,"1093","",0,"","","",12,0,0,[],""],["carrizo_salta-n1094-01",3,"Yo no publico mis males,\nPorque si los publicara,\nSi alguna pared me oyera,\nDe sentimiento llorara.",3,1,0,44,"",0,4,"aa",57,0,-1,0,429,429,"1094","",0,"","","",1,0,0,[],""],["carrizo_salta-n1095-01",3,"Yo no quiero que quieras,\nTampoco quiero querer,\nMás antes que me muriera,\nPara dejar de jo...",3,1,0,44,"",5,4,"o",-1,0,-1,0,429,429,"1095","",0,"","","",1,0,0,[],""],["carrizo_salta-n1096-01",3,"Yo no sé cómo ni cuando,\nNi se cómo he de vivir,\nLa prenda que ando mirando,\nNo me puede ni sentir.",3,1,0,44,"",1,4,"i",157,0,-1,0,429,429,"1096","",0,"","","",1,0,0,[],""],["carrizo_salta-n1097-01",3,"Yo no sé porque este mundo,\nMe aborrece de mil modos;\nCuando yo les doy la mano,\nYa quieren, tomar el codo.",3,1,0,44,"",0,4,"oo",-1,0,-1,0,429,429,"1097","",0,"","","",1,0,0,[],""],["carrizo_salta-n1098-01",3,"Yo no siento ser cautivo,\nEn esta cautividad,\nMas le siento a mi vidita\nQue ya me quiere olvidar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,429,429,"1098","",0,"","","",1,0,0,[],""],["carrizo_salta-n1099-01",3,"Yo no soy quien antes era,\nNi menos quien sabía ser,\nSoy un cuadro de desdichas,\nArrimado a una pared.",3,1,0,44,"",0,4,"e",-1,0,-1,0,430,430,"1099","",0,"","","",2,0,0,[],""],["carrizo_salta-n1100-01",3,"Yo no soy rosa encarnada,\nNi soy clavel encendido,\n¿Qué cariño me tendrás\nSi recién te he conocido?",3,1,0,44,"",0,4,"io",101,0,-1,0,430,430,"1100","",0,"","","",1,0,0,[],""],["carrizo_salta-n1101-01",3,"Yo no tengo quien me llore,\nMás que las tristes campanas,\nMe velarán esta noche,\nMe sepultarán mañana.",3,1,0,44,"",0,4,"aa",-1,0,-1,0,430,430,"1101","",0,"","","",1,0,0,[],""],["carrizo_salta-n1102-01",3,"Yo quisiera verme muerto,\nAntes de verme rendido,\nAsí no ofenderé a nadie,\nDe todos seré querido.",3,1,0,44,"",0,4,"io",101,0,-1,0,430,430,"1102","",0,"","","",1,0,0,[],""],["carrizo_salta-n1103-01",3,"Yo sabía vivir engreído\nPensando que era querido,\nAhora recuerdo y me hallo,\nEn el libro del olvido.",3,1,0,44,"",3,4,"io",101,0,-1,0,430,430,"1103","",0,"","","",1,0,0,[],""],["carrizo_salta-n1104-01",3,"¿Yo solito habré nacido,\nDe todos aborrecido?\n¿Algún día hi de cambiar\nDe aborrecido en querido?",3,1,0,44,"",0,4,"io",101,0,-1,0,430,430,"1104","",0,"","","",1,0,0,[],""],["carrizo_salta-n1105-01",3,"Yo soy amigo de todos,\nNadie es amigo de mí,\nDe todo varón que existe,\nYo soy el más infeliz.",3,1,0,44,"",0,4,"i",-1,0,-1,0,430,430,"1105","",0,"","","",1,0,0,[],""],["carrizo_salta-n1106-01",3,"Yo soy aquel caminante,\nQue busca felicidad,\nLa esperanza me acompaña,\nPero en vano la hi buscar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,430,430,"1106","",0,"","","",1,0,0,[],""],["carrizo_salta-n1107-01",3,"Yo soy como corderita,\nQue vive con lechecita,\nPor eso todos me dicen:\n¡Cómo vive, pobrecita!",3,1,0,44,"",0,4,"ia",50,0,-1,0,430,430,"1107","",0,"","","",1,0,0,[],""],["carrizo_salta-n1108-01",3,"Yo soy como el buey tropero,\nQue camina noche y día,\nDonde me pille el destino,\nHa i quedar la güesería.",3,1,0,44,"",0,4,"ia",0,0,-1,0,430,430,"1108","",0,"","","",1,0,0,[],""],["carrizo_salta-n1109-01",3,"Yo soy como el dedo malo,\nDonde trompiezo hago duelo,\n¡Caántas no estarán diciendo\nMuera el malo, quede el bueno!",3,1,0,44,"",0,4,"eo",-1,0,-1,0,430,430,"1109","",0,"","","",1,0,0,[],""],["carrizo_salta-n1110-01",3,"Yo soy como el mes de Agosto,\nDe ventarrones corrido,\nEn el pago de AAngastaco\nSoy siempre el aborrecido.",3,1,0,44,"",0,4,"io",101,0,-1,0,430,430,"1110","",0,"","","",2,0,0,[],""],["carrizo_salta-n1111-01",3,"Yo soy como la mojarra,\nQue vive en lo más profundo,\nQué me han de decir de penas\n¡Cuánto yo hi recorrió el mundo!",3,1,0,44,"",0,4,"uo",179,0,-1,0,431,431,"1111","",0,"","","",1,0,0,[],""],["carrizo_salta-n1112-01",3,"Yo soy como la paloma,\nCorrida por el halcón,\nTengo una herida en el alma,\nY no encuentro curación.",3,1,0,44,"",0,4,"o",31,0,-1,0,431,431,"1112","",0,"","","",3,0,0,[],""],["carrizo_salta-n1113-01",3,"Yo soy como la paloma,\nPaloma del palomar,\nTriste lloro mi destino,\nEn una cautividad.",3,1,0,44,"",0,4,"a",-1,0,-1,0,431,431,"1113","",0,"","","",3,0,0,[],""],["carrizo_salta-n1114-01",3,"Yo soy el ave más útil,\nY el viento me ha de llevar,\nBuscaré una rama seca,\nPara ponerme a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,431,431,"1114","",0,"","","",1,0,0,[],""],["carrizo_salta-n1114-02",3,"Yo soy la paja más alta,\nEl viento me ha de llevar,\nBusco la rama más seca,\nPara ausentarme a llorar.",3,1,0,44,"",0,4,"a",21,0,-1,0,431,431,"1114","",0,"","","",1,0,0,[],""],["carrizo_salta-n1115-01",3,"Yo soy el que a solas lloro,\nY en conversación me río,\nYo soy el que sufre y siente,\nGrandes penas y martirios.",3,1,0,44,"",0,4,"io",-1,0,-1,0,431,431,"1115","",0,"","","",1,0,0,[],""],["carrizo_salta-n1115-02",3,"Yo canto porque cantando\ndivierto los males míos;\ncuando estoy a solas lloro,\ny en conversación me río.",3,1,0,44,"",0,4,"io",-1,0,-1,0,431,431,"1115","",0,"machado_venezuela","","",2,0,0,[],""],["carrizo_salta-n1116-01",3,"Yo soy esa laya i mozo,\nCuyos servicios no valen.\n¿De qué vale servir bien\nSi con desprecios le salen?",3,1,0,44,"",0,4,"ae",227,0,-1,0,432,432,"1116","",0,"","","",2,0,0,[],""],["carrizo_salta-n1117-01",3,"Yo soy esa laya i mozo,\nMozo pobre rodador,\nSin un rancho pa dormir,\nNi un peso en el tirador.",3,1,0,44,"",0,4,"o",72,0,-1,0,432,432,"1117","",0,"","","",2,0,0,[],""],["carrizo_salta-n1118-01",3,"Yo soy ese caminante,\nQue busca felicidad,\nNoche i día voy tras ella,\nY en vano la hi de buscar.",3,1,0,44,"",0,4,"a",-1,0,-1,0,432,432,"1118","",0,"","","",1,0,0,[],""],["carrizo_salta-n1119-01",3,"Yo soy nacido en el campo,\nEn medio de una majada,\nPor eso todos me dicen:\n¿De ande salís desgraciada?",3,1,0,44,"",0,4,"aa",49,0,-1,0,432,432,"1119","",0,"","","",3,0,0,[],""],["carrizo_salta-n1120-01",3,"Yo también diré lo mismo\nQue dijo un jasimaneño;\n—La prenda que yo quería\nYa había tenido otro dueño.",3,1,0,44,"",0,4,"eo",138,0,-1,0,432,432,"1120","",0,"","","",3,0,0,[],""],["carrizo_salta-n1121-01",3,"Yo también sembré una chacra,\nY la regué con firmeza,\nY cuando fí a cosecharla,\nEncontré sólo malezas.",3,1,0,44,"",0,4,"ea",-1,0,-1,0,432,432,"1121","",0,"","","",1,0,0,[],""],["carrizo_salta-n1122-01",3,"Yo también supe gozar,\nDe mi fortuna la gloria,\nPero nunca hice memoria,\nQue se podría acabar.",3,1,0,44,"",11,4,"a",21,0,-1,0,432,432,"1122","",0,"","","",1,0,0,[],""],["carrizo_salta-n1123-01",3,"Yo vide pasar el agua,\nEntre la piedra y la arena,\nAsí pasan mis amores,\nEntre la dicha y la pena.",3,1,0,44,"",0,4,"ea",59,0,-1,0,432,432,"1123","",0,"","","",1,0,0,[],""],["carrizo_salta-n1124-01",3,"Yo vivo de un imposible,\nMantenida de un quizás,\nEsperando cuando ha i ser\n¡Quién sabe lo que será!",3,1,0,44,"",0,4,"a",-1,0,-1,0,432,432,"1124","",0,"","","",1,0,0,[],""],["carrizo_salta-n1125-01",3,"A este pobre corazón,\nNo le pagues mal su amor,\nPorque se ha de retirar,\nCalladito y sin dolor.",3,1,0,45,"",0,4,"o",72,0,-1,0,434,434,"1125","",0,"","","",3,0,0,[],""],["carrizo_salta-n1126-01",3,"Agua que busca su centro,\nNo le han de poner represa,\nLos desprecios que Ud. me hace,\nLos recibo con fineza.",3,1,0,45,"",0,4,"ea",108,0,-1,0,434,434,"1126","",0,"","","",2,0,0,[],""],["carrizo_salta-n1128-01",3,"¡Ahijuna putita!\nSombrero soroche,\n¿Dónde me querís llevar\nA hacerme la de esta noche?",3,1,0,45,"",0,4,"oe",337,0,-1,0,434,434,"1128","",0,"","","",1,0,0,[],""],["carrizo_salta-n1129-01",3,"Al amor de esta serrana,\nYo no lo puedo entender,\nHay días que quiere bien,\nOtros no me puede ver.",3,1,0,45,"",0,4,"e",-1,0,-1,0,434,434,"1129","",0,"","","",1,0,0,[],""],["carrizo_salta-n1130-01",3,"A la puerta de tu casa,\nHelándome me tenibas,\nDecí: ¿Por qué no salibas\nEn jachaques del meyando?",3,1,0,45,"",5,4,"ao",-1,0,-1,0,434,434,"1130","",0,"","","",2,0,0,[],""],["carrizo_salta-n1131-01",3,"Al buen amigo causante,\nDe nuestra separación,\nLe estoy muy agradecido,\nPorque fué mi salvación.",3,1,0,45,"",0,4,"o",31,0,-1,0,434,434,"1131","",0,"","","",1,0,0,[],""],["carrizo_salta-n1132-01",3,"Al cariño que te dí,\nNo lo has sabido apreciar.\nPues mi amor no se merece\nQue tu le pagues tan mal.",3,1,0,45,"",0,4,"a",-1,0,-1,0,434,434,"1132","",0,"","","",1,0,0,[],""],["carrizo_salta-n1133-01",3,"¿Al corazón me lo pides?\n—Ahí lo tienes, ahí lo tienes,\nPero no le andis pagando,\nCon desdenes, con desdenes.",3,1,0,45,"",3,4,"ee",120,0,-1,0,434,434,"1133","",0,"","","",1,0,0,[],""],["carrizo_salta-n1134-01",3,"Algún día tu caerás,\nEn aquel error que hiciste,\nCuando quieras no podrás,\nRecobrar lo que perdiste.",3,1,0,45,"",1,4,"ie",153,0,-1,0,434,434,"1134","",0,"","","",5,0,0,[],""],["carrizo_salta-n1135-01",3,"¿Algún otro te ha ofrecido\nOro y plata a cantidades?\n¿Te han ofrecido grandezas?\nPor mí no pierdas caudales.",3,1,0,45,"",0,4,"ae",-1,0,-1,0,434,434,"1135","",0,"","","",1,0,0,[],""],["carrizo_salta-n1136-01",3,"Al monte se va por leña,\nPero por varilla no,\nSi usted lo dice por mí,\nEso no lo admito yo.",3,1,0,45,"",0,4,"o",2,0,-1,0,434,434,"1136","",0,"","","",1,0,0,[],""],["carrizo_salta-n1137-01",3,"A los hombres no les creo\nAun cuando jurar los viera,\nPorque los hombres arriesgan,\nPor lo que pu.' pudieran.",3,1,0,45,"",0,4,"ea",-1,0,-1,0,435,435,"1137","",0,"","","",1,0,0,[],""],["carrizo_salta-n1138-01",3,"A los ojos de mi cara,\nLos tengo que castigar,\nPorque miran con cariño,\nA quien mal pago les da.",3,1,0,45,"",0,4,"a",-1,0,-1,0,435,435,"1138","",0,"","","",1,0,0,[],""],["carrizo_salta-n1139-01",3,"Allá va mi rabonita,\nPongamelén la colita,\nPor buscar contentamiento,\nEs bellaca la maldita.",3,1,0,45,"",0,4,"ia",50,0,-1,0,435,435,"1139","",0,"","","",2,0,0,[],""],["carrizo_salta-n1140-01",3,"A mí la vieja me quiere,\nPorque soy muy querendón,\nSólo su hija no me deja,\n¡Malhaya su corazón!",3,1,0,45,"",0,4,"o",31,0,-1,0,435,435,"1140","",0,"","","",1,0,0,[],""],["carrizo_salta-n1141-01",3,"Amor fingido, fingido,\nQue andas fingiendo dolor,\nYa me has cambiado con otro,\nYa no me tienes amor.",3,1,0,45,"",0,4,"o",72,0,-1,0,435,435,"1141","",0,"","","",1,0,0,[],""],["carrizo_salta-n1142-01",3,"Amorosa, sin cariño,\nIngrata de voluntad,\nHabías tenido otro dueño\n¿Ajeno o cuyo será?",3,1,0,45,"",0,4,"a",-1,0,-1,0,435,435,"1142","",0,"","","",1,0,0,[],""],["carrizo_salta-n1143-01",3,"Amor que viene trocado,\nNo lo quiero ni un instante,\nNo quiero que reine en mí,\nNo siendo firme y constante.",3,1,0,45,"",0,4,"ae",47,0,-1,0,435,435,"1143","",0,"","","",1,0,0,[],""],["carrizo_salta-n1144-01",3,"Anda diciendo tu madre,\nQue una reina te mereces,\nY yo como no soy reina,\nTe aconsejo que me dejes.",3,1,0,45,"",0,4,"ee",-1,0,-1,0,435,435,"1144","",0,"","","",23,0,0,[],""],["carrizo_salta-n1145-01",3,"Anda diciendo tu mama\nQue vos valís más que yo,\n¿No sabe esa vieja tonta,\nQue una cabra te crió?",3,1,0,45,"",0,4,"o",2,0,-1,0,435,435,"1145","",0,"","","",1,0,0,[],""],["carrizo_salta-n1146-01",3,"¡Anda, ingrata, que has de hallar,\nOtro que te pague mal,\nY cuando quieras volver,\nA mí no me has de encontrar.",3,1,0,45,"",0,4,"a",-1,0,-1,0,435,435,"1146","",0,"","","",1,0,0,[],""],["carrizo_salta-n1147-01",3,"A ninguna en este mundo,\nHe querido más que a tí,\nY que no me correspondas,\nEse es mi mayor sentir.",3,1,0,45,"",0,4,"i",-1,0,-1,0,435,435,"1147","",0,"","","",3,0,0,[],""],["carrizo_salta-n1148-01",3,"Antes, cuando mozo hi sío,\nNunca quise criatura,\nVean que diabla es la moza,\nYa ha puesto mi amor en duda.",3,1,0,45,"",0,4,"ua",-1,0,-1,0,435,435,"1148","",0,"","","",1,0,0,[],""],["carrizo_salta-n1149-01",3,"¡Aprende, ingrata, a querer,\nY a tener correspondencia!\nEn persona como tú\nNo es disculpa la inocencia.",3,1,0,45,"",0,4,"ea",46,0,-1,0,435,435,"1149","",0,"","","",1,0,0,[],""],["carrizo_salta-n1150-01",3,"Aquel momento no olvido,\nRecordándolo me mata,\nCuando yo te había pedido,\nQue no me fueras ingrata.",3,1,0,45,"",1,4,"aa",74,0,-1,0,435,435,"1150","",0,"","","",1,0,0,[],""],["carrizo_salta-n1151-01",3,"A un pobre di una limosna,\nY hasta lloró al recibirla.\nA tí que te he dado el alma,\nNi tan siquiera me miras.",3,1,0,45,"",0,4,"ia",-1,0,-1,0,436,436,"1151","",0,"","","",1,0,0,[],""],["carrizo_salta-n1152-01",3,"Aunque te subas al cielo,\nY te encuentres en las nubes,\nTe tengo que conocer,\nPor el amor que te tuve.",3,1,0,45,"",0,4,"ue",-1,0,-1,0,436,436,"1152","",0,"","","",8,0,0,[],""],["carrizo_salta-n1152-02",3,"Aunque tu no me quieras,\nTengo el consuelo,\nDe saber que tu sabes,\nQue yo te quiero.",3,1,0,45,"",6,4,"eo",-1,0,-1,0,436,436,"1152","",0,"rm_t2, palau_cantares, fernan_caballero","","",7,0,0,[],""],["carrizo_salta-n1154-01",3,"A vos te ha i pesar\nNo haberme querido,\nSi otro, remedio no encuentras\nLlorarás lo que has perdido.",3,1,0,45,"",0,4,"io",101,0,-1,0,436,436,"1154","",0,"","","",1,0,0,[],""],["carrizo_salta-n1155-01",3,"Ayer canté en Ceibalito,\nHoy canto medio La Pampa,\nLo que te pido es negrita,\nQue no me paguís con trampa.",3,1,0,45,"",0,4,"aa",413,0,-1,0,436,436,"1155","",0,"","","",1,0,0,[],""],["carrizo_salta-n1156-01",3,"Ahijuna puta mujer\nTan ingrata como sos,\nSi no me robas el alma\nMe robas el corazón.",3,1,0,45,"",0,4,"o",-1,0,-1,0,436,436,"1156","",0,"","","",1,0,0,[],""],["carrizo_salta-n1157-01",3,"¡Ahijuna puta vidita!\nDe mí te fuistes huyendo,\nSin que te deje te fuistes,\nPor eso vivís sintiendo.",3,1,0,45,"",0,4,"eo",52,0,-1,0,436,436,"1157","",0,"","","",4,0,0,[],""],["carrizo_salta-n1157-a-01",3,"Solita viví en tu ausencia,\nDe mi amor, fuistes huyendo,\nPor tu gusto me has dejado,\nTenis que vivir sintiendo.",3,1,0,45,"",0,4,"eo",52,0,-1,0,436,436,"1157-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1158-01",3,"¡Ahijuna puta, vidita!\nDígale cuando la vea,\nQue viva con mucha cuenta,\nNo la tape la batea.",3,1,0,45,"",0,4,"ea",-1,0,-1,0,436,436,"1158","",0,"","","",4,0,0,[],""],["carrizo_salta-n1159-01",3,"¡Ay, mi querida fulana\nAtienda y ponga atención!\nSiquiera por esta vez\nMiremé con compasión.",3,1,0,45,"",0,4,"o",31,0,-1,0,436,436,"1159","",0,"","","",9,0,0,[],""],["carrizo_salta-n1160-01",3,"¡Ay, mi querida fulana!\n¿Por qué me echa por los suelos?\nPueda ser que con el tiempo\nYo le sirva de consuelo.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,436,436,"1160","",0,"","","",9,0,0,[],""],["carrizo_salta-n1161-01",3,"¡Ay, sí, que lo has hecho bien!\nEn ese particular,\nLa culpa no tiene el loro,\nSino quien le enseñó a hablar.",3,1,0,45,"",0,4,"a",21,0,-1,0,436,436,"1161","",0,"","","",1,0,0,[],""],["carrizo_salta-n1162-01",3,"¡Ay, vidita de mi vida!\nNo hagas sufrir a tu amante,\nQue te prometió jurando,\nUn amor firme y constante.",3,1,0,45,"",0,4,"ae",47,0,-1,0,436,436,"1162","",0,"","","",1,0,0,[],""],["carrizo_salta-n1163-01",3,"Bajá la vista y mirame,\nA ver si me conocís,\nPedí licencia a tu dueño,\nCompadecete de mí.",3,1,0,45,"",0,4,"i",-1,0,-1,0,436,436,"1163","",0,"","","",1,0,0,[],""],["carrizo_salta-n1164-01",3,"Bonito te vas portando,\nAsí me has de aquerenciar,\n¿En qué libro has aprendido\nA olvidar sin avisar?",3,1,0,45,"",0,4,"a",21,0,-1,0,436,436,"1164","",0,"","","",1,0,0,[],""],["carrizo_salta-n1165-01",3,"¡Caballero de fulano!\nAmor tuve, amor te dí,\nYo no te ofrecí grandezas,\nNo me eches la culpa a mí.",3,1,0,45,"",0,4,"i",23,0,-1,0,436,436,"1165","",0,"","","",36,0,0,[],""],["carrizo_salta-n1166-01",3,"Cada vez que te dije,\nQue me quisieras,\nTe subías más alto,\nQue las estrellas.",3,1,0,45,"",6,4,"ea",-1,0,-1,0,437,437,"1166","",0,"","","",1,0,0,[],""],["carrizo_salta-n1167-01",3,"Causa de tu falsedad,\nVidita, vivo quejoso,\nHas escogido otro amante,\nCon él serás más dichoso.",3,1,0,45,"",0,4,"oo",160,0,-1,0,437,437,"1167","",0,"","","",1,0,0,[],""],["carrizo_salta-n1168-01",3,"Ciego del entendimiento,\nCiego del cuarto sentido,\nVivo llorando mi suerte,\nPorque tu amor he perdido.",3,1,0,45,"",0,4,"io",101,0,-1,0,437,437,"1168","",0,"","","",1,0,0,[],""],["carrizo_salta-n1169-01",3,"¡Cogollito de algarrobo!\nYo te vide florecer,\nY ahora que están florido\nQuieres verme padecer.",3,1,0,45,"",0,4,"e",20,0,-1,0,437,437,"1169","",0,"","","",1,0,0,[],""],["carrizo_salta-n1170-01",3,"Como corzuela del campo,\nTe has dejado cautivar,\nVolvé, vidita, a tu rancho\nConmigo no has de llorar.",3,1,0,45,"",0,4,"a",21,0,-1,0,437,437,"1170","",0,"","","",1,0,0,[],""],["carrizo_salta-n1171-01",3,"¡Cómo dices que me quieres!\n¡Cómo dices que me adoras!\nEstando a corta distancia\nNo me mandas ni memorias.",3,1,0,45,"",0,4,"oa",-1,0,-1,0,437,437,"1171","",0,"","","",1,0,0,[],""],["carrizo_salta-n1172-01",3,"¿Cómo me sabía decir\nSi se iba me llevaría?\nSi hoy día se va y me deja\nLe ha de pesar algún día.",3,1,0,45,"",0,4,"ia",0,0,-1,0,437,437,"1172","",0,"","","",1,0,0,[],""],["carrizo_salta-n1173-01",3,"¿Cómo quieres de mí peras\nEstando el peral en flor\n¿Cómo quieres que te quiera\nSi es tu corazón traidor?",3,1,0,45,"",0,4,"o",72,0,-1,0,437,437,"1173","",0,"","","",1,0,0,[],""],["carrizo_salta-n1174-01",3,"Con esas tus agachadas\nA mí no me anda gustando,\nTe hacís la disimulada,\nY de amor andas tratando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,437,437,"1174","",0,"","","",1,0,0,[],""],["carrizo_salta-n1175-01",3,"¿Con eso venís pintando,\nCara de tuna madura?\nTodo lo que me prometes\nSe te vuelve levadura.",3,1,0,45,"",0,4,"ua",17,0,-1,0,437,437,"1175","",0,"","","",1,0,0,[],""],["carrizo_salta-n1176-01",3,"Con lágrimas de mis ojos\nHoy te vengo a saludar,\n¿Qué motivos yo te dí?\nNo me quieres contestar.",3,1,0,45,"",0,4,"a",21,0,-1,0,437,437,"1176","",0,"","","",1,0,0,[],""],["carrizo_salta-n1177-01",3,"Conoceme por el eco,\nYa que por el rostro no,\n¿Cómo es posible mi dueña\nQué me desconozcas vos?",3,1,0,45,"",0,4,"o",-1,0,-1,0,437,437,"1177","",0,"","","",1,0,0,[],""],["carrizo_salta-n1178-01",3,"Conozco el cristal más fino,\nY lo brillante del oro,\nLas traiciones que me has hecho\nA ninguna las ignoro.",3,1,0,45,"",0,4,"oo",85,0,-1,0,437,437,"1178","",0,"","","",1,0,0,[],""],["carrizo_salta-n1179-01",3,"¡Corazón de guayacán!\n¡Alma de quebracho duro!\n¿Cómo querís que te quiera\nSi tienes dueño seguro?",3,1,0,45,"",0,4,"uo",248,0,-1,0,437,437,"1179","",0,"","","",1,0,0,[],""],["carrizo_salta-n1179-a-01",3,"¡Corazón de palo santo!\n¡Alma de quebracho duro!\n¿Por qué me cautivas tanto\nTeniendo dueño seguro?",3,1,0,45,"",1,4,"uo",248,0,-1,0,437,437,"1179-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n1180-01",3,"¡Corazón de palo santo!\nColor de palo amarillo,\n¿Para qué me cautivaste,\nSi me has de echar en olvido?",3,1,0,45,"",0,4,"io",-1,0,-1,0,437,437,"1180","",0,"","","",3,0,0,[],""],["carrizo_salta-n1181-01",3,"¡Corazón! ¿por qué faltastes?\n¿Qué compromiso tuvistes?\n¿Por qué tan mal le has pagado\nAl que por gusto quisistes?",3,1,0,45,"",0,4,"ie",91,0,-1,0,438,438,"1181","",0,"","","",1,0,0,[],""],["carrizo_salta-n1182-01",3,"Corre el agua para arriba,\nComo corre para abajo,\n¡Vidita, si me queris\nNo me des mucho trabajo!",3,1,0,45,"",0,4,"ao",168,0,-1,0,438,438,"1182","",0,"","","",1,0,0,[],""],["carrizo_salta-n1183-01",3,"Crendo que no hi volver,\nBonito se había vestido,\nBata amarilla se ha puesto,\nCintas de color de olvido.",3,1,0,45,"",0,4,"io",101,0,-1,0,438,438,"1183","",0,"","","",1,0,0,[],""],["carrizo_salta-n1184-01",3,"Cuando alguien te hable de mí,\nNo digas que me has querido,\nQue al amor y a la fineza,\nVos jamás la has conocido.",3,1,0,45,"",0,4,"io",101,0,-1,0,438,438,"1184","",0,"","","",1,0,0,[],""],["carrizo_salta-n1185-01",3,"Cuando bien te parecía,\n¡Con qué gusto me miraste!\n¿Quién te ha hablado mal de mí\nQue tan pronto me olvidaste?",3,1,0,45,"",0,4,"ae",212,0,-1,0,438,438,"1185","",0,"","","",1,0,0,[],""],["carrizo_salta-n1186-01",3,"¿Cuándo en mi patria estaré?\n¿A quién mis quejas daré?\nTriste mi infelicidad,\nTu ingratitud lloraré.",3,1,0,45,"",0,4,"e",77,0,-1,0,438,438,"1186","",0,"","","",2,0,0,[],""],["carrizo_salta-n1187-01",3,"Cuando me fui para arriba,\nTodas lloraron por mí,\nAgora que estoy aquí,\nNadie se acuerda de mí.",3,1,0,45,"",0,4,"i",23,0,-1,0,438,438,"1187","",0,"","","",3,0,0,[],""],["carrizo_salta-n1188-01",3,"Cuando me vaya de aquí,\nYo sé lo que han de decir.\n¡Qué se vaya y que no vuelva,\nNo ha sio prenda de sentir!",3,1,0,45,"",0,4,"i",157,0,-1,0,438,438,"1188","",0,"","","",3,0,0,[],""],["carrizo_salta-n1189-01",3,"Cuando me vaya o me muera,\nCuando la tierra me coma,\nEntonces has de saber,\nSi lo que sirve te estorba.",3,1,0,45,"",0,4,"oa",-1,0,-1,0,438,438,"1189","",0,"","","",1,0,0,[],""],["carrizo_salta-n1190-01",3,"Cuando se vaya de aquí,\nSólo una cosa le pido,\nNo vaya a beber el agua,\nDe la fuente del olvido.",3,1,0,45,"",0,4,"io",101,0,-1,0,438,438,"1190","",0,"","","",1,0,0,[],""],["carrizo_salta-n1191-01",3,"Cuando te veo, niña,\nTe amo y te quiero,\nY ese tu amor en cambio,\nEs trompetero.",3,1,0,45,"",6,4,"eo",38,0,-1,0,438,438,"1191","",0,"","","",1,0,0,[],""],["carrizo_salta-n1192-01",3,"¡Cuántas veces por amarte\nDaba pasos violentos!\n¿Por qué es tan cruel mi negrita,\nQue no atiende mis lamentos?",3,1,0,45,"",0,4,"eo",234,0,-1,0,438,438,"1192","",0,"","","",4,0,0,[],""],["carrizo_salta-n1193-01",3,"¡Cuántas veces por amarte,\nSufrí hambre, sufrí vientos!\nPara que al último, vida,\nMe dieras mal pagamiento.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,438,438,"1193","",0,"","","",4,0,0,[],""],["carrizo_salta-n1194-01",3,"Cuatro leguas he corrido,\nNiña, por venirla a ver,\nVengo y me la hallo con dueño,\nNiña, me quiero volver.",3,1,0,45,"",0,4,"e",20,0,-1,0,438,438,"1194","",0,"","","",1,0,0,[],""],["carrizo_salta-n1195-01",3,"Cuatro leguas hi corrío,\nCinco no puedo correr,\nSólo por venirte a ver,\nY hallarte en otro poder.",3,1,0,45,"",0,4,"e",20,0,-1,0,439,439,"1195","",0,"","","",1,0,0,[],""],["carrizo_salta-n1196-01",3,"Cuidá tu chacra vidita,\nYo no la puedo cuidar,\nDe tanto estar al sereno,\nNegrito me vuá quedar.",3,1,0,45,"",0,4,"a",21,0,-1,0,439,439,"1196","",0,"","","",1,0,0,[],""],["carrizo_salta-n1197-01",3,"¡Chacarera, chacarera!\nChacarera del Tunal,\n¿Por qué te vas y me dejas\nY no me queris llevar?",3,1,0,45,"",0,4,"a",-1,0,-1,0,439,439,"1197","",0,"","","",13,0,0,[],""],["carrizo_salta-n1198-01",3,"¡Chiquitita, chiquitita!\nComo grano de maní\nTe gusta querer a otro,\nY no me quieres a mí.",3,1,0,45,"",0,4,"i",23,0,-1,0,439,439,"1198","",0,"","","",1,0,0,[],""],["carrizo_salta-n1199-01",3,"Dame la carta de pago,\nQue yo te daré el recibo.\nSi la firmas en la arena,\nYo lo firmaré en el río.",3,1,0,45,"",0,4,"io",-1,0,-1,0,439,439,"1199","",0,"","","",1,0,0,[],""],["carrizo_salta-n1200-01",3,"Debajo de un sauce verde,\nMe puse a considerar,\nLo mucho que te he querido,\nY el mal pago que me das.",3,1,0,45,"",0,4,"a",-1,0,-1,0,439,439,"1200","",0,"","","",3,0,0,[],""],["carrizo_salta-n1201-01",3,"Debajo un nogal,\nDebajo un nogal,\nAllí me pagastes,\nUn bien con un mal.",3,1,0,45,"",0,4,"a",1,0,-1,0,439,439,"1201","",0,"","","",1,0,0,[],""],["carrizo_salta-n1202-01",3,"Debalde querís matarme\n¡Pa lo que yo hi de morir!\nPara el año como hoy día,\nSiempre te hi de perseguir.",3,1,0,45,"",0,4,"i",157,0,-1,0,439,439,"1202","",0,"","","",1,0,0,[],""],["carrizo_salta-n1203-01",3,"Decís que no me queris,\nQue yo soy tu aborrecido,\nEl pañuelo que te dí\nCon gusto lo has recibido.",3,1,0,45,"",0,4,"io",101,0,-1,0,439,439,"1203","",0,"","","",2,0,0,[],""],["carrizo_salta-n1204-01",3,"De la águila real quisiera,\nUna pluma de su frente,\nPara escribirle a mi vida,\nQue se porte como gente.",3,1,0,45,"",0,4,"ee",15,0,-1,0,439,439,"1204","",0,"","","",1,0,0,[],""],["carrizo_salta-n1205-01",3,"De la banda mí hi venío\nDe la banda \"El Paraná\"\nNo hi de volver a venir,\nPorque me has pagado mal.",3,1,0,45,"",0,4,"a",-1,0,-1,0,439,439,"1205","",0,"","","",1,0,0,[],""],["carrizo_salta-n1206-01",3,"De lo que me prometistes,\nNada me ha salido cierto,\nPara ser tan mal pagado,\nMás vale me hubiera muerto.",3,1,0,45,"",0,4,"eo",88,0,-1,0,439,439,"1206","",0,"","","",1,0,0,[],""],["carrizo_salta-n1207-01",3,"Del sentimiento me río,\nDe la pena y del dolor,\nPara sufrir tus desprecios,\nPara eso no hallo valor.",3,1,0,45,"",0,4,"o",72,0,-1,0,439,439,"1207","",0,"","","",1,0,0,[],""],["carrizo_salta-n1208-01",3,"De que no me quiera nadie,\nA tí me debo quejar,\nQue lo que por tí he perdido,\nYa no puedo recobrar.",3,1,0,45,"",0,4,"a",21,0,-1,0,439,439,"1208","",0,"","","",1,0,0,[],""],["carrizo_salta-n1209-01",3,"Desde arriba m'hi venío,\nEn mi caballo mansito,\nPero no te detenías\nPa que hablemos un poquit.",3,1,0,45,"",5,4,"i",-1,0,-1,0,440,440,"1209","",0,"","","",17,0,0,[],""],["carrizo_salta-n1210-01",3,"Desde arriba m'hi venío\nSólo por vos, vida mía,\nEsas tus malas pasiones,\n¿Por qué las olvidaría?",3,1,0,45,"",0,4,"ia",0,0,-1,0,440,440,"1210","",0,"","","",17,0,0,[],""],["carrizo_salta-n1211-01",3,"Desde el día en que te ví,\nTengo enfermo el pensamiento,\nSi no me tienes amor,\nMi vida será un tormento.",3,1,0,45,"",0,4,"eo",94,0,-1,0,440,440,"1211","",0,"","","",4,0,0,[],""],["carrizo_salta-n1212-01",3,"Después de tender la cama,\nVidita, te echaste al suelo.\nY me has dejado llorando,\nComo caschi sin consuelo.",3,1,0,45,"",0,4,"eo",10,0,-1,0,440,440,"1212","",0,"","","",1,0,0,[],""],["carrizo_salta-n1213-01",3,"De todas flores busqué,\nPara ponerte de adorno.\nAhora desprecias las mías,\nPara mi mayor bochorno.",3,1,0,45,"",0,4,"oo",414,0,-1,0,440,440,"1213","",0,"","","",1,0,0,[],""],["carrizo_salta-n1214-01",3,"De vicio te has de extender,\nComo verdolaga en huerta,\nLa mujer que a mí me quiera,\nNo ha de andar la rienda suelta.",3,1,0,45,"",0,4,"ea",-1,0,-1,0,440,440,"1214","",0,"","","",1,0,0,[],""],["carrizo_salta-n1215-01",3,"Día y noche yo me paso,\nEn mi casa cavilando,\nSin saber si cerá cierto,\nO me tendrás engañando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,440,440,"1215","",0,"","","",1,0,0,[],""],["carrizo_salta-n1216-01",3,"Dicen que me quiere mucho\n¡Quién sabe como será!\nNunca hi dentrao a su pecho\nPa poder garantizar.",3,1,0,45,"",0,4,"a",-1,0,-1,0,440,440,"1216","",0,"","","",1,0,0,[],""],["carrizo_salta-n1217-01",3,"Dicen que no me quieres\nPorque no he sido,\nEl primero en el mundo,\nQue te ha querido.",3,1,0,45,"",6,4,"io",101,0,-1,0,440,440,"1217","",0,"","","",18,0,0,[],""],["carrizo_salta-n1218-01",3,"Dicen que no me quieren\nPorque soy fiero y raspado,\nEllas han de estar queriendo,\nUn buenmozo y entregado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,440,440,"1218","",0,"","","",1,0,0,[],""],["carrizo_salta-n1219-01",3,"Dice que me quiere mucho,\nEs mentira, no lo creo,\nPara tanto cariñito\n¡Tantos desatinos veo!",3,1,0,45,"",0,4,"eo",66,0,-1,0,440,440,"1219","",0,"","","",2,0,0,[],""],["carrizo_salta-n1220-01",3,"Dices que no me quieres,\nQue soy Romero,\nEl romerito sirve,\nPara remedio.",3,1,0,45,"",6,4,"eo",-1,0,-1,0,440,440,"1220","",0,"","","",15,0,0,[],""],["carrizo_salta-n1221-01",3,"Dices que nunca has amado,\nNo me lo digas a mí,\nMás de una vez a mi lado,\nTemblar de pasión te ví.",3,1,0,45,"",1,4,"i",23,0,-1,0,440,440,"1221","",0,"","","",1,0,0,[],""],["carrizo_salta-n1222-01",3,"Dices siempre que me quieres,\nY no sé por qué razón,\nEn vez de darme placeres,\nTorturas mi corazón.",3,1,0,45,"",1,4,"o",31,0,-1,0,440,440,"1222","",0,"","","",1,0,0,[],""],["carrizo_salta-n1223-01",3,"Dijo un pajarillo amante:\n—Nadie se debe casar,\nSi al bien casado le pesa,\n¡Qué será al casado mal!",3,1,0,45,"",0,4,"a",-1,0,-1,0,441,441,"1223","",0,"","","",2,0,0,[],""],["carrizo_salta-n1224-01",3,"Dime si me quieres,\nDime la verdad,\nPara yo quererte,\nCon seguridad.",3,1,0,45,"",0,4,"a",16,0,-1,0,441,441,"1224","",0,"","","",1,0,0,[],""],["carrizo_salta-n1225-01",3,"Dime, dueña, la verdad,\n¿Qué motivo y qué razón\nTuvistes para agraviar\nMi rendido corazón?",3,1,0,45,"",0,4,"o",31,0,-1,0,441,441,"1225","",0,"","","",2,0,0,[],""],["carrizo_salta-n1226-01",3,"Dime, niña, si me quieres,\n¡Por Dios descubre tu pecho!\nQue no quiero en este mundo,\nPasar tiempo sin provecho.",3,1,0,45,"",0,4,"eo",60,0,-1,0,441,441,"1226","",0,"rm_t2","","",2,0,0,[],""],["carrizo_salta-n1227-01",3,"El alma, mi bien, te dí,\nPensando que has de ser fiel,\nComo fuistes tan ingrata,\nVuelvo el alma a recoger.",3,1,0,45,"",0,4,"e",-1,0,-1,0,441,441,"1227","",0,"","","",2,0,0,[],""],["carrizo_salta-n1228-01",3,"El amor que puse en tí,\nTan firme y tan verdadero,\nSi lo hubiera puesto en Dios,\nYa hubiera ganado el cielo.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,441,441,"1228","",0,"","","",4,0,0,[],""],["carrizo_salta-n1229-01",3,"El amor que yo te tuve,\nSe volvió ceniza y humo.\nAsí es tu querer, vidita,\nCuando no estás cerca de uno.",3,1,0,45,"",0,4,"uo",-1,0,-1,0,441,441,"1229","",0,"","","",2,0,0,[],""],["carrizo_salta-n1230-01",3,"El amor y desconfianza,\nEn batalla están conmigo,\nEl amor me pone ciego,\nY la desconfianza esquivo.",3,1,0,45,"",0,4,"io",-1,0,-1,0,441,441,"1230","",0,"","","",1,0,0,[],""],["carrizo_salta-n1231-01",3,"El beso es una limosna,\nQue brota del corazón,\nNo me niegues, vida mía,\nEl dulce pan de tu amor.",3,1,0,45,"",0,4,"o",-1,0,-1,0,441,441,"1231","",0,"","","",1,0,0,[],""],["carrizo_salta-n1232-01",3,"El corazón te entregué,\nCon todita mi pasión,\nY tu corazón ingrato,\nMe ha pagado con traición.",3,1,0,45,"",0,4,"o",31,0,-1,0,441,441,"1232","",0,"","","",1,0,0,[],""],["carrizo_salta-n1233-01",3,"El cuervo, con ser el cuervo,\nPara a veces su volido.\n¿Cómo quieres separarte,\nDe un corazón tan querido?",3,1,0,45,"",0,4,"io",101,0,-1,0,441,441,"1233","",0,"","","",1,0,0,[],""],["carrizo_salta-n1234-01",3,"El deber, no es deshonroso\nEso le pasa a cualquiera,\nNo me tome por tramposo,\nNi menos por calavera.",3,1,0,45,"",1,4,"ea",44,0,-1,0,441,441,"1234","",0,"","","",1,0,0,[],""],["carrizo_salta-n1235-01",3,"El día que tu te cases,\nAquel día muero yo,\nSe juntarán en la iglesia,\nMi entierro y tu velación.",3,1,0,45,"",0,4,"o",-1,0,-1,0,442,442,"1235","",0,"","","",2,0,0,[],""],["carrizo_salta-n1236-01",3,"El juramento que te hice,\nYo no lo debo cumplir,\nQuerís que comparta amor,\nYo no quiero compartir.",3,1,0,45,"",0,4,"i",157,0,-1,0,442,442,"1236","",0,"","","",1,0,0,[],""],["carrizo_salta-n1237-01",3,"El mundo se ha dedicado\nSólo a confundir mi vida,\nA ponerme por los suelos,\nEntre cuentos y mentiras.",3,1,0,45,"",0,4,"ia",-1,0,-1,0,442,442,"1237","",0,"","","",1,0,0,[],""],["carrizo_salta-n1238-01",3,"El naranjo tiene espinas,\nEl limoncillo también,\nMi corazoncito es tuyo,\nY el tuyo no sé de quién.",3,1,0,45,"",0,4,"e",242,0,-1,0,442,442,"1238","",0,"","","",3,0,0,[],""],["carrizo_salta-n1239-01",3,"El quererla fué mi gusto,\nYa que tanto mereció;\nHabrá sido más dichosa,\nPero más constante, no.",3,1,0,45,"",0,4,"o",2,0,-1,0,442,442,"1239","",0,"","","",1,0,0,[],""],["carrizo_salta-n1240-01",3,"El quererme a mí quitar,\nDe mi pecho el sentimiento,\nEs escribir en el agua,\nY predicar en desierto.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,442,442,"1240","",0,"","","",3,0,0,[],""],["carrizo_salta-n1241-01",3,"El zapatito me ajusta,\nLa media me da calor,\n¿Cómo querís que te quiera\nSi no me tenís amor?",3,1,0,45,"",0,4,"o",72,0,-1,0,442,442,"1241","",0,"","","",1,0,0,[],""],["carrizo_salta-n1241-a-01",3,"Las botas me tienen loco,\nPorque hace mucho calor,\n¿Cómo querís que te quiera\nSi no me tenís amor?",3,1,0,45,"",0,4,"o",72,0,-1,0,442,442,"1241-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1242-01",3,"Encima mi sepultura,\nAllí pondrás un letrero:\n\"Aquí descansa un amante\nEl más firme y verdadero\".",3,1,0,45,"",0,4,"eo",38,0,-1,0,442,442,"1242","",0,"","","",1,0,0,[],""],["carrizo_salta-n1243-01",3,"En el campo hay una flor,\nQue le llaman la jamada,\n¿Cómo querís que yo sepa\nSi jamás me has dicho nada?",3,1,0,45,"",0,4,"aa",49,0,-1,0,442,442,"1243","",0,"","","",5,0,0,[],""],["carrizo_salta-n1244-01",3,"En el campo hay una flor,\nQue le llaman toda cepa,\n¿Cómo querís que te quiera\nSi jamás me almitís cerca?",3,1,0,45,"",0,4,"ea",-1,0,-1,0,442,442,"1244","",0,"","","",5,0,0,[],""],["carrizo_salta-n1245-01",3,"En el campo hay una flor,\n¡Qué se llama cardo santo,\n¡No me hagas moniar mintiendo!\n¡Ni me hagas presumir tanto!",3,1,0,45,"",0,4,"ao",30,0,-1,0,442,442,"1245","",0,"","","",5,0,0,[],""],["carrizo_salta-n1245-a-01",3,"En el campo hay una yerba,\nQue se llama cardo santo,\nDecime si me querís,\nNo me hagas padecer tanto.",3,1,0,45,"",0,4,"ao",30,0,-1,0,442,442,"1245-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n1246-01",3,"En el fuego en que me abraso,\nTe quisiera ver arder,\nPara que sepas, ingrata,\nLo que cuesta un buen querer.",3,1,0,45,"",0,4,"e",20,0,-1,0,442,442,"1246","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["carrizo_salta-n1247-01",3,"En la cara se conoce,\nEl amor que es verdadero,\nNo está la monta en decir:\n—¡Hijito, mucho te quiero!",3,1,0,45,"",0,4,"eo",38,0,-1,0,443,443,"1247","",0,"","","",1,0,0,[],""],["carrizo_salta-n1248-01",3,"En la falda de aquel cerro,\nTengo una planta de rosa,\nYo no te tengo en los brazos,\nPorque tu mama es celosa.",3,1,0,45,"",0,4,"oa",63,0,-1,0,443,443,"1248","",0,"","","",54,0,0,[],""],["carrizo_salta-n1249-01",3,"En la falda de aquel cerro,\nTengo una planta i cebil,\nEso quisiera saber\nSi nos vamos al civil.",3,1,0,45,"",0,4,"i",290,0,-1,0,443,443,"1249","",0,"","","",54,0,0,[],""],["carrizo_salta-n1250-01",3,"En los telares de amor,\nDonde se trama y se teje,\nAhí has de ver con el tiempo\nCuando queriendo te deje.",3,1,0,45,"",0,4,"ee",173,0,-1,0,443,443,"1250","",0,"","","",1,0,0,[],""],["carrizo_salta-n1251-01",3,"En mi casa no me quieren,\nPorque soy muy calavera,\nEn todo el mundo yo debo,\nA cada santo una vela.",3,1,0,45,"",0,4,"ea",-1,0,-1,0,443,443,"1251","",0,"","","",1,0,0,[],""],["carrizo_salta-n1252-01",3,"Entre polkas, pocas pocas,\nY mazurcas ralo ralo,\nAsí me tiene tu amor,\nComo lechuza en un palo.",3,1,0,45,"",0,4,"ao",71,0,-1,0,443,443,"1252","",0,"","","",1,0,0,[],""],["carrizo_salta-n1253-01",3,"Eres como el arco iris,\nQue retira la tormenta,\nYo me retiro de tí,\nPues no me tenís en cuenta.",3,1,0,45,"",0,4,"ea",229,0,-1,0,443,443,"1253","",0,"","","",1,0,0,[],""],["carrizo_salta-n1254-01",3,"Esas penas y tormentos,\nQue he padecido a porfía,\nVos también padecerás,\nSeguramente algún día.",3,1,0,45,"",0,4,"ia",0,0,-1,0,443,443,"1254","",0,"","","",1,0,0,[],""],["carrizo_salta-n1255-01",3,"Esa tu fina amistad,\nQue fué desde muy primero.\nLo que te puedo decir,\nComo te dure ha i ser bueno.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,443,443,"1255","",0,"","","",1,0,0,[],""],["carrizo_salta-n1256-01",3,"Esa tu linda boquita,\nY tu lengua engañadora,\nYa me han engañado a mí,\n¿A quién engañan ahora?",3,1,0,45,"",0,4,"oa",107,0,-1,0,443,443,"1256","",0,"","","",1,0,0,[],""],["carrizo_salta-n1257-01",3,"Ese amor que me juraste,\nQue me juraste una tarde,\nEl viento se lo llevó,\nEn una forma cobarde.",3,1,0,45,"",0,4,"ae",344,0,-1,0,443,443,"1257","",0,"","","",1,0,0,[],""],["carrizo_salta-n1258-01",3,"¡Esperanza! bien pudieras,\nDejarme de perseguir,\nHasta ver, mi desengaño,\nVidita, t'hi de seguir.",3,1,0,45,"",0,4,"i",157,0,-1,0,443,443,"1258","",0,"","","",1,0,0,[],""],["carrizo_salta-n1259-01",3,"Espiga de arroz,\nEspiga de arroz,\nTrata con una,\nNo trates con dos.",3,1,0,45,"",6,4,"o",87,0,-1,0,443,443,"1259","",0,"","","",1,0,0,[],""],["carrizo_salta-n1260-01",3,"¿Es posible, vida mía,\nSiendo todo mi querer,\nQue me has cerrado tus puertas,\nMe has echado a padecer?",3,1,0,45,"",0,4,"e",20,0,-1,0,443,443,"1260","",0,"","","",1,0,0,[],""],["carrizo_salta-n1261-01",3,"Esta cajita que toco,\nMuy bien, muy bien.\nA mí todos me celan\nSin ver con quién.",3,1,0,45,"",6,4,"e",242,0,-1,0,444,444,"1261","",0,"","","",6,0,0,[],""],["carrizo_salta-n1262-01",3,"Esta tarde y esta noche,\nY mañana como ayer,\nLlevaré mi desventura\nSi me dejas de querer.",3,1,0,45,"",0,4,"e",20,0,-1,0,444,444,"1262","",0,"","","",1,0,0,[],""],["carrizo_salta-n1263-01",3,"Este es el remate nuevo\nSacao del año presente,\n¿Cómo querís que te quiera\nCuando vos andás ausente?",3,1,0,45,"",0,4,"ee",15,0,-1,0,444,444,"1263","",0,"","","",12,0,0,[],""],["carrizo_salta-n1264-01",3,"Es tu amor como una vela,\nQue no se apaga ni enciende,\nEl amor que me tenís,\nNadie en el mundo lo entiende.",3,1,0,45,"",0,4,"ee",233,0,-1,0,444,444,"1264","",0,"","","",1,0,0,[],""],["carrizo_salta-n1265-01",3,"Es verdad que puse en tí,\nAmor firme y lo olvidastes,\nQue yo te olvide por otro,\nClaro está que me enseñastes.",3,1,0,45,"",0,4,"ae",142,0,-1,0,444,444,"1265","",0,"","","",3,0,0,[],""],["carrizo_salta-n1266-01",3,"Es verdad que te he querido,\nQue te he querido y te quiero,\nCasarme ahora no puedo,\nVeremos para Año Nuevo.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,444,444,"1266","",0,"","","",4,0,0,[],""],["carrizo_salta-n1267-01",3,"Es verdad que t'hi querido,\nQue en tí puse mi afición,\nY es verdad que te aborrezco\nPor tu corazón traidor.",3,1,0,45,"",0,4,"o",-1,0,-1,0,444,444,"1267","",0,"","","",1,0,0,[],""],["carrizo_salta-n1268-01",3,"¡Falsa, tirana incostante!\n¡Alevosa engañadora!\n¿Así pagas a tu amante,\nCuándo en de veras te adora?",3,1,0,45,"",1,4,"oa",107,0,-1,0,444,444,"1268","",0,"","","",1,0,0,[],""],["carrizo_salta-n1269-01",3,"Fingías que me querías,\nY fingías que me amabas,\nY ahora veo tirana,\nQue con otra te regalas.",3,1,0,45,"",0,4,"aa",-1,0,-1,0,444,444,"1269","",0,"","","",1,0,0,[],""],["carrizo_salta-n1270-01",3,"Florcita de palo i lanza,\nAquí traigo tu esperanza,\nNo me mires con desprecio,\nQue yo pago con costancia.",3,1,0,45,"",0,4,"aa",-1,0,-1,0,444,444,"1270","",0,"","","",1,0,0,[],""],["carrizo_salta-n1271-01",3,"Fueron todas tus palabras,\nComo lluvia de verano,\nPor la mañana cayeron,\nPor la tarde se secaron.",3,1,0,45,"",0,4,"ao",-1,0,-1,0,444,444,"1271","",0,"","","",1,0,0,[],""],["carrizo_salta-n1272-01",3,"¡Granito de arena!\n¡Florcita de azahar!\nQuereme, vidita,\nNo me hagas penar.",3,1,0,45,"",0,4,"a",21,0,-1,0,444,444,"1272","",0,"","","",1,0,0,[],""],["carrizo_salta-n1273-01",3,"Has dicho que me querís,\nY eso es por entretenerme,\nPor gozar de mis cariños,\nY después aborrecerme.",3,1,0,45,"",0,4,"ee",245,0,-1,0,444,444,"1273","",0,"","","",1,0,0,[],""],["carrizo_salta-n1274-01",3,"¿Hasta cuándo me tendrás\nDe centinela en tus puertas,\nContando todas las horas,\nComo el reloj dando vueltas?",3,1,0,45,"",0,4,"ea",-1,0,-1,0,444,444,"1274","",0,"","","",1,0,0,[],""],["carrizo_salta-n1275-01",3,"¿Hasta cuándo vida mía\nMe vas ha tener penando?\nEchemos la capa al toro,\nAunque revienten hablando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,445,445,"1275","",0,"","","",11,0,0,[],""],["carrizo_salta-n1276-01",3,"Hasta para que te quiera\nQuieres que te haga llamar,\nA mí me cuesta vergüenza\nTu falta de voluntad.",3,1,0,45,"",0,4,"a",-1,0,-1,0,445,445,"1276","",0,"","","",1,0,0,[],""],["carrizo_salta-n1277-01",3,"¡Ingrata como ninguna!\nAlgún día has de llorar,\nQueriendo al que no te quiera,\nAsí me la has de pagar.",3,1,0,45,"",0,4,"a",21,0,-1,0,445,445,"1277","",0,"","","",1,0,0,[],""],["carrizo_salta-n1278-01",3,"¡Ingrata vil incostante!\nDe poco conocimiento,\nSobradas razones tengo,\nDe decir lo que yo siento.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,445,445,"1278","",0,"","","",1,0,0,[],""],["carrizo_salta-n1279-01",3,"La palabra que me distes,\nNo fué bajo juramento,\nSólo fué para engañarme,\nQue tratastes casamiento.",3,1,0,45,"",0,4,"eo",94,0,-1,0,445,445,"1279","",0,"","","",3,0,0,[],""],["carrizo_salta-n1280-01",3,"La paloma baja al agua\nA beber en un pocito,\nPor eso digo cantando:\n—Tu amor es trabajosito.",3,1,0,45,"",0,4,"io",119,0,-1,0,445,445,"1280","",0,"","","",2,0,0,[],""],["carrizo_salta-n1281-01",3,"Las estrellas se han caído\nY al aire cuatro quedaron,\nEl dolor que a mí me queda,\nQue por otro me has dejado.",3,1,0,45,"",0,4,"ao",-1,0,-1,0,445,445,"1281","",0,"","","",1,0,0,[],""],["carrizo_salta-n1282-01",3,"¡Llorá si tenés vergüenza!\n¡Llorá, llorá tu cariño!\nQue yo también por tu amor\nLloré lo mismo que un niño.",3,1,0,45,"",0,4,"io",176,0,-1,0,445,445,"1282","",0,"","","",1,0,0,[],""],["carrizo_salta-n1283-01",3,"Llora, llora urataú\nEn la sombra y el misterio,\n¿Quién te va a querer a vos\nSi tu corazón no es serio?",3,1,0,45,"",0,4,"eo",398,0,-1,0,445,445,"1283","",0,"","","",1,0,0,[],""],["carrizo_salta-n1284-01",3,"Mandame a tirar al blanco\nEn la plaza del Retiro,\nDonde se están disputando,\nLa ausencia con el olvido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,445,445,"1284","",0,"","","",1,0,0,[],""],["carrizo_salta-n1285-01",3,"Mañana y pasao,\nPor ahí hi de andar,\nPreguntando a todos,\nComo te has portao.",3,1,0,45,"",5,4,"ao",98,0,-1,0,445,445,"1285","",0,"","","",1,0,0,[],""],["carrizo_salta-n1286-01",3,"¡Matame si no te sirvo!\nCharquiame, echame a la soga,\nLlevame pa Cafayate\nCambiame por algarroba.",3,1,0,45,"",0,4,"oa",-1,0,-1,0,445,445,"1286","",0,"","","",1,0,0,[],""],["carrizo_salta-n1287-01",3,"Me acuerdo de ese momento,\nCuando juntitos los dos,\nMutuo amor nos prometimos,\nYo cumplí pero vos no.",3,1,0,45,"",0,4,"o",-1,0,-1,0,446,446,"1287","",0,"","","",1,0,0,[],""],["carrizo_salta-n1288-01",3,"Media luna, luna entera\nLuna tiene mi bandera,\nYo te encargo, vida mía,\nQue no trates con cualquiera.",3,1,0,45,"",0,4,"ea",44,0,-1,0,446,446,"1288","",0,"","","",3,0,0,[],""],["carrizo_salta-n1289-01",3,"Me dicen que andas diciendo,\nQue no te importa nada de mí,\n¿Cómo si te importa\nQué andas haciendo por tras de mí?",3,1,0,45,"",3,4,"i",-1,0,-1,0,446,446,"1289","",0,"","","",2,0,0,[],""],["carrizo_salta-n1290-01",3,"Me dicen que tu te casas,\nMirá que pena es la mía,\nAl ver en brazos ajenos,\nLa prenda que yo quería.",3,1,0,45,"",0,4,"ia",0,0,-1,0,446,446,"1290","",0,"","","",2,0,0,[],""],["carrizo_salta-n1291-01",3,"Me dices que no me quieres,\nQue no me, quieres me dices,\nQue soy hijo de las cabras,\nCriado por las perdices.",3,1,0,45,"",0,4,"ie",113,0,-1,0,446,446,"1291","",0,"","","",6,0,0,[],""],["carrizo_salta-n1292-01",3,"Me han dicho que no me quieres,\n¿Por qué no me dices franco?\nDecímelo así en la cara\nPara no sufrir yo tanto.",3,1,0,45,"",0,4,"ao",-1,0,-1,0,446,446,"1292","",0,"","","",3,0,0,[],""],["carrizo_salta-n1293-01",3,"Me has hecho penar.\nMe has hecho llorar,\n¿Por qué, mi vidita,\nMe piensas dejar?",3,1,0,45,"",0,4,"a",21,0,-1,0,446,446,"1293","",0,"","","",1,0,0,[],""],["carrizo_salta-n1298-01",3,"Me voy para lejos,\nNo pienso volver,\nY dejo a mi negra,\nQue aprenda a querer.",3,1,0,45,"",0,4,"e",20,0,-1,0,446,446,"1298","",0,"","","",1,0,0,[],""],["carrizo_salta-n1299-01",3,"Mi casa es debajo l'agua,\nEn una profundidad,\nYa sabe joven mi casa,\nSi me quiere visitar.",3,1,0,45,"",0,4,"a",-1,0,-1,0,446,446,"1299","",0,"","","",1,0,0,[],""],["carrizo_salta-n1300-01",3,"Mira como se consume,\nLa vela de tanto arder,\nAsí me consumo yo,\nPor tu ingrato proceder.",3,1,0,45,"",0,4,"e",20,0,-1,0,446,446,"1300","",0,"","","",1,0,0,[],""],["carrizo_salta-n1301-01",3,"¡Mira estas flores vidita,\nCon cariño y compasión!\nEllas te dirán llorando:\n—No me olvides, corazón.",3,1,0,45,"",0,4,"o",31,0,-1,0,446,446,"1301","",0,"","","",1,0,0,[],""],["carrizo_salta-n1302-01",3,"Mirando lo que me has hecho\nMucho tenimos que hablar\nYo no te hi dar mi palabra.\n¡Con traición me has de pagar!",3,1,0,45,"",0,4,"a",21,0,-1,0,447,447,"1302","",0,"","","",1,0,0,[],""],["carrizo_salta-n1303-01",3,"¡Mirelán como se va!\nY dijo que me quería,\nTan presto se va olvidando,\nEl amor que me tenía.",3,1,0,45,"",0,4,"ia",0,0,-1,0,447,447,"1303","",0,"","","",2,0,0,[],""],["carrizo_salta-n1303-a-01",3,"Mirelán como se va\nLa que me sabía querer,\nTan prontito echa en olvido\nL'amor que sabía tener.",3,1,0,45,"",0,4,"e",20,0,-1,0,447,447,"1303-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n1304-01",3,"Mi vidita se ha enojado\nPorque no l' hi dicho adiós,\n¡Hasta mañana, mi vida!\n¡Adiós, mi vidita, adiós!",3,1,0,45,"",0,4,"o",-1,0,-1,0,447,447,"1304","",0,"","","",1,0,0,[],""],["carrizo_salta-n1305-01",3,"¡Modera tu corazón!\nAmada prenda querida,\nY verás que por tu amor,\nEstoy por perder la vida.",3,1,0,45,"",0,4,"ia",37,0,-1,0,447,447,"1305","",0,"","","",1,0,0,[],""],["carrizo_salta-n1306-01",3,"Motivo nunca has tenido,\nPa que te alejes de mí,\nSi no he sido de tu gusto,\nDame el alma que te dí.",3,1,0,45,"",0,4,"i",23,0,-1,0,447,447,"1306","",0,"","","",1,0,0,[],""],["carrizo_salta-n1307-01",3,"Mozo libre siempre hi sío,\nMozo libre siempre hi ser\nMe quieres privar mis gustos,\nY eso es lo que no has de oler.",3,1,0,45,"",0,4,"e",20,0,-1,0,447,447,"1307","",0,"","","",1,0,0,[],""],["carrizo_salta-n1308-01",3,"Mozo pobre siempre hi sio,\nAsí pobre me has querido,\nSi precisabas riqueza,\n¿Para qué me has consentido?",3,1,0,45,"",0,4,"io",101,0,-1,0,447,447,"1308","",0,"","","",1,0,0,[],""],["carrizo_salta-n1309-01",3,"Muerto me quisiera ver,\nPor no verme mal pagado.\nEl que se muere descansa,\nY olvida lo que ha pasado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,447,447,"1309","",0,"","","",1,0,0,[],""],["carrizo_salta-n1310-01",3,"Mucho la quiero, vidita,\nPero recelo su alteza,\nTengo miedo que me diga,\n¡Viene con tanta franqueza!",3,1,0,45,"",0,4,"ea",108,0,-1,0,447,447,"1310","",0,"","","",2,0,0,[],""],["carrizo_salta-n1311-01",3,"Mucho te quiero, vidita,\nNo te doy a conocer,\nVos como a perro me tratas,\nMe das un güeso a morder.",3,1,0,45,"",0,4,"e",20,0,-1,0,447,447,"1311","",0,"","","",1,0,0,[],""],["carrizo_salta-n1312-01",3,"No está arriba, no está abajo,\nPero aquí cerquita está,\nEn la cara tiene pecas,\nEn la garganta un lunar,\nY en el pecho ingratitudes,\nComo rosa en un rosal.",3,1,0,45,"",9,6,"a",-1,0,-1,0,447,447,"1312","",0,"","","",1,0,0,[],""],["carrizo_salta-n1313-01",3,"No me dejes tener pena,\nNo me dejes padecer,\nSi te vas a media noche,\nVolvete al amanecer.",3,1,0,45,"",0,4,"e",20,0,-1,0,448,448,"1313","",0,"","","",1,0,0,[],""],["carrizo_salta-n1314-01",3,"No me desprecies, vidita,\nYo voy a cumplir tu antojo,\n¿Qué nunca has visto morir,\nUn guapo en manos de un flojo?",3,1,0,45,"",0,4,"oo",400,0,-1,0,448,448,"1314","",0,"","","",1,0,0,[],""],["carrizo_salta-n1315-01",3,"No me digas que te olvide,\nAunque lo pidas llorando,\nOye nomás los consejos,\nDel que te está aconsejando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,448,448,"1315","",0,"","","",4,0,0,[],""],["carrizo_salta-n1316-01",3,"No me importa que la lleven,\nAlgún día ha de volver,\nYo la esperaré en mi casa,\nHasta que aprenda a querer.",3,1,0,45,"",0,4,"e",20,0,-1,0,448,448,"1316","",0,"","","",1,0,0,[],""],["carrizo_salta-n1317-01",3,"No me trates con engaño,\nNi con halagos fingidos,\nTratame con la verdad,\nSi quieres que sea tu amigo.",3,1,0,45,"",0,4,"io",-1,0,-1,0,448,448,"1317","",0,"","","",1,0,0,[],""],["carrizo_salta-n1318-01",3,"No me tratís con engaño\nNi con halagos fingidos,\nAdvierte que soy constante,\nY cuando quiero no olvido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,448,448,"1318","",0,"","","",1,0,0,[],""],["carrizo_salta-n1319-01",3,"No me tratís con engaños,\nPorque no soy tu enemigo,\nLa pura verdad te digo,\nComo se dice a un amigo.",3,1,0,45,"",0,4,"io",106,0,-1,0,448,448,"1319","",0,"","","",1,0,0,[],""],["carrizo_salta-n1320-01",3,"No ponga mi amor en duda,\nQue en mí no hallará mudanza,\nHágame una promesita,\nQue me sirva de esperanza.",3,1,0,45,"",0,4,"aa",163,0,-1,0,448,448,"1320","",0,"","","",1,0,0,[],""],["carrizo_salta-n1321-01",3,"No por mucho madrugar,\nAmanece más temprano,\n¿Quieres borrar con el codo,\nLo que has hecho con la mano?",3,1,0,45,"",0,4,"ao",81,0,-1,0,448,448,"1321","",0,"","","",2,0,0,[],""],["carrizo_salta-n1322-01",3,"No porque me andes queriendo,\nProcedas con fantasía,\nPorque la fruta de este árbol,\nNo dura todos los días.",3,1,0,45,"",0,4,"ia",-1,0,-1,0,448,448,"1322","",0,"","","",1,0,0,[],""],["carrizo_salta-n1323-01",3,"No porque seas mujer,\nCon paradas no me vengas,\nA mí no me espantan rosas,\nPor más espinas que tengan.",3,1,0,45,"",0,4,"ea",-1,0,-1,0,448,448,"1323","",0,"","","",1,0,0,[],""],["carrizo_salta-n1324-01",3,"No seas así, mi negrita,\nEntregame el corazón,\nAmor pobre y leña verde,\nArden cuando hay ocasión.",3,1,0,45,"",0,4,"o",31,0,-1,0,448,448,"1324","",0,"","","",1,0,0,[],""],["carrizo_salta-n1325-01",3,"No soy piedra, ni soy bronce,\nPara no saber sentir,\nLo que mis ojos han visto,\nY lo que yo oigo decir.",3,1,0,45,"",0,4,"i",157,0,-1,0,448,448,"1325","",0,"","","",1,0,0,[],""],["carrizo_salta-n1326-01",3,"No te arrimes a la rama,\nNo me derrames la flor,\nArrimate al mismo tronco,\nVerás qué firme es mi amor.",3,1,0,45,"",0,4,"o",72,0,-1,0,448,448,"1326","",0,"","","",1,0,0,[],""],["carrizo_salta-n1327-01",3,"No te entregaré mi amor,\nSin tener conocimiento,\nPorque después ya no vale,\nLlorar arrepentimiento.",3,1,0,45,"",0,4,"eo",94,0,-1,0,448,448,"1327","",0,"","","",1,0,0,[],""],["carrizo_salta-n1328-01",3,"No te metas a la huella,\nAndando bien por l'orilla,\nNarices de queso fresco,\nVerijas de mantequilla.",3,1,0,45,"",0,4,"ia",162,0,-1,0,448,448,"1328","",0,"","","",1,0,0,[],""],["carrizo_salta-n1329-01",3,"¡Oiga la celosita!\n¿No baraja la bonita?\nTiende ancho para dormir,\nDespués se acuesta sólita.",3,1,0,45,"",5,4,"oa",-1,0,-1,0,449,449,"1329","",0,"","","",1,0,0,[],""],["carrizo_salta-n1330-01",3,"¡Ojitos de terciopelo!\nLabios de clavel morado,\nNo me des tanto pesar,\nDe sobra es lo que me has dado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,449,449,"1330","",0,"","","",4,0,0,[],""],["carrizo_salta-n1331-01",3,"¡Ojos de perra dañina!\n¿Por qué me has tratado así?\nBoca de puerta i corral,\nSentido me voy de aquí.",3,1,0,45,"",0,4,"i",23,0,-1,0,449,449,"1331","",0,"","","",1,0,0,[],""],["carrizo_salta-n1332-01",3,"¡Ojos negros de mi vida!\n¿Por qué me mirais así\nContentos para otra parte\nY enojados para mí?",3,1,0,45,"",0,4,"i",23,0,-1,0,449,449,"1332","",0,"","","",1,0,0,[],""],["carrizo_salta-n1332-a-01",3,"¿Qué tienen tus ojos negros,\nQué no me miran a mí?\nContentos están con otros\nEmpañados para mí.",3,1,0,45,"",0,4,"i",-1,0,-1,0,449,449,"1332-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1333-01",3,"¡Pajarito bochinchero!\n¡Ojos de clavel rosado!\nSeña de que tienes otro\nY de mí te has olvidado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,449,449,"1333","",0,"","","",1,0,0,[],""],["carrizo_salta-n1333-a-01",3,"¡Palomita bandolera!\nPico de clavel dorado,\nYa sé que vivís con otro\nY de mí te has olvidado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,449,449,"1333-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1334-01",3,"¡Paloma, que ayer estabas,\nEn el jardín de mi pecho!\n¿Por qué has dejado tu nido?\n¿Dónde has ido? ¿qué te has hecho?",3,1,0,45,"",0,4,"eo",60,0,-1,0,449,449,"1334","",0,"","","",1,0,0,[],""],["carrizo_salta-n1335-01",3,"Paloma quisiera ser,\nPaloma del Portezuelo,\nPara dentrar en tu pecho\nDecirte mi desconsuelo.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,449,449,"1335","",0,"","","",1,0,0,[],""],["carrizo_salta-n1336-01",3,"Para mí todo es lo mismo,\nInvierno que primavera,\nQue me maten tus desprecios,\nO que por quererte muera.",3,1,0,45,"",0,4,"ea",44,0,-1,0,449,449,"1336","",0,"","","",2,0,0,[],""],["carrizo_salta-n1337-01",3,"¿Para qué apagas los ojos\nY no me quieres mirar?\nSin duda que ya has hallado\nOtro dueño a quien amar.",3,1,0,45,"",0,4,"a",21,0,-1,0,449,449,"1337","",0,"","","",1,0,0,[],""],["carrizo_salta-n1338-01",3,"¡Para qué yo habré nacido!\n¡Tan desgraciado había sido!\nMás antes me hubiera muerto,\nSin haberte conocido.",3,1,0,45,"",0,4,"io",101,0,-1,0,449,449,"1338","",0,"","","",1,0,0,[],""],["carrizo_salta-n1339-01",3,"¿Para qué me das pañuelo\nCon puntas para llorar?\nSabiendo que este pañuelo\nLa vida me ha de costar.",3,1,0,45,"",1,4,"a",21,0,-1,0,449,449,"1339","",0,"","","",1,0,0,[],""],["carrizo_salta-n1340-01",3,"¿Para qué me das pañuelos\nCon puntas para zurcir?\n¿Por qué no me das cuchillo\nCon puntas para morir?",3,1,0,45,"",0,4,"i",157,0,-1,0,449,449,"1340","",0,"","","",1,0,0,[],""],["carrizo_salta-n1341-01",3,"¿Para qué venís moniando\nSi está tu dueña presente?\nY si ven tu mala fé\n¿Qué sabrá decir la gente?",3,1,0,45,"",0,4,"ee",15,0,-1,0,450,450,"1341","",0,"","","",1,0,0,[],""],["carrizo_salta-n1342-01",3,"Para visitarte, prenda,\nVenía de noche y de día\nY había sabido tu dueño,\nEl amor que te tenía.",3,1,0,45,"",3,4,"ia",0,0,-1,0,450,450,"1342","",0,"","","",1,0,0,[],""],["carrizo_salta-n1344-01",3,"Planta i chacra,\nPlanta i chacra,\n¿Por qué me mira\nY se agacha?",3,1,0,45,"",3,4,"aa",-1,0,-1,0,450,450,"1344","",0,"","","",1,0,0,[],""],["carrizo_salta-n1345-01",3,"¡Pobre mi negra,\nMe cela y se va!\nTarde o temprano,\nMe la ha de pagar.",3,1,0,45,"",3,4,"a",-1,0,-1,0,450,450,"1345","",0,"","","",3,0,0,[],""],["carrizo_salta-n1349-01",3,"Porque ya dejo un momento,\nLe causa tanta tristeza,\nNo ha sido por olvidarla,\nSino por ver su firmeza.",3,1,0,45,"",0,4,"ea",108,0,-1,0,450,450,"1349","",0,"","","",1,0,0,[],""],["carrizo_salta-n1350-01",3,"¿Por qué me das un pañuelo\nCon puntas para bordar,\nY no me das un pañuelo,\nCon puntas para olvidar?",3,1,0,45,"",1,4,"a",21,0,-1,0,450,450,"1350","",0,"","","",1,0,0,[],""],["carrizo_salta-n1351-01",3,"Porque no tuve dinero,\nMe dejastes de querer,\n¿Qué rico es el que te ama,\nInteresada mujer?",3,1,0,45,"",0,4,"e",20,0,-1,0,450,450,"1351","",0,"","","",1,0,0,[],""],["carrizo_salta-n1352-01",3,"Porque no tenía dinero,\nNo me quisiste mirar,\nYo no pensé que el amor,\nEra cosa de comprar.",3,1,0,45,"",0,4,"a",21,0,-1,0,450,450,"1352","",0,"","","",1,0,0,[],""],["carrizo_salta-n1353-01",3,"Porque te has visto querida\nTe has créido tan soberana,\nLos desprecios que me has hecho,\nLos has de pagar mañana.",3,1,0,45,"",0,4,"aa",4,0,-1,0,450,450,"1353","",0,"","","",1,0,0,[],""],["carrizo_salta-n1354-01",3,"Por tí he perdido la calma,\nLa memoria y el sentido,\nLuego perderé la vida,\nSi no soy correspondido.",3,1,0,45,"",0,4,"io",101,0,-1,0,450,450,"1354","",0,"","","",1,0,0,[],""],["carrizo_salta-n1355-01",3,"Por una senda de abrojos,\nVive mi amor renegando,\n¿Cuándo dejará de andar\nPor Ud. mi amor penando?",3,1,0,45,"",0,4,"ao",33,0,-1,0,450,450,"1355","",0,"","","",1,0,0,[],""],["carrizo_salta-n1356-01",3,"¡Preciosos ramos de flores!\nPor vos yo vivo penando\nComo me niegas tu amor,\nTriste lo paso llorando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,450,450,"1356","",0,"","","",1,0,0,[],""],["carrizo_salta-n1357-01",3,"Puse al cielo por testigo,\nCon firme amor te adoré,\nAhora inocente digo:\n—Mi cariño, vuelvemé.",3,1,0,45,"",1,4,"e",77,0,-1,0,451,451,"1357","",0,"","","",1,0,0,[],""],["carrizo_salta-n1358-01",3,"¿Qué haré yo, vidita mía,\nSi me negais compasión?\nYa que tanto te quería\nLastimáis mi corazón.",3,1,0,45,"",1,4,"o",31,0,-1,0,451,451,"1358","",0,"","","",1,0,0,[],""],["carrizo_salta-n1359-01",3,"Quéjate si sos quejosa,\nYo no te doy ocasión,\nVos te quejás porque quieres,\nYo me quejo con razón.",3,1,0,45,"",0,4,"o",31,0,-1,0,451,451,"1359","",0,"","","",1,0,0,[],""],["carrizo_salta-n1360-01",3,"Que mi amor te empalagaba,\nTu me lo distes a comprender,\nLa culpa tú la tuvistes,\nQue me enseñastes así a querer.",3,1,0,45,"",3,4,"e",20,0,-1,0,451,451,"1360","",0,"","","",1,0,0,[],""],["carrizo_salta-n1361-01",3,"¿Qué no me sabías decir\nQue solita sabías ser?\nMe habías sabido engañar,\nPara hacerme padecer.",3,1,0,45,"",0,4,"e",20,0,-1,0,451,451,"1361","",0,"","","",1,0,0,[],""],["carrizo_salta-n1362-01",3,"La yerba buena se cría,\nEn la corriente del agua,\n¿Para qué t' hi querer hoy,\nSi me has de olvidar mañana?",3,1,0,45,"",0,4,"aa",-1,0,-1,0,451,451,"1362","",0,"","","",2,0,0,[],""],["carrizo_salta-n1363-01",3,"Les pido que consideren,\nLo que vale esta mujer,\nLe entregué mi fino amor,\nNo sabe corresponder.",3,1,0,45,"",0,4,"e",20,0,-1,0,451,451,"1363","",0,"","","",1,0,0,[],""],["carrizo_salta-n1364-01",3,"Lo que con mi amor has hecho,\nCon otro lo has de pagar,\nPorque te ha de hacer sentir,\nSin haber necesidad.",3,1,0,45,"",0,4,"a",-1,0,-1,0,451,451,"1364","",0,"","","",1,0,0,[],""],["carrizo_salta-n1365-01",3,"Lo que has hecho con la mano,\nLo borrastes con el codo,\n¿Esto es lo que yo merezco?\n¿Desprecios y malos modos?",3,1,0,45,"",0,4,"oo",-1,0,-1,0,451,451,"1365","",0,"","","",1,0,0,[],""],["carrizo_salta-n1366-01",3,"Los pesares de mi vida,\nTodos los puedo sufrir.\nSi me prometís amarme,\nY no olvidarte de mí.",3,1,0,45,"",0,4,"i",-1,0,-1,0,451,451,"1366","",0,"","","",1,0,0,[],""],["carrizo_salta-n1367-01",3,"¿Qué no querís que te cuente,\nLa mano que me ha pasao?\nPrenda que he querido tanto,\nCon vilezas me ha pagao.",3,1,0,45,"",0,4,"ao",-1,0,-1,0,451,451,"1367","",0,"","","",1,0,0,[],""],["carrizo_salta-n1368-01",3,"¿Qué puñal te puse al pecho,\nQué amenazas te hice yo?\n¿Chanzas te parecería?\nChanzas con el amor, no.",3,1,0,45,"",0,4,"o",2,0,-1,0,451,451,"1368","",0,"","","",1,0,0,[],""],["carrizo_salta-n1369-01",3,"¿Querís niña que te diga\nLa pura verdad?\nMucho tenis de bonita,\nPero más de vanidad.",3,1,0,45,"",0,4,"a",16,0,-1,0,451,451,"1369","",0,"","","",1,0,0,[],""],["carrizo_salta-n1370-01",3,"¿Querís que te esté teniendo\nY otro te esté manejando?\nEso no has de ver en mí\nQue ande la tipa cargando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,451,451,"1370","",0,"","","",1,0,0,[],""],["carrizo_salta-n1371-01",3,"Que se divierta mucho,\nMucho me alegra;\n¿Qué se vaya con otro?\nYa no, mi negra.",3,1,0,45,"",6,4,"ea",382,0,-1,0,452,452,"1371","",0,"","","",1,0,0,[],""],["carrizo_salta-n1372-01",3,"¡Qué viva el refrán que dice,\n\"Un bien con un mal se paga\"!\n¡Mi querida Feliciana,\nNo me haga sufrir, no me haga!",3,1,0,45,"",0,4,"aa",-1,0,-1,0,452,452,"1372","",0,"","","",1,0,0,[],""],["carrizo_salta-n1373-01",3,"¿Quién ha dicho que m'hi muerto,\nCuando perdido hi andado?\nMe han dicho que tiene dueño\nLa prenda que yo he dejado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,452,452,"1373","",0,"","","",1,0,0,[],""],["carrizo_salta-n1374-01",3,"¿Quién te ha pegado?\n¿Venís llorando?\n—Ese es el pago,\nQue me vas dando.",3,1,0,45,"",6,4,"ao",-1,0,-1,0,452,452,"1374","",0,"","","",1,0,0,[],""],["carrizo_salta-n1375-01",3,"¿Quién te ha puesto soga al cuello\nPara que me haigas querido?\n¿Por qué te parece infierno\nDespués que tu gloria ha sido?",3,1,0,45,"",0,4,"io",101,0,-1,0,452,452,"1375","",0,"","","",1,0,0,[],""],["carrizo_salta-n1376-01",3,"Quisiera que me quisieras,\nPero no lo andis contando,\nSi llega a saber la gente,\nNos han de andar reparando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,452,452,"1376","",0,"","","",2,0,0,[],""],["carrizo_salta-n1377-01",3,"Quisiera saber de cierto,\nQuién te lava y te almidona,\nQuisiera ser adivina,\nQuién va gozar tu persona.",3,1,0,45,"",0,4,"oa",7,0,-1,0,452,452,"1377","",0,"","","",1,0,0,[],""],["carrizo_salta-n1378-01",3,"Quisiera verte en mis brazos,\nMuriendo de amor por mí,\nPara que así correspondas,\nLo que yo muero por tí.",3,1,0,45,"",0,4,"i",23,0,-1,0,452,452,"1378","",0,"","","",1,0,0,[],""],["carrizo_salta-n1379-01",3,"Quizás entre sueños,\nPiensas olvidarme,\nQuizás entre sueños,\nPiensas traicionarme.",3,1,0,45,"",1,4,"ae",35,0,-1,0,452,452,"1379","",0,"","","",1,0,0,[],""],["carrizo_salta-n1380-01",3,"Sale el sol, sale la luna,\nSale el lucero de guía,\nDesde que tu me dejaste,\nTengo contados los días.",3,1,0,45,"",0,4,"ia",-1,0,-1,0,452,452,"1380","",0,"","","",3,0,0,[],""],["carrizo_salta-n1381-01",3,"Sale el sol, sale la luna,\nSale el lucero mayor,\nMi amorcito es amor firme,\nY el tuyo es amor traidor.",3,1,0,45,"",0,4,"o",72,0,-1,0,452,452,"1381","",0,"","","",3,0,0,[],""],["carrizo_salta-n1382-01",3,"¡Salí ingrata de mi pecho!\nSalí mal agradecida,\nMucho tiempo te he tenido,\nBien estimada y querida.",3,1,0,45,"",0,4,"ia",37,0,-1,0,452,452,"1382","",0,"","","",1,0,0,[],""],["carrizo_salta-n1383-01",3,"San Francisco, por humilde,\nTiene su cuerpo llagado,\nY yo tengo por tu causa,\nMi corazón traspasado.",3,1,0,45,"",0,4,"ao",14,0,-1,0,452,452,"1383","",0,"","","",3,0,0,[],""],["carrizo_salta-n1384-01",3,"Si amoroso a verte llego,\nRespondes sobresaltada:\n—Que, anda, vete, vuelve luego,\nQue ahora estoy ocupada.",3,1,0,45,"",1,4,"aa",49,0,-1,0,452,452,"1384","",0,"","","",2,0,0,[],""],["carrizo_salta-n1385-01",3,"Si canto, decís que canto,\nSi lloro que te entristezco,\nSi callo por darte gusto,\nYa decís que te aborrezco.",3,1,0,45,"",1,4,"eo",355,0,-1,0,452,452,"1385","",0,"","","",1,0,0,[],""],["carrizo_salta-n1385-a-01",3,"Si canto dices que canto,\nSi lloro que te enternezco,\nYo lo hago por darte gusto,\nY dices que te aborrezco.",3,1,0,45,"",1,4,"eo",355,0,-1,0,452,452,"1385-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1386-01",3,"Si el clavo da en parte dura,\nSe dobla al golpiarlo más,\nAsí has doblao mi paciencia,\nAl quererla machacar.",3,1,0,45,"",0,4,"a",-1,0,-1,0,453,453,"1386","",0,"","","",1,0,0,[],""],["carrizo_salta-n1387-01",3,"Si el corazón me lo pides,\nAhí lo tienes, ahí lo tienes,\nPero no le andes pagando,\nCon desdenes, con desdenes.",3,1,0,45,"",3,4,"ee",120,0,-1,0,453,453,"1387","",0,"","","",1,0,0,[],""],["carrizo_salta-n1388-01",3,"Siempre que salgo a tu encuentro,\nSufro una pena morada,\nDespués no vas a decir,\nQue yo estoy equivocada.",3,1,0,45,"",0,4,"aa",49,0,-1,0,453,453,"1388","",0,"","","",1,0,0,[],""],["carrizo_salta-n1389-01",3,"Si en un caso no me quiere,\nNo es fuerza que me aborrezca,\nSiquiera de cuando en cuando,\nTratemé como merezca.",3,1,0,45,"",0,4,"ea",346,0,-1,0,453,453,"1389","",0,"","","",2,0,0,[],""],["carrizo_salta-n1390-01",3,"Si es cierto que vos me quieres,\nSiempre constante serás,\n¡Dios nos libre de la vieja!\nSi nos comienza a insultar.",3,1,0,45,"",0,4,"a",-1,0,-1,0,453,453,"1390","",0,"","","",1,0,0,[],""],["carrizo_salta-n1391-01",3,"Si es que ahora sos feliz,\nMientras con pasión te imploro,\nLlegarán tiempos en que,\nLlorarás como yo lloro.",3,1,0,45,"",0,4,"oo",85,0,-1,0,453,453,"1391","",0,"","","",1,0,0,[],""],["carrizo_salta-n1392-01",3,"Siete meses la he rogado,\nSiete más la rogaré,\nSi a los catorce no cede,\n¡Válgame Dios! ¿qué me haré?",3,1,0,45,"",0,4,"e",77,0,-1,0,453,453,"1392","",0,"","","",1,0,0,[],""],["carrizo_salta-n1393-01",3,"Si la muerte te amenaza,\nNo tengas pena ni susto,\nYo m' hi de morir primero,\nSi por mí pasas disgustos.",3,1,0,45,"",0,4,"uo",-1,0,-1,0,453,453,"1393","",0,"","","",1,0,0,[],""],["carrizo_salta-n1394-01",3,"Si larga fué tu tardanza,\nMás larga fué mi firmeza,\nEn fin si me pagas mal,\nEn vos queda la vileza.",3,1,0,45,"",0,4,"ea",108,0,-1,0,453,453,"1394","",0,"","","",1,0,0,[],""],["carrizo_salta-n1395-01",3,"Si me has de echar en olvido,\nMás vale dame la muerte,\nPorque para un hombre pobre,\nNo hay sacrificio más fuerte.",3,1,0,45,"",0,4,"ee",134,0,-1,0,453,453,"1395","",0,"","","",1,0,0,[],""],["carrizo_salta-n1396-01",3,"Si me has sabido querer,\n¿Por qué no me has avisado?\n¿Por qué me has dejado andar,\nEn el mundo descuidado?",3,1,0,45,"",0,4,"ao",14,0,-1,0,453,453,"1396","",0,"","","",1,0,0,[],""],["carrizo_salta-n1397-01",3,"Si me quiere, mi vidita,\nQuieramé con l'alvertencia,\nAunque me vea con otra\nSiempre me ha i tener paciencia.",3,1,0,45,"",0,4,"ea",46,0,-1,0,453,453,"1397","",0,"","","",1,0,0,[],""],["carrizo_salta-n1398-01",3,"Si me quieres, dime,\nLa pura verdad,\nPara yo quererte,\nCon seguridad.",3,1,0,45,"",0,4,"a",16,0,-1,0,453,453,"1398","",0,"","","",1,0,0,[],""],["carrizo_salta-n1399-01",3,"Si me quieres, dimeló,\nY si no, dame veneno,\nQue más prefiero la muerte,\nA verte en brazos ajenos.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,453,453,"1399","",0,"","","",17,0,0,[],""],["carrizo_salta-n1400-01",3,"Si me quieres olvidar,\nTendré pecho de marfil,\nTendré corazón de acero,\nPara no saber sentir.",3,1,0,45,"",0,4,"i",-1,0,-1,0,454,454,"1400","",0,"","","",1,0,0,[],""],["carrizo_salta-n1401-01",3,"Si me quieres ver feliz,\nNo me has de negar tu amor,\n¡Vidita, dame esperanzas,\nPorque me mata el dolor!",3,1,0,45,"",0,4,"o",72,0,-1,0,454,454,"1401","",0,"","","",1,0,0,[],""],["carrizo_salta-n1402-01",3,"Si mi destino lo quiere,\nMe resolveré a quererte,\nPero si me pagas mal,\nMe conformaré en la muerte.",3,1,0,45,"",0,4,"ee",134,0,-1,0,454,454,"1402","",0,"","","",1,0,0,[],""],["carrizo_salta-n1403-01",3,"Si otra tiene preferencia,\nY ocupa ya mi lugar,\nMe retiraré a un desierto\nPuesto que no me ha de amar.",3,1,0,45,"",0,4,"a",21,0,-1,0,454,454,"1403","",0,"","","",1,0,0,[],""],["carrizo_salta-n1404-01",3,"Si por los consejos de otro,\nTe quieres arrepentir,\nEn vano son tus intentos,\nPorque me lo has de cumplir.",3,1,0,45,"",0,4,"i",157,0,-1,0,454,454,"1404","",0,"","","",1,0,0,[],""],["carrizo_salta-n1405-01",3,"Si querís que yo te quiera,\nDos cosas has de tener:\nLa conciencia muy tranquila,\nY firme amor de mujer.",3,1,0,45,"",0,4,"e",20,0,-1,0,454,454,"1405","",0,"","","",3,0,0,[],""],["carrizo_salta-n1406-01",3,"Si supieras la verdad,\nY la tuvieras presente,\nFirme estaría en quererte,\nMi vidita, hasta la muerte.",3,1,0,45,"",0,4,"ee",134,0,-1,0,454,454,"1406","",0,"","","",1,0,0,[],""],["carrizo_salta-n1407-01",3,"Si te alcanzan mis suspiros,\nNo te vuelvas del camino,\nPorque tienes que acordarte,\nDel amor que te he tenido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,454,454,"1407","",0,"","","",1,0,0,[],""],["carrizo_salta-n1408-01",3,"Si te busco es porque te amo,\nY necesito tu amor,\nAsí es que si me desprecias,\nMe moriré de dolor.",3,1,0,45,"",0,4,"o",72,0,-1,0,454,454,"1408","",0,"","","",1,0,0,[],""],["carrizo_salta-n1409-01",3,"Si te miro, son desprecios,\nSi no te miro es enojo.\nSi no querís que te mire,\nEchame tierra en los ojos.",3,1,0,45,"",0,4,"oo",-1,0,-1,0,454,454,"1409","",0,"","","",1,0,0,[],""],["carrizo_salta-n1410-01",3,"Si te vas, los dos nos vamos,\nYo no me quiero quedar,\nPorque si te vas solito,\nProntito me has de olvidar.",3,1,0,45,"",0,4,"a",21,0,-1,0,454,454,"1410","",0,"","","",1,0,0,[],""],["carrizo_salta-n1410-a-01",3,"¡Vidita, si vos te vas,\nYo no me quiero quedar!\nPorque si la ausencia es larga,\nMe has de querer olvidar.",3,1,0,45,"",0,4,"a",21,0,-1,0,454,454,"1410-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1411-01",3,"Si vos te vas y me dejas,\nYo no me puedo quedar,\nTe pido que en la memoria,\nSiquiera me has de llevar.",3,1,0,45,"",0,4,"a",21,0,-1,0,454,454,"1411","",0,"","","",1,0,0,[],""],["carrizo_salta-n1412-01",3,"Si vos te vas yo me voy,\nYo no me quiero quedar,\nSi te vas más adelante,\nSiguiendo t'hi de alcanzar.",3,1,0,45,"",0,4,"a",21,0,-1,0,454,454,"1412","",0,"","","",1,0,0,[],""],["carrizo_salta-n1413-01",3,"Si yo tuviera valor,\n¡Con qué gusto te matara!\nCuando pienso que otros labios\nPueden tocar esa cara.",3,1,0,45,"",0,4,"aa",57,0,-1,0,454,454,"1413","",0,"","","",1,0,0,[],""],["carrizo_salta-n1414-01",3,"Sólo basta que me mires,\nPara poder ser feliz.\nPero cuando te atropello,\nTe escapas como perdiz.",3,1,0,45,"",0,4,"i",335,0,-1,0,454,454,"1414","",0,"","","",1,0,0,[],""],["carrizo_salta-n1415-01",3,"Sólo quisiera tener,\nLa suerte del poderoso,\nPara no ser desgraciado,\nConsiderarme dichoso.",3,1,0,45,"",0,4,"oo",160,0,-1,0,455,455,"1415","",0,"","","",1,0,0,[],""],["carrizo_salta-n1416-01",3,"Soy despreciada en el mundo,\nHecha para padecer.\nMás vale que me muriera,\nAsí nunca me has de ver.",3,1,0,45,"",0,4,"e",20,0,-1,0,455,455,"1416","",0,"","","",1,0,0,[],""],["carrizo_salta-n1417-01",3,"Soy una niña argentina\nSoy nacida en \"La Frontera\"\nDecís que me querís mucho\nY andás queriendo a cualquiera.",3,1,0,45,"",0,4,"ea",44,0,-1,0,455,455,"1417","",0,"","","",1,0,0,[],""],["carrizo_salta-n1418-01",3,"Tarde la noche a deshora,\nAl ocultarse mi llanto,\nHallarás quien te merezca\nMás no quien te quiera tanto.",3,1,0,45,"",0,4,"ao",30,0,-1,0,455,455,"1418","",0,"","","",2,0,0,[],""],["carrizo_salta-n1419-01",3,"Tengo una linda rosa,\nY un verde alhelí,\nAunque te quieran otros\nNunca te olvides de mí.",3,1,0,45,"",0,4,"i",23,0,-1,0,455,455,"1419","",0,"","","",1,0,0,[],""],["carrizo_salta-n1420-01",3,"Tengo un canal en mi pecho,\nDe tanto llorar por tí,\nVos me miras pa decir\nY no te dueles de mí.",3,1,0,45,"",0,4,"i",-1,0,-1,0,455,455,"1420","",0,"","","",1,0,0,[],""],["carrizo_salta-n1421-01",3,"Tengo yo mi corazón,\nMás oscuro que el tintero,\nDe ver que no puedo hablarte,\nTodas las veces que quiero.",3,1,0,45,"",0,4,"eo",38,0,-1,0,455,455,"1421","",0,"","","",14,0,0,[],""],["carrizo_salta-n1422-01",3,"Toda la noche en tu cama,\nFuí la guarda de tu sueño,\nY ahora a tu gusto durmiendo,\nEn los brazos de otro dueño.",3,1,0,45,"",3,4,"eo",-1,0,-1,0,455,455,"1422","",0,"","","",1,0,0,[],""],["carrizo_salta-n1423-01",3,"Toda la noche me paso,\nPensando e imaginando,\nSin saber si serís firme\nO me tendrás engañando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,455,455,"1423","",0,"","","",1,0,0,[],""],["carrizo_salta-n1424-01",3,"Todo el corazón te dí,\nNo como vos la mitad.\nDispone como te plazca\nCon toda tu libertad.",3,1,0,45,"",0,4,"a",16,0,-1,0,455,455,"1424","",0,"","","",1,0,0,[],""],["carrizo_salta-n1425-01",3,"Todo el que sabe querer,\nHa sufrido algún quebranto,\n¡Vidita, si me querís,\nNo me hagas padecer tanto!",3,1,0,45,"",0,4,"ao",30,0,-1,0,455,455,"1425","",0,"","","",1,0,0,[],""],["carrizo_salta-n1426-01",3,"Tomá la pluma en las manos\nAquí te traigo papel,\nPoné tu nombre y el mío,\nFirmá si sabís querer.",3,1,0,45,"",0,4,"e",-1,0,-1,0,455,455,"1426","",0,"","","",1,0,0,[],""],["carrizo_salta-n1427-01",3,"Tomá la pluma ligero,\nEscribime sin tardanza,\nAunque vos me pagues mal\nEn mí no ha de hallar mudanza.",3,1,0,45,"",0,4,"aa",163,0,-1,0,455,455,"1427","",0,"","","",1,0,0,[],""],["carrizo_salta-n1428-01",3,"Tormentos son los que paso,\nEn sólo considerar,\nQue por tí vivo penando\nSin tenerme voluntad.",3,1,0,45,"",0,4,"a",-1,0,-1,0,455,455,"1428","",0,"","","",1,0,0,[],""],["carrizo_salta-n1429-01",3,"Traicionera nunca he sido,\nPa traicionar a un amigo,\nAverigua como quieras,\nY te verás convencido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,455,455,"1429","",0,"","","",1,0,0,[],""],["carrizo_salta-n1430-01",3,"Tres veces mudo quedaste,\nMudo sin poder hablar,\nPara decir lo que sientes\nMuy mucho no has de pensar.",3,1,0,45,"",0,4,"a",21,0,-1,0,455,455,"1430","",0,"","","",1,0,0,[],""],["carrizo_salta-n1431-01",3,"Triste es la suerte del ciego,\nQue no vé por donde vá,\nPero mayor es la mía,\nNo veo tu voluntad.",3,1,0,45,"",0,4,"a",-1,0,-1,0,456,456,"1431","",0,"","","",1,0,0,[],""],["carrizo_salta-n1432-01",3,"Triste me pilla la tarde,\nY la noche imaginando,\nSin saber si Ud. me quiere,\nO si me tendrá engañando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,456,456,"1432","",0,"","","",1,0,0,[],""],["carrizo_salta-n1433-01",3,"Tu me das esperanzas,\nY no me dices,\nEl día que mis ansias,\nSerán felices.",3,1,0,45,"",6,4,"ie",113,0,-1,0,456,456,"1433","",0,"","","",4,0,0,[],""],["carrizo_salta-n1434-01",3,"Tu nombre escribí en l'arena,\nPor ver si se conservaba,\nY conforme iba escribiendo,\nEl viento se lo llevaba.",3,1,0,45,"",0,4,"aa",28,0,-1,0,456,456,"1434","",0,"","","",1,0,0,[],""],["carrizo_salta-n1435-01",3,"Una bella palomita,\nQue con trabajo busqué,\nPor adorar a otro dueño,\nTriste me dejó y se fué",3,1,0,45,"",0,4,"e",77,0,-1,0,456,456,"1435","",0,"","","",1,0,0,[],""],["carrizo_salta-n1436-01",3,"Una gotera continua\nAblanda un duro peñón,\nY con mis dulces suspiros,\nNo ablando tu corazón.",3,1,0,45,"",0,4,"o",31,0,-1,0,456,456,"1436","",0,"","","",6,0,0,[],""],["carrizo_salta-n1437-01",3,"Un amor que no es amor,\nUn querer que no es querer,\n¿Qué será? pregunto yo,\nEl amor de una mujer.",3,1,0,45,"",0,4,"e",20,0,-1,0,456,456,"1437","",0,"","","",1,0,0,[],""],["carrizo_salta-n1438-01",3,"Una pierna tengo aquí,\nOtra tengo en el bañao,\nAsí me tiene tu amor,\nTodo descuajeringao.",3,1,0,45,"",0,4,"ao",98,0,-1,0,456,456,"1438","",0,"","","",1,0,0,[],""],["carrizo_salta-n1439-01",3,"Una vez por darme celos,\nTe buscastes otro amor,\nDejándome el alma en pena,\nY herido mi corazón.",3,1,0,45,"",0,4,"o",-1,0,-1,0,456,456,"1439","",0,"","","",1,0,0,[],""],["carrizo_salta-n1440-01",3,"Un gallo estaba cantando,\nEn la rama de un olivo,\nY entre sus cantos decía:\n—Si me olvida, yo la olvido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,456,456,"1440","",0,"","","",1,0,0,[],""],["carrizo_salta-n1441-01",3,"Usted no ha sio la primera,\nQue me ofreció el corazón,\nMuchos prometen y dicen,\nPero capaces no son.",3,1,0,45,"",0,4,"o",31,0,-1,0,456,456,"1441","",0,"","","",1,0,0,[],""],["carrizo_salta-n1442-01",3,"¡Vas a saber, traidorita,\nCómo se trata al amor!\nSi algún otro te promete\nLo que te prometo yo.",3,1,0,45,"",0,4,"o",-1,0,-1,0,456,456,"1442","",0,"","","",1,0,0,[],""],["carrizo_salta-n1443-01",3,"Verde verdecito,\nVerde verdonal,\nAvisame, vida mía,\n¿Quién te enseñó a pagar mal?",3,1,0,45,"",0,4,"a",1,0,-1,0,456,456,"1443","",0,"","","",1,0,0,[],""],["carrizo_salta-n1444-01",3,"Vidita, si me querís\nNo me hagas ningún desaire,\nMira que en el mundo andamos,\nComo paja por el aire.",3,1,0,45,"",0,4,"ae",411,0,-1,0,456,456,"1444","",0,"","","",10,0,0,[],""],["carrizo_salta-n1445-01",3,"Vidita, si me querís,\nNo seas de mal proceder,\nYo te he de sacar pa fuera\nTe he de enseñar a querer.",3,1,0,45,"",0,4,"e",20,0,-1,0,457,457,"1445","",0,"","","",10,0,0,[],""],["carrizo_salta-n1446-01",3,"Vidita, si no me quiere,\nCon dejarme se acabó,\nAsí no pasas trabajos,\nNi yo los paso por vos.",3,1,0,45,"",0,4,"o",-1,0,-1,0,457,457,"1446","",0,"","","",1,0,0,[],""],["carrizo_salta-n1447-01",3,"Vinistes para mi casa,\nDiciendo que me querías,\nY solito me dejaste,\nComo la una del día.",3,1,0,45,"",0,4,"ia",-1,0,-1,0,457,457,"1447","",0,"","","",1,0,0,[],""],["carrizo_salta-n1449-01",3,"Vos con toditos bailas,\nMenos conmigo,\nYo solito había sido,\nTu aborrecido.",3,1,0,45,"",6,4,"io",101,0,-1,0,457,457,"1449","",0,"","","",1,0,0,[],""],["carrizo_salta-n1450-01",3,"Vos dejastes mi cariño,\nPor querer seguir tu rumbo,\n¡Andá, que pronto verás,\nEl pago que te da el mundo!",3,1,0,45,"",0,4,"uo",-1,0,-1,0,457,457,"1450","",0,"","","",1,0,0,[],""],["carrizo_salta-n1451-01",3,"Vos me quieres, yo te quiero,\nAmbos los dos nos queremos,\n¿Qué hacís que no nos gozamos?\n¿Por qué es lo que padecemos?",3,1,0,45,"",0,4,"eo",127,0,-1,0,457,457,"1451","",0,"","","",1,0,0,[],""],["carrizo_salta-n1452-01",3,"Vos, negrita, me has dejado,\nSin que yo te dé motivo,\nYo también t'hi de dejar,\nEn las sombras del olvido.",3,1,0,45,"",0,4,"io",-1,0,-1,0,457,457,"1452","",0,"","","",1,0,0,[],""],["carrizo_salta-n1453-01",3,"Voy a dejar de querer,\nVoy a dejar mi pasión,\nAl fin pude comprender,\nQue es falso tu corazón.",3,1,0,45,"",1,4,"o",31,0,-1,0,457,457,"1453","",0,"","","",2,0,0,[],""],["carrizo_salta-n1454-01",3,"Ya habrás tunado a tu gusto,\nAgora,ya no hay soltura,\n¿Para que me hacís llorar\nCorazón de piedra dura?",3,1,0,45,"",0,4,"ua",17,0,-1,0,457,457,"1454","",0,"","","",1,0,0,[],""],["carrizo_salta-n1455-01",3,"Ya llega la tarde,\nLa noche lloviendo,\nNo ponga imposibles,\nSi me está queriendo.",3,1,0,45,"",0,4,"eo",52,0,-1,0,457,457,"1455","",0,"","","",1,0,0,[],""],["carrizo_salta-n1456-01",3,"Ya marchita por mi llanto,\nToma, te brindo esta flor,\nGuárdala como un recuerdo,\nDe éste que tanto te amó.",3,1,0,45,"",0,4,"o",-1,0,-1,0,457,457,"1456","",0,"","","",1,0,0,[],""],["carrizo_salta-n1457-01",3,"Ya me voy a retirar,\nVida, con harto dolor,\nYa me has cambiado con otro,\nYa no me tienes amor.",3,1,0,45,"",0,4,"o",72,0,-1,0,457,457,"1457","",0,"","","",12,0,0,[],""],["carrizo_salta-n1458-01",3,"Ya no sé como decirle,\nPa que entienda mis razones,\nYa l' hi dicho que la quiero,\nRepetidas ocasiones.",3,1,0,45,"",0,4,"oe",34,0,-1,0,457,457,"1458","",0,"","","",1,0,0,[],""],["carrizo_salta-n1459-01",3,"Ya no te acuerdas de mí,\n¡Corazón de piedra dura!\nSabiendo que yo por tí,\nPaso ratos de amargura.",3,1,0,45,"",1,4,"ua",17,0,-1,0,458,458,"1459","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["carrizo_salta-n1460-01",3,"Ya no te quiero querer,\nAunque me quieras de empeño,\nDespués ya saldrás diciendo,\nQue ya tienes otro dueño.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,458,458,"1460","",0,"","","",1,0,0,[],""],["carrizo_salta-n1461-01",3,"Ya se han muerto los dichosos,\nSólo queda un desgraciado,\n¿Cuándo dejaré de ser,\nDe tu amor tan despreciado?",3,1,0,45,"",0,4,"ao",14,0,-1,0,458,458,"1461","",0,"","","",1,0,0,[],""],["carrizo_salta-n1462-01",3,"Ya sé lo que andás queriendo,\nCon tus enojos y engaños;\nQuerís que nada te diga,\nY eso has de pensar en vano.",3,1,0,45,"",0,4,"ao",-1,0,-1,0,458,458,"1462","",0,"","","",1,0,0,[],""],["carrizo_salta-n1463-01",3,"Ya te has ido, palomita,\nYa has remontado tu vuelo,\nAhora te veo otro amante,\n¡Cómo te dure ha i ser bueno!",3,1,0,45,"",0,4,"eo",-1,0,-1,0,458,458,"1463","",0,"","","",1,0,0,[],""],["carrizo_salta-n1464-01",3,"Ya t'hi visto pues ñatita,\nTenís que tener paciencia,\nYo soy muchacho soltero,\nLlorando vivo tu ausencia.",3,1,0,45,"",0,4,"ea",46,0,-1,0,458,458,"1464","",0,"","","",1,0,0,[],""],["carrizo_salta-n1465-01",3,"Yo digo que no,\nYo digo que si,\nTus ojos morenos,\nSe burlan de mí.",3,1,0,45,"",0,4,"i",23,0,-1,0,458,458,"1465","",0,"","","",1,0,0,[],""],["carrizo_salta-n1466-01",3,"Yo me voy a retirar\nPorque me han pagado mal,\nYo no les seré molesto,\nNo los ofenderé más.",3,1,0,45,"",0,4,"a",-1,0,-1,0,458,458,"1466","",0,"","","",1,0,0,[],""],["carrizo_salta-n1467-01",3,"Yo no me voy a la banda,\nNi chanciando ni dudando,\nEl desprecio que me has hecho,\nTodavía me anda durando.",3,1,0,45,"",0,4,"ao",33,0,-1,0,458,458,"1467","",0,"","","",1,0,0,[],""],["carrizo_salta-n1468-01",3,"Yo no quiero a cualesquiera\nPorque soy muy receloso,\nPrimero hi de medir bien\nEse semejante pozo.",3,1,0,45,"",0,4,"oo",156,0,-1,0,458,458,"1468","",0,"","","",1,0,0,[],""],["carrizo_salta-n1469-01",3,"Yo no sé por qué motivo,\nMi vida, me abandonó,\nYo no tuve más delito\nQue quererla y me olvidó.",3,1,0,45,"",0,4,"o",2,0,-1,0,458,458,"1469","",0,"","","",5,0,0,[],""],["carrizo_salta-n1470-01",3,"Yo no sé qué mal l'hi hecho\n¿Qué cristales hi quebrao\nQue amargan tanto mi vida?\n¿Qué caudales hi abarcao?",3,1,0,45,"",0,4,"ao",98,0,-1,0,458,458,"1470","",0,"","","",1,0,0,[],""],["carrizo_salta-n1471-01",3,"Yo no siento gastar plata,\nEn prenda de fundamento,\nSólo lo que siento yo,\nSon los malos pagamientos.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,458,458,"1471","",0,"","","",1,0,0,[],""],["carrizo_salta-n1472-01",3,"Yo no siento la cautela,\nNi la traición que me has hecho,\nSólo siento haberte criado,\nEn el centro de mi pecho.",3,1,0,45,"",0,4,"eo",60,0,-1,0,458,458,"1472","",0,"","","",2,0,0,[],""],["carrizo_salta-n1473-01",3,"Yo no siento que me coma,\nEl tigre más inhumano,\nSólo siento que mi prenda,\nSe ande de mano en mano.",3,1,0,45,"",0,4,"ao",81,0,-1,0,458,458,"1473","",0,"","","",1,0,0,[],""],["carrizo_salta-n1474-01",3,"Yo no soy ni más ni menos,\nNo soy ni menos ni más,\nYo no andoy porque me quieran,\nSino que me andoy nomás.",3,1,0,45,"",0,4,"a",51,0,-1,0,458,458,"1474","",0,"","","",1,0,0,[],""],["carrizo_salta-n1475-01",3,"Yo no te diré mi nombre,\nNi tampoco mi apellido,\nPara verte y no gozarte,\nMás vale no haber nacido.",3,1,0,45,"",0,4,"io",101,0,-1,0,459,459,"1475","",0,"","","",1,0,0,[],""],["carrizo_salta-n1476-01",3,"Yo no te quise querer,\nVos has sido del empeño,\nTanto que me asegurabas,\nVos has faltado primero.",3,1,0,45,"",0,4,"eo",-1,0,-1,0,459,459,"1476","",0,"","","",1,0,0,[],""],["carrizo_salta-n1477-01",3,"Yo quiero a una ingrata y bella,\nSabiendo que yo la adoro,\nDos tantos más que a mi vida,\nSe hace la desentendida.",3,1,0,45,"",5,4,"ia",37,0,-1,0,459,459,"1477","",0,"","","",1,0,0,[],""],["carrizo_salta-n1478-01",3,"Yo siempre te había querido,\nCon toda mi voluntad,\nDetesté la falsedad,\nY nunca te eché en olvido.",3,1,0,45,"",11,4,"io",101,0,-1,0,459,459,"1478","",0,"","","",1,0,0,[],""],["carrizo_salta-n1479-01",3,"Yo siento pero no lloro,\nCarezco pero no busco,\n¿Cuándo me verás salir\nPara que queden a gusto?",3,1,0,45,"",0,4,"uo",-1,0,-1,0,459,459,"1479","",0,"","","",1,0,0,[],""],["carrizo_salta-n1480-01",3,"Yo soy el malo del mundo,\nYo soy el ofendedor,\nQuiero que me justifiquen,\nEn que los ofiendo yo.",3,1,0,45,"",0,4,"o",-1,0,-1,0,459,459,"1480","",0,"","","",1,0,0,[],""],["carrizo_salta-n1481-01",3,"Yo soy esa pobre moza\nArenita de la playa,\nSi no le sirvo de nada,\nDespachené que me vaya.",3,1,0,45,"",0,4,"aa",-1,0,-1,0,459,459,"1481","",0,"","","",2,0,0,[],""],["carrizo_salta-n1482-01",3,"Yo soy pampeñito\nMe sé divertir,\n¿Qué tanto se le hace\nQue no sé sentir?",3,1,0,45,"",0,4,"i",157,0,-1,0,459,459,"1482","",0,"","","",1,0,0,[],""],["carrizo_salta-n1483-01",3,"Yo tan sólo me contento\nCuando te veo llorar,\nQue la ofensa que me hiciste\nNo te puedo perdonar.",3,1,0,45,"",0,4,"a",21,0,-1,0,459,459,"1483","",0,"","","",1,0,0,[],""],["carrizo_salta-n1484-01",3,"Yo te amé porque creí,\nQue también me amabas tú,\n¡Dulce aroma de mi vida!\nNo soñé tu ingratitud.",3,1,0,45,"",0,4,"u",-1,0,-1,0,459,459,"1484","",0,"","","",1,0,0,[],""],["carrizo_salta-n1485-01",3,"Yo te dí mi corazón\nY hoy al ver que me mentistes,\nQuedó mi corazón triste,\nY aplastada mi ilusión.",3,1,0,45,"",5,4,"o",31,0,-1,0,459,459,"1485","",0,"","","",1,0,0,[],""],["carrizo_salta-n1486-01",3,"Yo te presento esta flor\nMatizada con azahar,\nAhora me has de decir:\n¿Con quién te vais a casar?",3,1,0,45,"",0,4,"a",21,0,-1,0,459,459,"1486","",0,"","","",1,0,0,[],""],["carrizo_salta-n1487-01",3,"Yo te quiero a vos solita,\nY vos querís a un montón\n¿Por qué querís repicar\nY andar en la procesión?",3,1,0,45,"",0,4,"o",31,0,-1,0,459,459,"1487","",0,"","","",1,0,0,[],""],["carrizo_salta-n1488-01",3,"Yo te quiero, vida mía,\nSin adulación ninguna,\nSi ahora no me querís,\nSerá mi mala fortuna.",3,1,0,45,"",0,4,"ua",56,0,-1,0,459,459,"1488","",0,"","","",1,0,0,[],""],["carrizo_salta-n1489-01",3,"Yo te quisiera querer,\nPero no me determino,\nPorque me vas a dejar,\nAl trote como el zorrino.",3,1,0,45,"",0,4,"io",199,0,-1,0,459,459,"1489","",0,"","","",8,0,0,[],""],["carrizo_salta-n1490-01",3,"Yo te quisiera querer,\nPero tengo desconfianza,\nDe que seas como luna,\nCada mes tengas mudanza.",3,1,0,45,"",0,4,"aa",163,0,-1,0,459,459,"1490","",0,"","","",8,0,0,[],""],["carrizo_salta-n1491-01",3,"Yo te vu'a dar, mi vidita,\nPlatita y buena montura,\nDespués no vuelvas llorando\nAl pie de mi sepultura.",3,1,0,45,"",0,4,"ua",17,0,-1,0,459,459,"1491","",0,"","","",1,0,0,[],""],["carrizo_salta-n1495-01",3,"Adiós, clavel encarnado!\nAdiós, clavel de mi suerte!\nSi me matas con tu ausencia\nTambién me matas al verte.",3,1,0,46,"",0,4,"ee",134,0,-1,0,461,461,"1495","",0,"","","",1,0,0,[],""],["carrizo_salta-n1496-01",3,"Adiós, espejo sin mancha!\nAdiós, luna sin menguante!\nAdiós, vida de mi vida!\nAdiós, vorazón amante!",3,1,0,46,"",0,4,"ae",47,0,-1,0,461,461,"1496","",0,"","","",1,0,0,[],""],["carrizo_salta-n1499-01",3,"Adiós fragante azucena!\nAdiós, clavel encarnado!\nAdiós, vida de mis ojos!\nAdiós, corazón amado!",3,1,0,46,"",0,4,"ao",14,0,-1,0,461,461,"1499","",0,"","","",1,0,0,[],""],["carrizo_salta-n1500-01",3,"¡Adiós, lucero brillante!\nQue ya me voy y te dejo,\nSólo con las esperanzas\nDe volverte a ver, me alejo.",3,1,0,46,"",0,4,"eo",264,0,-1,0,461,461,"1500","",0,"","","",1,0,0,[],""],["carrizo_salta-n1501-01",3,"¡Adiós, madre y adiós, padre!\n¡Adiós, todos mis hermanos!\nYa me llevan a la cárcel,\nAtado de pies y manos.",3,1,0,46,"",0,4,"ao",318,0,-1,0,461,461,"1501","",0,"","","",1,0,0,[],""],["carrizo_salta-n1502-01",3,"¡Adiós, mi negra!\n¡Adiós, adiós!\nTalvez que vuelva,\nTalvez que no.",3,1,0,46,"",6,4,"o",-1,0,-1,0,461,461,"1502","",0,"","","",1,0,0,[],""],["carrizo_salta-n1503-01",3,"¡Adiós, mi prenda querida!\n¡Adiós, mi fina pasión!\n¡Adiós, todo mi consuelo!\nDueña de mi corazón.",3,1,0,46,"",0,4,"o",31,0,-1,0,461,461,"1503","",0,"","","",2,0,0,[],""],["carrizo_salta-n1504-01",3,"¡Adiós, palomita!\n¡Adiós! ¿hasta cuándo?\nSi querís querer, quereme,\nNo me tengais engañando.",3,1,0,46,"",0,4,"ao",33,0,-1,0,461,461,"1504","",0,"","","",2,0,0,[],""],["carrizo_salta-n1506-01",3,"¡Adiós, prenda de mi alma!\n¡Adiós, prenda! ¿Cómo está?\nMe alegro de verla sana,\nSin ninguna novedad.",3,1,0,46,"",0,4,"a",-1,0,-1,0,461,461,"1506","",0,"","","",1,0,0,[],""],["carrizo_salta-n1507-01",3,"¡Adiós, prenda de mi vida!\nYa no te verán mis ojos,\nDejarás de aborrecerme,\nSe acabarán tus enojos.",3,1,0,46,"",0,4,"oo",99,0,-1,0,461,461,"1507","",0,"","","",2,0,0,[],""],["carrizo_salta-n1524-01",3,"Amor viene por los campos,\nEn el verde no parece,\nElla es soltera y bonita,\nPorque ella quiere padece",3,1,0,46,"",0,4,"ee",64,0,-1,0,462,462,"1524","",0,"","","",1,0,0,[],""],["carrizo_salta-n1525-01",3,"Anda, dile pajarillo,\nA quién causa mis tormentos,\nQue llorando estoy su ausencia,\nPor horas y por momentos.",3,1,0,46,"",0,4,"eo",234,0,-1,0,462,462,"1525","",0,"","","",1,0,0,[],""],["carrizo_salta-n1526-01",3,"Andate papel volando,\nA donde está mi querida,\nSi te pregunta si lloro,\nDile que todos los días.",3,1,0,46,"",0,4,"ia",-1,0,-1,0,462,462,"1526","",0,"","","",4,0,0,[],""],["carrizo_salta-n1526-02",3,"Andate papel volando,\nDonde está la prenda mía,\nDile que por ella lloro,\nToda la noche y el día.",3,1,0,46,"",0,4,"ia",0,0,-1,0,462,462,"1526","",0,"","","",4,0,0,[],""],["carrizo_salta-n1527-01",3,"Andate papel volando,\nA las manos que te mando,\nSi te tratan con desprecio,\nVolvete papel llorando.",3,1,0,46,"",0,4,"ao",33,0,-1,0,462,462,"1527","",0,"","","",4,0,0,[],""],["carrizo_salta-n1528-01",3,"Andate papel volando,\nVolá sin intermisión,\nDe aquel corazón ingrato,\nTraéme contestación.",3,1,0,46,"",0,4,"o",31,0,-1,0,462,462,"1528","",0,"","","",4,0,0,[],""],["carrizo_salta-n1529-01",3,"¿Ande estará, mi vidita?\n¿Si se acordará de mí?\n¿Si me tendrá en la memoria,\nComo yo la tengo aquí?",3,1,0,46,"",0,4,"i",23,0,-1,0,462,462,"1529","",0,"","","",1,0,0,[],""],["carrizo_salta-n1530-01",3,"Antes, cuando yo era moza,\nVestía como parina,\nAhora que ya soy vieja,\nParezco bolsa de harina.",3,1,0,46,"",0,4,"ia",11,0,-1,0,462,462,"1530","",0,"","","",4,0,0,[],""],["carrizo_salta-n1530-a-01",3,"Antes, cuando yo era moza,\nEra como la parina,\nAhora que ya soy vieja,\nSoy como costal de harina.",3,1,0,46,"",0,4,"ia",11,0,-1,0,462,462,"1530-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n1531-01",3,"Antes, cuando yo era moza,\nMe andaba de cara buena,\nDe orégano eran los campos,\nY los montes yerba buena.",3,1,0,46,"",0,4,"ea",-1,0,-1,0,462,462,"1531","",0,"","","",4,0,0,[],""],["carrizo_salta-n1532-01",3,"Antes, cuando yo era moza,\nMe salía a retozar,\nAhora, que ya soy vieja,\nYa no puedo ni trotar.",3,1,0,46,"",0,4,"a",21,0,-1,0,462,462,"1532","",0,"","","",4,0,0,[],""],["carrizo_salta-n1533-01",3,"Antes, cuando yo era mozo,\nUsaba mi freno i copa,\nAgora que ya soy viejo,\nApenas mi chuspa y coca.",3,1,0,46,"",0,4,"oa",-1,0,-1,0,462,462,"1533","",0,"","","",4,0,0,[],""],["carrizo_salta-n1533-a-01",3,"Antes, cuando yo era mozo,\nUsaba mi freno i copa,\nAgora que ya soy viejo,\nTrajino la chuspa i coca.",3,1,0,46,"",0,4,"oa",-1,0,-1,0,462,462,"1533-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n1534-01",3,"A orillas del mar me fuí,\nY me senté en la ribera,\nMe puse a considerar,\n¡Si esta rubia me quisiera!",3,1,0,46,"",0,4,"ea",44,0,-1,0,462,462,"1534","",0,"","","",3,0,0,[],""],["carrizo_salta-n1535-01",3,"Aquí estoy hecho un congojo,\nMi cara está por los suelos,\nCuando no la puedo ver,\nCon nombrarla me consuelo.",3,1,0,46,"",0,4,"eo",-1,0,-1,0,463,463,"1535","",0,"","","",1,0,0,[],""],["carrizo_salta-n1536-01",3,"Aquí hi venido, vidita,\nA darte el último adiós,\nLlorando gotas de sangre,\nAl ver mi separación.",3,1,0,46,"",0,4,"o",-1,0,-1,0,463,463,"1536","",0,"","","",1,0,0,[],""],["carrizo_salta-n1537-01",3,"A una flor que yo vide,\nNo la dejo de mirar,\nMi alma se va por ella,\nY yo no me atrevo hablar.",3,1,0,46,"",0,4,"a",21,0,-1,0,463,463,"1537","",0,"","","",1,0,0,[],""],["carrizo_salta-n1538-01",3,"Ausente estoy de tu vista,\nPero no del pensamiento,\nTe quiero tanto, alma mía,\nSuspiro a cada momento.",3,1,0,46,"",0,4,"eo",94,0,-1,0,463,463,"1538","",0,"","","",7,0,0,[],""],["carrizo_salta-n1539-01",3,"¡Ay, esperanza!\n¡Ay, esperanza!\nYa viene el día,\nY el sol me alcanza.",3,1,0,46,"",6,4,"aa",163,0,-1,0,463,463,"1539","",0,"","","",1,0,0,[],""],["carrizo_salta-n1539-01-e2",3,"Ayer le mandé una carta,\nCon letras de amor constante,\nHaciéndole preguntar,\nSi me quería por su amante.",3,1,0,46,"",0,4,"ae",47,0,-1,0,463,463,"1539","",0,"","","",1,0,0,[],""],["carrizo_salta-n1540-01",3,"Ayer le mandé un brillante,\nCon letras de amor constante,\nHoy le mando a preguntar,\nSi me quería por su amante.",3,1,0,46,"",0,4,"ae",47,0,-1,0,463,463,"1540","",0,"","","",1,0,0,[],""],["carrizo_salta-n1541-01",3,"¡Ay, hijo! dijo mi madre:\nEl día que yo me muera,\nTe han de mirar los parientes,\nComo si un extraño fueras.",3,1,0,46,"",0,4,"ea",-1,0,-1,0,463,463,"1541","",0,"","","",2,0,0,[],""],["carrizo_salta-n1542-01",3,"¡Ay, mi vida, que anda ausente!\n¡Qué vida estará pasando!\n¿Quién me la tendrá en los brazos?\n¿Quién me la estará gozando?",3,1,0,46,"",0,4,"ao",-1,0,-1,0,463,463,"1542","",0,"","","",1,0,0,[],""],["carrizo_salta-n1543-01",3,"Cantaré mi despedida,\nAunque con harto dolor,\nPorque ningún despedido,\nLleva alegre el corazón.",3,1,0,46,"",0,4,"o",-1,0,-1,0,463,463,"1543","",0,"","","",2,0,0,[],""],["carrizo_salta-n1544-01",3,"Casa vieja,\nLlavi i tiento,\n¿Cuál será, vidita mía,\nCuál será su pensamiento?",3,1,0,46,"",3,4,"eo",94,0,-1,0,463,463,"1544","",0,"","","",1,0,0,[],""],["carrizo_salta-n1544-a-01",3,"Quincha i cuero,\nLlavi i tiento,\n¿Cuál será, vidita mía,\nCuál será su pensamiento?",3,1,0,46,"",3,4,"eo",94,0,-1,0,463,463,"1544-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1545-01",3,"¡Caramba, que ha dicho lindo,\nComo para hacer llorar!\nMe acuerdo de mi vidita,\nQue no me sabía olvidar.",3,1,0,46,"",0,4,"a",21,0,-1,0,464,464,"1545","",0,"","","",1,0,0,[],""],["carrizo_salta-n1545-02",3,"Cuando me fui a Cafayate,\nDe tí yo me fui acordando,\nAunque no continuamente,\nSiquiera de cuando en cuando.",3,1,0,46,"",0,4,"ao",33,0,-1,0,464,464,"1545","",0,"","","",1,0,0,[],""],["carrizo_salta-n1548-01",3,"Dame la mano, vidita,\nDame la mano y adiós,\nSi te duele el corazón,\nAprontate vamonós.",3,1,0,46,"",0,4,"o",-1,0,-1,0,464,464,"1548","",0,"","","",3,0,0,[],""],["carrizo_salta-n1548-02",3,"Daré vuelta a mi caballo,\nMe sentaré a descansar,\n¡Adiós, parientes y hermanos!\nYa no me oyerán cantar.",3,1,0,46,"",0,4,"a",21,0,-1,0,464,464,"1548","",0,"","","",1,0,0,[],""],["carrizo_salta-n1548-03",3,"Daré vuelta mi caballo,\nY comenzaré a marchar,\n¡Adiós, parientes y hermanos!\nQue ya me voy a ausentar.",3,1,0,46,"",0,4,"a",21,0,-1,0,464,464,"1548","",0,"","","",1,0,0,[],""],["carrizo_salta-n1550-01",3,"Decís que te vas,\n¿Cuándo volverás?\nLlorarán mis ojos,\nHasta que vuelvás.",3,1,0,46,"",0,4,"a",51,0,-1,0,464,464,"1550","",0,"","","",1,0,0,[],""],["carrizo_salta-n1551-01",3,"De Chile al Perú,\nDe Chile al Perú,\nQue Dios la conserve,\nCon vida y salud.",3,1,0,46,"",0,4,"u",-1,0,-1,0,464,464,"1551","",0,"","","",2,0,0,[],""],["carrizo_salta-n1552-01",3,"De San José soy,\nDe San José soy,\nHoy me despido,\nY el quince me voy.",3,1,0,46,"",3,4,"o",112,0,-1,0,464,464,"1552","",0,"","","",1,0,0,[],""],["carrizo_salta-n1553-01",3,"Desde que la conocí,\nMuchas veces he tenido,\nAntojos de verla sola,\nPero jamás he podido.",3,1,0,46,"",0,4,"io",101,0,-1,0,464,464,"1553","",0,"","","",1,0,0,[],""],["carrizo_salta-n1554-01",3,"De todas las niñas que hay,\nSólo una me está gustando,\n¿Cuándo llegará esa vez,\nQue la pueda estar gozando?",3,1,0,46,"",0,4,"ao",33,0,-1,0,464,464,"1554","",0,"","","",1,0,0,[],""],["carrizo_salta-n1555-01",3,"De tu boca quiero un beso,\nDe tus brazos un abrazo,\nDe tus ojos las caricias,\nY de tu amor un pedazo.",3,1,0,46,"",0,4,"ao",43,0,-1,0,464,464,"1555","",0,"","","",1,0,0,[],""],["carrizo_salta-n1556-01",3,"Echaré mi despedida,\nEsto es, porque ya nos vamos,\nAlgún día nos veremos,\nSi Dios quiere y vivo estamos.",3,1,0,46,"",0,4,"ao",116,0,-1,0,464,464,"1556","",0,"","","",1,0,0,[],""],["carrizo_salta-n1557-01",3,"El amor de las casadas,\nYo lo quisiera saber,\nPorque las casadas saben,\nCómo han de amar y querer.",3,1,0,46,"",0,4,"e",20,0,-1,0,464,464,"1557","",0,"","","",1,0,0,[],""],["carrizo_salta-n1558-01",3,"En el campo la esperanza,\nHallé un paraíso florido,\nDe otras flores no me acuerdo,\nPero de esa no me olvido.",3,1,0,46,"",0,4,"io",101,0,-1,0,464,464,"1558","",0,"","","",2,0,0,[],""],["carrizo_salta-n1559-01",3,"En esta fecha me voy,\nYa no volveré jamás,\nSoy como l'agua del río,\nNunca vuelve para atrás.",3,1,0,46,"",0,4,"a",51,0,-1,0,464,464,"1559","",0,"","","",1,0,0,[],""],["carrizo_salta-n1560-01",3,"En mis tiempos, cuando mozo,\nCuando sabía argumentar,\nCautivaba corazones,\nCuando empezaba a cantar.",3,1,0,46,"",0,4,"a",21,0,-1,0,465,465,"1560","",0,"","","",6,0,0,[],""],["carrizo_salta-n1561-01",3,"En mis tiempos, cuando mozo,\nMe comía pan y queso,\nAhora que ya soy viejo,\nYa no como nada de eso.",3,1,0,46,"",0,4,"eo",-1,0,-1,0,465,465,"1561","",0,"","","",6,0,0,[],""],["carrizo_salta-n1562-01",3,"Esta florcita te mando,\nAunque no es de mirasol,\nEsa manchita que tiene,\nEs sangre del corazón.",3,1,0,46,"",0,4,"o",-1,0,-1,0,465,465,"1562","",0,"","","",1,0,0,[],""],["carrizo_salta-n1563-01",3,"Esta va por despedida,\nY por despedida va,\nEl que quiere y no es querido,\nMuy bien despedido está.",3,1,0,46,"",0,4,"a",9,0,-1,0,465,465,"1563","",0,"","","",1,0,0,[],""],["carrizo_salta-n1564-01",3,"Hoy me separo de tí,\nParto por obligación,\nY llevo en mi corazón,\nEl no olvidarme de tí.",3,1,0,46,"",11,4,"i",-1,0,-1,0,465,465,"1564","",0,"","","",1,0,0,[],""],["carrizo_salta-n1565-01",3,"Los pichones cuando nacen,\nNacen dándose besitos,\n¿Cuándo querrá Dios del cielo,\nQue seamos pichoncitos?",3,1,0,46,"",0,4,"io",254,0,-1,0,465,465,"1565","",0,"","","",1,0,0,[],""],["carrizo_salta-n1566-01",3,"Lleva jilguero costante,\nEn tu pico este papel,\nPara que pueda mi amante,\nPasar la vista por él.",3,1,0,46,"",1,4,"e",32,0,-1,0,465,465,"1566","",0,"","","",1,0,0,[],""],["carrizo_salta-n1567-01",3,"Mañana me voy,\nNo voy a llorar,\nHoy me despido,\nLa dejo de amar.",3,1,0,46,"",6,4,"a",21,0,-1,0,465,465,"1567","",0,"","","",6,0,0,[],""],["carrizo_salta-n1568-01",3,"Me mira y se va,\nTal vez volverá,\nAhora no hay cómo,\nPa'l año será.",3,1,0,46,"",0,4,"a",9,0,-1,0,465,465,"1568","",0,"","","",1,0,0,[],""],["carrizo_salta-n1569-01",3,"Mensajeras de alegría,\nSon las flores que te envío,\nEn vez de llevar fragancia,\nLlevan el cariño mío.",3,1,0,46,"",0,4,"io",3,0,-1,0,465,465,"1569","",0,"","","",1,0,0,[],""],["carrizo_salta-n1570-01",3,"Mi destino, ¡qué dolor!\nMe obliga a dejarte ya,\nMás, mi alma con vos queda,\nY mi cuerpo sólo va.",3,1,0,46,"",0,4,"a",9,0,-1,0,465,465,"1570","",0,"","","",1,0,0,[],""],["carrizo_salta-n1571-01",3,"¡Palomita mensajera,\nCon un hilo colorado!\nDecile a mi corazón,\nSi yo soy su bien amado.",3,1,0,46,"",0,4,"ao",14,0,-1,0,465,465,"1571","",0,"","","",2,0,0,[],""],["carrizo_salta-n1572-01",3,"¿Para dónde pajarillo,\nVuelas tan precipitado?\nLlevamele este suspiro,\nA mi bien idolatrado.",3,1,0,46,"",0,4,"ao",14,0,-1,0,465,465,"1572","",0,"","","",1,0,0,[],""],["carrizo_salta-n1573-01",3,"Para el año, cuando llegue,\nSi no me muero, h'i volver,\nA ver si corren las aguas,\nPor donde solían correr.",3,1,0,46,"",0,4,"e",20,0,-1,0,465,465,"1573","",0,"","","",1,0,0,[],""],["carrizo_salta-n1574-01",3,"¡Qué triste es el ausentarme,\nLejos del pago querido!\nCuando me vaya de aquí,\nNo me pongas en olvido.",3,1,0,46,"",0,4,"io",101,0,-1,0,465,465,"1574","",0,"","","",1,0,0,[],""],["carrizo_salta-n1575-01",3,"Quisiera tener la pluma,\nDe la garza más overa,\nPara escribir y mandarle,\nPor más lejos que estuviera.",3,1,0,46,"",0,4,"ea",44,0,-1,0,465,465,"1575","",0,"","","",2,0,0,[],""],["carrizo_salta-n1576-01",3,"Recibe, prenda de mi alma,\nCon amor este papel,\nY cuando a tus manos llegue-\nPasa la vista por él.",3,1,0,46,"",0,4,"e",-1,0,-1,0,466,466,"1576","",0,"","","",1,0,0,[],""],["carrizo_salta-n1577-01",3,"San José tiene su rama,\nY San Francisco un cordón,\nAsí quisiera tener,\nDe mi amante el corazón.",3,1,0,46,"",0,4,"o",31,0,-1,0,466,466,"1577","",0,"","","",1,0,0,[],""],["carrizo_salta-n1578-01",3,"¿Se acuerda, vidita mía,\nCuando tratamos de amores?\nDebajo de un limón verde,\nLe alcancé un ramo de flores.",3,1,0,46,"",0,4,"oe",5,0,-1,0,466,466,"1578","",0,"","","",1,0,0,[],""],["carrizo_salta-n1579-01",3,"Si las nubes fueran tinta,\nY el cielo fuera papel,\nEscribiría y le mandara,\nA mi estimado clavel.",3,1,0,46,"",3,4,"e",32,0,-1,0,466,466,"1579","",0,"","","",1,0,0,[],""],["carrizo_salta-n1580-01",3,"Si te vas pa lao de arriba,\nMis recuerdos le has de dar,\nA esa morenita ingrata,\nQue no la puedo olvidar.",3,1,0,46,"",0,4,"a",21,0,-1,0,466,466,"1580","",0,"","","",1,0,0,[],""],["carrizo_salta-n1581-01",3,"¡Te acordarás, vida mía,\nQue un Domingo de mañana,\nMe alcanzastes una rosa,\nY un clavel por la ventana!",3,1,0,46,"",0,4,"aa",4,0,-1,0,466,466,"1581","",0,"","","",2,0,0,[],""],["carrizo_salta-n1583-01",3,"Todos tienen algo,\nYo quero tener,\nUna buenamoza,\nPara mi querer.",3,1,0,46,"",0,4,"e",20,0,-1,0,466,466,"1583","",0,"","","",1,0,0,[],""],["carrizo_salta-n1584-01",3,"Triste está mi alma y llorosa,\nTanto sufrir le da pena,\nLos pesares me envenenan,\n¡Adiós, palomita hermosa!",3,1,0,46,"",5,4,"oa",63,0,-1,0,466,466,"1584","",0,"","","",1,0,0,[],""],["carrizo_salta-n1585-01",3,"Un recuerdo de mi amado,\nEs este anillo de amor,\nAunque me vea separada,\nPor el destino traidor.",3,1,0,46,"",0,4,"o",72,0,-1,0,466,466,"1585","",0,"","","",1,0,0,[],""],["carrizo_salta-n1586-01",3,"Un santo dicen que tiene,\nLa paloma y el olivo,\nY yo quisiera tener,\nDe mi amante el apellido.",3,1,0,46,"",0,4,"io",-1,0,-1,0,466,466,"1586","",0,"","","",1,0,0,[],""],["carrizo_salta-n1587-01",3,"Verdecito me mantengo,\nComo palito de lanza,\nPor más lejos que me vaya,\nYo no pierdo la esperanza.",3,1,0,46,"",0,4,"aa",-1,0,-1,0,466,466,"1587","",0,"","","",2,0,0,[],""],["carrizo_salta-n1588-01",3,"Voy a echar mi despedida,\nTal vez me vaya y no vuelva,\nPorque no hi comprao la vida,\nY mi puesto está en \"La Selva\".",3,1,0,46,"",1,4,"ea",381,0,-1,0,466,466,"1588","",0,"","","",2,0,0,[],""],["carrizo_salta-n1589-01",3,"¡Vuela, vuela, pajarillo!\n¡Vuela, vuela, picaflor!\nAnda, dile a mi querida,\nQue me muero de dolor.",3,1,0,46,"",0,4,"o",72,0,-1,0,466,466,"1589","",0,"","","",1,0,0,[],""],["carrizo_salta-n1590-01",3,"¡Vuela, vuela papelito!\nEn alas de aquel halcón,\nAnda y trae la respuesta,\nDe aquel duro corazón.",3,1,0,46,"",0,4,"o",31,0,-1,0,466,466,"1590","",0,"","","",1,0,0,[],""],["carrizo_salta-n1591-01",3,"Ya camino, ya me voy,\nYa me voy a separar,\nDame la mano, mi vida,\nYa no t'hi poder hablar.",3,1,0,46,"",0,4,"a",21,0,-1,0,466,466,"1591","",0,"","","",2,0,0,[],""],["carrizo_salta-n1592-01",3,"Ya desfallece mi aliento,\nSe ofusca mi corazón,\nYa llega el fatal momento,\nDe nuestra separación.",3,1,0,46,"",1,4,"o",31,0,-1,0,467,467,"1592","",0,"","","",3,0,0,[],""],["carrizo_salta-n1593-01",3,"Ya me despido de tí,\nYa me voy, preciosa flor,\nDe tus brazos me retiro,\nCon mucha pena y dolor.",3,1,0,46,"",0,4,"o",72,0,-1,0,467,467,"1593","",0,"","","",1,0,0,[],""],["carrizo_salta-n1594-01",3,"Ya me vengo a despedir,\nVida mía de mis ojos;\nNo quiero hallar a mi vuelta,\nDe mi querer, los despojos.",3,1,0,46,"",0,4,"oo",99,0,-1,0,467,467,"1594","",0,"","","",3,0,0,[],""],["carrizo_salta-n1595-01",3,"Ya me voy, ya me despido,\nYa me despido llorando,\nPor los caminos yo voy,\nGotas de sangre regando.",3,1,0,46,"",0,4,"ao",33,0,-1,0,467,467,"1595","",0,"","","",9,0,0,[],""],["carrizo_salta-n1596-01",3,"Ya me voy, ya me estoy yendo,\nSeñores: ¡Hasta otro día!\nPara el año volveré,\nSi Dios quiere, como hoy día.",3,1,0,46,"",0,4,"ia",-1,0,-1,0,467,467,"1596","",0,"","","",3,0,0,[],""],["carrizo_salta-n1597-01",3,"Ya me voy, ya me retiro,\nDe tu presencia me alejo,\nSiquiera para memoria,\nEste corazón te dejo.",3,1,0,46,"",0,4,"eo",264,0,-1,0,467,467,"1597","",0,"","","",3,0,0,[],""],["carrizo_salta-n1598-01",3,"Ya me voy, ya me retiro,\nVoy a seguir otro giro,\nAunque sintiendo dejar,\nEl espejo en que me miro.",3,1,0,46,"",0,4,"io",222,0,-1,0,467,467,"1598","",0,"","","",3,0,0,[],""],["carrizo_salta-n1599-01",3,"Ya me voy, ya no hi volver,\nPorque no tengo qué ver,\nLa prenda que yo adoraba,\nHa cambiado de querer.",3,1,0,46,"",0,4,"e",20,0,-1,0,467,467,"1599","",0,"","","",1,0,0,[],""],["carrizo_salta-n1600-01",3,"Ya que el destino ha querido,\nQue me separe de vos,\nLloraré toda mi vida,\n¡Adiós, corazón, adiós!",3,1,0,46,"",0,4,"o",87,0,-1,0,467,467,"1600","",0,"","","",1,0,0,[],""],["carrizo_salta-n1601-01",3,"Yo la sé vivir espiando.\nComo a dañino león,,\nYo la sé vivir desiando,\nHambre le tengo a su amor.",3,1,0,46,"",0,4,"o",-1,0,-1,0,467,467,"1601","",0,"","","",1,0,0,[],""],["carrizo_salta-n1602-01",3,"Yo quisiera ser paloma,\nPaloma de buen volar,\nPara andar de tierra en tierra,\nY llegar donde ella está.",3,1,0,46,"",0,4,"a",-1,0,-1,0,467,467,"1602","",0,"","","",1,0,0,[],""],["carrizo_salta-n1603-01",3,"Yo soy esa pobre moza,\nVestida de sobrepelo,\nAlgún día Dios me ha i dar,\nVestido de terciopelo.",3,1,0,46,"",0,4,"eo",10,0,-1,0,467,467,"1603","",0,"","","",2,0,0,[],""],["carrizo_salta-n1604-01",3,"Yo ya me voy,\nYa me voy ir,\nYa me estoy yendo,\n¡Adiós, Tastil!",3,1,0,46,"",6,4,"i",-1,0,-1,0,467,467,"1604","",0,"","","",3,0,0,[],""],["carrizo_salta-n1605-01",3,"Ahí han de ver tonto s viejos,\nCuando de hambre and en al trote,\nYa no ha de haber qui en les dé\nPanza, libro, ni cogote.",3,1,0,47,"",0,4,"oe",292,0,-1,0,469,469,"1605","",0,"","","",1,0,0,[],""],["carrizo_salta-n1606-01",3,"Ahí, te mando mis amores,\nEn un pañuelito overo,\nLa mujer cuando es honrada,\nNo se cambia por dinero.",3,1,0,47,"",0,4,"eo",38,0,-1,0,469,469,"1606","",0,"","","",1,0,0,[],""],["carrizo_salta-n1611-01",3,"Al cielo pido justicia,\nQue conforme mates, mueras,\nY que mis ojos te vean,\nQueriendo sin que te quieran.",3,1,0,47,"",0,4,"ea",-1,0,-1,0,469,469,"1611","",0,"","","",2,0,0,[],""],["carrizo_salta-n1612-01",3,"Alegrate que me voy,\nLlora que no hi de volver,\nSi vuelvo hi de volver tarde,\nReinando en otro poder.",3,1,0,47,"",0,4,"e",20,0,-1,0,469,469,"1612","",0,"","","",3,0,0,[],""],["carrizo_salta-n1613-01",3,"Algún día, santito,\nFuí tu devota,\nAhora, por Dios te pido,\nQue busques otra.",3,1,0,47,"",6,4,"oa",-1,0,-1,0,469,469,"1613","",0,"","","",3,0,0,[],""],["carrizo_salta-n1614-01",3,"Al pedo andás gambetiando,\nComo avestruz charabón,\nSi no te quiero nadita,\n¿A qué me contás tu amor?",3,1,0,47,"",0,4,"o",-1,0,-1,0,469,469,"1614","",0,"","","",1,0,0,[],""],["carrizo_salta-n1615-01",3,"A mí también me fascinan,\nSus palabras amorosas,\nPero creo, caballero,\nQue nunca me hará dichosa.",3,1,0,47,"",0,4,"oa",-1,0,-1,0,469,469,"1615","",0,"","","",1,0,0,[],""],["carrizo_salta-n1616-01",3,"Andando te has de perder,\nComo la ciudad de Esteco,\nComo me dejes la manta,\nAunque te lleve el fleco.",3,1,0,47,"",0,4,"eo",320,0,-1,0,469,469,"1616","",0,"","","",2,0,0,[],""],["carrizo_salta-n1617-01",3,"¡Anda, palomita ingrata!\nTanto me has hecho llorar,\nCasi he perdido la vida,\nLlegando a tu palomar.",3,1,0,47,"",0,4,"a",21,0,-1,0,470,470,"1617","",0,"","","",2,0,0,[],""],["carrizo_salta-n1618-01",3,"Andate con quién quisistes,\nCon la prenda que elegistes,\nCon ella merecerás,\nLo que conmigo perdistes.",3,1,0,47,"",0,4,"ie",91,0,-1,0,470,470,"1618","",0,"","","",2,0,0,[],""],["carrizo_salta-n1619-01",3,"¡Andate con quien quisistes!\n¡Con quien quisistes andate!\nNo estoy pa calentar agua,\nPara que otro tome mate.",3,1,0,47,"",0,4,"ae",384,0,-1,0,470,470,"1619","",0,"","","",2,0,0,[],""],["carrizo_salta-n1620-01",3,"¡Andate pa donde quieras!\n¡Pa donde quieras andate!\nQue no soy para tu gusto,\nNi menos para aguantarte.",3,1,0,47,"",0,4,"ae",-1,0,-1,0,470,470,"1620","",0,"","","",1,0,0,[],""],["carrizo_salta-n1621-01",3,"¡Andate, tirano, andate!\n¡Andate con quien quisiste!\nA ver si con él ganastes,\nLo que conmigo perdistes.",3,1,0,47,"",0,4,"ie",-1,0,-1,0,470,470,"1621","",0,"","","",1,0,0,[],""],["carrizo_salta-n1622-01",3,"¡Andate y no te creás!\nQue en la luna me has dejao,\nQue por vos no hi de llorar,\nOtra mejor m' hi de hallar.",3,1,0,47,"",5,4,"a",21,0,-1,0,470,470,"1622","",0,"","","",1,0,0,[],""],["carrizo_salta-n1623-01",3,"¡Anda vos, falso, falsario!\nFalso, ingrato, engañador,\nComo los vientos variable,\nY como Judas traidor.",3,1,0,47,"",0,4,"o",72,0,-1,0,470,470,"1623","",0,"","","",1,0,0,[],""],["carrizo_salta-n1624-01",3,"Antes, cuando eras mía,\nEras una flor de albahaca,\nAhora que no sois nada,\nSos como una plasta i vaca.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,470,470,"1624","",0,"","","",2,0,0,[],""],["carrizo_salta-n1625-01",3,"Antes, cuando eras mía,\nEras media, media dura,\nAhora que no sos nada,\nPónete sal en la u...",3,1,0,47,"",5,4,"u",-1,0,-1,0,470,470,"1625","",0,"","","",2,0,0,[],""],["carrizo_salta-n1626-01",3,"Antes, cuando te quería,\nEras como perla fina,\nAhora que no te quiero,\nSos como bosta i gallina.",3,1,0,47,"",0,4,"ia",11,0,-1,0,470,470,"1626","",0,"","","",7,0,0,[],""],["carrizo_salta-n1627-01",3,"Antes, cuando te quería,\nEras mozo caballero,\nAhora que te aborrezco,\nSos un burro zapallero.",3,1,0,47,"",0,4,"eo",-1,0,-1,0,470,470,"1627","",0,"","","",7,0,0,[],""],["carrizo_salta-n1628-01",3,"Antes, cuando te quería,\nEras perla, eras coral,\nAhora que no te quiero,\nSos basura de corral.",3,1,0,47,"",0,4,"a",1,0,-1,0,470,470,"1628","",0,"","","",7,0,0,[],""],["carrizo_salta-n1629-01",3,"Antes, cuando te quería,\nEras una flor rosada,\nAhora que no te quiero,\nSos una fruta pasada.",3,1,0,47,"",0,4,"aa",49,0,-1,0,470,470,"1629","",0,"","","",7,0,0,[],""],["carrizo_salta-n1630-01",3,"Antes, cuando te quería,\nEras un granito de oro,\nAhora que no te quiero,\nEres como bosta i loro.",3,1,0,47,"",0,4,"oo",85,0,-1,0,470,470,"1630","",0,"","","",7,0,0,[],""],["carrizo_salta-n1631-01",3,"Antes, cuando te quería,\nTe peinabas a menudo,\nAhora que no te quiero,\nSos como choco lanudo.",3,1,0,47,"",0,4,"uo",191,0,-1,0,471,471,"1631","",0,"","","",7,0,0,[],""],["carrizo_salta-n1632-01",3,"Arriba de tu tejado,\nTengo un pinito plantado,\nCuando el pino me dé piñas,\nAndaré yo a tu mandado.",3,1,0,47,"",0,4,"ao",14,0,-1,0,471,471,"1632","",0,"","","",1,0,0,[],""],["carrizo_salta-n1633-01",3,"Así dicen y así sale,\nAmor viejo ya no vale,\nHabiendo plata y jabón,\nNo ha de faltar quien me lave.",3,1,0,47,"",0,4,"ae",-1,0,-1,0,471,471,"1633","",0,"","","",1,0,0,[],""],["carrizo_salta-n1634-01",3,"Así se les hace,\nPa que sean firmes,\n¡Oiga la cochina,\nCosa que no sirve!",3,1,0,47,"",0,4,"ie",-1,0,-1,0,471,471,"1634","",0,"","","",1,0,0,[],""],["carrizo_salta-n1635-01",3,"Asomate a la ventana,\nSi te querís asomar,\nSi no queris no te asomes,\nA mí nada se me da.",3,1,0,47,"",0,4,"a",-1,0,-1,0,471,471,"1635","",0,"","","",14,0,0,[],""],["carrizo_salta-n1636-01",3,"A sus puertas han venido,\nSeñora, los amadores,\nPasando ríos crecidos,\nPagando a los nadadores.",3,1,0,47,"",0,4,"oe",5,0,-1,0,471,471,"1636","",0,"","","",1,0,0,[],""],["carrizo_salta-n1637-01",3,"¿A qué vienes a pintar,\nEstando la pera verde?\nNo te extrañes cuando diga:\n—Perro que ladra no muerde.",3,1,0,47,"",0,4,"ee",154,0,-1,0,471,471,"1637","",0,"","","",1,0,0,[],""],["carrizo_salta-n1638-01",3,"¡Ay, Dios con la colorada!\nTan flaca y aguanacada,\nLigera pa las patadas,\nVerijas desguañangadas.",3,1,0,47,"",0,4,"aa",282,0,-1,0,471,471,"1638","",0,"","","",1,0,0,[],""],["carrizo_salta-n1639-01",3,"Ayer comí una limita,\nHoy comí la cascarita,\nAunque me quieras, vidita,\nYo no te quiero nadita.",3,1,0,47,"",0,4,"ia",50,0,-1,0,471,471,"1639","",0,"","","",1,0,0,[],""],["carrizo_salta-n1640-01",3,"Ayer me fuí a confesar,\nY me dijo el confesor,\nQue si no te olvido pronto,\nNo tengo perdón de Dios.",3,1,0,47,"",0,4,"o",-1,0,-1,0,471,471,"1640","",0,"","","",3,0,0,[],""],["carrizo_salta-n1641-01",3,"Ayer tarde, para verte,\nAbrí las cuatro ventanas,\nY ahora para no verte,\nTodas las tengo cerradas.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,471,471,"1641","",0,"","","",1,0,0,[],""],["carrizo_salta-n1642-01",3,"Calentate como teja,\nPues yo no m'hi calentar,\nOtra ingrata como vos,\nEn donde quiera hi de hallar.",3,1,0,47,"",0,4,"a",21,0,-1,0,471,471,"1642","",0,"","","",1,0,0,[],""],["carrizo_salta-n1643-01",3,"¡Callate gaucho baboso!\nOrejas de mancarrón,\nLa boca te va quedando,\nComo ternero mamón.",3,1,0,47,"",0,4,"o",31,0,-1,0,472,472,"1643","",0,"","","",1,0,0,[],""],["carrizo_salta-n1644-01",3,"¡Callate loro bocón!\nAmante a comer semilla,\nA vos no te digo nada,\nAndá a cuidar tu familia.",3,1,0,47,"",0,4,"ia",-1,0,-1,0,472,472,"1644","",0,"","","",1,0,0,[],""],["carrizo_salta-n1645-01",3,"Cambian las aves su nido,\nCambia el tiempo el parecer,\n¿Cómo no hi de cambiar yo,\nTambién mi nuevo querer?",3,1,0,47,"",0,4,"e",20,0,-1,0,472,472,"1645","",0,"","","",1,0,0,[],""],["carrizo_salta-n1646-01",3,"Casi, casi me quisistes,\nCasi, casi te he querido,\nSi no es por el casi, casi,\nCasi me caso contigo.",3,1,0,47,"",0,4,"io",-1,0,-1,0,472,472,"1646","",0,"","","",2,0,0,[],""],["carrizo_salta-n1647-01",3,"Cierto es que te quise,\nPero no te amé,\nHay mucha distancia,\nDe amar a querer.",3,1,0,47,"",0,4,"e",-1,0,-1,0,472,472,"1647","",0,"","","",1,0,0,[],""],["carrizo_salta-n1648-01",3,"¡Cinta negra, boliviana!\nCortadita con tijera,\nTú me dices que me quieres,\nMás vale no me quisieras.",3,1,0,47,"",0,4,"ea",-1,0,-1,0,472,472,"1648","",0,"","","",1,0,0,[],""],["carrizo_salta-n1649-01",3,"Cinta verde abotonada,\nTe ciñes en la cintura,\nTu amante vive en la sombra,\nEngreído de tu pintura.",3,1,0,47,"",0,4,"ua",17,0,-1,0,472,472,"1649","",0,"","","",1,0,0,[],""],["carrizo_salta-n1650-01",3,"Decís que has hecho promesa,\nDe no volverme a querer,\nEscondete, traicionera,\nDonde no te pueda ver.",3,1,0,47,"",0,4,"e",20,0,-1,0,472,472,"1650","",0,"","","",1,0,0,[],""],["carrizo_salta-n1651-01",3,"Decís que no me querís,\nPorque no tengo qué dar,\nCasate con el reloj,\nQue a todas las horas dá.",3,1,0,47,"",0,4,"a",-1,0,-1,0,472,472,"1651","",0,"","","",2,0,0,[],""],["carrizo_salta-n1652-01",3,"Decís que ya no me quieres,\nPucha que lo siento mucho,\nCuando fumo mi cigarro,\nA la mi er... tiro el pucho.",3,1,0,47,"",0,4,"uo",415,0,-1,0,472,472,"1652","",0,"","","",1,0,0,[],""],["carrizo_salta-n1653-01",3,"De mañanita te quise,\nAl medio día no tanto,\nSobre tarde cayi en cuenta,\nLo que te quise y me espanto.",3,1,0,47,"",0,4,"ao",30,0,-1,0,472,472,"1653","",0,"","","",1,0,0,[],""],["carrizo_salta-n1654-01",3,"De vicio me has de buscar,\nComo a la espina en la tuna,\nTan amante a enamorar,\nHecho el mozo con fortuna.",3,1,0,47,"",1,4,"ua",56,0,-1,0,472,472,"1654","",0,"","","",1,0,0,[],""],["carrizo_salta-n1655-01",3,"De vicio me has de dar miel,\nComo colmena en la flor,\nEse tu amor lisonjero,\nNo tiene zumo ni olor.",3,1,0,47,"",0,4,"o",72,0,-1,0,472,472,"1655","",0,"","","",1,0,0,[],""],["carrizo_salta-n1656-01",3,"De vicio me has de dar vueltas,\nComo mariposa en peña,\nToavía en el mundo no existe,\nEsa que ha de ser mi dueña.",3,1,0,47,"",3,4,"ea",291,0,-1,0,472,472,"1656","",0,"","","",1,0,0,[],""],["carrizo_salta-n1657-01",3,"De vicio me has de mirar,\nCon el blanco de tus ojos,\nAhora estoy con mi dueño,\nEn vano son tus enojos.",3,1,0,47,"",0,4,"oo",99,0,-1,0,473,473,"1657","",0,"","","",1,0,0,[],""],["carrizo_salta-n1658-01",3,"De vicio venís moniando,\nCon tus alforjas vacías,\nParecís zapallo helado,\nQue lo cortan de la guía.",3,1,0,47,"",0,4,"ia",-1,0,-1,0,473,473,"1658","",0,"","","",4,0,0,[],""],["carrizo_salta-n1659-01",3,"De vicio venís moniando,\nCara de palo borracho,\nSólo el cencerro te falta,\nPa ser marucho i muchachos.",3,1,0,47,"",0,4,"ao",-1,0,-1,0,473,473,"1659","",0,"","","",4,0,0,[],""],["carrizo_salta-n1660-01",3,"De vicio te andas guasquiando,\nComo tiento de otro apero,\nYa t' hi dicho muchas veces,\nQue es a otra a la que quiero.",3,1,0,47,"",0,4,"eo",38,0,-1,0,473,473,"1660","",0,"","","",1,0,0,[],""],["carrizo_salta-n1661-01",3,"De vicio te has alabado,\nQue yo te lavé los platos,\nEso es lo que no has de ver,\n¡Chinita de malos tratos!",3,1,0,47,"",0,4,"ao",386,0,-1,0,473,473,"1661","",0,"","","",1,0,0,[],""],["carrizo_salta-n1662-01",3,"Diz que me vas a dejar,\nCuando pase carnaval,\nPor eso no hi de llorar,\nTal vez buscando hi de hallar.",3,1,0,47,"",0,4,"a",21,0,-1,0,473,473,"1662","",0,"","","",1,0,0,[],""],["carrizo_salta-n1663-01",3,"El amor que yo te tengo,\nEs como el corcho en el agua,\nQue por más que quiera hundirse,\nSiempre arriba sobrenada.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,473,473,"1663","",0,"","","",4,0,0,[],""],["carrizo_salta-n1664-01",3,"El que no me quiera a mí,\nNo se cuente por dichoso.\nQue quien me desprecia a mí,\nEs un gaucho pretencioso.",3,1,0,47,"",1,4,"oo",160,0,-1,0,473,473,"1664","",0,"","","",1,0,0,[],""],["carrizo_salta-n1665-01",3,"El tambor es tu retrato,\nMucho brillo, mucho ruído,\nSi se mira por adentro,\nSe encuentra que está vacío.",3,1,0,47,"",0,4,"io",-1,0,-1,0,474,474,"1665","",0,"","","",1,0,0,[],""],["carrizo_salta-n1666-01",3,"En el campo hay una flor,\nQue se llama la pomada,\nOtros mejores que vos,\nNo me vienen con monadas.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,474,474,"1666","",0,"","","",5,0,0,[],""],["carrizo_salta-n1667-01",3,"En el campo hay una flor,\nQue se llama San Vicente,\n¿Cómo querís que te quiera,\nSi está tu dueño presente?",3,1,0,47,"",0,4,"ee",15,0,-1,0,474,474,"1667","",0,"","","",5,0,0,[],""],["carrizo_salta-n1668-01",3,"En el campo hay un yuyito,\nQue lo llaman cardo santo,\nTe estás alabando al ñudo,\nCuando no merecís tanto.",3,1,0,47,"",0,4,"ao",30,0,-1,0,474,474,"1668","",0,"","","",2,0,0,[],""],["carrizo_salta-n1668-02",3,"En el campo hay un yuyito,\nQue se llama dos por tres,\nNo se piense, señorita,\nQue el amor es para Vd.",3,1,0,47,"",5,4,"",-1,0,-1,0,474,474,"1669","",0,"","","",2,0,1,[],""],["carrizo_salta-n1670-01",3,"En la cara te conozco,\nQue me quieres olvidar,\nEl \"Padre nuestro\" lo dice:\n\"Hágase tu voluntad\".",3,1,0,47,"",0,4,"a",-1,0,-1,0,474,474,"1670","",0,"","","",3,0,0,[],""],["carrizo_salta-n1671-01",3,"En la falda de aquel cerro,\nGrita el toro por la vaca,\nNi por oro, ni por plata,\nYo no quiero mujer flaca.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,474,474,"1671","",0,"","","",54,0,0,[],""],["carrizo_salta-n1671-a-01",3,"En la falda de aquel cerro,\nHay una cruz de hojalata,\nYo no me caso con flaca,\nNi por oro ni por plata.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,474,474,"1671-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n1672-01",3,"En la falda de aquel cerro,\nTengo formado un chiquero,\nPara encerrar mis ovejas,\nY echarte a vos de carnero.",3,1,0,47,"",0,4,"eo",38,0,-1,0,474,474,"1672","",0,"","","",54,0,0,[],""],["carrizo_salta-n1673-01",3,"En la falda de aquel cerro,\nTengo un atado de lana,\nSi no me querís ahora,\nTe has de quedar con las ganas.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,474,474,"1673","",0,"","","",54,0,0,[],""],["carrizo_salta-n1674-01",3,"En la falda de aquel cerro,\nTengo una caja de lata,\nAhí tengo todo remedio,\nPara curarte la mata.",3,1,0,47,"",0,4,"aa",74,0,-1,0,474,474,"1674","",0,"","","",54,0,0,[],""],["carrizo_salta-n1674-a-01",3,"En la falda de aquel cerro,\nTengo una taza de plata,\nAhí tengo varios remedios,\nPara curarte las matas.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,474,474,"1674-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n1675-01",3,"En la falda de aquel cerro,\nTengo una planta de espada,\nDe vicio venís moniando,\nChina, verijas paspadas.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,475,475,"1675","",0,"","","",54,0,0,[],""],["carrizo_salta-n1676-01",3,"En la falda de aquel cerro,\nTengo un corral de ladrillos,\nPara encerrar a mis yeguas,\nPonerte a vos de padrillo.",3,1,0,47,"",0,4,"io",-1,0,-1,0,475,475,"1676","",0,"","","",54,0,0,[],""],["carrizo_salta-n1677-01",3,"En la puerta de mi casa,\nTengo un zapallo pupulo,\nSi no te casas conmigo,\nMetete el dedo en el c...",3,1,0,47,"",5,4,"",-1,0,-1,0,475,475,"1677","",0,"","","",24,0,0,[],""],["carrizo_salta-n1678-01",3,"En la punta del pañuelo,\nTengo un juramento atado,\nDe no volver a querer,\nA la familia Mercado.",3,1,0,47,"",0,4,"ao",14,0,-1,0,475,475,"1678","",0,"","","",3,0,0,[],""],["carrizo_salta-n1679-01",3,"Enójate y revolvete,\nSalite al campo y vengate,\nDe mi c... has de hacer poro,\nEn ese has de tomar mate.",3,1,0,47,"",0,4,"ae",384,0,-1,0,475,475,"1679","",0,"","","",1,0,0,[],""],["carrizo_salta-n1680-01",3,"En un rancho tengo yo,\nUna vaca y un ternero,\nSólo me faltabas vos,\nPara cerrar el chiquero.",3,1,0,47,"",0,4,"eo",38,0,-1,0,475,475,"1680","",0,"","","",1,0,0,[],""],["carrizo_salta-n1681-01",3,"Esta mujer está loca,\nQuiere que la quiera yo,\n¡Que la quiera su marido!\nEl tiene l' obligación!",3,1,0,47,"",0,4,"o",-1,0,-1,0,475,475,"1681","",0,"","","",1,0,0,[],""],["carrizo_salta-n1682-01",3,"Es tanto lo que te quiero,\nY tan firme mi costancia,\nQue ya quisiera tenerte,\nA cien leguas de distancia.",3,1,0,47,"",0,4,"aa",340,0,-1,0,475,475,"1682","",0,"","","",26,0,0,[],""],["carrizo_salta-n1683-01",3,"¡Florcita de anís!\n¡Florcita de anís!\nYo no te quiero,\nPorque otra tenís.",3,1,0,47,"",6,4,"i",58,0,-1,0,475,475,"1683","",0,"","","",2,0,0,[],""],["carrizo_salta-n1684-01",3,"¡Flor de nogal!\n¡Flor de nogal!\nPrenda con dueño,\nNo me hace caudal.",3,1,0,47,"",6,4,"a",1,0,-1,0,475,475,"1684","",0,"","","",1,0,0,[],""],["carrizo_salta-n1685-01",3,"Has dicho lo que has querido,\nY te has quedao con el tanto,\nOrejas de burro viejo,\nHocico de perro ñato.",3,1,0,47,"",0,4,"ao",-1,0,-1,0,475,475,"1685","",0,"","","",1,0,0,[],""],["carrizo_salta-n1686-01",3,"Has pensado en agraviarme,\nBuscando dueña mejor,\nNo son agravios con gustos,\nAntes me has hecho un favor.",3,1,0,47,"",0,4,"o",72,0,-1,0,475,475,"1686","",0,"","","",1,0,0,[],""],["carrizo_salta-n1687-01",3,"Humito de paja i trigo,\nVenis a jugar conmigo,\nSi no conocís las senda,\nYo te enseñaré el camino.",3,1,0,47,"",0,4,"io",-1,0,-1,0,476,476,"1687","",0,"","","",1,0,0,[],""],["carrizo_salta-n1688-01",3,"La mojarrita del agua,\nBusca sitio donde estar,\nAsí voy buscando yo,\nCómo poderte olvidar.",3,1,0,47,"",0,4,"a",21,0,-1,0,476,476,"1688","",0,"","","",1,0,0,[],""],["carrizo_salta-n1689-01",3,"La mujer que no me quiera,\nQue se deje de jo...,\nSi Vd. no me quiere a mí,\nYo fuerza no l' hi de hacer.",3,1,0,47,"",5,4,"e",-1,0,-1,0,476,476,"1689","",0,"","","",2,0,0,[],""],["carrizo_salta-n1690-01",3,"Las esperanzas son verdes,\nVerdes como hoja i nogal,\n¡Amante a pagar desprecio,\nY también a pagar mal!",3,1,0,47,"",0,4,"a",1,0,-1,0,476,476,"1690","",0,"","","",1,0,0,[],""],["carrizo_salta-n1691-01",3,"Le dije y l'hi de decir,\nEn toda forma y manera,\nQue un besito de mi boca,\nNo lo merece cualquiera.",3,1,0,47,"",0,4,"ea",44,0,-1,0,476,476,"1691","",0,"","","",1,0,0,[],""],["carrizo_salta-n1692-01",3,"Me dicen que andas diciendo,\nQue te quiero por los trapos,\nEso es lo que no has de ver,\n¡Cochino de malos tratos!",3,1,0,47,"",0,4,"ao",-1,0,-1,0,476,476,"1692","",0,"","","",2,0,0,[],""],["carrizo_salta-n1693-01",3,"Me has rebalsado de amor,\nPensando de equivocarme,\nNo sos más que una apariencia,\nY has pretendido engañarme.",3,1,0,47,"",0,4,"ae",35,0,-1,0,476,476,"1693","",0,"","","",1,0,0,[],""],["carrizo_salta-n1694-01",3,"Me mandastes a decir,\nPor carta, que me olvidabas,\nCuando llegó el parte a mí,\nYa de vos no me acordaba.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,476,476,"1694","",0,"","","",4,0,0,[],""],["carrizo_salta-n1695-01",3,"Niña de los veinte novios,\nConmigo serán veintiuno,\nSi todos son como yo,\nNo te ha de servir ninguno.",3,1,0,47,"",0,4,"uo",230,0,-1,0,476,476,"1695","",0,"","","",11,0,0,[],""],["carrizo_salta-n1696-01",3,"No creas lo que te he dicho,\nLa copla no es copla mía,\nSi te quise fué un capricho,\nPero no te quiero hoy día.",3,1,0,47,"",1,4,"ia",0,0,-1,0,476,476,"1696","",0,"","","",1,0,0,[],""],["carrizo_salta-n1697-01",3,"No creás que por tus enojos,\nMe he de poner a llorar,\nQuien me quiera no hay faltar,\nSin que yo salga a buscar.",3,1,0,47,"",0,4,"a",21,0,-1,0,476,476,"1697","",0,"","","",1,0,0,[],""],["carrizo_salta-n1698-01",3,"No le hace, vidita mía,\nQue me olvides con el tiempo,\nDespués de lo bien gozado,\nLas cartas las lleva el viento.",3,1,0,47,"",0,4,"eo",-1,0,-1,0,476,476,"1698","",0,"","","",1,0,0,[],""],["carrizo_salta-n1699-01",3,"No me digas que soy tuyo,\nA mi dueño no le gusta,\nFlor de tusca, flor de tusca,\nEl que no tiene, se busca.",3,1,0,47,"",0,4,"ua",416,0,-1,0,476,476,"1699","",0,"","","",1,0,0,[],""],["carrizo_salta-n1700-01",3,"No me hacés ningún agravio,\nVidita, con enojarte,\nVidita, lo que mes has hecho,\nNo tengo con qué pagarte.",3,1,0,47,"",0,4,"ae",8,0,-1,0,476,476,"1700","",0,"","","",1,0,0,[],""],["carrizo_salta-n1701-01",3,"No me importa de tu amor,\nOjalá vaya y se pierda,\nPorque en llegando a mi casa,\nTengo más amor que mi er...",3,1,0,47,"",5,4,"e",-1,0,-1,0,477,477,"1701","",0,"","","",1,0,0,[],""],["carrizo_salta-n1702-01",3,"No me importa que te enojes,\nDe tus desprecios me río,\nHay muchachitas bonitas,\nComo piedras en el río.",3,1,0,47,"",0,4,"io",-1,0,-1,0,477,477,"1702","",0,"","","",1,0,0,[],""],["carrizo_salta-n1703-01",3,"No me importa que te vayas,\nY que de mí no te acuerdes,\nNo ha i ser el primer carnero,\nQue en el camino se vuelve.",3,1,0,47,"",0,4,"ee",-1,0,-1,0,477,477,"1703","",0,"","","",1,0,0,[],""],["carrizo_salta-n1704-01",3,"No me traigas yuyos secos,\nNi paja para encender,\nNo creas que soy tan zonza,\nPara volverte a querer.",3,1,0,47,"",0,4,"e",20,0,-1,0,477,477,"1704","",0,"","","",1,0,0,[],""],["carrizo_salta-n1704-a-01",3,"No me traiga yerba seca,\nNi paja para encender,\n¿Cuándo soy tan sirvengüenza,\nPara volverte a querer?",3,1,0,47,"",0,4,"e",20,0,-1,0,477,477,"1704-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1705-01",3,"No pienses que m' hi secado,\nEstoy más verde que un yuyo,\nDe vicio me estás mirando,\nAhora ya no soy tuyo.",3,1,0,47,"",0,4,"uo",78,0,-1,0,477,477,"1705","",0,"","","",1,0,0,[],""],["carrizo_salta-n1706-01",3,"No por mucho madrugar,\nAmanece más temprano,\nTambién te puedes quedar,\nCon el ijar en la mano.",3,1,0,47,"",1,4,"ao",81,0,-1,0,477,477,"1706","",0,"","","",2,0,0,[],""],["carrizo_salta-n1707-01",3,"No quiero querer a nadie,\nNi quiero ser su querida,\nQuiero que sea mi enemigo,\nQuiero ser su aborrecida.",3,1,0,47,"",0,4,"ia",37,0,-1,0,477,477,"1707","",0,"","","",5,0,0,[],""],["carrizo_salta-n1708-01",3,"Nunca más te quise el bien,\nDesde que mal me quisiste,\nDéjalo al mundo rodar,\nQue viva el que aborreciste.",3,1,0,47,"",0,4,"ie",153,0,-1,0,477,477,"1708","",0,"","","",1,0,0,[],""],["carrizo_salta-n1709-01",3,"¿Pa qué se mete a cantar,\nSi la lengua no le ayuda?\nCara de matambre seco,\nRevolcao en la basura.",3,1,0,47,"",0,4,"ua",-1,0,-1,0,477,477,"1709","",0,"","","",1,0,0,[],""],["carrizo_salta-n1710-01",3,"Piedrecitas me tiráis,\nPiedrecitas de aquel alto,\nYo no quiero tus amores,\nAmores de sobresalto.",3,1,0,47,"",0,4,"ao",417,0,-1,0,477,477,"1710","",0,"","","",1,0,0,[],""],["carrizo_salta-n1711-01",3,"Por aquella cruz bendita,\nQue está puesta en la pared,\nHice yo mi juramento,\nDe no volverte a querer.",3,1,0,47,"",0,4,"e",-1,0,-1,0,477,477,"1711","",0,"","","",9,0,0,[],""],["carrizo_salta-n1712-01",3,"Porque me ves pobre y fiero,\nHasta el habla me has negao,\nAndate con el que quieras,\nEl mundo no se ha acabao.",3,1,0,47,"",0,4,"ao",98,0,-1,0,477,477,"1712","",0,"","","",1,0,0,[],""],["carrizo_salta-n1713-01",3,"Por tu gusto me has querido,\nY ahora te parece mal,\nAndate con el que quieras,\nEl gusto es de cada cual.",3,1,0,47,"",3,4,"a",1,0,-1,0,477,477,"1713","",0,"","","",2,0,0,[],""],["carrizo_salta-n1713-a-01",3,"Por tu gusto me has querido,\nY hoy te ha parecido mal,\nAndate con el que quieras,\nQue para mí es carnaval.",3,1,0,47,"",0,4,"a",1,0,-1,0,477,477,"1713-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n1714-01",3,"Que me olvide de tí,\nYo sé que me quieres.\n¡Nunca te conocí,\nNi sé quién eres!",3,1,0,47,"",6,4,"ee",55,0,-1,0,477,477,"1714","",0,"","","",1,0,0,[],""],["carrizo_salta-n1715-01",3,"Que quede bien remediado,\nQue yo me consolaré,\nQue no queden ni las güellas,\nDe un amor que ingrato fué.",3,1,0,47,"",0,4,"e",77,0,-1,0,478,478,"1715","",0,"","","",1,0,0,[],""],["carrizo_salta-n1716-01",3,"¡Retirate de mi lado!\nYa no te puedo mirar,\nNo quiero ser tu querido,\nQuiero que me aburrezcás.",3,1,0,47,"",0,4,"a",-1,0,-1,0,478,478,"1716","",0,"","","",2,0,0,[],""],["carrizo_salta-n1717-01",3,"¡Retirate de mi lado!\nYa no te puedo mirar,\nAndate con el que quieras,\nYa te dí la libertad.",3,1,0,47,"",0,4,"a",-1,0,-1,0,478,478,"1717","",0,"","","",2,0,0,[],""],["carrizo_salta-n1718-01",3,"¡Se acabó nuestra amistad!\nYa no te acuerdes de mí,\nResuelto estoy a olvidar,\nY a no pensar más en tí.",3,1,0,47,"",0,4,"i",23,0,-1,0,478,478,"1718","",0,"","","",1,0,0,[],""],["carrizo_salta-n1718-01-e2",3,"Se me hace, se me hace,\nLechuga sin flor,\nDejar a mi amante,\nPor otro mejor.",3,1,0,47,"",0,4,"o",72,0,-1,0,478,478,"1718","",0,"","","",1,0,0,[],""],["carrizo_salta-n1720-01",3,"Señores, yo soy un pobre,\nPobre pero delicado,\nYo no sé querer usar,\nPrendas que otros han usado.",3,1,0,47,"",0,4,"ao",14,0,-1,0,478,478,"1720","",0,"","","",3,0,0,[],""],["carrizo_salta-n1721-01",3,"Si amor me pide,\nNo l'hi de dar,\nYo no lo quiero,\nMe ha de olvidar.",3,1,0,47,"",6,4,"a",21,0,-1,0,478,478,"1721","",0,"","","",1,0,0,[],""],["carrizo_salta-n1722-01",3,"Si dentro al agua me mojo,\nSi dentro al fuego me quemo,\nMe retiraré de tí,\nY tengo un peligro menos.",3,1,0,47,"",0,4,"eo",-1,0,-1,0,478,478,"1722","",0,"","","",1,0,0,[],""],["carrizo_salta-n1723-01",3,"Si dice que no me quiere,\nPor eso no vua llorar,\nMe atengo a que el mundo es grande,\nQuien me quiera no ha i faltar.",3,1,0,47,"",0,4,"a",21,0,-1,0,478,478,"1723","",0,"","","",1,0,0,[],""],["carrizo_salta-n1724-01",3,"Si en mi última agonía,\nMe dan vida para verte,\nYo no lo consentiría,\nPreferiría la muerte.",3,1,0,47,"",1,4,"ee",134,0,-1,0,478,478,"1724","",0,"","","",1,0,0,[],""],["carrizo_salta-n1725-01",3,"Si en tu puerta se para,\nUn perro flaco,\nTrátalo con cariño,\nQue es tu retrato.",3,1,0,47,"",6,4,"ao",-1,0,-1,0,478,478,"1725","",0,"","","",1,0,0,[],""],["carrizo_salta-n1726-01",3,"Si en un caso no me quiere,\nNo hay mal que por bien no venga,\nHaciendo la diligencia;\nSólo que suerte no tenga.",3,1,0,47,"",0,4,"ea",-1,0,-1,0,478,478,"1726","",0,"","","",2,0,0,[],""],["carrizo_salta-n1727-01",3,"Si este mozo no me quiere,\nNada hago con afligirme,\nOtro mejor no ha i faltar,\nCon quien pueda divertirme.",3,1,0,47,"",0,4,"ie",184,0,-1,0,478,478,"1727","",0,"","","",1,0,0,[],""],["carrizo_salta-n1728-01",3,"Si no me querís, vidita,\nYo no te voy a rogar,\nPorque no pierdo gran cosa,\nSi yo pierdo tu amistad.",3,1,0,47,"",0,4,"a",-1,0,-1,0,478,478,"1728","",0,"","","",1,0,0,[],""],["carrizo_salta-n1729-01",3,"Si porque te quiero,\nTe hacís de rogar,\nAndate a la mie...\nMala voluntad.",3,1,0,47,"",0,4,"a",-1,0,-1,0,478,478,"1729","",0,"","","",2,0,0,[],""],["carrizo_salta-n1730-01",3,"Si porque te quiero quieres,\nQue yo la muerte reciba,\nMeté tu amor en el c...\nY dale siete fruncidas!",3,1,0,47,"",0,4,"ia",-1,0,-1,0,478,478,"1730","",0,"","","",11,0,0,[],""],["carrizo_salta-n1732-01",3,"Si quieres que yo te diga,\nTe lo diré en dos razones,\nEres hombre de dos caras,\nY de malas condiciones.",3,1,0,47,"",0,4,"oe",34,0,-1,0,479,479,"1732","",0,"","","",5,0,0,[],""],["carrizo_salta-n1733-01",3,"Sombrerito paja i trigo,\nCinta de yica de araña,\nBarbiquejo de zaraza.\nConmigo no has de hacer baza.",3,1,0,47,"",0,4,"aa",307,0,-1,0,479,479,"1733","",0,"","","",1,0,0,[],""],["carrizo_salta-n1734-01",3,"Te quiero, por que te ví,\nTe ví porque Dios lo quiso,\nY al ver que poco me quieres,\nMe pesa el haberte visto.",3,1,0,47,"",0,4,"io",-1,0,-1,0,479,479,"1734","",0,"","","",1,0,0,[],""],["carrizo_salta-n1735-01",3,"¡Tonta tú, tonta tu mama!\nTonta tu abuela y tu tía,\n¿Cómo querís que te quiera,\nSi sos puras tonterías?",3,1,0,47,"",0,4,"ia",-1,0,-1,0,479,479,"1735","",0,"","","",1,0,0,[],""],["carrizo_salta-n1736-01",3,"Tu presencia me repugna,\nPagaría por no verte,\nCómo has cambiado de nombre,\nAsí has cambiado de suerte.",3,1,0,47,"",0,4,"ee",134,0,-1,0,479,479,"1736","",0,"","","",1,0,0,[],""],["carrizo_salta-n1737-01",3,"Tuve un amor en peligro,\nY un domingo se acabó,\nMe dijo que había dejado,\nLo que conmigo pensó.",3,1,0,47,"",0,4,"o",2,0,-1,0,479,479,"1737","",0,"","","",1,0,0,[],""],["carrizo_salta-n1738-01",3,"Tus ojos me hacen llorar,\nSin consolar mi dolor,\nPara otra tenís amor,\nPero me la has de pagar.",3,1,0,47,"",11,4,"a",21,0,-1,0,479,479,"1738","",0,"","","",1,0,0,[],""],["carrizo_salta-n1739-01",3,"Un juramento me hiciste,\nDe no olvidar mi querer,\nAusente me has traicionado,\nMis ojos no te han de ver.",3,1,0,47,"",0,4,"e",20,0,-1,0,479,479,"1739","",0,"","","",1,0,0,[],""],["carrizo_salta-n1740-01",3,"¡Vidita, si no te sirvo,\nPelame con agua hirviendo!\nEs el gusto que yo tengo,\nDe estar con otro, y vos viendo.",3,1,0,47,"",0,4,"eo",-1,0,-1,0,479,479,"1740","",0,"","","",1,0,0,[],""],["carrizo_salta-n1741-01",3,"Vua formar una laguna,\nDe lechuga y verdulaga,\nQueré nomás a tu dueño,\nYa tengo donde alzar agua.",3,1,0,47,"",0,4,"aa",-1,0,-1,0,479,479,"1741","",0,"","","",1,0,0,[],""],["carrizo_salta-n1742-01",3,"Vuela el chimango y el tero,\nY también el picaflor,\nY si los pavos volaran,\nTambién volarías vos.",3,1,0,47,"",0,4,"o",-1,0,-1,0,479,479,"1742","",0,"","","",1,0,0,[],""],["carrizo_salta-n1743-01",3,"Ya te cansaste de mí,\nFué tu gusto el olvidarme,\nBien puedes considerarme,\nMuy separado de tí.",3,1,0,47,"",11,4,"i",23,0,-1,0,480,480,"1743","",0,"","","",1,0,0,[],""],["carrizo_salta-n1744-01",3,"Ya te he dicho varias veces,\nQue no me hables en la calle,\nQue la lechuga no s' hizo\nPara tan simple vinagre.",3,1,0,47,"",0,4,"ae",-1,0,-1,0,480,480,"1744","",0,"","","",1,0,0,[],""],["carrizo_salta-n1745-01",3,"Yo no siento que me deje,\nDespués de haberme querido,\nDespués de lo bien gozado,\nPoco será lo perdido.",3,1,0,47,"",0,4,"io",101,0,-1,0,480,480,"1745","",0,"","","",1,0,0,[],""],["carrizo_salta-n1746-01",3,"Yo no siento que me dejes,\nSiento el haberte querido,\nHaber ocupado el tiempo,\nEn un mal agradecido.",3,1,0,47,"",0,4,"io",101,0,-1,0,480,480,"1746","",0,"","","",1,0,0,[],""],["carrizo_salta-n1747-01",3,"Yo no solicito a nadie,\nMenos a quien se retira,\nPorque tengo la venganza,\nDe olvidarlo si me olvida.",3,1,0,47,"",0,4,"ia",-1,0,-1,0,480,480,"1747","",0,"","","",1,0,0,[],""],["carrizo_salta-n1748-01",3,"Yo soy como golondrina,\nPaso el mar en un volido,\n¿Cómo querís que te quiera,\nCuando tantos te han querido?",3,1,0,47,"",0,4,"io",101,0,-1,0,480,480,"1748","",0,"","","",1,0,0,[],""],["carrizo_salta-n1749-01",3,"Yo soy como la florcita,\nFlorcita de primavera,\nLe aviso que no lo quiero,\nPorque es Vd. un cualquiera.",3,1,0,47,"",0,4,"ea",44,0,-1,0,480,480,"1749","",0,"","","",1,0,0,[],""],["carrizo_salta-n1750-01",3,"Yo soy el que siempre he sido,\nAquí y en todo lugar,\nAl que me quiere, lo quiero,\nAl que no, no l' h'i rogar.",3,1,0,47,"",3,4,"a",21,0,-1,0,480,480,"1750","",0,"","","",2,0,0,[],""],["carrizo_salta-n1751-01",3,"A la mañanita,\nY al amanecer,\nQué lindo es amar,\nCuando pagan bien.",3,1,0,48,"",0,4,"e",-1,0,-1,0,482,482,"1751","",0,"","","",1,0,0,[],""],["carrizo_salta-n1752-01",3,"Al amor lo pintan,\nEn una azucena,\nPor eso se usa,\nQuerer cosa buena.",3,1,0,48,"",6,4,"ea",59,0,-1,0,482,482,"1752","",0,"","","",2,0,0,[],""],["carrizo_salta-n1753-01",3,"Al amor lo pintan,\nEn un papelito,\nPor eso se usa,\nQuerer un poquito.",3,1,0,48,"",6,4,"io",119,0,-1,0,482,482,"1753","",0,"","","",2,0,0,[],""],["carrizo_salta-n1754-01",3,"A la mujer cuando enviuda,\nPonerle trama,\nPor seguir a los mozos,\nSe desparrama.",3,1,0,48,"",6,4,"aa",90,0,-1,0,482,482,"1754","",0,"","","",1,0,0,[],""],["carrizo_salta-n1755-01",3,"A la mujer nunca es bueno,\nNi retarla ni sobarla,\nEl remedio que ellas tienen,\nDe no matarlas, dejarlas.",3,1,0,48,"",0,4,"aa",-1,0,-1,0,482,482,"1755","",0,"","","",1,0,0,[],""],["carrizo_salta-n1756-01",3,"A las mujeres casadas,\nQuererlas es un dolor,\nY después dirá la gente:\n—Ahí va ese descasador.",3,1,0,48,"",0,4,"o",72,0,-1,0,482,482,"1756","",0,"","","",1,0,0,[],""],["carrizo_salta-n1757-01",3,"Al asomar el bigote,\nTambién el amor asoma,\nY el hombre se descalzona,\nProcurando una mujer.",3,1,0,48,"",5,4,"e",-1,0,-1,0,482,482,"1757","",0,"","","",1,0,0,[],""],["carrizo_salta-n1758-01",3,"Al corral vuelve la oveja,\nY la paloma a su nido,\nSólo al corazón no vuelve,\nLa ilusión que se ha perdido.",3,1,0,48,"",0,4,"io",101,0,-1,0,482,482,"1758","",0,"","","",1,0,0,[],""],["carrizo_salta-n1759-01",3,"Al más sabio le pregunto,\nSobre el asunto de amor,\nSi qué sería mejor,\nOlvidar o ser traidor.",3,1,0,48,"",0,4,"o",72,0,-1,0,482,482,"1759","",0,"","","",1,0,0,[],""],["carrizo_salta-n1760-01",3,"A lo lejos se conoce,\nLa mujer enamorada;\nLe palpita el corazón,\nComo paloma trampiada.",3,1,0,48,"",0,4,"aa",49,0,-1,0,482,482,"1760","",0,"","","",1,0,0,[],""],["carrizo_salta-n1761-01",3,"A los hombres hoy en día,\nNo se les puede mirar,\nPorque en seguidita dicen:\nEsta me quiere pescar.",3,1,0,48,"",0,4,"a",21,0,-1,0,482,482,"1761","",0,"","","",1,0,0,[],""],["carrizo_salta-n1762-01",3,"Al que es pobre y quiere novia,\nLas viejas se vuelven fieras,\nAhí lo tienen dando vueltas,\nComo mula panadera.",3,1,0,48,"",0,4,"ea",-1,0,-1,0,482,482,"1762","",0,"","","",1,0,0,[],""],["carrizo_salta-n1763-01",3,"Al que es rico y quiere novia,\nLas viejas no hallan qué hacer,\nSe vuelven puros cumplidos,\nA ver si la hacen caer.",3,1,0,48,"",0,4,"e",20,0,-1,0,482,482,"1763","",0,"","","",1,0,0,[],""],["carrizo_salta-n1764-01",3,"Al que te quiera, querelo,\nAl que te adore, adoralo,\nAl que te juegue vileza,\nPor mi consejo, dejalo.",3,1,0,48,"",0,4,"ao",71,0,-1,0,482,482,"1764","",0,"","","",1,0,0,[],""],["carrizo_salta-n1764-a-01",3,"La que te quiera, querela,\nLa que te adora, adorala,\nLa que te muestre vileza,\nPor mi consejo, dejala.",3,1,0,48,"",0,4,"aa",330,0,-1,0,483,483,"1764-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1765-01",3,"Amarguras he pasado,\nCon el amor que hace maña,\nY más amarga había sido,\nLa desgracia que acompaña.",3,1,0,48,"",0,4,"aa",213,0,-1,0,483,483,"1765","",0,"","","",1,0,0,[],""],["carrizo_salta-n1766-01",3,"¡Amiguito de fulano!\nLe voy a dar un consejo,\nQue no deje de querer,\nAunque se rompa de viejo.",3,1,0,48,"",0,4,"eo",264,0,-1,0,483,483,"1766","",0,"","","",4,0,0,[],""],["carrizo_salta-n1767-01",3,"A mí me dicen el tonto,\nPorque me paro andequiera,\nMás tontas son las mujeres,\nQue quieren a cualesquiera.",3,1,0,48,"",0,4,"ea",44,0,-1,0,483,483,"1767","",0,"","","",4,0,0,[],""],["carrizo_salta-n1768-01",3,"Amores escondidos,\nPor tiempo largo,\nSi en tragedia no acaban,\nSerá milagro.",3,1,0,48,"",6,4,"ao",-1,0,-1,0,483,483,"1768","",0,"rm_t4, palau_cantares, preciso_coleccion","","",4,0,0,[],""],["carrizo_salta-n1769-01",3,"Amores tuve,\nTodo se acaba,\nNo hay bien que dure,\nNi penas largas.",3,1,0,48,"",6,4,"aa",-1,0,-1,0,483,483,"1769","",0,"","","",1,0,0,[],""],["carrizo_salta-n1770-01",3,"Amor es una senda,\nTan sin camino,\nQue quien va más derecho,\nVa más perdido.",3,1,0,48,"",6,4,"io",-1,0,-1,0,483,483,"1770","",0,"","","",2,0,0,[],""],["carrizo_salta-n1771-01",3,"Antes cuando era chiquito,\nNo sabía lo que era amor,\nAhora ya grandecito,\nLo lamento y con dolor.",3,1,0,48,"",1,4,"o",72,0,-1,0,483,483,"1771","",0,"","","",12,0,0,[],""],["carrizo_salta-n1772-01",3,"Antes cuando era chiquito,\nNo sabía lo que era amor,\nAhora que soy grandecito,\nSe me presenta el dolor.",3,1,0,48,"",1,4,"o",72,0,-1,0,483,483,"1772","",0,"","","",12,0,0,[],""],["carrizo_salta-n1773-01",3,"Antes cuando era chiquito,\nSombrerito valenciano,\nAhora que soy grandecito,\nConsejos me dan en vano.",3,1,0,48,"",1,4,"ao",81,0,-1,0,483,483,"1773","",0,"","","",12,0,0,[],""],["carrizo_salta-n1774-01",3,"Aquel que no tenga amores,\nNo se pare de llorar,\nQue para llorar son pocas,\nTodas las aguas del mar.",3,1,0,48,"",0,4,"a",21,0,-1,0,483,483,"1774","",0,"","","",1,0,0,[],""],["carrizo_salta-n1775-01",3,"A aquel que vive queriendo,\nNo se le debe ocultar,\nQue la ausencia y el olvido,\nNo se saben separar.",3,1,0,48,"",0,4,"a",21,0,-1,0,483,483,"1775","",0,"","","",1,0,0,[],""],["carrizo_salta-n1776-01",3,"A tu mujer, si te cela,\nConvídale mazamorra,\nY si te sigue celando,\nSeguile mazamorriando.",3,1,0,48,"",5,4,"ao",33,0,-1,0,483,483,"1776","",0,"","","",1,0,0,[],""],["carrizo_salta-n1777-01",3,"A un amante apasionado,\nLo vide querer sacar,\nCon un eslabón de seda,\nCentellas de un pedernal.",3,1,0,48,"",0,4,"a",-1,0,-1,0,483,483,"1777","",0,"","","",1,0,0,[],""],["carrizo_salta-n1779-01",3,"¡Ay, mi señor de fulano!\nNunca se fie en mujer,\nMire que lo han de dejar,\nArando sin tener buey.",3,1,0,48,"",0,4,"e",-1,0,-1,0,484,484,"1779","",0,"","","",1,0,0,[],""],["carrizo_salta-n1780-01",3,"Caballero de fulano!\nNo le haga caso a la suerte,\nQue se va cuando ella quiere,\nVuelve cuando se divierte.",3,1,0,48,"",0,4,"ee",-1,0,-1,0,484,484,"1780","",0,"","","",36,0,0,[],""],["carrizo_salta-n1781-01",3,"Callate, no le hagas caso!\nNo hagas tanto sentimiento,\nTratalo como lo trato,\nDejá las cosas pal tiempo.",3,1,0,48,"",0,4,"eo",-1,0,-1,0,484,484,"1781","",0,"","","",1,0,0,[],""],["carrizo_salta-n1785-01",3,"Como pajarito triste,\nQue salta de rama en rama,\nAsí el varón es sin culpa,\nCuando la mujer lo llama.",3,1,0,48,"",0,4,"aa",90,0,-1,0,484,484,"1785","",0,"","","",2,0,0,[],""],["carrizo_salta-n1786-01",3,"¡Corazón sin experiencia!\nNo te empeñes en amar,\nQue después te ha de pesar,\nEl no hallar correspondencia.",3,1,0,48,"",11,4,"ea",46,0,-1,0,484,484,"1786","",0,"","","",1,0,0,[],""],["carrizo_salta-n1787-01",3,"Cuando se quieran casar,\nAbran los ojos primero,\nPorque el engaño siempre anda,\nCon el casao y el soltero.",3,1,0,48,"",3,4,"eo",38,0,-1,0,484,484,"1787","",0,"","","",1,0,0,[],""],["carrizo_salta-n1788-01",3,"De dos que viven amando,\nAsí la pasión entiendo:\nEl hombre jura mintiendo,\nLa mujer miente jurando.",3,1,0,48,"",11,4,"ao",33,0,-1,0,484,484,"1788","",0,"","","",1,0,0,[],""],["carrizo_salta-n1789-01",3,"Dejala al agua correr,\nDejalo al verde brotar,\nDejalo al triste que llore,\nLlorando se ha i consolar.",3,1,0,48,"",0,4,"a",21,0,-1,0,484,484,"1789","",0,"","","",1,0,0,[],""],["carrizo_salta-n1790-01",3,"De los delirios de amor,\nNadie se debe fiar,\nPorque ellos se desvanecen,\nComo la espuma del mar.",3,1,0,48,"",0,4,"a",21,0,-1,0,484,484,"1790","",0,"","","",3,0,0,[],""],["carrizo_salta-n1791-01",3,"El amar prenda con dueño,\nNo es amor sino dolor,\nAmar bien pa que otro goce,\nEs el tormento mayor.",3,1,0,48,"",0,4,"o",72,0,-1,0,484,484,"1791","",0,"","","",1,0,0,[],""],["carrizo_salta-n1792-01",3,"El amor como las flores,\nTiene espinas penetrantes,\nPara un placer mil dolores,\nTiene la vida de amante.",3,1,0,48,"",0,4,"ae",-1,0,-1,0,485,485,"1792","",0,"","","",2,0,0,[],""],["carrizo_salta-n1793-01",3,"El amor es un bichito,\nQue por los ojos se mete,\nY llegando al corazón,\nDa fatiguitas de muerte.",3,1,0,48,"",0,4,"ee",-1,0,-1,0,485,485,"1793","",0,"","","",10,0,0,[],""],["carrizo_salta-n1794-01",3,"El amor es un niño,\nQue cuando nace,\nMientras más chiquitito,\nMás satisface.",3,1,0,48,"",6,4,"ae",84,0,-1,0,485,485,"1794","",0,"","","",2,0,0,[],""],["carrizo_salta-n1795-01",3,"El árbol del cariño,\nDos ramas tiene.\nLa una produce celos,\nLa otra desdenes.",3,1,0,48,"",6,4,"ee",-1,0,-1,0,485,485,"1795","",0,"","","",2,0,0,[],""],["carrizo_salta-n1796-01",3,"El bocado del amor,\nEs más dulce que la miel,\nPero en ciertas ocasiones,\nAmarga como la hiel.",3,1,0,48,"",0,4,"e",32,0,-1,0,485,485,"1796","",0,"","","",2,0,0,[],""],["carrizo_salta-n1797-01",3,"El hombre casado,\nDebe atender,\nA los cuernitos,\nDe su mujer.",3,1,0,48,"",6,4,"e",20,0,-1,0,485,485,"1797","",0,"","","",2,0,0,[],""],["carrizo_salta-n1797-a-01",3,"El hombre casado\nDebe atender,\nA sus hijitos,\nY a su mujer.",3,1,0,48,"",6,4,"e",20,0,-1,0,485,485,"1797-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n1798-01",3,"El hombre cuando se casa,\nEs como si se muriera,\nSólo mintiendo podrá,\nHallar mujer que lo quiera.",3,1,0,48,"",0,4,"ea",44,0,-1,0,485,485,"1798","",0,"","","",2,0,0,[],""],["carrizo_salta-n1799-01",3,"El hombre cuando se casa,\nHa de saber su deber,\nCon esmero ha de cuidar,\nSu caballo y su mujer.",3,1,0,48,"",0,4,"e",20,0,-1,0,485,485,"1799","",0,"","","",2,0,0,[],""],["carrizo_salta-n1800-01",3,"El hombre que a las faldas,\nLes tiene apego,\nNo es hombre de veras,\nEs un borrego.",3,1,0,48,"",6,4,"eo",29,0,-1,0,485,485,"1800","",0,"","","",1,0,0,[],""],["carrizo_salta-n1801-01",3,"El que quiera ser querido,\nNunca se debe ausentar,\nQue juntos suelen andar,\nLa ausencia con el olvido.",3,1,0,48,"",11,4,"io",101,0,-1,0,485,485,"1801","",0,"","","",1,0,0,[],""],["carrizo_salta-n1802-01",3,"El querer es un placer,\nCuando uno es correspondido,\nPero querer por querer,\nYo no le encuentro sentido.",3,1,0,48,"",1,4,"io",101,0,-1,0,485,485,"1802","",0,"","","",1,0,0,[],""],["carrizo_salta-n1803-01",3,"El querer y el ser querido,\nTodo está puesto en balanza,\nEl querer es apetito,\nY el olvidar es venganza.",3,1,0,48,"",0,4,"aa",163,0,-1,0,485,485,"1803","",0,"","","",1,0,0,[],""],["carrizo_salta-n1804-01",3,"En cuestiones de querer,\nNo se puede dar consejos,\nQue en la ciencia del amor,\nNo hay ni sabios ni maestros.",3,1,0,48,"",0,4,"eo",-1,0,-1,0,485,485,"1804","",0,"","","",1,0,0,[],""],["carrizo_salta-n1805-01",3,"En el árbol del amor,\nLas hojas son ilusiones,\nSe caen si las marchitan,\nLos ingratos corazones.",3,1,0,48,"",0,4,"oe",34,0,-1,0,486,486,"1805","",0,"","","",1,0,0,[],""],["carrizo_salta-n1806-01",3,"En el trance del amor,\nNo hay parientes, no hay hermanos,\nEl más verdadero miente,\nY el más amigo es tirano.",3,1,0,48,"",0,4,"ao",-1,0,-1,0,486,486,"1806","",0,"","","",1,0,0,[],""],["carrizo_salta-n1807-01",3,"En el valle está lloviendo,\nEn el alto está nevando,\nMi vidita, en el desierto,\nDe rama en rama volando.",3,1,0,48,"",0,4,"ao",33,0,-1,0,486,486,"1807","",0,"","","",1,0,0,[],""],["carrizo_salta-n1808-01",3,"En las huellas del cariño,\nBuscá rico si querís,\nY cuando te deje el rico,\nDel pobre te acordarís.",3,1,0,48,"",0,4,"i",58,0,-1,0,486,486,"1808","",0,"","","",1,0,0,[],""],["carrizo_salta-n1809-01",3,"En las huellas de la vida,\nY en los trances del amor,\nEl más verdadero miente,\nY el más amigo es traidor.",3,1,0,48,"",0,4,"o",72,0,-1,0,486,486,"1809","",0,"","","",1,0,0,[],""],["carrizo_salta-n1810-01",3,"Gallina que cacarea,\nEs señal que ha puesto huevo,\nY mujer que anda celando,\nEs señal que ha puesto cuerno.",3,1,0,48,"",0,4,"eo",-1,0,-1,0,486,486,"1810","",0,"","","",1,0,0,[],""],["carrizo_salta-n1811-01",3,"Hay pesares en el mundo,\nQue atormentan el sentido,\nEsperar a quien no viene,\nQuerer y no ser querido.",3,1,0,48,"",0,4,"io",101,0,-1,0,486,486,"1811","",0,"","","",1,0,0,[],""],["carrizo_salta-n1812-01",3,"Hay ojos que se están viendo,\nY no se pueden hablar,\nSe consuelan con decir:\n—El tiempo dará lugar.",3,1,0,48,"",0,4,"a",21,0,-1,0,486,486,"1812","",0,"","","",1,0,0,[],""],["carrizo_salta-n1812-a-01",3,"El tiempo dará lugar,\nPero no se sabe cuándo,\nPorque para mí los tiempos,\nCada vez se van mudando.",3,1,0,48,"",0,4,"ao",33,0,-1,0,486,486,"1812-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1813-01",3,"La aceituna en el molino,\nHace aceite y alpechín,\nLa mujer que quiere a muchos,\nNo puede tener buen fin.",3,1,0,48,"",0,4,"i",211,0,-1,0,486,486,"1813","",0,"","","",4,0,0,[],""],["carrizo_salta-n1814-01",3,"La nieve crece en invierno,\nLas plantas en el verano,\nEl amor crece en el mundo,\nDurante todito el año.",3,1,0,48,"",0,4,"ao",-1,0,-1,0,486,486,"1814","",0,"","","",1,0,0,[],""],["carrizo_salta-n1815-01",3,"La que trata los hombres,\nCon malos modos;\nSin gustarle ninguno,\nLe gustan todos.",3,1,0,48,"",6,4,"oo",418,0,-1,0,486,486,"1815","",0,"","","",1,0,0,[],""],["carrizo_salta-n1816-01",3,"Lárguese para adelante,\nLlevando el amor de guía,\nEl amor con la constancia,\nSe han de encontrar algún día.",3,1,0,48,"",0,4,"ia",0,0,-1,0,486,486,"1816","",0,"","","",1,0,0,[],""],["carrizo_salta-n1817-01",3,"Las flores y los cariños,\nHay que saberlos cuidar,\nLa flor sin agua se seca,\nAmor, sin beso se va.",3,1,0,48,"",0,4,"a",-1,0,-1,0,486,486,"1817","",0,"","","",1,0,0,[],""],["carrizo_salta-n1818-01",3,"La viborilla del campo,\nEn el pasto no parece,\nLa moza que quiere a dos,\nAlgún castigo merece.",3,1,0,48,"",0,4,"ee",64,0,-1,0,487,487,"1818","",0,"","","",3,0,0,[],""],["carrizo_salta-n1818-02",3,"La viborilla del campo,\nDe verde ya no aparece,\nLos hombres engañadores,\nTrescientos palos merecen.",3,1,0,48,"",0,4,"ee",-1,0,-1,0,487,487,"1818","",0,"","","",3,0,0,[],""],["carrizo_salta-n1819-01",3,"La viborilla del campo,\nEn el verde no aparece,\nA la mujer más revelde,\nEl hombre constante vence.",3,1,0,48,"",0,4,"ee",-1,0,-1,0,487,487,"1819","",0,"","","",3,0,0,[],""],["carrizo_salta-n1820-01",3,"Le aconsejo, amigo mío,\nQue no quiera con firmeza,\nNo hay firmeza en la mujer,\nEn lo más llano trompieza.",3,1,0,48,"",0,4,"ea",108,0,-1,0,487,487,"1820","",0,"","","",1,0,0,[],""],["carrizo_salta-n1821-01",3,"Los besos de las chicas,\nDe quince a veinte,\nMachan más a los hombres,\nQue el aguardiente.",3,1,0,48,"",6,4,"ee",-1,0,-1,0,487,487,"1821","",0,"","","",1,0,0,[],""],["carrizo_salta-n1822-01",3,"No hay amigo verdadero,\nEn el trance del amor,\nEl más cobarde es valiente,\nY el más amigo traidor.",3,1,0,48,"",0,4,"o",72,0,-1,0,487,487,"1822","",0,"","","",2,0,0,[],""],["carrizo_salta-n1823-01",3,"No sólo el que debe muertes,\nAnda al sereno y al viento,\nTambién el que anda en amores,\nLleva la vida a los tientos.",3,1,0,48,"",0,4,"eo",-1,0,-1,0,487,487,"1823","",0,"","","",2,0,0,[],""],["carrizo_salta-n1823-02",3,"No te dispongas casar,\nSi sos viejo y achacoso,\nPorque tu mujer ha i ser,\nPa que sirva a cualquier mozo.",3,1,0,48,"",0,4,"oo",156,0,-1,0,487,487,"1823","",0,"","","",1,0,0,[],""],["carrizo_salta-n1825-01",3,"Para curar achaques,\nDe amores necios,\nNo hay mejor que los parches,\nDe los desprecios.",3,1,0,48,"",6,4,"eo",419,0,-1,0,487,487,"1825","",0,"","","",1,0,0,[],""],["carrizo_salta-n1826-01",3,"Sabrás que rodando el mundo,\nY circulando en su rueda,\nUna ingratitud se paga,\nSiempre en la misma moneda.",3,1,0,48,"",0,4,"ea",266,0,-1,0,487,487,"1826","",0,"","","",1,0,0,[],""],["carrizo_salta-n1827-01",3,"Salomón, con ser tan sabio,\nSólo un consejo me dió,\nQue a las niñas quiera mucho,\nPero que las ruegue, no.",3,1,0,48,"",0,4,"o",2,0,-1,0,487,487,"1827","",0,"","","",2,0,0,[],""],["carrizo_salta-n1828-01",3,"Si de cristales fueran,\nLos corazones,\n¡Qué claras se verían\nLas intenciones!",3,1,0,48,"",6,4,"oe",34,0,-1,0,487,487,"1828","",0,"","","",3,0,0,[],""],["carrizo_salta-n1829-01",3,"Si estás de novia, cuídate,\nAconseja San Antonio,\nA toda mujer soltera,\nSiempre las tienta el demonio.",3,1,0,48,"",0,4,"oo",169,0,-1,0,487,487,"1829","",0,"","","",1,0,0,[],""],["carrizo_salta-n1830-01",3,"Toda mujer celosa,\nEn la vista es conocida,\nLos ojos le viborean,\nComo una tigra parida.",3,1,0,48,"",0,4,"ia",37,0,-1,0,487,487,"1830","",0,"","","",1,0,0,[],""],["carrizo_salta-n1831-01",3,"Todas las cosas son buenas,\nAntes de echarse a perder,\nLa leche antes de agriarse,\nY lo mismo la mujer.",3,1,0,48,"",0,4,"e",20,0,-1,0,488,488,"1831","",0,"","","",1,0,0,[],""],["carrizo_salta-n1832-01",3,"Todas las ilusiones,\nQue el amor fragua,\nSon como las espumas,\nQue lleva el agua.",3,1,0,48,"",6,4,"aa",383,0,-1,0,488,488,"1832","",0,"","","",3,0,0,[],""],["carrizo_salta-n1833-01",3,"Todos dicen: ¡pobre mozo!\nPor el amor se ha perdido,\nSalomón, con ser tan sabio,\nPor el amor fué vencido.",3,1,0,48,"",0,4,"io",101,0,-1,0,488,488,"1833","",0,"","","",1,0,0,[],""],["carrizo_salta-n1834-01",3,"Yo no sé por qué será,\nTodo aquel que ama, padece,\nDonde reina el imposible,\nEs donde el amor más crece.",3,1,0,48,"",0,4,"ee",64,0,-1,0,488,488,"1834","",0,"","","",1,0,0,[],""],["carrizo_salta-n1835-01",3,"Yo soy como mala yerba,\nMe arrancan, vuelvo a nacer,\nNo hay animal que se pierda,\nEn la huella del querer.",3,1,0,48,"",0,4,"e",20,0,-1,0,488,488,"1835","",0,"","","",1,0,0,[],""],["carrizo_salta-n1836-01",3,"Acatarrado me hallo,\nRonco del pecho,\nTal vez cantando un poco,\nMe haga provecho.",3,1,0,49,"",6,4,"eo",60,0,-1,0,490,490,"1836","",0,"","","",1,0,0,[],""],["carrizo_salta-n1837-01",3,"Agora ya estoy llegando,\nDe aquel cerro pedregoso,\nOyendo carnestoliendas,\nCuasi me muero de gozo.",3,1,0,49,"",0,4,"oo",156,0,-1,0,490,490,"1837","",0,"","","",1,0,0,[],""],["carrizo_salta-n1838-01",3,"Ah, mi querido fulano!\nCuerpito de espiga i trigo,\nYo no le canto pa Vd.,\nNo sea tan entremetido.",3,1,0,49,"",0,4,"io",-1,0,-1,0,490,490,"1838","",0,"","","",3,0,0,[],""],["carrizo_salta-n1839-01",3,"¡Ah, mi querido fulano!\nÚnico amigo querido,\nPor Vd. he de atravesar,\nArroyos, mares y ríos.",3,1,0,49,"",0,4,"io",-1,0,-1,0,490,490,"1839","",0,"","","",3,0,0,[],""],["carrizo_salta-n1840-01",3,"Al cura has de preguntar,\nCuando esté diciendo misa,\nSi será bueno cantar,\nEl Miércoles de Ceniza.",3,1,0,49,"",1,4,"ia",420,0,-1,0,490,490,"1840","",0,"","","",1,0,0,[],""],["carrizo_salta-n1841-01",3,"Alegre carnavalcito,\nAlegrito pasajero,\nDespués de los cinco días,\nSe manda a mudar ligero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,490,490,"1841","",0,"","","",1,0,0,[],""],["carrizo_salta-n1842-01",3,"Alegre mocita hi sio,\nAlegre vieja hi morir,\nCuando oigo sonar la caja.\nMe amanezco sin dormir.",3,1,0,49,"",0,4,"i",157,0,-1,0,490,490,"1842","",0,"","","",1,0,0,[],""],["carrizo_salta-n1843-01",3,"Alegre mocito hi sio,\nAlegre como mi madre,\n¿Cómo no hi de ser alegre,\nSiendo de su misma sangre?",3,1,0,49,"",0,4,"ae",-1,0,-1,0,490,490,"1843","",0,"","","",3,0,0,[],""],["carrizo_salta-n1844-01",3,"Alegre mocito hi sio,\nAlegre toda la vida,\n¡Cómo no hi de ser alegre,\nSi soy de tan buena cría!",3,1,0,49,"",0,4,"ia",-1,0,-1,0,490,490,"1844","",0,"","","",3,0,0,[],""],["carrizo_salta-n1845-01",3,"Alegre mocito hi sio,\nAsí nomás pienso ser,\nMe quieren privar mis gustos,\nY eso es lo que no han de ver.",3,1,0,49,"",0,4,"e",20,0,-1,0,490,490,"1845","",0,"","","",3,0,0,[],""],["carrizo_salta-n1846-01",3,"Alegre muchacho hi sío,\nAlegrito siempre vivo,\nTomo vino en copa de asta,\nTocando una panza y chivo.",3,1,0,49,"",0,4,"io",351,0,-1,0,490,490,"1846","",0,"","","",1,0,0,[],""],["carrizo_salta-n1847-01",3,"Alegres somos nosotros,\nOtro alegre no ha de haber,\nNi en Salta, ni en Buenos Aires,\nNi en España ha de nacer.",3,1,0,49,"",0,4,"e",20,0,-1,0,490,490,"1847","",0,"","","",1,0,0,[],""],["carrizo_salta-n1848-01",3,"Alegrita soy, señores,\nDesde el día que he nacido,\n¡Cómo no hi de ser alegre,\nSi mi padre alegre ha sido!",3,1,0,49,"",0,4,"io",101,0,-1,0,491,491,"1848","",0,"","","",1,0,0,[],""],["carrizo_salta-n1849-01",3,"Alojita de algarroba,\nDe la vainilla amarilla,\n¿Cómo me queris voltiar,\nSin echarme zancadilla?",3,1,0,49,"",0,4,"ia",162,0,-1,0,491,491,"1849","",0,"","","",2,0,0,[],""],["carrizo_salta-n1850-01",3,"Allá va \"El Gato\" criollo,\nNo pa los gringos,\nLa carrera se corre,\nCon buenos pingos.",3,1,0,49,"",6,4,"io",421,0,-1,0,491,491,"1850","",0,"","","",1,0,0,[],""],["carrizo_salta-n1851-01",3,"Al veinte i Febrero,\nCayó Carnaval,\nCausa mi gaucha,\nPerdí mi caudal.",3,1,0,49,"",6,4,"a",1,0,-1,0,491,491,"1851","",0,"","","",1,0,0,[],""],["carrizo_salta-n1852-01",3,"Allá viene Carnaval,\nPor la costa i Tala Pampa,\nSe viene haciendo la fiesta,\nPor Guachipa i Coripampa.",3,1,0,49,"",0,4,"aa",413,0,-1,0,491,491,"1852","",0,"","","",4,0,0,[],""],["carrizo_salta-n1853-01",3,"Allá viene Carnaval,\nPor el campo La Jarilla,\nAquí lo estoy aguardando,\nCon un caldo de gallina.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,491,491,"1853","",0,"","","",4,0,0,[],""],["carrizo_salta-n1854-01",3,"Allá viene Carnaval,\nPor la cuesta i Tolombón,\nCon su machito cargado,\nDándole hasta el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,491,491,"1854","",0,"","","",4,0,0,[],""],["carrizo_salta-n1855-01",3,"Allá viene el Carnaval,\nPor la costa el Saladillo,\n¡Cómo quedarán los mozos,\nSin un medio en los bolsillos!",3,1,0,49,"",0,4,"io",-1,0,-1,0,491,491,"1855","",0,"","","",1,0,0,[],""],["carrizo_salta-n1856-01",3,"Allá viene don fulano,\nLevantando polvareda,\nEn su potro cari blanco,\nCon su zaino de carrera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,491,491,"1856","",0,"","","",1,0,0,[],""],["carrizo_salta-n1857-01",3,"¡Amiguito de fulano!\nVerdecito como yuyo,\n¡Como no hi de cantar yo,\nCuando cantan los coyuyos!",3,1,0,49,"",0,4,"uo",-1,0,-1,0,491,491,"1857","",0,"","","",4,0,0,[],""],["carrizo_salta-n1858-01",3,"A mí me llaman \"El Fiero\",\nY por fiero me han premiado,\nMás vale un fiero dichoso,\nQue un hermoso desgraciado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,491,491,"1858","",0,"","","",1,0,0,[],""],["carrizo_salta-n1858-a-01",3,"Todos me dicen: \"El Fiero\",\nY de fiero soy premiado,\nMejor ser fiero dichoso,\nNo donoso y desgraciado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,491,491,"1858-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1859-01",3,"A mi no me gusta el vino,\nNi tampoco el aguardiente,\nA mí me gustan las niñas,\nDe los quince hasta los veinte.",3,1,0,49,"",0,4,"ee",-1,0,-1,0,492,492,"1859","",0,"","","",2,0,0,[],""],["carrizo_salta-n1860-01",3,"Andoy queriendo,\nDueña no tengo,\nLa andoy siguiendo,\n¡Velay, velay!",3,1,0,49,"",6,4,"a",-1,0,-1,0,492,492,"1860","",0,"","","",1,0,0,[],""],["carrizo_salta-n1861-01",3,"Antes cuando era chiquito,\nNo supe lo que es querer,\nAhora que ya soy grande,\nYa necesito mujer.",3,1,0,49,"",0,4,"e",20,0,-1,0,492,492,"1861","",0,"","","",12,0,0,[],""],["carrizo_salta-n1862-01",3,"Antes, cuando era chiquito,\nTodas me querían besar,\nAhora que grandecito,\nNo me quieren ni mirar.",3,1,0,49,"",1,4,"a",21,0,-1,0,492,492,"1862","",0,"","","",12,0,0,[],""],["carrizo_salta-n1863-01",3,"Aquí es pampa,\nAllá es llano.\nTengo sembrado,\nCanela y clavo.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,492,492,"1863","",0,"","","",1,0,0,[],""],["carrizo_salta-n1864-01",3,"Aquí está este fulanito,\nQue es muy clarito al hablar,\nCuando promete una cosa,\nCuente con seguridad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,492,492,"1864","",0,"","","",1,0,0,[],""],["carrizo_salta-n1865-01",3,"Aquí está este mataquito,\nNacido en las tolderías,\nAunque mataquito fiero,\nPero soy de buena cría.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,492,492,"1865","",0,"","","",1,0,0,[],""],["carrizo_salta-n1866-01",3,"Aquí está este pobre Cruz,\nTan alegre y forastero,\nCantando se ha i divertir,\nEn estos pagos ajenos.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,492,492,"1866","",0,"","","",1,0,0,[],""],["carrizo_salta-n1867-01",3,"Aquí hi venio a cantar,\nAunque no me han invitado,\nAgora que estoy aquí,\nMe daré por convidado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,492,492,"1867","",0,"","","",1,0,0,[],""],["carrizo_salta-n1868-01",3,"Aquí hi venio, señores,\nAunque no me han convidao,\nComo soy tan desgraciao,\nMilagro no me han botao.",3,1,0,49,"",0,4,"ao",98,0,-1,0,492,492,"1868","",0,"","","",1,0,0,[],""],["carrizo_salta-n1869-01",3,"Aquí hi venido, señores,\nComo aquel que no hace nada,\nA dejarles la coplita,\nY a llevarles la tonada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,492,492,"1869","",0,"","","",1,0,0,[],""],["carrizo_salta-n1870-01",3,"Aquí no hay cura ni alcalde,\nTodos se casan de balde.\nTienen que verse sin dueña,\nLos hombres que llegan tarde.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,492,492,"1870","",0,"","","",1,0,0,[],""],["carrizo_salta-n1871-01",3,"Arribita nomás canto,\nYa se pasa carnaval,\n¡Quién sabe si para el año,\nVolveremos a cantar!",3,1,0,49,"",0,4,"a",-1,0,-1,0,492,492,"1871","",0,"","","",1,0,0,[],""],["carrizo_salta-n1872-01",3,"Así cantando y bailando,\nChichita me estoy ganando,\nComo soy mozo alvertido,\nBuena vida estoy pasando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,492,492,"1872","",0,"","","",2,0,0,[],""],["carrizo_salta-n1873-01",3,"Así cantando y bailando,\nYo sabía pasar la vida,\nEsta noche en esta rueda,\nMañana en otra cuadrilla.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,492,492,"1873","",0,"","","",2,0,0,[],""],["carrizo_salta-n1874-01",3,"Así para Carnaval,\nDivididos en cuadrillas,\nHay que cantar y bailar,\nDurante los cuatro días.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,492,492,"1874","",0,"","","",1,0,0,[],""],["carrizo_salta-n1875-01",3,"Aunque se sequen los troncos,\nComo nos queden las guías,\n¡Qué le hemos de hacer, vidita!\nSomos de una misma cría.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,493,493,"1875","",0,"","","",1,0,0,[],""],["carrizo_salta-n1876-01",3,"Ayer me han llegado notas,\nLas notas del Carnaval,\nLa letra viene diciendo:\nMañana me vua casar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,493,493,"1876","",0,"","","",1,0,0,[],""],["carrizo_salta-n1877-01",3,"¡Ahijuay, puta Carnaval!\n¡Que mucho siento dejarte!\nSi al otro mundo te fueras,\nAllá me fuera a adorarte.",3,1,0,49,"",0,4,"ae",8,0,-1,0,493,493,"1877","",0,"","","",3,0,0,[],""],["carrizo_salta-n1878-01",3,"¡Ahijuay, puta Carnaval!\nT' hi cantar y t' hi bailar,\nY el Miércoles de Ceniza,\nTambién t' hi cacharpayar.",3,1,0,49,"",0,4,"a",21,0,-1,0,493,493,"1878","",0,"","","",3,0,0,[],""],["carrizo_salta-n1879-01",3,"¡Ahijuay, puta Carnaval!\nYa bastante me has molido,\nPor hacer la cacharpaya,\nCuatro noches no hi dormido.",3,1,0,49,"",0,4,"io",101,0,-1,0,493,493,"1879","",0,"","","",3,0,0,[],""],["carrizo_salta-n1880-01",3,"¡Ahijuna, pucha ñ'Elena!\nPollera y naguas ajenas,\nComo salga a Carnaval,\nDe nada se le da pena.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,493,493,"1880","",0,"","","",2,0,0,[],""],["carrizo_salta-n1881-01",3,"¡Ahíjuna, puta, mocito!\n¡Qué madre lo pariría!\nEl se llama Poca pena,\nSu apellido es Alegría.",3,1,0,49,"",0,4,"ia",0,0,-1,0,493,493,"1881","",0,"","","",1,0,0,[],""],["carrizo_salta-n1882-01",3,"¡Ayudame cuadrillita,\nA defender mi parada,\nEsta fiesta va a durar,\nLo menos una semana.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,493,493,"1882","",0,"","","",1,0,0,[],""],["carrizo_salta-n1883-01",3,"Bailecito que me gusta,\nEs el de la chacarera,\nPorque les digo a las niñas,\nJugando, pero en de veras.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,493,493,"1883","",0,"","","",1,0,0,[],""],["carrizo_salta-n1884-01",3,"¡Caballero de fulano!\nEstrellita de la mar,\n¡Qué rica la agua que trae,\nEn un vaso de cristal!",3,1,0,49,"",0,4,"a",-1,0,-1,0,493,493,"1884","",0,"","","",36,0,0,[],""],["carrizo_salta-n1885-01",3,"¡Caballero de fulano!\nHombre lindo y hombre noble,\nNo se le haga cuesta arriba,\nDe gastar un peso doble.",3,1,0,49,"",0,4,"oe",422,0,-1,0,493,493,"1885","",0,"","","",36,0,0,[],""],["carrizo_salta-n1886-01",3,"¡Caballero don fulano!\n¿Qué lo ha traido a estos rincones?\n¿Ha venido a cortar montes,\nO a cautivar corazones?",3,1,0,49,"",0,4,"oe",-1,0,-1,0,493,493,"1886","",0,"","","",2,0,0,[],""],["carrizo_salta-n1887-01",3,"¡Cacharpaya, cacharpaya!\nYa no hay temor que se pierda,\nDespachala que se vaya,\nLleva la marca en la pierna,",3,1,0,49,"",0,4,"ea",-1,0,-1,0,494,494,"1887","",0,"","","",2,0,0,[],""],["carrizo_salta-n1888-01",3,"¡Cachiyuyo de l'orilla!\nRemate de agua florida,\n¡Cachiyuyo de Angastaco,\nYa no hay coca ni tabaco.",3,1,0,49,"",5,4,"ao",423,0,-1,0,494,494,"1888","",0,"","","",1,0,0,[],""],["carrizo_salta-n1889-01",3,"Cada que suena la caja,\nDe alguna pena me olvido,\nPorque no hay cosa más linda,\nQue estar a \"pago y obligo\"",3,1,0,49,"",0,4,"io",-1,0,-1,0,494,494,"1889","",0,"","","",1,0,0,[],""],["carrizo_salta-n1890-01",3,"Campo flor y buena aguada,\nAlambrado de siete hilos,\nCuja, colchón y almohada,\n¡Chinita, vos sos mi amada!",3,1,0,49,"",5,4,"aa",49,0,-1,0,494,494,"1890","",0,"","","",1,0,0,[],""],["carrizo_salta-n1891-01",3,"¡Canta, canta palomita!\n¡Canta flor de maravilla!\nDespedite y vamonós,\nCuando esté clariando el día.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,494,494,"1891","",0,"","","",1,0,0,[],""],["carrizo_salta-n1892-01",3,"Cantemos esta coplita,\nHagamos cacharpayita,\nDigamos al dueño i casa:\n¡Hasta por la mañanita!",3,1,0,49,"",0,4,"ia",50,0,-1,0,494,494,"1892","",0,"","","",1,0,0,[],""],["carrizo_salta-n1893-01",3,"Cantemos la vidalita,\nMedio quitando, quitando,\nComo balan las ovejas,\nCutipando, cutipando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,495,495,"1893","",0,"","","",1,0,0,[],""],["carrizo_salta-n1894-01",3,"¡Canten, canten, compañeros!\nAlegrensén, se alegremos,\nCantaremos todos juntos,\nNinguno se apartaremos.",3,1,0,49,"",0,4,"eo",127,0,-1,0,495,495,"1894","",0,"","","",6,0,0,[],""],["carrizo_salta-n1895-01",3,"¡Canten, canten, compañeros!\n\"La flor del arbol\",\nYo soy salteñita,\nSoy firme en amor.",3,1,0,49,"",0,4,"o",-1,0,-1,0,495,495,"1895","",0,"","","",6,0,0,[],""],["carrizo_salta-n1896-01",3,"¡Canten, canten, compañeros!\nLa tonada es cuadradora,\nEsa la pueden llamar,\nLa carta desveladora.",3,1,0,49,"",0,4,"oa",107,0,-1,0,495,495,"1896","",0,"","","",6,0,0,[],""],["carrizo_salta-n1897-01",3,"¡Canten, canten, compañeros!\nNo se queden como en misa,\nDe la leña se hace brasas,\nDe las brasas las cenizas.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,495,495,"1897","",0,"","","",6,0,0,[],""],["carrizo_salta-n1898-01",3,"¡Canten compañeros míos!\n¿Por qué se quieren callar?\nAl fuego que han encendido,\nNo lo dejen apagar.",3,1,0,49,"",0,4,"a",21,0,-1,0,495,495,"1898","",0,"","","",1,0,0,[],""],["carrizo_salta-n1899-01",3,"¡Caramba, que cantan lindo!\nComo para hacer llorar,\nMe acuerdo de mi vidita,\nCuando le sabía cantar.",3,1,0,49,"",0,4,"a",21,0,-1,0,495,495,"1899","",0,"","","",2,0,0,[],""],["carrizo_salta-n1900-01",3,"¡Caramba, que cantan lindo!\nQue me han hecho tener pena,\nSi me parece que oigo,\nEl llanto de una sirena.",3,1,0,49,"",0,4,"ea",59,0,-1,0,495,495,"1900","",0,"","","",2,0,0,[],""],["carrizo_salta-n1901-01",3,"¡Caramba, que me desvelo!\nPor una que está allá adentro,\nNo es tanto por la persona,\nComo por el movimiento.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,495,495,"1901","",0,"","","",1,0,0,[],""],["carrizo_salta-n1902-01",3,"¡Caramba, que meten bulla!\nEn medio del totoral,\nSi parecen patos viejos,\nQue ya no pueden volar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,495,495,"1902","",0,"","","",1,0,0,[],""],["carrizo_salta-n1903-01",3,"¡Caramba, que se divierten!\n¿Si habrá licencia pa todos?\nAvisemén la verdad,\nSin mostrarme malos modos.",3,1,0,49,"",0,4,"oo",418,0,-1,0,495,495,"1903","",0,"","","",1,0,0,[],""],["carrizo_salta-n1904-01",3,"¡Caramba, que viene lindo!\nAsí que venga a la vuelta,\nQue no se venga enredando,\nComo madeja sin cuenta.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,495,495,"1904","",0,"","","",1,0,0,[],""],["carrizo_salta-n1905-01",3,"¡Carnavalcito han dicho!\nHay que cantar y bailar,\nCon las patitas al aire,\nDevisando El Aguilar.",3,1,0,49,"",0,4,"a",21,0,-1,0,495,495,"1905","",0,"","","",1,0,0,[],""],["carrizo_salta-n1906-01",3,"¡Carnaval dijeron!\n¡Velay, Carnaval!\nAhora no hay que sentarse,\nHay que cantar y bailar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,495,495,"1906","",0,"","","",1,0,0,[],""],["carrizo_salta-n1907-01",3,"Carnaval se va diciendo,\nQue pal año no h a i volver,\nPor milagro que ha venido,\nNo le han dado de comer.",3,1,0,49,"",0,4,"e",20,0,-1,0,496,496,"1907","",0,"","","",1,0,0,[],""],["carrizo_salta-n1908-01",3,"¡Cielito, cielito, sí!\n¡Cielito de tres por ocho!\nQue se empezó a desgranar,\nLo mismo que máiz morocho.",3,1,0,49,"",0,4,"oo",424,0,-1,0,496,496,"1908","",0,"","","",1,0,0,[],""],["carrizo_salta-n1909-01",3,"¡Cielito, cielo que sí!\n¡Cielito, locos están!\nEllos se ausentan cantando,\nQuién sabe si volverán.",3,1,0,49,"",0,4,"a",147,0,-1,0,496,496,"1909","",0,"","","",2,0,0,[],""],["carrizo_salta-n1910-01",3,"¡Cielito, hermoso, sí!\n¡Cielito hermoso!\n¿Qué saco con mirarte,\nSi no te gozo?",3,1,0,49,"",6,4,"oo",156,0,-1,0,496,496,"1910","",0,"","","",1,0,0,[],""],["carrizo_salta-n1911-01",3,"Como moza forastera,\nA todo el mundo pregunto:\n—¿Quién es ese morenito,\nQue está vestido de luto?",3,1,0,49,"",0,4,"uo",-1,0,-1,0,496,496,"1911","",0,"","","",1,0,0,[],""],["carrizo_salta-n1912-01",3,"Como mujer le contesto:\n—Me almiro su proceder,\nAntes de ser suplifalta,\nMe considero mujer.",3,1,0,49,"",0,4,"e",20,0,-1,0,496,496,"1912","",0,"","","",1,0,0,[],""],["carrizo_salta-n1913-01",3,"Con esta copla, señores,\nDe toditos me despido,\nQue mi mamita dirá,\n¿Dónde estará ese perdido?",3,1,0,49,"",0,4,"io",101,0,-1,0,496,496,"1913","",0,"","","",5,0,0,[],""],["carrizo_salta-n1914-01",3,"Con la caja y los palillos,\nCorra la voz que hi venio,\nSuspirando sin consuelo,\nComo gavilán herido.",3,1,0,49,"",0,4,"io",-1,0,-1,0,496,496,"1914","",0,"","","",1,0,0,[],""],["carrizo_salta-n1915-01",3,"Con la cajita en la mano,\nMe a r r i m a b a al mostrador,\nCantando coplas bonitas,\nDespreciando al buen cantor.",3,1,0,49,"",0,4,"o",72,0,-1,0,496,496,"1915","",0,"","","",1,0,0,[],""],["carrizo_salta-n1916-01",3,"¡Con su permiso, señores!\nA sus casas hi llegado,\nMi suerte es tan desgraciada,\n¡De cómo no me han botado!",3,1,0,49,"",0,4,"ao",14,0,-1,0,496,496,"1916","",0,"","","",7,0,0,[],""],["carrizo_salta-n1917-01",3,"¡Con sus permisos, señores!\nEcharé esta relancina,\nDe coplas y de tonadas,\nLlenita está la cocina.",3,1,0,49,"",0,4,"ia",11,0,-1,0,496,496,"1917","",0,"","","",5,0,0,[],""],["carrizo_salta-n1918-01",3,"¡Con su permiso, señora!\nEntraré a su residencia,\nDespués no vaya a decir,\nQue no he pedido licencia.",3,1,0,49,"",0,4,"ea",46,0,-1,0,496,496,"1918","",0,"","","",1,0,0,[],""],["carrizo_salta-n1919-01",3,"Con sus permisos, señores,\nLes cantaré de atrasito,\nY si me dan sus licencias,\nLes cantaré de adentrito.",3,1,0,49,"",0,4,"io",119,0,-1,0,497,497,"1919","",0,"","","",5,0,0,[],""],["carrizo_salta-n1920-01",3,"Con sus permisos, señores,\nUna copla cantaré,\nAunque yo soy medio lerdo,\nTal vez no molestaré.",3,1,0,49,"",0,4,"e",77,0,-1,0,497,497,"1920","",0,"","","",5,0,0,[],""],["carrizo_salta-n1921-01",3,"Cuando canto chacareras,\nMe dan ganas de llorar,\nPorque no tengo caballo,\nNi calchas para ensillar.",3,1,0,49,"",0,4,"a",21,0,-1,0,497,497,"1921","",0,"","","",1,0,0,[],""],["carrizo_salta-n1922-01",3,"Cuando canto esta coplita,\nMe da una corazonada,\nPorque se me representa,\nLa dueña de esta tonada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,497,497,"1922","",0,"","","",2,0,0,[],""],["carrizo_salta-n1922-02",3,"Cuando canto esta coplita,\nMiro a todos de soslayo,\nPorque me acuerdo, vidita,\nDel pago del Pilcomayo.",3,1,0,49,"",1,4,"ao",293,0,-1,0,497,497,"1922","",0,"","","",2,0,0,[],""],["carrizo_salta-n1924-01",3,"Cuando canto esta tonada,\nMe acuerdo de una tontera,\nMe acuerdo cuando cantaba,\nCon los gauchos \"La Frontera\".",3,1,0,49,"",0,4,"ea",44,0,-1,0,497,497,"1924","",0,"","","",1,0,0,[],""],["carrizo_salta-n1925-01",3,"Cuando canto quince días,\nRecién me voy componiendo,\nComo pimpollo de rosa,\nQue recién va floreciendo.",3,1,0,49,"",0,4,"eo",52,0,-1,0,497,497,"1925","",0,"","","",2,0,0,[],""],["carrizo_salta-n1926-01",3,"Cuando canto quince días,\nRecién me voy componiendo,\nSoy como l'agua del río,\nCuando recién va corriendo.",3,1,0,49,"",0,4,"eo",52,0,-1,0,497,497,"1926","",0,"","","",2,0,0,[],""],["carrizo_salta-n1927-01",3,"Cuando Cristo vino al mundo,\nDe sur a norte al poniente,\nDejó para bien del hombre,\nVino, chicha y aguardiente.",3,1,0,49,"",0,4,"ee",15,0,-1,0,497,497,"1927","",0,"","","",1,0,0,[],""],["carrizo_salta-n1928-01",3,"Cuando estoy con mis amigos,\nYo sé que nada me falta,\nY no los cambio en el mundo,\nNi por oro ni por plata.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,497,497,"1928","",0,"","","",1,0,0,[],""],["carrizo_salta-n1929-01",3,"Cuando llega Carnaval,\nNo almuerzo ni ceno nada,\nMe mantengo con las coplas,\nMe duermo con la tonada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,497,497,"1929","",0,"","","",2,0,0,[],""],["carrizo_salta-n1930-01",3,"Cuando me dicen: Te quiero,\nPongo mi amor en carrera,\nQue en constancia y en firmeza,\nMi amor ha i parar bandera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,497,497,"1930","",0,"","","",1,0,0,[],""],["carrizo_salta-n1931-01",3,"Cuando muera un divertido,\nSiempre es bueno hacerle duelo,\nQue no se vaya a morir,\nSin tener ningún consuelo.",3,1,0,49,"",0,4,"eo",10,0,-1,0,497,497,"1931","",0,"","","",1,0,0,[],""],["carrizo_salta-n1932-01",3,"Cuando oigo sonar la caja,\nLas coplas quieren volar,\nAunque no sé buenas coplas,\nSoy de buena voluntad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,497,497,"1932","",0,"","","",2,0,0,[],""],["carrizo_salta-n1933-01",3,"Cuando oigo sonar la caja,\nSe me hace que todo tengo,\nCantando la vidalita,\nCon las coplas me mantengo.",3,1,0,49,"",0,4,"eo",124,0,-1,0,497,497,"1933","",0,"","","",2,0,0,[],""],["carrizo_salta-n1934-01",3,"Cuando salen del chiquero,\nLindo saltan los cabritos,\nAsí juegan mis versitos,\nEntre medio los benditos.",3,1,0,49,"",0,4,"io",254,0,-1,0,497,497,"1934","",0,"","","",1,0,0,[],""],["carrizo_salta-n1940-01",3,"Cuando yo vine a este mundo,\nNo supe lo que era amor,\nAhora que sé y padezco,\nEn amor soy un doctor.",3,1,0,49,"",0,4,"o",72,0,-1,0,498,498,"1940","",0,"","","",1,0,0,[],""],["carrizo_salta-n1941-01",3,"¡Cuidadito con las piedras!\n¡Cuidao con el tropezón!\nLa mujer que no me quiera,\nEs dura de corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,498,498,"1941","",0,"","","",2,0,0,[],""],["carrizo_salta-n1942-01",3,"¡Cuidadito con las piedras!\n¡Cuidao con los trompezones!\nCuando las piedras se topan,\n¡Qué serán los corazones!",3,1,0,49,"",0,4,"oe",34,0,-1,0,498,498,"1942","",0,"","","",2,0,0,[],""],["carrizo_salta-n1943-01",3,"Cuerpiá, si vez la vieja,\nDel chaguarazo;\nQue ande tallan las suegras,\nTriunfos son bastos.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,498,498,"1943","",0,"","","",1,0,0,[],""],["carrizo_salta-n1944-01",3,"¡Chacarera, chacarera!\n¡Chacarera de los yuyos!\nPara el año hi de volver,\nA cantar como el coyuyo.",3,1,0,49,"",0,4,"uo",-1,0,-1,0,498,498,"1944","",0,"","","",13,0,0,[],""],["carrizo_salta-n1945-01",3,"¡Chacarera, chacarera!\nChacarera \"El Carrizal\",\nMe acuerdo del burro blanco,\nCuando salgo a carnaval.",3,1,0,49,"",0,4,"a",1,0,-1,0,498,498,"1945","",0,"","","",13,0,0,[],""],["carrizo_salta-n1946-01",3,"¡Chacarera, chacarera!\nChacarera \"El Carrizal\",\nMontando en un burro blanco,\nAnduve en el carnaval.",3,1,0,49,"",0,4,"a",1,0,-1,0,498,498,"1946","",0,"","","",13,0,0,[],""],["carrizo_salta-n1947-01",3,"¡Chacarera, chacarera!\n¡Chacarera pata i chancho!\nYa tengo mi real y medio,\nPara gastar en tu rancho.",3,1,0,49,"",0,4,"ao",380,0,-1,0,499,499,"1947","",0,"","","",13,0,0,[],""],["carrizo_salta-n1948-01",3,"Chiquitito soy, señores,\nY el corazón tengo grande,\nSantiago Ibáñez me llamo,\nPara que ustedes me manden.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,499,499,"1948","",0,"","","",2,0,0,[],""],["carrizo_salta-n1949-01",3,"Churcalito arriba,\nChurcalito abajo,\nSi no sabís pasar penas,\nAprendé a pasar trabajos.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,499,499,"1949","",0,"","","",1,0,0,[],""],["carrizo_salta-n1950-01",3,"De abajo vengo, señores,\nEscribiendo en las quinchitas,\nLa letra viene diciendo:\n—Echen coplas las chinitas.",3,1,0,49,"",0,4,"ia",258,0,-1,0,499,499,"1950","",0,"","","",1,0,0,[],""],["carrizo_salta-n1951-01",3,"¿De ande sale este mocito,\nCon tanta escuela?\nEsa relación que ha echao,\nEs pa su agüela.",3,1,0,49,"",6,4,"ea",167,0,-1,0,499,499,"1951","",0,"","","",1,0,0,[],""],["carrizo_salta-n1953-01",3,"¿De dónde sale esta rubia,\nQue no la puedo entender?\nParece que anda trayendo\nAngolas para vender.",3,1,0,49,"",0,4,"e",20,0,-1,0,499,499,"1953","",0,"","","",1,0,0,[],""],["carrizo_salta-n1954-01",3,"¿De dónde, sale este gringo,\nDe pantalón tan angosto?\nParece ternero guascho,\nDe la parición de Agosto.",3,1,0,49,"",0,4,"oo",425,0,-1,0,499,499,"1954","",0,"","","",1,0,0,[],""],["carrizo_salta-n1955-01",3,"¿De dónde viene?\n¿Cómo le va?\n¿Cómo se llama?\n¿Y cómo está?",3,1,0,49,"",6,4,"a",9,0,-1,0,499,499,"1955","",0,"","","",1,0,0,[],""],["carrizo_salta-n1956-01",3,"De esta banda a l'otra banda,\nDe este río al otro río,\nAndo siempre viajando,\nPa gozar de lo que es mío.",3,1,0,49,"",0,4,"io",3,0,-1,0,499,499,"1956","",0,"","","",5,0,0,[],""],["carrizo_salta-n1957-01",3,"De esta banda a l'otra banda,\nDe este río al otro río,\nVi peliar a Juan Moreira,\nPor quitarme lo que es mío.",3,1,0,49,"",0,4,"io",3,0,-1,0,499,499,"1957","",0,"","","",5,0,0,[],""],["carrizo_salta-n1958-01",3,"Dejemos de navidades,\nVamos con algo de amor,\nA ver si a todos los tristes,\nSe le alegra el corazón.",3,1,0,49,"",0,4,"o",-1,0,-1,0,499,499,"1958","",0,"","","",1,0,0,[],""],["carrizo_salta-n1959-01",3,"Dejesé de andar paviando,\nY guarde su pretensión,\nCabeza de burro viejo,\nOrejas de mancarrón.",3,1,0,49,"",0,4,"o",31,0,-1,0,500,500,"1959","",0,"","","",1,0,0,[],""],["carrizo_salta-n1960-01",3,"De la Banda m'hi venío,\nCaminando paso a paso,\nPorque hi tenio noticias,\nQue aquí estaban vaso a vaso.",3,1,0,49,"",0,4,"ao",145,0,-1,0,500,500,"1960","",0,"","","",1,0,0,[],""],["carrizo_salta-n1961-01",3,"De la Banda m'hi venido,\nDe la banda \"El Quebrachal\",\nCon la cajita en las manos,\nAnunciando carnaval.",3,1,0,49,"",0,4,"a",1,0,-1,0,500,500,"1961","",0,"","","",1,0,0,[],""],["carrizo_salta-n1962-01",3,"De lao de abajo me vengo,\nComo de lao \"La Frontera\",\nComo soy mocito tierno,\nVoy a cantar como quiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,500,500,"1962","",0,"","","",1,0,0,[],""],["carrizo_salta-n1963-01",3,"De lao de arriba he venido,\nSaltando como sapito,\nY aquí me he venido hallar,\nBlandito como trapito.",3,1,0,49,"",3,4,"io",119,0,-1,0,500,500,"1963","",0,"","","",1,0,0,[],""],["carrizo_salta-n1964-01",3,"Del cerro vengo,\nQue es Año Nuevo,\nAhora soy libre,\nNo tengo dueño.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,500,500,"1964","",0,"","","",1,0,0,[],""],["carrizo_salta-n1966-01",3,"Del Papa santo de Roma,\nTraigo licencia sagrada,\nPara llevar mi chinita,\nEn una mula ensillada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,500,500,"1966","",0,"","","",1,0,0,[],""],["carrizo_salta-n1967-01",3,"De lo bien que están cantando,\nLes vengo a echar a perder,\n¡Señores, tendrán paciencia!\nPa volver a componer.",3,1,0,49,"",0,4,"e",20,0,-1,0,500,500,"1967","",0,"","","",3,0,0,[],""],["carrizo_salta-n1967-a-01",3,"De lo bien que están cantando,\nLa vengo a echar a perder,\n¡Tengan paciencia, hermanitos!\nQue la voy a componer.",3,1,0,49,"",0,4,"e",20,0,-1,0,500,500,"1967-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n1967-b-01",3,"De lo bien que están cantando,\nVengo a echarles a perder,\n¡Pero, paciencia, señores!\nVua volver a componer.",3,1,0,49,"",0,4,"e",20,0,-1,0,500,500,"1967-b","",0,"","","",3,0,0,[],""],["carrizo_salta-n1968-01",3,"Dende abajo m'hi venío,\nPisando sobre paderes,\nLa yerba para los hombres,\nLa azúcar pa las mujeres.",3,1,0,49,"",0,4,"ee",55,0,-1,0,500,500,"1968","",0,"","","",1,0,0,[],""],["carrizo_salta-n1969-01",3,"Dentro de un corral de estrellas,\nDentré una sola ocasión,\nNunca quisiera dentrar,\nEn medio la diversión.",3,1,0,49,"",0,4,"o",31,0,-1,0,500,500,"1969","",0,"","","",1,0,0,[],""],["carrizo_salta-n1970-01",3,"De querer quisiera,\nA la más bonita,\nPero no con dueño,\nNi Dios lo permita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,500,500,"1970","",0,"","","",1,0,0,[],""],["carrizo_salta-n1971-01",3,"Desde abajo m'hi venío,\nBuscando la diversión,\nY me los hallo cantando\nPa mi mayor perdición.",3,1,0,49,"",0,4,"o",31,0,-1,0,500,500,"1971","",0,"","","",11,0,0,[],""],["carrizo_salta-n1971-02",3,"Desde abajo m'hi venío\nEn busca la diversión,\nVengo y l'encuentro cantando\nPara mayor perdición.",3,1,0,49,"",0,4,"o",31,0,-1,0,500,500,"1971","",0,"","","",11,0,0,[],""],["carrizo_salta-n1972-01",3,"Desde abajo m'hi venío,\nCaminando como bala,\nPorque hi tenío noticias,\nQue cantaban la vidala.",3,1,0,49,"",0,4,"aa",330,0,-1,0,501,501,"1972","",0,"","","",11,0,0,[],""],["carrizo_salta-n1973-01",3,"Desde abajo m'hi venío\nComo paja por el aire,\n¡Señora dueña de casa,\nNo me haga ningún desaire!",3,1,0,49,"",0,4,"ae",411,0,-1,0,501,501,"1973","",0,"","","",11,0,0,[],""],["carrizo_salta-n1974-01",3,"Desde abajo m'hi venío,\nN'el camino m'hi dormío,\nOyendo bramar la caja,\nSuspirando m'hi venío.",3,1,0,49,"",0,4,"io",3,0,-1,0,501,501,"1974","",0,"","","",11,0,0,[],""],["carrizo_salta-n1974-a-01",3,"Desde Salta m'hi venío,\nMedio el camino hi dormío.\nAl rúido de los tambores,\nRecordándome hi venío.",3,1,0,49,"",0,4,"io",3,0,-1,0,501,501,"1974-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n1975-01",3,"Desde abajo m'hi venío\nEscribiendo en los tronquitos,\nLa letra viene diciendo:\n—Echen coplas los mocitos.",3,1,0,49,"",0,4,"io",254,0,-1,0,501,501,"1975","",0,"","","",11,0,0,[],""],["carrizo_salta-n1976-01",3,"Desde abajo m'hi venío,\nEn mi yegua lobunita,\nPorque me dan la noticia,\nQue hay chicha en \"La Lagunita\".",3,1,0,49,"",0,4,"ia",-1,0,-1,0,501,501,"1976","",0,"","","",11,0,0,[],""],["carrizo_salta-n1977-01",3,"Desde Angastaco me vengo,\nCruzando el río y lomadas,\nA este pueblo de San Carlos,\nPara cantar mi tonada.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,501,501,"1977","",0,"","","",1,0,0,[],""],["carrizo_salta-n1978-01",3,"Desde arriba m'hi venío,\nArrastrando mi azotera,\nSólo por venirte a ver,\nCara de mula carrera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,501,501,"1978","",0,"","","",17,0,0,[],""],["carrizo_salta-n1979-01",3,"Desde abajo mí hi venío,\nAndando filo por filo,\nPorque hi tenío noticias,\nQue aquí está un cantor muy fino.",3,1,0,49,"",0,4,"io",-1,0,-1,0,501,501,"1979","",0,"","","",1,0,0,[],""],["carrizo_salta-n1979-02",3,"Desde arriba m'hi venío,\nAndando filo tras filo,\nPorque hi tenío noticias,\nQue aquí toman chicha y vino.",3,1,0,49,"",3,4,"io",-1,0,-1,0,501,501,"1979","",0,"","","",17,0,0,[],""],["carrizo_salta-n1980-01",3,"Desde arriba m'hi venío,\nEn busca de distraición,\nPorque estoy muy aburrido,\nSin ver a mi corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,501,501,"1980","",0,"","","",17,0,0,[],""],["carrizo_salta-n1981-01",3,"Desde arriba m'hi venío,\nSiguiendo mi pensamiento,\nA cantar con los de abajo,\nSin tener merecimiento.",3,1,0,49,"",0,4,"eo",94,0,-1,0,501,501,"1981","",0,"","","",17,0,0,[],""],["carrizo_salta-n1982-01",3,"Desde arriba m'hi venío,\nVolando como parina,\nYo vengo de guitarrero,\nMi mujer de bailarina.",3,1,0,49,"",0,4,"ia",11,0,-1,0,501,501,"1982","",0,"","","",17,0,0,[],""],["carrizo_salta-n1983-01",3,"Desde Lima traigo fama,\nDe buen mozo y buen ladrón;\nHe robado a una cholita,\nDe su pecho el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,501,501,"1983","",0,"","","",2,0,0,[],""],["carrizo_salta-n1984-01",3,"Desde mi pago hi venío,\nEn busca de amores nuevos,\nMe salió la cuenta errada,\nLa prenda había tenío dueño.",3,1,0,49,"",3,4,"eo",-1,0,-1,0,501,501,"1984","",0,"","","",6,0,0,[],""],["carrizo_salta-n1985-01",3,"Desde que lo ví llegar,\nLo sentí por la pisada,\nY me dije para mí,\n¿Quién será la afortunada?",3,1,0,49,"",0,4,"aa",49,0,-1,0,501,501,"1985","",0,"","","",1,0,0,[],""],["carrizo_salta-n1986-01",3,"Desde mi pago hi venío,\nAquí la chicha es barata,\nCuatro botijas por rial,\nY una jarrita de yapa.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,502,502,"1986","",0,"","","",6,0,0,[],""],["carrizo_salta-n1987-01",3,"Desde mi pago hi venío,\nPor medio de estos ulares,\nA cantar con mis amigos,\nY a recordar los lugares.",3,1,0,49,"",0,4,"ae",164,0,-1,0,502,502,"1987","",0,"","","",6,0,0,[],""],["carrizo_salta-n1988-01",3,"Desde mi tierra hi venío,\nLevantando polvareda,\nEn el paguito \"La Cuesta\"\nParen fuerte la bandera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,502,502,"1988","",0,"","","",1,0,0,[],""],["carrizo_salta-n1989-01",3,"Despacito m'hi venío,\nPorque no hi tenío coche,\n¡Señores, dueños de casa,\nBuenas tardes, buenas noches!",3,1,0,49,"",0,4,"oe",-1,0,-1,0,502,502,"1989","",0,"","","",1,0,0,[],""],["carrizo_salta-n1990-01",3,"De toditos mis hermanos,\nYo sólito ando en la mala,\nPara armar una parranda,\nSoy como tejido a pala.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,502,502,"1990","",0,"","","",2,0,0,[],""],["carrizo_salta-n1991-01",3,"De todos los instrumentos\nA mí me gusta la caja,\nPorque esa es la diversión,\nDe toda la gente baja.",3,1,0,49,"",0,4,"aa",393,0,-1,0,502,502,"1991","",0,"","","",2,0,0,[],""],["carrizo_salta-n1993-01",3,"¡De vicio te has de lamber!\nSoy gringo calzón angosto,\nPero me sé jinetear\nEn empelo cualquier potro.",3,1,0,49,"",0,4,"oo",-1,0,-1,0,502,502,"1993","",0,"","","",1,0,0,[],""],["carrizo_salta-n1994-01",3,"Dicen que el Carnaval viene\nPor el campo \"La Ramada\"\nAquí lo estoy esperando,\nCon la caja y la tonada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,502,502,"1994","",0,"","","",1,0,0,[],""],["carrizo_salta-n1995-01",3,"Dicen que el rancho tiene,\nPuertas al viento,\nQue el aire trae amores,\nY casamientos.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,502,502,"1995","",0,"","","",1,0,0,[],""],["carrizo_salta-n1996-01",3,"Dicen que estando callado,\nViene la melancolía,\nVoy a cantar esta noche,\nY mañana todo el día.",3,1,0,49,"",0,4,"ia",0,0,-1,0,502,502,"1996","",0,"","","",1,0,0,[],""],["carrizo_salta-n1997-01",3,"Dicen que la guitarra,\nEs la que suena,\nNo suena la guitarra,\nSuenan las cuerdas.",3,1,0,49,"",6,4,"ea",-1,0,-1,0,502,502,"1997","",0,"","","",1,0,0,[],""],["carrizo_salta-n1998-01",3,"Diz que viene Carnaval\nPor la quebrada de Salta,\nY dicen que manda carta,\nPara el domingo sin falta.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,502,502,"1998","",0,"","","",1,0,0,[],""],["carrizo_salta-n1999-01",3,"Domingo de Ramos,\nHacimos trato,\nPa la Pascua t'h'i dar,\nNo t'hi negar.",3,1,0,49,"",6,4,"a",21,0,-1,0,502,502,"1999","",0,"","","",1,0,0,[],""],["carrizo_salta-n2000-01",3,"Echa tu gaucha a las ancas,\nVámonos a la Quebrada,\nAllá han de estar esperando,\nCon chichita madurada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,503,503,"2000","",0,"","","",1,0,0,[],""],["carrizo_salta-n2001-01",3,"¡Eche chicha mama Carmen!\nNo me diga \"manan cancho\"\nAquí traigo real y medio,\nPara gastar en su rancho.",3,1,0,49,"",3,4,"ao",380,0,-1,0,503,503,"2001","",0,"","","",1,0,0,[],""],["carrizo_salta-n2002-01",3,"¡Echen coplas de una orilla\nComo a picar panza hervida!\n¿Dónde estará la chinita\nPreparando la comida?",3,1,0,49,"",0,4,"ia",-1,0,-1,0,503,503,"2002","",0,"","","",3,0,0,[],""],["carrizo_salta-n2003-01",3,"Echen coplas de una orilla,\nComo piedras de apacheta,\nYo les echaré remates,\nComo costura i chaqueta.",3,1,0,49,"",0,4,"ea",200,0,-1,0,503,503,"2003","",0,"","","",3,0,0,[],""],["carrizo_salta-n2004-01",3,"Echen coplas de una orilla,\nYo les voy a echar del medio,\nEstas cuantitas que tengo,\nSiquiera para remedio.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,503,503,"2004","",0,"","","",3,0,0,[],""],["carrizo_salta-n2005-01",3,"El año pasao canté,\nEste año lo mismo haré,\nHagamén el inventario,\nTal vez ya me moriré.",3,1,0,49,"",0,4,"e",77,0,-1,0,503,503,"2005","",0,"","","",2,0,0,[],""],["carrizo_salta-n2006-01",3,"El año pasao canté,\nEste año lo mismo haré,\nPara el año, si Dios quiere,\nSi estoy vivo cantaré.",3,1,0,49,"",0,4,"e",77,0,-1,0,503,503,"2006","",0,"","","",2,0,0,[],""],["carrizo_salta-n2007-01",3,"El Carnaval ya se ha muerto\nComiendo bollo caliente,\nY unos corderitos gordos,\nQue le ha dado su pariente.",3,1,0,49,"",0,4,"ee",15,0,-1,0,503,503,"2007","",0,"","","",2,0,0,[],""],["carrizo_salta-n2008-01",3,"El día que pienso menos,\nTengo la vida tranquila,\nA mí el desprecio me embarga,\nY el cariño me aniquila.",3,1,0,49,"",0,4,"ia",427,0,-1,0,504,504,"2008","",0,"","","",1,0,0,[],""],["carrizo_salta-n2009-01",3,"El dueño de esta tonada,\n¿A dónde estará cantando,\nSujetando, chicotiando,\nA gritos hablando, hablando?",3,1,0,49,"",0,4,"ao",33,0,-1,0,504,504,"2009","",0,"","","",1,0,0,[],""],["carrizo_salta-n2010-01",3,"El hombre que llega a viejo\nEs lo mismo que muriera,\nSe le achucharra la cara,\nY no hay mujer que lo quiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,504,504,"2010","",0,"","","",3,0,0,[],""],["carrizo_salta-n2011-01",3,"El hombre que me quiera,\nMe tiene que buscar,\nComo el arroyo al río,\nComo el río a la mar.",3,1,0,49,"",0,4,"a",21,0,-1,0,504,504,"2011","",0,"","","",1,0,0,[],""],["carrizo_salta-n2012-01",3,"El Miércoles de Ceniza\nHaremos la cacharpaya,\nDespachemos, despachemos,\nAl Carnaval que se vaya.",3,1,0,49,"",0,4,"aa",404,0,-1,0,504,504,"2012","",0,"","","",2,0,0,[],""],["carrizo_salta-n2013-01",3,"El mozo que me quiere,\nNo es como el tuyo,\nTiene el sombrero plomo,\nY el pelo rubio.",3,1,0,49,"",6,4,"uo",-1,0,-1,0,504,504,"2013","",0,"","","",1,0,0,[],""],["carrizo_salta-n2015-01",3,"El que nace para calvo,\nDesde chiquito es frentón,\nEl que tenga cola i paja,\nHuiga de la quemazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,504,504,"2015","",0,"","","",1,0,0,[],""],["carrizo_salta-n2016-01",3,"El que no sepa de amor,\nVenga y me pregunte a mí,\nYo le daré los detalles,\nDesde el principio hasta el fin.",3,1,0,49,"",0,4,"i",-1,0,-1,0,504,504,"2016","",0,"","","",1,0,0,[],""],["carrizo_salta-n2017-01",3,"El que quiera amor que compre\nYo tengo para vender,\nEn la botica no venden,\nRemedios para querer.",3,1,0,49,"",0,4,"e",20,0,-1,0,504,504,"2017","",0,"","","",1,0,0,[],""],["carrizo_salta-n2018-01",3,"El tiempo está de correr,\nYa no se puede vivir,\nY muy pronto hemos de ver,\nHasta los hombres parir.",3,1,0,49,"",1,4,"i",157,0,-1,0,504,504,"2018","",0,"","","",1,0,0,[],""],["carrizo_salta-n2019-01",3,"¡Ejuahijuna!\nÑo Laguna\n¡Ejuahijuna!\nYa no hay luna.",3,1,0,49,"",6,4,"ua",56,0,-1,0,504,504,"2019","",0,"","","",1,0,0,[],""],["carrizo_salta-n2020-01",3,"Eijuahiputa Carnaval\nFiero como Juan de Dios,\nAunque te lleven los diablos,\n¿Quién ha de sentir por vos?",3,1,0,49,"",0,4,"o",87,0,-1,0,504,504,"2020","",0,"","","",1,0,0,[],""],["carrizo_salta-n2021-01",3,"En el aro de mi caja,\nTraigo una copla bonita,\nPa cantar con mi vidita,\nCuando la encuentre solita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,504,504,"2021","",0,"","","",1,0,0,[],""],["carrizo_salta-n2022-01",3,"En el campo hay el quebracho,\nArbol que da rica leña,\nAsí cantaba y decía,\nUna vieja guachipeña.",3,1,0,49,"",0,4,"ea",291,0,-1,0,504,504,"2022","",0,"","","",1,0,0,[],""],["carrizo_salta-n2023-01",3,"En el campo hay una planta,\nQue le llaman mostacilla,\nDejemos el contrapunto,\nSigamos las redondillas.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,504,504,"2023","",0,"","","",1,0,0,[],""],["carrizo_salta-n2024-01",3,"En el campo \"La Esperanza\",\nDicen que nació una flor,\nEn los campos de mi pago,\nHa nacido otra mejor.",3,1,0,49,"",0,4,"o",72,0,-1,0,505,505,"2024","",0,"","","",2,0,0,[],""],["carrizo_salta-n2025-01",3,"En el cielo del amor,\nLos suspiros son estrellas,\nLos besos son los luceros,\nY los celos son centellas.",3,1,0,49,"",0,4,"ea",89,0,-1,0,505,505,"2025","",0,"","","",1,0,0,[],""],["carrizo_salta-n2026-01",3,"En el cielo hay una estrella,\nQue le dicen el lucero,\nEs el ojo de un buey tuerto,\nQue Dios tiene en su potrero.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,505,505,"2026","",0,"","","",2,0,0,[],""],["carrizo_salta-n2027-01",3,"En el corral de mi casa,\nTengo una planta i junquillo,\n¡De vicio has de compadriar,\nMuchacho sin calzoncillos!",3,1,0,49,"",0,4,"io",-1,0,-1,0,505,505,"2027","",0,"","","",1,0,0,[],""],["carrizo_salta-n2028-01",3,"En el fondo de la mar,\nSuspiraba una ballena,\nY entre suspiro decía:\n\"Haiga gusto, no haiga pena\".",3,1,0,49,"",0,4,"ea",59,0,-1,0,505,505,"2028","",0,"","","",9,0,0,[],""],["carrizo_salta-n2029-01",3,"En el nombre de la luna,\nHemos de hacer la fortuna,\nY mañana con el sol,\nHemos de hacer el amor.",3,1,0,49,"",5,4,"o",-1,0,-1,0,505,505,"2029","",0,"","","",1,0,0,[],""],["carrizo_salta-n2030-01",3,"En el río de Aliseno,\nFabricó un puente Cupido,\nCon barandillas de celos,\nY atravesaños de olvido.",3,1,0,49,"",0,4,"io",101,0,-1,0,505,505,"2030","",0,"","","",1,0,0,[],""],["carrizo_salta-n2031-01",3,"En esta casa hi llegado,\nSin decir ¡Ave María!\nEn la copa del sombrero,\nTraigo la Virgen María.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,505,505,"2031","",0,"","","",2,0,0,[],""],["carrizo_salta-n2032-01",3,"En esta casa se canta,\nCon la caja y la guitarra,\nDe ver la casa tan linda\nY la dueña tan bizarra.",3,1,0,49,"",0,4,"aa",308,0,-1,0,505,505,"2032","",0,"","","",1,0,0,[],""],["carrizo_salta-n2033-01",3,"En esta rueda han cantado,\nCuatro gauchos chiriguanos,\nConfundiéndolos los traigo,\nPara que se diviertamos.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,505,505,"2033","",0,"","","",1,0,0,[],""],["carrizo_salta-n2034-01",3,"En la copa del sombrero,\nTengo un papel de quinientos,\nQue quiero solicitarte,\nPalabra de casamiento.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,505,505,"2034","",0,"","","",2,0,0,[],""],["carrizo_salta-n2035-01",3,"En la copa del sombrero,\nLlevo un peso nacional,\nPara que alguna me firme,\nPromesa de ser formal.",3,1,0,49,"",0,4,"a",1,0,-1,0,505,505,"2035","",0,"","","",2,0,0,[],""],["carrizo_salta-n2036-01",3,"En la costa el Pilcomayo,\nFrente de María Cristina,\nCasi he perdido la vida,\nPor querer a una argentina.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,505,505,"2036","",0,"","","",1,0,0,[],""],["carrizo_salta-n2037-01",3,"En la falda de aquel cerro,\nBalando está un toro gacho,\nAsí lloran las muchachas,\nPor este infeliz muchacho.",3,1,0,49,"",0,4,"ao",310,0,-1,0,505,505,"2037","",0,"","","",54,0,0,[],""],["carrizo_salta-n2038-01",3,"En la falda de aquel cerro,\nLindo juegan las tamberas,\nAsí juega mi vidita,\nEntre medio las banderas.",3,1,0,49,"",0,4,"ea",103,0,-1,0,505,505,"2038","",0,"","","",54,0,0,[],""],["carrizo_salta-n2039-01",3,"En la falda de aquel cerro,\nSuspiraba un tero-tero,\nDecile hermana que llore,\nPor triste y por embustero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,505,505,"2039","",0,"","","",54,0,0,[],""],["carrizo_salta-n2040-01",3,"En la falda de aquel cerro,\nTengo una casa de tola,\nCada vez que dentro y salgo,\nHasta los caschis me torian.",3,1,0,49,"",0,4,"oa",-1,0,-1,0,506,506,"2040","",0,"","","",54,0,0,[],""],["carrizo_salta-n2041-01",3,"En la falda de aquel cerro,\nTengo una fuente de loza,\nYo no te quiero, vidita,\nPorque tu abuela es celosa.",3,1,0,49,"",0,4,"oa",63,0,-1,0,506,506,"2041","",0,"","","",54,0,0,[],""],["carrizo_salta-n2042-01",3,"En la falda de aquel cerro,\nTengo una linda casita,\nP'esconder a mi vidita,\nCuando caiga la garvita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,506,506,"2042","",0,"","","",54,0,0,[],""],["carrizo_salta-n2043-01",3,"En la falda de aquel cerro,\nTengo una piedra larguita\nPa esconder a mi vidita,\nEn la falda la lomita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,506,506,"2043","",0,"","","",54,0,0,[],""],["carrizo_salta-n2044-01",3,"En la falda de aquel cerro,\nTengo una planta i jarilla,\nPa sentar a mi vidita,\nSobre una cinta amarilla.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,506,506,"2044","",0,"","","",54,0,0,[],""],["carrizo_salta-n2046-01",3,"En la falda de aquel cerro,\nTengo una planta i tabaco,\nM'hi d' ir al cerro a cuidarla,\nHasta que pase el guanaco.",3,1,0,49,"",0,4,"ao",423,0,-1,0,506,506,"2046","",0,"","","",54,0,0,[],""],["carrizo_salta-n2046-a-01",3,"En la falda de aquel cerro,\nTengo una planta i tabaco,\nP'esconder a mi vidita,\nHasta que pase el guanaco.",3,1,0,49,"",0,4,"ao",423,0,-1,0,506,506,"2046-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n2046-b-01",3,"En la falda de aquel cerro,\nTengo una planta i tabaco,\nP'esconderla a mi vidita,\nQue no la pise el guanaco.",3,1,0,49,"",0,4,"ao",423,0,-1,0,506,506,"2046-b","",0,"","","",54,0,0,[],""],["carrizo_salta-n2047-01",3,"En la falda de aquel cerro,\nTengo una silla verdosa,\nPara sentarla a mi negra,\nPara que no sea celosa.",3,1,0,49,"",0,4,"oa",63,0,-1,0,506,506,"2047","",0,"","","",54,0,0,[],""],["carrizo_salta-n2048-01",3,"En la falda de aquel cerro,\nTengo una sombrilla i lata,\nLa relación que has echao,\nAndá y echala a tu tata.",3,1,0,49,"",0,4,"aa",74,0,-1,0,506,506,"2048","",0,"","","",54,0,0,[],""],["carrizo_salta-n2049-01",3,"En la falda de aquel cerro,\nTengo un atao de azulillo,\n¡De vicio venís moniando,\nGuaschito cara de pillo!",3,1,0,49,"",0,4,"io",228,0,-1,0,506,506,"2049","",0,"","","",54,0,0,[],""],["carrizo_salta-n2050-01",3,"En la falda de aquel cerro,\nTriste llora un gavilán,\nDejelón llorar sus penas,\nPor bruto y por animal.",3,1,0,49,"",0,4,"a",-1,0,-1,0,506,506,"2050","",0,"","","",54,0,0,[],""],["carrizo_salta-n2050-a-01",3,"En la falda de aquel cerro,\nTriste llora un gavilán,\nNo llora porque tiene hambre,\nSino por que es animal.",3,1,0,49,"",0,4,"a",-1,0,-1,0,506,506,"2050-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n2051-01",3,"En la falda de aquel cerro,\nTriste llora un tero-tero,\nNo llora porque tiene hambre,\nSino porque es embustero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,507,507,"2051","",0,"","","",54,0,0,[],""],["carrizo_salta-n2051-a-01",3,"En la falda de aquel cerro,\nTriste llora un tero-tero,\nNo llora porque tiene hambre,\nSino por su compañero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,507,507,"2051-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n2052-01",3,"En la orilla del bañao,\nTriste llora un tero-tero,\nDejelón nomás que llore\nPor p... y por cuadrillero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,507,507,"2052","",0,"","","",1,0,0,[],""],["carrizo_salta-n2053-01",3,"En la orilla del Pasaje,\nVierte un lagarto su lloro,\nPor ser verde y no volar,\nA la altura como el loro.",3,1,0,49,"",0,4,"oo",85,0,-1,0,507,507,"2053","",0,"","","",1,0,0,[],""],["carrizo_salta-n2054-01",3,"En la petaca de casa,\nTengo un tirador de plata,\nCada vez que dentro y salgo,\nGrito, ¡qué viva mi patria!",3,1,0,49,"",0,4,"aa",-1,0,-1,0,507,507,"2054","",0,"","","",1,0,0,[],""],["carrizo_salta-n2054-02",3,"En la puerta de mi casa,\nTengo un escudo de plata,\nCada vez que dentro y salgo,\nDigo que ¡Viva la patria!",3,1,0,49,"",0,4,"aa",-1,0,-1,0,507,507,"2054","",0,"","","",24,0,0,[],""],["carrizo_salta-n2055-01",3,"En la puerta de mi casa,\nTengo una planta de rosa,\nNo se arrime más a mí,\nQue mi mamita se enoja.",3,1,0,49,"",0,4,"oa",-1,0,-1,0,507,507,"2055","",0,"","","",24,0,0,[],""],["carrizo_salta-n2056-01",3,"En la puerta de mi casa,\nTengo un árbol de esperanza,\nCada vez que voy y vengo\nLas hojas tienen mudanzas.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,507,507,"2056","",0,"","","",24,0,0,[],""],["carrizo_salta-n2057-01",3,"En la puerta de mi casa,\nYo tengo un candao con llave,\nCon un letrero que dice:\n—Puede ser, pero ¿quién sabe?",3,1,0,49,"",0,4,"ae",131,0,-1,0,507,507,"2057","",0,"","","",24,0,0,[],""],["carrizo_salta-n2058-01",3,"En la puerta de tu casa\nUn jabalí,\nTiene un letrero y dice,\n¡Bésame aquí!",3,1,0,49,"",6,4,"i",23,0,-1,0,507,507,"2058","",0,"","","",13,0,0,[],""],["carrizo_salta-n2059-01",3,"En la punta del pañuelo,\nTengo un atado,\nYo los quiero a los hombres,\nMenos casados.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,507,507,"2059","",0,"","","",3,0,0,[],""],["carrizo_salta-n2060-01",3,"En la punta del pañuelo,\nTengo un compromiso atado.\nDe no querer a muchachos,\nNi tampoco a hombre casado.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,507,507,"2060","",0,"","","",3,0,0,[],""],["carrizo_salta-n2061-01",3,"En la rueda del baile,\nHay una ñata,\nQue me tiene penando\n¡Qué ñata ingrata!",3,1,0,49,"",6,4,"aa",74,0,-1,0,507,507,"2061","",0,"","","",1,0,0,[],""],["carrizo_salta-n2062-01",3,"En las riberas de un río,\nYo ví crecer una flor,\nQue creció sin marchitarse,\nComo recuerdos de amor.",3,1,0,49,"",0,4,"o",72,0,-1,0,507,507,"2062","",0,"","","",1,0,0,[],""],["carrizo_salta-n2063-01",3,"En los aros del tambor,\nTengo que pintar el sol,\nYa está bajita la luna,\nY me duele el corazón.",3,1,0,49,"",0,4,"o",-1,0,-1,0,507,507,"2063","",0,"","","",1,0,0,[],""],["carrizo_salta-n2064-01",3,"Enterré mi amor un día,\nPorque muerto me creyeron,\nY de esas pocas raíces,\nMuchas plantas florecieron.",3,1,0,49,"",0,4,"eo",105,0,-1,0,507,507,"2064","",0,"","","",1,0,0,[],""],["carrizo_salta-n2065-01",3,"Esa gracia no conozco,\nNi quisiera conocerla,\nHay que querer una sola,\nPara poder merecerla.",3,1,0,49,"",0,4,"ea",428,0,-1,0,507,507,"2065","",0,"","","",1,0,0,[],""],["carrizo_salta-n2066-01",3,"Esa mentira que has dicho,\nNunca puede ser verdad,\nComo soy recién nacido,\nMe has de querer engañar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,507,507,"2066","",0,"","","",1,0,0,[],""],["carrizo_salta-n2067-01",3,"Esa moza que baila,\nPollera overa,\n¡Cómo será de hedionda\nCuando se muera!",3,1,0,49,"",6,4,"ea",44,0,-1,0,508,508,"2067","",0,"","","",1,0,0,[],""],["carrizo_salta-n2067-a-01",3,"Esa niña que baila,\nPollera overa,\n¡Cómo será de fiera\nCuando se muera!",3,1,0,49,"",6,4,"ea",44,0,-1,0,508,508,"2067-a","",0,"","","",10,0,0,[],""],["carrizo_salta-n2067-a-02",3,"Esa niña que baila,\nPollera overa,\n¡Cómo será de gaucha\nCuando se muera!",3,1,0,49,"",6,4,"ea",44,0,-1,0,508,508,"2067-a","",0,"","","",10,0,0,[],""],["carrizo_salta-n2068-01",3,"Esa niña que baila,\nCintas volando,\nNo se acuerda del dueño,\nQue está llorando.",3,1,0,49,"",6,4,"ao",33,0,-1,0,508,508,"2068","",0,"","","",10,0,0,[],""],["carrizo_salta-n2069-01",3,"Esa niña que baila,\nDe vestido ante,\n¿Cómo tendrá l'aloja?\n¿Dulce o picante?",3,1,0,49,"",6,4,"ae",47,0,-1,0,508,508,"2069","",0,"","","",10,0,0,[],""],["carrizo_salta-n2070-01",3,"Esa niña que baila,\nMe diera un beso,\nY el que baila con ella,\nTrescientos pesos.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,508,508,"2070","",0,"","","",10,0,0,[],""],["carrizo_salta-n2071-01",3,"Esa niña que baila,\nMerece un dote,\nY el que baila con ella,\nCincuenta azotes.",3,1,0,49,"",6,4,"oe",-1,0,-1,0,508,508,"2071","",0,"","","",10,0,0,[],""],["carrizo_salta-n2072-01",3,"Esa niña que baila,\nPollera overa,\nTiene la cara sucia.\n¿Será añapera?",3,1,0,49,"",6,4,"ea",44,0,-1,0,508,508,"2072","",0,"","","",10,0,0,[],""],["carrizo_salta-n2073-01",3,"Esa niña que baila,\nTan tinterilla,\n¡Cómo tendrá de dulce,\nLa empanadilla!",3,1,0,49,"",6,4,"ia",162,0,-1,0,508,508,"2073","",0,"","","",10,0,0,[],""],["carrizo_salta-n2075-01",3,"Esa que me está mirando\n¿Qué me estará reparando?\nY yo sin poder cantar,\nDe vergüenza estoy sudando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,508,508,"2075","",0,"","","",1,0,0,[],""],["carrizo_salta-n2076-01",3,"Escuchen, señores míos,\nQuien canta de esta manera,\nAl pobrecito i fulano\nOigalén la voz siquiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,508,508,"2076","",0,"","","",1,0,0,[],""],["carrizo_salta-n2077-01",3,"Ese es \"El Triunfo\" madre,\nDe las mujeres,\nQué bonito lo bailan\nCuando ellas quieren.",3,1,0,49,"",6,4,"ee",-1,0,-1,0,509,509,"2077","",0,"","","",1,0,0,[],""],["carrizo_salta-n2078-01",3,"Ese mozo que baila,\nBota y talero,\nAnda que no se puede,\nDel avispero.",3,1,0,49,"",6,4,"eo",38,0,-1,0,509,509,"2078","",0,"","","",2,0,0,[],""],["carrizo_salta-n2079-01",3,"Ese mozo que baila,\nTan tinterillo,\nAurita se le caen,\nLos canzoncillos.",3,1,0,49,"",6,4,"io",-1,0,-1,0,509,509,"2079","",0,"","","",2,0,0,[],""],["carrizo_salta-n2080-01",3,"Ese par de polluelos,\nQue andan bailando,\nSon dos hermosas flores,\nQue están brotando.",3,1,0,49,"",6,4,"ao",33,0,-1,0,509,509,"2080","",0,"","","",1,0,0,[],""],["carrizo_salta-n2083-01",3,"Esta moza que ha llegado,\n¿Qué habrá traído pa vender?\n¿Habrá traido lindas coplas\nPara poderle aprender?",3,1,0,49,"",0,4,"e",20,0,-1,0,509,509,"2083","",0,"","","",1,0,0,[],""],["carrizo_salta-n2084-01",3,"Estando con mis hermanos,\nTengo más gusto que pena.\nPa divertirme cantando,\nSoy un eco de sirena.",3,1,0,49,"",0,4,"ea",59,0,-1,0,509,509,"2084","",0,"","","",1,0,0,[],""],["carrizo_salta-n2085-01",3,"Esta noche con la luna,\nBuscaremos la fortuna,\nY mañana con el sol,\nBuscaremos nuestro amor.",3,1,0,49,"",5,4,"o",-1,0,-1,0,509,509,"2085","",0,"","","",4,0,0,[],""],["carrizo_salta-n2086-01",3,"Esta tonada supe,\nPor Año Nuevo,\nAhora les aviso,\nQue tengo dueño.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,509,509,"2086","",0,"","","",1,0,0,[],""],["carrizo_salta-n2087-01",3,"Esta tonadita linda\nMe va a quitar el vivir,\nPero al fin si yo me muero,\nNo soy prenda de sentir.",3,1,0,49,"",0,4,"i",157,0,-1,0,509,509,"2087","",0,"","","",1,0,0,[],""],["carrizo_salta-n2088-01",3,"Este año me vua casar,\nAunque el diablo diga misa,\nCon que yo tenga mujer,\nAunque no tenga camisa.",3,1,0,49,"",0,4,"ia",68,0,-1,0,509,509,"2088","",0,"","","",1,0,0,[],""],["carrizo_salta-n2089-01",3,"Este año pa Carnaval,\nElla no tiene zapatos,\nComo quiera pasará,\nDescalcita como el gato.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,509,509,"2089","",0,"","","",22,0,0,[],""],["carrizo_salta-n2090-01",3,"Este año pa Carnaval,\nMi apero no tiene cincha,\nComo quiera pasaré\nComo vinchuca en la quincha.",3,1,0,49,"",0,4,"ia",429,0,-1,0,509,509,"2090","",0,"","","",22,0,0,[],""],["carrizo_salta-n2091-01",3,"Este año pa Carnaval,\nMi bota no tiene taco,\nComo quiera pasaré,\nA la moda de Angastaco.",3,1,0,49,"",0,4,"ao",423,0,-1,0,509,509,"2091","",0,"","","",22,0,0,[],""],["carrizo_salta-n2092-01",3,"Este año pa Carnaval,\nMi ojota no tiene quina,\nAhora le vua poner\nCosa que sirva y que ciña.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,509,509,"2092","",0,"","","",22,0,0,[],""],["carrizo_salta-n2093-01",3,"Este año pa Carnaval,\nMi ojota no tiene quina,\nComo quiera pasaré,\nComo carnero en la viña.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,510,510,"2093","",0,"","","",22,0,0,[],""],["carrizo_salta-n2093-a-01",3,"Este año pa Carnaval,\nMi ojota no tiene quina,\nComo quiera pasaré\nCon los \"cotos\" de la Viña.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,510,510,"2093-a","",0,"","","",22,0,0,[],""],["carrizo_salta-n2094-01",3,"Este año pa Carnaval,\nMi mujer no tiene nagua,\nComo quiera pasará\nCocinando pa la guagua.",3,1,0,49,"",0,4,"aa",383,0,-1,0,510,510,"2094","",0,"","","",22,0,0,[],""],["carrizo_salta-n2095-01",3,"Este año pa Carnaval,\nMi poncho no tiene uincha,\nComo quiera pasaré,\nComo zorro tras la quincha.",3,1,0,49,"",0,4,"ia",429,0,-1,0,510,510,"2095","",0,"","","",22,0,0,[],""],["carrizo_salta-n2096-01",3,"Este año pa Carnaval,\nMi potro no tiene rienda,\nComo quiera pasaré,\nComo burro en media senda.",3,1,0,49,"",0,4,"ea",159,0,-1,0,510,510,"2096","",0,"","","",22,0,0,[],""],["carrizo_salta-n2097-01",3,"Este año pa Carnaval,\nNo m' hi comprado zapatos,\nComo quiera pasaré,\nA la moda los matacos.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,510,510,"2097","",0,"","","",22,0,0,[],""],["carrizo_salta-n2098-01",3,"Este año pa Carnaval,\nNo tengo para camisa,\nComo quiera pasaré,\nComo gato en la ceniza.",3,1,0,49,"",0,4,"ia",420,0,-1,0,510,510,"2098","",0,"","","",22,0,0,[],""],["carrizo_salta-n2099-01",3,"Este año pa Carnaval,\nNo tengo prenda segura\nComo quiera pasaré,\nComo incancho en la basura.",3,1,0,49,"",0,4,"ua",17,0,-1,0,510,510,"2099","",0,"","","",22,0,0,[],""],["carrizo_salta-n2099-a-01",3,"Este año pa Carnaval,\nNo tengo rienda segura,\nComo quiera pasaré,\nComo icaco en la basura.",3,1,0,49,"",0,4,"ua",17,0,-1,0,510,510,"2099-a","",0,"","","",22,0,0,[],""],["carrizo_salta-n2100-01",3,"Este año pa Carnaval,\nQuiero cantar en mi tierra,\nMi casita está muy lejos,\nAquí hi cantar como quiera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,510,510,"2100","",0,"","","",22,0,0,[],""],["carrizo_salta-n2101-01",3,"Este año pa Carnaval,\nSe me ha muerto mi caballo,\nComo quiera pasaré,\nCorre, corre como el gallo.",3,1,0,49,"",0,4,"ao",102,0,-1,0,511,511,"2101","",0,"","","",22,0,0,[],""],["carrizo_salta-n2102-01",3,"Este año pa Carnaval,\nTengo un apero i moniar,\nAicioneras de torzal,\nAsí nomás sin pelar.",3,1,0,49,"",1,4,"a",-1,0,-1,0,511,511,"2102","",0,"","","",22,0,0,[],""],["carrizo_salta-n2103-01",3,"Este año pa Carnaval,\nVendré en mi caballo oscuro,\nPara que digan las mozas,\n¡Ahijuaiputa mozo churo!",3,1,0,49,"",0,4,"uo",248,0,-1,0,511,511,"2103","",0,"","","",22,0,0,[],""],["carrizo_salta-n2104-01",3,"Este año pa Carnaval,\nVoy a hacer una opería,\nVua robar una mujer,\nMe vu' ir a Santa María.",3,1,0,49,"",0,4,"ia",0,0,-1,0,511,511,"2104","",0,"","","",22,0,0,[],""],["carrizo_salta-n2105-01",3,"Este año pa Carnaval,\nVua cantar como zorrino,\nPara que la gente diga:\n—¡Bien haiga de este vecino!",3,1,0,49,"",0,4,"io",199,0,-1,0,511,511,"2105","",0,"","","",22,0,0,[],""],["carrizo_salta-n2106-01",3,"Este año pa Carnaval\nYa tengo para estrenar,\nUn saquito de picote,\nPantalón de barracán.",3,1,0,49,"",0,4,"a",-1,0,-1,0,511,511,"2106","",0,"","","",22,0,0,[],""],["carrizo_salta-n2107-01",3,"Este es \"El gato\" cielo,\nDe los salones,\nNo de aquellos que sacan,\nLas elecciones.",3,1,0,49,"",6,4,"oe",34,0,-1,0,511,511,"2107","",0,"","","",1,0,0,[],""],["carrizo_salta-n2108-01",3,"Este es \"El gato\" hermoso,\nQue a todos gusta,\nPorque sus arañones,\nA nadie asustan.",3,1,0,49,"",6,4,"ua",-1,0,-1,0,511,511,"2108","",0,"","","",1,0,0,[],""],["carrizo_salta-n2109-01",3,"Este es el modo de amar,\nDijo Panchita Aguilar,\nLas chiquititas valen medio,\nY las grandes valen rial.",3,1,0,49,"",0,4,"a",-1,0,-1,0,511,511,"2109","",0,"","","",1,0,0,[],""],["carrizo_salta-n2110-01",3,"Este es el nuevo remate,\nRemate de un triste pueblo,\nNo digo ponderaciones,\nLo digo con desconsuelo.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,511,511,"2110","",0,"","","",2,0,0,[],""],["carrizo_salta-n2111-01",3,"Este es el remate,\nDel alto \"La Loza\"\n¿De ande has venido, vidita,\nSoltera y tan buena moza?",3,1,0,49,"",0,4,"oa",195,0,-1,0,511,511,"2111","",0,"","","",4,0,0,[],""],["carrizo_salta-n2112-01",3,"Este es el remate\nDe los arenales,\nBien has hecho de quererme\nCerquita los carnavales.",3,1,0,49,"",0,4,"ae",26,0,-1,0,511,511,"2112","",0,"","","",4,0,0,[],""],["carrizo_salta-n2113-01",3,"Este es el remate,\nDel sol y la luna,\nLas h'i gozar a toditas\nNo m' h'i casar con ninguna.",3,1,0,49,"",0,4,"ua",56,0,-1,0,512,512,"2113","",0,"","","",4,0,0,[],""],["carrizo_salta-n2114-01",3,"Este es el remate nuevo,\nCogoyito de verbena,\n¡Adiós, consuelo de mi alma!\n¡Adiós, que me voy con pena!",3,1,0,49,"",0,4,"ea",59,0,-1,0,512,512,"2114","",0,"","","",12,0,0,[],""],["carrizo_salta-n2115-01",3,"Este es el remate nuevo,\nDe la banda \"El Portizuelo\"\nTomá esta rosa, vidita,\nQue te sirva de consuelo.",3,1,0,49,"",0,4,"eo",10,0,-1,0,512,512,"2115","",0,"","","",12,0,0,[],""],["carrizo_salta-n2116-01",3,"Este es el remate nuevo,\nDe la banda i \"Santa Cruz\",\nVengo a llevarte, vidita,\nDisponete y vamusnús.",3,1,0,49,"",0,4,"u",270,0,-1,0,512,512,"2116","",0,"","","",12,0,0,[],""],["carrizo_salta-n2117-01",3,"Este es el remate nuevo,\nQue han traído los forasteros,\nEste es el vado que ataja,\nA todos los pasianderos.",3,1,0,49,"",0,4,"eo",22,0,-1,0,512,512,"2117","",0,"","","",12,0,0,[],""],["carrizo_salta-n2118-01",3,"Este es el remate nuevo,\nSacadito de Abralaite,\nTraigo mi caballo bayo,\nVidita, para llevarte.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,512,512,"2118","",0,"","","",12,0,0,[],""],["carrizo_salta-n2119-01",3,"Este es el remate nuevo,\nSacao de la quina-quina,\nSi me querís, mi vidita,\nEmbarcate en la maquina.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,512,512,"2119","",0,"","","",12,0,0,[],""],["carrizo_salta-n2120-01",3,"Este es el remate nuevo,\nDe la florcita de anís,\nYo te quiero, mi vidita,\nPorque ni dueño tenís.",3,1,0,49,"",0,4,"i",58,0,-1,0,512,512,"2120","",0,"","","",12,0,0,[],""],["carrizo_salta-n2121-01",3,"Este es el remate nuevo,\nTráido del cortaderal,\n¿Cuándo has de volver, vidita,\nEn mis brazos a llorar?",3,1,0,49,"",0,4,"a",-1,0,-1,0,512,512,"2121","",0,"","","",12,0,0,[],""],["carrizo_salta-n2122-01",3,"Este es el tono,\nQue hay que cantar,\nPara las fiestas,\nDe Carnaval.",3,1,0,49,"",6,4,"a",-1,0,-1,0,512,512,"2122","",0,"","","",1,0,0,[],""],["carrizo_salta-n2123-01",3,"Este es El Triunfo, madre,\nCuando interesan,\nSe van a los aperos,\nBuscando prendas.",3,1,0,49,"",6,4,"ea",-1,0,-1,0,512,512,"2123","",0,"","","",3,0,0,[],""],["carrizo_salta-n2124-01",3,"Este es El Triunfo, madre,\nDe las desgracias,\nQue como andan palomas,\nAndan vizcachas.",3,1,0,49,"",6,4,"aa",-1,0,-1,0,512,512,"2124","",0,"","","",3,0,0,[],""],["carrizo_salta-n2125-01",3,"Este es El Triunfo, madre,\nDel contrapunto,\nQue para uno que gana,\nQueda un difunto.",3,1,0,49,"",6,4,"uo",36,0,-1,0,512,512,"2125","",0,"","","",3,0,0,[],""],["carrizo_salta-n2126-01",3,"Este es \"Gato\" de mi pago,\nNo es \"Gato\" de estos lugares,\nDe los naranjos floridos,\nLlenos de aromas y azahares.",3,1,0,49,"",3,4,"ae",164,0,-1,0,512,512,"2126","",0,"","","",1,0,0,[],""],["carrizo_salta-n2127-01",3,"Este j ulano no sirve,\nPa tener una pasión,\nSi le muestran un desprecio,\nYa le duele el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,512,512,"2127","",0,"","","",1,0,0,[],""],["carrizo_salta-n2128-01",3,"Este pobre de cantor,\nLlorando no más se pasa,\nSin poder hallar consuelo,\n¡Ahijuna puta desgracia!",3,1,0,49,"",0,4,"aa",-1,0,-1,0,512,512,"2128","",0,"","","",1,0,0,[],""],["carrizo_salta-n2129-01",3,"Estos carnavales\nQue duran tres días,\nQuisieran que duren,\nTodita la vida.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,513,513,"2129","",0,"","","",1,0,0,[],""],["carrizo_salta-n2130-01",3,"Estoy cansao de tocar,\nEstoy cansao de cantar,\n¡Bien haiga la gente guapa,\nNo se cansa de bailar!",3,1,0,49,"",0,4,"a",21,0,-1,0,513,513,"2130","",0,"","","",1,0,0,[],""],["carrizo_salta-n2131-01",3,"Estrellas del alto cielo,\nRamas del negro pinar,\nArroyo de aguas serranas,\nCantos de la soledad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,513,513,"2131","",0,"","","",6,0,0,[],""],["carrizo_salta-n2132-01",3,"¡Estrellita de alto cielo!\nNo la dejís subir más,\nY decile que me espere,\nQue poco puedo tardar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,513,513,"2132","",0,"","","",2,0,0,[],""],["carrizo_salta-n2133-01",3,"¡Florcita de azahar!\n¡Florcita de azahar!\n¿Pa que es el mundo\nSi no es pa gozar?",3,1,0,49,"",3,4,"a",21,0,-1,0,513,513,"2133","",0,"","","",2,0,0,[],""],["carrizo_salta-n2134-01",3,"¡Florcita i maní!\n¡Florcita i maní!\n¿Cuál es la chicha\nQue han guardao pa mí?",3,1,0,49,"",3,4,"i",23,0,-1,0,513,513,"2134","",0,"","","",1,0,0,[],""],["carrizo_salta-n2135-01",3,"¡Florcita i tuscal!\n¡Florcita i tuscal!\nDueña no tengo,\nLa salgo a buscar.",3,1,0,49,"",6,4,"a",-1,0,-1,0,513,513,"2135","",0,"","","",1,0,0,[],""],["carrizo_salta-n2136-01",3,"¡Flor de sereno!\n¡Flor de sereno!\nSi usted volviera,\nArreglaremos.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,513,513,"2136","",0,"","","",1,0,0,[],""],["carrizo_salta-n2137-01",3,"¡Gracias a Dios que m' hi visto,\nEntre medio de las flores!\nAhora me vua enflorar,\nEscogiendo las mejores.",3,1,0,49,"",0,4,"oe",5,0,-1,0,513,513,"2137","",0,"","","",1,0,0,[],""],["carrizo_salta-n2138-01",3,"¡Gracias a Dios que ya tengo,\nLa libertad en mi pecho!\nYa no tengo quien me diga:\n—¿Ande has ido? ¿Qué te has hecho?",3,1,0,49,"",0,4,"eo",60,0,-1,0,513,513,"2138","",0,"","","",6,0,0,[],""],["carrizo_salta-n2139-01",3,"¡Gracias a Dios y a mi madre,\nQue ya apareció el perdido!\nNunca se puede perder,\nPájaro que tiene nido.",3,1,0,49,"",0,4,"io",101,0,-1,0,513,513,"2139","",0,"","","",1,0,0,[],""],["carrizo_salta-n2140-01",3,"¡Guiche torito!\n¡Guiche torazo!\nEntrá a los ranchos\nRompé los vasos.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,513,513,"2140","",0,"","","",1,0,0,[],""],["carrizo_salta-n2141-01",3,"Había dicho Carnaval,\nQue pal año va a volver,\nEn los días que ha pasao,\nLe han dao mucho de beber.",3,1,0,49,"",0,4,"e",20,0,-1,0,513,513,"2141","",0,"","","",1,0,0,[],""],["carrizo_salta-n2142-01",3,"Había dicho la verdad,\nPiedra lisa y bien gastante,\nPara uno que es entendido\nMedia razón es bastante.",3,1,0,49,"",0,4,"ae",47,0,-1,0,513,513,"2142","",0,"","","",1,0,0,[],""],["carrizo_salta-n2143-01",3,"¿Habrá permiso señores\nPara que cante un mulato?\n¿Si habrá como pa poner\nTres cucharas en un plato?",3,1,0,49,"",0,4,"ao",19,0,-1,0,513,513,"2143","",0,"","","",1,0,0,[],""],["carrizo_salta-n2144-01",3,"Hagan pabellón las armas,\nQue se siga el ejercicio,\nComo soy muchacho activo,\nQuiero despuntar el vicio.",3,1,0,49,"",0,4,"io",-1,0,-1,0,513,513,"2144","",0,"","","",1,0,0,[],""],["carrizo_salta-n2147-01",3,"Hasta mañana, señores!\nHasta mañana me iré!\nSi les gusta con la misma,\nCon la misma volverá.",3,1,0,49,"",5,4,"a",-1,0,-1,0,514,514,"2147","",0,"","","",3,0,0,[],""],["carrizo_salta-n2148-01",3,"Hasta mañana, señores!\nQue mañana hi de volver\nA pagarles lo que debo,\nY llevar lo que dejé.",3,1,0,49,"",0,4,"e",-1,0,-1,0,514,514,"2148","",0,"","","",3,0,0,[],""],["carrizo_salta-n2149-01",3,"Hasta vergüenza me da,\nCantar con mi mala voz,\nCuántos me estarán diciendo:\n—Cantas como para vos!",3,1,0,49,"",0,4,"o",87,0,-1,0,514,514,"2149","",0,"","","",1,0,0,[],""],["carrizo_salta-n2152-01",3,"Hi repechado una loma,\nHi trastornado una cuesta,\nHi salido a una mesada,\nPara ganar una apuesta.",3,1,0,49,"",0,4,"ea",406,0,-1,0,514,514,"2152","",0,"","","",1,0,0,[],""],["carrizo_salta-n2153-01",3,"Hi visto una seña de ojo,\nCon movimiento i pestaña,\nSeña que me va queriendo,\nSi la vista no me engaña.",3,1,0,49,"",0,4,"aa",213,0,-1,0,514,514,"2153","",0,"","","",1,0,0,[],""],["carrizo_salta-n2154-01",3,"Hoy día es la luna llena,\nMañana cuarto menguante,\nSi Ud. se ha comprometido.\nQue su amor salga adelante.",3,1,0,49,"",0,4,"ae",47,0,-1,0,514,514,"2154","",0,"","","",1,0,0,[],""],["carrizo_salta-n2155-01",3,"Hoy me duele la cabeza,\nPero más me duele el pecho,\nCantando con las mujeres,\nSiento que me hace provecho.",3,1,0,49,"",0,4,"eo",60,0,-1,0,514,514,"2155","",0,"","","",1,0,0,[],""],["carrizo_salta-n2156-01",3,"Hoy sábado por la tarde,\nSe enteran los siete días,\nPor tí empecé a preguntar,\nDe ver que no aparecías.",3,1,0,49,"",0,4,"ia",214,0,-1,0,514,514,"2156","",0,"","","",1,0,0,[],""],["carrizo_salta-n2157-01",3,"Jacinta me dió una cinta,\nPetrona me dió un cordón,\nPor Jacinta doy la vida,\nPor Petrona el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,514,514,"2157","",0,"","","",2,0,0,[],""],["carrizo_salta-n2158-01",3,"Jesús María coca,\nRatos, ratos a mi boca,\nEl que hablara mal de mí,\nBien merece un tapaboca.",3,1,0,49,"",0,4,"oa",178,0,-1,0,514,514,"2158","",0,"","","",1,0,0,[],""],["carrizo_salta-n2159-01",3,"Juana, Rosa y María,\nDivino hechizo,\nLas mujeres se mueren\nPor un Carrizo.",3,1,0,49,"",6,4,"io",95,0,-1,0,515,515,"2159","",0,"","","",1,0,0,[],""],["carrizo_salta-n2160-01",3,"Junto al camino, si,\nLa chiquitita,\nDice que tiene miedo,\nDormir solita.",3,1,0,49,"",6,4,"ia",50,0,-1,0,515,515,"2160","",0,"","","",2,0,0,[],""],["carrizo_salta-n2161-01",3,"La corriente cuando crece,\nSe lleva piedra y terrón,\nMi amor que está resfalando,\nSe lleva tu corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,515,515,"2161","",0,"","","",1,0,0,[],""],["carrizo_salta-n2162-01",3,"La culebra en las espinas,\nSe enrosca y desaparece,\nLa mujer que engaña a un hombre,\nCorona de oro merece.",3,1,0,49,"",0,4,"ee",64,0,-1,0,515,515,"2162","",0,"","","",1,0,0,[],""],["carrizo_salta-n2163-01",3,"La china que yo les digo,\nNo es malacara ni zaina,\nY en mi pecho está metida,\nComo cuchillo en la vaina.",3,1,0,49,"",0,4,"aa",323,0,-1,0,515,515,"2163","",0,"","","",1,0,0,[],""],["carrizo_salta-n2163-a-01",3,"La mujer que a mí me quiera,\nNo es ni zaina ni alazana,\nEstá metida en mi pecho,\nComo cuchillo en la vaina.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,515,515,"2163-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n2164-01",3,"La fallanquiadora,\nLa fallanquiadora,\n¡Tan linda la rubia,\nTan sargentiadora!",3,1,0,49,"",0,4,"oa",107,0,-1,0,515,515,"2164","",0,"","","",1,0,0,[],""],["carrizo_salta-n2165-01",3,"La guitarra está machada,\nY el que la toca también,\nLos señores bailarines,\nNo se pueden mantener.",3,1,0,49,"",0,4,"e",-1,0,-1,0,515,515,"2165","",0,"","","",1,0,0,[],""],["carrizo_salta-n2166-01",3,"La luna para salir,\nLe pide licencia al cielo,\nYo para cantar aquí,\nSe lo pido con recelo.",3,1,0,49,"",0,4,"eo",10,0,-1,0,515,515,"2166","",0,"","","",14,0,0,[],""],["carrizo_salta-n2167-01",3,"La mujer es un veneno,\nQue poquito a poco mata,\nY toditos las buscamos,\nComo si fueran de plata.",3,1,0,49,"",0,4,"aa",74,0,-1,0,515,515,"2167","",0,"","","",2,0,0,[],""],["carrizo_salta-n2168-01",3,"La mujer no necesita,\nTener de su amante queja,\nSi otro le parece bien,\nAl mismo tiempo lo deja.",3,1,0,49,"",0,4,"ea",165,0,-1,0,516,516,"2168","",0,"","","",1,0,0,[],""],["carrizo_salta-n2169-01",3,"La mujer que a los treinta,\nConfiesa quince,\nEs loca de remate,\nO es una lince.",3,1,0,49,"",6,4,"ie",430,0,-1,0,516,516,"2169","",0,"","","",1,0,0,[],""],["carrizo_salta-n2170-01",3,"La mujer que a mí me quiera,\nHa de ser del gusto mío,\nHa de salir para fuera,\nCuando yo le haga pío, pío.",3,1,0,49,"",1,4,"io",3,0,-1,0,516,516,"2170","",0,"","","",3,0,0,[],""],["carrizo_salta-n2171-a-01",3,"La mujer que quiera a dos\n¿Cuál será su pensamiento?\nCuando se junten los dos,\n¿A cuál dará cumplimiento?",3,1,0,49,"",1,4,"eo",94,0,-1,0,516,516,"2171-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2172-01",3,"La mujer que quiere a un negro,\nNegro tiene el corazón,\nHaga de cuenta que quiere\nA un_pila negro rabón.",3,1,0,49,"",0,4,"o",31,0,-1,0,516,516,"2172","",0,"","","",1,0,0,[],""],["carrizo_salta-n2173-01",3,"L'año pasao pa este tiempo,\nSe me murió mi mujer,\nDesde entonces cargo luto\nPara acabarme i j...",3,1,0,49,"",5,4,"",-1,0,-1,0,516,516,"2173","",0,"","","",1,0,0,[],""],["carrizo_salta-n2174-01",3,"La paloma baja al agua,\nVestida de verde mar,\nYo no les creo a los hombres,\nAunque los vea llorar.",3,1,0,49,"",0,4,"a",21,0,-1,0,516,516,"2174","",0,"","","",2,0,0,[],""],["carrizo_salta-n2175-01",3,"La perla con el coral,\nEstán en un argumento,\nLa perla le da sus quejas\nY el coral su sentimiento.",3,1,0,49,"",0,4,"eo",94,0,-1,0,516,516,"2175","",0,"","","",1,0,0,[],""],["carrizo_salta-n2176-01",3,"¡La p u.. que me da rabia,\nCuando pido y no me dan!\nSabiendo que yo les pido,\nCon toda necesidad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,516,516,"2176","",0,"","","",1,0,0,[],""],["carrizo_salta-n2177-01",3,"La relación que me has dicho,\nMe ha hecho doler las muelas,\nYo no sé bromiar contigo,\nAndá a bromiar a tu agüela.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,516,516,"2177","",0,"","","",1,0,0,[],""],["carrizo_salta-n2178-01",3,"Las mocitas de este tiempo,\nMuy bien puestitas se salen,\nDe peinetilla y horquilla,\n¡Vamos a ver lo que valen!",3,1,0,49,"",0,4,"ae",227,0,-1,0,516,516,"2178","",0,"","","",3,0,0,[],""],["carrizo_salta-n2179-01",3,"Las mocitas de este tiempo,\nSon como la cortadera,\nPor ver de echar una copla,\nLes da chuscho y tembladera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,517,517,"2179","",0,"","","",3,0,0,[],""],["carrizo_salta-n2179-a-01",3,"Las mocitas no me quieren,\nPorque soy firme y rogado,\nEllas han de estar queriendo,\nUn buenmozo y entregado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,517,517,"2179-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2180-01",3,"Las muchachas de estos tiempos,\nSon como la \"madre el viento\"\nNo se contentan con uno,\nSino sólo con trescientos.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,518,518,"2180","",0,"","","",2,0,0,[],""],["carrizo_salta-n2181-01",3,"Las mujeres a los quince,\nSon más dulces que el almíbar\nY llegando a los cuarenta,\nSon más amargas que acíbar.",3,1,0,49,"",0,4,"ia",431,0,-1,0,518,518,"2181","",0,"","","",3,0,0,[],""],["carrizo_salta-n2182-01",3,"Las mujeres de este tiempo,\nSon como la tijerilla,\nEn vez de andar con sus mamas,\nAndan con una tropilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,518,518,"2182","",0,"","","",8,0,0,[],""],["carrizo_salta-n2183-01",3,"Las mujeres de este tiempo,\nSon como la tormenta,\nPuro refucilo y trueno,\nViene el viento y las ahuyenta.",3,1,0,49,"",3,4,"ea",229,0,-1,0,518,518,"2183","",0,"","","",8,0,0,[],""],["carrizo_salta-n2184-01",3,"Las mujeres no me quieren,\nDiciendo que soy casado,\nNo saben las pobrecitas\nQue el casado es bendisado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,519,519,"2184","",0,"","","",7,0,0,[],""],["carrizo_salta-n2184-02",3,"Las mujeres no me quieren,\nDiciendo que soy casado,\nNo saben las pobrecitas\nQue ser soltero es petardo.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,519,519,"2184","",0,"","","",7,0,0,[],""],["carrizo_salta-n2185-01",3,"Las mujeres de estos tiempos,\nTienen muchas pretensiones,\nY le deben al tendero,\nLa camisa y los calzones.",3,1,0,49,"",0,4,"oe",34,0,-1,0,519,519,"2185","",0,"","","",4,0,0,[],""],["carrizo_salta-n2186-01",3,"Las mujeres no me quieren,\nPorque m'hi puesto el lapacho,\nEllas estarán queriendo,\nUno de bota y bombacho.",3,1,0,49,"",0,4,"ao",310,0,-1,0,519,519,"2186","",0,"","","",7,0,0,[],""],["carrizo_salta-n2187-01",3,"Las mujeres no me quieren,\nPorque no tengo bigote,\nPero ya me están brotando\nComo pata i chilicote.",3,1,0,49,"",0,4,"oe",292,0,-1,0,519,519,"2187","",0,"","","",7,0,0,[],""],["carrizo_salta-n2188-01",3,"Las mujeres no me quieren\nPorque soy mozo de ojota,\nEllas estarán queriendo,\nMocitos de media bota.",3,1,0,49,"",0,4,"oa",432,0,-1,0,519,519,"2188","",0,"","","",7,0,0,[],""],["carrizo_salta-n2189-01",3,"Las mujeres no me quieren,\nPorque yo sé trabajar,\nSi yo fuera un haragán,\nMujeres me había i sobrar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,519,519,"2189","",0,"","","",7,0,0,[],""],["carrizo_salta-n2190-01",3,"Las nubes se van cargando,\nPara el centro de Bolivia,\nEsta noche va a llover\nGoteras de agua florida.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,519,519,"2190","",0,"","","",1,0,0,[],""],["carrizo_salta-n2191-01",3,"Las palabras las mujeres,\nSon como la caña vana,\nLo que prometen hoy día,\nYa no se acuerdan mañana.",3,1,0,49,"",0,4,"aa",4,0,-1,0,519,519,"2191","",0,"","","",1,0,0,[],""],["carrizo_salta-n2192-01",3,"Las salteñas son de plata,\nLas vallistas de algodón,\nTucumanas de aguardiente,\nSantiagueñas de mistol.",3,1,0,49,"",0,4,"o",-1,0,-1,0,519,519,"2192","",0,"","","",1,0,0,[],""],["carrizo_salta-n2193-01",3,"¡Lástima me da cortar,\nLa flor cuando está en botón!\nSi está cerrada, dejarla,\nPara mejor ocasión.",3,1,0,49,"",0,4,"o",31,0,-1,0,519,519,"2193","",0,"","","",1,0,0,[],""],["carrizo_salta-n2194-01",3,"¡Lástima que ya estoy viejo\nY avanzado de l'edad!\nEl consuelo que me queda,\nQue gocé en mi mocedad.",3,1,0,49,"",0,4,"a",16,0,-1,0,519,519,"2194","",0,"","","",1,0,0,[],""],["carrizo_salta-n2195-01",3,"La tarde viene lloviendo,\nLas nubes están saliendo,\n¡Deme lo que ando quiriendo,\nNo me lo niegue teniendo!",3,1,0,49,"",0,4,"eo",52,0,-1,0,520,520,"2195","",0,"","","",1,0,0,[],""],["carrizo_salta-n2196-01",3,"La tonada es rumiarqueña,\nLa dueña es cachipampeña,\nSuspiros de una salteña,\nLágrimas de una pomeña.",3,1,0,49,"",0,4,"ea",291,0,-1,0,520,520,"2196","",0,"","","",1,0,0,[],""],["carrizo_salta-n2197-01",3,"¡Lechuguita, lechuguita!\nLechuguita con vinagre,\nSi querís que yo te cante,\nNo t'hi de cantar de balde.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,520,520,"2197","",0,"","","",1,0,0,[],""],["carrizo_salta-n2198-01",3,"¡Lechuga sin flor!\n¡Lechuga sin flor!\n¿Qué andas diciendo\nCon tanto calor?",3,1,0,49,"",6,4,"o",72,0,-1,0,520,520,"2198","",0,"","","",2,0,0,[],""],["carrizo_salta-n2199-01",3,"Le digo, vídita mía,\nYo me muero por Ud.\nSi Ud. se muere por otro,\n¡Bien haiga el mundo al revés!",3,1,0,49,"",5,4,"e",-1,0,-1,0,520,520,"2199","",0,"","","",1,0,0,[],""],["carrizo_salta-n2200-01",3,"Les voy a contar un caso,\nPara que puedan guiarse,\nConviene siempre tener,\nMujer a donde rascarse.",3,1,0,49,"",0,4,"ae",250,0,-1,0,520,520,"2200","",0,"","","",1,0,0,[],""],["carrizo_salta-n2201-01",3,"Licencia pido, señores,\nPara cantar y bailar,\nAl señor dueño de casa,\nCompadre de este lugar.",3,1,0,49,"",0,4,"a",21,0,-1,0,520,520,"2201","",0,"","","",2,0,0,[],""],["carrizo_salta-n2202-01",3,"Los botines tengo rotos,\n¿Con qué los remendaré?\nCon puntas de malas lenguas,\nQue dicen lo que no es.",3,1,0,49,"",0,4,"e",-1,0,-1,0,520,520,"2202","",0,"","","",1,0,0,[],""],["carrizo_salta-n2203-01",3,"Los cabellos de una rubia,\nDicen que tienen veneno,\nYo he de casarme con una,\nQue el veneno es un remedio.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,520,520,"2203","",0,"","","",1,0,0,[],""],["carrizo_salta-n2204-01",3,"Los mocitos de este tiempo,\nParecen de rupachico,\nSi ven una moza linda,\nSe les hace agua el hocico.",3,1,0,49,"",0,4,"io",141,0,-1,0,520,520,"2204","",0,"","","",2,0,0,[],""],["carrizo_salta-n2205-01",3,"Los mocitos de este tiempo,\nSon como la cerrazón,\nTras de las niñas bonitas\nSe van como en procesión.",3,1,0,49,"",0,4,"o",31,0,-1,0,520,520,"2205","",0,"","","",2,0,0,[],""],["carrizo_salta-n2206-01",3,"Los mocitos de estos tiempos,\nSon como la sota i basto,\nCuando gastan diez centavos,\nDicen que hacen mucho gasto.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,520,520,"2206","",0,"","","",2,0,0,[],""],["carrizo_salta-n2207-01",3,"Los mocitos de estos tiempos,\nSon pinturita de barro,\nCuando salen a farriar,\nNo tienen diez pa cigarro.",3,1,0,49,"",0,4,"ao",392,0,-1,0,521,521,"2207","",0,"","","",2,0,0,[],""],["carrizo_salta-n2208-01",3,"Los mocitos no me quieren\nPorque yo no soy risueña,\nEllos han de estar queriendo,\nRisueñas y cuadrilleras.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,521,521,"2208","",0,"","","",1,0,0,[],""],["carrizo_salta-n2209-01",3,"Los ojitos de mi cara,\n¿Quién me los quiere comprar?\nLos vendo por traicioneros,\nPorque publican mi mal.",3,1,0,49,"",0,4,"a",-1,0,-1,0,521,521,"2209","",0,"rm_t3, palau_cantares","","",13,0,0,[],""],["carrizo_salta-n2210-01",3,"¡Luna de todas las noches!\n¡Lucero al amanecer!\nAndá, decile a tu madre,\nQue ella mi suegra ha de ser.",3,1,0,49,"",0,4,"e",20,0,-1,0,521,521,"2210","",0,"","","",2,0,0,[],""],["carrizo_salta-n2211-01",3,"Luna nueva, luna entera,\nLuna de franco bandera,\nPoca facilidad tengo,\nY mi dueño no es cualquiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,521,521,"2211","",0,"","","",1,0,0,[],""],["carrizo_salta-n2212-01",3,"¡Ma, canten como yo canto!\n¡Como yo canto, ma, canten!\nLo de adelante pa atrás,\nLo de atrás para delante.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,521,521,"2212","",0,"","","",1,0,0,[],""],["carrizo_salta-n2212-01-e2",3,"¡Malditos sean los hombres!\nY el demonio se los lleve,\nSalvado sea mi padre,\nY el moreno que me quiere.",3,1,0,49,"",0,4,"ee",-1,0,-1,0,521,521,"2212","",0,"","","",3,0,0,[],""],["carrizo_salta-n2213-01",3,"Mal estoy de la memoria,\nY del pulso tiritando,\nDame el tintero y la pluma,\nPa que te vaya dictando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,521,521,"2213","",0,"","","",1,0,0,[],""],["carrizo_salta-n2214-01",3,"¡Mal vas por ese camino,\nVolvé pa atrás criatura;\nDejá el llanto pa los tristes,\nQue la vida poco dura!",3,1,0,49,"",0,4,"ua",17,0,-1,0,521,521,"2214","",0,"","","",1,0,0,[],""],["carrizo_salta-n2216-01",3,"¡Malhaya la cocina!\n¡Malhaya el humo!\n¡Malhaya quien se fía\nDe hombre ninguno!",3,1,0,49,"",6,4,"uo",-1,0,-1,0,521,521,"2216","",0,"","","",1,0,0,[],""],["carrizo_salta-n2217-01",3,"¡Malhaya quien dijo amor,\nEn vez de decir veneno,\nQue el veneno pronto mata,\nY el amor mucho dilata.",3,1,0,49,"",5,4,"aa",74,0,-1,0,522,522,"2217","",0,"","","",6,0,0,[],""],["carrizo_salta-n2218-01",3,"Mancarrón que has recorrido\nPor la costa del Pasaje,\nSi tu amor está en la banda,\nNo hay creciente que te ataje.",3,1,0,49,"",0,4,"ae",231,0,-1,0,522,522,"2218","",0,"","","",1,0,0,[],""],["carrizo_salta-n2219-01",3,"Mañana, cuando me muera,\nCerrarán mis documentos,\nAsí nadie podrá leer,\nLo que está en mi pensamiento.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,522,522,"2219","",0,"","","",2,0,0,[],""],["carrizo_salta-n2220-01",3,"Mañana, cuando me vaya,\nCantaré en \"La Lagunilla\",\nSegún vaya caminando,\nCantaré en la serranía.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,522,522,"2220","",0,"","","",9,0,0,[],""],["carrizo_salta-n2221-01",3,"Mañana, cuando me vaya,\nUn recuerdo llevaré,\nLlevaré un recuerdo grato,\nDe quién me supo querer.",3,1,0,49,"",0,4,"e",-1,0,-1,0,522,522,"2221","",0,"","","",9,0,0,[],""],["carrizo_salta-n2222-01",3,"Mañana me voy de aquí,\nCuando todos me estén viendo,\nYo también les pago a todos,\nNada les quedo debiendo.",3,1,0,49,"",0,4,"eo",52,0,-1,0,522,522,"2222","",0,"","","",8,0,0,[],""],["carrizo_salta-n2223-01",3,"Mañana me voy\nMe voy pal Aibal,\nAhora soy libre,\nSoy dueña de amar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,522,522,"2223","",0,"","","",6,0,0,[],""],["carrizo_salta-n2224-01",3,"Mañana me voy,\nMe voy pal Mollar.\nPorque allá no hay cuentos,\nNi saben celar.",3,1,0,49,"",0,4,"a",21,0,-1,0,522,522,"2224","",0,"","","",6,0,0,[],""],["carrizo_salta-n2225-01",3,"Mañana por la mañana,\nMe voy a \"Las Cinco Esquinas\",\nA tomar un mate amargo\nQue me lo cebe mi china.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,522,522,"2225","",0,"","","",14,0,0,[],""],["carrizo_salta-n2225-02",3,"Me alegro que te diviertas,\nY que te hayas divertido,\nMe alegro que te diviertas,\nCon lo que yo no he querido.",3,1,0,49,"",1,4,"io",101,0,-1,0,522,522,"2225","",0,"","","",1,0,0,[],""],["carrizo_salta-n2227-01",3,"Me dicen que no ande triste,\nQue anda la melancolía,\nPor eso en mi pecho reina,\nDesde entonces la alegría.",3,1,0,49,"",0,4,"ia",0,0,-1,0,522,522,"2227","",0,"","","",1,0,0,[],""],["carrizo_salta-n2228-01",3,"Me dices de pocas plumas,\nEn verdad tienes razón,\nPorque vos me las robastes,\nPara hacerte tu colchón.",3,1,0,49,"",0,4,"o",31,0,-1,0,522,522,"2228","",0,"","","",1,0,0,[],""],["carrizo_salta-n2229-01",3,"Me dices que lo pesemos,\nEstá bien lo pesaremos,\nComo la piedra del río,\nMucho pesa, y vale menos.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,522,522,"2229","",0,"","","",1,0,0,[],""],["carrizo_salta-n2230-01",3,"Me fuí a preguntarle al cura,\nSi será bueno cantar,\nY el cura me respondió:\n—¡Metalé hasta descansar!",3,1,0,49,"",0,4,"a",21,0,-1,0,522,522,"2230","",0,"","","",1,0,0,[],""],["carrizo_salta-n2231-01",3,"Me gusta encender el fuego,\nPor no estar sopla que sopla,\nA mí no me han de correr,\nCantando una sola copla.",3,1,0,49,"",0,4,"oa",433,0,-1,0,522,522,"2231","",0,"","","",1,0,0,[],""],["carrizo_salta-n2232-01",3,"Me gusta tomar el vino,\nLa chicha y el aguardiente,\n¿Cuya esta casa será?\n¿Será de algún presidente?",3,1,0,49,"",0,4,"ee",15,0,-1,0,522,522,"2232","",0,"","","",1,0,0,[],""],["carrizo_salta-n2233-01",3,"Me han mandado que le cobre,\nA mi señor cantinero,\nCinco pesos por oveja,\nDos cincuenta por carnero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,523,523,"2233","",0,"","","",1,0,0,[],""],["carrizo_salta-n2234-01",3,"Me ocuparon de hortelano,\nY me puse a plantar lima,\nCon esmero la cuidé,\nComo es la planta, es la estima.",3,1,0,49,"",0,4,"ia",302,0,-1,0,523,523,"2234","",0,"","","",1,0,0,[],""],["carrizo_salta-n2235-01",3,"Me puse a labrar un palo,\nMe responde la madera:\n—Un besito de tu boca\nNo lo merece cualquiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,523,523,"2235","",0,"","","",1,0,0,[],""],["carrizo_salta-n2236-01",3,"Me voy a los \"Chacos de Orán\",\nAllá no hay penas,\nNi saben celar.\nMe voy a los \"Chacos de Orán\".",3,1,0,49,"",3,4,"a",-1,0,-1,0,523,523,"2236","",0,"","","",1,0,0,[],""],["carrizo_salta-n2237-01",3,"Me voy a hacer un barquito,\nDe cáscaras de jarilla,\nPara embarcar corazones,\nDe Angastaco a Pucarilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,523,523,"2237","",0,"","","",2,0,0,[],""],["carrizo_salta-n2238-01",3,"Me voy a hacer un barquito,\nDe cáscara de nogal,\nPara embarcar corazones,\nMiraflores y El Ceibal.",3,1,0,49,"",0,4,"a",1,0,-1,0,523,523,"2238","",0,"","","",2,0,0,[],""],["carrizo_salta-n2239-01",3,"Me voy a hacer un carrito,\nDe astillitas de marfil,\nPara embarcar corazones,\nDel paguito de \"El Carril\".",3,1,0,49,"",0,4,"i",290,0,-1,0,523,523,"2239","",0,"","","",1,0,0,[],""],["carrizo_salta-n2240-01",3,"Me voy pal Aibal,\nMe voy pal Aibal,\nPorque allí son buenos,\nNo saben celar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,523,523,"2240","",0,"","","",1,0,0,[],""],["carrizo_salta-n2241-01",3,"Mi amante me dijo anoche,\nQue cantara y no llorara,\nQue echara canas al aire,\nPero que no la olvidara.",3,1,0,49,"",0,4,"aa",57,0,-1,0,523,523,"2241","",0,"","","",3,0,0,[],""],["carrizo_salta-n2242-01",3,"Mi amorcito con el tuyo,\nAndan medio enredaditos,\nParece sachamorita\nQue está en la bañaderita.",3,1,0,49,"",5,4,"ia",50,0,-1,0,523,523,"2242","",0,"","","",1,0,0,[],""],["carrizo_salta-n2243-01",3,"Mi caballo es caballero,\nNo quiere comer cebada,\nEl quiere comer cariños,\nY eso no mantiene nada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,523,523,"2243","",0,"","","",1,0,0,[],""],["carrizo_salta-n2244-01",3,"Mi caballo es escribano,\nTiene en la frente un letrero,\nLas letras vienen diciendo:\n¡Amito, saquemé el freno!",3,1,0,49,"",0,4,"eo",-1,0,-1,0,523,523,"2244","",0,"","","",1,0,0,[],""],["carrizo_salta-n2245-01",3,"Mi caballo me ha cobrado,\nLos años que me ha servido,\nYo también l'hi de hacer cargo,\nEl pasto que me ha comido.",3,1,0,49,"",0,4,"io",101,0,-1,0,523,523,"2245","",0,"","","",1,0,0,[],""],["carrizo_salta-n2246-01",3,"Mi cigarro se ha apagado,\nAyudemén a encender,\nMil gracias les doy, señores,\nSe saben compadecer.",3,1,0,49,"",0,4,"e",20,0,-1,0,523,523,"2246","",0,"","","",1,0,0,[],""],["carrizo_salta-n2247-01",3,"Mi corazón no se cose,\nNi con el hilo más fino,\nMi corazón ha nacido,\nPara ser firme y querido.",3,1,0,49,"",0,4,"io",101,0,-1,0,524,524,"2247","",0,"","","",1,0,0,[],""],["carrizo_salta-n2248-01",3,"Mi fiero pajaro,\nMi hermoso halcón,\nVuela muy alto,\nAl reino del sol.",3,1,0,49,"",6,4,"o",-1,0,-1,0,524,524,"2248","",0,"","","",1,0,0,[],""],["carrizo_salta-n2249-01",3,"Mi nombre voy a firmar,\nEn el aro del tambor,\nDesde el vientre de mi madre,\nMe eligieron pa cantor.",3,1,0,49,"",0,4,"o",72,0,-1,0,524,524,"2249","",0,"","","",1,0,0,[],""],["carrizo_salta-n2250-01",3,"Mi señor don Juan Bautista,\nMasque la coca y la yista,\nNo ha de haber ninguna niña,\nQue no se afloje a su vista.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,524,524,"2250","",0,"","","",1,0,0,[],""],["carrizo_salta-n2251-01",3,"Mi padre fué muy cantor,\nMi madre cantó en La Audiencia,\nCómo no hi de salir yo\nCantor por mi descendencia!",3,1,0,49,"",0,4,"ea",46,0,-1,0,524,524,"2251","",0,"","","",1,0,0,[],""],["carrizo_salta-n2252-01",3,"¡Mi palo i chalchal!\n¡Es mi palo i mecer!\nLo meto y lo saco,\nLo vuelvo a poner.",3,1,0,49,"",0,4,"e",20,0,-1,0,524,524,"2252","",0,"","","",2,0,0,[],""],["carrizo_salta-n2253-01",3,"¡Mi palo i chalchal!\n¡Mi palo i nogal!\nNo se vaya sola\nQue yo la h'i llevar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,524,524,"2253","",0,"","","",2,0,0,[],""],["carrizo_salta-n2254-01",3,"Mi querido de fulano,\n¿De ande sale, qué anda haciendo?\n¿En qué diligencias anda?\n¿Qué pasos anda siguiendo?",3,1,0,49,"",0,4,"eo",52,0,-1,0,524,524,"2254","",0,"","","",1,0,0,[],""],["carrizo_salta-n2256-01",3,"¡Mocito lindo\nTan divertido!\nSombrero chato\nY tan rompido.",3,1,0,49,"",6,4,"io",101,0,-1,0,524,524,"2256","",0,"","","",1,0,0,[],""],["carrizo_salta-n2257-01",3,"Morena tiene que ser,\nLa tierra para ser buena,\nY la mujer para el hombre,\nTambién ha de ser morena.",3,1,0,49,"",0,4,"ea",59,0,-1,0,524,524,"2257","",0,"rm_t2, palau_cantares, murciano_antiguo","","",9,0,0,[],""],["carrizo_salta-n2258-01",3,"Morenita soy, señores,\nMorena del Tucumán,\nAsí moreno es el trigo,\nPero blanco sale el pan.",3,1,0,49,"",0,4,"a",147,0,-1,0,524,524,"2258","",0,"","","",2,0,0,[],""],["carrizo_salta-n2259-01",3,"Muriéndome estoy de rabia,\nPorque la fiesta se acaba,\nSi la fiesta me aguardara,\n¡Una semana cantara!",3,1,0,49,"",0,4,"aa",57,0,-1,0,525,525,"2259","",0,"","","",1,0,0,[],""],["carrizo_salta-n2260-01",3,"Nadie me gana en querer,\nSi encuentro correspondencia;\nY si de olvidar se trata,\nSoy la misma indiferencia.",3,1,0,49,"",0,4,"ea",46,0,-1,0,525,525,"2260","",0,"","","",1,0,0,[],""],["carrizo_salta-n2261-01",3,"No amis mujer casada,\nPues una que yo he querido,\nCuando menos lo pensaba,\nSe la llevó su marido.",3,1,0,49,"",0,4,"io",101,0,-1,0,525,525,"2261","",0,"","","",1,0,0,[],""],["carrizo_salta-n2262-01",3,"No atropellen compañeros,\nPorque grande es el portillo,\nSigalén por la misma hebra,\nQue lo han de hallar al ovillo.",3,1,0,49,"",0,4,"io",228,0,-1,0,525,525,"2262","",0,"","","",1,0,0,[],""],["carrizo_salta-n2263-01",3,"No es un capricho el que tengo,\nSino intenciones morales,\nMás se me aumenta la dicha,\nCuando más duran los males.",3,1,0,49,"",0,4,"ae",26,0,-1,0,525,525,"2263","",0,"","","",1,0,0,[],""],["carrizo_salta-n2264-01",3,"No hi de volver a ensillar,\nCaballo marca \"El Tunal\",\nA causa de esos caballos,\nEs que me pagan tan mal.",3,1,0,49,"",0,4,"a",1,0,-1,0,525,525,"2264","",0,"","","",2,0,0,[],""],["carrizo_salta-n2265-01",3,"No hi de volver a ensillar,\nCaballos marca \"Los Pérez\",\nA causa de esos caballos,\nNo me quieren las mujeres.",3,1,0,49,"",0,4,"ee",55,0,-1,0,525,525,"2265","",0,"","","",2,0,0,[],""],["carrizo_salta-n2266-01",3,"No les creo a las mujeres,\nAunque las vea llorar.\nPorque las lágrimas que echan,\nSon calabazas que dan.",3,1,0,49,"",0,4,"a",-1,0,-1,0,525,525,"2266","",0,"","","",1,0,0,[],""],["carrizo_salta-n2267-01",3,"¿No lo ven a este mocoso\nQue me viene a enamorar?\n—¡Andá, decile a tu madre\nQue te enseñe a trabajar!",3,1,0,49,"",0,4,"a",21,0,-1,0,525,525,"2267","",0,"","","",1,0,0,[],""],["carrizo_salta-n2268-01",3,"No me quisiera casar,\nCerquita del Carnaval,\nPa que no me anden tirando,\nComo a burro del bozal.",3,1,0,49,"",0,4,"a",1,0,-1,0,525,525,"2268","",0,"","","",1,0,0,[],""],["carrizo_salta-n2269-01",3,"¡No me tires al ala!\n¡Carabinero!\nQue soy, águila nueva,\nPerderé el vuelo.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,525,525,"2269","",0,"","","",2,0,0,[],""],["carrizo_salta-n2270-01",3,"No porque me vean desnudo,\nDirán que soy resertor,\nNo sólo la patria pela,\nTambién pela el sarampión.",3,1,0,49,"",0,4,"o",-1,0,-1,0,525,525,"2270","",0,"","","",1,0,0,[],""],["carrizo_salta-n2271-01",3,"No quiero encender el fuego,\nPor no estar sopla que sopla,\nEn el paguito de aquí,\nCada cual echa su copla.",3,1,0,49,"",0,4,"oa",433,0,-1,0,526,526,"2271","",0,"","","",1,0,0,[],""],["carrizo_salta-n2272-01",3,"¡No sea bárbaro compadre!\nMire que lo oye su moza,\nY puede creerle que está,\nEntre San Juan y Mendoza.",3,1,0,49,"",0,4,"oa",195,0,-1,0,526,526,"2272","",0,"","","",1,0,0,[],""],["carrizo_salta-n2273-01",3,"No seas cobarde, niña,\nNo seas cobarde,\nGocemos de la vida,\nAntes que acabe.",3,1,0,49,"",6,4,"ae",-1,0,-1,0,526,526,"2273","",0,"","","",1,0,0,[],""],["carrizo_salta-n2274-01",3,"No se case, compañero,\nCon mujer baja y delgada,\nConforme le falta el cuerpo,\nNo tiene firmeza en nada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,526,526,"2274","",0,"","","",1,0,0,[],""],["carrizo_salta-n2275-01",3,"No sé porque estoy cantando,\nGrueso, grueso y desparejo,\nSerá porque me ha salido,\nSobregüeso en el pescuezo.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,526,526,"2275","",0,"","","",1,0,0,[],""],["carrizo_salta-n2276-01",3,"No sé que giro h'i tomar,\nPara seguir mejor giro,\n¡Tan cuánta que no hi cantao!\nVoy desconfiando a mi tino.",3,1,0,49,"",0,4,"io",-1,0,-1,0,526,526,"2276","",0,"","","",1,0,0,[],""],["carrizo_salta-n2277-01",3,"No soy criollo de aquí,\nPorque de Santiago soy,\nSi me miran con desprecio,\nDe mañanita me voy.",3,1,0,49,"",0,4,"o",112,0,-1,0,526,526,"2277","",0,"","","",1,0,0,[],""],["carrizo_salta-n2279-01",3,"No soy morenita linda,\nNi prenda de gran valor,\nSoy morena y a cualquiera,\nLe robo su corazón.",3,1,0,49,"",0,4,"o",-1,0,-1,0,526,526,"2279","",0,"","","",1,0,0,[],""],["carrizo_salta-n2280-01",3,"No soy moza, yo soy vieja,\nComo así tendrá que ser,\nLos años son como el río,\nPara tras no han de correr.",3,1,0,49,"",0,4,"e",20,0,-1,0,526,526,"2280","",0,"","","",1,0,0,[],""],["carrizo_salta-n2281-01",3,"No temo tanto a la muerte,\nComo temo a la vejez,\nLa madre que me parió,\nNo me ha i parir otra vez.",3,1,0,49,"",0,4,"e",150,0,-1,0,526,526,"2281","",0,"","","",1,0,0,[],""],["carrizo_salta-n2282-01",3,"No tengas pena, vidita,\nQue yo hago aquí lo que puedo,\nEn mi casa soy casado,\nSaliendo al campo, soltero.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,526,526,"2282","",0,"","","",1,0,0,[],""],["carrizo_salta-n2283-01",3,"No te vaya a suceder,\nLo que a mí la vez pasada,\nCasi mi hi visto perdido,\nPor querer una casada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,526,526,"2283","",0,"","","",4,0,0,[],""],["carrizo_salta-n2284-01",3,"¡No vé este viejo verde\nComo la tuna!\nTiene la penca seca,\nY la espina dura.",3,1,0,49,"",6,4,"ua",-1,0,-1,0,526,526,"2284","",0,"","","",1,0,0,[],""],["carrizo_salta-n2285-01",3,"¡Oh, qué dichosos serán,\nLos que se aman con ternura!\nY disfrutan con ventura\nLas delicias del amor.",3,1,0,49,"",5,4,"o",-1,0,-1,0,527,527,"2285","",0,"","","",1,0,0,[],""],["carrizo_salta-n2286-01",3,"¡Oiga, diga, cocherito!\n¿Por cuánto me va llevar?\n—Suba nomás amiguito,\nQue nada le va a costar.",3,1,0,49,"",1,4,"a",21,0,-1,0,527,527,"2286","",0,"","","",1,0,0,[],""],["carrizo_salta-n2287-01",3,"¡Oiga la viudita loca!\nNo se cansa de sentir,\nAntes de las nueve noches,\nHallará con quien dormir.",3,1,0,49,"",0,4,"i",157,0,-1,0,527,527,"2287","",0,"","","",1,0,0,[],""],["carrizo_salta-n2289-01",3,"¡Oiga mi señor fulano!\nLo quiero de corazón,\nDentro de mí no hallará,\nNi falsedad ni traición.",3,1,0,49,"",0,4,"o",31,0,-1,0,527,527,"2289","",0,"","","",1,0,0,[],""],["carrizo_salta-n2290-01",3,"¡Oigan compañeros míos!\nY sigan para adelante,\nComo soy mozo ignorante,\nNo les cantaré delante.",3,1,0,49,"",0,4,"ae",47,0,-1,0,527,527,"2290","",0,"","","",1,0,0,[],""],["carrizo_salta-n2291-01",3,"¡Oiganmén señores míos!\nQue vienen a la cocina,\nPor encender el cigarro,\n¡No me pasen por encima!",3,1,0,49,"",0,4,"ia",-1,0,-1,0,527,527,"2291","",0,"","","",1,0,0,[],""],["carrizo_salta-n2292-01",3,"¡Oiga, querido fulano!\nUsté es un amigo mío,\nPor Ud. atravesaría,\nArroyos, mares y ríos.",3,1,0,49,"",0,4,"io",-1,0,-1,0,527,527,"2292","",0,"","","",1,0,0,[],""],["carrizo_salta-n2293-01",3,"¡Ofrecele, ofrecele!\nOfrecele harto,\nUn vestido a la moda\nY casa de alto.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,527,527,"2293","",0,"","","",2,0,0,[],""],["carrizo_salta-n2294-01",3,"¡Ofrecele, ofrecele!\nUna corona,\nDel orito más firme,\nDe California.",3,1,0,49,"",6,4,"oa",-1,0,-1,0,527,527,"2294","",0,"","","",2,0,0,[],""],["carrizo_salta-n2295-01",3,"¡Ojalá gallito\nQue por cantador!\nTe vean mis ojos\nEn un asador.",3,1,0,49,"",0,4,"o",72,0,-1,0,527,527,"2295","",0,"","","",1,0,0,[],""],["carrizo_salta-n2296-01",3,"¡Ojalá vidita mía\nNo tuvieras quién te guarde!\nVileza sería la mía\nPerderte por ser cobarde.",3,1,0,49,"",1,4,"ae",344,0,-1,0,527,527,"2296","",0,"","","",1,0,0,[],""],["carrizo_salta-n2297-01",3,"Otros ya te habrán cantado\nY habrán dado cumplimiento,\nYo te voy a dar el mío,\nCon mi corto entendimiento.",3,1,0,49,"",0,4,"eo",94,0,-1,0,527,527,"2297","",0,"","","",1,0,0,[],""],["carrizo_salta-n2298-01",3,"Otra vez de nuevo quiero,\nEmpezarme a componer,\nLas estrellitas del cielo,\nSe me quieren oponer.",3,1,0,49,"",0,4,"e",20,0,-1,0,527,527,"2298","",0,"","","",1,0,0,[],""],["carrizo_salta-n2299-01",3,"Pa cantar pido licencia,\nAl señor dueño de casa,\nPorque al cabeza mayor,\nSe le dá la primer gracia.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,527,527,"2299","",0,"","","",2,0,0,[],""],["carrizo_salta-n2300-01",3,"¡Pajarillo triste!\n¿Qué andas picando?\nQue andas de rama en rama,\nComo yo me ando.",3,1,0,49,"",6,4,"ao",33,0,-1,0,527,527,"2300","",0,"","","",2,0,0,[],""],["carrizo_salta-n2300-a-01",3,"¡Pajarillo triste\nQue andas volando,\nQue andas de rama en rama,\nCalaveriando!",3,1,0,49,"",6,4,"ao",33,0,-1,0,528,528,"2300-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n2301-01",3,"¡Pajarillo, picaflor,\nNo piques esa florcita!\nCamina más adelante,\nY pica otra mejorcita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,528,528,"2301","",0,"","","",1,0,0,[],""],["carrizo_salta-n2302-01",3,"Palabras sacan palabras,\nRazones sacan razones,\nQuerís mantener amor,\nY no tenís pa calzones.",3,1,0,49,"",0,4,"oe",34,0,-1,0,528,528,"2302","",0,"","","",1,0,0,[],""],["carrizo_salta-n2303-01",3,"Pa'l amor contrariado,\nBuena es la bota.\nY pa halagar a suegras,\nTriunfos son copas.",3,1,0,49,"",6,4,"oa",-1,0,-1,0,528,528,"2303","",0,"","","",1,0,0,[],""],["carrizo_salta-n2304-01",3,"Pa'l amor, la pobreza,\nSiempre es estorbo,\nCon las mozas de ahora,\nTriunfos son oro.",3,1,0,49,"",6,4,"oo",-1,0,-1,0,528,528,"2304","",0,"","","",1,0,0,[],""],["carrizo_salta-n2305-01",3,"Palomita blanca,\nPecho de gasa!\n¿Dónde estará mi negra\nQue no me abraza?",3,1,0,49,"",6,4,"aa",307,0,-1,0,528,528,"2305","",0,"","","",12,0,0,[],""],["carrizo_salta-n2306-01",3,"¡Palomita blanca,\nPiquito de acero!\nVivís en la banda\nY yo en el potrero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,528,528,"2306","",0,"","","",12,0,0,[],""],["carrizo_salta-n2307-01",3,"¡Palomita voladora!\nCortando el hilo te has d'ir,\nY si no cortás el hilo,\nVidita, aquí has de dormir.",3,1,0,49,"",0,4,"i",157,0,-1,0,528,528,"2307","",0,"","","",1,0,0,[],""],["carrizo_salta-n2308-01",3,"Pañuelo blanco, vidita,\nVestidito azul oscuro,\nVamos logrando lo ajeno,\nQue lo nuestro está seguro.",3,1,0,49,"",0,4,"uo",248,0,-1,0,528,528,"2308","",0,"","","",1,0,0,[],""],["carrizo_salta-n2309-01",3,"Para besar una ñata,\nTe has de limpiar el hocico,\n¿Qué ñata te va a besar\nCon esa trompa de mico?",3,1,0,49,"",0,4,"io",141,0,-1,0,528,528,"2309","",0,"","","",1,0,0,[],""],["carrizo_salta-n2310-01",3,"Para cantar con la caja,\nNo se necesita escuela.\nEn caso i necesidad,\nEl ave más vieja vuela.",3,1,0,49,"",0,4,"ea",167,0,-1,0,528,528,"2310","",0,"","","",1,0,0,[],""],["carrizo_salta-n2310-a-01",3,"Para cantar vidalitas,\nNo es preciso ser de escuela,\nNo cortándole las alas\nEl ave más vieja vuela.",3,1,0,49,"",0,4,"ea",167,0,-1,0,528,528,"2310-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2311-01",3,"Para cantar cuatro coplas,\nNo tengo la lengua ruda,\nMemoria y entendimiento,\nSólo la voz no me ayuda.",3,1,0,49,"",0,4,"ua",144,0,-1,0,528,528,"2311","",0,"","","",2,0,0,[],""],["carrizo_salta-n2312-01",3,"Para cantar la vidala,\nEs preciso el ardiliar,\nPara poder disponer,\nCada copla en su lugar.",3,1,0,49,"",0,4,"a",21,0,-1,0,528,528,"2312","",0,"","","",2,0,0,[],""],["carrizo_salta-n2313-01",3,"Para cantar la vidala,\nSoy como tejido a pala,\nY como el acero fino,\nQue no le dentra la bala.",3,1,0,49,"",0,4,"aa",330,0,-1,0,528,528,"2313","",0,"","","",2,0,0,[],""],["carrizo_salta-n2314-01",3,"Pa cantar pido licencia,\nPorque no soy atrevido,\nPorque el hombre divertido,\nSuele perder el sentido.",3,1,0,49,"",0,4,"io",101,0,-1,0,528,528,"2314","",0,"","","",2,0,0,[],""],["carrizo_salta-n2315-01",3,"Para cantar yo quisiera,\nTener eco de sierena,\nY paradito en la rueda,\nNo me ganaría cualquiera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,529,529,"2315","",0,"","","",1,0,0,[],""],["carrizo_salta-n2316-01",3,"Para firme, el oro fino,\nPara falso el oropel,\nPara firme nació el hombre,\nPara falsa la mujer.",3,1,0,49,"",0,4,"e",-1,0,-1,0,529,529,"2316","",0,"","","",1,0,0,[],""],["carrizo_salta-n2317-01",3,"Para Jesús la vergüenza,\nPara Galván el bochorno,\nSi no le sirvo de carga,\nL'hi de servir de soborno.",3,1,0,49,"",0,4,"oo",414,0,-1,0,529,529,"2317","",0,"","","",1,0,0,[],""],["carrizo_salta-n2318-01",3,"Para los hombres celosos,\nTengo un remedio aprobado,\nColgarlos como a campana,\nY azotarlos por porfiados.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,529,529,"2318","",0,"","","",1,0,0,[],""],["carrizo_salta-n2319-01",3,"Para poderla medir,\nTendría que dentrarme a lazo,\nTalvez me pudiera ahugar,\nMe aseguro por si acaso.",3,1,0,49,"",0,4,"ao",145,0,-1,0,529,529,"2319","",0,"","","",1,0,0,[],""],["carrizo_salta-n2320-01",3,"¿Para qué me han dado el jarro\nSi no me han de dar el yuro?\nYa se pasa Carnaval\nY no me encuentro seguro.",3,1,0,49,"",0,4,"uo",248,0,-1,0,529,529,"2320","",0,"","","",1,0,0,[],""],["carrizo_salta-n2321-01",3,"¿Para qué me preguntas\nA dónde vivo?\nSi no sabes mi casa,\n¡Vente conmigo!",3,1,0,49,"",6,4,"io",-1,0,-1,0,529,529,"2321","",0,"","","",3,0,0,[],""],["carrizo_salta-n2322-01",3,"¿Para qué quieres que quiera\nPrenda de tanto valor?\nSi yo solito me basto\nPara sustentar mi amor.",3,1,0,49,"",0,4,"o",72,0,-1,0,529,529,"2322","",0,"","","",1,0,0,[],""],["carrizo_salta-n2323-01",3,"Para querer un amor\nSoy como paica de horcón,\nSoy capaz de abrirme el pecho,\nY entregar te el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,529,529,"2323","",0,"","","",1,0,0,[],""],["carrizo_salta-n2326-01",3,"Para que será el amor?\n-¿Pa consuelo del querer?\nPara qué será el varón?\n-Pal consuelo la mujer.",3,1,0,49,"",0,4,"e",20,0,-1,0,530,530,"2326","",0,"","","",1,0,0,[],""],["carrizo_salta-n2327-01",3,"Para qué vas y vienes\n'ienes y vas?\ni otros con andar menos,\nConsiguen más.",3,1,0,49,"",6,4,"a",51,0,-1,0,530,530,"2327","",0,"","","",7,0,0,[],""],["carrizo_salta-n2329-01",3,"'ara ver qué me hace falta,\n'a'l caso no tengo tino.\n'ara pretender mujeres\n?engo memoria y sentido.",3,1,0,49,"",0,4,"io",-1,0,-1,0,530,530,"2329","",0,"","","",1,0,0,[],""],["carrizo_salta-n2330-01",3,"Para volar nació l'ave,\nPara perfume la flor,\nNo te has de ir sin darme el gusto,\nRecién t'hi tenido amor.",3,1,0,49,"",0,4,"o",72,0,-1,0,530,530,"2330","",0,"","","",1,0,0,[],""],["carrizo_salta-n2331-01",3,"Pasada mi juventud,\nAl sol me irán a botar,\nSiendo una vieja arrugada,\nAsí me sabrán amar.",3,1,0,49,"",0,4,"a",21,0,-1,0,530,530,"2331","",0,"","","",1,0,0,[],""],["carrizo_salta-n2332-01",3,"Pastor, la gente me llama,\nPorque me gusta pastiar,\nCon niña de quince a veinte,\n¡Ay, qué dicha es pastoriar!",3,1,0,49,"",0,4,"a",21,0,-1,0,530,530,"2332","",0,"","","",1,0,0,[],""],["carrizo_salta-n2334-01",3,"Permiso pido, señores,\nEn su rueda cantaré,\nAunque soy medio moreno,\nTalvez no los mancharé.",3,1,0,49,"",0,4,"e",77,0,-1,0,530,530,"2334","",0,"","","",1,0,0,[],""],["carrizo_salta-n2335-01",3,"Perdone mi buen amigo,\nYo le daré una lección,\nLe traigo de Buenos Aires\nOro de composición.",3,1,0,49,"",0,4,"o",31,0,-1,0,530,530,"2335","",0,"","","",1,0,0,[],""],["carrizo_salta-n2336-01",3,"¡Planta de ají!\n¡Planta i poleo!\n¿Dónde estará mi negra,\nQue no la veo?",3,1,0,49,"",6,4,"eo",66,0,-1,0,531,531,"2336","",0,"","","",3,0,0,[],""],["carrizo_salta-n2337-01",3,"¡Plantita i mugrón!\n¡Florcita i laurel!\nMujer no tengo\nNi pienso tener.",3,1,0,49,"",6,4,"e",-1,0,-1,0,531,531,"2337","",0,"","","",1,0,0,[],""],["carrizo_salta-n2338-01",3,"¡Pobrecita mi tonada!\nYa la van hacer quedar,\nEl consuelo que me queda,\nDurmiendo la han de olvidar.",3,1,0,49,"",0,4,"a",21,0,-1,0,531,531,"2338","",0,"","","",1,0,0,[],""],["carrizo_salta-n2339-01",3,"¡Pobrecito ese mocito!\nQue se anda de forastero,\nAntinoche perdió el poncho,\nY anoche perdió el sombrero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,531,531,"2339","",0,"","","",1,0,0,[],""],["carrizo_salta-n2339-02",3,"¡Pobrecito este mocito!\n¡Miren su generación!\nSu madre fué la jarana,\nSu tata la diversión.",3,1,0,49,"",0,4,"o",31,0,-1,0,531,531,"2339","",0,"","","",1,0,0,[],""],["carrizo_salta-n2340-a-01",3,"Para cantar cuatro coplas,\nNo tengo comparación,\nSoy padre de la jarana,\nHijo de la diversión.",3,1,0,49,"",0,4,"o",31,0,-1,0,531,531,"2340-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n2341-01",3,"Ponchito blanco m'hi puesto,\nComo espumita del mar.\nBrilla el lucero en Jujuy,\nEstrellas en Tucumán.",3,1,0,49,"",0,4,"a",-1,0,-1,0,531,531,"2341","",0,"","","",1,0,0,[],""],["carrizo_salta-n2342-01",3,"Por acá me vua largar,\nComo a deshilar un fleco,\n—No te vayas a perder\nComo la ciudad de Esteco.",3,1,0,49,"",0,4,"eo",320,0,-1,0,531,531,"2342","",0,"","","",1,0,0,[],""],["carrizo_salta-n2343-01",3,"Por aquí les cantaré,\nPor ser camino más suave,\nSuplicándoles a todos\nQue canten conforme saben.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,531,531,"2343","",0,"","","",1,0,0,[],""],["carrizo_salta-n2344-01",3,"Por el interés pudiera,\nQue al pobre le hagan favor,\nMás con respecto al amor,\nYa no hay mujer que lo quiera.",3,1,0,49,"",11,4,"ea",44,0,-1,0,531,531,"2344","",0,"","","",1,0,0,[],""],["carrizo_salta-n2345-01",3,"Por esta calle a lo largo,\nRío del Valle, campo de honor,\nJuran que me han de matar,\nTucumán, Salta, La Rioja es mejor.",3,1,0,49,"",3,4,"o",72,0,-1,0,531,531,"2345","",0,"","","",5,0,0,[],""],["carrizo_salta-n2346-01",3,"¡Por la Cañada de Páez,\nPartido de \"El Totoral\",\nLloraban dos palomitas,\nPor un solo gavilán.",3,1,0,49,"",0,4,"a",-1,0,-1,0,531,531,"2346","",0,"","","",1,0,0,[],""],["carrizo_salta-n2347-01",3,"Por la señal de la cruz,\nQue me voy a persignar,\nNo venga el diablo maldito,\nPara quererme tentar.",3,1,0,49,"",0,4,"a",21,0,-1,0,531,531,"2347","",0,"","","",1,0,0,[],""],["carrizo_salta-n2348-01",3,"Por milagro qu'hi venío,\nEcharé mi relancina,\nLas coplas con los cantores,\nDan vueltas en la cocina.",3,1,0,49,"",0,4,"ia",11,0,-1,0,531,531,"2348","",0,"","","",1,0,0,[],""],["carrizo_salta-n2349-01",3,"Por mujeres no me pierdo,\nCuando se empaca un amor,\nMe doy vuelta el tirador,\nY si te ví no me acuerdo.",3,1,0,49,"",11,4,"eo",350,0,-1,0,532,532,"2349","",0,"","","",1,0,0,[],""],["carrizo_salta-n2350-01",3,"Porque me ven chiquitito,\nY porque vine en empelo,\nYa dicen que no soy hombre,\nDigno de pisar el suelo.",3,1,0,49,"",0,4,"eo",10,0,-1,0,532,532,"2350","",0,"","","",2,0,0,[],""],["carrizo_salta-n2351-01",3,"Porque me ven poncho blanco,\nMe dirán que soy carnero.\nPor mi modo i pretender,\nSoy mejor que un caballero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,532,532,"2351","",0,"","","",1,0,0,[],""],["carrizo_salta-n2351-a-01",3,"Porque me ven poncho i lana,\nYa dicen que soy carnero,\nYo también sé pretender\nComo el mejor caballero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,532,532,"2351-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2352-01",3,"Porque me ven mala traza,\nYa me aborrece la gente,\nY soy capaz de dormir,\nCon l'hija del presidente.",3,1,0,49,"",0,4,"ee",15,0,-1,0,532,532,"2352","",0,"","","",1,0,0,[],""],["carrizo_salta-n2353-01",3,"Porque me ven orejano,\nTodas me quieren marcar.\nSi quieren que yo sea suyos\nPrimero me han de comparar.",3,1,0,49,"",0,4,"a",21,0,-1,0,532,532,"2353","",0,"","","",1,0,0,[],""],["carrizo_salta-n2354-01",3,"¿Por qué no cantan señores?\n¿Por qué están tan calladitos?\n¿Qué no han visto en el verano\nQué bullen los pajaritos?",3,1,0,49,"",0,4,"io",254,0,-1,0,532,532,"2354","",0,"","","",2,0,0,[],""],["carrizo_salta-n2355-01",3,"¿Por qué no cantan señores?\n¿Y digan por qué están tristes?\n¿Qué no han visto que el verano\nDe hojitas verdes se viste?",3,1,0,49,"",0,4,"ie",-1,0,-1,0,532,532,"2355","",0,"","","",2,0,0,[],""],["carrizo_salta-n2356-01",3,"Por querer una casada,\nCasi m'hi visto abatido,\nPor milagro que me quiso,\nLlegó a saber su marido.",3,1,0,49,"",0,4,"io",-1,0,-1,0,532,532,"2356","",0,"","","",1,0,0,[],""],["carrizo_salta-n2357-01",3,"Por querer y andar queriendo,\nY por querer me han dejao,\nAmarillo largo y seco,\nComo vela de finao.",3,1,0,49,"",0,4,"ao",98,0,-1,0,532,532,"2357","",0,"","","",1,0,0,[],""],["carrizo_salta-n2358-01",3,"¿Por qué te quieres morir?\nNo quieras pasar de largo,\nQue yo no soy San Antonio,\nPara hacerte los milagros.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,532,532,"2358","",0,"","","",1,0,0,[],""],["carrizo_salta-n2359-01",3,"¡Por una que está en la rueda,\nVelay por esa me muero!\nY se llama la vidita..\n¡Velay, que ya no me acuerdo!",3,1,0,49,"",0,4,"eo",-1,0,-1,0,532,532,"2359","",0,"","","",1,0,0,[],""],["carrizo_salta-n2360-01",3,"Por una blanca rubia,\nMe llevó el diablo,\nPor una morenita,\nVengo y me salvo.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,532,532,"2360","",0,"","","",1,0,0,[],""],["carrizo_salta-n2360-a-01",3,"Por una tucumana,\nMe llevó el diablo,\nPor una salteñita\nMe estoy salvando.",3,1,0,49,"",6,4,"ao",-1,0,-1,0,532,532,"2360-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2361-01",3,"- Potrereño soy señores,\nPotrereño como quiera,\nOjotitas doble suela\nSoy más gaucho que mi agüela.",3,1,0,49,"",0,4,"ea",167,0,-1,0,533,533,"2361","",0,"","","",1,0,0,[],""],["carrizo_salta-n2362-01",3,"Primero es una mirada,\nUna sonrisa después,\nCon un apretón de manos,\nAsí se empieza a querer.",3,1,0,49,"",0,4,"e",-1,0,-1,0,533,533,"2362","",0,"","","",1,0,0,[],""],["carrizo_salta-n2362-02",3,"¡Pucha que soy divertido!\nChupador sin avenencia,\nEs genio que Dios me ha dado,\nSeñores, tengan paciencia.",3,1,0,49,"",0,4,"ea",46,0,-1,0,533,533,"2362","",0,"","","",1,0,0,[],""],["carrizo_salta-n2364-01",3,"Puede decir lo que quiera,\nQue no me espantan sus dichos,\nPorque estoy acostumbrado,\nA lidiar con todo bicho.",3,1,0,49,"",0,4,"io",-1,0,-1,0,533,533,"2364","",0,"","","",1,0,0,[],""],["carrizo_salta-n2365-01",3,"¡Puta que soy tomador!\n¡La pucha que soy borracho!\nUnos toman yo me macho,\nOtros comen yo me empacho.",3,1,0,49,"",0,4,"ao",310,0,-1,0,533,533,"2365","",0,"","","",1,0,0,[],""],["carrizo_salta-n2366-01",3,"¡Quí alegriya, este año!\nPa Carnaval,\nCantando juntos\nMos de pasar.",3,1,0,49,"",6,4,"a",-1,0,-1,0,533,533,"2366","",0,"","","",1,0,0,[],""],["carrizo_salta-n2367-01",3,"¡Qué arbolito tan hermoso!\n¡Qué clavel tan encendido!\n¡Qué niña tan de mi gusto!\nEsta que baila conmigo.",3,1,0,49,"",0,4,"io",-1,0,-1,0,533,533,"2367","",0,"","","",1,0,0,[],""],["carrizo_salta-n2368-01",3,"¡Qué bien te lo dijo el cura\nCon el señor sacristán!\nQue nunca, quieras a nadie,\nNo siendo Simón Pistán.",3,1,0,49,"",0,4,"a",147,0,-1,0,533,533,"2368","",0,"","","",1,0,0,[],""],["carrizo_salta-n2369-01",3,"¿Qué cantar voy a cantar\nPara no ofender a Dios?\nSi no hay cantar que no tenga,\nDos palabritas de amor.",3,1,0,49,"",0,4,"o",-1,0,-1,0,533,533,"2369","",0,"","","",1,0,0,[],""],["carrizo_salta-n2370-01",3,"¿Qué copla cantaré yo,\nCuándo soy tan ignorante?\nLa memoria se me va\nPorque no soy estudiante.",3,1,0,49,"",0,4,"ae",47,0,-1,0,533,533,"2370","",0,"","","",1,0,0,[],""],["carrizo_salta-n2371-01",3,"¿Qué dedo m'hi de cortar\nQue no m'hi de sacar sangre?\nA todas las quiero igual,\nComo la quiero a mi madre.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,533,533,"2371","",0,"","","",1,0,0,[],""],["carrizo_salta-n2372-01",3,"¿Qué haremos compañeritos\nCon estos hombres sentaos?\nParecen troncos quemaos\nDe los Sanjuanes pasaos.",3,1,0,49,"",0,4,"ao",342,0,-1,0,533,533,"2372","",0,"","","",2,0,0,[],""],["carrizo_salta-n2373-01",3,"¿Qué haré yo para cantar,\nAhora que se ha ofrecido?\nComo quiera lo hi de hacer\nPor cumplir lo prometido.",3,1,0,49,"",0,4,"io",101,0,-1,0,533,533,"2373","",0,"","","",2,0,0,[],""],["carrizo_salta-n2374-01",3,"¿Qué haré yo para cantar\nYa que todos me han pedido?\nYo no quiero ser rogado,\nNi menos aborrecido.",3,1,0,49,"",0,4,"io",101,0,-1,0,533,533,"2374","",0,"","","",2,0,0,[],""],["carrizo_salta-n2377-01",3,"¡Qué les parece, señores,\nSi me ocuparan en algo?\nTalvez les podría servir\nComo su mayor esclavo.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,534,534,"2377","",0,"","","",3,0,0,[],""],["carrizo_salta-n2378-01",3,"Qué linda es la mañanita!\nQué lindo el amanecer!\nMás lindos son los amores\nCuando los dejan crecer.",3,1,0,49,"",0,4,"e",20,0,-1,0,534,534,"2378","",0,"","","",1,0,0,[],""],["carrizo_salta-n2379-01",3,"¡Qué lindo es pa Carnaval\nCuando todo es alegría,\nCuando cantan los jilgueros\nTres horas antes del día!",3,1,0,49,"",0,4,"ia",0,0,-1,0,534,534,"2379","",0,"","","",1,0,0,[],""],["carrizo_salta-n2380-01",3,"Que repiquen las campanas,\nY que redoble el tambor,\nLa mujer que no me quiera,\nNo tiene perdón de Dios.",3,1,0,49,"",0,4,"o",-1,0,-1,0,534,534,"2380","",0,"","","",1,0,0,[],""],["carrizo_salta-n2381-01",3,"¿Querís bueno?\n¿Tenís dueño?\nVos querís dormir,\nSin sueño.",3,1,0,49,"",3,4,"eo",138,0,-1,0,534,534,"2381","",0,"","","",1,0,0,[],""],["carrizo_salta-n2382-01",3,"¿Qué te diré, cantorcito,\nQue cantas tan por bajito?\nAndá para el gallinero,\nY cántale a los pollitos.",3,1,0,49,"",0,4,"io",-1,0,-1,0,534,534,"2382","",0,"","","",1,0,0,[],""],["carrizo_salta-n2383-01",3,"¡Qué te parece, compadre!\nYo te asisto en el intento,\nPorqué te tengo guardado,\nDentro de mi pensamiento.",3,1,0,49,"",0,4,"eo",94,0,-1,0,534,534,"2383","",0,"","","",1,0,0,[],""],["carrizo_salta-n2384-01",3,"¿Quién existirá en el mundo\nQue no lo pueda saber?\nNo se me escapa una sombra,\nNi una alma que pueda haber.",3,1,0,49,"",0,4,"e",20,0,-1,0,534,534,"2384","",0,"","","",1,0,0,[],""],["carrizo_salta-n2385-01",3,"¿Quién ha perdido qui hi hallado\nUn pañuelo nuevo, nuevo?\nEn cada esquina un suspiro,\nY en el centro un ¡ay, me muero!",3,1,0,49,"",0,4,"eo",-1,0,-1,0,534,534,"2385","",0,"","","",1,0,0,[],""],["carrizo_salta-n2386-01",3,"Quien quiera cantar conmigo,\nAcompáñeme algún rato,\nYo le voa pasar las coplas,\nAtaditas en un trapo.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,534,534,"2386","",0,"","","",1,0,0,[],""],["carrizo_salta-n2387-01",3,"Quisiera moralizar,\nLa pluma con el sentido,\nCuando me falte discurso,\nQuisiera ser alvertido.",3,1,0,49,"",0,4,"io",101,0,-1,0,534,534,"2387","",0,"","","",2,0,0,[],""],["carrizo_salta-n2388-01",3,"Quisiera moralizar\nLa pluma con el sentido,\nPara cantar con mujer,\nEs bueno ser comprendido.",3,1,0,49,"",0,4,"io",101,0,-1,0,534,534,"2388","",0,"","","",2,0,0,[],""],["carrizo_salta-n2389-01",3,"Quisiera pronosticar,\nComo el pronosticador,\nTambién quisiera arriesgar,\nComo un hombre arrisgador.",3,1,0,49,"",1,4,"o",72,0,-1,0,534,534,"2389","",0,"","","",1,0,0,[],""],["carrizo_salta-n2390-01",3,"Quisiera ser cangrijeño,\nPara batir la bandera,\nEnsillaría mi caballo,\nLevantaría polvareda.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,534,534,"2390","",0,"","","",1,0,0,[],""],["carrizo_salta-n2391-01",3,"Quisiera ser capitán,\nCapitán de artillería,\nPara echar rodilla en tierra,\nY poner la puntería.",3,1,0,49,"",0,4,"ia",0,0,-1,0,535,535,"2391","",0,"","","",1,0,0,[],""],["carrizo_salta-n2392-01",3,"Quisiera ser como el árbol,\nCada año reverdeciera,\nBotaría el pelo viejo,\nY otro nuevo me saliera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,535,535,"2392","",0,"","","",1,0,0,[],""],["carrizo_salta-n2393-01",3,"Quisiera ser como el chancho,\nPara no saber rezar,\nEl chancho no se persina,\nTodo se le va en hozar.",3,1,0,49,"",0,4,"a",21,0,-1,0,535,535,"2393","",0,"","","",1,0,0,[],""],["carrizo_salta-n2394-01",3,"Quisiera ser como el zorro,\nPara pasarla cantando,\n¡Cómo cantaría de lindo,\nCuando el chañar 'sté pintando!",3,1,0,49,"",0,4,"ao",33,0,-1,0,535,535,"2394","",0,"","","",3,0,0,[],""],["carrizo_salta-n2394-a-01",3,"Quisiera ser como el zorro,\nPara pasarme gritando.\n¡Cómo habría de cantar fuerte,\nCuando el chañar 'sté pintando!",3,1,0,49,"",0,4,"ao",33,0,-1,0,535,535,"2394-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n2395-01",3,"Quisiera ser de resorte,\nPara armarme y desarmarme,\nEntre medio las doncellas,\nAchicarme y agrandarme.",3,1,0,49,"",0,4,"ae",35,0,-1,0,535,535,"2395","",0,"","","",1,0,0,[],""],["carrizo_salta-n2396-01",3,"Quisiera ser ingeniero,\nPara ver de qué manera,\nPodría entrar en tu cuarto,\nSentarme a tu cabecera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,535,535,"2396","",0,"","","",3,0,0,[],""],["carrizo_salta-n2397-01",3,"Quisiera un caballo bayo,\nUn caballo bayo tunte,\nPara pegar un galope,\nA mi paguito de Túite.",3,1,0,49,"",0,4,"ue",-1,0,-1,0,535,535,"2397","",0,"","","",1,0,0,[],""],["carrizo_salta-n2398-01",3,"Reciba don Caracciolo,\nVd. es un hombre decente,\nPuede subir al Cabildo,\nY hablar con el Presidente.",3,1,0,49,"",0,4,"ee",15,0,-1,0,535,535,"2398","",0,"","","",1,0,0,[],""],["carrizo_salta-n2399-01",3,"Reciencito mos llegado,\nA saludar este barrio,\nJunto con mi cuadrillita,\nCon el sombrero en la mano.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,535,535,"2399","",0,"","","",1,0,0,[],""],["carrizo_salta-n2400-01",3,"¡Recuerda, si estás dormida!\nDe ese sueño delicado,\nPara ver si amor le tienes,\nA este pobre desgraciado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,535,535,"2400","",0,"","","",1,0,0,[],""],["carrizo_salta-n2401-01",3,"Rematemos, rematemos,\nAl Carnaval lo matemos,\nEl Miércoles de Ceniza,\nTambién lo cacharpayemos.",3,1,0,49,"",0,4,"eo",127,0,-1,0,535,535,"2401","",0,"","","",1,0,0,[],""],["carrizo_salta-n2402-01",3,"¡Rematito humahuaqueño!\nColor de cinta rosada,\nVolviendo t'hi de llevar,\nVolviendo de \"La Quebrada\".",3,1,0,49,"",0,4,"aa",49,0,-1,0,535,535,"2402","",0,"","","",1,0,0,[],""],["carrizo_salta-n2403-01",3,"Rematito no t' hi tráido,\nPorque no quiere venir,\nEn estas tierras extrañas,\nTiene miedo de morir.",3,1,0,49,"",0,4,"i",157,0,-1,0,535,535,"2403","",0,"","","",1,0,0,[],""],["carrizo_salta-n2404-01",3,"¡Rematito, rematito!\n¡Rematito tilcareño!\nPa qué has andao preguntando\nSi soy libre o tengo dueño?",3,1,0,49,"",0,4,"eo",138,0,-1,0,536,536,"2404","",0,"","","",1,0,0,[],""],["carrizo_salta-n2405-01",3,"Reniego todos los días,\nDel maldito matrimonio,\nQue sólo por el demonio,\nInventado pudo ser.",3,1,0,49,"",5,4,"e",-1,0,-1,0,536,536,"2405","",0,"","","",1,0,0,[],""],["carrizo_salta-n2406-01",3,"¡Río caudaloso!\nDejame pasar,\nUn beso a mi negra,\nLe quisiera dar.",3,1,0,49,"",0,4,"a",21,0,-1,0,536,536,"2406","",0,"","","",3,0,0,[],""],["carrizo_salta-n2407-01",3,"¡Río del Oriente!\nDejame pasar,\nA mi palomita,\nLa voy a buscar.",3,1,0,49,"",0,4,"a",21,0,-1,0,536,536,"2407","",0,"","","",1,0,0,[],""],["carrizo_salta-n2408-01",3,"Ronco me siento del pecho,\nY la voz muy diferente,\nPor eso voy a cantar,\nEn esta casa sin gente.",3,1,0,49,"",0,4,"ee",15,0,-1,0,536,536,"2408","",0,"","","",2,0,0,[],""],["carrizo_salta-n2409-01",3,"Ronco vengo de los piés,\nDespiado de la garganta,\nPor eso digo cantando;\nQue mi pecho ya no aguanta.",3,1,0,49,"",0,4,"aa",148,0,-1,0,536,536,"2409","",0,"","","",1,0,0,[],""],["carrizo_salta-n2410-01",3,"Saladino soy, señores,\nPor mi modo de cantar,\nAunque no dentre a la escuela,\nYo les puedo contestar.",3,1,0,49,"",0,4,"a",21,0,-1,0,536,536,"2410","",0,"","","",1,0,0,[],""],["carrizo_salta-n2411-01",3,"Salga mozo, molinisto,\nSalga niña tomuqueña,\nEl mozo que a mí me gusta,\nSabe tonadas pomeñas.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,536,536,"2411","",0,"","","",1,0,0,[],""],["carrizo_salta-n2412-01",3,"Salí al campo y pregunté,\nA la humilde violeta,\nSi para curar mi amor,\nConoce alguna receta.",3,1,0,49,"",0,4,"ea",200,0,-1,0,536,536,"2412","",0,"","","",1,0,0,[],""],["carrizo_salta-n2413-01",3,"¡Salí burro de mi puerta!\nNo me comás la cebada,\nNo sea que tal vez dentrando,\nSe te rompa la quijada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,536,536,"2413","",0,"","","",1,0,0,[],""],["carrizo_salta-n2414-01",3,"¡Salí mi Juanita!\nBatí tu bandera,\nEnsillá tu macho blanco,\nVamonós pa Guacalera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,536,536,"2414","",0,"","","",1,0,0,[],""],["carrizo_salta-n2415-01",3,"Salta la perdiz, madre,\nLa superior,\nQue se la caza el gato,\nGato traidor.",3,1,0,49,"",6,4,"o",72,0,-1,0,536,536,"2415","",0,"","","",2,0,0,[],""],["carrizo_salta-n2416-01",3,"Salta la perdiz, madre,\nParió la cabra\nTres chivitos bonitos,\nY un malacara.",3,1,0,49,"",6,4,"aa",-1,0,-1,0,536,536,"2416","",0,"","","",2,0,0,[],""],["carrizo_salta-n2417-01",3,"Salteñito me dicen,\nLas santiagueñas,\nOtra vez que me digan,\nMe iré con ellas.",3,1,0,49,"",6,4,"ea",-1,0,-1,0,536,536,"2417","",0,"","","",1,0,0,[],""],["carrizo_salta-n2418-01",3,"Salteñito soy, señores,\nPero de lao de Bolivia,\nCuando canto mi tonada,\nCualquier enfermo se alivia.",3,1,0,49,"",0,4,"ia",339,0,-1,0,536,536,"2418","",0,"","","",1,0,0,[],""],["carrizo_salta-n2419-01",3,"Saludo al chico y al grande,\nY a toditos en común,\nY pregunto al dueño i casa,\n¿Cómo le va de salud?",3,1,0,49,"",0,4,"u",-1,0,-1,0,536,536,"2419","",0,"","","",1,0,0,[],""],["carrizo_salta-n2420-01",3,"¡Santa Rosa de Lima!\n¿Por qué consientes,\nQue dos enamorados\nVivan ausentes?",3,1,0,49,"",6,4,"ee",252,0,-1,0,537,537,"2420","",0,"","","",5,0,0,[],""],["carrizo_salta-n2420-02",3,"Vivan ausentes, sí,\nPreciosa perla,\nAunque no sea mi dueña,\nMe gusta verla.",3,1,0,49,"",6,4,"ea",-1,0,-1,0,537,537,"2420","",0,"","","",1,0,0,[],""],["carrizo_salta-n2421-01",3,"¡Santa Rosa de Lima!\nTres cosas pido,\nSalvación para mi alma,\nPlata y marido.",3,1,0,49,"",6,4,"io",101,0,-1,0,537,537,"2421","",0,"","","",5,0,0,[],""],["carrizo_salta-n2421-02",3,"Plata y marido sí,\nChicha en botella,\nA la mujer infiel,\nGuasca con ella.",3,1,0,49,"",6,4,"ea",6,0,-1,0,537,537,"2421","",0,"","","",1,0,0,[],""],["carrizo_salta-n2422-01",3,"Santiagueña soy, señores,\nYo no niego mi nación,\nPor la patria doy la vida,\nPor Santiago el corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,537,537,"2422","",0,"","","",1,0,0,[],""],["carrizo_salta-n2422-01-e2",3,"Santiagueño soy, señores,\nPor el modo de cantar,\nY si en algo me equivoco,\nVd. sabrá disculpar.",3,1,0,49,"",0,4,"a",21,0,-1,0,537,537,"2422","",0,"","","",3,0,0,[],""],["carrizo_salta-n2423-01",3,"Santiagueño soy, señores,\nPor mi modo de cantar,\nY si en algo me equivoco,\nNo tengo por novedad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,537,537,"2423","",0,"","","",3,0,0,[],""],["carrizo_salta-n2424-01",3,"Santiagueño soy, señores,\nYo no niego mi nación,\nSantiagueño, lengua dura,\nHabla cuando hay ocasión.",3,1,0,49,"",0,4,"o",31,0,-1,0,537,537,"2424","",0,"","","",3,0,0,[],""],["carrizo_salta-n2425-01",3,"Saqueseló a su sombrero,\nY vuelvaseló a poner,\nPa que no diga la gente,\nQue lo hi echado a perder.",3,1,0,49,"",0,4,"e",20,0,-1,0,537,537,"2425","",0,"","","",1,0,0,[],""],["carrizo_salta-n2426-01",3,"Se acabaron mis consejos,\nEn pro de su dicha ansiada,\nPero, amigo, usted está lejos,\nPara hacerme caso en nada.",3,1,0,49,"",1,4,"aa",49,0,-1,0,537,537,"2426","",0,"","","",1,0,0,[],""],["carrizo_salta-n2427-01",3,"Se dentró el sol y la luna,\nYa se perdió tata Dios,\nQuedamos con las estrellas,\nEs muy tarde, vamonós.",3,1,0,49,"",0,4,"o",87,0,-1,0,537,537,"2427","",0,"","","",1,0,0,[],""],["carrizo_salta-n2428-01",3,"¡Señora doña fulana!\nCantemeló una tonada,\nPorque si no me da el gusto,\nDiré que no valgo nada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,537,537,"2428","",0,"","","",22,0,0,[],""],["carrizo_salta-n2429-01",3,"¡Señora doña fulana!\nPonga un jarrito de vino,\nY no se le haga, señora,\nQue yo no estoy en mi tino.",3,1,0,49,"",0,4,"io",199,0,-1,0,537,537,"2429","",0,"","","",22,0,0,[],""],["carrizo_salta-n2430-01",3,"¡Señora doña fulana!\nSirvamé una vasirusca,\nSi me fuera y no pagara,\n¡Cómo habría i quedar de chusca!",3,1,0,49,"",0,4,"ua",416,0,-1,0,537,537,"2430","",0,"","","",22,0,0,[],""],["carrizo_salta-n2431-01",3,"¡Señora doña fulana!\nYo soy como mariposa,\nSi no me quema las alas,\nL'hi de servir pa una cosa.",3,1,0,49,"",0,4,"oa",63,0,-1,0,537,537,"2431","",0,"","","",22,0,0,[],""],["carrizo_salta-n2432-01",3,"¡Señora, dueña de casa!\nPrestemé su casa pido;\nPara cantar cuatro coplas,\nA sus puertas hi venido.",3,1,0,49,"",0,4,"io",101,0,-1,0,538,538,"2432","",0,"","","",7,0,0,[],""],["carrizo_salta-n2433-01",3,"¡Señora la dueña i casa!\nY el dueño i casa también,\nLa dueña i casa una rosa,\nY el dueño i casa un clavel.",3,1,0,49,"",0,4,"e",-1,0,-1,0,538,538,"2433","",0,"","","",1,0,0,[],""],["carrizo_salta-n2434-01",3,"¡Señora, no la conozco!\nPero sus noticias tengo,\nDicen que Vd. es suplifalta,\nA que la supla me vengo.",3,1,0,49,"",0,4,"eo",124,0,-1,0,538,538,"2434","",0,"","","",2,0,0,[],""],["carrizo_salta-n2435-01",3,"¡Señora, yo soy un pobre!\nY, de cantar tengo ganas,\nDe mi pecho hago una torre,\nDe mi voz una campana.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,538,538,"2435","",0,"","","",5,0,0,[],""],["carrizo_salta-n2436-01",3,"¡Señores animanistos!\nTengan fuerte su bandera,\nYa vienen los de San Carlos,\nLevantando polvareda.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,538,538,"2436","",0,"","","",1,0,0,[],""],["carrizo_salta-n2437-01",3,"¡Señores, con todos hablo!\nDe toditos soy amigo,\nSi no dicen como digo,\nMe pagan con un obligo,",3,1,0,49,"",0,4,"io",106,0,-1,0,538,538,"2437","",0,"","","",1,0,0,[],""],["carrizo_salta-n2438-01",3,"¡Señores, no hay que dudar!\nEn este mundo embustero,\nLo mejor para gozar,\nEs permanecer soltero.",3,1,0,49,"",1,4,"eo",38,0,-1,0,538,538,"2438","",0,"","","",1,0,0,[],""],["carrizo_salta-n2439-01",3,"¡Señores, no sé cantar!\nComo cantan los porteños,\nLes cantaré mis coplitas,\nComo gaucho santiagueño.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,538,538,"2439","",0,"","","",1,0,0,[],""],["carrizo_salta-n2440-01",3,"¡Señores, por la vergüenza!\nSe callan las buenasmozas,\nYo las quiero conquistar,\nCon palabras amorosas.",3,1,0,49,"",0,4,"oa",61,0,-1,0,538,538,"2440","",0,"","","",1,0,0,[],""],["carrizo_salta-n2441-01",3,"¡Señores, tomen un trago!\nQue no es cosa de upilarse,\nHay que coliar un poquito,\nY lueguito retirarse.",3,1,0,49,"",0,4,"ae",250,0,-1,0,538,538,"2441","",0,"","","",1,0,0,[],""],["carrizo_salta-n2442-01",3,"¡Señores y caballeros!\nTodos habrán comprendido,\nQue a esta mujer la traigo,\nDe la simba y del vestido.",3,1,0,49,"",0,4,"io",101,0,-1,0,539,539,"2442","",0,"","","",1,0,0,[],""],["carrizo_salta-n2443-01",3,"¡Señores, yo soy un pobre\nOficial de carpintero!\nCuando no tengo qué dar,\nDoy astillas para el fuego.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,539,539,"2443","",0,"","","",3,0,0,[],""],["carrizo_salta-n2444-01",3,"¡Señores, yo soy un pobre!\nSoy humilde y caballero,\nNo soy como son los ricos,\nOrgullosos y altaneros.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,539,539,"2444","",0,"","","",3,0,0,[],""],["carrizo_salta-n2445-01",3,"¡Señor fulano de tal!\nEl nombrarlo se me antoja,\n¿Por qué se deja decir,\nQue de bueno se deshoja?",3,1,0,49,"",0,4,"oa",146,0,-1,0,539,539,"2445","",0,"","","",3,0,0,[],""],["carrizo_salta-n2446-01",3,"¡Señor fulano de tal!\nVd. que todo merece,\nHa gozao lo que ha querido,\nAhora de nada carece.",3,1,0,49,"",0,4,"ee",64,0,-1,0,539,539,"2446","",0,"","","",3,0,0,[],""],["carrizo_salta-n2447-01",3,"¡Señorita de fulana!\nNo le haga caso al muchacho,\nA Vd. le dicen la cabra,\nA mí me dicen camacho.",3,1,0,49,"",0,4,"ao",310,0,-1,0,539,539,"2447","",0,"","","",16,0,0,[],""],["carrizo_salta-n2448-01",3,"¡Señorita, mal!\n¡Señorita, bien!\nA usted te quiero,\nA l' otra también.",3,1,0,49,"",6,4,"e",242,0,-1,0,539,539,"2448","",0,"","","",1,0,0,[],""],["carrizo_salta-n2449-01",3,"Si alguien pregunta por mí\nPor una casualidad,\nDigalén que estoy aquí,\nPor una necesidad.",3,1,0,49,"",1,4,"a",16,0,-1,0,539,539,"2449","",0,"","","",1,0,0,[],""],["carrizo_salta-n2450-01",3,"Si algún fino caballero,\nAndando me solicita,\nHe de averiguar primero,\nSi me quiere a mí solita.",3,1,0,49,"",1,4,"ia",50,0,-1,0,539,539,"2450","",0,"","","",1,0,0,[],""],["carrizo_salta-n2451-01",3,"Si algún maestro de amores,\nA mí me enseñara a leer,\nEcharía mi libro al suelo,\nY me pusiera a querer.",3,1,0,49,"",0,4,"e",20,0,-1,0,539,539,"2451","",0,"","","",1,0,0,[],""],["carrizo_salta-n2452-01",3,"Si coplas faltan, señores,\nPor coplas no estén llorando,\nEn mi casa tengo un árbol,\nCon coplas se está ladiando.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,539,539,"2452","",0,"","","",1,0,0,[],""],["carrizo_salta-n2453-01",3,"Si cuando su amor se empaca,\nA su tirador da un giro,\nDebe andar el tirador,\nComo piedra de molino.",3,1,0,49,"",0,4,"io",-1,0,-1,0,539,539,"2453","",0,"","","",1,0,0,[],""],["carrizo_salta-n2454-01",3,"Si dijera la verdad,\nSería como pa matarse,\nPero como no ha i ser cierto,\nSería en vano sepultarse.",3,1,0,49,"",0,4,"ae",250,0,-1,0,539,539,"2454","",0,"","","",1,0,0,[],""],["carrizo_salta-n2455-01",3,"Siempre de negro visten,\nLos alcahuetes,\nY los enamorados,\nDe azul celeste.",3,1,0,49,"",6,4,"ee",-1,0,-1,0,539,539,"2455","",0,"","","",1,0,0,[],""],["carrizo_salta-n2456-01",3,"Si eres soltera,\nMarcha conmigo,\nSi eres casada,\nCon tu marido.",3,1,0,49,"",6,4,"io",-1,0,-1,0,540,540,"2456","",0,"","","",1,0,0,[],""],["carrizo_salta-n2457-01",3,"Si es que quieres chupar caña,\nVamos al cañaveral,\nAllá hay cortas, allá hay largas,\nComo fija pa pescar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,540,540,"2457","",0,"","","",1,0,0,[],""],["carrizo_salta-n2458-01",3,"Si es que te querís casar,\nBuscá una mujer morena\nPorque de blancas y rubias\nDe ciento sale una buena",3,1,0,49,"",0,4,"ea",59,0,-1,0,540,540,"2458","",0,"","","",1,0,0,[],""],["carrizo_salta-n2459-01",3,"Si esta casa fuera alta,\nTuviera siete estaciones,\nDivisaría Buenos Aires,\nY toditas las naciones.",3,1,0,49,"",0,4,"oe",34,0,-1,0,540,540,"2459","",0,"","","",1,0,0,[],""],["carrizo_salta-n2460-01",3,"Si estoy triste, estoy contento,\nSi lloro, siempre sonrío,\nSi désio lo que no tengo,\nMe gusta lo que no es mío.",3,1,0,49,"",0,4,"io",3,0,-1,0,540,540,"2460","",0,"","","",1,0,0,[],""],["carrizo_salta-n2461-01",3,"Si estoy en mi casa,\nMe dicen casero,\nSi salgo a la calle,\nYa soy bandolero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,540,540,"2461","",0,"","","",1,0,0,[],""],["carrizo_salta-n2462-01",3,"Si fuera dable creer,\nEn palabras lisonjeras,\nSolamente de quimeras,\nViviría una mujer.",3,1,0,49,"",11,4,"e",20,0,-1,0,540,540,"2462","",0,"","","",1,0,0,[],""],["carrizo_salta-n2463-01",3,"Sigan para adelante,\nPor ver si algo se compriende,\nEl carbón que ha sido brasa,\nCon facilidad se enciende.",3,1,0,49,"",0,4,"ee",233,0,-1,0,540,540,"2463","",0,"","","",1,0,0,[],""],["carrizo_salta-n2464-01",3,"¡Sí gozará mi hermosura,\nCon mucha facilidad!\nCon el conqué que me jure,\nQue no me ha de pagar mal.",3,1,0,49,"",0,4,"a",-1,0,-1,0,540,540,"2464","",0,"","","",1,0,0,[],""],["carrizo_salta-n2465-01",3,"¿Si habrá permiso, señores,\nPara dentrar y salir?\nVoy a cantar esta copla,\nPor lo que pueda morir.",3,1,0,49,"",0,4,"i",157,0,-1,0,540,540,"2465","",0,"","","",1,0,0,[],""],["carrizo_salta-n2466-01",3,"Si hasta mi cajita llora,\nCon ser de cuero i capón,\n¿Cómo no hi de llorar yo,\nPor los gauchos del Cajón?",3,1,0,49,"",0,4,"o",-1,0,-1,0,540,540,"2466","",0,"","","",2,0,0,[],""],["carrizo_salta-n2467-01",3,"Si hasta mi cajita llora,\nCon ser de cuero i langosta,\n¿Cómo no hi de llorar yo,\nPor los gauchitos \"La Costa\"?",3,1,0,49,"",0,4,"oa",434,0,-1,0,540,540,"2467","",0,"","","",2,0,0,[],""],["carrizo_salta-n2468-01",3,"Si la \"Chacarera\" muere,\nYo también había hi morir,\nPorque sin la \"Chacarera\",\nNo me es posible vivir.",3,1,0,49,"",0,4,"i",157,0,-1,0,541,541,"2468","",0,"","","",1,0,0,[],""],["carrizo_salta-n2469-01",3,"Si la gracia me ayudara,\nComo me ayuda el deseo,\nA toditos agradara,\nPero sin gracia, no puedo.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,541,541,"2469","",0,"","","",3,0,0,[],""],["carrizo_salta-n2470-01",3,"Si la moza es ajena,\nPuja la daga,\nQue con las cartas bravas,\nTriunfo es espada.",3,1,0,49,"",6,4,"aa",-1,0,-1,0,541,541,"2470","",0,"","","",1,0,0,[],""],["carrizo_salta-n2471-01",3,"Si las mujeres tuvieran\nLa libertad de los hombres,\nA los caminos salieran,\nA robar los corazones.",3,1,0,49,"",0,4,"oe",-1,0,-1,0,541,541,"2471","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["carrizo_salta-n2472-01",3,"Si libre me considero,\nLa libertad me entristece,\nMi corazón apetece,\nVolver a ser prisionero.",3,1,0,49,"",11,4,"eo",38,0,-1,0,541,541,"2472","",0,"","","",1,0,0,[],""],["carrizo_salta-n2473-01",3,"Si los besitos nacieran,\nComo nace el perejil,\nA más de cuatro yo viera,\nLa cara como un jardín.",3,1,0,49,"",0,4,"i",-1,0,-1,0,541,541,"2473","",0,"","","",2,0,0,[],""],["carrizo_salta-n2474-01",3,"Si los besos que me das,\nFueran sellos que sellaran,\nMás de cuatro solteritas,\nDe la cara los robaran.",3,1,0,49,"",0,4,"aa",435,0,-1,0,541,541,"2474","",0,"","","",1,0,0,[],""],["carrizo_salta-n2475-01",3,"Si me muero hago falta,\nSi vivo estorbo,\nYo me h' i pasar la vida,\nDe cualquier modo.",3,1,0,49,"",6,4,"oo",-1,0,-1,0,541,541,"2475","",0,"","","",2,0,0,[],""],["carrizo_salta-n2476-01",3,"Si me querís, vida mía,\nSilbame como perdiz,\nSi no me silbas así,\nSeña es que no me querís.",3,1,0,49,"",0,4,"i",-1,0,-1,0,541,541,"2476","",0,"","","",1,0,0,[],""],["carrizo_salta-n2477-01",3,"Si me quieren convidar,\nVino con canela, ha i ser,\nY si me piden que cante,\nCantando hi de amanecer.",3,1,0,49,"",0,4,"e",-1,0,-1,0,541,541,"2477","",0,"","","",1,0,0,[],""],["carrizo_salta-n2478-01",3,"Si me quiere, señorita,\nFormaremos relación,\nPara decir con franqueza:\n¡Viva la nueva elección!",3,1,0,49,"",0,4,"o",31,0,-1,0,541,541,"2478","",0,"","","",1,0,0,[],""],["carrizo_salta-n2479-01",3,"Si mis brazos fueran largos,\nComo timón de navio,\nCafayete sería nada,\nTodo Lima sería mío.",3,1,0,49,"",0,4,"io",3,0,-1,0,541,541,"2479","",0,"","","",2,0,0,[],""],["carrizo_salta-n2480-01",3,"Si mi madre me dijera:\n—Dejá de querer, me muero.\n—Muerasé, mi madrecita,\nDejar de querer, no puedo.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,541,541,"2480","",0,"","","",1,0,0,[],""],["carrizo_salta-n2481-01",3,"Si querís que yo te quiera,\nPrimero te has de varear,\nDe la Tala al Quebrachito,\nLa cola se te ha i pelar.",3,1,0,49,"",0,4,"a",21,0,-1,0,541,541,"2481","",0,"","","",3,0,0,[],""],["carrizo_salta-n2482-01",3,"Si querís saber mi nombre,\nYo me llamo flor rosada,\nAcordate de otros tiempos,\nDe la cosecha pasada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,542,542,"2482","",0,"","","",1,0,0,[],""],["carrizo_salta-n2483-01",3,"Si quieren saber, señores,\nCómo cantan en mi tierra,\nConcertando bien las coplas,\nLa tonada como quiera.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,542,542,"2483","",0,"","","",11,0,0,[],""],["carrizo_salta-n2484-01",3,"Si quieren saber, señores,\nLo que hi tráido pa vender,\nHi tráido una flor marchita,\nComprarla no han de querer.",3,1,0,49,"",0,4,"e",20,0,-1,0,542,542,"2484","",0,"","","",11,0,0,[],""],["carrizo_salta-n2485-01",3,"Si quieren saber, señores,\nLo que hi tráido pa vender,\nTraigo flores, traigo amores,\nSólo busco a quién querer.",3,1,0,49,"",1,4,"e",20,0,-1,0,542,542,"2485","",0,"","","",11,0,0,[],""],["carrizo_salta-n2486-01",3,"Si quieren saber, señores,\nQue hi tráido para vender,\nNo hi tráido más que mi poncho,\nPara poderlo tender.",3,1,0,49,"",0,4,"e",20,0,-1,0,542,542,"2486","",0,"","","",11,0,0,[],""],["carrizo_salta-n2487-01",3,"Si quieres que yo te quiera,\nHas de embaldosar la mar,\nY después de embaldosado,\nSeré tuyo sin faltar.",3,1,0,49,"",0,4,"a",21,0,-1,0,542,542,"2487","",0,"","","",23,0,0,[],""],["carrizo_salta-n2488-01",3,"Si quieres saber mi nombre,\nDiré nombre y apellido,\nYo soy hijo de una estrella,\nDel cielo favorecido.",3,1,0,49,"",0,4,"io",101,0,-1,0,542,542,"2488","",0,"","","",2,0,0,[],""],["carrizo_salta-n2489-01",3,"Si quieres saber mi nombre,\nPasa por aquel jardín,\nY hallarás mi nombre escrito,\nEn una flor de jazmín.",3,1,0,49,"",0,4,"i",211,0,-1,0,542,542,"2489","",0,"","","",2,0,0,[],""],["carrizo_salta-n2490-01",3,"Si quieres ser ruiseñor,\nYo quisiera ser halcón,\nPara sacarte los ojos,\nAlma, vida y corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,542,542,"2490","",0,"","","",1,0,0,[],""],["carrizo_salta-n2491-01",3,"Si soy trigo, trillemén,\nY después avientemén,\nLlevemén para el molino,\nHagan pan y vendamén.",3,1,0,49,"",0,4,"e",242,0,-1,0,542,542,"2491","",0,"","","",1,0,0,[],""],["carrizo_salta-n2492-01",3,"Si te duele la barriga,\nVení, yo te sanaré,\nY si te acierto la cura,\nMedica me llamaré.",3,1,0,49,"",0,4,"e",77,0,-1,0,542,542,"2492","",0,"","","",1,0,0,[],""],["carrizo_salta-n2493-01",3,"Si tu marido es celoso,\nDale chamico molido,\nPa que se muera ligero,\nY vos te quedís conmigo.",3,1,0,49,"",0,4,"io",-1,0,-1,0,542,542,"2493","",0,"","","",7,0,0,[],""],["carrizo_salta-n2494-01",3,"Si Vd., joven, se ha ofertado,\nLo voy ahora a ocupar,\nTraigamé un vasito de agua,\nDe las orillas del mar.",3,1,0,49,"",0,4,"a",21,0,-1,0,542,542,"2494","",0,"","","",1,0,0,[],""],["carrizo_salta-n2495-01",3,"Si van a cantar, cantemos,\nSi van a dejar, dejemos,\nSi hay alguno de afición,\nAquí nomás se quedemos.",3,1,0,49,"",0,4,"eo",127,0,-1,0,542,542,"2495","",0,"","","",1,0,0,[],""],["carrizo_salta-n2496-01",3,"Si ves al enemigo,\nMontado a la siniestra,\nDejalo, así te digo,\nAsegurad la diestra.",3,1,0,49,"",1,4,"ea",436,0,-1,0,543,543,"2496","",0,"","","",1,0,0,[],""],["carrizo_salta-n2497-01",3,"Si yo fuera una baldosa,\nY tu pecho fuera cal,\nY el amor fuera maestro,\nSe habría embaldosado el mar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,543,543,"2497","",0,"","","",1,0,0,[],""],["carrizo_salta-n2499-01",3,"Solita cantando,\nCon su banderita,\nYo la voy a acompañar,\nCantando con mi cajita.",3,1,0,49,"",0,4,"ia",50,0,-1,0,543,543,"2499","",0,"","","",1,0,0,[],""],["carrizo_salta-n2500-01",3,"Solita nací en el mundo,\nY todavía ando rodando,\nNadie me ha gozao toavía,\nPara usted me ando guardando.",3,1,0,49,"",3,4,"ao",33,0,-1,0,543,543,"2500","",0,"","","",1,0,0,[],""],["carrizo_salta-n2501-01",3,"Sólo a cantar hi venío,\nNo traigo más diligencia,\nSin ensuciar cara a nadie,\nNi quitarles conveniencia.",3,1,0,49,"",0,4,"ea",46,0,-1,0,543,543,"2501","",0,"","","",1,0,0,[],""],["carrizo_salta-n2502-01",3,"Sólo canto por cantar,\nNo canto por interés,\nY si me dan un cigarro,\nNo está el tiempo pa perder.",3,1,0,49,"",0,4,"e",-1,0,-1,0,543,543,"2502","",0,"","","",1,0,0,[],""],["carrizo_salta-n2503-01",3,"Sólo tengo, vidita,\nPoncho i frazada,\nSi le pusiera fleco,\n¡Cómo quedara!",3,1,0,49,"",6,4,"aa",-1,0,-1,0,543,543,"2503","",0,"","","",1,0,0,[],""],["carrizo_salta-n2504-01",3,"Soná, cajita por Dios,\nSoltá toda tu carrera,\nQue se quiere divertir,\nUn gusano de la tierra.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,543,543,"2504","",0,"","","",1,0,0,[],""],["carrizo_salta-n2505-01",3,"Son tus ojos las estrellas,\nQue alumbran mi corazón,\nCuando llevo mis ovejas,\nNo temo la cerrazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,543,543,"2505","",0,"","","",2,0,0,[],""],["carrizo_salta-n2506-01",3,"Sortija de plata blanca,\nEs seña de amor constante,\nPara un joven entendido,\nMedia razón es bastante.",3,1,0,49,"",0,4,"ae",47,0,-1,0,543,543,"2506","",0,"","","",1,0,0,[],""],["carrizo_salta-n2507-01",3,"Soy cantor de \"La Frontera\".\nCantor soy de las estancias,\nLes puedo cantar aquí,\nPara acortar la distancia.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,543,543,"2507","",0,"","","",1,0,0,[],""],["carrizo_salta-n2508-01",3,"Soy capaz de hacer promesa,\nPa que me dejen llegar,\nY no me tengan envidia,\nLos que me quieren celar.",3,1,0,49,"",0,4,"a",21,0,-1,0,544,544,"2508","",0,"","","",1,0,0,[],""],["carrizo_salta-n2509-01",3,"Soy como el pichón de águila,\nCuando baja del peñón,\nCuando hice el primer volido,\nCayó la pluma mayor.",3,1,0,49,"",0,4,"o",-1,0,-1,0,544,544,"2509","",0,"","","",1,0,0,[],""],["carrizo_salta-n2510-01",3,"Soy como l' hormiguita,\nSalgo a buscar,\nMuchachitas bonitas,\nNo puedo hallar.",3,1,0,49,"",6,4,"a",21,0,-1,0,544,544,"2510","",0,"","","",1,0,0,[],""],["carrizo_salta-n2511-01",3,"Soy halconcito pichón,\nQue recién salgo a volar,\nTanto que me la mezquinan,\nAl fin me la hi de llevar.",3,1,0,49,"",0,4,"a",21,0,-1,0,544,544,"2511","",0,"","","",1,0,0,[],""],["carrizo_salta-n2512-01",3,"Soy hijo de las estrellas,\nPrimo hermano del lucero,\nPa divertirme cantando,\nAquí estoy de cuerpo entero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,544,544,"2512","",0,"","","",1,0,0,[],""],["carrizo_salta-n2513-01",3,"Soy joven de una palabra,\nLlevado de mis ideas,\nCuando comienzo a querer,\n¿Cuándo será que eso sea?",3,1,0,49,"",0,4,"ea",-1,0,-1,0,544,544,"2513","",0,"","","",1,0,0,[],""],["carrizo_salta-n2514-01",3,"Soy lo mismo que el alcanto,\nA las nubes me levanto,\nDe las mocitas me encanto,\nY de las viejas me espanto.",3,1,0,49,"",0,4,"ao",30,0,-1,0,544,544,"2514","",0,"","","",1,0,0,[],""],["carrizo_salta-n2515-01",3,"Soy lo mismo que el lanar,\nQue vuelta a vuelta lo esquilan,\nCon los desprecios engordo,\nLos cariños me aniquilan.",3,1,0,49,"",0,4,"ia",437,0,-1,0,544,544,"2515","",0,"","","",1,0,0,[],""],["carrizo_salta-n2516-01",3,"Supuesto que sois tan sabio,\nUna pregunta te haré,\nDesde la tierra hasta el cielo,\n¿Cuántas leguas puede haber?",3,1,0,49,"",0,4,"e",-1,0,-1,0,544,544,"2516","",0,"","","",1,0,0,[],""],["carrizo_salta-n2517-01",3,"¡Tanta naranja en el suelo!\n¡Tanto limón en el techo!\nTanta niña buenamoza!\n¡Tanto mozo sin provecho!",3,1,0,49,"",0,4,"eo",60,0,-1,0,544,544,"2517","",0,"","","",1,0,0,[],""],["carrizo_salta-n2517-a-01",3,"¡Tantas naranjas maduras!\n¡Tanto limón por el techo!\n¡Tantas gauchas divertidas!\nMe hacen llorar sin provecho.",3,1,0,49,"",0,4,"eo",60,0,-1,0,544,544,"2517-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2518-01",3,"Tanto dormir al sereno,\nMe ha dado la pechugera,\nYa no me ayuda la voz,\nMucho menos la ronquera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,544,544,"2518","",0,"","","",1,0,0,[],""],["carrizo_salta-n2519-01",3,"Tarde la noche hi salido,\nPero hi llegado muy tarde,\nCon el sombrero en la mano,\nSaludo al chico y al grande.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,544,544,"2519","",0,"","","",1,0,0,[],""],["carrizo_salta-n2520-01",3,"Tengo de hacer un barquito,\nCon bala y con lachiguana,\nPara embarcar corazones,\nDesde Salta hasta Chicuana.",3,1,0,49,"",0,4,"aa",4,0,-1,0,544,544,"2520","",0,"","","",1,0,0,[],""],["carrizo_salta-n2521-01",3,"Tengo en la cara pequitas,\nComo tiene el campo flores.\nLa abeja busca su néctar,\nPero no busca colores.",3,1,0,49,"",0,4,"oe",5,0,-1,0,545,545,"2521","",0,"","","",1,0,0,[],""],["carrizo_salta-n2522-01",3,"Tengo mi pecho de coplas,\nQue aprece un avispero,\nSe empujan unas a otras,\nPor ver cuál sale primero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,545,545,"2522","",0,"","","",2,0,0,[],""],["carrizo_salta-n2523-01",3,"Tengo mi quinta frutal,\nLa fruta no la merezco,\nTodo tengo, nada gozo,\nAsí teniendo, carezco.",3,1,0,49,"",0,4,"eo",355,0,-1,0,545,545,"2523","",0,"","","",1,0,0,[],""],["carrizo_salta-n2524-01",3,"Tengo pleito con mi madre,\nSi no lo gano me muero,\nPorque quiere que me case,\nCon uno que yo no quiero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,545,545,"2524","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["carrizo_salta-n2525-01",3,"Tengo que hacer un barquito,\nDe cáscara de jarilla,\nPara embarcar corazones,\nDe Pucará a Pucarilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,545,545,"2525","",0,"","","",3,0,0,[],""],["carrizo_salta-n2525-a-01",3,"Tengo que hacer un barquito,\nDe cascaras de jarilla,\nPara embarcar corazones,\nSan José y Santa María.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,545,545,"2525-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n2526-01",3,"Tengo que hacer un barquito,\nDe güesitos de mayuato,\nPara embarcar corazones,\nGuasamayo y Utuyaco.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,545,545,"2526","",0,"","","",3,0,0,[],""],["carrizo_salta-n2527-01",3,"Tengo que hacer un molino,\nDe pura piedra y arena,\nPara moler esas lenguas,\nQue hablan de la Martiarena.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,545,545,"2527","",0,"","","",1,0,0,[],""],["carrizo_salta-n2528-01",3,"Tengo una copla guardada,\nPa cantar pa carnaval,\nCuando yo cante esa copla,\nLas mozas han de llorar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,545,545,"2528","",0,"","","",1,0,0,[],""],["carrizo_salta-n2529-01",3,"Teófila me llamo yo,\nNombre que el cura me puso,\nAhora me quieren tener,\nComo tortero en el huso.",3,1,0,49,"",0,4,"uo",438,0,-1,0,545,545,"2529","",0,"","","",1,0,0,[],""],["carrizo_salta-n2530-01",3,"Tienen las niñas pomeñas,\nLa sal de Dios en los labios,\nY en la punta de la lengua,\nAzúcar, canela y clavo.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,545,545,"2530","",0,"","","",1,0,0,[],""],["carrizo_salta-n2538-01",3,"Todos dicen que son pascuas,\nYo no sé cómo sería,\nYo la quisiera encontrar,\nTres horas antes del día.",3,1,0,49,"",0,4,"ia",0,0,-1,0,546,546,"2538","",0,"","","",1,0,0,[],""],["carrizo_salta-n2539-01",3,"Todos los guitarreros\nCargan la tipa,\nPero los bailarines,\nSiempre pellizcan.",3,1,0,49,"",6,4,"ia",-1,0,-1,0,546,546,"2539","",0,"","","",1,0,0,[],""],["carrizo_salta-n2540-01",3,"Todos los que cantan bien,\nCantan de puertas adentro,\nY yo como canto mal,\nCanto al sereno y al viento.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,546,546,"2540","",0,"","","",5,0,0,[],""],["carrizo_salta-n2541-01",3,"Todos los que me están viendo,\n¿Qué me estarán murmurando?\nYo aquí sin poder cantar,\nDe vergüenza estoy sudando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,546,546,"2541","",0,"","","",1,0,0,[],""],["carrizo_salta-n2542-01",3,"Todos lloraron,\nTristes mi muerte,\nY no han sabido,\nQue estuve ausente.",3,1,0,49,"",6,4,"ee",-1,0,-1,0,546,546,"2542","",0,"","","",1,0,0,[],""],["carrizo_salta-n2543-01",3,"Todos me dicen que tengo,\nOjitos de religiosa;\nY yo digo que los tengo,\nDe casada buenamoza.",3,1,0,49,"",1,4,"oa",195,0,-1,0,546,546,"2543","",0,"","","",5,0,0,[],""],["carrizo_salta-n2544-01",3,"Todos mis amigos dicen,\nQue yo digo la verdad,\nCuando el hombre no está en casa,\nOtro ocupa su lugar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,546,546,"2544","",0,"","","",2,0,0,[],""],["carrizo_salta-n2545-01",3,"Todos quieren, todos aman,\nSólo yo no puedo amar,\nLas amigas no me duran,\nPorque yo no sé rogar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,547,547,"2545","",0,"","","",1,0,0,[],""],["carrizo_salta-n2546-01",3,"Tomá este cuartillo,\nComprate un zorzal,\nSi te sale malo,\nLo echás a volar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,547,547,"2546","",0,"","","",1,0,0,[],""],["carrizo_salta-n2547-01",3,"Tonadas viejas, diciendo,\nYa no las quieren cantar,\nSolamente yo las canto;\nCon viejas me sé amañar.",3,1,0,49,"",0,4,"a",21,0,-1,0,547,547,"2547","",0,"","","",1,0,0,[],""],["carrizo_salta-n2548-01",3,"Toquen y cantemos juntos,\nQue las coplitas aguardan,\nHaremos sonar la caja,\nHasta que las velas no ardan.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,547,547,"2548","",0,"","","",1,0,0,[],""],["carrizo_salta-n2549-01",3,"¡Tortolita de otro nido,\nQue querís avecinar!\nSin duda habrás aprendido,\nA olvidar sin avisar.",3,1,0,49,"",1,4,"a",21,0,-1,0,547,547,"2549","",0,"","","",1,0,0,[],""],["carrizo_salta-n2550-01",3,"Treinta días trae el mes,\nDoce meses tiene el año,\nDemasiado tiempo has tenío\nPara ver tu desengaño.",3,1,0,49,"",0,4,"ao",40,0,-1,0,547,547,"2550","",0,"","","",1,0,0,[],""],["carrizo_salta-n2551-01",3,"Tunas, tunas con pasacana,\nTunas, tunas con pasacana,\nSi querís que yo te quiera,\nDame un besito mañana.",3,1,0,49,"",0,4,"aa",4,0,-1,0,547,547,"2551","",0,"","","",1,0,0,[],""],["carrizo_salta-n2553-01",3,"Tunas, tunas con pasacanas,\nTunas, tunas con pasacanas,\nSi quieres que yo te quiera,\nHacé lo que hace tu hermana.\nTu hermana la Juana Rosa,\nQue cuando le doy un beso,\nMe dice que es poca cosa.",3,1,0,49,"",4,7,"oa",63,0,-1,0,547,547,"2553","",0,"","","",2,0,0,[],""],["carrizo_salta-n2554-01",3,"Una copla no me acuerdo,\n¿Cómo haré para acordarme?\nSe me hace preciso un maistro,\nPara que venga a dictarme.",3,1,0,49,"",0,4,"ae",35,0,-1,0,547,547,"2554","",0,"","","",1,0,0,[],""],["carrizo_salta-n2555-01",3,"Una Juana y dos Juanas,\nTres Juanas tengo,\nSi una Juana me deja,\nCon dos me quedo.",3,1,0,49,"",6,4,"eo",-1,0,-1,0,547,547,"2555","",0,"","","",1,0,0,[],""],["carrizo_salta-n2556-01",3,"Una mora me enamora,\nUna turca me da pena,\nY una cristiana me tiene,\nEntre grillos y cadenas.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,547,547,"2556","",0,"","","",8,0,0,[],""],["carrizo_salta-n2561-01",3,"Válgame Dios de los cielos!\nVálgame Dios, qué maleza!\nfo también sé cantar coplas,\nSacando de la cabeza.",3,1,0,49,"",0,4,"ea",108,0,-1,0,548,548,"2561","",0,"","","",33,0,0,[],""],["carrizo_salta-n2563-01",3,"Vamonós, compañeritos,\nVamonós al \"Carrizal\",\nVamonós a chupar caña,\nEn el pago \"El Totoral\".",3,1,0,49,"",0,4,"a",1,0,-1,0,548,548,"2563","",0,"","","",11,0,0,[],""],["carrizo_salta-n2563-a-01",3,"Vamonós, compañeritos.\nVamonós pal \"Carrizal\",\nVamonós a chupar caña,\nVamonós a Tucumán.",3,1,0,49,"",0,4,"a",-1,0,-1,0,548,548,"2563-a","",0,"","","",11,0,0,[],""],["carrizo_salta-n2564-01",3,"Vamonós, compañeritos,\nVamos como a segar caña,\nVamos a dormir temprano,\nTenimos que hacer mañana.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,548,548,"2564","",0,"","","",11,0,0,[],""],["carrizo_salta-n2565-01",3,"Vamonós, compañeritos,\nVamos todos a su casa,\nHallá ha de estar ese gente,\nLlorando como torcaza.",3,1,0,49,"",0,4,"aa",307,0,-1,0,548,548,"2565","",0,"","","",11,0,0,[],""],["carrizo_salta-n2566-01",3,"Vamonós, compañeritos,\nYa las cabrillas van altas,\nYa viene el alba y el día,\nDescubriendo nuestras faltas.",3,1,0,49,"",0,4,"aa",183,0,-1,0,548,548,"2566","",0,"","","",11,0,0,[],""],["carrizo_salta-n2567-01",3,"Vamonós pa lao de arriba,\nVamos como a atar jarilla,\nMi vidita está en el medio,\nSaquemelán pa l'orilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,548,548,"2567","",0,"","","",1,0,0,[],""],["carrizo_salta-n2568-01",3,"Vamonós pa lao de Salta,\nTodita la paisanada,\nEn Salta están esperando,\nCon bateas de empanadas.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,548,548,"2568","",0,"","","",1,0,0,[],""],["carrizo_salta-n2569-01",3,"Vamonós pa Tucumán,\nAl pago los bochincheros,\nCuando no bochincho yo,\nBochincha mi compañero.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,549,549,"2569","",0,"","","",1,0,0,[],""],["carrizo_salta-n2570-01",3,"Vamos al Pilcomayo,\nAhí se pasa buenos ratos,\nAllá se chupa y se canta,\n¡De arriba, se cayó un gato!",3,1,0,49,"",0,4,"ao",-1,0,-1,0,549,549,"2570","",0,"","","",1,0,0,[],""],["carrizo_salta-n2571-01",3,"Vamos al verde, sí,\nVamos al verde,\nDonde las esperanzas,\nNunca se pierden.",3,1,0,49,"",6,4,"ee",-1,0,-1,0,549,549,"2571","",0,"","","",1,0,0,[],""],["carrizo_salta-n2571-01-e2",3,"Vamos cantando y bailando,\nDiciendo a una voz:\n—A causa los celos,\nSe ausenta el amor.",3,1,0,49,"",0,4,"o",-1,0,-1,0,549,549,"2571","",0,"","","",2,0,0,[],""],["carrizo_salta-n2573-01",3,"Vamos de tejas arriba,\nVamos de escala en escala,\nVamos sacando las cuentas,\nUnas buenas y otras malas.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,549,549,"2573","",0,"","","",1,0,0,[],""],["carrizo_salta-n2574-01",3,"Vamos, querida comadre,\nA calmar nuestro dolor,\nQue nos espera la dicha,\nEn la ciencia del amor.",3,1,0,49,"",0,4,"o",72,0,-1,0,549,549,"2574","",0,"","","",1,0,0,[],""],["carrizo_salta-n2575-01",3,"Vamos separandonós,\nLos que seamos de esta parte,\nQue los unos ponen l'agua,\nY los otros toman mate.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,549,549,"2575","",0,"","","",1,0,0,[],""],["carrizo_salta-n2576-01",3,"Vamos, vidita, vamos,\nEl caminito es muy ancho,\nY que no te salgan cuernos,\nComo a carnero tahuancho.",3,1,0,49,"",0,4,"ao",380,0,-1,0,549,549,"2576","",0,"","","",1,0,0,[],""],["carrizo_salta-n2577-01",3,"Veinticinco años tengo,\nMadre, me quiero casar,\nNo tengo novia tuavía,\nPero me puedo buscar.",3,1,0,49,"",0,4,"a",21,0,-1,0,549,549,"2577","",0,"","","",1,0,0,[],""],["carrizo_salta-n2578-01",3,"Veinticinco bergantines,\nVeinticinco bogadores,\nVeinticinco lanchas traigo,\nPara embarcar mis amores.",3,1,0,49,"",0,4,"oe",5,0,-1,0,549,549,"2578","",0,"","","",1,0,0,[],""],["carrizo_salta-n2579-01",3,"Veinticinco limones,\nCarga una rama,\nY amanecen cuarenta,\nPor la mañana.",3,1,0,49,"",6,4,"aa",-1,0,-1,0,549,549,"2579","",0,"","","",6,0,0,[],""],["carrizo_salta-n2580-01",3,"Veme como ando, sí,\nVeme como ando,\nPor falta de una pluma,\nNo ando volando.",3,1,0,49,"",6,4,"ao",33,0,-1,0,549,549,"2580","",0,"","","",1,0,0,[],""],["carrizo_salta-n2581-01",3,"Vengansé todos conmigo,\nYo soy el maestro segundo,\nMe hallo capaz de cantar,\nCon el inventor del mundo.",3,1,0,49,"",0,4,"uo",179,0,-1,0,549,549,"2581","",0,"","","",1,0,0,[],""],["carrizo_salta-n2582-01",3,"Vengo del pago,\nQuiero farriar,\nTraigan aloja,\nQuiero chupar.",3,1,0,49,"",6,4,"a",21,0,-1,0,549,549,"2582","",0,"","","",1,0,0,[],""],["carrizo_salta-n2584-01",3,"Vení, venite, chinita,\nDijo un vallista,\nEl chambao se ha perdido,\nDe un chicuanista.",3,1,0,49,"",6,4,"ia",352,0,-1,0,550,550,"2584","",0,"","","",1,0,0,[],""],["carrizo_salta-n2585-01",3,"Vení, vidita, cantemos,\nVení, parate a mi lado,\nY si te celan conmigo,\nDecile que soy tu hermano.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,550,550,"2585","",0,"","","",2,0,0,[],""],["carrizo_salta-n2586-01",3,"Verdadero rey de copa,\nVerdadero dios Cupido,\nCausa las mujeres locas,\nSe mira el hombre perdido.",3,1,0,49,"",0,4,"io",101,0,-1,0,550,550,"2586","",0,"","","",1,0,0,[],""],["carrizo_salta-n2587-01",3,"Verdecito me mantengo,\nComo l'hoja del nogal,\nEn esta rueda cantando,\nMe gusta pagarles mal.",3,1,0,49,"",0,4,"a",1,0,-1,0,550,550,"2587","",0,"","","",2,0,0,[],""],["carrizo_salta-n2588-01",3,"Verde es el remate,\nVerde es la flor,\nSi este es buen remate,\nEl otro es mejor.",3,1,0,49,"",6,4,"o",72,0,-1,0,550,550,"2588","",0,"","","",1,0,0,[],""],["carrizo_salta-n2589-01",3,"Verde es el romero,\nCuando no florece,\nOscura la noche,\nCuando no amanece.",3,1,0,49,"",0,4,"ee",64,0,-1,0,550,550,"2589","",0,"","","",1,0,0,[],""],["carrizo_salta-n2590-01",3,"Verde planta, verde planta,\nVerde plantita de coles,\nYa se acaba el carnaval,\nAyer Martes, hoy Miercoles.",3,1,0,49,"",0,4,"oe",27,0,-1,0,550,550,"2590","",0,"","","",1,0,0,[],""],["carrizo_salta-n2591-01",3,"¿Ves aquel pájaro blanco,\nAsentado en esa lata?\nComo soy mujer honrada,\nNo me entrego ni por plata.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,550,550,"2591","",0,"","","",1,0,0,[],""],["carrizo_salta-n2592-01",3,"¿Ves aquel pájaro verde,\nAsentado en esa lata?\nNo hay mujer que se resista,\nCuando el hombre tiene plata.",3,1,0,49,"",0,4,"aa",74,0,-1,0,550,550,"2592","",0,"","","",1,0,0,[],""],["carrizo_salta-n2593-01",3,"¡Vidita, si me querís,\nDame mate con anís!\nPa que nunca te olvidís\nDe los gauchos que tenis.",3,1,0,49,"",5,4,"ei",58,0,-1,0,550,550,"2593","",0,"","","",10,0,0,[],""],["carrizo_salta-n2594-01",3,"¡Vidita, si me querís,\nSilbame como perdíz!\nComo soy mocito tierno,\nSujetame si podís.",3,1,0,49,"",0,4,"i",58,0,-1,0,550,550,"2594","",0,"","","",10,0,0,[],""],["carrizo_salta-n2595-01",3,"¡Viva el sol, viva la luna!\n¡Viva la estrella de oriente!\nEn un capullo de nieve,\n¡Vivan todos los presentes!",3,1,0,49,"",0,4,"ee",-1,0,-1,0,550,550,"2595","",0,"","","",6,0,0,[],""],["carrizo_salta-n2596-01",3,"¡Viva la media naranja!\n¡Viva la naranja entera!\nViva Bautista Bascari,\nQue defendió su bandera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,550,550,"2596","",0,"","","",3,0,0,[],""],["carrizo_salta-n2597-01",3,"Voy a cantar cuatro coplas,\nY no sé si servirán,\n¿No serán como las mozas,\nQue alzan la cola y se van?",3,1,0,49,"",0,4,"a",147,0,-1,0,551,551,"2597","",0,"","","",1,0,0,[],""],["carrizo_salta-n2598-01",3,"Voy a cantar esta copla,\nA' compás de la vihuela,\nSoy un ave solitaria,\nQue con cantar se consuela.",3,1,0,49,"",0,4,"ea",167,0,-1,0,551,551,"2598","",0,"","","",3,0,0,[],""],["carrizo_salta-n2599-01",3,"Voy a cantar esta copla,\nAi corte de una tijera,\nAl pobrecito i Gaspar,\nOigalén la voz siquiera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,551,551,"2599","",0,"","","",3,0,0,[],""],["carrizo_salta-n2600-01",3,"Voy a cantar esta copla,\nCon mi pausado y despacio,\nPorque con mucho rigor,\nNo se dentra en un palacio.",3,1,0,49,"",0,4,"ao",440,0,-1,0,551,551,"2600","",0,"","","",3,0,0,[],""],["carrizo_salta-n2600-02",3,"Voy a cantar fiero, fiero,\n¡Pa lo que me han de atender!\nAunque les cante bonito,\n¡Por lo que me han de querer!",3,1,0,49,"",0,4,"e",20,0,-1,0,551,551,"2600","",0,"","","",1,0,0,[],""],["carrizo_salta-n2602-01",3,"Voy a cantar mi coplita,\nAunque coquiando y pitando,\nA la moda las ovejas,\nCutipando, cutipando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,551,551,"2602","",0,"","","",1,0,0,[],""],["carrizo_salta-n2603-01",3,"Voy a cantar una letra,\nPero no voy a nombrar,\nLos voy a dejar en duda,\n¿Adivinen, quién será?",3,1,0,49,"",0,4,"a",-1,0,-1,0,551,551,"2603","",0,"","","",1,0,0,[],""],["carrizo_salta-n2604-01",3,"Voy a cantar un momento,\nPa continuar la alegría,\nPorque el corazón exige,\nMás empeño todavía.",3,1,0,49,"",0,4,"ia",0,0,-1,0,551,551,"2604","",0,"","","",1,0,0,[],""],["carrizo_salta-n2605-01",3,"Voy a cantar veinte coplas,\nVeintiuna con la tonada,\nEsa que cante después,\nEs la mejor concertada.",3,1,0,49,"",0,4,"aa",49,0,-1,0,551,551,"2605","",0,"","","",1,0,0,[],""],["carrizo_salta-n2606-01",3,"Voy a carniar mi toruno,\nEl padre de mis terneros,\nUsted es el dueño del cuero,\nYo me voa tender primero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,551,551,"2606","",0,"","","",1,0,0,[],""],["carrizo_salta-n2607-01",3,"Voy a cortar una flor,\nY adivinen cuál será,\nNo está lejos ni está cerca,\nAquicito nomá está.",3,1,0,49,"",0,4,"a",9,0,-1,0,551,551,"2607","",0,"","","",3,0,0,[],""],["carrizo_salta-n2608-01",3,"Voy a formar un barquito,\nEl mejor de la marina,\nPara embarcar corazones,\nDe Bolivia a la Argentina.",3,1,0,49,"",0,4,"ia",11,0,-1,0,551,551,"2608","",0,"","","",1,0,0,[],""],["carrizo_salta-n2609-01",3,"Voy a fumar un cigarro,\nCon el humo me mantengo,\nAsí mantengo a mi vida,\nCon el amor que le tengo.",3,1,0,49,"",0,4,"eo",124,0,-1,0,552,552,"2609","",0,"","","",3,0,0,[],""],["carrizo_salta-n2610-01",3,"Voy andando por la orilla,\nQue al medio no puedo entrar,\nNo tengo categoría,\nNi me puedo nivelar.",3,1,0,49,"",0,4,"a",21,0,-1,0,552,552,"2610","",0,"","","",1,0,0,[],""],["carrizo_salta-n2611-01",3,"Voy a tirar esta copla,\nArriba de l'escalera,\nMañana cuando me muera,\nCantará mi calavera.",3,1,0,49,"",0,4,"ea",44,0,-1,0,552,552,"2611","",0,"","","",1,0,0,[],""],["carrizo_salta-n2612-01",3,"Voy a vender esta copla,\nPara caerles en gracia,\nAyer cautivé un amor,\nHoy se me ha vuelto desgracia.",3,1,0,49,"",0,4,"aa",121,0,-1,0,552,552,"2612","",0,"","","",1,0,0,[],""],["carrizo_salta-n2613-01",3,"Vua dejar una que tengo,\nPor otra que ando queriendo,\nVua buscar una mocita,\nCon viejas yo no me avengo.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,552,552,"2613","",0,"","","",1,0,0,[],""],["carrizo_salta-n2614-01",3,"Vuela la perdiz, madre,\nAsí decile,\nA esa que anda bailando,\nQue no me olvide.",3,1,0,49,"",6,4,"ie",-1,0,-1,0,552,552,"2614","",0,"","","",4,0,0,[],""],["carrizo_salta-n2615-01",3,"Vuela la perdiz, madre,\nLa voladora,\nLe han cortado las alas,\n¡Que vuele ahora!",3,1,0,49,"",6,4,"oa",107,0,-1,0,552,552,"2615","",0,"","","",4,0,0,[],""],["carrizo_salta-n2616-01",3,"Vuela la perdiz, madre,\nZapatía duro,\nNo vaya a ser que seas,\nCarnero astuto.",3,1,0,49,"",6,4,"uo",-1,0,-1,0,552,552,"2616","",0,"","","",4,0,0,[],""],["carrizo_salta-n2617-01",3,"Vuela la perdiz, madre,\nZapatía fuerte,\nHasta que te conviden,\nCon aguardiente.",3,1,0,49,"",6,4,"ee",-1,0,-1,0,552,552,"2617","",0,"","","",4,0,0,[],""],["carrizo_salta-n2618-01",3,"¡Vuela, vuela, galondrina!\n¡Vuela, vuela, tu volido!\nAvisame con tus alas,\nA dónde tenís tu nido.",3,1,0,49,"",0,4,"io",101,0,-1,0,552,552,"2618","",0,"","","",1,0,0,[],""],["carrizo_salta-n2619-01",3,"Ya dicen, yo soy cantor,\nPorque saben cuatro coplas,\nY no saben defender,\nEl derecho que les toca.",3,1,0,49,"",0,4,"oa",-1,0,-1,0,552,552,"2619","",0,"","","",1,0,0,[],""],["carrizo_salta-n2620-01",3,"Ya es tarde, vidita mía,\nYa está arribita la luna,\nCarnaval viene al galope,\nY la chichita madura.",3,1,0,49,"",0,4,"ua",-1,0,-1,0,552,552,"2620","",0,"","","",1,0,0,[],""],["carrizo_salta-n2621-01",3,"Ya me han sacado la manga,\nAhora sáqueme la falda,\nPa cantar la vidalita,\nMás tengo pecho que espalda.",3,1,0,49,"",0,4,"aa",96,0,-1,0,552,552,"2621","",0,"","","",1,0,0,[],""],["carrizo_salta-n2622-01",3,"Ya me voy pa lao de abajo,\nEn mi caballito oscuro,\nMe voy galopiando siempre,\nPor lo blando y por lo duro.",3,1,0,49,"",0,4,"uo",248,0,-1,0,552,552,"2622","",0,"","","",3,0,0,[],""],["carrizo_salta-n2623-01",3,"Ya me voy para mi abajo,\nYa me voy para mi centro,\nAllá vive quién me tiene,\nPerdido el entendimiento.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,552,552,"2623","",0,"","","",1,0,0,[],""],["carrizo_salta-n2624-01",3,"Ya me voy para mi casa,\nPorque me quiero dormir,\nUn ojo se me ha cerrado,\nY el otro no puedo abrir.",3,1,0,49,"",0,4,"i",157,0,-1,0,552,552,"2624","",0,"","","",3,0,0,[],""],["carrizo_salta-n2625-01",3,"Ya no hay coplas ni conciertos,\nTodo es puro sentimiento.\nEn el centro de la mar,\nYa la sirena se ha muerto.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,553,553,"2625","",0,"","","",1,0,0,[],""],["carrizo_salta-n2625-a-01",3,"Ya no hay coplas ni tonadas,\nYo les digo lo que es cierto,\nEn el centro de la mar,\nYa la sirena se ha muerto.",3,1,0,49,"",0,4,"eo",88,0,-1,0,553,553,"2625-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2626-01",3,"Ya no sé que vua cantar,\nQue todo me había olvidado,\nYo tengo la culpa de esto,\nNo me había ejercitado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,553,553,"2626","",0,"","","",1,0,0,[],""],["carrizo_salta-n2627-01",3,"Ya no voy a querer firme,\nPorque firme ya no vale,\nVoy a querer al descuido,\nAl uso de Buenos Aires.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,553,553,"2627","",0,"","","",1,0,0,[],""],["carrizo_salta-n2628-01",3,"Ya que por la mano viene,\nDe las coplas haré gasto,\nEn medio la polvareda,\nCamino y no dejo rastro.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,553,553,"2628","",0,"","","",1,0,0,[],""],["carrizo_salta-n2629-01",3,"Ya que todos han cantado,\nYo también quiero cantar,\nCante bien o cante mal,\nPara mí es un carnaval.",3,1,0,49,"",0,4,"a",1,0,-1,0,553,553,"2629","",0,"","","",2,0,0,[],""],["carrizo_salta-n2630-01",3,"Ya que todos han cantado,\nYo también quiero cantar,\nQue yo también tengo hiel,\nY se puede reventar.",3,1,0,49,"",0,4,"a",21,0,-1,0,553,553,"2630","",0,"","","",2,0,0,[],""],["carrizo_salta-n2631-01",3,"Ya sale el lucero grande,\nCaminando cuatro a cuatro,\nSi la fulanita es tuya,\nVéndela caro o barato.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,553,553,"2631","",0,"","","",2,0,0,[],""],["carrizo_salta-n2632-01",3,"Ya sale el lucero grande,\nEntre medio las estrellas,\nAsí quisiera salir,\nEntre medio de doncellas.",3,1,0,49,"",0,4,"ea",89,0,-1,0,553,553,"2632","",0,"","","",2,0,0,[],""],["carrizo_salta-n2633-01",3,"Ya se fué Carnavalcito,\nPor allá, por Puerta i Díaz,\nYa se marchó ese caudillo,\nLlenito de picardías.",3,1,0,49,"",0,4,"ia",214,0,-1,0,553,553,"2633","",0,"","","",1,0,0,[],""],["carrizo_salta-n2633-a-01",3,"Ya se va Carnavalcito,\nPor allá por Puerta i Díaz,\nCon las alforjitas llenas,\nLlenitas de picardías.",3,1,0,49,"",0,4,"ia",214,0,-1,0,553,553,"2633-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2634-01",3,"Ya se ha muerto Carnaval,\nComiendo una vaca mocha,\nYa lo llevan a enterrar,\nA la Quebrada i Sococha.",3,1,0,49,"",0,4,"oa",441,0,-1,0,553,553,"2634","",0,"","","",1,0,0,[],""],["carrizo_salta-n2635-01",3,"Ya sé que estas en camisa,\nTras la ventana escuchando,\nEn un papel escribiendo,\nLas coplas que estoy cantando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,553,553,"2635","",0,"","","",3,0,0,[],""],["carrizo_salta-n2636-01",3,"Ya sé que m'hi de morir,\nCuando me llegue el destino,\nNo soy corazón de bronce,\nNi entrañas de cristal fino.",3,1,0,49,"",0,4,"io",199,0,-1,0,553,553,"2636","",0,"","","",1,0,0,[],""],["carrizo_salta-n2637-01",3,"Ya se van mis compañeros,\nY yo también debo d'irme,\nEcharé mi poncho al hombro,\nY tendré que despedirme.",3,1,0,49,"",0,4,"ie",184,0,-1,0,553,553,"2637","",0,"","","",1,0,0,[],""],["carrizo_salta-n2638-01",3,"Ya se viene Carnaval,\nCon su carguita i cajones,\nYa se viene el sinvergüenza,\nCon la faja en los talones.",3,1,0,49,"",0,4,"oe",34,0,-1,0,553,553,"2638","",0,"","","",13,0,0,[],""],["carrizo_salta-n2639-01",3,"Ya se viene Carnaval,\nMontadito en un guanaco,\nAquí lo estoy esperando,\nPara hacer los tincunacos.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,554,554,"2639","",0,"","","",13,0,0,[],""],["carrizo_salta-n2640-01",3,"Ya se viene Carnaval,\nPor allá por Cajoncillo,\nAquí lo estoy esperando,\nCon la plata en el bolsillo.",3,1,0,49,"",0,4,"io",228,0,-1,0,554,554,"2640","",0,"","","",13,0,0,[],""],["carrizo_salta-n2641-01",3,"Ya se viene Carnaval,\nPor allá por las lomitas,\nAquí lo estoy esperando,\nCon la aloja coladita.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,554,554,"2641","",0,"","","",13,0,0,[],""],["carrizo_salta-n2642-01",3,"Ya se viene Carnaval,\nPor allá por \"Los Cardones\",\nAquí lo estoy esperando,\nRemedando los calzones.",3,1,0,49,"",0,4,"oe",34,0,-1,0,554,554,"2642","",0,"","","",13,0,0,[],""],["carrizo_salta-n2643-01",3,"Ya se viene Carnaval,\nPor allá por \"Los Laureles\",\nAquí lo estoy aguardando,\nCon la caja y los claveles.",3,1,0,49,"",0,4,"ee",97,0,-1,0,554,554,"2643","",0,"","","",13,0,0,[],""],["carrizo_salta-n2644-01",3,"Ya se viene Carnaval,\nPor el camino de Salta,\nAquí lo estoy esperando,\nPara el Domingo, sin falta.",3,1,0,49,"",0,4,"aa",442,0,-1,0,554,554,"2644","",0,"","","",13,0,0,[],""],["carrizo_salta-n2645-01",3,"Ya se viene Carnaval,\nPor el camino i San Lúcas,\nAquí lo están esperando\nCon el sombrero en la nuca.",3,1,0,49,"",0,4,"ua",-1,0,-1,0,554,554,"2645","",0,"","","",13,0,0,[],""],["carrizo_salta-n2645-a-01",3,"Ya se viene Carnaval,\nPor la falda de San Lúcas,\nCastigando y sujetando,\nCon el sombrero en la nuca.",3,1,0,49,"",0,4,"ua",-1,0,-1,0,554,554,"2645-a","",0,"","","",13,0,0,[],""],["carrizo_salta-n2646-01",3,"Ya se viene Carnaval,\nPor la costa \"El Cerro Bayo\",\nEl bichito el Carnaval,\nViene a estropiarme el caballo.",3,1,0,49,"",1,4,"ao",102,0,-1,0,554,554,"2646","",0,"","","",13,0,0,[],""],["carrizo_salta-n2647-01",3,"Ya se viene Carnaval,\nPor la \"Falda de Zorrilla\",\nAquí lo están esperando,\nCon una horniada i tortilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,554,554,"2647","",0,"","","",13,0,0,[],""],["carrizo_salta-n2648-01",3,"Ya se viene Carnaval,\nYa se viene el majadero,\nA estropiarme mi caballo,\nA ensuciarme mis peleros.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,554,554,"2648","",0,"","","",13,0,0,[],""],["carrizo_salta-n2648-02",3,"Ya viene ese Carnaval,\nYa viene ese majadero,\nA estropiar mis animales,\nAl zaino, con el overo.",3,1,0,49,"",0,4,"eo",38,0,-1,0,554,554,"2648","",0,"","","",1,0,0,[],""],["carrizo_salta-n2649-01",3,"Ya todos habrán cantado,\nYo también quiero cantar,\nQuiero deshechar mis penas,\nQue me tienen por matar.",3,1,0,49,"",0,4,"a",21,0,-1,0,554,554,"2649","",0,"","","",1,0,0,[],""],["carrizo_salta-n2650-01",3,"Ya viene blanquiando el día,\nLas estrellas van raliando,\nComo soy mozo cantor,\nComo quiera voy cantando.",3,1,0,49,"",0,4,"ao",33,0,-1,0,554,554,"2650","",0,"","","",2,0,0,[],""],["carrizo_salta-n2651-01",3,"Ya viene el alba llegando,\nYo ya quiero preguntar,\n¿A dónde se encontrará,\nLa bella flor del lugar?",3,1,0,49,"",0,4,"a",-1,0,-1,0,555,555,"2651","",0,"","","",1,0,0,[],""],["carrizo_salta-n2652-01",3,"Ya viene el Carnaval cerca,\nEn una yegua tordilla,\nAquí lo estoy esperando,\nCon una carga i tortilla.",3,1,0,49,"",0,4,"ia",162,0,-1,0,555,555,"2652","",0,"","","",3,0,0,[],""],["carrizo_salta-n2653-01",3,"Ya viene el Carnaval cerca,\nPor \"L'Abra de Pucará\",\nAquí lo estoy esperando,\nTal vez vendrá por acá.",3,1,0,49,"",0,4,"a",9,0,-1,0,555,555,"2653","",0,"","","",3,0,0,[],""],["carrizo_salta-n2654-01",3,"Ya viene el Carnaval cerca,\nPor \"La Cuesta del Obispo\",\nAquí lo estoy esperando\nCon queso y duraznos friscos.",3,1,0,49,"",0,4,"io",-1,0,-1,0,555,555,"2654","",0,"","","",3,0,0,[],""],["carrizo_salta-n2655-01",3,"Ya viene este Carnaval,\nPor el camino de Trancas,\nCon un sapo redomón,\nCon un cordero en las ancas.",3,1,0,49,"",0,4,"aa",443,0,-1,0,555,555,"2655","",0,"","","",1,0,0,[],""],["carrizo_salta-n2656-01",3,"Ya viene la cerrazón,\nTapando el cerro chiquito,\nVidita, si me querís,\nTapame con tu ponchito.",3,1,0,49,"",0,4,"io",119,0,-1,0,555,555,"2656","",0,"","","",1,0,0,[],""],["carrizo_salta-n2657-01",3,"Yo canto buenas tonadas,\nY no canto disparates,\nParece que estoy cantando,\nEn el pueblo i Cafayate.",3,1,0,49,"",0,4,"ae",-1,0,-1,0,555,555,"2657","",0,"","","",1,0,0,[],""],["carrizo_salta-n2658-01",3,"Yo compro un aborrecido,\nPero ha i ser con la advertencia,\nQue no ha de mirar a nadie,\nSin tomarme la licencia.",3,1,0,49,"",0,4,"ea",46,0,-1,0,555,555,"2658","",0,"","","",1,0,0,[],""],["carrizo_salta-n2659-01",3,"Yo he nacido de mi madre,\nHe nacido en una flor,\nPara cantar el amor,\nMe ha echado Nuestro Señor.",3,1,0,49,"",0,4,"o",72,0,-1,0,555,555,"2659","",0,"","","",1,0,0,[],""],["carrizo_salta-n2660-01",3,"Yo me llamo poca - pena,\nPariente de mala - gana,\n¿Y qué dirían de mí,\nSi cantando les ganara?",3,1,0,49,"",0,4,"aa",-1,0,-1,0,555,555,"2660","",0,"","","",2,0,0,[],""],["carrizo_salta-n2661-01",3,"Yo me voy pa lao de abajo,\nEn mi caballo tordillo,\nHaciendo bramar las piedras,\nComo a golpes de un martillo.",3,1,0,49,"",0,4,"io",228,0,-1,0,555,555,"2661","",0,"","","",1,0,0,[],""],["carrizo_salta-n2662-01",3,"Yo nací para cantar,\nDesde el vientre de mi madre,\nEso voa agarrar de herencia,\nSi soy hija de mi padre.",3,1,0,49,"",0,4,"ae",166,0,-1,0,555,555,"2662","",0,"","","",1,0,0,[],""],["carrizo_salta-n2663-01",3,"Yo no canto por cantar,\nYo canto por aprender,\nPara mí es mucha vergüenza,\nQuerer cantar sin saber.",3,1,0,49,"",0,4,"e",20,0,-1,0,555,555,"2663","",0,"","","",2,0,0,[],""],["carrizo_salta-n2664-01",3,"Yo nomás soy el indigno,\nYo nomás soy el fatal,\nComo no les caigo en gracia,\nToda falta me han de hallar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,555,555,"2664","",0,"","","",1,0,0,[],""],["carrizo_salta-n2665-01",3,"Yo no m' hi d' ir esta noche,\nYo m' hi d' ir cuando amanezca,\nHasta que halle quién me quiera,\nO de mí se compadezca.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,555,555,"2665","",0,"","","",1,0,0,[],""],["carrizo_salta-n2666-01",3,"Yo no paso pa la banda,\nDe miedo de las heladas,\nPor no mojarme los pies,\nEn las aguas escarchadas.",3,1,0,49,"",0,4,"aa",282,0,-1,0,555,555,"2666","",0,"","","",1,0,0,[],""],["carrizo_salta-n2667-01",3,"Yo no sé pitar en chala,\nCuando hay una pulpería,\nYo sé cantar buenas coplas,\nY no cantar operías.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,556,556,"2667","",0,"","","",1,0,0,[],""],["carrizo_salta-n2668-01",3,"Yo no sé qué voy a hacer,\nCon esta mi mala vida,\nA mí me cortan calzones,\nSin tomarme la medida.",3,1,0,49,"",0,4,"ia",37,0,-1,0,556,556,"2668","",0,"","","",1,0,0,[],""],["carrizo_salta-n2669-01",3,"Yo no soy gaucho de aquí,\nSeñores, yo soy de allá,\nSi quieren que yo los lleve,\nYa se pueden aprontar.",3,1,0,49,"",0,4,"a",-1,0,-1,0,556,556,"2669","",0,"","","",4,0,0,[],""],["carrizo_salta-n2670-01",3,"Yo no soy gaucho de aquí,\nYo soy gaucho santiagueño,\nYo sé sentir por lo mío,\nNo sé sentir po lo ajeno.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,556,556,"2670","",0,"","","",4,0,0,[],""],["carrizo_salta-n2671-01",3,"Yo no soy gaucho de aquí,\nYo soy un gaucho rayano,\nDe la provincia de Salta,\nCon la provincia i Santiago.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,556,556,"2671","",0,"","","",4,0,0,[],""],["carrizo_salta-n2672-01",3,"Yo no soy hoyón de fragua,\nNi martillo que da golpe,\nCada cual siente su pena,\nLa mía la siento el doble.",3,1,0,49,"",0,4,"oe",-1,0,-1,0,556,556,"2672","",0,"","","",1,0,0,[],""],["carrizo_salta-n2673-01",3,"Yo no soy ni buenamoza,\nNi me suelo ponderar,\nSoy morenita que sirvo,\nCasos de necesidad.",3,1,0,49,"",0,4,"a",-1,0,-1,0,556,556,"2673","",0,"","","",2,0,0,[],""],["carrizo_salta-n2674-01",3,"Yo no soy ni buenamoza,\nNi mucho menos soy rica,\nTampoco soy envidiosa,\nNi quiero con nadie pica.",3,1,0,49,"",1,4,"ia",174,0,-1,0,556,556,"2674","",0,"","","",2,0,0,[],""],["carrizo_salta-n2675-01",3,"Yo no soy toro de aquí,\nYo soy torito abajeño,\nBusco una prenda solita,\nY sólo encuentro con dueño.",3,1,0,49,"",0,4,"eo",138,0,-1,0,556,556,"2675","",0,"","","",1,0,0,[],""],["carrizo_salta-n2676-01",3,"Yo planté una siempreviva,\nLa siempreviva prendió,\n¡Qué viva la siempreviva,\nY el corazón de los dos!",3,1,0,49,"",0,4,"o",-1,0,-1,0,556,556,"2676","",0,"","","",1,0,0,[],""],["carrizo_salta-n2677-01",3,"Yo recién estoy llegando,\nComo llega una centella,\nPorque he tenido noticias,\nQue aquí se toma en botellas.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,556,556,"2677","",0,"","","",1,0,0,[],""],["carrizo_salta-n2678-01",3,"Yo recién vengo llegando,\nY me quiero declarar,\nA una que me hizo sentir,\nMocita de este lugar.",3,1,0,49,"",0,4,"a",21,0,-1,0,556,556,"2678","",0,"","","",1,0,0,[],""],["carrizo_salta-n2679-01",3,"Yo sólo tengo un querer,\nUn amor y una pasión,\nYo les canto a mis amigos,\nCon todo mi corazón.",3,1,0,49,"",0,4,"o",31,0,-1,0,556,556,"2679","",0,"","","",1,0,0,[],""],["carrizo_salta-n2680-01",3,"Yo soy como el boliviano,\nNunca me falta la coca,\nEn una rueda cantando,\nCada cual echa su copla.",3,1,0,49,"",0,4,"oa",-1,0,-1,0,556,556,"2680","",0,"","","",1,0,0,[],""],["carrizo_salta-n2681-01",3,"Yo soy como el mal viviente,\nEl bien me parece mal,\nDesecho la cama buena,\nPor dormir en pedregal.",3,1,0,49,"",0,4,"a",1,0,-1,0,557,557,"2681","",0,"","","",1,0,0,[],""],["carrizo_salta-n2682-01",3,"Yo soy como el mes de Agosto,\nTraigo viento y huracanes,\nEstoy dispuesto a voltiar,\nQuebrachos y guayacanes.",3,1,0,49,"",0,4,"ae",444,0,-1,0,557,557,"2682","",0,"","","",2,0,0,[],""],["carrizo_salta-n2683-01",3,"Yo soy como el picaflor,\nQue pica todas las flores,\nSólo las piedras ni pico,\nPorque no tienen olores.",3,1,0,49,"",0,4,"oe",5,0,-1,0,557,557,"2683","",0,"","","",1,0,0,[],""],["carrizo_salta-n2684-01",3,"Yo soy como el temporal,\nQue me ando de cerro en cerro,\nMe vengo de otros lugares,\nHaciendo toriar los perros.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,557,557,"2684","",0,"","","",3,0,0,[],""],["carrizo_salta-n2685-01",3,"Yo soy como el tucu-tucu,\nA donde quiera me alumbro,\nY como mocito tierno,\nNo sé las cosas del mundo.",3,1,0,49,"",0,4,"uo",-1,0,-1,0,557,557,"2685","",0,"","","",1,0,0,[],""],["carrizo_salta-n2686-01",3,"Yo soy como la calandria,\nMis días no van menguando,\nPorque el invierno y verano,\nSólo lo paso cantando.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,557,557,"2686","",0,"","","",4,0,0,[],""],["carrizo_salta-n2686-a-01",3,"Yo soy como la calandria,\nPara mí no hay tiempo malo,\nSea invierno, sea verano,\nYo me lo paso cantando.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,557,557,"2686-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n2686-b-01",3,"Yo soy como la calandria,\nQue canta de noche y día,\nPara mí no hay tiempo malo,\nYo canto toda la vida.",3,1,0,49,"",0,4,"ia",-1,0,-1,0,557,557,"2686-b","",0,"","","",4,0,0,[],""],["carrizo_salta-n2687-01",3,"Yo soy como la cigarra,\nCorta vida y larga fama,\nY me amanezco cantando,\nDe la noche a la mañana.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,557,557,"2687","",0,"","","",1,0,0,[],""],["carrizo_salta-n2688-01",3,"Yo soy como la culebra,\nPor donde quiera me arrastro,\nPor medio la polvadera,\nCamino y no dejo rastro.",3,1,0,49,"",0,4,"ao",445,0,-1,0,557,557,"2688","",0,"","","",1,0,0,[],""],["carrizo_salta-n2689-01",3,"Yo soy como la gallina,\nQue me paso entre los yuyos,\nCantando vivo en los montes,\nComo el zorro y el coyuyo.",3,1,0,49,"",0,4,"uo",-1,0,-1,0,557,557,"2689","",0,"","","",1,0,0,[],""],["carrizo_salta-n2690-01",3,"Yo soy como la paloma,\nCanto medio l' aguacero,\nCuando remanece el día,\nRelumbro como el lucero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,557,557,"2690","",0,"","","",3,0,0,[],""],["carrizo_salta-n2691-01",3,"Yo soy como planta i tuna,\nTodo se me va en penquiar,\nMe parezco al peje en l' agua,\nTodo se me va en nadar.",3,1,0,49,"",0,4,"a",21,0,-1,0,557,557,"2691","",0,"","","",1,0,0,[],""],["carrizo_salta-n2692-01",3,"Yo soy como la sortija,\nQue no tiene paradero,\nQue se anda de dedo en dedo,\nDejar de querer no puedo.",3,1,0,49,"",0,4,"eo",304,0,-1,0,557,557,"2692","",0,"","","",1,0,0,[],""],["carrizo_salta-n2693-01",3,"Yo soy como Martín Fierro,\nCuando me pongo a cantar,\nCoplas salen adelante,\nComo agua de un manantial.",3,1,0,49,"",0,4,"a",-1,0,-1,0,557,557,"2693","",0,"","","",1,0,0,[],""],["carrizo_salta-n2694-01",3,"Yo soy como pesadilla,\nCuando empiezo a perseguir,\nPor más que quiera, mi amigo,\nNo lo hi de dejar dormir.",3,1,0,49,"",0,4,"i",157,0,-1,0,557,557,"2694","",0,"","","",1,0,0,[],""],["carrizo_salta-n2695-01",3,"Yo soy como tigre viejo,\nSalgo de mi triste cueva,\nDesprecio las presas viejas,\nPor salir a comer nuevas.",3,1,0,49,"",0,4,"ea",-1,0,-1,0,558,558,"2695","",0,"","","",1,0,0,[],""],["carrizo_salta-n2696-01",3,"Yo soy ese fulanito,\nEl más querido y honrado,\nBusque, niña, en su registro,\nTal vez no me habrá borrado.",3,1,0,49,"",0,4,"ao",14,0,-1,0,558,558,"2696","",0,"","","",3,0,0,[],""],["carrizo_salta-n2697-01",3,"Yo soy ese fulanito,\nNacido el noventa y nueve,\nBautizado en día Martes,\nConfirmado en día Jueves.",3,1,0,49,"",0,4,"ee",-1,0,-1,0,558,558,"2697","",0,"","","",3,0,0,[],""],["carrizo_salta-n2698-01",3,"Yo soy ese fulanito,\nSepan si quieren saber,\nEngendrado por un hombre,\nNacido de una mujer",3,1,0,49,"",0,4,"e",20,0,-1,0,558,558,"2698","",0,"","","",3,0,0,[],""],["carrizo_salta-n2699-01",3,"Yo soy ese pobre mozo,\nPariente de la sirena.\n¿Cómo no hi de ser familia,\nSiendo sangre de sus venas?",3,1,0,49,"",0,4,"ea",-1,0,-1,0,558,558,"2699","",0,"","","",2,0,0,[],""],["carrizo_salta-n2700-01",3,"Yo soy ese toro bueno,\nTorito de la lomada,\nEn las astas llevo coplas,\nY en la garganta tonadas.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,558,558,"2700","",0,"","","",2,0,0,[],""],["carrizo_salta-n2701-01",3,"Yo soy fulano de tal,\nYo soy su amigo leal,\nPor venir a la Argentina,\nDejé la Banda Oriental.",3,1,0,49,"",0,4,"a",1,0,-1,0,558,558,"2701","",0,"","","",4,0,0,[],""],["carrizo_salta-n2702-01",3,"Yo soy hijo de la peña,\nMi madre se llama leña,\nMi padre se llama viento,\nYo me llamo pensamiento.",3,1,0,49,"",5,4,"eo",94,0,-1,0,558,558,"2702","",0,"","","",1,0,0,[],""],["carrizo_salta-n2703-01",3,"Yo soy hijo de mi madre,\nA mi padre parecido,\nA mí me echaron al mundo,\nPor alegre y divertido.",3,1,0,49,"",0,4,"io",101,0,-1,0,558,558,"2703","",0,"","","",1,0,0,[],""],["carrizo_salta-n2704-01",3,"Yo soy lo mismo que santa,\nParecida a Santa Aleja,\nNo hi de dejar de cantar,\nAunque me muera de vieja.",3,1,0,49,"",0,4,"ea",165,0,-1,0,558,558,"2704","",0,"","","",1,0,0,[],""],["carrizo_salta-n2705-01",3,"Yo soy mojarra del agua,\nComida de las gaviotas,\nSoy hijo de un Pedro Vargas,\nNacido de una Carlota.",3,1,0,49,"",0,4,"oa",-1,0,-1,0,558,558,"2705","",0,"","","",1,0,0,[],""],["carrizo_salta-n2706-01",3,"Yo soy nacida en el campo,\nSoy hija de una carancha,\nTengo una manito menos,\nY una patita de plancha.",3,1,0,49,"",0,4,"aa",446,0,-1,0,558,558,"2706","",0,"","","",1,0,0,[],""],["carrizo_salta-n2707-01",3,"Yo soy nacido en el campo,\nSobre una pirca,\nNunca recibí bautismo,\nMe llaman Vilca.",3,1,0,49,"",6,4,"ia",-1,0,-1,0,558,558,"2707","",0,"","","",3,0,0,[],""],["carrizo_salta-n2708-01",3,"Yo soy nacido en el campo,\nSoy hijo de una alcatraza,\nPor eso todos me dicen:\n—¿De ande salís mala traza?",3,1,0,49,"",0,4,"aa",307,0,-1,0,558,558,"2708","",0,"","","",3,0,0,[],""],["carrizo_salta-n2709-01",3,"Yo soy nacido en Santiago,\nBautizado en Tucumán,\nY mi nombre es Secundino,\nMi apellido es Barracán.",3,1,0,49,"",0,4,"a",147,0,-1,0,559,559,"2709","",0,"","","",1,0,0,[],""],["carrizo_salta-n2710-01",3,"Yo soy paloma del cerro,\nQue voy bajando a la aguada,\nCon las alitas la enturbio,\nPor no tomar agua clara.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,559,559,"2710","",0,"","","",1,0,0,[],""],["carrizo_salta-n2711-01",3,"Yo soy palomita nueva,\nQue recién quiere volar,\nNo me diga relaciones,\nPor que no sé contestar.",3,1,0,49,"",0,4,"a",21,0,-1,0,559,559,"2711","",0,"","","",1,0,0,[],""],["carrizo_salta-n2712-01",3,"Yo soy Pastorcito Luna,\nCantorcito \"L' Angostura\",\nEl día que yo me muera,\nCantará mi sepultura.",3,1,0,49,"",0,4,"ua",17,0,-1,0,559,559,"2712","",0,"","","",1,0,0,[],""],["carrizo_salta-n2713-01",3,"Yo soy peje que en el agua,\nToda mi existencia ha sido,\nTambién me muero de sed,\nSiendo del agua nacido.",3,1,0,49,"",0,4,"io",101,0,-1,0,559,559,"2713","",0,"","","",1,0,0,[],""],["carrizo_salta-n2714-01",3,"Yo soy quien ando en los campos,\nY bajo a los lamederos,\nY de toda la cuadrilla,\nSoy el mozo más jullero.",3,1,0,49,"",0,4,"eo",-1,0,-1,0,559,559,"2714","",0,"","","",1,0,0,[],""],["carrizo_salta-n2715-01",3,"Yo soy su amigo leal,\nVd. es mi amigo querido,\nPa que muente su caballo,\nYo l' hi tener el estribo.",3,1,0,49,"",0,4,"io",-1,0,-1,0,559,559,"2715","",0,"","","",1,0,0,[],""],["carrizo_salta-n2716-01",3,"Yo soy un lorito nuevo,\nQue recién salgo a volar,\nTirame un granito de oro,\nSi me quieres cautivar.",3,1,0,49,"",0,4,"a",21,0,-1,0,559,559,"2716","",0,"","","",1,0,0,[],""],["carrizo_salta-n2717-01",3,"Yo soy un loro choclero,\nChiquitito y majadero,\nBusco a las chicas bonitas,\nComo la vaca al ternero.",3,1,0,49,"",0,4,"eo",38,0,-1,0,559,559,"2717","",0,"","","",2,0,0,[],""],["carrizo_salta-n2718-01",3,"Yo soy viejo en el oficio,\nY poco sé creer sin ver,\nPorque en este mundo hay muchos,\nSe dan fama sin tener.",3,1,0,49,"",0,4,"e",20,0,-1,0,559,559,"2718","",0,"","","",1,0,0,[],""],["carrizo_salta-n2719-01",3,"Yo también como los buenos,\nVoy a pegar mi petardo,\nPa que no diga la gente,\nAhi viene el sombrero largo.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,559,559,"2719","",0,"","","",2,0,0,[],""],["carrizo_salta-n2720-01",3,"Yo también como los buenos,\nQuiero pegar mis petardos,\nPorque dicen que de noche,\nTodos los gatos son pardos.",3,1,0,49,"",0,4,"ao",447,0,-1,0,559,559,"2720","",0,"","","",2,0,0,[],""],["carrizo_salta-n2721-01",3,"Yo también me debo ir,\nSi se van mis compañeros,\nPa que no diga la gente:\n—¡Qué colla tan majadero!",3,1,0,49,"",0,4,"eo",-1,0,-1,0,559,559,"2721","",0,"","","",1,0,0,[],""],["carrizo_salta-n2722-01",3,"Yo también sabía cantar,\nNo con caja ni guitarra,\nCantar con mi sola boca,\nComo cantan las chicharras.",3,1,0,49,"",0,4,"aa",-1,0,-1,0,559,559,"2722","",0,"","","",1,0,0,[],""],["carrizo_salta-n2723-01",3,"Yo también sabía querer,\nY no daba a conocer,\nSólo en este pago hi visto,\nQue a todos hacen saber.",3,1,0,49,"",0,4,"e",20,0,-1,0,560,560,"2723","",0,"","","",1,0,0,[],""],["carrizo_salta-n2724-01",3,"Yo también soy pescuecero,\nPero vuelvo sobre el lazo,\nPor eso será que canto,\nComo haciendo poco caso.",3,1,0,49,"",0,4,"ao",-1,0,-1,0,560,560,"2724","",0,"","","",1,0,0,[],""],["carrizo_salta-n2725-01",3,"Yo también voy a decir,\nLo que dijo Juan del Monte:\n—Cuando muera mi caballo,\nLlorarán mis guardamontes.",3,1,0,49,"",0,4,"oe",-1,0,-1,0,560,560,"2725","",0,"","","",3,0,0,[],""],["carrizo_salta-n2726-01",3,"Yo tenía mi buen apero,\nDe tiento crudo y sobado,\nQue me lo había regalado,\nUn viejito aparejero.",3,1,0,49,"",11,4,"eo",38,0,-1,0,560,560,"2726","",0,"","","",1,0,0,[],""],["carrizo_salta-n2727-01",3,"Yo tenía mis tres novias,\nJuanita, Pepa y Marciana,\nA unas iba de noche,\nA otras por la mañana.",3,1,0,49,"",0,4,"aa",4,0,-1,0,560,560,"2727","",0,"","","",1,0,0,[],""],["carrizo_salta-n2728-01",3,"Yo tuve mis tres queridas,\nDe las tres no son ninguna,\nVoy a buscar amor nuevo,\nPara probar la fortuna.",3,1,0,49,"",0,4,"ua",56,0,-1,0,560,560,"2728","",0,"","","",1,0,0,[],""],["carrizo_salta-n2729-01",3,"Yo vivo en la Banda Grande,\nDonde viven los marinos,\nDonde está la flor morada,\nLa prenda que más estimo.",3,1,0,49,"",0,4,"io",-1,0,-1,0,560,560,"2729","",0,"","","",1,0,0,[],""],["carrizo_salta-n2730-01",3,"Yo voy a hacer un barquito,\nDe la pata de un guanaco,\nPara embarcar corazones,\nSanta Rosa y Angastaco.",3,1,0,49,"",0,4,"ao",423,0,-1,0,560,560,"2730","",0,"","","",1,0,0,[],""],["carrizo_salta-n2731-01",3,"Abran cancha al charabón!\nQue se viene como flecha,\nEnvuelto el poncho en la zurda,\nY el facón en la derecha.",3,1,0,50,"",0,4,"ea",269,0,-1,0,562,562,"2731","",0,"","","",1,0,0,[],""],["carrizo_salta-n2732-01",3,"A Dios le debo la vida,\nAl fondero la comida,\nAl comisario la multa,\nY al milico la propina.",3,1,0,50,"",0,4,"ia",-1,0,-1,0,562,562,"2732","",0,"","","",1,0,0,[],""],["carrizo_salta-n2733-01",3,"Aguardiente y vino puro,\nEs lo que marca la ley,\nLa agua se hizo para el buey,\nQue tiene los cuernos duros.",3,1,0,50,"",5,4,"uo",-1,0,-1,0,562,562,"2733","",0,"","","",4,0,0,[],""],["carrizo_salta-n2734-01",3,"¡A la copa llaman Juana!\nY a la zoncera macana,\nAsí me dijo mi negra,\nPor decir: ¡Hasta mañana!",3,1,0,50,"",0,4,"aa",4,0,-1,0,562,562,"2734","",0,"","","",1,0,0,[],""],["carrizo_salta-n2735-01",3,"A la cárcel me llevaron,\nPorque dí una puñalada,\nCuando a mí me dejó solo,\nLa justicia no hizo nada.",3,1,0,50,"",0,4,"aa",49,0,-1,0,562,562,"2735","",0,"","","",1,0,0,[],""],["carrizo_salta-n2736-01",3,"Aloja no hi de tomar,\nAunque el dablo cante misa,\nAguardiente tomo yo,\nAunque no tenga camisa.",3,1,0,50,"",0,4,"ia",68,0,-1,0,562,562,"2736","",0,"","","",1,0,0,[],""],["carrizo_salta-n2737-01",3,"Al pobrecito i fulano,\nDelén duro, delén fuerte,\nMetanlé balas al pecho,\nEsa es su maldita suerte.",3,1,0,50,"",0,4,"ee",134,0,-1,0,562,562,"2737","",0,"","","",1,0,0,[],""],["carrizo_salta-n2738-01",3,"Allá viene mi vidita,\nComo prenda sin valor,\nUn pajarito en la rama,\nCantaba al ver esa flor.",3,1,0,50,"",0,4,"o",72,0,-1,0,562,562,"2738","",0,"","","",2,0,0,[],""],["carrizo_salta-n2739-01",3,"A mí me gusta cantar,\nCon hombres de barba llena,\nPa agarrarlo de las barbas,\nRamiando como cadena.",3,1,0,50,"",0,4,"ea",59,0,-1,0,562,562,"2739","",0,"","","",2,0,0,[],""],["carrizo_salta-n2740-01",3,"A mí me gusta cortar,\nCollera de cuero fresco,\nSiendo que la prenda quiera,\nAunque el dueño me haga gesto.",3,1,0,50,"",0,4,"eo",-1,0,-1,0,562,562,"2740","",0,"","","",1,0,0,[],""],["carrizo_salta-n2741-01",3,"A mí me gusta querer,\nLa mujer que es descarada,\nPorque el amor no pregunta,\nSi es soltera o si es casada.",3,1,0,50,"",0,4,"aa",49,0,-1,0,562,562,"2741","",0,"","","",2,0,0,[],""],["carrizo_salta-n2742-01",3,"A mí me gusta querer,\nQuerer al que no me quiere,\nY mostrarle malos modos,\nAl que voluntad me tiene.",3,1,0,50,"",0,4,"ee",-1,0,-1,0,562,562,"2742","",0,"","","",2,0,0,[],""],["carrizo_salta-n2743-01",3,"A mí me quieren hacer,\nLa carne del matadero,\nSi con otros se disgustan,\nYo hi de ser el pegadero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,563,563,"2743","",0,"","","",1,0,0,[],""],["carrizo_salta-n2743-a-01",3,"Todos hacen lo que quieren,\nComo carne i matadero,\nOtros tienen los delitos,\nY yo soy el pegadero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,563,563,"2743-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2744-01",3,"A nadies le debo nada,\nSino al traidor la venganza,\nA Dios le debo la vida,\nY a mi madre la crianza.",3,1,0,50,"",0,4,"aa",163,0,-1,0,563,563,"2744","",0,"","","",1,0,0,[],""],["carrizo_salta-n2744-a-01",3,"Yo no debo medio a nadie,\nTan sólo a vos la venganza,\nA Dios le debo la vida,\nY a mi madre la crianza.",3,1,0,50,"",0,4,"aa",163,0,-1,0,563,563,"2744-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2745-01",3,"Andá decile a tu dueño,\nMala traza como vos,\nQue te goce y te regoce,\nSobras que hi dejado yo.",3,1,0,50,"",0,4,"o",-1,0,-1,0,563,563,"2745","",0,"","","",1,0,0,[],""],["carrizo_salta-n2746-01",3,"Antinoche jugué al truco,\nCon un negro jugador,\nVuelta a vuelta flor y truco,\nAy, qué negro ligador.",3,1,0,50,"",1,4,"o",72,0,-1,0,563,563,"2746","",0,"","","",1,0,0,[],""],["carrizo_salta-n2747-01",3,"Apenas soy fulanito,\nNombre que nunca se pierde,\nAunque lo tiren al mar,\nSobre las espumas vuelve.",3,1,0,50,"",0,4,"ee",-1,0,-1,0,563,563,"2747","",0,"","","",2,0,0,[],""],["carrizo_salta-n2748-01",3,"Apenitas soy mocito,\nOjotita doble suela,\nPero pa tener una h e m...,\nSoy más gaucho que mi agüela.",3,1,0,50,"",0,4,"ea",167,0,-1,0,563,563,"2748","",0,"","","",1,0,0,[],""],["carrizo_salta-n2749-01",3,"Aquel que se meta a malo,\nConmigo la h' i sacar mal,\nLo haré pagar las ofensas,\nCon la hoja de mi puñal.",3,1,0,50,"",0,4,"a",1,0,-1,0,563,563,"2749","",0,"","","",1,0,0,[],""],["carrizo_salta-n2750-01",3,"A querer nadie me gana,\nNi les conozco ventaja,\nSólo en la dicha me ganan,\nPorque soy de suerte baja.",3,1,0,50,"",0,4,"aa",-1,0,-1,0,563,563,"2750","",0,"","","",1,0,0,[],""],["carrizo_salta-n2751-01",3,"Aquí está este pobre gaucho,\nMe han hecho lo que han querido,\nY si no me han hecho más,\nSerá porque no han podido.",3,1,0,50,"",0,4,"io",101,0,-1,0,563,563,"2751","",0,"","","",1,0,0,[],""],["carrizo_salta-n2752-01",3,"Aquí está sólo mi nombre,\nEn este baile reinando,\nY yo quisiera un mocito,\nQue se venga relanciando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,563,563,"2752","",0,"","","",1,0,0,[],""],["carrizo_salta-n2753-01",3,"Aquí tengo mi caballo,\n¿Quién me lo quiere correr?\nA las tres cuadras les corro,\nPero para ir y volver.",3,1,0,50,"",0,4,"e",20,0,-1,0,563,563,"2753","",0,"","","",1,0,0,[],""],["carrizo_salta-n2754-01",3,"Aquí voy a terminar,\nPorque se me acaba el trago,\nVoy a subir a caballo,\nPara puntiar a mi pago.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,563,563,"2754","",0,"","","",1,0,0,[],""],["carrizo_salta-n2755-01",3,"Arbolito gajo a gajo,\nQuerer con dueño es trabajo,\nSabiendo que tiene dueño,\nMe cuido de un por si acaso.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,564,564,"2755","",0,"","","",1,0,0,[],""],["carrizo_salta-n2756-01",3,"Arrastro la punta el poncho,\nA ver si alguno lo pisa,\nPor comprar una camorra,\nCasi vendo mi camisa.",3,1,0,50,"",0,4,"ia",68,0,-1,0,564,564,"2756","",0,"","","",1,0,0,[],""],["carrizo_salta-n2757-01",3,"¡Arriba, caballo moro!\nSacame del arenal,\nQue me vienen persiguiendo,\nNo me vayan a matar.",3,1,0,50,"",0,4,"a",-1,0,-1,0,564,564,"2757","",0,"","","",6,0,0,[],""],["carrizo_salta-n2758-01",3,"Aunque encerrada te tengan,\nY no te dejen salir,\nYo hi de ver modo de hablarte,\nCuando se me antoje a mí.",3,1,0,50,"",0,4,"i",-1,0,-1,0,564,564,"2758","",0,"","","",1,0,0,[],""],["carrizo_salta-n2759-01",3,"Aunque te anden mezquinando,\nY no te dejen salir,\nLas puertas se han de hacer calles,\nCuando se me antoje a mí.",3,1,0,50,"",0,4,"i",-1,0,-1,0,564,564,"2759","",0,"","","",1,0,0,[],""],["carrizo_salta-n2760-01",3,"Aunque todos me aborrezcan,\nEn este pago hi de andar,\nAl que le duela la muela,\nQue se la mande sacar.",3,1,0,50,"",0,4,"a",21,0,-1,0,564,564,"2760","",0,"","","",1,0,0,[],""],["carrizo_salta-n2761-01",3,"¡Ahijuna, ahijuna, me dicen!\n¡Ahijuna, ahijuna hi de ser!\nPa querer prenda con dueño,\nSoy como mandado a hacer.",3,1,0,50,"",3,4,"e",20,0,-1,0,564,564,"2761","",0,"","","",1,0,0,[],""],["carrizo_salta-n2762-01",3,"¡Ahijuna junando!\nDijo una perdiz volando,\nYo como mocito gaucho,\nMe la hice sonar boliando.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,564,564,"2762","",0,"","","",1,0,0,[],""],["carrizo_salta-n2763-01",3,"¡Ahijuna, puta la vieja!\nQue no me deja querer,\nCuando oye decir vidala,\nNi la puerta me hace ver.",3,1,0,50,"",0,4,"e",20,0,-1,0,564,564,"2763","",0,"","","",1,0,0,[],""],["carrizo_salta-n2764-01",3,"¡Ay, mi querido fulano!\nNo se quiera ponderar,\nSiendo la distancia larga,\nNi el trote le ha de quedar.",3,1,0,50,"",0,4,"a",21,0,-1,0,564,564,"2764","",0,"","","",2,0,0,[],""],["carrizo_salta-n2765-01",3,"¡Ay, tananita, ay tanana!\n¿Qué dirán de mí mañana?\nQue digan que me aborrecen,\nA mí no se me da nada.",3,1,0,50,"",0,4,"aa",-1,0,-1,0,564,564,"2765","",0,"","","",1,0,0,[],""],["carrizo_salta-n2766-01",3,"Botellas y damajuanas,\nSi me muero, han de sentir,\nY no habrá nadie en el mundo,\nQue se conduela de mí.",3,1,0,50,"",0,4,"i",-1,0,-1,0,564,564,"2766","",0,"","","",1,0,0,[],""],["carrizo_salta-n2767-01",3,"Buena noticia he tenido,\nQue tienes a quien querer,\nAndando me has de pagar,\nLas hechas y por hacer.",3,1,0,50,"",0,4,"e",20,0,-1,0,565,565,"2767","",0,"","","",1,0,0,[],""],["carrizo_salta-n2768-01",3,"¡Caballero de fulano!\nTome esta copa de vino,\nCuando sea cerquita el día,\nLe hi de mostrar el camino.",3,1,0,50,"",0,4,"io",199,0,-1,0,565,565,"2768","",0,"","","",36,0,0,[],""],["carrizo_salta-n2770-01",3,"¡Caramba con el amor!\nFuerte como el aguardiente,\nA los mudos hace hablar,\nY a los cobardes, valientes.",3,1,0,50,"",0,4,"ee",-1,0,-1,0,565,565,"2770","",0,"","","",1,0,0,[],""],["carrizo_salta-n2771-01",3,"¡Caramba, con las pedradas!\n¡Caramba, con los hachazos!\nAtajesé compañero,\nYo me atajo por si acaso.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,565,565,"2771","",0,"","","",1,0,0,[],""],["carrizo_salta-n2772-01",3,"¡Caramba, con la pedrada!\nCasi casi me ha pegado,\nComo soy mozo de vista,\nAl aire la hi barajado.",3,1,0,50,"",0,4,"ao",14,0,-1,0,565,565,"2772","",0,"","","",1,0,0,[],""],["carrizo_salta-n2773-01",3,"¡Caramba, que me hallo bien!\nA las tres horas del día,\nSi es que al diablo lo encontrara,\nCon él me examinaría.",3,1,0,50,"",0,4,"ia",0,0,-1,0,565,565,"2773","",0,"","","",1,0,0,[],""],["carrizo_salta-n2774-01",3,"¡Caramba, que me hallo viejo!\nY me están saliendo canas,\nToda la noche hi andado,\nTodavía me sobran ganas.",3,1,0,50,"",0,4,"aa",263,0,-1,0,565,565,"2774","",0,"","","",1,0,0,[],""],["carrizo_salta-n2775-01",3,"¡Cargad con pólvora roja,\nHermanos, vuestros cañones,\nQue con la amarilla y floja,\nNo hacen fuego los varones.",3,1,0,50,"",1,4,"oe",34,0,-1,0,565,565,"2775","",0,"","","",1,0,0,[],""],["carrizo_salta-n2776-01",3,"Carne quiero,\nGüeso no,\nConvídame un vaso i caña,\n¡Como no!",3,1,0,50,"",3,4,"o",-1,0,-1,0,565,565,"2776","",0,"","","",1,0,0,[],""],["carrizo_salta-n2777-01",3,"Casada soy, pero tengo,\nLibertad para querer,\nA la que sea de mi gusto,\nY a quien me parezca bien.",3,1,0,50,"",0,4,"e",-1,0,-1,0,565,565,"2777","",0,"","","",1,0,0,[],""],["carrizo_salta-n2778-01",3,"¡Cebame mate, mi vida!\nCebalo con yerba fuerte,\nAyer tarde m' hi venío,\nEscapando de la muerte.",3,1,0,50,"",0,4,"ee",134,0,-1,0,565,565,"2778","",0,"","","",1,0,0,[],""],["carrizo_salta-n2779-01",3,"Como me amenazan tanto,\nY echan cerrojo a la puerta,\nPor la reja de la huerta,\nVeo a flor de mi encanto.",3,1,0,50,"",11,4,"ao",30,0,-1,0,565,565,"2779","",0,"","","",1,0,0,[],""],["carrizo_salta-n2780-01",3,"Con un cigarrillo al alba,\nY un vasito de agua fría,\nSe desayuna un tunante,\nCuando anda en tunantería.",3,1,0,50,"",0,4,"ia",0,0,-1,0,565,565,"2780","",0,"","","",1,0,0,[],""],["carrizo_salta-n2781-01",3,"Cuando bajé de mi tierra,\nDe las peñas del Candado,\nMe leyeron la sentencia,\nDe morir afusilado.",3,1,0,50,"",0,4,"ao",14,0,-1,0,566,566,"2781","",0,"","","",1,0,0,[],""],["carrizo_salta-n2782-01",3,"Cuando caí a Pampa Grande,\nYo caí de domador,\nAunque no era muy ginete,\nEra medio salidor.",3,1,0,50,"",0,4,"o",72,0,-1,0,566,566,"2782","",0,"","","",1,0,0,[],""],["carrizo_salta-n2783-01",3,"Cuando me fuí destinado,\nTodos quedaron contentos,\nSe pusieron a cantar,\nComo frailes en convento.",3,1,0,50,"",0,4,"eo",-1,0,-1,0,566,566,"2783","",0,"","","",1,0,0,[],""],["carrizo_salta-n2784-01",3,"Cuando me fuí para abajo,\nNo me podía olvidar,\nSoy gajo de buena planta,\nNo me han de poder voltiar.",3,1,0,50,"",0,4,"a",21,0,-1,0,566,566,"2784","",0,"","","",4,0,0,[],""],["carrizo_salta-n2785-01",3,"Cuando oigo nombrar un guapo,\nQue es ligero y que es de vista,\nDoy plata pa conocerlo,\nPago pa que me resista.",3,1,0,50,"",0,4,"ia",352,0,-1,0,566,566,"2785","",0,"","","",2,0,0,[],""],["carrizo_salta-n2786-01",3,"Cuando oigo nombrar un guapo,\nSiento que se caen mis canas,\nDe viejo me andoy doblando,\nPero me suebran las ganas.",3,1,0,50,"",0,4,"aa",263,0,-1,0,566,566,"2786","",0,"","","",2,0,0,[],""],["carrizo_salta-n2787-01",3,"Cuando se muera Cardozo,\nCardozo han de querer ser,\nYo hi de dejar por escrito:\n—Eso es lo que no han de ver.",3,1,0,50,"",0,4,"e",20,0,-1,0,566,566,"2787","",0,"","","",2,0,0,[],""],["carrizo_salta-n2788-01",3,"Cuando se muera Cardozo,\nEnterrelón como a gente,\nCon los responsos cantados,\nMisa de cuerpo presente.",3,1,0,50,"",0,4,"ee",15,0,-1,0,566,566,"2788","",0,"","","",2,0,0,[],""],["carrizo_salta-n2789-01",3,"¡Cuidado con esa prenda!\nQue hace tiempo tiene dueño;\nNo hay primero sin segundo,\nDijo un gaucho santiagueño.",3,1,0,50,"",0,4,"eo",138,0,-1,0,566,566,"2789","",0,"","","",1,0,0,[],""],["carrizo_salta-n2790-01",3,"¡Chacarera, chacarera!\n¡Chacarera de la estrella!\nYo no te digo chanciando,\nEntregame la botella.",3,1,0,50,"",0,4,"ea",6,0,-1,0,566,566,"2790","",0,"","","",13,0,0,[],""],["carrizo_salta-n2791-01",3,"¡Chacarera, chacarera!\n¡Chacarera \"El Simbolar\"!,\nLa mujer que no me quiera,\nCon el juez la hi de obligar.",3,1,0,50,"",1,4,"a",21,0,-1,0,566,566,"2791","",0,"","","",13,0,0,[],""],["carrizo_salta-n2792-01",3,"Chicha linda y machadora,\nLa que vende ño Fulano,\nDicen que es santo remedio,\nPara matar el gusano.",3,1,0,50,"",0,4,"ao",81,0,-1,0,566,566,"2792","",0,"","","",1,0,0,[],""],["carrizo_salta-n2793-01",3,"¡Chiquitita, tortolita!\nYo me quisiera ir con vos,\nNo me han de privar los santos,\nY hemos de vivir los dos.",3,1,0,50,"",0,4,"o",87,0,-1,0,566,566,"2793","",0,"","","",1,0,0,[],""],["carrizo_salta-n2794-01",3,"Dame un jarrito de aloja,\nQue me estoy amejorando,\nCon el mismo licor sana,\nEl que se enferma tomando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,566,566,"2794","",0,"","","",1,0,0,[],""],["carrizo_salta-n2795-01",3,"De abajo viene lloviendo,\nEl mundo viene temblando,\nEsos son los pasos míos,\nY recién vengo llegando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,567,567,"2795","",0,"","","",3,0,0,[],""],["carrizo_salta-n2795-a-01",3,"De abajo viene lloviendo,\nEl mundo viene temblando,\n¿Qué le pasa al pobre mozo,\nQue recién viene llegando?",3,1,0,50,"",0,4,"ao",33,0,-1,0,567,567,"2795-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n2796-01",3,"¿De ande salís buena alhaja,\nCon tus espuelitas motas?\nDe allá has venido con botas,\nDe aquí te has de ir con ojota.",3,1,0,50,"",0,4,"oa",-1,0,-1,0,567,567,"2796","",0,"","","",2,0,0,[],""],["carrizo_salta-n2797-01",3,"¿De ande salís, buena alhaja,\nDe noche solo a los bailes?,\nSólo, tus rastros padecen,\nDebajo del mal msá grande.",3,1,0,50,"",0,4,"ae",-1,0,-1,0,567,567,"2797","",0,"","","",2,0,0,[],""],["carrizo_salta-n2798-01",3,"Debo y no quiero pagar,\nMi gusto es andas, debiendo,\nEn la plaza me han cobrado,\nA la orilla voy saliendo.",3,1,0,50,"",0,4,"eo",52,0,-1,0,567,567,"2798","",0,"","","",1,0,0,[],""],["carrizo_salta-n2798-a-01",3,"De la plaza me han corrido,\nPa l'orilla voy saliendo,\nTengo y no quiero pagar,\nMi gusto es andar debiendo.",3,1,0,50,"",0,4,"eo",52,0,-1,0,567,567,"2798-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2798-b-01",3,"Cuando salí de la iglesia,\nEn la plaza me han cobrado,\nTengo y no quiero pagar,\nQue me gusta ser regado.",3,1,0,50,"",0,4,"ao",14,0,-1,0,567,567,"2798-b","",0,"","","",1,0,0,[],""],["carrizo_salta-n2799-01",3,"De este filo, al otro filo,\nYo soy como gallo giro,\nSalgo, salto, doy un grito,\nY lueguito me retiro.",3,1,0,50,"",0,4,"io",-1,0,-1,0,567,567,"2799","",0,"","","",1,0,0,[],""],["carrizo_salta-n2800-01",3,"De la falda de aquel cerro,\nBajó un toro retuzando,\nComo yo era tan gauchito,\nLe daba un grito cantando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,567,567,"2800","",0,"","","",2,0,0,[],""],["carrizo_salta-n2801-01",3,"De los trabajos del mundo,\nYo no sé cuál es mejor,\nEl casarse o el morirse,\nO ser soldao como yo.",3,1,0,50,"",0,4,"o",-1,0,-1,0,567,567,"2801","",0,"","","",2,0,0,[],""],["carrizo_salta-n2802-01",3,"Del trigo se hizo la harina,\nDe la harina se hizo el bollo,\nSi le gusta, caballero,\nEchelé un gallo a este pollo.",3,1,0,50,"",0,4,"oo",448,0,-1,0,567,567,"2802","",0,"","","",1,0,0,[],""],["carrizo_salta-n2803-01",3,"Desde la Rioja hi venío,\nDesde la Rioja al Rosario,\nQuereme bien con firmeza,\nQue no sepa el comisario.",3,1,0,50,"",0,4,"ao",25,0,-1,0,567,567,"2803","",0,"","","",1,0,0,[],""],["carrizo_salta-n2805-01",3,"¡Despacito por las piedras!\nNo se vaya a resfalar,\nPor que el golpe de las piedras,\nCuesta mucho pa sanar.",3,1,0,50,"",1,4,"a",21,0,-1,0,567,567,"2805","",0,"","","",2,0,0,[],""],["carrizo_salta-n2806-01",3,"De viejo estoy hecho astillas,\nEntrando al fuego hi de arder,\nHi de arder dentro del mundo,\nSin dar el brazo a torcer.",3,1,0,50,"",0,4,"e",20,0,-1,0,567,567,"2806","",0,"","","",1,0,0,[],""],["carrizo_salta-n2807-01",3,"¿Diande ha venido este gaucho,\nCon su chura en medio el monte?\nDe vos hi de hacer corona,\nDe tu chura guardamonte.",3,1,0,50,"",0,4,"oe",325,0,-1,0,568,568,"2807","",0,"","","",1,0,0,[],""],["carrizo_salta-n2808-01",3,"Dicen que me han de privar,\nNo sé si me privarán,\nPrivarme ya no han podido,\nAhora menos podrán.",3,1,0,50,"",0,4,"a",147,0,-1,0,568,568,"2808","",0,"","","",1,0,0,[],""],["carrizo_salta-n2809-01",3,"Dicen que me vas a dar,\nHachazos y puñaladas,\nEso será si yo quiero,\nY si a mi cuerpo le agrada.",3,1,0,50,"",0,4,"aa",-1,0,-1,0,568,568,"2809","",0,"","","",1,0,0,[],""],["carrizo_salta-n2810-01",3,"Echelén más leña al fuego,\nQue se haga la llamarada,\nA mí no me asustan gritos,\nDe gauchos con compadradas.",3,1,0,50,"",0,4,"aa",-1,0,-1,0,568,568,"2810","",0,"","","",1,0,0,[],""],["carrizo_salta-n2811-01",3,"¡Eche una copa de vino!\nAvisemé cuánto vale,\nComo soy mozo tunante,\nNo pido nada de balde.",3,1,0,50,"",0,4,"ae",-1,0,-1,0,568,568,"2811","",0,"","","",1,0,0,[],""],["carrizo_salta-n2812-01",3,"El andar tan despilchao,\nNingún mérito me quita,\nSoy un pastel con reyeno,\nY parezco torta frita.",3,1,0,50,"",0,4,"ia",50,0,-1,0,568,568,"2812","",0,"","","",1,0,0,[],""],["carrizo_salta-n2813-01",3,"El anillo que me distes,\nLo largué en el mar profundo,\nNo te has de casar con nadie,\nMientras yo viva en el mundo.",3,1,0,50,"",0,4,"uo",179,0,-1,0,568,568,"2813","",0,"","","",2,0,0,[],""],["carrizo_salta-n2814-01",3,"El comisario y el juez,\nMe trataron de cuatrero,\nDecían que yo les robaba,\nBueyes, vacas y terneros.",3,1,0,50,"",0,4,"eo",-1,0,-1,0,568,568,"2814","",0,"","","",1,0,0,[],""],["carrizo_salta-n2815-01",3,"El cuerpo lleno de espinas,\nCorazón en confusión,\nY si no llueve esta noche,\nMe caigo en la procesión.",3,1,0,50,"",0,4,"o",31,0,-1,0,568,568,"2815","",0,"","","",1,0,0,[],""],["carrizo_salta-n2816-01",3,"El gaucho pide una copa,\nPreguntando cuánto vale,\nCon la cartera en las manos,\nContando los nacionales.",3,1,0,50,"",0,4,"ae",-1,0,-1,0,568,568,"2816","",0,"","","",1,0,0,[],""],["carrizo_salta-n2817-01",3,"El hombre para ser hombre,\nDiez hembras ha de tener,\nNueve para suplifalta,\nUna pa permanecer.",3,1,0,50,"",0,4,"e",20,0,-1,0,568,568,"2817","",0,"","","",7,0,0,[],""],["carrizo_salta-n2818-01",3,"El hombre para ser hombre,\nTres cosas debe tener:\nBuen caballo, buen apero,\nY una china a quien querer.",3,1,0,50,"",0,4,"e",20,0,-1,0,568,568,"2818","",0,"","","",7,0,0,[],""],["carrizo_salta-n2819-01",3,"El Miércoles me apresaron,\nEl Jueves me deserté,\nEl Viernes topé con ella,\nSábado la dijuntié.",3,1,0,50,"",0,4,"e",77,0,-1,0,568,568,"2819","",0,"","","",1,0,0,[],""],["carrizo_salta-n2820-01",3,"El otro día de mañana,\nFué mi madre y me halló preso,\nPegó un suspiro y me dijo:\n—¡Ahí has de entregar tus güesos!",3,1,0,50,"",0,4,"eo",-1,0,-1,0,568,568,"2820","",0,"","","",1,0,0,[],""],["carrizo_salta-n2821-01",3,"En el puesto \"El Porvenir\",\nJuran que me han de matar,\nNo sé qué les habrán dicho,\nQue me quieren fusilar.",3,1,0,50,"",0,4,"a",21,0,-1,0,569,569,"2821","",0,"","","",1,0,0,[],""],["carrizo_salta-n2822-01",3,"Enfermo estoy en la cama,\nCon un dolor en el brazo,\nY me han dado de receta,\nLa botella con el vaso.",3,1,0,50,"",0,4,"ao",145,0,-1,0,569,569,"2822","",0,"","","",3,0,0,[],""],["carrizo_salta-n2823-01",3,"En la cima de aquel cerro,\nHay una piedra verdosa,\nCon un letrero que dice:\n—¡Viva San Juan y Mendoza!",3,1,0,50,"",0,4,"oa",195,0,-1,0,569,569,"2823","",0,"","","",1,0,0,[],""],["carrizo_salta-n2824-01",3,"En la falda de aquel cerro,\nPonga la mesa y juguemos,\nMeta la mano al bolsillo,\nSaque un cigarro y fumemos.",3,1,0,50,"",0,4,"eo",127,0,-1,0,569,569,"2824","",0,"","","",54,0,0,[],""],["carrizo_salta-n2825-01",3,"En la falda de aquel cerro,\nTengo una planta de fruta,\nLos carozos por el suelo,\n¡Contestá juna gran puta!",3,1,0,50,"",0,4,"ua",197,0,-1,0,569,569,"2825","",0,"","","",54,0,0,[],""],["carrizo_salta-n2825-a-01",3,"En la plaza de Atacama,\nAlguna cosa juguemos,\nMeta la mano al bolsillo,\nSaque la plata y contemos.",3,1,0,50,"",0,4,"eo",127,0,-1,0,569,569,"2825-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2826-01",3,"En la punta de mi fierro,\nTraigo un poquito de acero,\nPara taparle la boca,\nA este gaucho brasilero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,569,569,"2826","",0,"","","",1,0,0,[],""],["carrizo_salta-n2827-01",3,"En los jardines de Diana,\nCorté una rosa en botón,\nConservate siempre pura,\nSi te querís llamar flor.",3,1,0,50,"",0,4,"o",-1,0,-1,0,569,569,"2827","",0,"","","",1,0,0,[],""],["carrizo_salta-n2828-01",3,"En los tientos de mi apero,\nTengo una longa graniada,\nPa atar palo con pescuezo,\nA la hembra más retobada.",3,1,0,50,"",0,4,"aa",49,0,-1,0,569,569,"2828","",0,"","","",1,0,0,[],""],["carrizo_salta-n2829-01",3,"En mi pago tengo menta,\nPa la taba y pa enlazar,\nPa peliar y pa domar,\nPa cantar y pa bailar.",3,1,0,50,"",0,4,"a",21,0,-1,0,569,569,"2829","",0,"","","",1,0,0,[],""],["carrizo_salta-n2830-01",3,"En mis tiempos cuando mozo,\nTenía tres y tenía cuatro,\nPero las hacía comer,\nComo hermanas en un plato.",3,1,0,50,"",3,4,"ao",-1,0,-1,0,569,569,"2830","",0,"","","",6,0,0,[],""],["carrizo_salta-n2831-01",3,"En un profundo letargo,\nRestaura la vida un triste,\nAquel que penando vive,\nSólo cuando bebe existe.",3,1,0,50,"",0,4,"ie",-1,0,-1,0,569,569,"2831","",0,"","","",1,0,0,[],""],["carrizo_salta-n2832-01",3,"¡Envido, envido mi falta!\nNo hay duda que tengo flor,\nCon las tres cartas que tengo,\nJuego como picaflor.",3,1,0,50,"",0,4,"o",72,0,-1,0,569,569,"2832","",0,"","","",2,0,0,[],""],["carrizo_salta-n2832-a-01",3,"¡Envido, envido mi falta!\nNo hay duda que tengo flor,\nEnvido por las tres cartas,\nY al truco juego mejor.",3,1,0,50,"",0,4,"o",72,0,-1,0,569,569,"2832-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n2833-01",3,"Es lindo para cantar,\nEn una casa decente,\nUna botella con vino,\nVarios vasos de aguardiente.",3,1,0,50,"",0,4,"ee",15,0,-1,0,570,570,"2833","",0,"","","",1,0,0,[],""],["carrizo_salta-n2834-01",3,"Estando con mi arriador,\nDoy doble contra sencillo,\nQue sepan qué gusto tiene,\nLa cáscara de novillo.",3,1,0,50,"",0,4,"io",228,0,-1,0,570,570,"2834","",0,"","","",1,0,0,[],""],["carrizo_salta-n2835-01",3,"Este es el remate nuevo,\nSacao de Santo Domingo,\nAquí estoy con la vidita,\n¿Qué quieren hacer conmigo?",3,1,0,50,"",0,4,"io",-1,0,-1,0,570,570,"2835","",0,"","","",12,0,0,[],""],["carrizo_salta-n2836-01",3,"Hoy no se fía,\nMañana sí,\nTrampas afuera,\nMenos aquí.",3,1,0,50,"",6,4,"i",23,0,-1,0,570,570,"2836","",0,"","","",1,0,0,[],""],["carrizo_salta-n2837-01",3,"La caña se llama caña,\nYo me llamo tomaré,\nCuando se acabe la caña,\nYo también me acabaré.",3,1,0,50,"",1,4,"e",77,0,-1,0,570,570,"2837","",0,"","","",1,0,0,[],""],["carrizo_salta-n2838-01",3,"La chicha es buena bebida,\nY el vino mucho mejor,\nLos barriles de aguardiente,\nMe inclinan el corazón.",3,1,0,50,"",0,4,"o",-1,0,-1,0,570,570,"2838","",0,"","","",1,0,0,[],""],["carrizo_salta-n2839-01",3,"La hi de llevar y mi d' ir,\nCon el tanto han de quedar,\nLos que me tengan envidia,\nVerán, qué han de remediar.",3,1,0,50,"",0,4,"a",21,0,-1,0,570,570,"2839","",0,"","","",1,0,0,[],""],["carrizo_salta-n2840-01",3,"La paja tiene su grano,\nEl cardo tiene su flor.\nLinda pluma el picaflor,\nYo desgraciao pa'l amor.",3,1,0,50,"",0,4,"o",72,0,-1,0,570,570,"2840","",0,"","","",1,0,0,[],""],["carrizo_salta-n2841-01",3,"La rama tiene su espina,\nY el cardón tiene su flor,\nYo también tengo mi amor,\nPara gozarlo mejor.",3,1,0,50,"",0,4,"o",72,0,-1,0,570,570,"2841","",0,"","","",1,0,0,[],""],["carrizo_salta-n2842-01",3,"Largate como a comerme,\nHaciendo cuerpo de gato,\nAquí te vas a juntar,\nCon la horma de tu zapato.",3,1,0,50,"",0,4,"ao",19,0,-1,0,570,570,"2842","",0,"","","",1,0,0,[],""],["carrizo_salta-n2843-01",3,"Las estrellas en el cielo,\nCaminan Jueves y Viernes,\n¿Cómo las hi seguir yo,\nSi tengo quien me gobierne?",3,1,0,50,"",0,4,"ee",-1,0,-1,0,570,570,"2843","",0,"","","",18,0,0,[],""],["carrizo_salta-n2844-01",3,"Le tengo dicho a mi vida,\nSi me llegan a encerrar,\nQue sufra y tenga paciencia,\nQue no me quiera olvidar.",3,1,0,50,"",0,4,"a",21,0,-1,0,570,570,"2844","",0,"","","",1,0,0,[],""],["carrizo_salta-n2845-01",3,"Los que hablan detrás de mí,\nHablarán por envidiosos,\nYo les voy a sacar cosas,\nPor tontos y mentirosos.",3,1,0,50,"",0,4,"oo",186,0,-1,0,571,571,"2845","",0,"","","",1,0,0,[],""],["carrizo_salta-n2846-01",3,"Machadito con la chicha,\nSolito me voy cantando;\nY si la beso a mi china,\nMachadito voy quedando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,571,571,"2846","",0,"","","",1,0,0,[],""],["carrizo_salta-n2847-01",3,"Me acuerdo de la carrera,\nEn la cancha de \"El Sauzal\",\nCuando corrió el añapero,\nCon el tostao alazán.",3,1,0,50,"",0,4,"a",-1,0,-1,0,571,571,"2847","",0,"","","",1,0,0,[],""],["carrizo_salta-n2848-01",3,"Me acuso mi padre santo,\nDe mi pecado menor,\nQue degollé una monjita,\nEncima el altar mayor.",3,1,0,50,"",0,4,"o",72,0,-1,0,571,571,"2848","",0,"","","",1,0,0,[],""],["carrizo_salta-n2849-01",3,"Me alzaron de las gallinas,\nPara llevarme a peliar,\nComo era gallito guapo,\nNo me pudieron ganar.",3,1,0,50,"",0,4,"a",21,0,-1,0,571,571,"2849","",0,"","","",1,0,0,[],""],["carrizo_salta-n2850-01",3,"Me dicen que tenis dueño,\nAsí con dueño te quiero,\nComo soy mozo tunante,\nMe gusta querer lo ajeno.",3,1,0,50,"",0,4,"eo",-1,0,-1,0,571,571,"2850","",0,"","","",1,0,0,[],""],["carrizo_salta-n2851-01",3,"Me gusta cortar las guindas,\nCuando ya están madurando,\nMe gusta querer lo ajeno,\nCuando el dueño está mirando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,571,571,"2851","",0,"","","",1,0,0,[],""],["carrizo_salta-n2852-01",3,"Me gusta el alcohol en jarro,\nY la chicha en la botella,\nMás me gusta la pulpera,\nQuisiera dormir con ella.",3,1,0,50,"",0,4,"ea",-1,0,-1,0,571,571,"2852","",0,"","","",1,0,0,[],""],["carrizo_salta-n2853-01",3,"Me gusta en medio del monte,\nCorrer el toro orejano,\nQue no conozca la casa,\nNí ha visto nunca un cristiano.",3,1,0,50,"",0,4,"ao",81,0,-1,0,571,571,"2853","",0,"","","",1,0,0,[],""],["carrizo_salta-n2854-01",3,"Me gusta la mujer grande,\nTambién la niña doncella,\nMe gusta la chicha en vaso,\nY el aguardiente en botella.",3,1,0,50,"",0,4,"ea",6,0,-1,0,571,571,"2854","",0,"","","",1,0,0,[],""],["carrizo_salta-n2855-01",3,"Me gustan los batallones,\nCuando marchan por escalas,\nMe gusta contar los muertos,\nCuando sosiegan las balas.",3,1,0,50,"",0,4,"aa",449,0,-1,0,571,571,"2855","",0,"","","",1,0,0,[],""],["carrizo_salta-n2856-01",3,"Me has de querer por tu gusto,\nO a la fuerza me has de amar,\nSi no me querís, vidita,\nTe tendré que travesiar.",3,1,0,50,"",0,4,"a",21,0,-1,0,571,571,"2856","",0,"","","",1,0,0,[],""],["carrizo_salta-n2857-01",3,"Me siento en el plan de un bajo,\nA llorar mi sentimiento,\nHago tiritar los pastos,\nComo si soplara el viento.",3,1,0,50,"",0,4,"eo",94,0,-1,0,571,571,"2857","",0,"","","",2,0,0,[],""],["carrizo_salta-n2858-01",3,"Métale frío y caliente,\nQue las penas son de amor,\nY si las viejas nos sienten,\nGanaremos un rincón.",3,1,0,50,"",0,4,"o",-1,0,-1,0,571,571,"2858","",0,"","","",1,0,0,[],""],["carrizo_salta-n2859-01",3,"Metalé sin descansar,\nAsí como a cuerpo ajeno,\nMientras más vueltas le dé,\nMás le ha de entrar el barreno.",3,1,0,50,"",0,4,"eo",76,0,-1,0,572,572,"2859","",0,"","","",1,0,0,[],""],["carrizo_salta-n2860-01",3,"Me tengo por buen jinete,\nAguanto las corcobiadas,\n¿Qué diría la vidita,\nSi le echara una ensillada?",3,1,0,50,"",0,4,"aa",-1,0,-1,0,572,572,"2860","",0,"","","",1,0,0,[],""],["carrizo_salta-n2861-01",3,"Mi gusto será cortar,\nNaranja que está pintando,\nAgrede la hi de querer,\nAunque la tengan cuidando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,572,572,"2861","",0,"","","",1,0,0,[],""],["carrizo_salta-n2862-01",3,"Mi viejo poncho rayao,\nEn el pago no flamea,\nPor un golpe de cuchillo,\n¡Pobre mi poncho tajiao!",3,1,0,50,"",5,4,"ao",98,0,-1,0,572,572,"2862","",0,"","","",1,0,0,[],""],["carrizo_salta-n2863-01",3,"Nací como nace el peje,\nEn el fondo de la mar,\nLa prenda que Dios me dió,\nNadies me la ha de quitar.",3,1,0,50,"",0,4,"a",21,0,-1,0,572,572,"2863","",0,"","","",2,0,0,[],""],["carrizo_salta-n2864-01",3,"¡Niña linda, dije yo!\nSi su madre me la diera,\nPara dormir esta noche,\nMañana se la volviera.",3,1,0,50,"",0,4,"ea",44,0,-1,0,572,572,"2864","",0,"","","",1,0,0,[],""],["carrizo_salta-n2865-01",3,"Noche oscura y tenebrosa,\nTempranito hi de venir,\nAsómate a la ventana,\nY tendrás con quién dormir.",3,1,0,50,"",0,4,"i",157,0,-1,0,572,572,"2865","",0,"","","",6,0,0,[],""],["carrizo_salta-n2866-01",3,"No es la primera vez\nQue me veo en apretura,\nUn pié pisando al estribo,\nY el otro en la sepultura.",3,1,0,50,"",0,4,"ua",17,0,-1,0,572,572,"2866","",0,"","","",1,0,0,[],""],["carrizo_salta-n2867-01",3,"No hay bagual que se haga el malo,\nTirándole un pial volcao,\nY no hay hombre que sea pavo,\nSi en el amor se ha golpiao.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,572,572,"2867","",0,"","","",1,0,0,[],""],["carrizo_salta-n2868-01",3,"No importa que no me quiera,\nNo me importa que padezca,\nNo importa perder la vida,\nCuando la ocasión se ofrezca.",3,1,0,50,"",0,4,"ea",346,0,-1,0,572,572,"2868","",0,"","","",1,0,0,[],""],["carrizo_salta-n2869-01",3,"No les aviso mi nombre,\nPor no ponerme en peligro,\nMi nombre se llama llanto,\nY mi apellido suspiro.",3,1,0,50,"",0,4,"io",-1,0,-1,0,572,572,"2869","",0,"","","",1,0,0,[],""],["carrizo_salta-n2869-a-01",3,"Yo no le digo mi nombre,\nPor no ponerme en peligro,\nPorque mi nombre es la pena,\nY mi apellido suspiro.",3,1,0,50,"",0,4,"io",-1,0,-1,0,572,572,"2869-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2870-01",3,"No sé de qué peña soy,\nTal vez sea pedernal,\n¿O seré de oro macizo,\nQue no me pueden sellar?",3,1,0,50,"",0,4,"a",-1,0,-1,0,572,572,"2870","",0,"","","",1,0,0,[],""],["carrizo_salta-n2871-01",3,"No soy paisano de acá,\nSoy paisano forastero,\nQue caigo en este entrevero,\nPor una casualidad.",3,1,0,50,"",5,4,"a",-1,0,-1,0,573,573,"2871","",0,"","","",1,0,0,[],""],["carrizo_salta-n2871-01-e2",3,"Yo no soy gaucho de aquí,\nYo soy gaucho forastero,\nYo no sé cómo hi llegado,\nEn medio de este entrevero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,573,573,"2871","",0,"","","",4,0,0,[],""],["carrizo_salta-n2872-01",3,"No tan pavo como Vd,\nAmigaso, se figura,\nParece que mi recao,\nLe ha apretao la matadura.",3,1,0,50,"",0,4,"ua",17,0,-1,0,573,573,"2872","",0,"","","",1,0,0,[],""],["carrizo_salta-n2873-01",3,"Nunca hi sido panadero,\nNi tampoco estibador,\nPero en cuanto me dispongo,\nSaco panes como flor.",3,1,0,50,"",0,4,"o",72,0,-1,0,573,573,"2873","",0,"","","",1,0,0,[],""],["carrizo_salta-n2874-01",3,"Oregiando una por una,\nLas cartas que me van dando,\nVeo que puedo ir cantando,\nAunque se pique: flor.",3,1,0,50,"",5,4,"o",-1,0,-1,0,573,573,"2874","",0,"","","",1,0,0,[],""],["carrizo_salta-n2875-01",3,"Pal carnaval, mis hermanas\nPreparaban los quesillos,\nMientras me esperaba el flete,\nQue afile bien mi cuchillo.",3,1,0,50,"",0,4,"io",-1,0,-1,0,573,573,"2875","",0,"","","",1,0,0,[],""],["carrizo_salta-n2876-01",3,"Pa lo que ha i ser la primera,\nQue cabecera me han hecho,\nY me levanto y me dicen:\nQue el olor le haga provecho.",3,1,0,50,"",0,4,"eo",60,0,-1,0,573,573,"2876","",0,"","","",1,0,0,[],""],["carrizo_salta-n2877-01",3,"¿Pa qué preguntas quién anda,\nSabiendo que hi de venir?\nHi agarrado por costumbre,\nDe no dejarte dormir.",3,1,0,50,"",0,4,"i",157,0,-1,0,573,573,"2877","",0,"","","",1,0,0,[],""],["carrizo_salta-n2878-01",3,"Para mí la cola es pecho,\nY el espinazo es cadera,\nEl gaucho que no me quiera,\nPara mí es la vinagrera.",3,1,0,50,"",0,4,"ea",44,0,-1,0,573,573,"2878","",0,"","","",2,0,0,[],""],["carrizo_salta-n2879-01",3,"Para mí todo es lo mismo,\nLo mismo me es diez que veinte,\nComo no hago mal a nadie,\nMe ha de respetar la gente.",3,1,0,50,"",0,4,"ee",-1,0,-1,0,573,573,"2879","",0,"","","",2,0,0,[],""],["carrizo_salta-n2880-01",3,"¡Para qué padre ni madre!\n¡Para qué cura ni alcalde!\nNadie me ha i privar mis gustos,\nElla me quiere y es grande.",3,1,0,50,"",0,4,"ae",-1,0,-1,0,573,573,"2880","",0,"","","",1,0,0,[],""],["carrizo_salta-n2881-01",3,"Por aquí me vua largar,\nPor esta fiera ladera,\nJuyeriando, juyeriando,\nCon la mano en la cadera.",3,1,0,50,"",0,4,"ea",44,0,-1,0,573,573,"2881","",0,"","","",1,0,0,[],""],["carrizo_salta-n2882-01",3,"Por ausente me han tenido,\nCuerra la voz qu' hi venío,\nA recordar a la prenda,\nQue con mi marca hi tenío.",3,1,0,50,"",0,4,"io",3,0,-1,0,573,573,"2882","",0,"","","",1,0,0,[],""],["carrizo_salta-n2883-01",3,"Por el año ochenta y uno,\nVenía Carlos Tejedor,\nPor chirliarle el c... a Roca,\nCon un gajo de esta flor.",3,1,0,50,"",0,4,"o",72,0,-1,0,574,574,"2883","",0,"","","",1,0,0,[],""],["carrizo_salta-n2885-01",3,"Porque me ven chiquitito,\nPensarán que soy borbojo,\n¿No sabrán oir decir,\nQue soy carta que no aflojo?",3,1,0,50,"",0,4,"oo",400,0,-1,0,574,574,"2885","",0,"","","",2,0,0,[],""],["carrizo_salta-n2886-01",3,"Quisiera toriar al toro,\nAtando el lazo al cinchero,\n¡Si se me cortara el lazo..\nMi caballo no es ligero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,574,574,"2886","",0,"","","",1,0,0,[],""],["carrizo_salta-n2887-01",3,"Reciencito estoy llegando,\nDe mi pago del Rosario,\nY ya no me está gustando,\nLa multa del comisario.",3,1,0,50,"",1,4,"ao",-1,0,-1,0,574,574,"2887","",0,"","","",1,0,0,[],""],["carrizo_salta-n2888-01",3,"¡Señores, pregunto a todos!\nDigo si han oído decir,\nDe que en las manos de un flojo,\nUn guapo viene a morir.",3,1,0,50,"",0,4,"i",157,0,-1,0,574,574,"2888","",0,"","","",1,0,0,[],""],["carrizo_salta-n2889-01",3,"Se tienen por mozos churos,\nCuando tienen dos o tres,\nYo le llamo churo y medio,\nCuando tiene nueve o diez.",3,1,0,50,"",0,4,"e",150,0,-1,0,574,574,"2889","",0,"","","",1,0,0,[],""],["carrizo_salta-n2890-01",3,"Si hubiera un gaucho ligero,\nLigero para el cuchillo,\nLe haría unos cuantos tiritos,\nPero en amistad de amigo.",3,1,0,50,"",0,4,"io",-1,0,-1,0,574,574,"2890","",0,"","","",1,0,0,[],""],["carrizo_salta-n2891-01",3,"Si quiere cantar, cantemos,\nSi quiere jugar, juguemos,\nAquí tengo plata blanca,\nSi quiere parar, paremos.",3,1,0,50,"",0,4,"eo",127,0,-1,0,574,574,"2891","",0,"","","",1,0,0,[],""],["carrizo_salta-n2892-01",3,"Si quiere cantar conmigo,\nHa de tener buena cuenta,\nQue en la mitad del camino,\nLe ajustaré las cuarenta.",3,1,0,50,"",0,4,"ea",229,0,-1,0,574,574,"2892","",0,"","","",1,0,0,[],""],["carrizo_salta-n2893-01",3,"Solamente un placer tengo,\nDe todos los mil placeres,\nAño por año me vengo,\nRemudando las mujeres.",3,1,0,50,"",1,4,"ee",55,0,-1,0,574,574,"2893","",0,"","","",1,0,0,[],""],["carrizo_salta-n2894-01",3,"Soy José Manuel Quiroga,\nTengo de indio y de mulato,\nAunque soy cejas topadas,\nPero soy limpio en mis tratos.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,574,574,"2894","",0,"","","",1,0,0,[],""],["carrizo_salta-n2895-01",3,"Soy mocitos de mis gustos,\nAunque mocito campero,\nY sé ensillar mi caballo,\nPara irme donde yo quiero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,575,575,"2895","",0,"","","",1,0,0,[],""],["carrizo_salta-n2896-01",3,"Soy pollo por que me arrollo,\nSoy gallo por que me callo,\nCuando toca la ocasión,\nSoy pollo, gallina y gallo.",3,1,0,50,"",0,4,"ao",102,0,-1,0,575,575,"2896","",0,"","","",1,0,0,[],""],["carrizo_salta-n2897-01",3,"Soy un gauchito bandido,\nSegún todo el mundo dice,\nLlevo mi poncho a la rastra,\nPa que nadie me lo pise.",3,1,0,50,"",0,4,"ie",224,0,-1,0,575,575,"2897","",0,"","","",1,0,0,[],""],["carrizo_salta-n2898-01",3,"Un pantalón de bombilla,\nUsaba don Salvador,\nUna levita muy corta,\nY en el ojal una flor.",3,1,0,50,"",0,4,"o",72,0,-1,0,575,575,"2898","",0,"","","",1,0,0,[],""],["carrizo_salta-n2899-01",3,"Un punto quisiera ver,\nQue lo desea mi fortuna,\nHasta agora no hi topado,\nQuién me baraje la pluma.",3,1,0,50,"",0,4,"ua",-1,0,-1,0,575,575,"2899","",0,"","","",1,0,0,[],""],["carrizo_salta-n2900-01",3,"Venite como a comerme,\nMedio arrugando la frente,\nHagamos unos tiritos,\nQue se divierta la gente.",3,1,0,50,"",0,4,"ee",15,0,-1,0,575,575,"2900","",0,"","","",1,0,0,[],""],["carrizo_salta-n2901-01",3,"Venite haciendo el malito,\nCreyendo que es una fija,\nTe voy a dejar la cara\nComo cuero i lagartija.",3,1,0,50,"",0,4,"ia",219,0,-1,0,575,575,"2901","",0,"","","",1,0,0,[],""],["carrizo_salta-n2902-01",3,"Voy a dentrar a la escuela,\nHaciendo todo valor,\nPorque yo no sé explicarme,\n¿Dónde ha salido esa flor?",3,1,0,50,"",0,4,"o",72,0,-1,0,575,575,"2902","",0,"","","",1,0,0,[],""],["carrizo_salta-n2903-01",3,"Ya me voy a retirar,\nPorque muy dueñito soy,\nA mí nadie me ha i privar,\nLa p.. que los p...",3,1,0,50,"",3,4,"",-1,0,-1,0,575,575,"2903","",0,"","","",12,0,0,[],""],["carrizo_salta-n2904-01",3,"Yo no le temo a la muerte,\nPorque sé que hi de morir,\nAunque sea tarde o temprano,\nLa muerte ha i venir por mí.",3,1,0,50,"",0,4,"i",-1,0,-1,0,575,575,"2904","",0,"","","",12,0,0,[],""],["carrizo_salta-n2905-01",3,"Yo no le temo al cuchillo,\nVenga de punta o de filo,\nAunque venga apareciendo,\nCon truenos y refucilos.",3,1,0,50,"",0,4,"io",-1,0,-1,0,575,575,"2905","",0,"","","",1,0,0,[],""],["carrizo_salta-n2906-01",3,"Yo no le temo al león,\nNi al tigre más fiero y malo,\nFrente a frente l' hi peliar,\nCon un perro y con un palo.",3,1,0,50,"",0,4,"ao",71,0,-1,0,575,575,"2906","",0,"","","",1,0,0,[],""],["carrizo_salta-n2907-01",3,"Yo no quiero ser soldado,\nLa guerra que me tiene loco,\nMi trabajo es demasiado,\nY el sueldo que gano es poco.",3,1,0,50,"",1,4,"oo",152,0,-1,0,575,575,"2907","",0,"","","",2,0,0,[],""],["carrizo_salta-n2908-01",3,"Yo no quiero ser soldado,\nYa mis servicios no valen,\nTambién el soldado merece,\nNo sólo los oficiales.",3,1,0,50,"",0,4,"ae",-1,0,-1,0,575,575,"2908","",0,"","","",2,0,0,[],""],["carrizo_salta-n2909-01",3,"Yo soy como el jugador,\nPierda o gane, me hace cuenta,\nEl que se cría con veneno,\nCon veneno se alimenta.",3,1,0,50,"",0,4,"ea",229,0,-1,0,576,576,"2909","",0,"","","",1,0,0,[],""],["carrizo_salta-n2909-02",3,"Yo soy como el pez en l'agua,\nQue vive en lo más profundo,\nTengo mi rancho en el monte,\nVivo contento del mundo.",3,1,0,50,"",0,4,"uo",179,0,-1,0,576,576,"2909","",0,"","","",1,0,0,[],""],["carrizo_salta-n2911-01",3,"Yo soy como el resertor,\nNo tengo casa ni rancho,\nNi un peso en el tirador,\nSoy más pobre que el carincho.",3,1,0,50,"",5,4,"io",-1,0,-1,0,576,576,"2911","",0,"","","",1,0,0,[],""],["carrizo_salta-n2912-01",3,"Yo soy como el río Pasaje,\nQue no entiende de, por Dios,\nAsí como llevo a una,\n¿Cómo no llevo a las dos?",3,1,0,50,"",0,4,"o",87,0,-1,0,576,576,"2912","",0,"","","",1,0,0,[],""],["carrizo_salta-n2913-01",3,"Yo soy como el temporal,\nQue salgo de otro lugar,\nTraigo unos toritos gordos,\nSin marcas y sin señal.",3,1,0,50,"",0,4,"a",-1,0,-1,0,576,576,"2913","",0,"","","",3,0,0,[],""],["carrizo_salta-n2914-01",3,"Yo soy como el tilo-tilo,\nHago que flechar no flecho,\nLo que digo con mis labios,\nLo sustento con el pecho.",3,1,0,50,"",0,4,"eo",60,0,-1,0,576,576,"2914","",0,"","","",1,0,0,[],""],["carrizo_salta-n2915-01",3,"Yo soy del barrio de arriba,\nDonde relumbra el acero,\nLo que digo con la boca,\nLo sustento con el cuero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,576,576,"2915","",0,"","","",1,0,0,[],""],["carrizo_salta-n2916-01",3,"Yo soy el toro más chico,\nTengo muesquita y varilla,\nYo no tengo miedo a nadie,\nNi aunque vengan en cuadrilla.",3,1,0,50,"",0,4,"ia",162,0,-1,0,576,576,"2916","",0,"","","",1,0,0,[],""],["carrizo_salta-n2917-01",3,"Yo soy ese gaucho malo,\nMe lo paso matreriando,\nPor eso la policía,\nDe mí vive preguntando.",3,1,0,50,"",0,4,"ao",33,0,-1,0,576,576,"2917","",0,"","","",1,0,0,[],""],["carrizo_salta-n2918-01",3,"Yo soy ese mozo malo,\nHijo de hombre saltiador,\nEn cada casa que llego,\nLlego con mala intención.",3,1,0,50,"",0,4,"o",-1,0,-1,0,576,576,"2918","",0,"","","",1,0,0,[],""],["carrizo_salta-n2919-01",3,"Yo soy ese pollo bueno,\nCosteado de Lecherones,\nEchandomé al reñidero,\nYo no respeto puyones.",3,1,0,50,"",0,4,"oe",34,0,-1,0,576,576,"2919","",0,"","","",1,0,0,[],""],["carrizo_salta-n2920-01",3,"Yo soy ese puesterito,\nDe aquellos primeros criollos,\nLo sé boliar al más listo,\nDe un pial con todo el rollo.",3,1,0,50,"",0,4,"oo",-1,0,-1,0,576,576,"2920","",0,"","","",2,0,0,[],""],["carrizo_salta-n2921-01",3,"Yo soy ese puesterito,\nDel puesto del \"Porvenir\",\nBagual que lo saco viendo,\n¡Qué putas que se me v' ir!",3,1,0,50,"",0,4,"i",157,0,-1,0,576,576,"2921","",0,"","","",2,0,0,[],""],["carrizo_salta-n2921-a-01",3,"Yo también era puestero,\nPuertero del \"Porvenir\",\nOrejano que me echaba,\n¡Putas que se me iba a ir!",3,1,0,50,"",0,4,"i",157,0,-1,0,576,576,"2921-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n2922-01",3,"Yo soy ese quebrachito,\nDe medio del Qebrachal,\nMe han metido fuego y hacha,\nY no me han podio voltiar.",3,1,0,50,"",0,4,"a",-1,0,-1,0,577,577,"2922","",0,"","","",2,0,0,[],""],["carrizo_salta-n2923-01",3,"Yo soy ese quebrachito,\nDe medio de la lomada,\nQue no me han de sacar leña,\nNi a hachazos me han de hacer nada.",3,1,0,50,"",0,4,"aa",49,0,-1,0,577,577,"2923","",0,"","","",2,0,0,[],""],["carrizo_salta-n2923-a-01",3,"Yo soy quebrachito tierno,\nDe medio del Quebrachal.\nAunque traigan fuego i hacha,\nNo me han de poder voltiar.",3,1,0,50,"",0,4,"a",-1,0,-1,0,577,577,"2923-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2924-01",3,"Yo soy ese toro bayo,\nCostillar de color plomo,\nCuando se aumentan los toros,\nMe echo tierra sobre el lomo.",3,1,0,50,"",0,4,"oo",-1,0,-1,0,577,577,"2924","",0,"","","",1,0,0,[],""],["carrizo_salta-n2924-a-01",3,"Yo soy un triste serrano,\nDe costillar color plomo,\nCuando oigo bramar un guapo,\nMe echo tierra sobre el lomo.",3,1,0,50,"",0,4,"oo",349,0,-1,0,577,577,"2924-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2925-01",3,"Yo soy ese toro bravo,\nQue bajo de las laderas,\nEn el balido que pego,\nJunto vacas y terneros.",3,1,0,50,"",5,4,"eo",-1,0,-1,0,577,577,"2925","",0,"","","",1,0,0,[],""],["carrizo_salta-n2926-01",3,"Yo soy ese toro bueno,\nDe la marca de los Sierra,\nComo no hallo quien me tope,\nAquí estoy cavando tierra.",3,1,0,50,"",0,4,"ea",80,0,-1,0,577,577,"2926","",0,"","","",2,0,0,[],""],["carrizo_salta-n2927-01",3,"Yo soy ese toro malo,\nDe la marca los Cardozos,\nAl que se tope conmigo,\nLe haré sonar el carozo.",3,1,0,50,"",0,4,"oo",-1,0,-1,0,577,577,"2927","",0,"","","",1,0,0,[],""],["carrizo_salta-n2928-01",3,"Yo soy ese toro nuevo,\nDe la loma \"El Cebilar\",\nCuatro toros hi corrio,\nToavía me hallo regular.",3,1,0,50,"",3,4,"a",21,0,-1,0,577,577,"2928","",0,"","","",1,0,0,[],""],["carrizo_salta-n2929-01",3,"Yo soy fulano de tal,\nNombre que me puso el cura,\nPa cantar con los varones,\nTengo la bolsa segura.",3,1,0,50,"",0,4,"ua",17,0,-1,0,577,577,"2929","",0,"","","",4,0,0,[],""],["carrizo_salta-n2930-01",3,"Yo soy gaucho para el campo,\nSoy gaucho pa un tiro i lazo,\nNo le temo a la estirada,\nComo le temo al guascazo.",3,1,0,50,"",0,4,"ao",43,0,-1,0,577,577,"2930","",0,"","","",1,0,0,[],""],["carrizo_salta-n2931-01",3,"Yo soy torito muy bueno,\nMarquita de don Juan Cueya,\nY donde bala este toro,\nTambera sale a la huella.",3,1,0,50,"",0,4,"ea",6,0,-1,0,577,577,"2931","",0,"","","",1,0,0,[],""],["carrizo_salta-n2932-01",3,"Yo soy torito bueno,\nCargo grillos y cadenas,\nEn las astas traigo fuerzas,\nY en el cogote la arena.",3,1,0,50,"",0,4,"ea",-1,0,-1,0,577,577,"2932","",0,"","","",1,0,0,[],""],["carrizo_salta-n2933-01",3,"Yo soy un torito bueno,\nNo hay árbol que no desgaje,\nEn las astas traigo fuerzas,\nY en el cogote coraje.",3,1,0,50,"",0,4,"ae",231,0,-1,0,577,577,"2933","",0,"","","",1,0,0,[],""],["carrizo_salta-n2934-01",3,"Yo también diré, señores,\nLo que dice el comisario,\nSi no cumple lo que digo,\nEcho encima mi caballo.",3,1,0,50,"",0,4,"ao",-1,0,-1,0,578,578,"2934","",0,"","","",1,0,0,[],""],["carrizo_salta-n2935-01",3,"Yo también voy a decir.\nLo que me dijo un arriero:\n—Ventajándole el tirón,\nNo hay animal pescuecero.",3,1,0,50,"",0,4,"eo",38,0,-1,0,578,578,"2935","",0,"","","",3,0,0,[],""],["carrizo_salta-n2936-01",3,"Yo tenía una vaquita,\nDe mi vaquita rosada,\nCuando sacaba la leche.\nDe chorros me la largaba.",3,1,0,50,"",0,4,"aa",-1,0,-1,0,578,578,"2936","",0,"","","",1,0,0,[],""],["carrizo_salta-n2937-01",3,"Agora que estamos juntos,\nUna pregunta le haré:\n—¿Cuántos pelo tiene un gato,\nCuando acaba de nacer?",3,1,0,51,"",0,4,"e",-1,0,-1,0,580,580,"2937","",0,"","","",1,0,0,[],""],["carrizo_salta-n2938-01",3,"Agua negra es del nogal,\nRosada la del socondo,\nAsí me enseñó a cantar,\nJosé Domingo Elizondo.",3,1,0,51,"",0,4,"oo",450,0,-1,0,580,580,"2938","",0,"","","",1,0,0,[],""],["carrizo_salta-n2938-a-01",3,"Blanca l'agua del romero,\nRosada la del socondo,\nAsí me enseñó a cantar,\nJosé Domingo Lizondo.",3,1,0,51,"",0,4,"oo",450,0,-1,0,580,580,"2938-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n2939-01",3,"A las perlas deje en paz,\nVd. no debe tocarlas,\nPorque sería capaz,\nPor dos pesos, empeñarlas.",3,1,0,51,"",1,4,"aa",451,0,-1,0,580,580,"2939","",0,"","","",1,0,0,[],""],["carrizo_salta-n2940-01",3,"Al cantor que se presente,\nQue tenga o no quien lo ampare,\nAunque su saber sea mucho,\nNo espere que yo dispare.",3,1,0,51,"",0,4,"ae",175,0,-1,0,580,580,"2940","",0,"","","",1,0,0,[],""],["carrizo_salta-n2941-01",3,"¡Amigo, si le parece,\nLe haré una pregunta suave!\n—¿Cómo se puede casar:\nUn hijo con una madre?",3,1,0,51,"",0,4,"ae",-1,0,-1,0,580,580,"2941","",0,"","","",1,0,0,[],""],["carrizo_salta-n2942-01",3,"A mí me toca la copla,\nA mí me toca soltar,\nAlegrías de mi pecho,\nYo les quisiera cantar.",3,1,0,51,"",0,4,"a",21,0,-1,0,580,580,"2942","",0,"","","",3,0,0,[],""],["carrizo_salta-n2943-01",3,"A mí me toca la copla,\nMiren qué casualidad,\nNo tengo más que esta unita,\nEn caso i necesidad.",3,1,0,51,"",0,4,"a",16,0,-1,0,580,580,"2943","",0,"","","",3,0,0,[],""],["carrizo_salta-n2943-a-01",3,"A mí me toca la copla,\nPa mayor casualidad.\nNo tengo más que imitar,\nEn caso i necesidad.",3,1,0,51,"",0,4,"a",-1,0,-1,0,580,580,"2943-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n2944-01",3,"Anoche comí una pera,\nY hoy amanecí con tos,\nPor eso es que estoy cantando,\nTan ronco y con mala voz.",3,1,0,51,"",0,4,"o",280,0,-1,0,580,580,"2944","",0,"","","",1,0,0,[],""],["carrizo_salta-n2945-01",3,"Anoche me confesé,\nCon el cura de la higuera,\nY me dió de penitencia,\nQue cante una chacarera.",3,1,0,51,"",0,4,"ea",-1,0,-1,0,580,580,"2945","",0,"","","",3,0,0,[],""],["carrizo_salta-n2947-01",3,"Apenitas voy saliendo,\nDe esta cuesta resfalosa,\nDirán que lis hi cantado,\nLas tonadas trabajosas.",3,1,0,51,"",0,4,"oa",-1,0,-1,0,580,580,"2947","",0,"","","",2,0,0,[],""],["carrizo_salta-n2948-01",3,"Aquel que me está mirando,\n¿Qué me estará reparando?\nY yo sin poder cantar,\nDe vergüenza estoy sudando.",3,1,0,51,"",0,4,"ao",33,0,-1,0,580,580,"2948","",0,"","","",1,0,0,[],""],["carrizo_salta-n2949-01",3,"Aquí me pongo a cantar,\nBajo de este corredor,\nA ver si puedo sacar\nL'alma de mi corazón.",3,1,0,51,"",0,4,"o",-1,0,-1,0,581,581,"2949","",0,"","","",18,0,0,[],""],["carrizo_salta-n2950-01",3,"Aquí me pongo a cantar,\nDebajito de este techo\nA ver si puedo sacar\nLa ronquera de mi pecho.",3,1,0,51,"",1,4,"eo",60,0,-1,0,581,581,"2950","",0,"","","",18,0,0,[],""],["carrizo_salta-n2951-01",3,"Aquí me pongo a cantar,\nDebajo de esta magnolia,\nA ver si puedo alcanzar,\nUn besito de mi novia.",3,1,0,51,"",0,4,"oa",-1,0,-1,0,581,581,"2951","",0,"","","",18,0,0,[],""],["carrizo_salta-n2952-01",3,"Aquí me pongo a cantar,\nDebajo de este algarrobo,\nPara contarles a Uds.\nLos corazones que robo.",3,1,0,51,"",0,4,"oo",452,0,-1,0,581,581,"2952","",0,"","","",18,0,0,[],""],["carrizo_salta-n2954-01",3,"Aquí me pongo a cantar,\nDebajo de este cardón,\nA ver si puedo sacar,\nAmor de tu corazón.",3,1,0,51,"",1,4,"o",31,0,-1,0,581,581,"2954","",0,"","","",18,0,0,[],""],["carrizo_salta-n2955-01",3,"Aquí me pongo a cantar,\nEn el alto de El Rosario,\n¡Caramba que tengo miedo\nA la multa el comisario!",3,1,0,51,"",0,4,"ao",25,0,-1,0,581,581,"2955","",0,"","","",18,0,0,[],""],["carrizo_salta-n2956-01",3,"Aquí me pongo a cantar,\nEncimita de este umbral,\nMe pongo a concertar coplas,\nPa cantar en Carnaval.",3,1,0,51,"",0,4,"a",1,0,-1,0,581,581,"2956","",0,"","","",18,0,0,[],""],["carrizo_salta-n2957-01",3,"Aquí me pongo, vidita,\nA cantar mi relancina,\nDe muerto y resucitado,\nVengo como golondrina.",3,1,0,51,"",0,4,"ia",11,0,-1,0,581,581,"2957","",0,"","","",1,0,0,[],""],["carrizo_salta-n2958-01",3,"Argumentaba un moreno,\nPor pretender una dama,\nComo era tan pretendiente,\nSe le aumentaba la fama.",3,1,0,51,"",0,4,"aa",90,0,-1,0,581,581,"2958","",0,"","","",1,0,0,[],""],["carrizo_salta-n2959-01",3,"¡Arrimesén a la rueda!\nComo trompos a la troya,\nOyerán explicación,\nA la modita i Corolla.",3,1,0,51,"",0,4,"oa",453,0,-1,0,581,581,"2959","",0,"","","",1,0,0,[],""],["carrizo_salta-n2960-01",3,"Atención pido al silencio,\nY al silencio la atención,\nOigan de esta torpe lengua,\nUna ruda explicación.",3,1,0,51,"",0,4,"o",31,0,-1,0,581,581,"2960","",0,"","","",2,0,0,[],""],["carrizo_salta-n2961-01",3,"Atienda mi compañero,\nUna pregunta le haré,\n¿A dónde quedan las nubes\nCuando acaba de llover?",3,1,0,51,"",0,4,"e",-1,0,-1,0,581,581,"2961","",0,"","","",1,0,0,[],""],["carrizo_salta-n2962-01",3,"Atravesada, sí,\n¡Lucero hermoso!\nDe qué me sirve verte\nSi no te gozo?",3,1,0,51,"",6,4,"oo",156,0,-1,0,581,581,"2962","",0,"","","",1,0,0,[],""],["carrizo_salta-n2963-01",3,"Aunque es poco mi saber,\nNo tengo estudio de nada,\nSoy una noche nublada,\nQue anuncia el amanecer.",3,1,0,51,"",11,4,"e",20,0,-1,0,581,581,"2963","",0,"","","",1,0,0,[],""],["carrizo_salta-n2964-01",3,"A ver si puedo,\nNo sé si podré,\nPues cuando es mucho el gauchaje,\nNo sé si explicar podré.",3,1,0,51,"",3,4,"e",-1,0,-1,0,581,581,"2964","",0,"","","",1,0,0,[],""],["carrizo_salta-n2965-01",3,"Ayer canté en Catamarca,\nHoy canto en \"Las Peñas Blancas\",\nQuien quiera cantar conmigo,\nQue dentre a la salamanca.",3,1,0,51,"",0,4,"aa",-1,0,-1,0,582,582,"2965","",0,"","","",1,0,0,[],""],["carrizo_salta-n2966-01",3,"Ayer canté en \"La Frontera\",\nHoy canto en Río las Piedras,\nTodito el mundo hi andao,\nSin que ninguna me quiera.",3,1,0,51,"",0,4,"ea",-1,0,-1,0,582,582,"2966","",0,"","","",1,0,0,[],""],["carrizo_salta-n2967-01",3,"Ayer canté en Los Horcones,\nHoy canto en la Piedra Blanca,\nPa que me ganen cantando,\nDentren a la salamanca.",3,1,0,51,"",0,4,"aa",75,0,-1,0,582,582,"2967","",0,"","","",1,0,0,[],""],["carrizo_salta-n2969-01",3,"¡Ahijuay puta Gualfincito!\n¡Qué lindo estarán cantando!\nEntre medio los cantores,\nSólo yo estaré faltando.",3,1,0,51,"",0,4,"ao",33,0,-1,0,582,582,"2969","",0,"","","",1,0,0,[],""],["carrizo_salta-n2970-01",3,"Bien me lo dijo mi madre,\nAprendé a cantar, criatura,\nPorque los cantores de aura,\nCantan con abreviatura.",3,1,0,51,"",0,4,"ua",17,0,-1,0,582,582,"2970","",0,"","","",1,0,0,[],""],["carrizo_salta-n2971-01",3,"¡Buenas noches Dn. Fulano!\nMe alegro de verlo bueno,\nCuando nombro a su persona,\nMe hallo de placeres lleno.",3,1,0,51,"",0,4,"eo",76,0,-1,0,582,582,"2971","",0,"","","",1,0,0,[],""],["carrizo_salta-n2972-01",3,"¡Caballero, caballero!\nLa albricia me ha de pagar,\nQue se ha muerto el rey de España\nY a usted van a coronar.",3,1,0,51,"",0,4,"a",21,0,-1,0,582,582,"2972","",0,"","","",1,0,0,[],""],["carrizo_salta-n2973-01",3,"¡Caballero de fulano!\nA la pisada de un gallo,\nSi se ha venido a cantar,\nBajesé de su caballo.",3,1,0,51,"",0,4,"ao",102,0,-1,0,582,582,"2973","",0,"","","",36,0,0,[],""],["carrizo_salta-n2973-a-01",3,"¡Cabalero de fulano!\nAl primer canto del gallo,\nSi quiere cantar conmigo,\nBajesé de su caballo.",3,1,0,51,"",0,4,"ao",102,0,-1,0,582,582,"2973-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n2974-01",3,"¡Caballero de fulano!\n¡Blanca espuma de la mar!\nEspejo de Buenos Aires,\nRetrato de Tucumán.",3,1,0,51,"",0,4,"a",-1,0,-1,0,582,582,"2974","",0,"","","",36,0,0,[],""],["carrizo_salta-n2975-01",3,"¡Caballero de fulano!\n¿Cómo quiere que le cante?\n¿Quiere por amor llanito?\n¿Quiere por amor tunante?",3,1,0,51,"",0,4,"ae",47,0,-1,0,582,582,"2975","",0,"","","",36,0,0,[],""],["carrizo_salta-n2976-01",3,"¡Caballero de fulano!\nFiel y constante amador,\nSu seguro servidor,\nSoy Manuel Corregidor.",3,1,0,51,"",0,4,"o",72,0,-1,0,583,583,"2976","",0,"","","",36,0,0,[],""],["carrizo_salta-n2977-01",3,"¡Caballero de fulano!\nFirmando sobre la mesa,\nAquí tiene dos amigos,\nHechos de pura firmeza.",3,1,0,51,"",0,4,"ea",108,0,-1,0,583,583,"2977","",0,"","","",36,0,0,[],""],["carrizo_salta-n2978-01",3,"¡Caballero de fulano!\nTire el banco y sientesé,\nSi no sabe concertar,\nLleguesé le enseñaré.",3,1,0,51,"",0,4,"e",77,0,-1,0,583,583,"2978","",0,"","","",36,0,0,[],""],["carrizo_salta-n2979-01",3,"¡Callate, loro pichón!\nApretado en la barranca,\nEchameló coplas lindas,\nNo me echís chanca, que chanca.",3,1,0,51,"",0,4,"aa",75,0,-1,0,583,583,"2979","",0,"","","",1,0,0,[],""],["carrizo_salta-n2980-01",3,"¡Callate rubio sin gracia!\nParecido al cientopiés,\n¿Quién me presta unas chancletas,\nPa aplastarlo en la pared?",3,1,0,51,"",0,4,"e",-1,0,-1,0,583,583,"2980","",0,"","","",1,0,0,[],""],["carrizo_salta-n2981-01",3,"Cantando así despacito,\nHaré corpus y San Juan,\nPor negra que sea la harina,\nHi de sacar blanco el pan.",3,1,0,51,"",0,4,"a",147,0,-1,0,583,583,"2981","",0,"","","",1,0,0,[],""],["carrizo_salta-n2982-01",3,"Cantando juntos,\nLo mos de pasar,\nA este mes y al otro\nY al año cabal.",3,1,0,51,"",3,4,"a",-1,0,-1,0,583,583,"2982","",0,"","","",1,0,0,[],""],["carrizo_salta-n2983-01",3,"Cantando la vidalita,\nMe van saliendo las canas,\nCantando los quince días,\nTodavía me sobran ganas.",3,1,0,51,"",0,4,"aa",263,0,-1,0,583,583,"2983","",0,"","","",1,0,0,[],""],["carrizo_salta-n2984-01",3,"Cantando me voy al cielo,\nCantando voy a la gloria,\nLas coplas me van brotando,\nDel fondo de la memoria.",3,1,0,51,"",0,4,"oa",126,0,-1,0,583,583,"2984","",0,"","","",1,0,0,[],""],["carrizo_salta-n2985-01",3,"¡Cantá nomás jilguerito!\nCantá nomás tu canción,\nDespedite de tus cantos,\nQue ya te llega el halcón.",3,1,0,51,"",0,4,"o",31,0,-1,0,583,583,"2985","",0,"","","",1,0,0,[],""],["carrizo_salta-n2986-01",3,"¡Cantá pajarillo alegre!\nQue alegre te conocí,\nAgora te miro triste,\n¿Será porque estoy aquí?",3,1,0,51,"",0,4,"i",23,0,-1,0,583,583,"2986","",0,"","","",1,0,0,[],""],["carrizo_salta-n2987-01",3,"¡Canten, canten compañeros!\nA mí no me tengan miedo,\nAunque soy mocito fiero,\nNo soy tigre pa comerlos.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,583,583,"2987","",0,"","","",6,0,0,[],""],["carrizo_salta-n2988-01",3,"¡Caramba con la memoria!\nQue no me puedo acordar,\nLas coplas junto conmigo,\nY no las puedo largar.",3,1,0,51,"",0,4,"a",21,0,-1,0,583,583,"2988","",0,"","","",2,0,0,[],""],["carrizo_salta-n2989-01",3,"Cierto mi vida, cierto,\nDame que dame,\nEl peine y el espejo,\nQuiero peinarme.",3,1,0,51,"",6,4,"ae",-1,0,-1,0,583,583,"2989","",0,"","","",5,0,0,[],""],["carrizo_salta-n2990-01",3,"Cierto, mi vida, cierto,\n\"Chinche bonete\",\nNo hay mujer que no tenga,\nSu adversa suerte.",3,1,0,51,"",6,4,"ee",-1,0,-1,0,584,584,"2990","",0,"","","",5,0,0,[],""],["carrizo_salta-n2991-01",3,"Cierto, mi vida, cierto,\nFormen cadena,\nPerdonen que los mande\nEn casa ajena.",3,1,0,51,"",6,4,"ea",59,0,-1,0,584,584,"2991","",0,"","","",5,0,0,[],""],["carrizo_salta-n2992-01",3,"Cierto, mi vida, cierto,\nMe hacís pensar,\nEn el río crecido,\nQue hay que pasar.",3,1,0,51,"",6,4,"a",21,0,-1,0,584,584,"2992","",0,"","","",5,0,0,[],""],["carrizo_salta-n2993-01",3,"Cierto, mi vida, cierto,\n¿Por qué se muere?\nAsí es como se pierde,\nLo que uno quiere.",3,1,0,51,"",6,4,"ee",-1,0,-1,0,584,584,"2993","",0,"","","",5,0,0,[],""],["carrizo_salta-n2994-01",3,"Como canta la calandria\nAsí canta el chalchalero,\nComo canta el campesino,\nPuede cantar el pueblero.",3,1,0,51,"",0,4,"eo",38,0,-1,0,584,584,"2994","",0,"","","",1,0,0,[],""],["carrizo_salta-n2995-01",3,"Como de debajo i tierra,\nSeñores hi aparecido,\nPara cantar en su rueda,\nDigo si me es permitido.",3,1,0,51,"",0,4,"io",101,0,-1,0,584,584,"2995","",0,"","","",1,0,0,[],""],["carrizo_salta-n2996-01",3,"¡Cómo no cantan señores\nY se alegran como yo!\n¿Por qué no se hacen la cuenta?\nHoy somos, mañana no.",3,1,0,51,"",0,4,"o",2,0,-1,0,584,584,"2996","",0,"","","",1,0,0,[],""],["carrizo_salta-n2997-01",3,"¿Cómo son estas razones,\nQue vienen las cuatro juntas?\n¡Ma ver, desate ese nudo,\nSin que aparezcan las puntas!",3,1,0,51,"",0,4,"ua",454,0,-1,0,584,584,"2997","",0,"","","",1,0,0,[],""],["carrizo_salta-n2998-01",3,"Con guitarra que otro toca,\nYo bailo si estoy contento,\nY si estoy triste, mi vida,\nMe prendo del instrumento.",3,1,0,51,"",0,4,"eo",94,0,-1,0,584,584,"2998","",0,"","","",1,0,0,[],""],["carrizo_salta-n2999-01",3,"Con la guitarra en las manos,\nYo no hi de quedar dijunto,\nSi me topo con el diablo,\nL'hi payar de contrapunto.",3,1,0,51,"",0,4,"uo",36,0,-1,0,584,584,"2999","",0,"","","",1,0,0,[],""],["carrizo_salta-n3000-01",3,"Con mi canto, a los que sufren,\nYo les doy mi sombra amiga,\nComo el árbol del desierto,\nAl gaucho sin techo, abriga.",3,1,0,51,"",0,4,"ia",232,0,-1,0,584,584,"3000","",0,"","","",1,0,0,[],""],["carrizo_salta-n3001-01",3,"Con sus permisos, señores,\nCantaré en su residencia,\nSin perjudicar a naides,\nNi quitarles conveniencia.",3,1,0,51,"",0,4,"ea",46,0,-1,0,584,584,"3001","",0,"","","",5,0,0,[],""],["carrizo_salta-n3002-01",3,"Contrapuntos me han pedido,\nAquí les voy a decir,\nCon estas mis triste coplas,\nCantando hi de ser feliz.",3,1,0,51,"",0,4,"i",-1,0,-1,0,584,584,"3002","",0,"","","",1,0,0,[],""],["carrizo_salta-n3003-01",3,"Corazón con alegría,\nAlma sin tribulación,\nCuando agarro mi cajita,\nSe entona mi corazón.",3,1,0,51,"",0,4,"o",31,0,-1,0,584,584,"3003","",0,"","","",1,0,0,[],""],["carrizo_salta-n3004-01",3,"Cuando amor canta, amor cantan,\nLas nubes con su donaire,\nY de amor cantan las aves,\nPayadores de los aires.",3,1,0,51,"",0,4,"ae",-1,0,-1,0,584,584,"3004","",0,"","","",2,0,0,[],""],["carrizo_salta-n3005-01",3,"Cuando amor canta, amor cantan,\nYuyos, árboles y flores,\nCon la voz de su fragancia,\nY el tono de sus colores.",3,1,0,51,"",0,4,"oe",5,0,-1,0,584,584,"3005","",0,"","","",2,0,0,[],""],["carrizo_salta-n3006-01",3,"Cuando me pongo a cantar,\nNo tengo cuando acabar,\nPrincipiando por San Juan,\nAcabo por Navidad.",3,1,0,51,"",0,4,"a",-1,0,-1,0,585,585,"3006","",0,"","","",5,0,0,[],""],["carrizo_salta-n3007-01",3,"Cuando me pongo a cantar,\nSe me hace el mundo totora,\nY el corazón se me parte,\nComo si fuera cantora.",3,1,0,51,"",0,4,"oa",107,0,-1,0,585,585,"3007","",0,"","","",5,0,0,[],""],["carrizo_salta-n3008-01",3,"Cuando me pongo a cantar,\nSuelo cantar con empeño,\nPorque yo no sé tener\nHambre, pereza ni sueño.",3,1,0,51,"",0,4,"eo",138,0,-1,0,585,585,"3008","",0,"","","",5,0,0,[],""],["carrizo_salta-n3009-01",3,"Cuando yo destré a cantar,\nLos ríos se rebalsaron,\nY las piedras se partieron,\nLos árboles se secaron.",3,1,0,51,"",0,4,"ao",41,0,-1,0,585,585,"3009","",0,"","","",1,0,0,[],""],["carrizo_salta-n3010-01",3,"¡Dame, negra, de tu pelo,\nCuerdas para mi vigüela,\nQue se me ha roto la prima,\nCuarta, segunda y tercera!",3,1,0,51,"",0,4,"ea",-1,0,-1,0,585,585,"3010","",0,"","","",1,0,0,[],""],["carrizo_salta-n3011-01",3,"¡Dame, negra, tu pelo,\nPara una cuerda,\nSe me ha roto la prima,\nDe mi vigüela!",3,1,0,51,"",6,4,"ea",-1,0,-1,0,585,585,"3011","",0,"","","",1,0,0,[],""],["carrizo_salta-n3012-01",3,"¿De ande ha salio ese cantor,\nQue canta de tan de lejos?\nTraigamelón para acá,\nPa ponerle un aparejo.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,585,585,"3012","",0,"","","",1,0,0,[],""],["carrizo_salta-n3013-01",3,"¿De ande sale este cantor,\nRevolcado en la ceniza?\nAgora me va a avisar,\nLo que contiene la misa.",3,1,0,51,"",0,4,"ia",68,0,-1,0,585,585,"3013","",0,"","","",1,0,0,[],""],["carrizo_salta-n3014-01",3,"Debe ser lindo el querer,\nYa que ninguno lo deja,\nYo no tengo más consuelo,\nQue esta guitarrita vieja.",3,1,0,51,"",0,4,"ea",165,0,-1,0,585,585,"3014","",0,"","","",1,0,0,[],""],["carrizo_salta-n3015-01",3,"De cantores como Ud.,\nMi padre tenía doscientos,\nLos sacaba para fuera,\nQue no se ca... adentro.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,585,585,"3015","",0,"","","",1,0,0,[],""],["carrizo_salta-n3016-01",3,"De día voy al trabajo,\nDe noche salgo a cantar,\nCantando como el coyuyo,\nAnunciando Carnaval.",3,1,0,51,"",0,4,"a",-1,0,-1,0,585,585,"3016","",0,"","","",1,0,0,[],""],["carrizo_salta-n3017-01",3,"Demasiado hemos cantado,\nUna pregunta haré yo:\n¿Por qué mi Dios soberano\nAl tiempo lo dividió?",3,1,0,51,"",0,4,"o",2,0,-1,0,585,585,"3017","",0,"","","",1,0,0,[],""],["carrizo_salta-n3018-01",3,"Demén lugar del camino,\nAllé iré a ver si puedo,\nVoy a cantar una letra,\nEscribiendo con el dedo.",3,1,0,51,"",0,4,"eo",304,0,-1,0,585,585,"3018","",0,"","","",1,0,0,[],""],["carrizo_salta-n3019-01",3,"De mi pago m'hi venío,\nEnsillando un pangaré,\nA divertirlos cantando,\nEse gustito tendré.",3,1,0,51,"",0,4,"e",77,0,-1,0,585,585,"3019","",0,"","","",2,0,0,[],""],["carrizo_salta-n3020-01",3,"Derecho ande el sol se pone,\nDueblan la punta los pastos,\nYa que la ocasión se ofrece,\nDe mis coplas haré gasto.",3,1,0,51,"",0,4,"ao",-1,0,-1,0,586,586,"3020","",0,"","","",1,0,0,[],""],["carrizo_salta-n3021-01",3,"Desde arriba m'hi venío,\nChicotiando y sujetando,\nMe gusta dictar las coplas,\nConcertando, concertando.",3,1,0,51,"",0,4,"ao",33,0,-1,0,586,586,"3021","",0,"","","",17,0,0,[],""],["carrizo_salta-n3022-01",3,"Desde el cielo hasta la tierra,\nHa de haber mucha distancia,\nNunca pude medir yo\nPorque es mucha mi ignorancia.",3,1,0,51,"",0,4,"aa",340,0,-1,0,586,586,"3022","",0,"","","",1,0,0,[],""],["carrizo_salta-n3023-01",3,"De todos estos cantores,\n¿Cuál será el que sobresale?\nQuiero hacerle una pregunta.\nPa que conteste a la tarde.",3,1,0,51,"",0,4,"ae",-1,0,-1,0,586,586,"3023","",0,"","","",1,0,0,[],""],["carrizo_salta-n3024-01",3,"Dios vino solo a este mundo,\nMás solo que el pensamiento,\nA enseñarnos a vivir,\nY darnos entendimiento.",3,1,0,51,"",0,4,"eo",94,0,-1,0,586,586,"3024","",0,"","","",1,0,0,[],""],["carrizo_salta-n3025-01",3,"Disculpará mi patrón,\nY aprete las cuatro sotas,\nMire que le va a cantar,\nUn militar de su escolta.",3,1,0,51,"",0,4,"oa",-1,0,-1,0,586,586,"3025","",0,"","","",2,0,0,[],""],["carrizo_salta-n3026-01",3,"El cantar por este estilo,\nEs muy bueno y es muy bueno,\nAsí se conciertan coplas,\nMedio al vuelo, medio al vuelto.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,586,586,"3026","",0,"","","",1,0,0,[],""],["carrizo_salta-n3028-01",3,"El sábado por la tarde,\nMe paso sin merendar,\nCon la cajita en la mano,\nBuscando dónde cantar.",3,1,0,51,"",0,4,"a",21,0,-1,0,586,586,"3028","",0,"","","",1,0,0,[],""],["carrizo_salta-n3029-01",3,"En la provincia de Salta,\nAllá en San José de Orquera,\nHa nacido un buen cantor,\nQue lo desafía a cualquiera.",3,1,0,51,"",0,4,"ea",44,0,-1,0,586,586,"3029","",0,"","","",1,0,0,[],""],["carrizo_salta-n3030-01",3,"En mis tiempos cuando mozo,\nCuando joven solía ser,\nTenía mi cajita buena,\nEn el medio un cascabel.",3,1,0,51,"",0,4,"e",-1,0,-1,0,586,586,"3030","",0,"","","",6,0,0,[],""],["carrizo_salta-n3031-01",3,"Esta cajita que toco,\nTiene boca para hablar,\nY como le falta voz,\nSe consuela con llorar.",3,1,0,51,"",0,4,"a",21,0,-1,0,586,586,"3031","",0,"","","",6,0,0,[],""],["carrizo_salta-n3032-01",3,"Esta cajita que toco,\nTiene voz encantadora,\nCuando no puedo cantar,\nTengo mi reemplazadora.",3,1,0,51,"",0,4,"oa",107,0,-1,0,587,587,"3032","",0,"","","",6,0,0,[],""],["carrizo_salta-n3033-01",3,"Esta noche vua cantar.\nHasta que retumbe el cerro,\nA ver si puedo igualar,\nAl valiente Martín Fierro.",3,1,0,51,"",1,4,"eo",379,0,-1,0,587,587,"3033","",0,"","","",1,0,0,[],""],["carrizo_salta-n3034-01",3,"Es una de esas preguntas,\nQue contestar no sabría,\nPero creo que algún día,\nLas pagaré todas juntas.",3,1,0,51,"",11,4,"ua",454,0,-1,0,587,587,"3034","",0,"","","",1,0,0,[],""],["carrizo_salta-n3035-01",3,"Formaré mi relación,\nLa cuchara y el martillo,\nLa plomada con la escuadra,\nLa piedra con el ladrillo.",3,1,0,51,"",0,4,"io",228,0,-1,0,587,587,"3035","",0,"","","",1,0,0,[],""],["carrizo_salta-n3036-01",3,"¡Hablá lengua, no te turbes!\nDelante de gente honrada,\nNi permitas que me saquen,\nLos colores a la cara.",3,1,0,51,"",0,4,"aa",-1,0,-1,0,587,587,"3036","",0,"","","",1,0,0,[],""],["carrizo_salta-n3037-01",3,"La guitarra que yo toco,\nSiente como una persona,\nUnas veces canta y ríe,\nY otras veces gime y llora.",3,1,0,51,"",3,4,"oa",-1,0,-1,0,587,587,"3037","",0,"","","",4,0,0,[],""],["carrizo_salta-n3038-01",3,"Lo que contiene la misa,\nRezarla con devoción,\nReza los cinco misterios,\nDe la sagrada Pasión.",3,1,0,51,"",0,4,"o",31,0,-1,0,587,587,"3038","",0,"","","",1,0,0,[],""],["carrizo_salta-n3039-01",3,"¡Madrecita del Rosario!\nDame ciencia, dame guía,\nPara poder explicarme,\nToda la noche y el día.",3,1,0,51,"",0,4,"ia",0,0,-1,0,587,587,"3039","",0,"","","",1,0,0,[],""],["carrizo_salta-n3040-01",3,"¡Madre mía del Rosario!\nDame los cinco sentidos,\nPara poderme explicar,\nDelante los entendidos.",3,1,0,51,"",0,4,"io",255,0,-1,0,587,587,"3040","",0,"","","",5,0,0,[],""],["carrizo_salta-n3041-01",3,"Mi guitarra siempre llora,\nLos lloros de mi canción,\nSi la toco arrimadita,\nBien juntita al corazón.",3,1,0,51,"",0,4,"o",31,0,-1,0,587,587,"3041","",0,"","","",1,0,0,[],""],["carrizo_salta-n3042-01",3,"No canto porque me escuchen,\nNi tampoco porque sé,\nCanto porque soy mandado,\nY es preciso obedecer.",3,1,0,51,"",0,4,"e",-1,0,-1,0,587,587,"3042","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["carrizo_salta-n3043-01",3,"No debe pedir licencia,\nTodo cantor de talento,\nY debe dentrar cantando,\nComo fraile en el convento.",3,1,0,51,"",0,4,"eo",94,0,-1,0,587,587,"3043","",0,"","","",1,0,0,[],""],["carrizo_salta-n3044-01",3,"No l'hi de aflojar, mi amigo,\nAunque sea el negro l'uña,\nAhora l'hi de ajustar,\nComo el herrero la cuña.",3,1,0,51,"",0,4,"ua",456,0,-1,0,587,587,"3044","",0,"","","",1,0,0,[],""],["carrizo_salta-n3045-01",3,"No me canten contrapunto,\nNo les voy a contestar,\nCantemos en amistad,\nPa' que nos pueda durar.",3,1,0,51,"",0,4,"a",-1,0,-1,0,587,587,"3045","",0,"","","",1,0,0,[],""],["carrizo_salta-n3046-01",3,"No soy cantor de guitarra,\nNo sé ningún instrumento,\nPero tomando la pluma,\nSé pronunciar mi concierto.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,588,588,"3046","",0,"","","",1,0,0,[],""],["carrizo_salta-n3047-01",3,"Pa contarles mi existencia,\nAtención tengan paciencia,\nPorque con mi relación,\nPueden templar su conciencia.",3,1,0,51,"",0,4,"ea",46,0,-1,0,588,588,"3047","",0,"","","",1,0,0,[],""],["carrizo_salta-n3048-01",3,"Para cantar contrapuntos,\nEs un asunto sencillo,\nYa me parece que tengo,\nEl dinero en el bolsillo.",3,1,0,51,"",0,4,"io",228,0,-1,0,588,588,"3048","",0,"","","",1,0,0,[],""],["carrizo_salta-n3049-01",3,"Para cantar en el mundo,\nSoy como paica de horcón,\nYo no conozco ventaja,\nCuando se para un cantor.",3,1,0,51,"",0,4,"o",-1,0,-1,0,588,588,"3049","",0,"","","",1,0,0,[],""],["carrizo_salta-n3050-01",3,"¡Ponga una vuelta, pulpero!\nQue yo se la hi de pagar,\nY pongamé un argumento,\nEstoy dispuesto a cantar.",3,1,0,51,"",0,4,"a",21,0,-1,0,588,588,"3050","",0,"","","",1,0,0,[],""],["carrizo_salta-n3051-01",3,"Porque saben cuatro coplas,\nQuieren al cielo subir,\nY quieren cantar conmigo,\nComo si han de resistir.",3,1,0,51,"",0,4,"i",157,0,-1,0,588,588,"3051","",0,"","","",1,0,0,[],""],["carrizo_salta-n3052-01",3,"¿Quién ha visto nacer pollos,\nEstando los huevos hueros?\nA esa pregunta que me hace,\nLe contestaré si puedo.",3,1,0,51,"",0,4,"eo",-1,0,-1,0,588,588,"3052","",0,"","","",1,0,0,[],""],["carrizo_salta-n3053-01",3,"Si me cantan por la ley,\nYo les canto por razón,\nSi me cantan contrapunto,\nYo les cantaré al botón.",3,1,0,51,"",0,4,"o",31,0,-1,0,588,588,"3053","",0,"","","",1,0,0,[],""],["carrizo_salta-n3054-01",3,"Toda tu sabiduría,\nLa has de mostrar esta vez,\nLa noche tiene su canto,\nY me has de decir cuál es.",3,1,0,51,"",0,4,"e",218,0,-1,0,588,588,"3054","",0,"","","",2,0,0,[],""],["carrizo_salta-n3055-01",3,"Una pregunta le haré,\nYa que se la echa de bueno,\nAhora me vas a decir:\n¿Cuántas leguas hay al cielo?",3,1,0,51,"",0,4,"eo",-1,0,-1,0,588,588,"3055","",0,"","","",1,0,0,[],""],["carrizo_salta-n3056-01",3,"¡Vení para acá, moreno!\nQue te quiero preguntar,\n¿Cuál es el hilo más largo,\nQue al cielo pueda llegar?",3,1,0,51,"",0,4,"a",21,0,-1,0,588,588,"3056","",0,"","","",1,0,0,[],""],["carrizo_salta-n3057-01",3,"Ya que esa pregunta me hace,\nLa respuesta le daré,\nLe preguntémos a Dios,\nSólo Dios podrá saber.",3,1,0,51,"",0,4,"e",-1,0,-1,0,588,588,"3057","",0,"","","",3,0,0,[],""],["carrizo_salta-n3058-01",3,"Ya que la pregunta me haces,\nLa respuesta te he de dar,\nEs el alma de un cristiano,\nCuando acaba de expirar.",3,1,0,51,"",0,4,"a",21,0,-1,0,588,588,"3058","",0,"","","",1,0,0,[],""],["carrizo_salta-n3059-01",3,"Yo lo vua sacar de dudas,\nPor qué lo hizo el Soberano,\nAl tiempo lo dividió,\nPa hacer invierno y verano.",3,1,0,51,"",0,4,"ao",81,0,-1,0,589,589,"3059","",0,"","","",1,0,0,[],""],["carrizo_salta-n3060-01",3,"Yo me llamo Picardía,\nSoy nacido en Chicochao,\nQuien quiera p a y a r conmigo,\nHa i ser diablo desatao.",3,1,0,51,"",0,4,"ao",98,0,-1,0,589,589,"3060","",0,"","","",1,0,0,[],""],["carrizo_salta-n3060-a-01",3,"Si vos sos de Chicochao,\nYo soy de Santa María,\nSi sos diablo desatao,\nA ver, decí: ¡Ave María!",3,1,0,51,"",1,4,"ia",-1,0,-1,0,589,589,"3060-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3061-01",3,"Yo no sé que me habrán dicho,\nPero contesto al tanteo,\nCuando la noche es oscura,\nEntonces más claro veo.",3,1,0,51,"",0,4,"eo",66,0,-1,0,589,589,"3061","",0,"","","",1,0,0,[],""]]);
